    /// Install the linear-scan register plan. Called once, after construction
    /// and before any emission, only when the path is enabled.
    fn set_residency(&mut self, residency: RegResidency) {
        self.reg_live = vec![false; residency.reg_of.len()];
        self.reg_of = residency.reg_of;
        self.poll_fp_reloads = residency.poll_fp_reloads;
        self.gp_reg_live = vec![false; residency.gp_reg_of.len()];
        self.gp_reg_owner = [None; 16];
        self.gp_reg_of = residency.gp_reg_of;
        // ── The split plan, installed before anything reads the file ─────
        //
        // Order matters twice below: the save-set snapshot has to see every
        // register a managed value passes through, and the droppability pass
        // has to see `ls_managed` so it can refuse exactly that population.
        self.ls_at = residency.splits.at;
        self.ls_block_start = residency.splits.block_start;
        self.ls_managed = residency.splits.managed;
        self.ls_edge_copies_done = vec![false; residency.splits.edges.len()];
        self.ls_edge_copies = residency.splits.edges;
        // Round 16 wave 3 (lane codegen, CG16-6): a loop phi's back-edge
        // source into the phi's own register, before anything below snapshots
        // or counts `gp_reg_of`.
        self.coalesce_back_edge_phi_sources();
        // Snapshot the definition-time registers NOW. `gp_reg_of`/`reg_of`
        // still hold what the plan assigned at each definition; from the first
        // `ls_apply_transitions` onward they hold what the value has moved to.
        self.ls_origin = (self.gp_reg_of.clone(), self.reg_of.clone());
        // The registers this frame owes its caller, frozen now. Both halves:
        // what the plan assigned for a whole range, and every register any
        // managed value visits. See the field comment for the failure a
        // prologue and an epilogue that disagree about this produce.
        //
        // Rebuilt rather than accumulated: this function's contract is "called
        // once", and a snapshot that ORed a second plan onto a first would keep
        // saving a register no plan hands out — harmless in this direction, but
        // it would make the snapshot stop being a function of the plan, which
        // is the property the tests below rest on.
        self.ls_saved_fp = [false; 16];
        self.ls_saved_gp = [false; 16];
        for reg in self.reg_of.iter().flatten() {
            if let Some(cell) = self.ls_saved_fp.get_mut(*reg as usize) {
                *cell = true;
            }
        }
        for reg in self.gp_reg_of.iter().flatten() {
            if let Some(cell) = self.ls_saved_gp.get_mut(*reg as usize) {
                *cell = true;
            }
        }
        for transitions in &self.ls_at {
            for t in transitions {
                let Some((reg, gp)) = t.destination() else {
                    continue;
                };
                let bank = if gp {
                    &mut self.ls_saved_gp
                } else {
                    &mut self.ls_saved_fp
                };
                if let Some(cell) = bank.get_mut(reg as usize) {
                    *cell = true;
                }
            }
        }
        // And every register an edge-resolution copy writes (round 9 wave 6):
        // it is a write this frame performs, so the caller's value in it has
        // to be saved and restored like any other.
        for edge in &self.ls_edge_copies {
            for &(_, reg, gp) in &edge.copies {
                let bank = if gp {
                    &mut self.ls_saved_gp
                } else {
                    &mut self.ls_saved_fp
                };
                if let Some(cell) = bank.get_mut(reg as usize) {
                    *cell = true;
                }
            }
        }
        // Exclusive ownership, computed once: how many values share each
        // register, and a value is nameable only if the answer for its own is
        // one. See the field comment for why "resident" is not enough.
        self.deopt_nameable = vec![false; self.gp_reg_of.len()];
        self.home_dropped = vec![false; self.gp_reg_of.len()];
        // Filled at the bottom of this function, once `deopt_nameable` is
        // known. **Up front, not lazily at the first edge copy**: `slot_of` has
        // to refuse from the first instruction emitted, or a read that happens
        // to precede the copy would silently take the unwritten word.
        if ir_deopt_regs_enabled() {
            let mut holders = [0usize; 16];
            for (id, reg) in self.gp_reg_of.iter().enumerate() {
                let Some(reg) = reg else {
                    continue;
                };
                // CG16-6: a coalesced back-edge source shares its phi's
                // register and is not a second holder (see
                // `coalesce_back_edge_phi_sources` for why naming either one
                // by that register is right wherever a frame can name it).
                if self.phi_coalesced_src.get(id).copied().unwrap_or(false) {
                    continue;
                }
                if let Some(cell) = holders.get_mut(*reg as usize) {
                    *cell += 1;
                }
            }
            // A register a managed value passes through holds DIFFERENT values
            // at different positions by construction, so no value is its
            // exclusive owner and none of them may be named in a frame state.
            // Poisoning the count rather than filtering the owner is deliberate:
            // it also takes the register away from the UNMANAGED value that
            // happens to hold it for its whole range, which is the one a naive
            // "skip managed ids" filter would wrongly still call exclusive.
            for id in 0..self.ls_managed.len() {
                if !self.ls_managed[id] {
                    continue;
                }
                for reg in self.ls_split_registers(id as NodeId, true) {
                    if let Some(cell) = holders.get_mut(reg as usize) {
                        *cell = usize::MAX;
                    }
                }
            }
            for id in 0..self.gp_reg_of.len() {
                let Some(reg) = self.gp_reg_of[id] else {
                    continue;
                };
                // `IR_LOWER_LS_GPRS` and nothing else: `DEOPT_ARG0` is spilled
                // holding the point pointer rather than its trapping value
                // (see `emit_deopt_stub`), and no register outside the file can
                // be reasoned about here at all.
                if !IR_LOWER_LS_GPRS.contains(&reg) {
                    continue;
                }
                if holders.get(reg as usize).copied().unwrap_or(0) == 1 {
                    self.deopt_nameable[id] = true;
                }
            }
        }
        // Which values a REACHABLE deopt can name. Computed before the
        // droppability pass below, which consults it.
        self.deopt_named_reachable = self.compute_deopt_named_reachable();
        // Two passes: the droppability predicates borrow `&self`.
        let droppable: Vec<usize> = (0..self.home_dropped.len())
            // A managed value's home is not optional. Its transitions RELOAD
            // from that word, and the reload is the whole mechanism — a dropped
            // home would make `ls_apply_transitions` read bytes nothing wrote,
            // which for an `IrType::Ref` is a fabricated object pointer handed
            // to the collector. The predicates below could answer `true` here
            // through either of their two widening clauses (a body that cannot
            // deopt, or a value no reachable deopt names), so the refusal is
            // stated as its own conjunct rather than left to them.
            .filter(|id| !self.ls_managed.get(*id).copied().unwrap_or(false))
            // Cast: an index into the node arena is a `NodeId`.
            .filter(|id| {
                let id = *id as NodeId;
                match self.graph.nodes.get(id as usize).map(|n| &n.op) {
                    Some(crate::ir::Op::Phi) => self.phi_home_droppable(id),
                    Some(_) => self.value_home_droppable(id),
                    None => false,
                }
            })
            .collect();
        for id in droppable {
            self.home_dropped[id] = true;
        }
    }

    /// Round 16 wave 3 (lane codegen, CG16-6;
    /// `r16-codegen-loop-and-straight-line-anatomy-FIXED-20261005.md`): give a loop
    /// phi's back-edge source the PHI's register, so `i = i + 1` is one
    /// `LEA r, [r + 1]` and the edge copy `MOV r_phi, r_src` (or, for a source
    /// the residency rules refused, its home store and reload) disappears.
    ///
    /// The single-range linear scan cannot do this itself: the phi's range is
    /// one interval over the linear layout, so a phi read after the loop (an
    /// accumulator returned at exit) occupies its register across the whole
    /// latch, and the scan hands the source another one. The argument here is
    /// the CFG's instead, and every clause is checked:
    ///
    /// * the source `v` is an `int`/`long` `Add`/`Sub` read exactly once -- by
    ///   this phi, on the edge from `v`'s own block `B`, which has no
    ///   terminator and ONE successor, the phi's header, and feeds exactly one
    ///   merge input. So from `v`'s definition every path runs the rest of `B`
    ///   and then the edge copy, which makes `v` the phi again;
    /// * no node of `B` after `v` reads the phi, and no other phi of the header
    ///   reads it on that edge: the phi is dead from `v`'s definition on, so
    ///   its register is free for `v` there. The arms that define an
    ///   `Add`/`Sub` read every operand before they write the result's
    ///   register (`LEA dst, [..]`, or the accumulator in RAX and then the
    ///   publish), so `v` may read the phi it replaces;
    /// * every node of `B` after `v` is `op_cannot_deopt`: no deopt frame can
    ///   name the phi while its register holds `v`. The back-edge poll's mode
    ///   exit names the header's phis by their edge sources
    ///   (`back_edge_mode_exit_state`), i.e. `v`, which IS in that register;
    /// * no other value assigned the register is live anywhere in `v`'s range
    ///   (`slot_plan.range`, the colourer's model the scan agreed with), and no
    ///   other phi holds it (a phi's register is also written by edge copies
    ///   outside its range);
    /// * no split residency, no edge-resolution copies, no MIR mode.
    ///
    /// The pair is then ONE holder of the register for `deopt_nameable`, which
    /// is what keeps both homes droppable where they were.
    fn coalesce_back_edge_phi_sources(&mut self) {
        let n = self.gp_reg_of.len();
        self.phi_coalesced_src = vec![false; n];
        self.phi_coalesced = 0;
        if !ir_phi_coalesce_back_edge_enabled()
            || self.mir_mode != MirMode::Off
            || self.ls_managed.iter().any(|&m| m)
            || !self.ls_edge_copies.is_empty()
        {
            return;
        }
        let graph: &'a Graph = self.graph;
        let mut use_count = vec![0u32; graph.nodes.len()];
        for node in &graph.nodes {
            for &input in &node.inputs {
                if input != NO_NODE {
                    if let Some(c) = use_count.get_mut(input as usize) {
                        *c = c.saturating_add(1);
                    }
                }
            }
        }
        for p in 0..graph.nodes.len().min(n) {
            let Some(pn) = graph.nodes.get(p) else {
                continue;
            };
            if pn.op != Op::Phi || !matches!(pn.ty, IrType::Int | IrType::Long) {
                continue;
            }
            let Some(reg) = self.gp_reg_of.get(p).copied().flatten() else {
                continue;
            };
            if !IR_LOWER_LS_GPRS.contains(&reg) {
                continue;
            }
            let Some(&merge_ctrl) = pn.inputs.first() else {
                continue;
            };
            let Some(merge) = graph.nodes.get(merge_ctrl as usize) else {
                continue;
            };
            if !matches!(merge.op, Op::Merge | Op::Region) {
                continue;
            }
            let Some(header) = self.block_of_ctrl(merge_ctrl) else {
                continue;
            };
            for k in 0..merge.inputs.len() {
                let Some(&v) = pn.inputs.get(k + 1) else {
                    continue;
                };
                let Some(&ctrl_in) = merge.inputs.get(k) else {
                    continue;
                };
                let Some(b) = self.block_of_ctrl(ctrl_in) else {
                    continue;
                };
                if v == NO_NODE
                    || !self.phi_source_coalesces(p, v as usize, b, header, reg, &use_count)
                {
                    continue;
                }
                if let Some(cell) = self.gp_reg_of.get_mut(v as usize) {
                    *cell = Some(reg);
                }
                if let Some(cell) = self.phi_coalesced_src.get_mut(v as usize) {
                    *cell = true;
                }
                self.phi_coalesced += 1;
            }
        }
        if self.phi_coalesced > 0
            && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
        {
            eprintln!(
                "[ir-ls] back-edge phi sources coalesced: {}",
                self.phi_coalesced
            );
        }
    }

    /// One candidate of [`Self::coalesce_back_edge_phi_sources`]: may phi `p`'s
    /// source `v`, arriving on the edge from block `b` to `header`, take the
    /// phi's register `reg`? Every clause that method's doc states, checked
    /// against the CURRENT `gp_reg_of` (earlier coalesced sources included).
    fn phi_source_coalesces(
        &self,
        p: usize,
        v: usize,
        b: usize,
        header: usize,
        reg: u8,
        use_count: &[u32],
    ) -> bool {
        let (Some(pn), Some(vn)) = (self.graph.nodes.get(p), self.graph.nodes.get(v)) else {
            return false;
        };
        if !matches!(vn.op, Op::Add | Op::Sub) || vn.ty != pn.ty {
            return false;
        }
        if use_count.get(v).copied() != Some(1)
            || self.phi_coalesced_src.get(v).copied().unwrap_or(true)
            || self.gp_reg_of.get(v).is_none()
        {
            return false;
        }
        if self.schedule.node_to_block.get(v).copied() != Some(b) {
            return false;
        }
        let Some(block) = self.schedule.blocks.get(b) else {
            return false;
        };
        if block.terminator.is_some() || block.successors.as_slice() != [header] {
            return false;
        }
        // Exactly one merge input from `b`: one copy, of `v`.
        let Some(&merge_ctrl) = pn.inputs.first() else {
            return false;
        };
        let Some(merge) = self.graph.nodes.get(merge_ctrl as usize) else {
            return false;
        };
        let from_b = merge
            .inputs
            .iter()
            .filter(|&&c| self.block_of_ctrl(c) == Some(b))
            .count();
        if from_b != 1 {
            return false;
        }
        // Cast: an index into the node arena is a `NodeId`.
        let phi = p as NodeId;
        // The rest of `b`: pure, and not reading the phi.
        let Some(at) = block.nodes.iter().position(|&x| x as usize == v) else {
            return false;
        };
        for &x in block.nodes.iter().skip(at + 1) {
            let Some(xn) = self.graph.nodes.get(x as usize) else {
                return false;
            };
            if !op_cannot_deopt(&xn.op) || xn.inputs.contains(&phi) {
                return false;
            }
        }
        // No other phi of the header reads this phi on any edge from `b`.
        if let Some(phis) = self.phis_by_merge.get(&merge_ctrl) {
            for &q in phis {
                if q == phi {
                    continue;
                }
                let Some(qn) = self.graph.nodes.get(q as usize) else {
                    return false;
                };
                for (k, &ctrl_in) in merge.inputs.iter().enumerate() {
                    if self.block_of_ctrl(ctrl_in) == Some(b) && qn.inputs.get(k + 1) == Some(&phi)
                    {
                        return false;
                    }
                }
            }
        }
        // No other holder of `reg` live in `v`'s range; no other phi holds it.
        let Some(vr) = self.slot_plan.range.get(v).copied().flatten() else {
            return false;
        };
        for (w, r) in self.gp_reg_of.iter().enumerate() {
            if *r != Some(reg) || w == p || w == v {
                continue;
            }
            match self.graph.nodes.get(w) {
                Some(wn) if wn.op != Op::Phi => {}
                _ => return false,
            }
            let Some(wr) = self.slot_plan.range.get(w).copied().flatten() else {
                return false;
            };
            if !(wr.hi < vr.lo || wr.lo > vr.hi) {
                return false;
            }
        }
        true
    }

    /// Every register in the `gp` bank that node `id`'s residency names, when
    /// `id` is managed: the one it starts in plus every transition destination.
    ///
    /// Read by `set_residency` for the exclusive-ownership poison above, and by
    /// the tests. A scan of the whole position table rather than a stored set:
    /// the table is the authority on where a managed value goes, and a second
    /// copy of that fact is a second thing to keep in step.
    ///
    /// **Banked, and it is not tidiness.** `holders` above is indexed by GP
    /// number; an XMM 3 leaking into it would poison RBX for a value that has
    /// nothing to do with the FP file. `PhysReg` carries its class for exactly
    /// this reason and a bare `u8` does not.
    fn ls_split_registers(&self, id: NodeId, gp: bool) -> Vec<u8> {
        let mut out: Vec<u8> = Vec::new();
        // The DEFINITION's register, not the current one -- see `ls_origin`.
        let bank = if gp {
            &self.ls_origin.0
        } else {
            &self.ls_origin.1
        };
        let start = bank.get(id as usize).copied().flatten();
        if let Some(reg) = start {
            out.push(reg);
        }
        for transitions in &self.ls_at {
            for t in transitions {
                if t.node() != id {
                    continue;
                }
                if let Some((reg, is_gp)) = t.destination() {
                    if is_gp == gp {
                        out.push(reg);
                    }
                }
            }
        }
        // An edge-resolution copy puts the value in a register too (round 9
        // wave 6).
        for edge in &self.ls_edge_copies {
            for &(node, reg, is_gp) in &edge.copies {
                if node == id && is_gp == gp {
                    out.push(reg);
                }
            }
        }
        out.sort_unstable();
        out.dedup();
        out
    }

    /// Why each PROMOTED value that kept its home kept it, per cause:
    /// `[switch, deopt, type,
    /// op]`, in the order [`Self::value_home_droppable`] tests them.
    ///
    /// # Why a per-cause census and not a count
    ///
    /// `plan_register_residency` used to print a `home: droppable=… ` line
    /// computed from a NAIVE rule — "some safepoint's locals or stack names
    /// it" — that predates `ir-deopt-regs`, `ir-reg-authoritative` and
    /// `ir-drop-phi-home`. By 2026-09-10 it read `droppable=0` on
    /// `probes/FieldLoop.java` `sum` while the emission on the SAME compile
    /// dropped three homes, and
    /// `internal/performance/c2-the-gp-register-file-is-not-the-binding-constraint-20260910.md`
    /// quoted the zero and built an argument on it. A diagnostic that is wrong
    /// in the direction of "nothing works" is worse than none: it retires
    /// levers that are in fact engaged.
    ///
    /// This one is computed from the predicates that actually decide, at the
    /// moment they decide, so it cannot drift from them — and the four causes
    /// call for four different next steps, which a bare count cannot say:
    ///
    ///   * `switch` — a flag in the conjunction is off. Nothing to chase.
    ///   * `deopt`  — a reachable frame state names it and the register is not
    ///     exclusively its own. **This is the one the architecture change is
    ///     for**: it wants a register bank the frame reconstructor can read at
    ///     an arbitrary bci, not another heuristic.
    ///   * `type`   — `Ref` (needs a register bank in the OOP MAP, a different
    ///     and larger change) or FP (a different file).
    ///   * `op`     — the defining arm does not write its home through one
    ///     `store_rax`, so there is no single store to drop.
    ///
    /// Deliberately counts only values the residency plan actually promoted: a
    /// value with no register has no home to drop and would swamp the census
    /// with a cause nobody can act on. Called at the END of lowering, after
    /// [`Self::extend_home_drops_to_carried_values`] has had its say, so
    /// "kept" means what the emission really did rather than what the plan
    /// intended.
    ///
    /// # The accounting identity, which is what stops this one drifting
    ///
    /// Every promoted value is either dropped or attributed to exactly one
    /// cause, and the assertion at the bottom says so. That is not decoration:
    /// the diagnostic it replaces went wrong precisely by computing its own
    /// answer instead of reading the one the emission used, and an identity
    /// that ties the census to `home_dropped` cannot do that. A future clause
    /// added to `value_home_droppable` and not here fails this immediately
    /// under `cargo test`, because `lower_inner_with_array_list` calls this on
    /// every debug lowering and not only when the diagnostic is on.
    fn census_home_blocks(&self) -> [usize; 4] {
        let (mut switch, mut deopt, mut ty, mut op) = (0usize, 0, 0, 0);
        let mut promoted = 0usize;
        let mut dropped = 0usize;
        for id in 0..self.home_dropped.len() {
            if self.gp_reg_of.get(id).copied().flatten().is_none() {
                continue;
            }
            promoted += 1;
            if self.home_dropped[id] {
                dropped += 1;
                continue;
            }
            // Cast: an index into the node arena is a `NodeId`.
            let nid = id as NodeId;
            // No node behind a promoted index is not a shape this can
            // attribute, and dropping it silently would break the identity
            // below. `op` is the honest bucket: whatever it is, its home store
            // is not one this pass can reason about.
            let Some(node) = self.graph.nodes.get(id) else {
                op += 1;
                continue;
            };
            // Round 9: `set_residency` refuses a dropped home to every
            // split-MANAGED value before either predicate is asked (its
            // transitions reload from that word), and this census had no bucket
            // for that refusal — a managed `Int`/`Long` with a one-store home
            // that ended the body in a register fell through every clause below
            // and tripped the identity under `CRATONVM_JIT_IR_LS_SPLITS=1`.
            // `op` is the bucket whose meaning fits: its home store is one this
            // pass may not reason about.
            if self.ls_managed.get(id).copied().unwrap_or(false) {
                op += 1;
                continue;
            }
            let is_phi = matches!(node.op, crate::ir::Op::Phi);
            let switches_on = if is_phi {
                ir_drop_phi_home_enabled()
                    && ir_deopt_regs_enabled()
                    && self.phi_copy_regs_on
                    && ir_skip_live_republish_enabled()
            } else {
                ir_drop_home_enabled()
                    && ir_publish_at_def_enabled()
                    && ir_deopt_regs_enabled()
                    && ir_skip_live_republish_enabled()
                    && self.phi_copy_regs_on
            };
            if !switches_on {
                switch += 1;
                continue;
            }
            // The frame-state obligation, in the same widening order the
            // predicates use: nameable in a register, or named by no deopt
            // that can happen (a phi's own publisher makes the trap-free arm
            // redundant for it, which is why the two spellings differ).
            let named_reachable = self.deopt_named_reachable.get(id).copied().unwrap_or(true);
            let nameable = self.deopt_nameable.get(id).copied().unwrap_or(false);
            let frame_ok = if is_phi {
                nameable || !named_reachable
            } else {
                nameable
                    || (self.graph_cannot_deopt() && self.assigned_gpr(nid).is_some())
                    || (!named_reachable && self.assigned_gpr(nid).is_some())
            };
            if !frame_ok {
                deopt += 1;
                continue;
            }
            if !matches!(node.ty, IrType::Int | IrType::Long) {
                ty += 1;
                continue;
            }
            // A phi has no defining arm to certify; reaching here means the
            // predicate said yes, so this is unreachable for one. Ordinary
            // values fall to the store-shape clause.
            if is_phi || !self.home_is_one_store_rax(node) {
                op += 1;
            }
        }
        debug_assert_eq!(
            dropped + switch + deopt + ty + op,
            promoted,
            "the home census lost a promoted value: {dropped} dropped, [{switch}, {deopt}, {ty}, {op}] kept, against {promoted} promoted. Every clause of `value_home_droppable` / `phi_home_droppable` needs a cause here, or this line reads low for a reason nobody can chase -- which is exactly how the census it replaced came to report zero on a compile that dropped three homes."
        );
        [switch, deopt, ty, op]
    }

    /// May this phi's home word go unwritten?
    ///
    /// **Every clause is load-bearing, and the point of writing them as one
    /// conjunction is that no combination of switches can satisfy some of them
    /// and not the rest.** In order:
    ///
    /// * the switch, and the register image the deopt path reads;
    /// * the edge copies publish the register (otherwise nothing puts the value
    ///   there at all, since the publish this replaces was a load OF the home);
    /// * a value already in its register is not re-published (otherwise the
    ///   generic publish site reloads the unwritten home once per iteration and
    ///   overwrites the register with whatever the frame word holds — the same
    ///   reload this whole line of work removed, now actively destructive);
    /// * the register is EXCLUSIVELY this value's, so a deopt frame can name it
    ///   at any bci (see `deopt_nameable`);
    /// * and it is an `Int` or a `Long`. A `Ref` is never in this file, and an
    ///   FP value's home is written by a different path.
    ///
    /// **And it HAS a register** (round 11 wave 12, lane fib). The widening
    /// below (no reachable deopt names it) answered `true` for a phi the
    /// residency plan gave no GPR at all -- spilled, split, or never allocated
    /// -- so `emit_copy_op` dropped its only store, published nothing (no
    /// register to publish into), and the dropped-home guard in
    /// `emit_phi_copies` refused the whole method at the first edge
    /// (`UnallocatedValue`: "home was dropped and its register is not live at
    /// a publish edge"). That was every recursively spliced `CratonBench.fib`
    /// body: a multi-return splice's result phi is live across the nested
    /// splice's calls, loses its register to pressure, and is named by no
    /// frame state a reachable deopt reads. `value_home_droppable` has always
    /// required `assigned_gpr` on the same widening; this is the phi arm
    /// catching up. The census counts promoted values only, so it is unmoved.
    fn phi_home_droppable(&self, phi: NodeId) -> bool {
        if !(ir_drop_phi_home_enabled()
            && ir_deopt_regs_enabled()
            && self.phi_copy_regs_on
            && ir_skip_live_republish_enabled())
        {
            return false;
        }
        // No register, no second location: the home word is all there is.
        if self.assigned_gpr(phi).is_none() {
            return false;
        }
        // Same widening as `value_home_droppable`: a phi named by no deopt that
        // can actually happen is not pinned by a frame state either. Its
        // register is published by the edge copies (`emit_copy_op`), which the
        // `ir_phi_copy_regs_enabled` clause above already requires.
        if !self
            .deopt_nameable
            .get(phi as usize)
            .copied()
            .unwrap_or(false)
            && self
                .deopt_named_reachable
                .get(phi as usize)
                .copied()
                .unwrap_or(true)
        {
            return false;
        }
        // The register is the ONLY location a dropped home leaves, so a phi
        // with none keeps its home -- the conjunct `value_home_droppable`'s
        // widening clauses carry (`assigned_gpr(id).is_some()`) and this one
        // lacked. Without it a phi no reachable deopt names, but that the
        // allocator left in memory, had no location at all, and
        // `emit_phi_copies` refused the compile at its first publish edge
        // (bounded self-recursive inlining's `itemCheck`, whose spliced
        // copies' result phis are exactly that).
        if self.assigned_gpr(phi).is_none() {
            return false;
        }
        matches!(
            self.graph.nodes.get(phi as usize).map(|n| n.ty),
            Some(IrType::Int) | Some(IrType::Long)
        )
    }

    /// Can NOTHING in this graph transfer to the interpreter?
    ///
    /// The PREDICTION half of [`ir_drop_unreachable_homes_enabled`]. Computed
    /// from the graph because the decision it feeds — which homes to drop — is
    /// made before a byte is emitted; `lower_inner` checks the answer against
    /// the emission afterwards.
    fn graph_cannot_deopt(&self) -> bool {
        if !ir_drop_unreachable_homes_enabled() {
            return false;
        }
        *self.graph_trap_free.get_or_init(|| {
            self.graph
                .nodes
                .iter()
                .all(|n| self.node_cannot_deopt_here(n))
        })
    }

    /// nio21 wave 7 (lane L5): does a pre-header mask guard prove this
    /// access (`ir_optimize::mask_guard_proves_access`, under
    /// `CRATONVM_JIT_IR_MASK_GUARD_ELIDE`)? The per-compile cached form: the
    /// graph does not change during lowering, so the proofs are computed once
    /// instead of a node scan, a users map and a loop forest per question.
    fn mask_guard_proven(&self, n: &Node) -> bool {
        self.mask_proofs
            .get_or_init(|| {
                crate::ir_optimize::mask_guard_elide_enabled()
                    .then(|| crate::ir_optimize::MaskGuardProofs::of(self.graph))
            })
            .as_ref()
            .is_some_and(|p| p.proves(self.graph, n))
    }

    /// [`node_cannot_deopt`] over this compile's cached mask proofs: the same
    /// clauses (`node_cannot_deopt_with`), the masked-load one answered by
    /// [`Self::mask_guard_proven`].
    fn node_cannot_deopt_here(&self, n: &Node) -> bool {
        node_cannot_deopt_with(self.graph, n, |m| {
            matches!(m.op, Op::ArrayLoad(_)) && self.mask_guard_proven(m)
        })
    }

    /// Is this value pinned to its home only by frame states nothing can
    /// reach?
    ///
    /// `deopt_named` says a frame state mentions it. That is a reason to keep
    /// the home word only if some deopt can consult that frame state.
    fn deopt_naming_is_reachable(&self, id: NodeId) -> bool {
        if !self.deopt_named.get(id as usize).copied().unwrap_or(true) {
            return false;
        }
        !self.graph_cannot_deopt()
    }

    /// Can a deopt that can actually happen name `id`?
    ///
    /// # Why this exists — the real limit on register residency
    ///
    /// A value's home store is dropped only when a deopt frame could describe
    /// it some other way, and the test for that was
    /// [`Self::deopt_nameable`]: the value must own its register
    /// **exclusively, for the whole method**. With a five-register file and a
    /// linear-scan allocator whose entire job is to give one register to
    /// several values with disjoint ranges, that is nearly never true — so
    /// nearly every promoted value kept its home store, and the register file
    /// stayed a write-through read CACHE rather than the authoritative
    /// location. That, not the allocator, is why this tier stores every SSA
    /// value to the frame.
    ///
    /// The only escape was `graph_cannot_deopt()` — whole-body trap freedom,
    /// which one `getfield` anywhere in the method destroys.
    ///
    /// This is the per-value form of the same question. A frame state can only
    /// ever be read at a bci something can actually trap at, so a value named
    /// exclusively by frame states at NON-trapping bcis is not pinned by any of
    /// them, whatever the rest of the method does.
    ///
    /// # Why it is safe without touching the GC
    ///
    /// Strictly a widening of the existing escape: `graph_cannot_deopt()`
    /// implies this for every value, so nothing that dropped a home before
    /// stops doing so. And the callers restrict it to `Int` and `Long` —
    /// `IrType::Ref` is refused by `value_home_droppable` and
    /// `phi_home_droppable` exactly as before, so no reference becomes
    /// register-resident and `OopMapEntry` needs no register bank. That
    /// remains the blocker for reference promotion and is untouched here.
    ///
    /// # Why a wrong prediction cannot produce a wrong answer
    ///
    /// This is a PREDICTION from the graph, made before emission, in the same
    /// shape and with the same net as `graph_cannot_deopt`: if a trap does
    /// occur at a bci predicted safe, `frame_value_for` meets a dropped home
    /// with no register describing it and REFUSES THE COMPILE. The method
    /// falls to the single-pass backend — a coverage loss, never a wrong
    /// frame.
    ///
    /// # The loop-header exception
    ///
    /// Every loop header is treated as trapping whether or not its ops can
    /// trap. An optimizing OSR entry seeds this tier's locals at a loop header
    /// from the interpreter's frame, and it seeds HOME WORDS; a value whose
    /// home was dropped there would be seeded into a word nothing reads. The
    /// door was implicated in one miscompile for exactly this reason
    /// (`ir-osr-entry-miscompiles-a-spliced-merge-FIXED-20260909.md`: the stub
    /// jumped past the block that writes a constant's home word). That one is
    /// fixed, by MAKING the stub write the words it skipped rather than by
    /// refusing anything — so this clause stands on its own argument, not on
    /// that page: a dropped home is a word the seeding cannot write at all,
    /// which is a different problem from a word it merely forgot to.
    fn compute_deopt_named_reachable(&self) -> Vec<bool> {
        let n = self.graph.nodes.len();
        let mut out = vec![false; n];
        let widened = ir_register_authoritative_enabled();
        // bcis a deopt can arrive at: every node whose op is outside the
        // cannot-trap allowlist, plus every loop header.
        // Round 9: BOTH the raw pc and its `resume_bci`. A trap inside a
        // spliced callee body resumes at the enclosing `invoke`
        // (`emit_deopt_unless` and the `Op::Guard` arm resolve their frame
        // state at `self.resume_bci(bci)`), so the caller snapshot AT that
        // invoke is the one such a trap reads. Keyed by the raw combined-buffer
        // pc alone, the invoke's bci was missing from this set whenever the
        // spliced call node itself was gone, its values' homes were dropped,
        // and the inlined null/bounds check then latched `UnallocatedValue`
        // and refused the whole method. Adding a bci only KEEPS more homes, so
        // this can widen what is kept and never what is dropped.
        let mut trapping: std::collections::HashSet<usize> = if widened {
            let mut set = std::collections::HashSet::new();
            for pc in self
                .graph
                .nodes
                .iter()
                // Round 9 wave 3: `node_cannot_deopt`, the graph-aware form
                // `graph_cannot_deopt` already uses -- a division by a non-zero
                // constant emits no deopt point, so its bci is not a trap.
                .filter(|node| !self.node_cannot_deopt_here(node))
                // Round 11 wave 13 (lane fib): a direct self-call outside every
                // protected range transfers nothing -- see
                // `self_call_reads_no_frame_state`. Its exits are recorded to
                // match (`push_self_call_exc_patch`), so `build_deopt_points`'
                // latch still checks this prediction against the emission.
                .filter(|node| !self.self_call_reads_no_frame_state(node))
                .filter_map(|node| node.bytecode_pc)
            {
                set.insert(pc);
                set.insert(self.resume_bci(pc));
            }
            set
        } else {
            std::collections::HashSet::new()
        };
        if widened {
            for (b, block) in self.schedule.blocks.iter().enumerate() {
                if block.successors.iter().any(|&s| s <= b) {
                    for &succ in &block.successors {
                        if succ <= b {
                            if let Some(header) = self.schedule.blocks.get(succ) {
                                if let Some(pc) = self
                                    .graph
                                    .nodes
                                    .get(header.ctrl as usize)
                                    .and_then(|node| node.bytecode_pc)
                                {
                                    trapping.insert(pc);
                                }
                            }
                        }
                    }
                }
            }
        }
        for sp in &self.graph.safepoints {
            // Unwidened: every naming counts, which is the pre-2026-09-09
            // behaviour and leaves `graph_cannot_deopt` as the only escape.
            if widened && !trapping.contains(&sp.bci) {
                continue;
            }
            for &v in sp
                .locals
                .iter()
                .chain(sp.stack.iter())
                .chain(sp.monitors.iter())
            {
                if v != NO_NODE {
                    if let Some(cell) = out.get_mut(v as usize) {
                        *cell = true;
                    }
                }
            }
        }
        for v in loop_carried_recipe_values(self.sr_map) {
            if let Some(cell) = out.get_mut(v as usize) {
                *cell = true;
            }
        }
        // JIT round 19 wave 5 (lane osr5, OSR2-3): a promoted loop's deopt
        // pads read these (`promoted_pending_pin_values`; wave 7, lane osr7,
        // OSR6-1 / OSR5-3: `promoted_pending_deopt_named`).
        for v in promoted_pending_deopt_named(self.graph, self.schedule) {
            if let Some(cell) = out.get_mut(v as usize) {
                *cell = true;
            }
        }
        out
    }

    /// May this ORDINARY value's home word go unwritten?
    ///
    /// The same conjunction as [`Self::phi_home_droppable`] with the phi's
    /// publisher swapped for this one's. A phi is published by `emit_copy_op`
    /// at every incoming edge; every other value is published by `store_rax`
    /// at its single home write, which is what `ir_publish_at_def_enabled`
    /// arranges and what `op_home_is_one_store_rax` certifies exists.
    ///
    /// `ir_skip_live_republish_enabled` is required for the same reason it is
    /// there: without it the generic publish at the end of `lower_data_node`
    /// would reload the home word nothing wrote, over the top of the register
    /// this value's definition had just published correctly.
    fn value_home_droppable(&self, id: NodeId) -> bool {
        if !(ir_drop_home_enabled()
            && ir_publish_at_def_enabled()
            && ir_deopt_regs_enabled()
            && ir_skip_live_republish_enabled()
            // `gather_phi_copies` is the ONE reader that is exempt from
            // `slot_of`'s refusal: it takes the would-be offset from
            // `slot_of_unwritten` to identify a copy destination. `emit_copy_op`
            // then reads the SOURCE out of its register -- but only under this
            // switch. With it off, a dropped-home value used as a phi source
            // would be loaded from the word nothing wrote, which is the one
            // silent miscompile this area can produce.
            && self.phi_copy_regs_on)
        {
            return false;
        }
        // `deopt_nameable` asks "can a deopt frame NAME this in a register".
        // A body nothing can deopt from never asks, so an assigned register is
        // enough — the readers need it, the frame states do not exist to be
        // wrong. Verified against the emission in `lower_inner`.
        // Three ways to satisfy the frame-state obligation, in widening order:
        //
        //   1. a deopt can NAME this value in its register (exclusive owner);
        //   2. the whole body cannot deopt, so no frame state is ever read;
        //   3. no deopt that can actually happen names THIS value.
        //
        // (3) subsumes (2) and is the one that makes the register file
        // authoritative on ordinary methods — see
        // `compute_deopt_named_reachable` for why one `getfield` used to be
        // enough to force every promoted value in the method back to memory.
        if !self
            .deopt_nameable
            .get(id as usize)
            .copied()
            .unwrap_or(false)
            && !(self.graph_cannot_deopt() && self.assigned_gpr(id).is_some())
            && !(!self
                .deopt_named_reachable
                .get(id as usize)
                .copied()
                .unwrap_or(true)
                && self.assigned_gpr(id).is_some())
        {
            return false;
        }
        let Some(node) = self.graph.nodes.get(id as usize) else {
            return false;
        };
        // `Ref` is named by frame slots in the oop map and FP lives in the
        // other file -- the same two exclusions the phi predicate makes.
        if !matches!(node.ty, IrType::Int | IrType::Long) {
            return false;
        }
        self.home_is_one_store_rax(node)
    }

    /// [`op_home_is_one_store_rax`], plus the one route-specific shape the op
    /// alone cannot certify: the result of a DIRECT self-recursive call.
    ///
    /// Round 11 wave 13 (lane fib). `Op::Call` has several routes and most do
    /// not end in one `store_rax`, so the op is not on the allowlist. The
    /// `invoke_kind == 4` route always does: the `Op::Call` arm sends it to
    /// [`Self::emit_self_recursive_call`] before anything else can claim it
    /// (both call prefixes decline kind 4), which writes the result once, at
    /// `.keep`, through `store_rax(slot)` -- `publish_def_at_store` publishes
    /// the register there -- and then returns past the generic publish. Every
    /// other path out of that route leaves through the call-exception stub
    /// and reads no home. Shared with [`Self::census_home_blocks`] so the two
    /// cannot disagree about which values have a single home write.
    fn home_is_one_store_rax(&self, node: &Node) -> bool {
        op_home_is_one_store_rax(&node.op)
            || (Self::is_direct_self_call(node) && ir_self_call_states_unread_enabled())
    }

    /// Is `node` an `Op::Call` bound to the direct self-recursive route
    /// (`JitInvokeInfo::invoke_kind == 4`)? The same read the `Op::Call` arm
    /// makes to choose [`Self::emit_self_recursive_call`].
    fn is_direct_self_call(node: &Node) -> bool {
        let Op::Call { info_ptr } = node.op else {
            return false;
        };
        if info_ptr == 0 {
            return false;
        }
        // SAFETY: as the `Op::Call` arm's own `invoke_kind` read -- a non-zero
        // `info_ptr` names a live `JitInvokeInfo` owned by `ir_call_infos` for
        // the whole compile.
        unsafe { (*(info_ptr as *const JitInvokeInfo)).invoke_kind == 4 }
    }

    /// Can a frame state at this node's bci be READ because of this node?
    /// `true` means no: `node` is a direct self-call whose exits publish
    /// nothing.
    ///
    /// Round 11 wave 13 (lane fib; calls proposal 2, "parameters kept in
    /// registers", generalised). Every value a self-recursive body keeps live
    /// across its own recursion -- `fib`'s `n`, the pending `fib(n-1)`, both
    /// arguments -- is named by the snapshots at the recursive invokes, and a
    /// call is not on `op_cannot_deopt`'s allowlist, so every one of them kept
    /// a home store it never needed. What the kind-4 route actually emits:
    ///
    /// * the sampled stack-guard trip and the `dispatch_threw` exit both go to
    ///   the call-exception stub, which stamps the bci and returns the
    ///   sentinel -- it publishes no frame (`propagating_exit_holds_monitor`'s
    ///   doc: "a call-exception exit that publishes NOTHING");
    /// * the callee-deopt service rebuilds the CALLEE's frame from the
    ///   callee's own stash and staged arguments (read through
    ///   `gp_load_value`, i.e. from registers when that is where they are);
    /// * no guard, no null check (`invokestatic`), no deopt stub.
    ///
    /// The one transfer that does read this frame at a call is the reason-9
    /// rethrow pad, emitted only inside a protected range
    /// ([`Self::push_rethrow_pad`]), so a protected call keeps its bci
    /// trapping. A handler outside the precise-frame route resumes on the
    /// incoming arguments (`run_jit_callee_handler`'s params-only tier), not
    /// on a by-bci point, and the by-bci consumers of `deopt_points` ask about
    /// bci and reason only.
    ///
    /// Soundness does not rest on this list being complete:
    /// [`Self::push_self_call_exc_patch`] leaves the bci out of
    /// `transfer_bcis` under exactly this predicate, so if any other site at
    /// the same bci can transfer, it records the bci itself and
    /// `build_deopt_points` refuses the compile on the first dropped home it
    /// names (`UnallocatedValue`) -- a lost compile, never a wrong frame.
    /// [`ir_self_call_states_unread_enabled`] is the switch.
    fn self_call_reads_no_frame_state(&self, node: &Node) -> bool {
        if !Self::is_direct_self_call(node) || !ir_self_call_states_unread_enabled() {
            return false;
        }
        match node.bytecode_pc {
            Some(pc) => !self.bci_is_protected(self.resume_bci(pc)),
            None => false,
        }
    }

    /// [`Self::push_call_exc_patch`] for the direct self-recursive route: the
    /// same row and the same monitor fact, but the bci is recorded as a
    /// transfer site only when a reason-9 pad makes it one. See
    /// [`Self::self_call_reads_no_frame_state`], which is the prediction this
    /// must match.
    fn push_self_call_exc_patch(&mut self, patch: usize) {
        let bci = self.resume_bci(self.cur_bci);
        if !ir_self_call_states_unread_enabled() || self.bci_is_protected(bci) {
            self.push_call_exc_patch(patch);
            return;
        }
        if !self.propagating_exit_holds_monitor && self.site_snapshot_may_hold_monitor(bci) {
            self.propagating_exit_holds_monitor = true;
        }
        self.call_exc_patches.push((patch, bci));
    }

    /// Describe `id` as living in its register, if that is provably where it
    /// is at every bci a frame state could name it.
    ///
    /// `None` for everything else, and the caller then falls through to the
    /// home word exactly as before — this is additive, and with
    /// `CRATONVM_JIT_IR_DEOPT_REGS` off it answers `None` for every value.
    fn register_frame_value(&self, id: NodeId, ty: IrType) -> Option<FrameValue> {
        if !self
            .deopt_nameable
            .get(id as usize)
            .copied()
            .unwrap_or(false)
        {
            return None;
        }
        let reg = self.gp_reg_of.get(id as usize).copied().flatten()?;
        // Round 16 wave 11 (lane frames2): a register the sized image does not
        // reserve is never named. Unreachable by construction (the image holds
        // every register the plan hands out, `size_deopt_image`); if it ever
        // fires, the caller falls through to the home word, and a dropped home
        // refuses the compile there -- fail closed, never a read of a word the
        // stub did not write.
        if !self.deopt_image_holds_gpr(reg) {
            return None;
        }
        match ty {
            // A cat-1 `int`: `Register` resolves it truncated to 32 bits.
            IrType::Int => Some(FrameValue::Register(reg)),
            // A cat-2 `long` keeps all 64.
            IrType::Long => Some(FrameValue::RegisterLong(reg)),
            // `Ref` is never in this file (the oop map names frame slots only),
            // and FP lives in the other one. Both fall through to the home.
            _ => None,
        }
    }

    /// Does this frame's deopt register image reserve `gpr[reg]` -- is the
    /// word the stub stores `reg` to inside the frame, and stored by it?
    fn deopt_image_holds_gpr(&self, reg: u8) -> bool {
        self.deopt_regs_base > 0 && i32::from(reg) < (self.deopt_regs_bytes / 8).min(16)
    }

    /// The image's XMM half as the published `[lo, hi)` range, or `None` when
    /// the frame does not reserve it (no image at all, or a sized one, which
    /// never does: this tier names no XMM register in a frame state).
    fn deopt_xmm_image(&self) -> Option<(i32, i32)> {
        if self.deopt_regs_bytes < DEOPT_IMAGE_FULL_BYTES {
            return None;
        }
        deopt_xmm_image_range(self.deopt_regs_base)
    }

    /// The image's GPR half as the published `[lo, hi)` range (`deopt_gpr_lo`
    /// / `deopt_gpr_hi`), or `(0, 0)` with no image. `gpr[0]` is the deepest
    /// word, at `deopt_regs_base`, so `hi == deopt_regs_base + 8` whatever the
    /// size -- the convention `conservative_roots` (`deopt_image_rbp_slot`,
    /// `ir_tail_word`) derives `gpr[0]` and the RBP image `gpr[5]` from.
    fn deopt_gpr_image(&self) -> (i32, i32) {
        if self.deopt_regs_base == 0 {
            return (0, 0);
        }
        let words = (self.deopt_regs_bytes / 8).clamp(1, 16);
        (
            self.deopt_regs_base - (words - 1) * 8,
            self.deopt_regs_base + 8,
        )
    }

    /// Round 16 wave 11 (lane frames2, FR16P-1 / backlog FR-B2;
    /// `CRATONVM_JIT_IR_DEOPT_IMAGE_SIZED`, default OFF): shrink the 256-byte
    /// deopt register image to the words a deopt exit of this body can name.
    ///
    /// Called once, after the residency plan is installed (`set_residency`)
    /// and before anything is emitted, because the plan is what decides which
    /// registers a frame state can name and the prologue is what carves the
    /// frame. This tier names only general-purpose registers, and only ones a
    /// value is assigned to (`register_frame_value`: an exclusively owned
    /// `gp_reg_of`; the mode-exit polls: a resident `gp_reg_of`), all of which
    /// `ls_saved_gp` (the frame's whole-method register set) records. So the
    /// image keeps `gpr[0..=k]`, `k` the highest such register and at least 5
    /// (the RBP image the collector's residue test reads, `gpr[5]`), and drops
    /// the XMM half; with no register in the plan it keeps nothing.
    ///
    /// Only the image changes size: it is the deepest region below the save
    /// bands and above the argument staging, so the cut (a multiple of 16)
    /// comes off `frame_size` and the staging/shadow offsets, while
    /// `spill_cap_off`, every spill, save and bookkeeping offset stay where
    /// `Lowerer::new` put them. The image still abuts the staging region.
    fn size_deopt_image(&mut self, on: bool) {
        if !on || self.deopt_regs_base <= 0 || self.deopt_regs_bytes <= 0 {
            return;
        }
        let want = sized_deopt_image_bytes(&self.ls_saved_gp);
        if want >= self.deopt_regs_bytes {
            return;
        }
        let cut = self.deopt_regs_bytes - want;
        debug_assert_eq!(cut % 16, 0, "the cut must keep the frame 16-aligned");
        if cut % 16 != 0 {
            return;
        }
        self.frame_size -= cut;
        self.args_stage_top_off -= cut;
        // Round 16 wave 17 (lane frames2): the planned staging clears move
        // with the staging region.
        self.rebase_planned_stage_clears(cut);
        self.deopt_regs_bytes = want;
        self.deopt_regs_base = if want > 0 {
            self.spill_cap_off + self.saved_xmm_bytes + self.saved_gpr_bytes + want
        } else {
            0
        };
        // Cast: the widest call's argument count, far below i32::MAX.
        let stage = self.args_stage_words as i32 * 8;
        debug_assert!(
            want == 0 || self.deopt_regs_base == self.args_stage_top_off - stage,
            "the sized deopt image must still abut the argument staging region"
        );
        debug_assert!(
            (0u8..16)
                .filter(|r| self.ls_saved_gp[*r as usize])
                .all(|r| self.deopt_image_holds_gpr(r)),
            "the sized image must hold every register the plan hands out"
        );
    }

    /// Round 16 wave 17 (lane frames2, PC-1 of
    /// `jit-r16-polyclear-proposals-RETIRED-20261005.md`;
    /// `CRATONVM_JIT_IR_SAVE_BANDS_SIZED`, default OFF): size the callee-saved
    /// XMM and GPR save bands to the registers this body saves, and take the
    /// rest out of the frame. Returns the bytes cut (0 when nothing changed).
    ///
    /// `Lowerer::new` reserves one slot per register of each file (XMM6/XMM7
    /// on Win64, none on SysV; five or seven GPRs), but a body saves only what
    /// its residency plan hands out (`ls_saved_fp` / `ls_saved_gp`, the
    /// snapshot `saved_xmm_regs` / `saved_gpr_regs` already filter on). An
    /// unused slot is never written by this activation, so the band scan roots
    /// whatever the previous occupant of the stack left there, and the
    /// fresh-frame clear zeroes it on every call. `R16Bench poly`'s `area()`
    /// saves one GPR of five; `fib` two.
    ///
    /// Called once, after `set_residency` (the plan decides what is saved)
    /// and before `size_deopt_image` and the prologue. The bands sit between
    /// the spill cap and the deopt image, so the cut comes off everything
    /// deeper: `frame_size`, the image base and the staging top move by it;
    /// `spill_cap_off` (`callee_saved_lo`), every spill, local and bookkeeping
    /// offset stay. The used slots are packed from the shallow end
    /// (`save_bands_packed`), so every reader of a save slot -- the prologue,
    /// every epilogue, the OSR entry stubs, the fresh-frame clear's
    /// `_SKIP_WRITTEN` and the published `ir_saved_gpr_slots` -- reads the
    /// packed offset through the same two iterators. The XMM band shrinks by
    /// 16 per unused register; the GPR band by the unused bytes rounded DOWN
    /// to 16, so the frame keeps its alignment (a slot that rounding keeps is
    /// cleared as before).
    ///
    /// The collector loses nothing it scanned: the removed words are no
    /// longer in the frame (`osr_frame_size` is `frame_size`), the clear sizes
    /// itself from `frame_size`, and the published layout derives the image
    /// and staging geometry from `callee_saved_lo`, `deopt_gpr_*` and
    /// `frame_size` (`ir_tail_word`), never from the file sizes.
    fn size_save_bands(&mut self, on: bool) -> i32 {
        if !on || self.save_bands_packed {
            return 0;
        }
        let xmm_used = if self.saved_xmm_bytes > 0 {
            IR_LOWER_SAVED_XMMS
                .iter()
                .filter(|&&r| self.ls_saved_fp.get(r as usize).copied().unwrap_or(true))
                .count()
        } else {
            0
        };
        let gpr_used = if self.saved_gpr_bytes > 0 {
            ir_gp_file()
                .iter()
                .filter(|&&r| self.ls_saved_gp.get(r as usize).copied().unwrap_or(true))
                .count()
        } else {
            0
        };
        // Casts: at most seven registers per file.
        let xmm_cut = (self.saved_xmm_bytes - xmm_used as i32 * 16).max(0);
        let gpr_cut = (self.saved_gpr_bytes - gpr_used as i32 * 8).max(0) & !15;
        let cut = xmm_cut + gpr_cut;
        if cut <= 0 || cut % 16 != 0 {
            return 0;
        }
        let before = (self.frame_size, self.saved_xmm_bytes, self.saved_gpr_bytes);
        self.saved_xmm_bytes -= xmm_cut;
        self.saved_gpr_bytes -= gpr_cut;
        self.save_bands_packed = true;
        self.frame_size -= cut;
        self.args_stage_top_off -= cut;
        if self.deopt_regs_base > 0 {
            self.deopt_regs_base -= cut;
        }
        self.rebase_planned_stage_clears(cut);
        debug_assert!(
            self.deopt_regs_base == 0
                || self.deopt_regs_base
                    == self.spill_cap_off
                        + self.saved_xmm_bytes
                        + self.saved_gpr_bytes
                        + self.deopt_regs_bytes,
            "the deopt image must still begin where the save bands end"
        );
        // Cast: the widest call's argument count, far below i32::MAX.
        let stage = self.args_stage_words as i32 * 8;
        debug_assert!(
            self.deopt_regs_base == 0 || self.deopt_regs_base == self.args_stage_top_off - stage,
            "the deopt image must still abut the argument staging region"
        );
        debug_assert!(
            self.saved_xmm_regs()
                .chain(self.saved_gpr_regs())
                .all(|(_, off)| off > self.spill_cap_off
                    && off <= self.spill_cap_off + self.saved_xmm_bytes + self.saved_gpr_bytes),
            "every save slot must lie inside the sized bands"
        );
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-save-bands sized: xmm {} -> {} gpr {} -> {} bytes (frame {} -> {} bytes)",
                before.1,
                self.saved_xmm_bytes,
                before.2,
                self.saved_gpr_bytes,
                before.0,
                self.frame_size
            );
        }
        cut
    }

    /// Round 16 wave 17 (lane frames2; kill switch
    /// `CRATONVM_JIT_IR_STAGE_CLEAR_REBASE=0`): move the argument-staging
    /// words [`Self::plan_dead_home_clears`] recorded by `cut` bytes, after a
    /// layout step moved the staging region that much shallower.
    ///
    /// The plan runs before the residency plan, so it records offsets against
    /// `Lowerer::new`'s layout. Its two kinds of word are told apart by the
    /// spill cap, which no layout step moves: a reference home is at or above
    /// it (`home_off`), a staging word strictly below (`stage_off`). Only the
    /// second kind moves, and every layout step cuts bytes between the cap and
    /// the staging region, so each staging word moves by exactly `cut` and
    /// stays strictly below the cap.
    fn rebase_planned_stage_clears(&mut self, cut: i32) {
        if cut == 0 || self.dead_home_clears.is_empty() || !ir_stage_clear_rebase_enabled() {
            return;
        }
        let cap = self.spill_cap_off;
        for offs in self.dead_home_clears.values_mut() {
            for off in offs.iter_mut() {
                if *off > cap {
                    *off -= cut;
                    debug_assert!(
                        *off > cap,
                        "a rebased staging word stays below the spill cap"
                    );
                }
            }
        }
    }

    /// Can no exit of this body ever read the deopt register image? Round 16
    /// wave 12 (lane polyclear, FR2P-1). A prediction made before the first
    /// byte is emitted, after the residency plan (`set_residency`), from the
    /// same tables the home-drop decisions already trust:
    ///
    /// * **loop-free** (no cycle in the block graph): no back-edge poll, so no
    ///   poll mode exit (`back_edge_mode_exit_state`, the only poll exit that
    ///   names a resident register; the method-entry poll never has one), no
    ///   loop-header state and no OSR entry stub with its re-check exit;
    /// * **no `Op::Call` and no OSR node**: no post-call exit site
    ///   (`post_call_exit_state`, which names resident registers) and no
    ///   frame state of a Java call's exception exit;
    /// * **no spliced callee body**: every frame state is the method's own, so
    ///   `compute_deopt_named_reachable` (which reads `graph.safepoints`) sees
    ///   every snapshot a deopt point is built from;
    /// * **every `Int`/`Long` value a deopt could name by its register
    ///   (`deopt_nameable`) AND a snapshot a deopt can reach names
    ///   (`deopt_named_reachable`) kept its home word** (`home_dropped` is
    ///   false). Without an image `register_frame_value`, the one remaining
    ///   producer of a `FrameValue::Register*`, answers `None`, and
    ///   `frame_value_for` describes such a value by its home word -- the
    ///   description every value that does NOT own its register exclusively
    ///   (most of them) already gets at every reachable deopt: a kept home is
    ///   written at the value's definition (`publish_at_def` / `store_rax`;
    ///   the carries skip it only for a value no reachable snapshot names, and
    ///   then mark the home dropped), before any snapshot naming it. A value
    ///   whose home was dropped BECAUSE it was nameable has no other location,
    ///   so it keeps the image. (`Ref` and FP values are never named by
    ///   register on this tier.)
    /// * **and no such value is a monitor object** (a live monitor operand, or
    ///   named in a snapshot's `monitors`). Round 16 wave 13 (lane polyclear):
    ///   `monitor_object_value` re-spells a monitor's word as
    ///   `StackSlotRef`, so the same frame word described by its home in the
    ///   locals or the stack (`StackSlot`, `int`) is a `SlotTypeConflict` --
    ///   and an `int` slot the active map names -- to the deopt-metadata
    ///   verifier, which refuses the compile. With the image the local is
    ///   `Register(r)`, which names no frame word. Witness: the hand-built
    ///   `aload_0; monitorenter; aload_0; monitorexit` bodies (their `this`
    ///   is an `int`-typed `Op::Param`), which stopped lowering when the
    ///   switch went default ON (w13a).
    ///
    /// Why a wrong answer cannot produce a wrong frame: every reader of the
    /// image fails closed without one. `register_frame_value` answers `None`
    /// (`deopt_image_holds_gpr`), so `frame_value_for` falls to the home word,
    /// and a dropped home there latches `UnallocatedValue` and refuses the
    /// compile; the poll and post-call exits refuse themselves
    /// (`names_a_register && deopt_regs_base <= 0`); the stub stores nothing
    /// and hands `ir_deopt_entry` NULL. A misprediction costs a compile or an
    /// exit, never a value.
    fn deopt_image_never_read(&self) -> bool {
        if schedule_block_cfg_has_cycle(self.schedule) || !self.spliced_ranges.is_empty() {
            return false;
        }
        if self.graph.nodes.iter().any(|n| {
            matches!(
                n.op,
                Op::Call { .. }
                    | Op::OsrEntryFlag { .. }
                    | Op::OsrLocal(_)
                    | Op::OsrMemory
                    | Op::CatchEntryFlag { .. }
                    | Op::CaughtException
            )
        }) {
            return false;
        }
        (0..self.deopt_nameable.len()).all(|id| {
            let nameable = self.deopt_nameable[id];
            let reachable = self.deopt_named_reachable.get(id).copied().unwrap_or(true);
            let primitive = matches!(
                self.graph.nodes.get(id).map(|n| n.ty),
                Some(IrType::Int) | Some(IrType::Long)
            );
            if !(nameable && reachable && primitive) {
                return true;
            }
            let dropped = self.home_dropped.get(id).copied().unwrap_or(true);
            let Ok(nid) = NodeId::try_from(id) else {
                return false;
            };
            let monitor = self.live_monitor_operands.contains(&nid)
                || self
                    .graph
                    .safepoints
                    .iter()
                    .any(|sp| sp.monitors.contains(&nid));
            !dropped && !monitor
        })
    }

    /// Round 16 wave 12 (lane polyclear, FR2P-1;
    /// `CRATONVM_JIT_IR_DEOPT_IMAGE_EXITLESS`, default OFF): reserve no deopt
    /// register image in a body [`Self::deopt_image_never_read`] says no exit
    /// can read. Called right after [`Self::size_deopt_image`] and before the
    /// prologue, on whatever that left (the full image or a sized one).
    ///
    /// The layout is the one `size_deopt_image` already produces for an empty
    /// residency plan: the image is the deepest region above the argument
    /// staging, so its whole size (a multiple of 16) comes off `frame_size`
    /// and `args_stage_top_off`, `deopt_regs_base` becomes 0 (the stub's and
    /// the publication's "no image"), and every shallower offset stays. The
    /// published layout then names no image (`deopt_gpr_image` answers
    /// `(0, 0)`, `deopt_xmm_image` `None`).
    ///
    /// The collector loses nothing it scanned: the removed words are no
    /// longer in the frame's band (`[rbp - frame_size, rbp)`), and every word
    /// still in it is cleared exactly as before by the fresh-frame clear,
    /// which sizes itself from `frame_size`. Returns whether it dropped one.
    /// Round 17 (CG16P-4 of `jit-r16-codegen-proposals-DONE-20261005.md`;
    /// [`ir_const_home_drop_enabled`]): drop the home word of every `int` /
    /// `long` constant that holds no register, so `Op::Const` emits nothing.
    ///
    /// Every reader of such a constant already folds it -- `gp_load_value`
    /// and the ALU arms take an immediate, a frame state describes it as one
    /// (`frame_value_for`), an OSR entry need not seed it, and an edge copy
    /// takes it as `MOV r, imm` (`emit_copy_op`) -- so the stores feed nothing
    /// on the common path (`bigA` wrote ~100 per call). A reader that still
    /// wants the word goes through `slot_of`, which refuses a dropped home and
    /// fails THIS attempt; `lower_inner_with_mode_exit_polls` then lowers once
    /// more with every home kept (the deopt-image fallback's retry), so a
    /// misprediction costs a second lowering, never a wrong answer.
    ///
    /// Needs the register-read phi copies and the constant immediates (the
    /// two readers that take the immediate instead of the word). Returns
    /// whether anything was dropped.
    fn drop_const_homes(&mut self, on: bool) -> bool {
        if !on || !self.phi_copy_regs_on || !self.const_imm_on || self.mir_mode != MirMode::Off {
            return false;
        }
        let mut dropped = 0usize;
        for id in 0..self.home_dropped.len() {
            let Some(node) = self.graph.nodes.get(id) else {
                continue;
            };
            if !matches!(node.op, Op::Const(_)) || !matches!(node.ty, IrType::Int | IrType::Long) {
                continue;
            }
            if self.gp_reg_of.get(id).copied().flatten().is_some()
                || self.ls_managed.get(id).copied().unwrap_or(false)
                || self.home_dropped[id]
            {
                continue;
            }
            self.home_dropped[id] = true;
            dropped += 1;
        }
        self.const_homes_dropped = dropped;
        dropped > 0
    }

    /// Is `id` an `int` / `long` constant whose home [`Self::drop_const_homes`]
    /// dropped?
    fn is_dropped_const(&self, id: NodeId) -> bool {
        self.home_dropped.get(id as usize).copied().unwrap_or(false)
            && self.gp_reg_of.get(id as usize).copied().flatten().is_none()
            && self.graph.nodes.get(id as usize).is_some_and(|n| {
                matches!(n.op, Op::Const(_)) && matches!(n.ty, IrType::Int | IrType::Long)
            })
    }

    fn drop_unread_deopt_image(&mut self, on: bool) -> bool {
        if !on || self.deopt_regs_base <= 0 || self.deopt_regs_bytes <= 0 {
            return false;
        }
        let cut = self.deopt_regs_bytes;
        if cut % 16 != 0 || !self.deopt_image_never_read() {
            return false;
        }
        let before = self.frame_size;
        self.frame_size -= cut;
        self.args_stage_top_off -= cut;
        // Round 16 wave 17 (lane frames2): a no-op today (an exitless body has
        // no `Op::Call`, so no planned staging clear), kept so the rule "every
        // layout cut moves the planned staging clears" has no exception.
        self.rebase_planned_stage_clears(cut);
        self.deopt_regs_bytes = 0;
        self.deopt_regs_base = 0;
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-deopt-image dropped: no exit can read it (frame {before} -> {} bytes)",
                self.frame_size
            );
        }
        true
    }

    /// Install the level-2 machine list. Called once, after construction and
    /// before any emission, only when a machine-level flag is on.
    fn set_mir(&mut self, plan: MirPlan, mode: MirMode) {
        self.mir = Some(plan);
        self.mir_mode = mode;
        if mode != MirMode::Off {
            self.home_reload_forward_on = false;
        }
    }

    /// The XMM register `id`'s value is CURRENTLY resident in, if any.
    ///
    /// Gated on `reg_live`, not on `reg_of`: a value is only readable from a
    /// register once its definition site has published it there. See the field
    /// comment for why that direction is the safe one.
    #[track_caller]
    fn resident_xmm(&self, id: NodeId) -> Option<u8> {
        // Wave 64 (lane L2): the token-read guard; a no-op while it is off.
        self.token_read_check(id);
        if !self.reg_live.get(id as usize).copied().unwrap_or(false) {
            return None;
        }
        self.reg_of.get(id as usize).copied().flatten()
    }

    /// MOVAPS `dst`, `src` — a full 128-bit register copy.
    ///
    /// `MOVAPS` rather than `MOVSS`/`MOVSD` so the copy has no false
    /// dependency on `dst`'s previous contents and one encoding serves both
    /// widths: the low 32 or 64 bits are what every consumer reads, and a bit
    /// copy preserves them exactly (NaN payloads included — this must never be
    /// an arithmetic move).
    fn fp_reg_move(&mut self, dst: u8, src: u8) {
        if dst == src {
            return;
        }
        // REX.R for dst >= 8, REX.B for src >= 8. `IR_LOWER_LS_XMMS` is
        // XMM2–XMM7 and the value tier is XMM0/XMM1, so no REX is emitted
        // today; encoding it anyway keeps the helper correct if the file grows.
        // `MOVAPS` has no mandatory SSE prefix, so REX is the first byte here —
        // see the prefix-order note above `fp_load`.
        let rex = 0x40u8 | (((dst >= 8) as u8) << 2) | ((src >= 8) as u8);
        if rex != 0x40 {
            self.buf.emit_byte(rex);
        }
        self.buf
            .emit(&[0x0F, 0x28, 0xC0 | ((dst & 7) << 3) | (src & 7)]);
    }

    /// `Math.sqrt(D)` and FP `Math.min`/`max` (JIT round 19, lane irops19,
    /// R15B-31), into XMM0 and out through `fp_store_value`. Uses only the
    /// value tier's XMM0/XMM1: XMM2-XMM7 belong to the register cache.
    ///
    /// `MINSD`/`MAXSD` alone are NOT `Math.min`/`max`: they return the SECOND
    /// operand when either is NaN or both are zero. The JDK body returns the
    /// NaN ARGUMENT (`a` first), and orders -0.0 strictly below +0.0. So:
    ///
    /// ```text
    ///   UCOMIS a, b ; JP unordered ; JNE ordered
    ///   equal:     min: a OR b  / max: a AND b  -- +-0.0 sign rule; identical
    ///              bits otherwise, so the identity for every other equal pair
    ///   ordered:   MINS/MAXS a, b                -- exact for unequal operands
    ///   unordered: UCOMIS a, a ; JP done (a is NaN: keep it) ; a = b
    /// ```
    ///
    /// The same answers, bit for bit, as the single-pass
    /// `MATH_MIN_FLOAT_INTRINSIC` arm (`x64/op_invoke.rs`), which needs two
    /// more XMM registers this tier does not have.
    fn lower_fp_math_scalar(
        &mut self,
        id: NodeId,
        slot: i32,
        sop: ScalarOp,
        a: NodeId,
        b: Option<NodeId>,
    ) {
        if matches!(sop, ScalarOp::SqrtD) {
            self.fp_load_value(XMM0, a, true);
            self.buf.emit(&[0xF2, 0x0F, 0x51, 0xC0]); // SQRTSD XMM0, XMM0
            self.fp_store_value(id, slot, XMM0, true);
            return;
        }
        // JIT round 19 wave 2 (lane irops2, IROPS19-2): `Math.floor`/`ceil`/
        // `rint` -- SSE4.1 `ROUNDSD XMM0, XMM0, imm8` with the single-pass
        // arm's immediates (bit 3 suppresses the precision exception, which
        // MXCSR masks anyway). The recognizer admitted the row only with
        // SSE4.1 present (`try_ir_scalar_intrinsic`).
        if let Some(imm8) = match sop {
            ScalarOp::FloorD => Some(0x09u8), // toward -inf
            ScalarOp::CeilD => Some(0x0Au8),  // toward +inf
            ScalarOp::RintD => Some(0x08u8),  // nearest, ties to even
            _ => None,
        } {
            self.fp_load_value(XMM0, a, true);
            self.buf.emit(&[0x66, 0x0F, 0x3A, 0x0B, 0xC0, imm8]); // ROUNDSD XMM0, XMM0, imm8
            self.fp_store_value(id, slot, XMM0, true);
            return;
        }
        let (dbl, is_min) = match sop {
            ScalarOp::MinF => (false, true),
            ScalarOp::MaxF => (false, false),
            ScalarOp::MinD => (true, true),
            ScalarOp::MaxD => (true, false),
            _ => {
                self.latch_bailout(Bailout::new(BailoutReason::Internal(
                    "ir_lower: lower_fp_math_scalar given a non-FP-math family",
                )));
                return;
            }
        };
        let Some(b) = b else {
            self.latch_bailout(Bailout::new(BailoutReason::Internal(
                "ir_lower: an FP min/max node with one input",
            )));
            return;
        };
        // JIT round 19 wave 4 (lane irops3, IROPS19-5), opt-in: both operands
        // register-resident and the host has AVX -- the branch-free form
        // (`fp_minmax_avx_bytes`), which reads them in place.
        if ir_fp_minmax_avx_enabled() {
            if let (Some(ra), Some(rb)) = (self.resident_xmm(a), self.resident_xmm(b)) {
                if ![ra, rb].iter().any(|r| *r == XMM0 || *r == XMM1) {
                    let bytes = fp_minmax_avx_bytes(dbl, is_min, ra, rb);
                    self.buf.emit(&bytes);
                    self.fp_store_value(id, slot, XMM0, dbl);
                    return;
                }
            }
        }
        self.fp_load_value(XMM0, a, dbl);
        self.fp_load_value(XMM1, b, dbl);
        // 66-prefixed (PD / SD-compare) forms for double, bare (PS / SS) for float.
        let pd = |dbl: bool, op: &[u8]| -> Vec<u8> {
            let mut v = Vec::with_capacity(op.len() + 1);
            if dbl {
                v.push(0x66);
            }
            v.extend_from_slice(op);
            v
        };
        let ucomis_ab = pd(dbl, &[0x0F, 0x2E, 0xC1]); // UCOMIS XMM0, XMM1
        self.buf.emit(&ucomis_ab);
        let to_unordered = self.emit_jcc_rel32(0x8A); // JP
        let to_ordered = self.emit_jcc_rel32(0x85); // JNE
                                                    // Equal (both zeros included): OR keeps a -0.0 sign from either side
                                                    // (min), AND keeps it only when both are -0.0 (max).
        let bitop = if is_min { 0x56 } else { 0x54 }; // ORP / ANDP
        let eq_op = pd(dbl, &[0x0F, bitop, 0xC1]);
        self.buf.emit(&eq_op);
        let done_eq = self.emit_jmp_rel32();
        // Ordered and unequal: the SSE instruction is exactly Java's answer.
        self.patch_rel32_to_here(to_ordered);
        let prefix = if dbl { 0xF2 } else { 0xF3 };
        let minmax = if is_min { 0x5D } else { 0x5F };
        self.buf.emit(&[prefix, 0x0F, minmax, 0xC1]); // MIN/MAX S{S,D} XMM0, XMM1
        let done_ord = self.emit_jmp_rel32();
        // Unordered: return the NaN argument itself, `a` first.
        self.patch_rel32_to_here(to_unordered);
        let ucomis_aa = pd(dbl, &[0x0F, 0x2E, 0xC0]); // UCOMIS XMM0, XMM0
        self.buf.emit(&ucomis_aa);
        let a_is_nan = self.emit_jcc_rel32(0x8A); // JP: keep a
        self.buf.emit(&[0x0F, 0x28, 0xC1]); // MOVAPS XMM0, XMM1 (b, exact bits)
        self.patch_rel32_to_here(a_is_nan);
        self.patch_rel32_to_here(done_eq);
        self.patch_rel32_to_here(done_ord);
        self.fp_store_value(id, slot, XMM0, dbl);
    }

    /// `Math.fma(a, b, c)` (JIT round 19 wave 2, lane irops2, IROPS19-2):
    /// FMA3 `VFMADD213S{D,S} XMM0, XMM1, src` = `XMM1 * XMM0 + src` =
    /// `b * a + c`, rounded once -- the single-pass inline arm's instruction
    /// (`x64/op_invoke.rs`, `MATH_FMA_*_INTRINSIC`).
    ///
    /// The single-pass arm stages `c` in XMM2; this tier may not write XMM2
    /// (XMM2-XMM7 are the register cache), so the third operand is READ in
    /// place instead: `c`'s resident register when it has one, else its home
    /// word as the `m64`/`m32` operand (`fp_load_value`'s two sources, with
    /// no copy). Nothing but XMM0/XMM1 is written. The recognizer admitted
    /// the row only where the inline FMA3 form is enabled.
    fn lower_fp_fma_scalar(&mut self, id: NodeId, slot: i32, sop: ScalarOp, inputs: &[NodeId]) {
        let &[a, b, c] = inputs else {
            self.latch_bailout(Bailout::new(BailoutReason::Internal(
                "ir_lower: an FMA node without three inputs",
            )));
            return;
        };
        let dbl = match sop {
            ScalarOp::FmaD => true,
            ScalarOp::FmaF => false,
            _ => {
                self.latch_bailout(Bailout::new(BailoutReason::Internal(
                    "ir_lower: lower_fp_fma_scalar given a non-FMA family",
                )));
                return;
            }
        };
        self.fp_load_value(XMM0, a, dbl);
        self.fp_load_value(XMM1, b, dbl);
        // VEX3: C4 | R X B mmmmm=00010 (0F38) | W vvvv=~XMM1 L=0 pp=01 (66).
        // W=1 is the SD form, W=0 the SS form.
        let wvvvv = if dbl { 0xF1u8 } else { 0x71u8 };
        match self.resident_xmm(c) {
            Some(r) => {
                // B̄ is clear (bit 5) to reach XMM8-XMM15 through r/m.
                let rxb = if r >= 8 { 0xC2u8 } else { 0xE2u8 };
                self.buf.emit(&[0xC4, rxb, wvvvv, 0xA9, 0xC0 | (r & 7)]);
            }
            None => {
                let off = self.slot_of(c);
                self.buf.emit(&[0xC4, 0xE2, wvvvv, 0xA9]);
                self.emit_rbp_modrm_disp(XMM0, off);
            }
        }
        self.fp_store_value(id, slot, XMM0, dbl);
    }

    /// Load `id`'s value into `xmm`, from its resident register when it has
    /// one and from its home word otherwise.
    ///
    /// The read half of the cache. Every FP operand read in `lower_data_node`
    /// goes through here; a site left calling `fp_load(self.slot_of(id))`
    /// directly is simply not accelerated.
    // JIT round 19 wave 2 (lane irops2): this doc and `#[track_caller]` were
    // stranded above `lower_fp_math_scalar` by the wave-1 insertion.
    #[track_caller]
    fn fp_load_value(&mut self, xmm: u8, id: NodeId, is_double: bool) {
        // Bound out of the scrutinee position: every read of `self` here must
        // finish before the emitters take `&mut self`.
        let resident = self.resident_xmm(id);
        match resident {
            Some(src) => self.fp_reg_move(xmm, src),
            None => {
                let off = self.slot_of(id);
                self.fp_load(xmm, off, is_double);
            }
        }
    }

    /// The register `id`'s value has been ASSIGNED, whether or not its
    /// definition has published it yet. Only the two publishing sites may use
    /// this; every reader goes through [`Self::resident_xmm`].
    fn assigned_xmm(&self, id: NodeId) -> Option<u8> {
        self.reg_of.get(id as usize).copied().flatten()
    }

    /// Mark `id` readable from its assigned register.
    fn mark_reg_live(&mut self, id: NodeId) {
        if let Some(cell) = self.reg_live.get_mut(id as usize) {
            *cell = true;
        }
    }

    /// Write `id`'s result from `xmm`: ALWAYS to the home word, and
    /// additionally into its resident register.
    ///
    /// The write-through invariant lives here. The home store is emitted
    /// unconditionally and first, so the frame image is complete at every
    /// instruction boundary — which is what lets `emit_safepoint_map`,
    /// `build_deopt_points` and `emit_phi_copies` stay untouched.
    fn fp_store_value(&mut self, id: NodeId, slot: i32, xmm: u8, is_double: bool) {
        self.fp_store(slot, xmm, is_double);
        let dst = self.assigned_xmm(id);
        if let Some(dst) = dst {
            self.fp_reg_move(dst, xmm);
            self.ls_spills += 1;
            self.mark_reg_live(id);
        }
    }

    /// Publish a result that was computed in RAX and already stored to its home
    /// word (`Op::ConstF`, FP `Op::Neg`, FP `Op::Param`) into its register.
    ///
    /// A memory → register transition, and counted as one: the value's only
    /// materialisation is the home word this reads back. It is still a win in
    /// a loop, where the alternative is that load once per use.
    fn publish_fp_from_slot(&mut self, id: NodeId, slot: i32, is_double: bool) {
        let dst = self.assigned_xmm(id);
        if let Some(dst) = dst {
            self.fp_load(dst, slot, is_double);
            self.ls_reloads += 1;
            self.mark_reg_live(id);
        }
    }

    // ── The general-purpose half of the same cache ──────────────────────
    //
    // Identical contract to the FP accessors above, over `IR_LOWER_LS_GPRS`
    // rather than `IR_LOWER_LS_XMMS`: write-through, gated on `gp_reg_live` so
    // a value is readable from a register only once its definition published it
    // there, and `None` everywhere means the read falls back to the home word.
    //
    // This is the half that reaches an `int` loop counter — the gap the FP-only
    // wiring's own doc comment named, and the reason this backend's bodies
    // measured slower than the single-pass bodies they supersede.

    /// The GP register `id`'s value is CURRENTLY resident in, if any.
    #[track_caller]
    fn resident_gpr(&self, id: NodeId) -> Option<u8> {
        // Wave 64 (lane L2): the token-read guard; a no-op while it is off.
        self.token_read_check(id);
        if !self.gp_reg_live.get(id as usize).copied().unwrap_or(false) {
            return None;
        }
        self.gp_reg_of.get(id as usize).copied().flatten()
    }

    /// The register `id`'s value has been ASSIGNED, whether or not its
    /// definition has published it yet. Only publishing sites may use this;
    /// every reader goes through [`Self::resident_gpr`].
    fn assigned_gpr(&self, id: NodeId) -> Option<u8> {
        self.gp_reg_of.get(id as usize).copied().flatten()
    }

    /// Mark `id` readable from its assigned GP register — and mark whoever held
    /// that register before UNREADABLE.
    ///
    /// The second half is the whole of the interlock. Setting the per-node bit
    /// says "id's value is in its register"; without dropping the previous
    /// owner's bit, `resident_gpr` goes on answering that register for a node
    /// whose value this very instruction has just overwritten. See
    /// [`Self::gp_reg_owner`] for the edge that makes two nodes share one
    /// register while both are still being read, and for what it produced.
    ///
    /// A node re-published into its own register is not a transfer and clears
    /// nothing; that is the ordinary definition-site case and the common path.
    fn mark_gp_reg_live(&mut self, id: NodeId) {
        if let Some(reg) = self.assigned_gpr(id) {
            if let Some(slot) = self.gp_reg_owner.get_mut(reg as usize) {
                let previous = slot.replace(id);
                if let Some(previous) = previous {
                    if previous != id {
                        if let Some(cell) = self.gp_reg_live.get_mut(previous as usize) {
                            *cell = false;
                        }
                    }
                }
            }
        }
        if let Some(cell) = self.gp_reg_live.get_mut(id as usize) {
            *cell = true;
        }
    }

    /// Drop every cached REFERENCE copy, because a collector may have run.
    ///
    /// The register file here is a write-through read cache over a frame slot.
    /// For an `int` that cache never goes stale — nothing but this body writes
    /// the slot. For a reference it does: a moving collector rewrites the slot
    /// under a frame it did not stop, and it cannot rewrite a copy in a
    /// register no oop map names. Reading that copy afterwards dereferences the
    /// object's OLD address, which is the failure class
    /// `fix/netty-close-ordering-20260905` was.
    ///
    /// So every point at which control can leave this body and come back drops
    /// the copies, and the next read reloads the word the collector updated.
    /// `except` is the node the site itself just defined — an `Op::Call`'s
    /// result is produced AFTER the collection, so it is fresh, and dropping it
    /// would take back the one promotion a call site can offer.
    ///
    /// Cheap enough to be unconditional in shape: the loop runs over the nodes
    /// that actually hold a register (`gp_reg_owner` is five wide), not over
    /// the graph.
    fn invalidate_ref_residency(&mut self, except: Option<NodeId>) {
        if !self.ref_residency_on {
            return;
        }
        for slot in 0..self.gp_reg_owner.len() {
            let Some(owner) = self.gp_reg_owner[slot] else {
                continue;
            };
            if Some(owner) == except {
                continue;
            }
            if self.graph.nodes.get(owner as usize).map(|n| n.ty) != Some(IrType::Ref) {
                continue;
            }
            if let Some(cell) = self.gp_reg_live.get_mut(owner as usize) {
                if *cell {
                    *cell = false;
                    REF_RESIDENCY_DROPPED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
        }
    }

    // ── Split residency: applying one position's transitions ─────────

    /// Point `id`'s FP assignment at `reg`, or at no register at all.
    ///
    /// The ONE site that makes `reg_of` change after installation. Everything
    /// that reads `reg_of` as a whole-method property reads `ls_saved_fp`
    /// instead (see `saved_xmm_regs`), and everything that reads it per node
    /// goes through `resident_xmm` / `assigned_xmm` exactly as before — which
    /// is what makes widening the vector's meaning from "for its whole life" to
    /// "right now" an additive change rather than a new contract.
    fn ls_set_fp_reg(&mut self, id: NodeId, reg: Option<u8>) {
        if let Some(cell) = self.reg_of.get_mut(id as usize) {
            *cell = reg;
        }
    }

    /// The GP twin of [`Self::ls_set_fp_reg`].
    fn ls_set_gp_reg(&mut self, id: NodeId, reg: Option<u8>) {
        if let Some(cell) = self.gp_reg_of.get_mut(id as usize) {
            *cell = reg;
        }
    }

    /// `id`'s value has left its register: the home word is where it lives from
    /// this position on.
    ///
    /// State only — no instruction. The home word already holds the value
    /// (write-through stores it at the definition, and `set_residency` refuses
    /// a dropped home to every managed value), so a `SpillKind::Store` event is
    /// a no-op for this consumer and the only thing a drop has to do is stop
    /// readers believing the register.
    ///
    /// Clearing the OWNER as well as the per-node bit is the half that is easy
    /// to miss: `gp_reg_owner` is what `mark_gp_reg_live` uses to evict the
    /// previous holder, and an owner entry left naming a node whose value is no
    /// longer there would make the next publish into that register clear a bit
    /// that is already clear and, worse, leave a stale owner for a register the
    /// plan hands to somebody else.
    fn ls_drop_residency(&mut self, id: NodeId, gp: bool) {
        if gp {
            if let Some(reg) = self.assigned_gpr(id) {
                if self.gp_reg_owner.get(reg as usize).copied().flatten() == Some(id) {
                    self.gp_reg_owner[reg as usize] = None;
                }
            }
            if let Some(cell) = self.gp_reg_live.get_mut(id as usize) {
                *cell = false;
            }
            self.ls_set_gp_reg(id, None);
        } else {
            if let Some(cell) = self.reg_live.get_mut(id as usize) {
                *cell = false;
            }
            self.ls_set_fp_reg(id, None);
        }
    }

    /// Publish `id` into `reg` and make every reader see it there.
    ///
    /// The FP bank has no `gp_reg_owner`, so the eviction the GP bank gets from
    /// `mark_gp_reg_live` is done here by hand: any OTHER node currently
    /// pointed at `reg` has its publication bit cleared, because the
    /// instruction that just ran overwrote the value it was reading. Without
    /// that, `resident_xmm` keeps answering `reg` for a value whose bits are
    /// gone — the identical hazard `gp_reg_owner`'s field comment records, with
    /// the identical consequence (a wrong value, not a crash) and none of the
    /// machinery.
    ///
    /// The scan is over the whole node arena rather than over `ls_managed`.
    /// Restricting it to managed values would be defensible — the allocator
    /// proves no managed value is published into a register an unmanaged one
    /// holds while that one is live — but it makes the safety of this function
    /// depend on a proof in another module, and the scan runs only at a
    /// transition, of which a method has a handful.
    fn ls_publish(&mut self, id: NodeId, reg: u8, gp: bool) {
        if gp {
            // Round 9: a `Move` vacates its source register. Leaving the OLD
            // register's owner naming `id` made the next publish into it (the
            // allocator vacated it precisely to reuse it) run
            // `mark_gp_reg_live(other)`, see `previous == id` and clear `id`'s
            // bit although `id` is correctly in `reg` — every later read of
            // `id` then fell back to its home word. Never wrong code (managed
            // homes are never dropped), but it cancelled the Move's benefit.
            if let Some(old) = self.assigned_gpr(id) {
                if old != reg && self.gp_reg_owner.get(old as usize).copied().flatten() == Some(id)
                {
                    self.gp_reg_owner[old as usize] = None;
                }
            }
            self.ls_set_gp_reg(id, Some(reg));
            self.mark_gp_reg_live(id);
            return;
        }
        for other in 0..self.reg_live.len() {
            let other_id = other as NodeId;
            if other_id == id {
                continue;
            }
            if self.assigned_xmm(other_id) == Some(reg) {
                if let Some(cell) = self.reg_live.get_mut(other) {
                    *cell = false;
                }
            }
        }
        self.ls_set_fp_reg(id, Some(reg));
        self.mark_reg_live(id);
    }

    /// Materialise every transition the plan puts at linear position `pos`,
    /// immediately before the node at that position is lowered.
    ///
    /// # Ordering, in three parts
    ///
    /// 1. **Drops first.** They emit nothing and only take a register away from
    ///    a reader, so doing them first means no instruction below can be read
    ///    out of a location the allocator says is already stale.
    /// 2. **Then the copies, in the order the plan computed.** Several moves at
    ///    one position are a PARALLEL copy — `a ← b` beside `b ← a` is a swap,
    ///    and emitting the two in sequence makes both `b`. `plan_register_
    ///    residency` has already run them through `regalloc::resolve_parallel_
    ///    copy`, the same sequencer the phi edges use, and has REFUSED the whole
    ///    split plan for the method if the answer needed a scratch register
    ///    (this position is between two nodes, where RAX may be carrying a value
    ///    and RCX a deferred one, so there is no register here that is free by
    ///    construction).
    /// 3. **A move reads its planned source or it reads memory, never a third
    ///    thing.** `resident_*` is asked whether the source register really
    ///    holds the value right now; when it does not — a definition arm that
    ///    never published, or a `Ref` copy `invalidate_ref_residency` dropped
    ///    because a collector could have run — the home word is read instead.
    ///    Falling back to memory can only REMOVE a register read, so the
    ///    sequence the plan computed stays valid. Falling back to *some other*
    ///    register would not, which is why this does not reuse the generic
    ///    operand readers.
    ///
    /// # The safepoint rule
    ///
    /// A `Load` into a register is a new cached copy of a word the oop map
    /// names, exactly like the publish at a definition site — so it lives under
    /// the same audit and needs no new argument: `lower_block`'s per-node loop
    /// invalidates after every node that is not `op_cannot_deopt`, and this runs
    /// strictly INSIDE that loop, before the node whose lowering the copy exists
    /// to serve. `plan_register_residency` refuses any managed value with a
    /// transition at a terminator or edge position precisely so that this
    /// remains true — those two positions are outside the loop that owns the
    /// invariant, and a `Ref` published there would survive the back-edge poll's
    /// own call with nothing to drop it.
    fn ls_apply_transitions(&mut self, pos: usize) {
        let Some(at) = self.ls_at.get(pos) else {
            return;
        };
        if at.is_empty() {
            return;
        }
        // Cloned out of `self`: every arm below takes `&mut self` to emit.
        let at = at.clone();
        for t in &at {
            if let LsTransition::Drop { node, gp } = *t {
                self.ls_drop_residency(node, gp);
                self.ls_split_emitted[3] += 1;
            }
        }
        for t in &at {
            match *t {
                LsTransition::Drop { .. } => {}
                LsTransition::Load { node, reg, gp } => {
                    self.ls_emit_home_load(node, reg, gp);
                    self.ls_split_emitted[0] += 1;
                }
                LsTransition::RematConst { node, reg, value } => {
                    // No memory access at all: the point of a remat. `Op::Const`
                    // is the only shape taken here — see `ls_split_transitions`
                    // for why `ConstF` and `Param` are lowered as home loads.
                    self.emit_mov_reg_imm_smart(reg, value);
                    self.ls_publish(node, reg, true);
                    self.ls_split_emitted[1] += 1;
                }
                LsTransition::Move { node, from, to, gp } => {
                    let readable = if gp {
                        self.resident_gpr(node) == Some(from)
                    } else {
                        self.resident_xmm(node) == Some(from)
                    };
                    if readable {
                        if gp {
                            self.emit_mov_reg_reg64(to, from);
                        } else {
                            self.fp_reg_move(to, from);
                        }
                        self.ls_publish(node, to, gp);
                        self.ls_split_emitted[2] += 1;
                    } else {
                        self.ls_emit_home_load(node, to, gp);
                        self.ls_split_emitted[0] += 1;
                    }
                }
            }
        }
    }

    /// `reg ← [home(node)]`, in whichever bank, then publish.
    ///
    /// `slot_of` rather than `slot_of_unwritten`: a managed value's home is
    /// never dropped (`set_residency` withholds droppability from exactly this
    /// population), so the word this reads is one the definition wrote — and if
    /// that ever stops being true, `slot_of` refusing and latching a bailout is
    /// the outcome this file wants, rather than an offset nothing wrote.
    fn ls_emit_home_load(&mut self, node: NodeId, reg: u8, gp: bool) {
        let off = self.slot_of(node);
        if gp {
            self.load_reg_from_frame(reg, off);
            self.ls_reloads += 1;
        } else {
            let is_double = self
                .graph
                .nodes
                .get(node as usize)
                .is_some_and(|n| matches!(n.ty, IrType::Double));
            self.fp_load(reg, off, is_double);
            self.ls_reloads += 1;
        }
        self.ls_publish(node, reg, gp);
    }

    /// The `imm32` this operand denotes, if it is an integer constant that
    /// fits one.
    ///
    /// A wider `long` constant falls back to the register form, which is
    /// correct rather than merely conservative: every immediate form below
    /// SIGN-EXTENDS its `imm32` to 64 bits, so a constant outside `i32` cannot
    /// be expressed by one.
    fn alu_imm32(&self, id: NodeId) -> Option<i32> {
        if !self.alu_imm_on {
            return None;
        }
        match self.graph.nodes.get(id as usize)?.op {
            Op::Const(val) => i32::try_from(val).ok(),
            _ => None,
        }
    }

    /// Does lowering THIS NODE leave RCX exactly as it found it?
    ///
    /// [`op_preserves_rcx`] asked of the op, widened by the one fact an op
    /// cannot express: a binary arm reaches RCX only through the REGISTER form
    /// of its second operand, and an operand that folds into an immediate never
    /// takes that branch. The three fold helpers (`emit_alu_acc_imm`,
    /// `emit_imul_imm`, `emit_shift_imm`) all decide on `alu_imm32(id)`, so
    /// asking that here is asking the arm's own question rather than a proxy
    /// for it — and `every_folded_arm_reaches_rcx_only_in_its_register_form`
    /// is what holds the two together.
    ///
    /// `alu_imm32` already answers `None` when `alu_imm_on` (`ir_alu_imm_enabled`) is off,
    /// so the two flags cannot disagree: with folding off nothing here is
    /// eligible and this collapses back to `op_preserves_rcx`.
    ///
    /// A prediction, and treated as one: `lower_data_node_tracked` compares
    /// `rcx_writes` across the node and refuses the compile if the arm wrote
    /// RCX anyway.
    fn node_preserves_rcx(&self, id: NodeId) -> bool {
        let Some(node) = self.graph.nodes.get(id as usize) else {
            return false;
        };
        if op_preserves_rcx(&node.op) {
            return true;
        }
        if !ir_carry_rcx_folded_enabled() {
            return false;
        }
        // The FP forms of these ops go through `fp_load_value` into XMM0/XMM1
        // and never reach the arm this reasons about.
        if !matches!(node.ty, IrType::Int | IrType::Long) {
            return false;
        }
        if !matches!(
            node.op,
            Op::Add | Op::Sub | Op::Mul | Op::And | Op::Or | Op::Xor | Op::Shl | Op::Shr | Op::UShr
        ) {
            return false;
        }
        node.inputs
            .get(1)
            .is_some_and(|&b| self.alu_imm32(b).is_some())
    }

    /// Would `node_preserves_rcx` admit `id` if the folded widening were on?
    ///
    /// Census only, and deliberately independent of both flags: a run with
    /// `CRATONVM_JIT_IR_CARRY_RCX_FOLDED=0` still reports how many triples the
    /// widening would have converted, which is the number that prices it
    /// WITHOUT a second run.
    fn mid_would_fold(&self, id: NodeId) -> bool {
        let Some(node) = self.graph.nodes.get(id as usize) else {
            return false;
        };
        matches!(node.ty, IrType::Int | IrType::Long)
            && matches!(
                node.op,
                Op::Add
                    | Op::Sub
                    | Op::Mul
                    | Op::And
                    | Op::Or
                    | Op::Xor
                    | Op::Shl
                    | Op::Shr
                    | Op::UShr
            )
            && node.inputs.get(1).is_some_and(|&b| {
                matches!(
                    self.graph.nodes.get(b as usize).map(|c| &c.op),
                    Some(Op::Const(v)) if i32::try_from(*v).is_ok()
                )
            })
    }

    /// `<op> EAX/RAX, imm32` in the one-byte accumulator form, if `id` is a
    /// constant. Answers whether it emitted, so the caller skips its
    /// register-to-register form.
    ///
    /// `acc` is the `AL/eAX, imm` opcode: ADD 0x05, OR 0x0D, AND 0x25,
    /// SUB 0x2D, XOR 0x35 -- the same column of the opcode map, which is why
    /// one helper covers five arms.
    fn emit_alu_acc_imm(&mut self, id: NodeId, acc: u8, wide: bool) -> bool {
        let Some(imm) = self.alu_imm32(id) else {
            return false;
        };
        if wide {
            self.buf.emit_byte(0x48); // REX.W
        }
        if let Ok(imm8) = i8::try_from(imm) {
            // Round 9: `83 /digit ib`, three bytes (four with REX.W) instead
            // of five (six). The accumulator opcodes this is handed are
            // `(digit << 3) | 5` (ADD 05, OR 0D, AND 25, SUB 2D, XOR 35), so
            // the ModRM for `rm = RAX` is `0xC0 | (acc & 0x38)`. The imm8 is
            // sign-extended to the operand width exactly as the imm32 was, so
            // result and flags are identical. `i` loops (`i + 1`, `x & 0xF`)
            // are overwhelmingly in this range.
            self.buf.emit(&[0x83, 0xC0 | (acc & 0x38), imm8 as u8]);
        } else {
            self.buf.emit_byte(acc);
            self.buf.emit(&imm.to_le_bytes());
        }
        self.alu_imms_folded += 1;
        true
    }

    /// Round 17 ([`ir_alu_reg_operand_enabled`]): `op EAX/RAX, r` straight
    /// from the register `id` is resident in, instead of `MOV RCX, r; op EAX,
    /// ECX`. `acc` is the accumulator opcode [`Self::emit_alu_acc_imm`] takes;
    /// the `r/m, r` form of the same operation is `acc - 4` (ADD 01, OR 09,
    /// AND 21, SUB 29, XOR 31). Declines -- emitting nothing -- for a value
    /// one of the two carry slots names (its read is the carry's, through
    /// `gp_load_value`), a constant (the immediate form's), a value with no
    /// resident register, and one in RAX or RCX. RCX is not written, so no
    /// carry is disturbed; the caller skips the RCX-twin offer, which needs
    /// the operand in RCX.
    fn emit_alu_acc_reg(&mut self, id: NodeId, acc: u8, wide: bool) -> bool {
        if !ir_alu_reg_operand_enabled() || self.mir_mode != MirMode::Off {
            return false;
        }
        if matches!(self.live_carry, Some((prod, _, _, _)) if prod == id)
            || matches!(self.deferred_rcx, Some((prod, _, _)) if prod == id)
        {
            return false;
        }
        if self
            .graph
            .nodes
            .get(id as usize)
            .is_some_and(|n| matches!(n.op, Op::Const(_)))
        {
            return false;
        }
        let Some(r) = self.resident_gpr(id) else {
            return false;
        };
        if r == RAX || r == RCX {
            return false;
        }
        let mut rex = 0x40u8;
        if wide {
            rex |= 0x08; // REX.W
        }
        if r >= 8 {
            rex |= 0x04; // REX.R
        }
        if rex != 0x40 {
            self.buf.emit_byte(rex);
        }
        // ModRM: mod 11, reg = r (the source), rm = RAX.
        self.buf.emit(&[acc - 4, 0xC0 | ((r & 7) << 3)]);
        self.alu_reg_operands += 1;
        true
    }

    /// `IMUL EAX/RAX, EAX/RAX, imm32` (0x69 /r id), if `id` is a constant.
    fn emit_imul_imm(&mut self, id: NodeId, wide: bool) -> bool {
        let Some(imm) = self.alu_imm32(id) else {
            return false;
        };
        if wide {
            self.buf.emit_byte(0x48);
        }
        if let Ok(imm8) = i8::try_from(imm) {
            // Round 9: `6B /r ib` — IMUL with a sign-extended imm8, three
            // bytes instead of six; same product, same flags.
            self.buf.emit(&[0x6B, 0xC0, imm8 as u8]); // dst=rax, src=rax
        } else {
            self.buf.emit(&[0x69, 0xC0]); // dst=rax, src=rax
            self.buf.emit(&imm.to_le_bytes());
        }
        self.alu_imms_folded += 1;
        true
    }

    /// `IMUL EAX/RAX, r, imm` (`6B /r ib` / `69 /r id`) -- the THREE-operand
    /// form, reading the first operand straight from its resident register --
    /// when `b` folds and `a` is resident. Answers whether it emitted; when it
    /// did, RAX holds `a * b` exactly as `gp_load_value(RAX, a)` followed by
    /// [`Self::emit_imul_imm`] would have left it, one `MOV` shorter.
    ///
    /// Round 9 wave 10 (irl10),
    /// `perf-long-counted-loops-lose-the-optimizing-osr-body`: `s += i * 3`
    /// spent `mov rax,r15; imul rax,3` per iteration on a counter that was
    /// already in R15.
    ///
    /// Declines, EMITTING NOTHING, unless all of:
    ///
    /// * `b` folds on exactly the predicate the other fold helpers use
    ///   (`alu_imm32`), so `node_preserves_rcx`' prediction for the arm is
    ///   unchanged: when this fires the arm never reaches RCX, and when `b`
    ///   does not fold this declines and the arm's register form runs as before;
    /// * `a` is resident in the GP file and is not a value a carry is holding
    ///   (a carried value must be read through `gp_load_value`, which is what
    ///   retires the carry; a resident value is never carried, so this is the
    ///   belt to `plan_carries`' braces, as in `emit_add_lea`).
    ///
    /// Writes RAX only; reads `a`'s register. The GP file names neither RAX nor
    /// RCX (asserted in `every_folded_arm_reaches_rcx_only_in_its_register_form`).
    fn emit_imul_reg_imm3(&mut self, a: NodeId, b: NodeId, wide: bool) -> bool {
        let Some(imm) = self.alu_imm32(b) else {
            return false;
        };
        if self.carry_names(a) || self.carry_names(b) {
            return false;
        }
        let Some(src) = self.resident_gpr(a) else {
            return false;
        };
        let (bytes, len) = imul_rax_reg_imm_bytes(src, imm, wide);
        self.buf.emit(&bytes[..len]);
        self.alu_imms_folded += 1;
        true
    }

    /// `<shift> EAX/RAX, imm8` (0xC1 /digit ib), if `id` is a constant.
    ///
    /// The count is masked here to the width the JVM specifies -- 5 bits for
    /// `ishl`/`ishr`/`iushr`, 6 for the `l` forms. x86 masks a shift count the
    /// same way, which is what makes the existing `CL` form correct without a
    /// mask; doing it explicitly keeps the immediate form from depending on
    /// that coincidence.
    ///
    /// `modrm` is the WHOLE ModRM byte (`0xE0` SHL, `0xF8` SAR, `0xE8` SHR —
    /// `0xC0 | digit << 3`, rm = RAX), not the `/digit`: a bare digit here
    /// would encode a memory operand. (Named `digit` before round 9.)
    fn emit_shift_imm(&mut self, id: NodeId, modrm: u8, wide: bool) -> bool {
        let Some(imm) = self.alu_imm32(id) else {
            return false;
        };
        let count = (imm as u32) & if wide { 63 } else { 31 };
        if wide {
            self.buf.emit_byte(0x48);
        }
        self.buf.emit(&[0xC1, modrm, count as u8]);
        self.alu_imms_folded += 1;
        true
    }

    /// Load `id` into `dst` for a value that LEAVES this tier through the
    /// compiled-entry ABI (a call argument or a return value): an `int`
    /// sign-extended to 64 bits.
    ///
    /// The backend ABI is "all JVM values are passed as i64, ints sign-extended"
    /// (`x64.rs`), and the single-pass tier's callees and callers RELY on it: its
    /// `i2l` is a no-op, so a callee that widens a parameter, or an inlined body
    /// that does, reads all 64 bits. This tier's own `int` convention is the
    /// opposite -- a consumer reads only the LOW 32 bits, and a 32-bit ALU
    /// result (`neg eax`, `add eax, ecx`, `mov eax, eax` for `l2i`) leaves the
    /// high half ZERO -- so a negative `int` computed here and handed on
    /// unextended reached a single-pass `flog10pow2` as 4294967244 where it
    /// meant -52, and `Double.toString` indexed `MathUtils.g` with garbage
    /// (`ArrayIndexOutOfBoundsException: Index 2137324 out of bounds for length
    /// 1234`, `Sbr3UnsafecasOsr`). A constant is already sign-extended by its
    /// own materialisation and is left alone.
    fn gp_load_abi_value(&mut self, dst: u8, id: NodeId) {
        self.gp_load_value(dst, id);
        let Some(node) = self.graph.nodes.get(id as usize) else {
            return;
        };
        if node.ty == IrType::Int && !matches!(node.op, Op::Const(_)) {
            // MOVSXD dst, dst32
            let hi = u8::from(dst >= 8);
            self.buf.emit(&[
                0x48 | (hi << 2) | hi,
                0x63,
                0xC0 | ((dst & 7) << 3) | (dst & 7),
            ]);
        }
    }

    /// Load `id`'s value into `dst`, from its resident register when it has one
    /// and from its home word otherwise.
    ///
    /// The read half of the GP cache. A site that still calls
    /// `load_to_rax(self.slot_of(id))` directly is simply not accelerated,
    /// which is a missed optimization and never wrong code: the home word is
    /// written unconditionally.
    #[track_caller]
    fn gp_load_value(&mut self, dst: u8, id: NodeId) {
        // Wave 64 (lane L2): the token-read guard, checked before the carry
        // paths below, which return without reaching `resident_gpr`. A read
        // that falls through to the register or home path is checked again
        // there; the hit count is "hits", not distinct reads.
        self.token_read_check(id);
        // ── A carried value is already in `dst`, and only in `dst` ────
        //
        // Every clause below is checked rather than argued, because a carried
        // value exists in exactly one place and a wrong answer here would read
        // a frame word nothing wrote:
        //
        // * this really is the consumer the carry was planned for;
        // * it is asking for the register the plan chose;
        // * and for an RAX carry, NOTHING has been emitted since the producer
        //   left the value there — `buf.pos()` proves it, and no audit of what
        //   the arms emit can be wrong about it. An RCX carry cannot use that
        //   proof (the consumer's first read is emitted in between) and rests
        //   on `op_reads_rax_then_rcx` instead: that read writes RAX only.
        if let Some((prod, cons, reg, pos)) = self.live_carry {
            if prod == id {
                if self.cur_def != Some(cons) {
                    self.refuse_carry("read outside its planned consumer");
                } else if dst != reg {
                    self.refuse_carry("read into a register the plan did not choose");
                } else if reg == RAX && pos != self.buf.pos() {
                    self.refuse_carry("something was emitted between the two");
                } else {
                    self.live_carry = None;
                    self.carries_read += 1;
                    // The value is in `dst`. That is the whole optimization:
                    // no store, no load, and for an RAX carry no instruction
                    // at all.
                    return;
                }
            }
        }
        // The DEFERRED carry, read the same way and on the same three checks
        // as the adjacent one, minus the `buf.pos()` proof — which is exactly
        // what this slot cannot offer, since a whole arm was emitted in
        // between. What stands in for it is `op_preserves_rcx`, checked when
        // that arm was lowered (`lower_data_node_tracked`), plus the allowance
        // running out if more than one arm ever gets between the two.
        if let Some((prod, cons, _)) = self.deferred_rcx {
            if prod == id {
                if self.cur_def != Some(cons) {
                    self.refuse_deferred("read outside its planned consumer");
                } else if dst != RCX {
                    self.refuse_deferred("read into a register other than RCX");
                } else {
                    self.deferred_rcx = None;
                    self.carry_deferred_read += 1;
                    self.carries_read += 1;
                    return;
                }
            }
        }
        // Past both carry slots, so this read is not the one either was
        // planned for. If it names RCX it is about to overwrite whatever a
        // deferred carry left there.
        if dst == RCX {
            self.note_rcx_written();
        }
        // 2026-09-02: a constant is an IMMEDIATE, not a frame word. The
        // `Op::Const` arm still writes its home (a deopt frame may name it,
        // and some sites still read slots directly), but no reader of a
        // constant has to wait on that store any more: `fib` materialised
        // `1` and `2` into frame words and reloaded them on every call.
        if self.const_imm_on {
            if let Some(node) = self.graph.nodes.get(id as usize) {
                if let Op::Const(val) = &node.op {
                    let val = *val;
                    self.emit_mov_reg_imm_smart(dst, val);
                    return;
                }
            }
        }
        match self.resident_gpr(id) {
            Some(src) => self.emit_mov_reg_reg64(dst, src),
            None => {
                let off = self.slot_of(id);
                self.load_reg_from_frame(dst, off);
            }
        }
    }

    /// Load an array INDEX into RCX already zero-extended, so the bounds
    /// guard's `MOV ECX, ECX` has nothing left to do (backlog MX-B2 of
    /// `r16-matrix-2d-inner-loop-rereads-rows`).
    ///
    /// Every 32-bit write of a GPR zero-extends through the full register in
    /// hardware, so `MOV ECX, r32`, `MOV ECX, [rbp - off]` and `MOV ECX,
    /// imm32` each leave RCX with a zero high half and the low half the index
    /// node defines -- exactly what `MOV ECX, ECX` would have made of the
    /// 64-bit copy. A carried value is read through [`Self::gp_load_value`]
    /// (it is already in RCX, with whatever high half its producer left) and
    /// is not marked. The mark is a code position, consumed by
    /// [`Self::emit_array_null_bounds_guards_for`] only when NOTHING has been
    /// emitted since: the same `buf.pos()` proof the RAX carry uses.
    fn gp_load_index_rcx(&mut self, id: NodeId) {
        let carried = matches!(self.live_carry, Some((prod, ..)) if prod == id)
            || matches!(self.deferred_rcx, Some((prod, ..)) if prod == id);
        if carried {
            self.gp_load_value(RCX, id);
            return;
        }
        self.note_rcx_written();
        if self.const_imm_on {
            if let Some(Op::Const(val)) = self.graph.nodes.get(id as usize).map(|n| &n.op) {
                // MOV ECX, imm32 (the low half; the high half becomes zero).
                let v = *val as u32;
                self.buf.emit_byte(0xB9);
                self.buf.emit(&v.to_le_bytes());
                self.index_zx_at = Some(self.buf.pos());
                return;
            }
        }
        match self.resident_gpr(id) {
            Some(src) => {
                // MOV ECX, r32 (`89 /r`, REX.R for an extended source).
                if src >= 8 {
                    self.buf.emit_byte(0x44);
                }
                self.buf.emit(&[0x89, 0xC0 | ((src & 7) << 3) | (RCX & 7)]);
            }
            None => {
                // MOV ECX, dword [rbp - off]: the home word's low half.
                let off = self.slot_of(id);
                self.buf.emit_byte(0x8B);
                self.emit_rbp_modrm_disp(RCX, off);
            }
        }
        self.index_zx_at = Some(self.buf.pos());
    }

    /// The element-wise vector pre-loop on the entry edge `pred_block ->
    /// succ_block`, when [`crate::ir_vector_loop::plan_vector_loops`] admitted
    /// that loop (round 16 matrix residual, MX16-5). Emitted after the edge's
    /// phi copies, so the induction phi holds its entry value, and before the
    /// jump into the header; see the module doc for the shape and why it is
    /// exact. Emits nothing for every other edge.
    ///
    /// Clobbers RAX, RCX, RDX, R8-R11, the flags, XMM0/XMM1 and the vector
    /// pool (`xmm_roles::VECTOR_REGION_MAX`, as the frame may use it). None of
    /// them holds a value across a block boundary: the GP residency file is
    /// callee-saved (`IR_LOWER_LS_GPRS`), the FP file is XMM2-XMM7, and a carry
    /// never spans a block. `VZEROUPPER` closes the 256-bit region, so the
    /// legacy-SSE code after it pays no transition.
    fn emit_vector_preloop(&mut self, pred_block: usize, succ_block: usize) {
        use crate::ir_vector_loop as vl;
        if !crate::ir_vector_loop::ir_vector_loop_enabled() {
            return;
        }
        if self.vec_plans.is_none() {
            let graph = self.graph;
            let schedule = self.schedule;
            let (plans, refusals) =
                vl::plan_vector_loops(graph, schedule, &|c| ctrl_block_of(graph, schedule, c));
            if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_JITC") {
                for p in &plans {
                    eprintln!(
                        "[ir-vec] loop at bci {:?}: {:?} x{} lanes, {} arrays, {} invariants{}",
                        p.header_bci,
                        p.kind,
                        p.kind.lanes(),
                        p.bases.len(),
                        p.invariants.len(),
                        if p.reduce.is_some() { ", reduction" } else { "" }
                    );
                }
                for (h, why) in &refusals {
                    let bci = self
                        .graph
                        .nodes
                        .get(self.schedule.blocks[*h].ctrl as usize)
                        .and_then(|n| n.bytecode_pc);
                    eprintln!("[ir-vec] loop at bci {bci:?} refused: {why}");
                }
            }
            self.vec_plans = Some(plans);
        }
        let Some(plan) = self
            .vec_plans
            .as_ref()
            .and_then(|ps| {
                ps.iter()
                    .find(|p| p.entry_pred == pred_block && p.header == succ_block)
            })
            .cloned()
        else {
            return;
        };
        // Refused, too, with a `--gpu` input-cache barrier armed (every scalar
        // primitive store marks its bucket, a vector store would not), with a
        // split plan installed (a value's register at the header is then its
        // layout predecessor's) and with the owed-cycle poll latch (a second
        // flag the pre-loop's poll does not test).
        if !crate::x64::has_avx2()
            || !self.ls_edge_copies.is_empty()
            || !self.ls_block_start.is_empty()
            || self.direct_helpers.gen_owed_poll_flag_addr != 0
            || crate::gpu_barrier::barrier_bytes().is_some()
        {
            return;
        }
        // Where `j` goes back: its home word when it has a live one, and its
        // register when it has one. A phi with neither has nowhere to be told.
        let iv = plan.iv;
        let home_live = self.node_slot.get(iv as usize).copied().flatten().is_some()
            && !self.home_dropped.get(iv as usize).copied().unwrap_or(false);
        let iv_reg = self.assigned_gpr(iv);
        if !home_live && iv_reg.is_none() {
            return;
        }
        // A reduction (r21 vector, VEC21-4): the accumulator phi is told the
        // same way, so it needs a home or a register too.
        let acc_phi = plan.reduce.map(|r| r.acc);
        let (acc_home_live, acc_reg) = match acc_phi {
            Some(a) => (
                self.node_slot.get(a as usize).copied().flatten().is_some()
                    && !self.home_dropped.get(a as usize).copied().unwrap_or(false),
                self.assigned_gpr(a),
            ),
            None => (false, None),
        };
        if acc_phi.is_some() && !acc_home_live && acc_reg.is_none() {
            return;
        }
        // The registers: XMM0/XMM1 and the encodable vector pool. Invariants
        // take the top of it, a reduction's accumulator the next one down,
        // temporaries the rest (at least one: the fold's scratch).
        let mut pool: Vec<u8> = vec![XMM0, XMM1];
        pool.extend(
            crate::regalloc::xmm_roles::VECTOR_REGION_MAX
                .iter()
                .copied()
                .filter(|&r| {
                    crate::regalloc::xmm_roles::vector_pool_is_encodable(r, IR_LOWER_SAVED_XMMS)
                }),
        );
        let acc_regs = usize::from(acc_phi.is_some());
        if plan.invariants.len() + acc_regs >= pool.len() {
            return;
        }
        let inv_regs: Vec<u8> = pool.split_off(pool.len() - plan.invariants.len());
        let acc_vreg: Option<u8> = if acc_phi.is_some() { pool.pop() } else { None };
        let regs = vl::StepRegs {
            temps: &pool,
            inv_regs: &inv_regs,
            acc: acc_vreg,
        };
        let fold: Option<Vec<u8>> = match acc_vreg {
            Some(a) => match vl::fold_code(plan.kind, a, pool[0]) {
                Some(code) => Some(code),
                None => return,
            },
            None => None,
        };
        let step_bytes = 32i32;
        let mut steps: Vec<Vec<u8>> = Vec::with_capacity(vl::UNROLL);
        for u in 0..vl::UNROLL {
            // Cast: HEADER_SIZE + 3 * 32 <= 127 (asserted by the conversion).
            let Ok(disp) = i8::try_from(HEADER_SIZE as i32 + u as i32 * step_bytes) else {
                return;
            };
            match vl::step_code(&plan, &regs, disp) {
                Some(code) => steps.push(code),
                None => return,
            }
        }
        let lanes = plan.kind.lanes();
        // A byte-lane STORE (VEC21-3) also needs the `boolean[]` kind byte, to
        // refuse an array whose `bastore` masks; decided before any byte is
        // emitted, like every refusal above.
        let byte_store = plan.kind == vl::VecKind::Byte && plan.reduce.is_none();
        let bool_store_tag: Option<u8> = if byte_store {
            match cratonvm_types::primitive_array_kind_tags_byte("[Z") {
                Some(tag) => Some(tag),
                None => return,
            }
        } else {
            None
        };
        // ── Guards: nothing Java-visible has changed until they all pass ──
        let mut bail: Vec<usize> = Vec::new();
        self.gp_load_value(RDX, plan.iv);
        self.buf.emit(&[0x48, 0x63, 0xD2]); // MOVSXD RDX, EDX
        const LEN_DISP: u8 = crate::x64::disp::disp8_const(ARRAY_LENGTH_OFFSET as i64) as u8;
        match plan.bound_length_of {
            Some(arr) => {
                // n = arr.length, read once: a null `arr` leaves for the
                // scalar header, whose own `arraylength` throws there.
                self.gp_load_value(R10, arr);
                self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                bail.push(self.emit_jcc_rel32(0x84)); // JZ bail
                self.buf.emit(&[0x45, 0x8B, 0x52, LEN_DISP]); // MOV R10D, [R10 + len]
            }
            None => {
                self.gp_load_value(R10, plan.bound);
                self.buf.emit(&[0x4D, 0x63, 0xD2]); // MOVSXD R10, R10D
            }
        }
        self.buf.emit(&[0x48, 0x85, 0xD2]); // TEST RDX, RDX
        bail.push(self.emit_jcc_rel32(0x88)); // JS bail
        for (i, &b) in plan.bases.iter().enumerate() {
            let r = vl::BASE_REGS[i];
            self.gp_load_value(r, b);
            let rex_b = u8::from(r >= 8);
            // TEST r, r
            self.buf.emit(&[
                0x48 | (rex_b << 2) | rex_b,
                0x85,
                0xC0 | ((r & 7) << 3) | (r & 7),
            ]);
            bail.push(self.emit_jcc_rel32(0x84)); // JZ bail
                                                  // CMP R10D, [r + len] -- n > length: some lane would be past it.
            self.buf
                .emit(&[0x44 | rex_b, 0x3B, 0x40 | (2 << 3) | (r & 7), LEN_DISP]);
            bail.push(self.emit_jcc_rel32(0x8F)); // JG bail
            // VEC21-3: a byte-lane store into a `boolean[]` owes JVMS 6.5's
            // `value & 1`, which a raw byte lane does not apply; such a call
            // leaves for the scalar loop, whose `bastore` masks.
            if let (Some(tag), true) = (bool_store_tag, i == plan.store_base) {
                // CMP BYTE [r + KIND_TAGS_BYTE_OFFSET], tag("[Z")
                if rex_b != 0 {
                    self.buf.emit_byte(0x41);
                }
                self.buf.emit(&[
                    0x80,
                    0x78 | (r & 7),
                    cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    tag,
                ]);
                bail.push(self.emit_jcc_rel32(0x84)); // JE bail
            }
        }
        // ── The invariants, broadcast once ──
        for (i, &v) in plan.invariants.iter().enumerate() {
            let dst = inv_regs[i];
            let konst = match self.graph.nodes.get(v as usize).map(|n| &n.op) {
                Some(Op::Const(c)) => Some(*c as u64),
                Some(Op::ConstF(bits)) => Some(*bits),
                _ => None,
            };
            match (konst, plan.kind) {
                (Some(bits), _) => {
                    self.emit_mov_reg_imm64(R11, bits);
                    self.buf.emit(&[0x66, 0x49, 0x0F, 0x6E, 0xC3]); // MOVQ XMM0, R11
                }
                (None, vl::VecKind::Double) => self.fp_load_value(XMM0, v, true),
                (None, vl::VecKind::Float) => self.fp_load_value(XMM0, v, false),
                // Int / Long, and a sub-word lane, which broadcasts the low
                // byte / word of the `int`.
                (None, _) => {
                    self.gp_load_value(R11, v);
                    self.buf.emit(&[0x66, 0x49, 0x0F, 0x6E, 0xC3]); // MOVQ XMM0, R11
                }
            }
            let mut b = Vec::new();
            vl::emit_broadcast(&mut b, plan.kind, dst, XMM0);
            self.buf.emit(&b);
        }
        // A reduction's accumulator starts at zero lanes: after the
        // broadcasts, which stage through XMM0.
        if let Some(a) = acc_vreg {
            let mut z = Vec::new();
            vl::emit_zero(&mut z, a);
            self.buf.emit(&z);
        }
        let polls = crate::x64::jit_safepoint_polls_enabled() && self.safepoint_flag_addr != 0;
        if polls {
            // Interpreter round i6 wave 120, lane L2 (`CRATONVM_JIT_POLL_THREAD_WORD`,
            // default OFF; i24-L3 stage 3): the loop's polls test whatever R11
            // names, once chosen here -- this thread's poll word when its
            // mirror is set (a door of this VM published it), else the baked
            // flag. A set pause byte leaves the vector loop for the scalar
            // remainder, whose own poll parks, exactly as the flag did.
            //
            //   MOV R11, <seg>:[disp32] ; TEST R11, R11 ; JNZ .have
            //   MOV R11, imm64 <flag>   ; .have:
            let have = if crate::x64::jit_poll_thread_word_enabled() {
                // Cast: the probe answers a 32-bit segment displacement.
                let disp = crate::x64::loop_poll_word_tls_disp() as u32;
                self.buf
                    .emit_byte(crate::x64::inline_rbp_tls_segment_prefix());
                self.buf.emit(&[0x4C, 0x8B, 0x1C, 0x25]); // MOV R11, <seg>:[disp32]
                self.buf.emit(&disp.to_le_bytes());
                self.buf.emit(&[0x4D, 0x85, 0xDB]); // TEST R11, R11
                Some(self.emit_jcc_rel32(0x85)) // JNZ .have
            } else {
                None
            };
            self.emit_mov_reg_imm64(R11, self.safepoint_flag_addr as u64);
            if let Some(have) = have {
                self.patch_rel32_to_here(have);
            }
        }
        let mut done: Vec<usize> = Vec::new();
        let unroll = vl::UNROLL as i32;
        // ── Main loop: UNROLL steps per trip while j + lanes*UNROLL <= n ──
        self.buf.emit(&[0x49, 0x81, 0xEA]); // SUB R10, imm32
        self.buf.emit(&(lanes * unroll).to_le_bytes());
        self.buf.emit(&[0x4C, 0x39, 0xD2]); // CMP RDX, R10
        let skip_main = self.emit_jcc_rel32(0x8F); // JG after_main
        let main_top = self.buf.pos();
        if polls {
            self.buf.emit(&[0x41, 0xF6, 0x03, 0xFF]); // TEST byte [R11], 0xFF
            done.push(self.emit_jcc_rel32(0x85)); // JNZ done
        }
        for s in &steps {
            self.buf.emit(s);
        }
        self.buf.emit(&[0x48, 0x81, 0xC2]); // ADD RDX, imm32
        self.buf.emit(&(lanes * unroll).to_le_bytes());
        self.buf.emit(&[0x4C, 0x39, 0xD2]); // CMP RDX, R10
        self.buf.emit(&[0x0F, 0x8E]); // JLE main_top
        let rel = main_top as i32 - (self.buf.pos() as i32 + 4);
        self.buf.emit(&rel.to_le_bytes());
        self.patch_rel32_to_here(skip_main);
        // ── One step per trip while j + lanes <= n ──
        self.buf.emit(&[0x49, 0x81, 0xC2]); // ADD R10, imm32
        self.buf.emit(&(lanes * (unroll - 1)).to_le_bytes());
        let one_top = self.buf.pos();
        self.buf.emit(&[0x4C, 0x39, 0xD2]); // CMP RDX, R10
        done.push(self.emit_jcc_rel32(0x8F)); // JG done
        if polls {
            self.buf.emit(&[0x41, 0xF6, 0x03, 0xFF]); // TEST byte [R11], 0xFF
            done.push(self.emit_jcc_rel32(0x85)); // JNZ done
        }
        self.buf.emit(&steps[0]);
        self.buf.emit(&[0x48, 0x81, 0xC2]); // ADD RDX, imm32
        self.buf.emit(&lanes.to_le_bytes());
        self.buf.emit_byte(0xE9); // JMP one_top
        let rel = one_top as i32 - (self.buf.pos() as i32 + 4);
        self.buf.emit(&rel.to_le_bytes());
        // ── done: j (in [entry, n], non-negative) back into the phi ──
        for p in done {
            self.patch_rel32_to_here(p);
        }
        // A reduction: the lanes' wrapped sum (EAX / RAX) added to the
        // accumulator's entry value, back into its phi (VEC21-4). Every lane
        // holds the sum of the elements before `j` in its residue class, so
        // the total is the scalar sum of elements `entry..j` mod 2^32 / 2^64.
        if let (Some(acc), Some(code)) = (acc_phi, fold.as_ref()) {
            self.buf.emit(code);
            self.gp_load_value(RCX, acc);
            if plan.kind == vl::VecKind::Long {
                self.buf.emit(&[0x48, 0x01, 0xC1]); // ADD RCX, RAX
            } else {
                self.buf.emit(&[0x01, 0xC1]); // ADD ECX, EAX
                self.buf.emit(&[0x48, 0x63, 0xC9]); // MOVSXD RCX, ECX
            }
            if acc_home_live {
                let off = self.slot_of(acc);
                self.store_abi_reg(RCX, off);
            }
            if let Some(r) = acc_reg {
                self.emit_mov_reg_reg64(r, RCX);
            }
        }
        self.buf.emit(&[0xC5, 0xF8, 0x77]); // VZEROUPPER
        if home_live {
            let off = self.slot_of(iv);
            self.store_abi_reg(RDX, off);
        }
        if let Some(r) = iv_reg {
            self.emit_mov_reg_reg64(r, RDX);
        }
        for p in bail {
            self.patch_rel32_to_here(p);
        }
        self.note_rcx_written();
        self.vec_loops_emitted += 1;
    }

    /// Write `id`'s result from `src`: ALWAYS to the home word, and
    /// additionally into its resident register.
    ///
    /// The write-through invariant lives here. The home store is emitted
    /// unconditionally and first, so the frame image is complete at every
    /// instruction boundary — which is what lets `emit_safepoint_map`,
    /// `build_deopt_points` and `emit_phi_copies` stay untouched.
    fn gp_store_value(&mut self, id: NodeId, slot: i32, src: u8) {
        if self.poisons_int_def(id) {
            self.emit_poison_int_high(src);
        }
        self.store_abi_reg(src, slot);
        if let Some(dst) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(dst, src);
            self.ls_spills += 1;
            self.mark_gp_reg_live(id);
        }
    }

    /// Publish a result already stored to its home word into its register — the
    /// memory → register transition, for definition sites whose result reaches
    /// the home word by a route this cache does not intercept.
    fn publish_gp_from_slot(&mut self, id: NodeId, slot: i32) {
        if let Some(dst) = self.assigned_gpr(id) {
            self.load_reg_from_frame(dst, slot);
            self.ls_reloads += 1;
            self.mark_gp_reg_live(id);
        }
    }

    /// Make parameter node `id`'s home the word the prologue stored it to,
    /// `[rbp - param_offset]`, instead of a coloured slot holding a copy of it
    /// (round 11 wave 14, lane fib, proposal F13-2). `false` -- and nothing
    /// changed -- for an offset that cannot be a home.
    ///
    /// Sound because that word is written exactly once, by the prologue (or,
    /// on an OSR entry, by the stub's seed of this very node's home), and never
    /// again: this tier keeps locals in SSA values, and every other home is a
    /// coloured slot past `first_spill`. So the word holds the parameter at
    /// every point of the frame, which is also what `frame_value_for` already
    /// assumed for a parameter whose node had not been emitted yet. What goes
    /// is the copy: one store per activation, and the `RAX` round trip of the
    /// load that preceded it.
    fn alias_param_home(&mut self, id: NodeId, param_offset: i32) -> bool {
        let Some(home) = u32::try_from(param_offset).ok().and_then(NonZeroU32::new) else {
            return false;
        };
        // Only a word `emit_prologue` stores: `local_offset(i)` for a
        // parameter `i < num_params`, all of them below `first_spill`.
        let stored_by_prologue = usize::try_from(param_offset)
            .is_ok_and(|off| off % 8 == 0 && off / 8 >= 1 && off / 8 <= self.num_params);
        if !stored_by_prologue || param_offset >= self.first_spill {
            return false;
        }
        let Some(cell) = self.node_slot.get_mut(id as usize) else {
            return false;
        };
        *cell = Some(home);
        // Defined from the prologue on; the relocation contract's "written by
        // the emitting code" holds for this word before the body runs.
        if let Some(defined) = self.defined_nodes.get_mut(id as usize) {
            *defined = true;
        }
        true
    }

    /// `MOV dst, src` — 64-bit register to register, for any pair including the
    /// extended registers the GP file is made of.
    fn emit_mov_reg_reg64(&mut self, dst: u8, src: u8) {
        if dst == RCX {
            self.note_rcx_written();
        }
        self.emit_mov_reg_reg64_raw(dst, src);
    }

    /// [`Self::emit_mov_reg_reg64`] without the RCX bookkeeping, for the ONE
    /// site that writes RCX on purpose while a deferred carry is being
    /// INSTALLED: `store_rax` moving the carried value out of RAX. Every other
    /// caller wants the counter to move.
    fn emit_mov_reg_reg64_raw(&mut self, dst: u8, src: u8) {
        if dst == src {
            return;
        }
        let rex = 0x48u8 | (((src >= 8) as u8) << 2) | ((dst >= 8) as u8);
        self.buf
            .emit(&[rex, 0x89, 0xC0 | ((src & 7) << 3) | (dst & 7)]);
    }

    /// `CMP a, b` — register to register, any pair, 64-bit when `wide`.
    ///
    /// `39 /r` is `CMP r/m, r`, so the FIRST operand goes in the ModRM `r/m`
    /// field and the second in `reg` — the opposite nesting from the mnemonic,
    /// and the reason this is a named helper rather than three inline literals.
    /// The flags it sets are `a - b`, which is the order `CmpCond::x64_cc`
    /// expects.
    ///
    /// The 32-bit form emits REX only when it has to name an extended register,
    /// so a comparison of two low registers stays two bytes exactly as
    /// `CMP EAX, ECX` did.
    fn emit_cmp_reg_reg(&mut self, a: u8, b: u8, wide: bool) {
        let (bytes, len) = cmp_reg_reg_bytes(a, b, wide);
        self.buf.emit(&bytes[..len]);
    }

    /// `CMP a, [RBP - offset]` — 64-bit when `wide`.
    ///
    /// `3B /r` is `CMP r, r/m`, the mirror of the `39 /r` above: here the FIRST
    /// operand is the `reg` field and the second comes from memory, which is
    /// the direction needed to compare a resident value against one still in
    /// its frame slot. Flags are `a - [slot]`, the same order
    /// `CmpCond::x64_cc` expects.
    ///
    /// The 32-bit form reads four bytes where the `MOV` it replaces read eight.
    /// That is the same comparison: an `int` slot's value is its low word (the
    /// high half is either extension, whichever its producer left, and never
    /// read), and the `CMP EAX, ECX` this replaces only ever looked at those
    /// four bytes either.
    fn emit_cmp_reg_frame(&mut self, a: u8, offset: i32, wide: bool) {
        let rex = if wide { 0x48u8 } else { 0x40u8 } | (((a >= 8) as u8) << 2);
        if rex != 0x40 {
            self.buf.emit_byte(rex);
        }
        self.buf.emit_byte(0x3B);
        self.emit_rbp_modrm_disp(a, offset);
    }

    /// `CMP a, imm` — register against a folded constant, 64-bit when `wide`.
    fn emit_cmp_reg_imm(&mut self, a: u8, imm: i32, wide: bool) {
        let (bytes, len) = cmp_reg_imm_bytes(a, imm, wide);
        self.buf.emit(&bytes[..len]);
    }

    /// `CMP [RBP - offset], imm` — a value still in its slot against a folded
    /// constant, 64-bit when `wide`. Three instructions become one, and the
    /// one names no register at all.
    fn emit_cmp_frame_imm(&mut self, offset: i32, imm: i32, wide: bool) {
        let (bytes, len) = cmp_frame_imm_bytes(offset, imm, wide);
        self.buf.emit(&bytes[..len]);
    }

    /// Which in-place form a fused compare of `a` against `b` can take, if any.
    ///
    /// Ordered by how much each saves, and the immediate forms come first
    /// because they need the least: a constant folds into the instruction, so
    /// only the FIRST operand needs a place to be read from, and a first
    /// operand that lost its register is served as well as one that kept it.
    ///
    /// `alu_imm32` is the gate on the constant rather than a local
    /// `Op::Const` match, deliberately. It declines a constant too wide for
    /// `i32` — which every immediate form here sign-extends, so such a
    /// constant has no immediate encoding at all — and it is OFF under a MIR
    /// mode, where a tiled node is emitted by the selector and a fold here
    /// would make the byte-equality lane compare two different programs.
    ///
    /// `slot_of_checked` rather than `slot_of`: a dropped home declines the
    /// frame forms instead of latching a bailout on a path that has a
    /// perfectly good fallback.
    fn pick_cmp_form(&self, a: NodeId, b: NodeId) -> Option<CmpForm> {
        if let Some(imm) = self.alu_imm32(b) {
            return match self.resident_gpr(a) {
                Some(ra) => Some(CmpForm::RegImm(ra, imm)),
                None => self
                    .slot_of_checked(a)
                    .ok()
                    .map(|off| CmpForm::FrameImm(off, imm)),
            };
        }
        // Both remaining forms need the first operand in a register: there is
        // no `CMP mem, mem`, and loading `a` to compare it against a slot
        // would spend the instruction this exists to remove.
        let ra = self.resident_gpr(a)?;
        match self.resident_gpr(b) {
            Some(rb) => Some(CmpForm::RegReg(ra, rb)),
            None => self
                .slot_of_checked(b)
                .ok()
                .map(|off| CmpForm::RegFrame(ra, off)),
        }
    }

    /// Set the flags for `a <cc> b` -- the compare of a FUSED `Op::Cmp`, which
    /// materialises no boolean -- in the cheapest form the operands' locations
    /// allow. Shared by the fused `If` (`lower_terminator`) and, since round 11,
    /// the fused `Op::Guard`; the caller emits the `Jcc`.
    ///
    /// 64-bit for `Ref` and `Long` operands; see the unfused `Op::Cmp` arm.
    ///
    /// Both already in registers: compare them there. A fused compare is the
    /// one site that may do this without owing anything else -- it defines no
    /// value, writes no home and publishes no register, so the only thing that
    /// outlives it is the flags, and those are the same either way. Nothing
    /// downstream may assume RAX holds `a`.
    ///
    /// Four in-place forms -- see `pick_cmp_form` for which one wins and why.
    /// Neither operand may be a value some carry is holding: that has to be
    /// read through `gp_load_value` or the carry strands. `b` in a frame slot is
    /// the common case, not the fallback: `peak_live` routinely exceeds the
    /// register file, and a loop bound is exactly the long-lived value that
    /// loses. `b` a CONSTANT is commoner still -- `i < 100` is the shape of most
    /// Java loops.
    fn emit_fused_int_compare(&mut self, a: NodeId, b: NodeId) {
        let ref_cmp = matches!(self.graph.nodes[a as usize].ty, IrType::Ref | IrType::Long)
            || matches!(self.graph.nodes[b as usize].ty, IrType::Ref | IrType::Long);
        let form = if ir_cmp_in_place_enabled() && !self.carry_names(a) && !self.carry_names(b) {
            self.pick_cmp_form(a, b)
        } else {
            None
        };
        match form {
            Some(CmpForm::RegReg(ra, rb)) => {
                self.emit_cmp_reg_reg(ra, rb, ref_cmp);
                self.cmp_in_place += 1;
            }
            Some(CmpForm::RegFrame(ra, off)) => {
                self.emit_cmp_reg_frame(ra, off, ref_cmp);
                self.cmp_in_place_frame += 1;
            }
            Some(CmpForm::RegImm(ra, imm)) => {
                self.emit_cmp_reg_imm(ra, imm, ref_cmp);
                self.cmp_imm += 1;
            }
            Some(CmpForm::FrameImm(off, imm)) => {
                self.emit_cmp_frame_imm(off, imm, ref_cmp);
                self.cmp_imm_frame += 1;
            }
            None => {
                self.gp_load_value(RAX, a);
                self.gp_load_value(RCX, b);
                if ref_cmp {
                    self.buf.emit(&[0x48, 0x39, 0xC8]); // CMP RAX, RCX
                } else {
                    self.buf.emit(&[0x39, 0xC8]); // CMP EAX, ECX
                }
            }
        }
    }

    /// `x + k` (or `x - k`) as a `LEA`, when `k` is a constant and `x` is
    /// resident. Answers WHERE it left the result, so the caller knows how
    /// much of its accumulator sequence still has to run.
    ///
    /// What it replaces, from `CmpImm.wide` with `i` in RBX:
    ///
    /// ```asm
    /// mov rax,rbx        ; i -> RAX
    /// add eax,1
    /// ```
    ///
    /// Two instructions to add one to a value that was already in a register.
    /// `LEA` is the only three-operand integer instruction on this machine, so
    /// it is the only way to read a source and write a destination that is not
    /// the source without routing through the accumulator — and `x + 1` in a
    /// counted loop is exactly that shape.
    ///
    /// **Two forms, and the weaker one is the common case.** Which applies
    /// turns on whether the result got a register of its own:
    ///
    /// * it did — [`AddForm::Done`], `lea r14d,[rbx+1]` writes that register
    ///   directly and the arm owes nothing further;
    /// * it did not — [`AddForm::InRax`], `lea eax,[rbx+1]` writes the
    ///   accumulator and [`Self::store_rax`] finishes exactly as it would
    ///   have. One instruction out of two, and nothing else about the arm
    ///   changes.
    ///
    /// The second form is the one a loop-carried increment actually takes, and
    /// it is why this is not written as a single all-or-nothing fold. Measured
    /// on `CmpImm.wide`: `def_publishes=0` against `phi copies:
    /// reg_publishes=10` — the loop-carried values are published by the phi
    /// copies on the back edge, so `i + 1` itself writes a home word and is
    /// given no register. A first version that required one engaged **nowhere**
    /// on that probe.
    ///
    /// Unlike the fused compare this DEFINES a value, so the direct form owes
    /// everything a definition owes:
    ///
    /// * neither operand may be a value a carry is holding, which has to be
    ///   read through `gp_load_value` or the carry strands — and when `x` IS
    ///   carried in RAX the accumulator path is already one instruction, so
    ///   declining costs nothing;
    /// * the result must not itself be PLANNED as a carry: `store_rax` hands a
    ///   carried value to its consumer out of RAX, and the direct form never
    ///   puts it there. The accumulator form needs no such guard — it falls
    ///   into `store_rax` with RAX loaded, which is the contract that path
    ///   already has;
    /// * and when the home word survives (`home_dropped` is false — a deopt
    ///   frame names it, say) it is still written, from the destination
    ///   register, which by then holds exactly what RAX would have.
    ///
    /// The 32-bit form zero-extends into the destination, which is what `ADD
    /// EAX, imm` did and what the 64-bit home store then writes, so the frame
    /// image is byte-identical either way.
    fn emit_add_lea(&mut self, id: NodeId, slot: i32, sub: bool, wide: bool) -> AddForm {
        if !ir_add_lea_enabled() {
            return AddForm::No;
        }
        let node = &self.graph.nodes[id as usize];
        let (x, k) = (node.inputs[0], node.inputs[1]);
        // Only the SECOND operand is tried as the constant. `Op::Add` is
        // commutative and nothing canonicalises it, so `1 + i` is left to the
        // accumulator path — a missed fold, never a wrong one, and javac does
        // not emit that order for a counted loop.
        let Some(imm) = self.alu_imm32(k) else {
            // Round 9 wave 10 (irl10): `x + y` with both operands in registers
            // has a `LEA` form too. `x - y` has none.
            return if sub {
                AddForm::No
            } else {
                self.emit_add_lea_reg_reg(id, slot, x, k, wide)
            };
        };
        // `x - k` is `x + (-k)`, except at `i32::MIN`, whose negation is not an
        // `i32` at all. One constant in the language, and it declines here
        // rather than wrapping into a silent `+ MIN`.
        let Some(disp) = (if sub { imm.checked_neg() } else { Some(imm) }) else {
            return AddForm::No;
        };
        if self.carry_names(x) || self.carry_names(k) {
            return AddForm::No;
        }
        let Some(base) = self.resident_gpr(x) else {
            return AddForm::No;
        };
        // The direct form, when the result has a register to be written into
        // and nothing has claimed RAX as the route to its consumer.
        if let Some(dst) = self.assigned_gpr(id) {
            if self.carry_at_store(slot).is_none() {
                let (bytes, len) = lea_reg_base_disp_bytes(dst, base, disp, wide);
                self.buf.emit(&bytes[..len]);
                if self.poisons_int_def(id) {
                    self.emit_poison_int_high(dst);
                }
                self.mark_gp_reg_live(id);
                self.reg_publishes_at_def += 1;
                self.cur_def_published = true;
                if self.home_dropped.get(id as usize).copied().unwrap_or(false) {
                    self.homes_dropped_at_def += 1;
                    self.home_stores_dropped += 1;
                } else {
                    self.store_abi_reg(dst, slot);
                }
                self.add_lea += 1;
                return AddForm::Done;
            }
        }
        let (bytes, len) = lea_reg_base_disp_bytes(RAX, base, disp, wide);
        self.buf.emit(&bytes[..len]);
        self.add_lea_acc += 1;
        AddForm::InRax
    }

    /// `x + y` as `LEA dst, [x + y]` when both operands are in registers --
    /// the register-register sibling of [`Self::emit_add_lea`]'s `x + k`, with
    /// the same two outcomes ([`AddForm::Done`] into the result's own register,
    /// [`AddForm::InRax`] into the accumulator for the caller's `store_rax`)
    /// and the same obligations for the direct one.
    ///
    /// Round 9 wave 10 (irl10),
    /// `perf-long-counted-loops-lose-the-optimizing-osr-body`: the
    /// accumulator `s += t` was `mov rax,r14; add rax,rcx; mov r12,rax` per
    /// iteration -- three instructions for one add of two register values.
    ///
    /// The second operand may be the value an RCX CARRY holds for exactly this
    /// node (`live_carry` naming RCX, or `deferred_rcx`, with this node as the
    /// planned consumer): it is then read out of RCX through `gp_load_value`,
    /// which retires the carry and emits nothing, and used as the `LEA` index.
    /// A value carried in RAX, or carried for a different consumer, declines,
    /// as does a first operand that is carried at all -- the accumulator path
    /// then reads it, and is already one instruction shorter for an RAX carry.
    ///
    /// Every check precedes the first byte, so a decline emits NOTHING and the
    /// caller's accumulator sequence runs exactly as before -- which matters
    /// for an RAX carry into this node, whose `gp_load_value` proves that
    /// nothing was emitted since its producer.
    ///
    /// Writes only the destination (the result's register, never RAX/RCX,
    /// which the GP file does not name) or RAX; RCX is only READ.
    fn emit_add_lea_reg_reg(
        &mut self,
        id: NodeId,
        slot: i32,
        x: NodeId,
        y: NodeId,
        wide: bool,
    ) -> AddForm {
        if self.carry_names(x) {
            return AddForm::No;
        }
        let this_consumer = self.cur_def == Some(id);
        let y_in_rcx = this_consumer
            && (matches!(self.live_carry, Some((p, c, r, _)) if p == y && c == id && r == RCX)
                || matches!(self.deferred_rcx, Some((p, c, _)) if p == y && c == id));
        if !y_in_rcx && self.carry_names(y) {
            return AddForm::No;
        }
        let Some(base) = self.resident_gpr(x) else {
            return AddForm::No;
        };
        let index = if y_in_rcx {
            RCX
        } else {
            match self.resident_gpr(y) {
                Some(r) => r,
                None => return AddForm::No,
            }
        };
        if y_in_rcx {
            // Retires the carry: the value is already in RCX, so this emits
            // nothing. `y_in_rcx` asked exactly the three things
            // `gp_load_value`'s carry arms check (producer, planned consumer
            // is the node being lowered, register), so it takes the carry;
            // were it ever to refuse instead, it latches a bailout and this
            // artifact is discarded whatever the `LEA` below reads.
            self.gp_load_value(RCX, y);
        }
        // The direct form, when the result has a register to be written into
        // and nothing has claimed RAX as the route to its consumer.
        if let Some(dst) = self.assigned_gpr(id) {
            if self.carry_at_store(slot).is_none() {
                let (bytes, len) = lea_reg_base_index_bytes(dst, base, index, wide);
                self.buf.emit(&bytes[..len]);
                if self.poisons_int_def(id) {
                    self.emit_poison_int_high(dst);
                }
                self.mark_gp_reg_live(id);
                self.reg_publishes_at_def += 1;
                self.cur_def_published = true;
                if self.home_dropped.get(id as usize).copied().unwrap_or(false) {
                    self.homes_dropped_at_def += 1;
                    self.home_stores_dropped += 1;
                } else {
                    self.store_abi_reg(dst, slot);
                }
                self.add_lea += 1;
                return AddForm::Done;
            }
        }
        let (bytes, len) = lea_reg_base_index_bytes(RAX, base, index, wide);
        self.buf.emit(&bytes[..len]);
        self.add_lea_acc += 1;
        AddForm::InRax
    }

    /// Is `id` a value some carry is holding in RAX or RCX right now?
    ///
    /// A carried value must be read through `gp_load_value`, which is what
    /// takes it out of the slot; a site that reads it any other way would leave
    /// the carry stranded and refuse the compile. `plan_carries` already
    /// declines to carry anything the residency file assigned a register, so a
    /// resident value is never carried — this is the belt to that braces,
    /// because the failure is silent at the point it is made.
    fn carry_names(&self, id: NodeId) -> bool {
        matches!(self.live_carry, Some((prod, _, _, _)) if prod == id)
            || matches!(self.deferred_rcx, Some((prod, _, _)) if prod == id)
    }

    /// Latch a structured bailout raised from an infallible legacy accessor.
    ///
    /// The first one wins (it is the cause; later ones are consequences of
    /// continuing to emit into an artifact that is already doomed).
    /// `lower_inner` takes it and reports it instead of returning a bare
    /// `None`. Interior mutability because both `&self` (`slot_of`) and
    /// `&mut self` (`alloc_slot`) accessors latch.
    fn latch_bailout(&self, bailout: Bailout) {
        let mut slot = self.latched_bailout.borrow_mut();
        if slot.is_none() {
            *slot = Some(bailout);
        }
    }

    /// Take the latched bailout, if any.
    fn take_latched_bailout(&self) -> Option<Bailout> {
        self.latched_bailout.borrow_mut().take()
    }

    /// A frame offset that is safe to *emit* against but is not a real
    /// location: the first spill slot. Returned only by the legacy infallible
    /// accessors, and only after a bailout has been latched — which makes
    /// `lower_inner` discard the whole artifact before it can be executed.
    ///
    /// It exists so a doomed compile finishes walking the graph without
    /// panicking and without addressing memory outside the frame. The one
    /// value it must never be is `0`: that is `[rbp - 0]`, the saved caller
    /// frame pointer, which is exactly the read this whole change exists to
    /// make unrepresentable.
    fn poison_slot(&self) -> i32 {
        debug_assert!(self.first_spill > 0);
        self.first_spill
    }

    /// Allocate a frame slot for a node result, or refuse the compile.
    ///
    /// real-frame-deopt (#6): the deopt stub calls `ir_deopt_entry` while the
    /// frame is live, with `rsp = rbp - frame_size`. The Win64 ABI requires 32
    /// bytes of caller shadow space at `[rsp, rsp+32)` — i.e. frame offsets
    /// `(frame_size-32 .. frame_size]`. A spill slot at offset `o` occupies
    /// `[rbp-o, rbp-o+8)`; to keep it clear of the shadow region we cap
    /// `o <= frame_size - DEOPT_SHADOW_SPACE`. `frame_size` already budgets the
    /// 32-byte shadow (plus a 16-byte stack-arg reserve), so this never rejects
    /// a method the old `o < frame_size` bound accepted.
    ///
    /// Exceeding that cap used to be an `assert!`, i.e. a panic on the compiler
    /// thread — which in a release VM is `fatal runtime error: failed to
    /// initiate panic` → SIGABRT of the whole process, for what is only a
    /// *compiler* resource limit. It is now a `FrameTooLarge` bailout: the
    /// method loses its optimized body and runs in a lower tier, which is
    /// always semantically valid.
    ///
    /// The offset is no longer a bump cursor: it is `first_spill + colour * 8`
    /// for the colour [`plan_slots`] assigned this value, so two values whose
    /// live ranges do not overlap land on the same word. Calling this twice for
    /// one node is therefore idempotent rather than wasteful. A node the plan
    /// does not cover is an internal inconsistency (the plan enumerates exactly
    /// the nodes `prealloc_phi_slots` and `lower_data_node` allocate for), and
    /// refuses the compile rather than inventing an offset.
    fn alloc_slot_checked(&mut self, id: NodeId) -> CompileResult<i32> {
        let offset = self.planned_slot_off(id)?;
        // `planned_slot_off` already proved the offset non-zero and inside the
        // frame; re-deriving the `NonZeroU32` here keeps the "no zero offsets"
        // invariant enforced at the write, not merely upstream of it.
        let located = u32::try_from(offset)
            .ok()
            .and_then(NonZeroU32::new)
            .ok_or_else(|| {
                Bailout::new(BailoutReason::Internal(
                    "ir_lower: spill offset 0 would encode [rbp - 0] (saved caller RBP)",
                ))
            })?;
        let cell = self.node_slot.get_mut(id as usize).ok_or_else(|| {
            Bailout::new(BailoutReason::Internal("ir_lower: node id out of range"))
        })?;
        *cell = Some(located);
        // Watermark, not a cursor: the highest word any emitted node's slot has
        // reached. Every safepoint's `live_frame_hi` is read off this, and with
        // reuse it stops growing once the peak live set is reached.
        self.spill_high_water = self.spill_high_water.max(offset.saturating_add(8));
        // Relocation contract: a slot becomes publishable the moment the
        // emitting code writes it. `alloc_slot` is called at the point of
        // emission for every node EXCEPT phis, whose slots are reserved up
        // front by `prealloc_phi_slots` and written later by edge copies —
        // those are marked separately, after the prologue zeroes them.
        if !matches!(self.graph.nodes[id as usize].op, Op::Phi) {
            self.defined_nodes[id as usize] = true;
        }
        Ok(offset)
    }

    /// The frame offset [`Self::alloc_slot_checked`] *will* assign `id`, without
    /// assigning it.
    ///
    /// Split out so the level-2 tile encoder can encode a store to a
    /// destination slot before the destination has been allocated, and get the
    /// same answer the allocating path would — by calling the same code, not by
    /// repeating the arithmetic. Every refusal below is the allocating path's
    /// refusal, unchanged; only the three mutations live in the caller.
    fn planned_slot_off(&self, id: NodeId) -> CompileResult<i32> {
        let color = match self
            .slot_plan
            .node_color
            .get(id as usize)
            .copied()
            .flatten()
        {
            Some(color) => color,
            None => {
                return Err(Bailout::with_context(
                    BailoutReason::Internal(
                        "ir_lower: the slot plan has no colour for a value being lowered",
                    ),
                    format!(
                        "n{id} reached alloc_slot with no planned frame slot (op {:?})",
                        self.graph.nodes.get(id as usize).map(|n| &n.op),
                    ),
                ))
            }
        };
        let offset = i32::try_from(u64::from(color).saturating_mul(8))
            .ok()
            .and_then(|delta| self.first_spill.checked_add(delta))
            .ok_or_else(|| {
                Bailout::new(BailoutReason::Internal(
                    "ir_lower: coloured spill offset overflowed the frame arithmetic",
                ))
            })?;
        // `spill_cap_off` excludes the 32-byte shadow space AND (Gap B) the
        // Java-arg staging region, so a spill never overlaps either. For a
        // no-call method it equals `frame_size - DEOPT_SHADOW_SPACE` — the
        // historical bound, unchanged.
        if offset > self.spill_cap_off {
            return Err(Bailout::with_context(
                BailoutReason::FrameTooLarge {
                    bytes: offset.max(0) as usize,
                    limit: self.spill_cap_off.max(0) as usize,
                },
                format!(
                    "spill slot for n{id} past the frame's spill cap \
                     (frame {} bytes, cap {})",
                    self.frame_size, self.spill_cap_off
                ),
            ));
        }
        // `first_spill > 0` and colours are non-negative, so this cannot be
        // `None` — but the conversion is where the "no zero offsets" invariant
        // is *enforced* rather than assumed, so it is checked, not asserted.
        u32::try_from(offset)
            .ok()
            .and_then(NonZeroU32::new)
            .ok_or_else(|| {
                Bailout::new(BailoutReason::Internal(
                    "ir_lower: spill offset 0 would encode [rbp - 0] (saved caller RBP)",
                ))
            })?;
        Ok(offset)
    }

    /// Infallible façade over [`Self::alloc_slot_checked`] for the ~45
    /// per-opcode emission sites, which are `fn(..) -> ()` and cannot `?`.
    ///
    /// On refusal it latches the structured bailout — so `lower_inner` discards
    /// the artifact and the caller falls back to the single-pass backend — and
    /// returns the poison slot so the doomed walk finishes without panicking.
    /// New code should call `alloc_slot_checked` and propagate.
    fn alloc_slot(&mut self, id: NodeId) -> i32 {
        match self.alloc_slot_checked(id) {
            Ok(offset) => offset,
            Err(bailout) => {
                self.latch_bailout(bailout);
                self.poison_slot()
            }
        }
    }

    /// LV11-4 (JIT round 19 proposal wave 12, lane lv12): the position of
    /// by-bci point `index` -- the earliest scheduled node that claims its
    /// snapshot (`frame_snapshot`), else the earliest node at its bci, which is
    /// where `snapshot_native` / `bci_native` anchor it -- and every value it
    /// names whose home [`point_home_covers`] rejects there. Latches the
    /// refusal (`ir_lower: deopt point names a home past its range`).
    fn check_deopt_point_ranges(&self, index: usize, sp: &crate::ir::SafepointSnapshot) {
        let plan = &self.slot_plan;
        let pos_of = |id: usize| plan.pos_of.get(id).copied().flatten();
        let claimed = self
            .graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| n.frame_snapshot == Some(index as u32))
            .filter_map(|(id, _)| pos_of(id))
            .min();
        let pos = claimed.or_else(|| {
            self.graph
                .nodes
                .iter()
                .enumerate()
                .filter(|(_, n)| n.bytecode_pc == Some(sp.bci))
                .filter_map(|(id, _)| pos_of(id))
                .min()
        });
        let Some(pos) = pos else {
            return;
        };
        for &v in sp
            .locals
            .iter()
            .chain(sp.stack.iter())
            .chain(sp.monitors.iter())
        {
            if v == NO_NODE || point_home_covers(plan, v as usize, pos) {
                continue;
            }
            self.deopt_point_stale.set(self.deopt_point_stale.get() + 1);
            self.latch_bailout(Bailout::with_context(
                BailoutReason::Internal("ir_lower: deopt point names a home past its range"),
                format!(
                    "point {index} (bci {}) at position {pos} names n{v}",
                    sp.bci
                ),
            ));
        }
    }

    /// Interpreter round i2 wave 64 (lane L2): the token-read guard's check,
    /// called from the operand funnels -- [`Self::slot_of_checked`] (and so
    /// `slot_of`), [`Self::resident_gpr`], [`Self::resident_xmm`],
    /// [`Self::gp_load_value`] and [`Self::fp_load_value`].
    ///
    /// `id` is a read of the node being lowered's operand; when that node names
    /// `id` only in a memory-token slot ([`Self::token_only_inputs`]) the read
    /// has no business existing, and with a trimmed home it reads a word the
    /// colouring may have handed on. Such a read latches
    /// `BailoutReason::Internal("ir_lower: operand read through a memory-token
    /// slot")` -- the compile is refused, the method runs in a lower tier.
    ///
    /// Exempt, by construction of the set rather than by a list: an id the node
    /// ALSO names in a value slot (a real read), and an id whose home the
    /// colouring pinned (its range is the pinned one with or without a trim;
    /// counted in `token_read_pinned_hits`, e.g. the deopt description of a
    /// snapshot that names the token producer). Reads outside a data node's
    /// lowering (phi edge copies, deopt pads) see an empty set.
    ///
    /// A hit prints one `[ir-ls] token-read guard:` line under
    /// `CRATONVM_DBG_IR_LINEAR_SCAN` or `CRATONVM_DBG_IR_LS_TOKEN_TRIM_CENSUS`.
    #[track_caller]
    fn token_read_check(&self, id: NodeId) {
        if self.token_only_inputs.is_empty() {
            return;
        }
        let Some(&(_, slot, pinned)) = self.token_only_inputs.iter().find(|e| e.0 == id) else {
            return;
        };
        let scope = self.token_scope;
        if pinned {
            self.token_read_pinned_hits
                .set(self.token_read_pinned_hits.get() + 1);
            let mut by_scope = self.token_scope_pinned_hits.get();
            by_scope[scope as usize] += 1;
            self.token_scope_pinned_hits.set(by_scope);
            return;
        }
        self.token_read_refusals
            .set(self.token_read_refusals.get() + 1);
        let mut by_scope = self.token_scope_refusals.get();
        by_scope[scope as usize] += 1;
        self.token_scope_refusals.set(by_scope);
        let site = core::panic::Location::caller();
        // The scope's reader: the data node (`cur_def`), or -- JIT round 19
        // wave 10, i64-L2 -- the terminator / the tile root that installed a
        // `term` / `mir` set.
        let reader = match scope {
            TokenScope::Data => self.cur_def.unwrap_or(NO_NODE),
            TokenScope::Term | TokenScope::Mir => self.token_scope_reader,
        };
        let op = self
            .graph
            .nodes
            .get(reader as usize)
            .map(|n| format!("{:?}", n.op))
            .unwrap_or_default();
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
            || crate::regalloc::ls_token_trim_census_enabled()
        {
            eprintln!(
                "[ir-ls] token-read guard: n{reader} {op} reads n{id} through token slot {slot} \
                 (at {}:{}) scope={}",
                site.file(),
                site.line(),
                scope.name(),
            );
        }
        // JIT round 19 proposal wave 11, lane lv11 (TOK10-1): in a test build,
        // `CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD=strict` turns a refusal into
        // a panic naming the funnel, so `cargo test -p cratonvm-jit --lib`
        // under that value fails exactly the tests whose compile read through
        // a token slot (`tools/jit/token-read-guard-lib-tests.sh`). The tests
        // that latch a refusal on purpose pin the guard to `1`.
        #[cfg(test)]
        if token_read_guard_strict() {
            panic!(
                "token-read guard (strict test mode): n{reader} ({op}) reads n{id} through its \
                 token slot {slot} (at {}:{}, scope={})",
                site.file(),
                site.line(),
                scope.name(),
            );
        }
        self.latch_bailout(Bailout::with_context(
            BailoutReason::Internal("ir_lower: operand read through a memory-token slot"),
            format!(
                "n{reader} ({op}) reads n{id} through its token slot {slot} (at {}:{}, scope={})",
                site.file(),
                site.line(),
                scope.name(),
            ),
        ));
    }

    /// The token-only inputs of the nodes `ids` for
    /// [`Self::token_only_inputs`]: every id in a memory-token slot of one of
    /// them that no value slot of any of them names
    /// ([`token_only_inputs_across`]). One node: exactly
    /// [`token_only_inputs_in`] of it.
    fn token_only_inputs_of(&self, ids: &[NodeId]) -> Vec<(NodeId, usize, bool)> {
        let graph = self.graph;
        let nodes: Vec<&Node> = ids
            .iter()
            .filter_map(|&id| graph.nodes.get(id as usize))
            .collect();
        // TOK10-3: the reader's own position, the point every in-scope read
        // (an operand funnel or the reader's own deopt description) happens at.
        let reader_pos = if self.token_guard_point_range {
            ids.first()
                .and_then(|&r| self.slot_plan.pos_of.get(r as usize).copied().flatten())
        } else {
            None
        };
        let ranges = self.slot_plan.colouring_ranges();
        token_only_inputs_across(&nodes, |inp| {
            let i = inp as usize;
            let class = self.slot_plan.class.get(i).copied().flatten();
            let named = self.token_guard_named.get(i).copied().unwrap_or(false);
            let range = ranges.get(i).copied().flatten();
            let exempt = token_exempt_at(class, named, range, reader_pos);
            if !exempt && token_exempt_at(class, named, range, None) {
                self.token_point_stale.set(self.token_point_stale.get() + 1);
            }
            exempt
        })
    }

    /// Install the token-read guard's set for the lowering scope `scope`
    /// over the nodes `ids` (the first is the scope's reader), returning what
    /// [`Self::token_scope_exit`] restores. `None`, and nothing computed,
    /// while the guard is off -- so a guard-off compile runs exactly the code
    /// it ran before the scopes existed.
    ///
    /// Interpreter round i2 wave 64 (lane L2) built the `data` scope inline in
    /// [`Self::lower_data_node_tracked`]; JIT round 19 wave 10 (lane tok10,
    /// `i64-L2-proposal-the-token-read-guard-covers-terminators-and-fused-compares`)
    /// moved it here and added the `term` and `mir` scopes.
    fn token_scope_enter(&mut self, ids: &[NodeId], scope: TokenScope) -> Option<TokenScopeSaved> {
        if !self.token_read_guard {
            return None;
        }
        if self.token_guard_named.is_empty() {
            let mut named = vec![false; self.graph.nodes.len().max(1)];
            for sp in &self.graph.safepoints {
                for &v in sp
                    .locals
                    .iter()
                    .chain(sp.stack.iter())
                    .chain(sp.monitors.iter())
                {
                    if let Some(cell) = named.get_mut(v as usize) {
                        *cell = true;
                    }
                }
            }
            self.token_guard_named = named;
        }
        let set = self.token_only_inputs_of(ids);
        if !set.is_empty() {
            self.token_read_nodes += 1;
            self.token_scope_nodes[scope as usize] += 1;
        }
        let saved = TokenScopeSaved {
            set: std::mem::replace(&mut self.token_only_inputs, set),
            scope: self.token_scope,
            reader: self.token_scope_reader,
        };
        self.token_scope = scope;
        self.token_scope_reader = ids.first().copied().unwrap_or(NO_NODE);
        Some(saved)
    }

    /// Undo [`Self::token_scope_enter`].
    fn token_scope_exit(&mut self, saved: Option<TokenScopeSaved>) {
        if let Some(saved) = saved {
            self.token_only_inputs = saved.set;
            self.token_scope = saved.scope;
            self.token_scope_reader = saved.reader;
        }
    }

    /// The census line's `scope=` field: `name:nodes/refusals/pinned-hits`
    /// per [`TokenScope`], comma-separated.
    fn token_scope_census(&self) -> String {
        let refusals = self.token_scope_refusals.get();
        let pinned = self.token_scope_pinned_hits.get();
        TokenScope::ALL
            .iter()
            .map(|&sc| {
                let i = sc as usize;
                format!(
                    "{}:{}/{}/{}",
                    sc.name(),
                    self.token_scope_nodes[i],
                    refusals[i],
                    pinned[i]
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    /// The nodes a terminator's lowering reads operands for: the terminator,
    /// and for an `If` whose compare is FUSED into the branch (`fused_cmp`)
    /// that compare and any `lcmp` / `fcmp` fused under it (`fused_lcmp`,
    /// `fused_fcmp`) -- their arms emit nothing and their operands are read at
    /// the branch. JIT round 19 wave 10 (lane tok10, i64-L2).
    fn term_token_scope_nodes(&self, term: NodeId) -> Vec<NodeId> {
        let mut out = vec![term];
        let Some(node) = self.graph.nodes.get(term as usize) else {
            return out;
        };
        if !matches!(node.op, Op::If) {
            return out;
        }
        let Some(&cond) = node.inputs.get(1) else {
            return out;
        };
        if cond == NO_NODE || !self.fused_cmp.get(cond as usize).copied().unwrap_or(false) {
            return out;
        }
        out.push(cond);
        if let Some(cmp) = self.graph.nodes.get(cond as usize) {
            for &inp in &cmp.inputs {
                if inp == NO_NODE || out.contains(&inp) {
                    continue;
                }
                let fused_under = self.fused_lcmp.get(inp as usize).copied().unwrap_or(false)
                    || self.fused_fcmp.get(inp as usize).copied().unwrap_or(false);
                if fused_under {
                    out.push(inp);
                }
            }
        }
        out
    }

    /// The nodes the level-2 tile rooted at `id` in `block_idx` covers, root
    /// first, when the MIR plan has one (the tile [`Self::mir_tile_bytes`] /
    /// [`Self::mir_shadow_tile_bytes`] would encode). JIT round 19 wave 10.
    fn mir_tile_covered(&self, block_idx: usize, id: NodeId) -> Option<Vec<NodeId>> {
        let plan = self.mir.as_ref()?;
        let (tb, ti) = (*plan.tile_of.get(id as usize)?)?;
        if usize::try_from(tb).ok()? != block_idx {
            return None;
        }
        let tile = plan
            .blocks
            .get(usize::try_from(tb).ok()?)?
            .tiles
            .get(usize::try_from(ti).ok()?)?;
        let mut out = vec![tile.root];
        out.extend(tile.covered.iter().copied().filter(|&c| c != tile.root));
        Some(out)
    }

    /// The frame offset of a node's result, or a bailout if it has none.
    ///
    /// The only read path into `node_slot`. There is no longer a value that
    /// means "unallocated": an absent location is an `Err`, never `0`.
    #[track_caller]
    fn slot_of_checked(&self, id: NodeId) -> CompileResult<i32> {
        self.token_read_check(id);
        // A home nobody wrote is not a location. Refusing here fails the
        // compile and drops the method to the single-pass backend — a coverage
        // loss, never a wrong answer — and `home_read_refusals` names the site
        // that wanted converting. See `home_dropped`.
        //
        // "Names the site" was a COUNT until an `Op::NewArray` length read sent
        // `StringRegexOnly.run` to the single-pass backend and the only way to
        // find which of the ~45 emission sites had asked was to rebuild with a
        // backtrace. `#[track_caller]` costs nothing on the success path — the
        // caller's `Location` is a compile-time constant threaded in a register
        // — and turns the refusal into the file:line of the reader that wants
        // converting to `gp_load_value`. Both façades below forward it.
        if self.home_dropped.get(id as usize).copied().unwrap_or(false) {
            self.home_read_refusals
                .set(self.home_read_refusals.get() + 1);
            let site = core::panic::Location::caller();
            return Err(Bailout::with_context(
                BailoutReason::UnallocatedValue { node: id },
                format!(
                    "n{id}'s home word is never written; read it from its register \
                     (read at {}:{})",
                    site.file(),
                    site.line(),
                ),
            ));
        }
        match self.node_slot.get(id as usize).copied().flatten() {
            // `NonZeroU32` ⇒ never 0, and `alloc_slot_checked` bounds it by
            // `spill_cap_off` ⇒ always inside the frame.
            Some(off) => Ok(off.get() as i32),
            None => Err(Bailout::new(BailoutReason::UnallocatedValue { node: id })),
        }
    }

    /// Infallible façade over [`Self::slot_of_checked`] for the emission sites.
    ///
    /// See `unallocated_slot_use`: this path is unreachable now that
    /// `verify_data_locations` refuses such graphs before emission starts. If
    /// it is ever taken, the latch discards the artifact and the caller falls
    /// back to the single-pass backend — the same outcome as before, but with a
    /// structured reason attached, and returning the poison slot rather than
    /// `0` so no `[rbp - 0]` read can be emitted even transiently.
    /// The frame offset a value's home WOULD occupy, whether or not anything
    /// writes it.
    ///
    /// The single exemption from [`Self::slot_of`]'s refusal, and it is narrow
    /// on purpose: `gather_phi_copies` needs the offset to identify a
    /// destination and to sequentialise the edge's parallel copy, and it hands
    /// that offset to `emit_copy_op`, which decides per copy whether to store
    /// through it. Nothing here reads the word.
    #[track_caller]
    fn slot_of_unwritten(&self, id: NodeId) -> i32 {
        match self.node_slot.get(id as usize).copied().flatten() {
            Some(off) => off.get() as i32,
            None => self.slot_of(id),
        }
    }

    #[track_caller]
    fn slot_of(&self, id: NodeId) -> i32 {
        match self.slot_of_checked(id) {
            Ok(offset) => offset,
            Err(bailout) => {
                self.unallocated_slot_use.set(true);
                self.latch_bailout(bailout);
                if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IRSLOT") {
                    match self.graph.nodes.get(id as usize) {
                        Some(n) => eprintln!(
                            "[irslot] UNALLOCATED node={} op={:?} ty={:?} inputs={:?} pc={:?}",
                            id, n.op, n.ty, n.inputs, n.bytecode_pc
                        ),
                        None => eprintln!("[irslot] UNALLOCATED node={id} (out of range)"),
                    }
                }
                self.poison_slot()
            }
        }
    }

    /// `CRATONVM_JIT_IR_RELOC_EMIT=0` — disable the relocation contract's EMISSION
    /// side entirely (safepoint-id stores, shadow push/reload, the prologue thread
    /// fetch), leaving the frame layout alone.
    ///
    /// Exists so the cost of that emission can be A/B'd on ONE binary against a
    /// deterministic probe. Three attempts inferred it from a single run of a suite
    /// class that later turned out to be bimodal; a lever plus repeats is what that
    /// should have been. Default on, so this changes nothing unless asked.
    fn reloc_emit_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RELOC_EMIT")
    }

    /// `CRATONVM_JIT_IR_COLD_ARG_STAGE=0` — stage a call's outgoing arguments
    /// EAGERLY, before the call, as this backend did until 2026-09-02.
    ///
    /// Default on, meaning the staging happens on each reader's own cold side.
    /// The switch exists because the eager version was removed without one, and
    /// a change to what a frame holds across a call is exactly the kind that
    /// has to be A/B-able in ONE binary when a GC-stress test starts failing.
    /// Not having it cost a rebuild per hypothesis.
    fn cold_arg_stage_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_COLD_ARG_STAGE")
    }

    // ── Moving-young relocation contract ─────────────────────────────────
    //
    // What `conservative_roots` demands of a compiled frame before a young
    // collection may RELOCATE while that frame is live:
    //
    //   1. a non-zero `sp_id_slot_off`, and the id of the active safepoint
    //      stored there, so the exact map can be found (never a union);
    //   2. an `OopMapEntry` whose `bytecode_pc` equals that id and whose
    //      `moving_young_coverage_complete` is set. **No matching entry is a
    //      refusal**, not an absence of objections;
    //   3. `frame_slot_offsets` naming every frame slot that holds a live
    //      reference, so each can be rewritten in place;
    //   4. a `frame_layout` + `live_frame_hi` precise enough that the band scan
    //      can tell storage this frame resumes from apart from dead spill and
    //      outgoing-argument scratch.
    //
    // The IR lowerer is unusually well placed to satisfy this: every REFERENCE
    // keeps an authoritative home word (`value_home_droppable` admits only
    // `Int`/`Long`; the opt-in `ir_ref_residency_enabled` caches a reference in
    // a register but invalidates the copy at every GC point), so unlike the
    // single-pass backend there are no register-resident oops to chase — the
    // complete root set at a safepoint is a set of frame offsets. (Primitive
    // values may live in registers since linear scan went default-ON; that
    // does not touch the root set.)

    /// Interpreter round i2 wave 58 (lane L2,
    /// `CRATONVM_JIT_IR_SYNC_SPLICE_ENTER_NAMES_CALLEE`): when `id` is the
    /// `MonitorEnter` of a synchronized splice window
    /// (`Graph::sync_splice_windows`), the combined pc of that spliced callee's
    /// first instruction -- `chain_at` of it is the callee at bci 0 over its
    /// callers. `None` with the switch off, the inline-frame map off, for
    /// every other monitor op, and when the window's invoke spliced no body
    /// or more than one (a bimorphic site), so a chain is never guessed.
    ///
    /// Why: HotSpot builds a synchronized method's frame before
    /// `lock_method`, so a thread blocked entering it lists it on top
    /// (`docs/internal/fixed-bugs/interpreter-L6-a-blocked-synchronized-method-entrant-is-missing-from-its-stack-trace-FIXED-20261007.md`).
    /// The splice takes the callee's monitor in the caller's frame, at the
    /// invoke's pc; without this the blocked frame read `spin` at the invoke.
    /// Compile time only: the map is published on the slow path of the
    /// acquire, the inline thin lock takes no map at all.
    fn sync_splice_enter_callee_base(&self, id: NodeId) -> Option<usize> {
        if self.inline_frame_sites.is_empty()
            || !crate::x64::inline_frame_map_enabled()
            || !self.graph.sync_splice_windows.iter().any(|w| w.enter == id)
            || !ir_sync_splice_enter_names_callee_enabled()
        {
            return None;
        }
        let pc = self.graph.nodes.get(id as usize)?.bytecode_pc?;
        self.inline_frame_sites.sole_body_base_for_caller_pc(pc)
    }

    /// Record a TWIN of the safepoint map `a` that [`Self::emit_safepoint_map`]
    /// just recorded: the same oop map, the same id-to-bci row and liveness
    /// claim, under a new id whose inline chain is the one at `cur_node_pc`
    /// (the caller's own). Returns the twin's id for the caller to store after
    /// the call that map protected returned, or `None` when `a` is not the
    /// last map recorded (nothing to copy). Interpreter round i2 wave 58,
    /// lane L2: a synchronized splice's enter names its callee only while the
    /// acquire runs.
    fn record_safepoint_twin(&mut self, a: u32) -> Option<u32> {
        let map = self.oop_maps.last().filter(|m| m.bytecode_pc == a)?.clone();
        let twin = self.next_sp_id;
        self.next_sp_id = self.next_sp_id.wrapping_add(1);
        let mut map = map;
        map.bytecode_pc = twin;
        self.oop_maps.push(map);
        // GC719-1 (round 19 wave 8, lane gc8): the twin holds what `a` holds.
        if let Some(homes) = self
            .ir_monitor_homes
            .last()
            .filter(|(id, _)| *id == a)
            .map(|(_, homes)| homes.clone())
        {
            self.ir_monitor_homes.push((twin, homes));
        }
        if let Some(&(_, bci)) = self.sp_id_bcis.iter().rev().find(|&&(id, _)| id == a) {
            self.sp_id_bcis.push((twin, bci));
        }
        if let Some(rec) = self
            .frame_liveness_records
            .iter()
            .rev()
            .find(|r| r.sp_id == a)
            .cloned()
        {
            self.frame_liveness_records
                .push(crate::SafepointFrameLiveness { sp_id: twin, ..rec });
        }
        if !self.inline_frame_sites.is_empty() && crate::x64::inline_frame_map_enabled() {
            let chain: Vec<crate::x64::InlineFrameLevel> = match self.cur_node_pc {
                Some(node_pc) => self
                    .inline_frame_sites
                    .chain_at(node_pc)
                    .into_iter()
                    .map(|l| crate::x64::InlineFrameLevel {
                        label: l.method_key.into(),
                        bci: l.bci,
                        class_id: l.class_id,
                        // Wave 122 (L2): the optimizing tier stamps no bit.
                        hidden: None,
                    })
                    .collect(),
                None => Vec::new(),
            };
            self.inline_frame_sp_id_rows.push((twin, chain));
        }
        Some(twin)
    }

    /// `MOV qword [rbp - sp_id_slot_off], imm32`: publish `id` as this frame's
    /// active safepoint. Sign-extended; ids are small.
    fn emit_sp_id_store(&mut self, id: u32) {
        self.buf.emit(&[0x48, 0xC7, 0x85]);
        self.buf.emit(&(-self.sp_id_slot_off).to_le_bytes());
        self.buf.emit(&id.to_le_bytes());
    }

    /// `CRATONVM_JIT_IR_SELF_CALL_LAZY_SP_ID=0` -- keep the safepoint-id store on
    /// the hot path of a direct self-call in a reference-free body (round 11
    /// wave 15, lane fib; step 3 of `r11w14-rt-ir-lower-oop-free-frame-patch`).
    /// Default on: the store moves to the call's two cold paths, see
    /// `deferred_self_call_sp_id`. Read per compile, so a test can arrange it.
    fn self_call_lazy_sp_id_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SELF_CALL_LAZY_SP_ID")
    }

    /// gen r5w2/oomjit6: the `(plan position, method bci, node)` that arms
    /// [`Self::emit_dead_ref_slot_clears`] while node `id` is lowered, or
    /// `None`. An `Op::Call` qualifies (by default the only op that does): it
    /// is control-pinned, so its bci is
    /// its program point, which is what the reachability argument in the
    /// section above [`DeadRefSlotClear`] needs.
    ///
    /// gen r5w5/oomjit9: a call inside a splice qualifies too. It used to be
    /// left alone because its bci is a combined-buffer pc, not one of this
    /// method's -- and that made every GC point reached through an inlined
    /// callee (`cleared(ref)`'s `System.gc()` spliced into an OSR body, the
    /// shape of `GenR5W3OsrHolderProbe`) a site where nothing was ever
    /// claimed. The bci is now the OUTERMOST enclosing invoke of this method's
    /// own code ([`resolve_spliced_pc`]), and the keep set at that bci
    /// includes every snapshot inside every splice that resolves to an
    /// invoke reachable from it ([`DeadRefSlotClear::splice_named`]), so all
    /// that can run after the call -- the rest of the splice and of the
    /// method -- is covered.
    ///
    /// JIT round 20 wave 17, lane gcDead (I-9): an `Op::New` / `Op::NewArray`
    /// qualifies too under [`Self::alloc_dead_home_clear`]. Both are
    /// control-pinned like a call, and their runtime helper is a GC point;
    /// see the section above [`ir_alloc_dead_home_clear_enabled`] for where
    /// their clears run and why the site never counts as cleaning.
    ///
    /// gci i1/fr (`CRATONVM_JIT_IR_ALLOC_SITE_CLEARS`, default ON since gci i3;
    /// `gengc-r5w5-oomjit9-...` item 1): an `Op::New` / `Op::NewArray` too
    /// ([`dead_ref_clear_arms`]). Both are control-pinned exactly like a call
    /// (`ir_schedule::pinned_anchor`), and the keep-set builders record their
    /// after-sets under the same switch, so the collection an allocation's
    /// slow path reaches sees the homes dead there cleared and claimed dead,
    /// as a call's GC point does.
    ///
    /// At the 2026-10-15 merge of dev into the gci round the two rules
    /// compose: an allocation is armed only while BOTH
    /// `CRATONVM_JIT_IR_ALLOC_DEAD_HOME_CLEAR` (dev; dropped when no plan
    /// converged) and `CRATONVM_JIT_IR_ALLOC_SITE_CLEARS` (gci) are on, and its
    /// clears are placed by the I-9 slow-path machinery; the pinned non-call GC
    /// points (gci i4/ir, `CRATONVM_JIT_IR_OTHER_GC_POINT_CLEARS`) stay armed
    /// under their own switch.
    fn dead_ref_clear_site_for(&self, id: NodeId) -> Option<(usize, usize, NodeId)> {
        if self.dead_ref_clear.is_none() {
            return None;
        }
        let node = self.graph.nodes.get(id as usize)?;
        let armed = match node.op {
            Op::Call { .. } => true,
            Op::New { .. } | Op::NewArray { .. } => {
                self.alloc_dead_home_clear && self.alloc_site_clears
            }
            _ => self.other_site_clears && other_gc_point_is_pinned_site(self.graph, node),
        };
        if !armed {
            return None;
        }
        let pc = node.bytecode_pc?;
        let bci = resolve_spliced_pc(self.spliced_ranges, pc);
        let pos = self.slot_plan.pos_of.get(id as usize).copied().flatten()?;
        Some((pos, bci, id))
    }

    /// gci i5/ir (`CRATONVM_JIT_IR_POLL_GC_POINT_CLEARS`, opt-in): the armed
    /// site of the back-edge poll at the end of `block`, or `None` (arm
    /// nothing) off the switch, without the facts, or for a poll
    /// [`back_edge_poll_header`] does not arm. The position is the
    /// terminator's when the block has one (the poll precedes its compare),
    /// else the block's edge position; the bci is the loop header's, out of a
    /// splice as a call's is; the site is [`poll_site_key`]. See the section
    /// above [`ir_poll_gc_point_clears_enabled`].
    fn poll_dead_ref_clear_site(&self, block: usize) -> Option<(usize, usize, NodeId)> {
        if self.poll_edge_pos.is_empty() || self.dead_ref_clear.is_none() {
            return None;
        }
        let (_, header_pc) = back_edge_poll_header(self.graph, self.schedule, block)?;
        let edge = self.poll_edge_pos.get(block).copied()?;
        let pos = match self.schedule.blocks.get(block)?.terminator {
            Some(term) => self.slot_plan.pos_of.get(term as usize).copied().flatten()?,
            None => edge,
        };
        let bci = resolve_spliced_pc(self.spliced_ranges, header_pc);
        let site = poll_site_key(self.graph, block)?;
        Some((pos, bci, site))
    }

    /// gci i5/ir: emit an armed back-edge poll's map (`block` = the poll's
    /// back-edge block, `None` at the method entry, which is never armed) with
    /// [`Self::poll_dead_ref_clear_site`] installed around it, and the dense
    /// stores forced. Returns what [`Self::emit_safepoint_map_if_enabled`]
    /// returns. Off the switch it IS that call.
    fn emit_poll_safepoint_map(&mut self, block: Option<usize>) -> bool {
        let site = block.and_then(|b| self.poll_dead_ref_clear_site(b));
        let Some((pos, bci, key)) = site else {
            return self.emit_safepoint_map_if_enabled();
        };
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!(
                "[ir-slots] poll site armed: block={} pos={pos} bci={bci} site=n{key}",
                block.unwrap_or(usize::MAX)
            );
        }
        let saved_site = std::mem::replace(&mut self.dead_ref_clear_site, site);
        let saved_args = std::mem::replace(&mut self.dead_ref_clear_site_args, usize::MAX);
        let saved_dense = std::mem::replace(&mut self.poll_site_dense, true);
        let mapped = self.emit_safepoint_map_if_enabled();
        self.dead_ref_clear_site = saved_site;
        self.dead_ref_clear_site_args = saved_args;
        self.poll_site_dense = saved_dense;
        mapped
    }

    /// hga (`r16-codegen-hashmap-get-anatomy`): may the `Op::Call` `id` take
    /// one of the inline prefixes its arm tries ahead of the call
    /// (`try_emit_ir_arraylist_access_prefix`, `..._box_hash_equals_prefix`,
    /// `..._integer_value_of_prefix`, `..._long_value_of_prefix`)? The
    /// method-name screens of those four only, so a superset: a `true` here
    /// for a call no prefix claims merely keeps more homes "may be stale" in
    /// [`stale_sets_at_sites`], which can only add stores, never drop one.
    /// Always `false` under `CRATONVM_JIT_IR_PREFIX_SLOW_PATH_CLEARS=0`.
    fn call_site_may_take_inline_prefix(&self, id: NodeId) -> bool {
        if !self.prefix_slow_path_clears {
            return false;
        }
        let Some(Op::Call { info_ptr }) = self.graph.nodes.get(id as usize).map(|n| &n.op) else {
            return false;
        };
        if *info_ptr == 0 {
            return false;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(*info_ptr as *const JitInvokeInfo) };
        let (class, name, desc) = (info.class_name, info.method_name, info.descriptor);
        let box_value_of = info.invoke_kind == 3
            && name == "valueOf"
            && matches!(
                (class, desc),
                ("java/lang/Integer", "(I)Ljava/lang/Integer;")
                    | ("java/lang/Long", "(J)Ljava/lang/Long;")
            );
        let hash_equals = info.invoke_kind == 0
            && ((name == "hashCode" && desc == "()I")
                || (name == "equals" && desc == "(Ljava/lang/Object;)Z"));
        let array_list = self.array_list_layout.is_some()
            && matches!(info.invoke_kind, 0 | 2)
            && crate::try_resolve_arraylist_intrinsic(class, name, desc, self.array_list_layout)
                .is_some();
        // nio20 L3: the `getClass()` prefix (`try_emit_ir_getclass_prefix`).
        let get_class = self.getclass_prefix_admits(info);
        // nio20 L2 (NIO19-2): the `Unsafe` accessor prefix
        // (`try_emit_ir_unsafe_access_prefix`); its method screen only.
        // nio21 wave 5 L3: and its CAS / getAndAdd / getAndSet rows
        // (`try_emit_ir_unsafe_rmw_prefix`).
        let unsafe_access = self.direct_helpers.unsafe_inline_admitted != 0
            && (crate::direct_helpers::unsafe_inline_access_site(class, name, desc).is_some()
                || crate::direct_helpers::unsafe_inline_rmw_site(class, name, desc).is_some()
                // JIT round 20 wave 12, lane qUnsafe (AT-4): the reference
                // CAS row (`try_emit_ir_unsafe_ref_cas_prefix`).
                || crate::direct_helpers::unsafe_inline_ref_cas_site(class, name, desc)
                // JIT round 21 wave 1, lane updaters (UPDATERS21-1): the
                // reference volatile get / put rows.
                || crate::direct_helpers::unsafe_inline_ref_volatile_site(class, name, desc)
                    .is_some());
        // nio20 wave 3 L2: the String search prefix
        // (`try_emit_ir_string_search_prefix`); its site screen only. Invoke
        // kind 1 too, which `hash_equals` above does not cover.
        let string_search = self.string_layout.is_some()
            && crate::ir_string_search_prefix_kind(class, name, desc)
                .is_some_and(|k| k.admits_invoke_kind(info.invoke_kind));
        // nio20 wave 5 L2: the identity-hash prefix
        // (`try_emit_ir_identity_hash_prefix`); its site screen only.
        let identity_hash = self.identity_hash_prefix_admits(info).is_some();
        // nio21 wave 1 L5: the current-thread prefix
        // (`try_emit_ir_current_thread_prefix`).
        let current_thread = self.current_thread_prefix_admits(info);
        // nio21 wave 11 L5: the constant-`VarHandle` prefix
        // (`try_emit_ir_vh_const_prefix`); its site screen only.
        // JIT r20 wave 18 (lane xVhArr): and its array-element arm
        // (`try_emit_ir_vh_const_array_prefix`).
        let vh_const = class == "java/lang/invoke/VarHandle"
            && vh_const_inline_enabled()
            && (vh_const_site_shape(name, desc).is_some()
                || vh_const_array_site_shape(name, desc).is_some());
        // JIT round 20 wave 17, lane pAtom2: the `Class.isInstance` prefix
        // (`try_emit_ir_class_is_instance_prefix`).
        let class_is_instance = self.class_is_instance_prefix_admits(info);
        // JIT round 20 wave 19, lane zAssign: the `Class.isAssignableFrom`
        // prefix (`try_emit_ir_class_is_assignable_prefix`).
        let class_is_assignable = self.class_is_assignable_prefix_admits(info);
        class_is_instance
            || class_is_assignable
            || vh_const
            || box_value_of
            || hash_equals
            || array_list
            || get_class
            || unsafe_access
            || string_search
            || identity_hash
            || current_thread
    }

    /// hga: the planned clears of the `Op::Call` being lowered, held from its
    /// first byte to the end of its inline prefixes, then emitted there --
    /// at the head of the call path, ahead of its safepoint map and its
    /// argument staging. Every decline edge of a prefix lands on that point,
    /// and no prefix's hit path contains a GC point (they load, compare,
    /// bump a TLAB and store the result home; none calls out), so each GC
    /// point the call reaches still finds the planned words zero, while a
    /// prefix hit skips the stores. The planner knows the hit path does not
    /// zero ([`Self::call_site_may_take_inline_prefix`]).
    fn emit_pending_call_clears(&mut self) {
        if std::mem::take(&mut self.pending_arg_stage_clears) {
            self.emit_dead_arg_stage_clears();
        }
        if let Some(offs) = self.pending_call_clears.take() {
            for off in offs {
                self.emit_zero_frame_slot(off);
            }
        }
    }

    /// gci i3/ir (opt-in `CRATONVM_JIT_IR_REF_PARAM_HOME_ZERO`; the section
    /// above [`ref_param_home_zero_candidates`]): right after reference
    /// parameter `id` was copied from its prologue word `[rbp -
    /// param_offset]` into its own home `[rbp - slot]`, zero the prologue
    /// word, so the parameter's only frame copy is the coloured one that the
    /// dead-home clears and the liveness claim already govern.
    ///
    /// Declines (writes nothing) for a node the plan did not admit, a copy
    /// that IS the prologue word, a copy whose store was dropped (the
    /// register is then the value's only location and nothing else would
    /// hold it in the frame), and the self-locking body's receiver (its
    /// exceptional exits release the monitor from that word). `MOV qword
    /// [rbp - off], 0`: no register, no flag, so a carry out of this node is
    /// undisturbed.
    fn zero_ref_param_home_after_copy(&mut self, id: NodeId, slot: i32, param_offset: i32) {
        if self.ref_param_home_zero.binary_search(&id).is_err() {
            return;
        }
        if slot <= 0
            || slot == param_offset
            || param_offset <= 0
            || param_offset >= self.first_spill
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            || self.self_lock_obj_home() == Some(param_offset)
        {
            return;
        }
        self.emit_zero_frame_slot(param_offset);
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!(
                "[ir-slots] ref param home zeroed after its copy: n{id} off={param_offset} copy={slot}"
            );
        }
    }

    /// gci i5/ir (`CRATONVM_JIT_IR_REF_PARAM_HOME_ZERO_LAZY`, opt-in; the
    /// section above [`ir_ref_param_home_zero_lazy_enabled`]): after
    /// [`Self::plan_dead_home_clears`] and the candidate plan, move each
    /// candidate's prologue-word zeroing into the planned first-byte clears of
    /// its own colour, and drop it from [`Self::ref_param_home_zero`] (no
    /// store after the copy). A candidate the rule cannot place keeps the
    /// eager store. Declines, as the eager store does, a copy that is the
    /// prologue word, a dropped home and the self-locking receiver's word;
    /// and needs a complete plan and a colour no other node shares.
    fn plan_lazy_ref_param_home_zero(&mut self) {
        if self.ref_param_home_zero.is_empty() || !self.dead_home_clears_complete {
            return;
        }
        let graph = self.graph;
        let schedule = self.schedule;
        let slot_plan = self.slot_plan;
        let first_spill = self.first_spill;
        let spill_cap_off = self.spill_cap_off;
        let self_lock_home = self.self_lock_obj_home();
        let nb = schedule.blocks.len();
        let mut params: Vec<(NodeId, i32, i32, usize, usize)> = Vec::new();
        for &id in &self.ref_param_home_zero {
            let Some(Op::Param(idx)) = graph.nodes.get(id as usize).map(|n| &n.op) else {
                continue;
            };
            let param_off = ((*idx as i32) + 1) * 8;
            let Some(Some(colour)) = slot_plan.node_color.get(id as usize).copied() else {
                continue;
            };
            if slot_plan
                .node_color
                .iter()
                .filter(|&&k| k == Some(colour))
                .count()
                != 1
            {
                continue;
            }
            let Some(home_off) = i32::try_from(u64::from(colour).saturating_mul(8))
                .ok()
                .and_then(|delta| first_spill.checked_add(delta))
                .filter(|&off| off > 0 && off <= spill_cap_off)
            else {
                continue;
            };
            if param_off <= 0
                || param_off >= first_spill
                || home_off == param_off
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
                || self_lock_home == Some(param_off)
            {
                continue;
            }
            let Some(block) = schedule
                .node_to_block
                .get(id as usize)
                .copied()
                .filter(|&b| b < nb)
            else {
                continue;
            };
            let Some(pos) = slot_plan.pos_of.get(id as usize).copied().flatten() else {
                continue;
            };
            params.push((id, param_off, home_off, block, pos));
        }
        let (adds, lazy) = lazy_ref_param_home_zero_plan(
            &params,
            &self.dead_home_clears,
            |site| {
                let b = schedule
                    .node_to_block
                    .get(site as usize)
                    .copied()
                    .filter(|&b| b < nb)?;
                let p = slot_plan.pos_of.get(site as usize).copied().flatten()?;
                Some((b, p))
            },
            |a, b| schedule.dom.dominates(a, b),
        );
        let dbg = cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS");
        for &(site, off) in &adds {
            if let Some(offs) = self.dead_home_clears.get_mut(&site) {
                offs.push(off);
                offs.sort_unstable();
                offs.dedup();
            }
            if dbg {
                eprintln!("[ir-slots] ref param home zero lazy: off={off} at n{site}");
            }
        }
        if dbg {
            eprintln!(
                "[ir-slots] ref param home zero lazy plan: lazy={lazy:?} sites={}",
                adds.len()
            );
        }
        self.ref_param_home_zero
            .retain(|id| lazy.binary_search(id).is_err());
    }

    /// JIT round 20 wave 17, lane gcDead (I-9): is `id` an allocation node
    /// armed as a dead-home site right now? Its clears are then held (like a
    /// prefixed call's) for the allocation arm to place on its slow path.
    fn alloc_site_armed(&self, id: NodeId) -> bool {
        self.dead_ref_clear_site
            .is_some_and(|(_, _, site)| site == id)
            && self
                .graph
                .nodes
                .get(id as usize)
                .is_some_and(|n| matches!(n.op, Op::New { .. } | Op::NewArray { .. }))
    }

    /// JIT round 20 wave 17, lane gcDead (I-9): an allocation route whose
    /// runtime helper call this arm cannot reach separately (it sits inside
    /// a fast-path emitter that also emits the stub) gives up the site
    /// instead: the held clears are dropped AND the site is disarmed before
    /// its map, so that map makes no liveness claim (`precise_liveness_claim`)
    /// and no dense clear -- byte for byte the map it had before I-9. A claim
    /// without the zeroing would leave a dead home out of the precise roots
    /// while it still holds a reference, which a later, unarmed map would
    /// publish after a moving collection had left it stale. Sound because the
    /// stale-set union never counts an allocation site as cleaning.
    fn disarm_alloc_site(&mut self, id: NodeId) {
        if self.alloc_site_armed(id) {
            self.pending_call_clears = None;
            self.pending_arg_stage_clears = false;
            self.dead_ref_clear_site = None;
        }
    }

    /// JIT round 20 wave 17, lane gcDead (I-9): the primitive-array bump of
    /// an armed `Op::NewArray`, with its slow path landed HERE -- the held
    /// dead-home clears, then the same stub `emit_inline_tlab_newarray_ir`
    /// would have emitted there (same target, atype immediate, length word
    /// and frame record), so the bump path carries no store. Returns the
    /// stub's return address, or `None` having emitted nothing when the bump
    /// declines (the caller then emits the clears and the stub alone).
    fn emit_newarray_bump_with_slow_path_clears(
        &mut self,
        plan: &crate::runtime_lowering::InlineTlabArrayPlan,
        target: usize,
        immediate: u32,
        length_slot: i32,
    ) -> Option<usize> {
        let mut slow: Vec<usize> = Vec::new();
        if !crate::runtime_lowering::emit_inline_tlab_newarray_fast_path_ir(
            &mut self.buf,
            plan,
            target,
            self.frame_record,
            &mut slow,
        ) {
            return None;
        }
        let done = self.emit_jmp_rel32();
        for patch in slow {
            self.patch_rel32_to_here(patch);
        }
        self.emit_pending_call_clears();
        let slow_return = crate::runtime_lowering::emit_new_array_stub(
            &mut self.buf,
            self.context_slot_off,
            target,
            immediate,
            length_slot,
            self.frame_record,
        );
        self.patch_rel32_to_here(done);
        Some(slow_return)
    }

    /// gen r5w2/oomjit6 (`CRATONVM_JIT_IR_CLEAR_DEAD_REF_SLOTS`, default ON since gcf vf5): at the
    /// START of an armed `Op::Call` node, before any of its bytes, zero every
    /// word of the Java-argument staging region.
    ///
    /// The region sits in the frame's callee-saved band, which the band scan
    /// always reads, and nothing clears it: the arguments the LAST dispatched
    /// call staged there (the `WeakReference` constructor's referent, a
    /// `List.add`'s receiver) stay conservative roots until a later call stages
    /// over the same index -- and a direct call to a compiled callee stages
    /// nothing on its hot path (`CRATONVM_JIT_IR_COLD_ARG_STAGE`). Every writer
    /// of the region is a call lowering whose readers (the dispatch helper it
    /// calls, and that node's own cold paths) run inside the same node, so at a
    /// node boundary nothing staged there is read again before it is written.
    /// Each staged reference is also an input of its call, so it is in its home
    /// word while the call runs. Writes no register and no flag, so a carry into
    /// this node is undisturbed.
    fn emit_dead_arg_stage_clears(&mut self) {
        for i in 0..self.args_stage_words {
            let Some(off) = i32::try_from(i)
                .ok()
                .and_then(|i| i.checked_mul(8))
                .and_then(|delta| self.args_stage_top_off.checked_sub(delta))
            else {
                break;
            };
            if off <= 0 {
                break;
            }
            self.emit_zero_frame_slot(off);
        }
    }

    /// gen r5w5/oomjit9: fill [`Self::dead_home_clears`] -- see the section
    /// above [`ir_dead_home_clears_enabled`]. Runs once, before emission, off
    /// the slot plan and the schedule; leaves the map empty (zero nothing)
    /// when the dead-reference facts are absent or the union over the block
    /// graph does not converge. Returns whether the complete plan and clean
    /// entry premise also make dense home stores redundant. Argument staging
    /// retains the dense clear: its conservative primitive words are outside
    /// this reference-only stale-set proof.
    fn plan_dead_home_clears(&mut self) -> bool {
        self.dead_home_clears.clear();
        let schedule = self.schedule;
        let graph = self.graph;
        let slot_plan = self.slot_plan;
        let nb = schedule.blocks.len();
        let (words, ref_colours) = match self.dead_ref_clear.as_ref() {
            Some(plan) => (plan.words, plan.ref_colours.clone()),
            None => return false,
        };
        let mut ref_bits = vec![0u64; words];
        for &c in &ref_colours {
            bits_insert(&mut ref_bits, c as usize);
        }
        let stage_n = self.args_stage_words;
        let stage_words = stage_n.div_ceil(64).max(1);

        // 1. The dead colours at every armed site.
        let mut site_dead: HashMap<NodeId, Vec<u64>> = HashMap::new();
        for block in &schedule.blocks {
            for &nid in &block.nodes {
                let Some((pos, bci, site)) = self.dead_ref_clear_site_for(nid) else {
                    continue;
                };
                let dead = match self.dead_ref_clear.as_mut() {
                    Some(plan) => plan.dead_colours_at(pos, bci, site),
                    None => return false,
                };
                let mut bits = vec![0u64; words];
                for c in dead {
                    bits_insert(&mut bits, c as usize);
                }
                site_dead.insert(nid, bits);
            }
        }
        if site_dead.is_empty() {
            return false;
        }

        // gen r5w6/oomjit10: the clearable colours of each block's `Ref` phis
        // (non-empty only when the keep set is precise, which is what admits
        // phi colours into `ref_colours`). Their edge copies write them at
        // the END of every predecessor, which the walk below records as a
        // `Def` there.
        let mut phi_colours_at: Vec<Vec<usize>> = vec![Vec::new(); nb];
        {
            let block_of_merge: HashMap<NodeId, usize> = schedule
                .blocks
                .iter()
                .enumerate()
                .map(|(b, blk)| (blk.ctrl, b))
                .collect();
            for (id, node) in graph.nodes.iter().enumerate() {
                if !matches!(node.op, Op::Phi) || node.ty != IrType::Ref {
                    continue;
                }
                let Some(&b) = node.inputs.first().and_then(|m| block_of_merge.get(m)) else {
                    continue;
                };
                if let Some(Some(c)) = slot_plan.node_color.get(id).copied() {
                    if bits_contains(&ref_bits, c as usize) {
                        phi_colours_at[b].push(c as usize);
                    }
                }
            }
        }
        // 2. The block graph as the stale-set union sees it: per block, in
        //    order, every armed site, every `Ref` argument a call stages and
        //    every definition of a clearable colour.
        let mut blocks: Vec<StaleBlock> = schedule
            .blocks
            .iter()
            .map(|block| {
                let mut events = Vec::new();
                for nid in block.nodes.iter().copied().chain(block.terminator) {
                    let Some(node) = graph.nodes.get(nid as usize) else {
                        continue;
                    };
                    if let Some(dead) = site_dead.remove(&nid) {
                        // JIT round 20 wave 17, lane gcDead (I-9): an
                        // allocation site zeroes on its slow path only (or
                        // not at all), so it never cleans for what follows.
                        let cleans = matches!(node.op, Op::Call { .. })
                            && !self.call_site_may_take_inline_prefix(nid);
                        events.push(StaleEvent::Site {
                            node: nid,
                            dead,
                            cleans,
                        });
                    }
                    if matches!(node.op, Op::Call { .. }) {
                        let num_args = node.inputs.len().saturating_sub(2);
                        for i in 0..num_args.min(stage_n) {
                            let is_ref = node
                                .inputs
                                .get(2 + i)
                                .and_then(|&a| graph.nodes.get(a as usize))
                                .is_some_and(|a| a.ty == IrType::Ref);
                            if is_ref {
                                events.push(StaleEvent::Staged(i));
                            }
                        }
                    }
                    if let Some(Some(c)) = slot_plan.node_color.get(nid as usize).copied() {
                        if bits_contains(&ref_bits, c as usize) {
                            events.push(StaleEvent::Def(c as usize));
                        }
                    }
                }
                // gen r5w6/oomjit10: the edge copies into each successor's
                // phis, after everything else in this block.
                for &s in &block.successors {
                    if let Some(cols) = phi_colours_at.get(s) {
                        events.extend(cols.iter().map(|&c| StaleEvent::Def(c)));
                    }
                }
                StaleBlock {
                    events,
                    predecessors: block.predecessors.clone(),
                }
            })
            .collect();
        // The entry starts clean: the prologue (and the OSR stub, which enters
        // past it) zeroes every reference home it does not write
        // (`zero_ref_value_slots`); where that is switched off, a home's
        // pre-frame word is simply left alone, as before.
        // gci i5/ir (i4 open item O2): the block the method ENTERS, found by
        // its head (`scheduled_entry_block`); the `node_to_block[graph.entry]`
        // lookup was `usize::MAX` on every real schedule and only the `0`
        // fallback made it right.
        let entry_block = scheduled_entry_block(graph, schedule).unwrap_or(0);
        // gen r5w6/oomjit10: ...except the phis of a loop header (a block
        // entered from a later one), which an OSR entry stub seeds instead of
        // zeroing: they start stale, so a seeded value that dies is zeroed at
        // the first site that finds it dead.
        let mut seeded: Vec<usize> = Vec::new();
        for (b, block) in schedule.blocks.iter().enumerate() {
            if block.predecessors.iter().any(|&p| p >= b) {
                if let Some(cols) = phi_colours_at.get(b) {
                    seeded.extend_from_slice(cols);
                }
            }
        }
        if let Some(entry) = blocks.get_mut(entry_block) {
            let mut events: Vec<StaleEvent> = seeded.into_iter().map(StaleEvent::Def).collect();
            events.append(&mut entry.events);
            entry.events = events;
        }

        // 3. The forward union, and each site's stale sets at its first byte.
        let Some(at_sites) = stale_sets_at_sites(&blocks, entry_block, &ref_bits, stage_words)
        else {
            // JIT round 20 wave 17, lane gcDead (I-9): no plan, so no
            // allocation site is armed -- its claim would have no zeroing
            // behind it (see `disarm_alloc_site`).
            self.alloc_dead_home_clear = false;
            return false;
        };
        // JIT round 20 wave 17, lane gcDead: the zeroing the liveness claim
        // relies on is now in place at every armed site.
        self.dead_home_plan_converged = true;

        // 4. The words each site zeroes: the dead homes stale at it, and the
        //    stale staging words. `planned_slot_off`'s arithmetic for a home
        //    (inside the spill band only); a staging word only strictly above
        //    the spill band, so this can never write a colour's home through
        //    the staging arithmetic.
        let first_spill = self.first_spill;
        let spill_cap_off = self.spill_cap_off;
        let args_stage_top_off = self.args_stage_top_off;
        // gcd d5/u: the arithmetic below, so a census `off=` names its colour.
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!(
                "[ir-slots] homes: colour c at [rbp - ({first_spill} + 8c)], spill cap {}, staging top {} x {}",
                spill_cap_off, args_stage_top_off, stage_n
            );
        }
        let home_off = |colour: u32| -> Option<i32> {
            let off = i32::try_from(u64::from(colour).saturating_mul(8))
                .ok()
                .and_then(|delta| first_spill.checked_add(delta))?;
            (off > 0 && off >= first_spill && off <= spill_cap_off).then_some(off)
        };
        let stage_off = |i: usize| -> Option<i32> {
            let off = i32::try_from(i)
                .ok()
                .and_then(|i| i.checked_mul(8))
                .and_then(|delta| args_stage_top_off.checked_sub(delta))?;
            (off > 0 && off > spill_cap_off).then_some(off)
        };
        let mut sites: HashMap<NodeId, Vec<i32>> = HashMap::new();
        for (nid, homes, stage) in at_sites {
            let mut offs: Vec<i32> = ref_colours
                .iter()
                .copied()
                .filter(|&c| bits_contains(&homes, c as usize))
                .filter_map(home_off)
                .collect();
            offs.extend(
                (0..stage_n)
                    .filter(|&i| bits_contains(&stage, i))
                    .filter_map(stage_off),
            );
            if !offs.is_empty() {
                offs.sort_unstable();
                offs.dedup();
                sites.insert(nid, offs);
            }
        }
        if !sites.is_empty() && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            let mut listed: Vec<(&NodeId, &Vec<i32>)> = sites.iter().collect();
            listed.sort_unstable_by_key(|&(nid, _)| *nid);
            for (nid, offs) in listed {
                eprintln!("[ir-slots] dead-home clears at n{nid}: offsets {offs:?}");
            }
        }
        self.dead_home_clears = sites;
        // The stale union starts clean. Only replace the dense store form
        // when both normal and OSR entries establish that premise; otherwise
        // retain the old stores even though the sparse retention fix runs.
        ir_zero_fresh_frames_enabled()
            && self.reloc_emit_on
            && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_ZERO_REF_SLOTS")
    }

    /// gen r5w2/oomjit6 (`CRATONVM_JIT_IR_CLEAR_DEAD_REF_SLOTS`, default ON since gcf vf5): at a
    /// GC point of an armed call site, `MOV qword [rbp - off], 0` for every
    /// reference home that is dead there (see the section above
    /// [`DeadRefSlotClear`]) and that the band scan would read at this
    /// safepoint (below `live_hi`). Writes no register and no flag, so it may
    /// sit anywhere a safepoint map may.
    fn emit_dead_ref_slot_clears(&mut self, live_hi: i32) {
        // gen r5w3/live7: the facts may be built for the store-free claim
        // alone (`CRATONVM_JIT_PRECISE_FRAME_LIVENESS`), which writes nothing.
        // The incremental plan clears a dead colour at the first byte of
        // this call whenever any path may have written it since its previous
        // clear. Its def/phi-edge events cover every reference-home writer;
        // nothing in this call rewrites a dead home before this GC point.
        // With initialized entries and convergence, another dense clear here
        // can only store zero over zero. Retain it when that proof is absent.
        // gci i5/ir: an armed back-edge poll stores whatever the plan proved:
        // no planned first-byte clear runs before a poll.
        if !self.dead_ref_clear_stores
            || (self.dead_home_clears_complete && !self.poll_site_dense)
        {
            return;
        }
        let Some((pos, bci, site)) = self.dead_ref_clear_site else {
            return;
        };
        let dead = match self.dead_ref_clear.as_mut() {
            Some(plan) => plan.dead_colours_at(pos, bci, site),
            None => return,
        };
        let mut cleared: Vec<i32> = Vec::new();
        for colour in dead {
            let Some(off) = i32::try_from(u64::from(colour).saturating_mul(8))
                .ok()
                .and_then(|delta| self.first_spill.checked_add(delta))
            else {
                continue;
            };
            // Inside the spill band, and below the scan's cursor for this map:
            // a word above it is not BAND-scanned, so zeroing it buys nothing
            // -- unless the body publishes a frame block. The block names
            // every planned home for the whole activation, above the cursor
            // too (a home whose node comes later in linear order can have been
            // written earlier in time, e.g. by a loop body laid out after the
            // call), and the collector roots each named word through the
            // shadow stack whatever the cursor says (gen r5w3/live7 review).
            // Dead is dead on either side of the cursor: the rule above is
            // about live ranges and snapshots, not about the watermark.
            if off < self.first_spill
                || off > self.spill_cap_off
                || (off >= live_hi && self.frame_block.is_empty())
            {
                continue;
            }
            self.emit_zero_frame_slot(off);
            cleared.push(off);
        }
        if !cleared.is_empty() && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!("[ir-slots] dead-ref clear at pos={pos} bci={bci}: offsets {cleared:?}");
        }
    }

    /// gen r5w3/live7 (`CRATONVM_JIT_PRECISE_FRAME_LIVENESS`): the store-free
    /// form of [`Self::emit_dead_ref_slot_clears`] and
    /// [`Self::emit_dead_arg_stage_clears`]. At a GC point of an armed call
    /// site, returns `(covered, dead)`, both sorted and distinct, `dead` a
    /// subset of `covered`:
    ///
    ///   * **covered** -- the home word of every clearable reference colour
    ///     (`DeadRefSlotClear::ref_colours`: holds a `Ref`, never a phi) that
    ///     lies inside the spill band, and every word of the argument-staging
    ///     region;
    ///   * **dead** -- the homes of the colours `dead_colours_at` calls dead at
    ///     this call (no live range covers its position and no snapshot at a
    ///     bci reachable from it names the colour: the rule the store form
    ///     zeroes by, argued in the section above [`DeadRefSlotClear`]), and
    ///     the staging words at index `>= dead_ref_clear_site_args`. This call's
    ///     lowering never writes those (every staging store is `arg[i]` for
    ///     `i < num_args <= inputs.len() - 2`), so they hold an EARLIER node's
    ///     arguments, and the store form zeroes the whole region at this node's
    ///     first byte on the argument that nothing an earlier node staged is
    ///     read again. The words this call does stage stay covered-and-live:
    ///     one may be the argument's only home (`home_dropped`), and none is
    ///     rewritten by a relocation, so they must keep pinning.
    ///
    /// `None` -- no claim, nothing skipped -- off the flag, away from an armed
    /// site, or when nothing here is dead.
    fn precise_liveness_claim(&mut self) -> Option<(Vec<i16>, Vec<i16>)> {
        if !self.frame_liveness_on {
            return None;
        }
        // JIT round 20 wave 17, lane gcDead (correctness, unconditional): a
        // home this claim drops is not relocated, and every LATER unarmed map
        // (a poll, a monitor enter, a helper-backed op) publishes every
        // defined node's home again. So a dropped home must be zero at the
        // collection, which only the converged dead-home plan guarantees --
        // not under `CRATONVM_JIT_IR_DEAD_HOME_CLEARS=0`, nor when its
        // stale-set union did not converge. No claim then (the old map).
        if !self.dead_home_plan_converged {
            return None;
        }
        let (pos, bci, site) = self.dead_ref_clear_site?;
        let first_spill = self.first_spill;
        let spill_cap_off = self.spill_cap_off;
        // `planned_slot_off`'s arithmetic, as `emit_dead_ref_slot_clears` does
        // it; an offset outside the spill band is simply not covered.
        let home_off = |colour: u32| -> Option<i16> {
            let off = i32::try_from(u64::from(colour).saturating_mul(8))
                .ok()
                .and_then(|delta| first_spill.checked_add(delta))?;
            if off <= 0 || off < first_spill || off > spill_cap_off {
                return None;
            }
            i16::try_from(off).ok()
        };
        let plan = self.dead_ref_clear.as_mut()?;
        let dead_colours = plan.dead_colours_at(pos, bci, site);
        let mut covered: Vec<i16> = plan
            .ref_colours
            .iter()
            .copied()
            .filter_map(home_off)
            .collect();
        let mut dead: Vec<i16> = dead_colours.into_iter().filter_map(home_off).collect();
        let (stage_covered, stage_dead) = staging_liveness_words(
            self.args_stage_top_off,
            self.args_stage_words,
            spill_cap_off,
            self.dead_ref_clear_site_args,
        );
        covered.extend(stage_covered);
        dead.extend(stage_dead);
        if dead.is_empty() {
            return None;
        }
        covered.sort_unstable();
        covered.dedup();
        dead.sort_unstable();
        dead.dedup();
        // `dead` is built from `covered`'s own sources, so this only guards a
        // future edit: a dead word nothing covers would be a claim the table
        // cannot represent, and the collector must not act on it.
        dead.retain(|off| covered.binary_search(off).is_ok());
        Some((covered, dead))
    }

    /// gen r5w3/live7: append safepoint `id`'s record to the body's liveness
    /// table. Every record of one body speaks for the SAME covered set (the
    /// clearable colours and the staging region are per-body facts); a record
    /// whose covered set differed would make the earlier records' `live`
    /// lists wrong for the union, so that poisons the table instead
    /// (`frame_liveness_poisoned`, read at finalize: no claim at all).
    fn record_frame_liveness(&mut self, id: u32, covered: Vec<i16>, dead: &[i16]) {
        if self.frame_liveness_covered.is_empty() {
            self.frame_liveness_covered = covered;
        } else if self.frame_liveness_covered != covered {
            self.frame_liveness_poisoned = true;
            return;
        }
        let live: Vec<i16> = self
            .frame_liveness_covered
            .iter()
            .copied()
            .filter(|off| dead.binary_search(off).is_err())
            .collect();
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!("[ir-slots] liveness claim at sp={id}: dead offsets {dead:?}");
        }
        self.frame_liveness_records
            .push(crate::SafepointFrameLiveness {
                sp_id: id,
                live,
                complete: true,
            });
    }

    /// gen r5w3/live7: the body's finished liveness table, or the empty table
    /// (no claim) when the flag was off, a record was poisoned, or any
    /// safepoint id store was deferred -- a deferred store leaves an older id
    /// in the frame word, and a claim keyed by that id would then describe a
    /// different program point.
    fn take_frame_liveness(&mut self) -> crate::FrameLivenessTable {
        let covered = std::mem::take(&mut self.frame_liveness_covered);
        let mut records = std::mem::take(&mut self.frame_liveness_records);
        if !self.frame_liveness_on
            || self.frame_liveness_poisoned
            || self.self_call_id_stores_deferred > 0
            || covered.is_empty()
            || records.is_empty()
        {
            return crate::FrameLivenessTable::default();
        }
        // Ascending already (ids come from a counter); sorted rather than
        // asserted, as `sp_id_bcis` is, because `proves_dead` binary-searches.
        records.sort_by_key(|r| r.sp_id);
        crate::FrameLivenessTable { covered, records }
    }

    /// Emit the safepoint-id store and record the map for a GC-capable point.
    ///
    /// Call immediately BEFORE the call or allocation that can reach a
    /// collection, and before allocating the result slot of that node — the
    /// result slot is not written until the call returns, so publishing it as a
    /// live reference beforehand would hand the collector uninitialised memory.
    ///
    /// This ALWAYS stores an id and ALWAYS records a map, even when coverage
    /// cannot be established. Skipping either would leave the slot holding the
    /// id of an *earlier* safepoint, and the collector would then match a map
    /// describing a different program point and relocate against it. A map with
    /// `moving_young_coverage_complete: false` is the fail-closed answer: the
    /// verifier finds the entry, sees the flag, and diverts to the non-moving
    /// sweep for that cycle.
    fn emit_safepoint_map(&mut self, live_hi: i32) {
        // gen r5w2/oomjit6 (opt-in): BEFORE the map and its shadow push, so a
        // cleared word is published (and copied back after the call) as the
        // null it now holds. Inert unless an armed site (an `Op::Call`, or under
        // `CRATONVM_JIT_IR_ALLOC_SITE_CLEARS` an allocation) armed it.
        self.emit_dead_ref_slot_clears(live_hi);
        if self.sp_id_slot_off <= 0 || !self.reloc_emit_on {
            return;
        }
        // `live_ref_slots` returns an empty vector for two different reasons —
        // a genuinely oop-free safepoint, and a slot it could not describe.
        // Distinguish them, because the first is complete coverage and the
        // second is a refusal.
        let mut coverable = true;
        // Reference PARAMETER homes come first, because they are the one class
        // of live oop that is not a node result and so cannot be found by the
        // scan below. The prologue stores each incoming argument to
        // `[rbp - (idx+1)*8]` and that word keeps holding the reference for the
        // whole frame; `Op::Param`'s own spill slot is a COPY of it.
        //
        // Omitting them is not a partial claim, it is a false one: the band
        // scan is conservative, so a single unpublished young word anywhere in
        // the live band refuses the whole cycle. Measured on `IrEscapeProbe`
        // (`CRATONVM_MOVING_YOUNG_BAND_DBG`), the two rejected words were
        // `off=8 region=java-local` and `off=56 region=operand-spill` holding
        // the SAME reference — the parameter home and its node copy.
        let mut slots: Vec<i16> = self.ref_param_homes.clone();
        // Membership for the dedup below, one bit per frame byte offset
        // (round 11 wave 3, `r11-irlower-safepoint-map-compile-cost`): the
        // `Vec::contains` it replaces made every GC point O(R^2) in the number
        // of reference slots. An offset past the bitset (a frame that grew
        // after `frame_size` was read) falls back to the scan, so the published
        // list -- first occurrence, ascending node id -- is unchanged.
        let mut seen: Vec<u64> = std::mem::take(&mut self.sp_map_seen);
        seen.clear();
        seen.resize((usize::try_from(self.frame_size).unwrap_or(0) >> 6) + 2, 0);
        for &s in &slots {
            if let Ok(i) = usize::try_from(s) {
                if let Some(w) = seen.get_mut(i >> 6) {
                    *w |= 1u64 << (i & 63);
                }
            }
        }
        // Only the `Ref` nodes, in ascending id order (`ref_node_ids`): the
        // same slots in the same order as a walk over every node.
        for &id in &self.ref_node_ids {
            if !self.defined_nodes.get(id).copied().unwrap_or(false) {
                continue;
            }
            // `defined_nodes[id]` implies an allocated slot, so `None` here is
            // an internal inconsistency, not a `Ref` without a home. Treat it
            // exactly like an unencodable offset: fail closed, publish no map.
            let off = match self.node_slot.get(id).copied().flatten() {
                Some(off) => off.get() as i32,
                None => {
                    coverable = false;
                    break;
                }
            };
            if off > i16::MAX as i32 {
                coverable = false;
                break;
            }
            let off = off as i16;
            let idx = usize::try_from(off).unwrap_or(usize::MAX);
            let fresh = match seen.get_mut(idx >> 6) {
                Some(w) => {
                    let bit = 1u64 << (idx & 63);
                    let fresh = *w & bit == 0;
                    *w |= bit;
                    fresh
                }
                None => !slots.contains(&off),
            };
            if fresh {
                slots.push(off);
            }
        }
        self.sp_map_seen = seen;
        // gen r5w3/live7 (`CRATONVM_JIT_PRECISE_FRAME_LIVENESS`): a home this
        // call site proves dead is neither named by the map nor pushed to the
        // shadow stack, so the precise channels stop rooting it, and the
        // record below lets the band scan skip its word too. The frame block
        // is off under the flag (`plan_frame_block`): a block publishes every
        // home for the whole activation, dead or not. Parameter homes are
        // never in `dead` (they are not colours).
        let liveness_claim = self.precise_liveness_claim();
        if let Some((_, dead)) = &liveness_claim {
            slots.retain(|s| dead.binary_search(s).is_err());
        }
        if !coverable {
            slots.clear();
        }

        let id = self.next_sp_id;
        self.next_sp_id = self.next_sp_id.wrapping_add(1);
        // JIT round 19 proposal wave 8, lane gc8 (GC719-1): the frame words of
        // the `synchronized` blocks this safepoint holds, for the VM's
        // locked-monitor depths. Metadata only; nothing is emitted.
        if let Some(homes) = self.safepoint_monitor_homes(&slots) {
            self.ir_monitor_homes.push((id, homes));
        }
        // The id->bci translation a stack walk needs. `resume_bci` is the same
        // normalisation the throw-site and deopt paths apply: inside an
        // IR-spliced callee `cur_bci` is a pc in the COMBINED buffer, which
        // names no instruction in this method's own `Code`, so it is mapped
        // back to the enclosing invoke. `u32::try_from` cannot fail for a
        // spec-legal bci; a value that somehow exceeds it records nothing,
        // which reports no line rather than a wrong one.
        if let Ok(bci) = u32::try_from(self.resume_bci(self.cur_bci)) {
            self.sp_id_bcis.push((id, bci));
        }
        // Round 14 wave 2 (lane trace): the chain at THIS id, the innermost
        // frame's exact inline-chain key. `cur_node_pc`, never `cur_bci`, as
        // `note_inline_frame_return_site_at`: a pc-less node records an empty
        // chain (no frame rather than a wrong one).
        // Wave 58 (lane L2): a synchronized splice's enter names its callee.
        let chain_pc = self.sp_chain_pc_override.take().or(self.cur_node_pc);
        if !self.inline_frame_sites.is_empty() && crate::x64::inline_frame_map_enabled() {
            let chain: Vec<crate::x64::InlineFrameLevel> = match chain_pc {
                Some(node_pc) => self
                    .inline_frame_sites
                    .chain_at(node_pc)
                    .into_iter()
                    .map(|l| crate::x64::InlineFrameLevel {
                        label: l.method_key.into(),
                        bci: l.bci,
                        class_id: l.class_id,
                        // Wave 122 (L2): the optimizing tier stamps no bit.
                        hidden: None,
                    })
                    .collect(),
                None => Vec::new(),
            };
            self.inline_frame_sp_id_rows.push((id, chain));
        }
        // gen r5w3/live7: the claim is keyed by the id the frame word will
        // hold while this safepoint is active. A deferred id store leaves an
        // OLDER id there on the hot path, so such a site records nothing (and
        // the finalize drops the whole table if any store was deferred).
        if let Some((covered, dead)) = liveness_claim {
            if !self.defer_next_sp_id_store {
                self.record_frame_liveness(id, covered, &dead);
            }
        }
        // MOV qword [rbp - sp_id_slot_off], imm32 (sign-extended; ids are small)
        //
        // Round 11 wave 15 (lane fib): except for a direct self-call in a
        // reference-free body, whose id `emit_self_recursive_call` stores on
        // its cold paths instead (`deferred_self_call_sp_id`). The map and the
        // id->bci row above are recorded either way.
        if self.defer_next_sp_id_store {
            self.deferred_self_call_sp_id = Some(id);
            self.self_call_id_stores_deferred += 1;
        } else {
            self.emit_sp_id_store(id);
        }

        // Publish, and only then claim coverage. `emit_shadow_push` returns
        // false when the thread helper is unwired or there is nothing to
        // publish; an oop-free safepoint is still complete coverage, so the
        // claim below requires `coverable` AND (published OR nothing to
        // publish).
        //
        // With a frame block the whole block is published instead — once per
        // activation, as indirect entries the collector rewrites THROUGH — and
        // there is nothing to copy back after the call, so `pending_shadow`
        // stays empty and every reload / copy-back site below emits nothing.
        // The block names every word a map can name, because both come from
        // `planned_slot_off`; a map that named anything else would be a word
        // this frame publishes nowhere, so that refuses the body rather than
        // mixing the two protocols (they share the saved-base word).
        let block_mode = !self.frame_block.is_empty();
        if block_mode
            && !slots
                .iter()
                .all(|s| self.frame_block.binary_search(s).is_ok())
        {
            self.latch_bailout(Bailout::new(BailoutReason::Internal(
                "ir_lower: a safepoint map names a reference word outside the frame block",
            )));
        }
        let published = if !block_mode {
            self.emit_shadow_push(&slots)
        } else if slots.is_empty() {
            false
        } else {
            self.emit_frame_block_ensure()
        };
        if self.dbg_ir_reloc_on {
            eprintln!(
                "[ir-reloc] safepoint id={id} slots={slots:?} coverable={coverable} \
                 published={published} frame_block={:?} thread_helper={:#x} thread_slot={} \
                 savebase={} ss_off={}",
                self.frame_block,
                self.get_current_thread,
                self.shadow_thread_slot_off,
                self.shadow_savebase_slot_off,
                self.shadow_off_in_thread,
            );
        }
        self.shadow_pushed_any |= published;
        self.pending_shadow = if published && !block_mode {
            slots.clone()
        } else {
            Vec::new()
        };
        let complete = coverable && (published || slots.is_empty());
        // §25.3's diagnostic count, the same quantity the single-pass backend
        // records (`x64/safepoint.rs`, `shadow_pushed_here`): how many slots
        // THIS safepoint's shadow push published. Diagnostic only — read by
        // `conservative_roots`' band report, never by a collector decision.
        let shadow_pushed = if published {
            u16::try_from(slots.len()).unwrap_or(u16::MAX)
        } else {
            0
        };

        self.oop_maps.push(super::OopMapEntry {
            // The relocation path matches on the id in the frame slot, not on
            // this, and nothing fills it: IR maps stay unanchored (so the deopt
            // verifier's oop-map lane in `lower_inner_attempt` skips them).
            // There is no `close_safepoint_map`, whatever older notes say.
            native_pc_offset: 0,
            bytecode_pc: id,
            frame_slot_offsets: slots,
            // The claim the collector acts on: the shadow stack HAS been
            // published with every live oop of this frame, so each can be
            // rewritten in place. Requires both halves — `coverable` (every
            // live `Ref` slot could be named) and `published` (the push was
            // actually emitted). Naming the slots alone is not enough:
            // `scan_oop_slots` yields `ObjectRef` values, which mark but cannot
            // be written back through.
            moving_young_coverage_complete: complete,
            // The IR tier stages its oops in frame slots rather than in a
            // blind register image, so it has no register claim to make.
            reg_oop_mask: None,
            live_frame_hi: live_hi,
            // The IR tier allocates frame slots; it does not home local `k` at
            // `[rbp - 8*(k+1)]`, so the locals-band oracle does not apply to
            // these frames and must not answer as if it did.
            local_oop_mask: None,
            num_locals: 0,
            inline_local_scopes: Vec::new(),
            // The IR tier has no java-locals band to speak for, but its slot
            // COLOURING is a proof about every spill slot it allocated: a
            // non-`Ref` colour never holds an object pointer, because
            // `assign_colors` never moves a colour between its two free lists.
            // Exact because `verify_slot_colouring` re-derives the no-aliasing
            // property rather than trusting it.
            //
            // The premise is `IrType::Ref`, which is the SAME premise this
            // function publishes roots on a few lines above. So the oracle
            // cannot be wrong here unless the map itself already is: a
            // non-`Ref` node holding a real object pointer would be an
            // unpublished root today, with or without this field. It is not an
            // independent check of that, and must not be read as one.
            non_oop_stack_slots: self.prim_slot_offsets.clone(),
            stack_marks_exact: true,
            // Round 9: this said "The IR tier emits no shadow push of its
            // own" and recorded 0, but `emit_shadow_push` above IS this tier's
            // push, so every IR map read as "pushed nothing" in the band report.
            shadow_pushed,
            // gcg g3/v: no single-pass blind image on this tier.
            spill_written: None,
        });
    }

    // ── Phi resolution (BUG FIX [jit-irlower #2]) ────────────────────────
    //
    // Previously `Op::Phi` only called `alloc_slot` with the comment
    // "predecessors will write it" — but no code ever emitted those writes,
    // so a phi read an uninitialised frame slot. We now perform a standard
    // edge-split parallel copy: before a predecessor block branches to a
    // merge/region successor, store each incoming phi-argument value into
    // the corresponding phi's slot.

    /// Reserve a frame slot for every `Op::Phi` up front.
    ///
    /// A forward branch can target a merge block whose phis have not yet
    /// been lowered, so the destination slots must exist before any edge
    /// copy is emitted. Phis are skipped by `lower_data_node`.
    ///
    /// Fallible: this is the first thing that can exhaust the frame, and a
    /// refusal here must reach `lower_inner` as a `FrameTooLarge` bailout
    /// rather than a panic.
    fn prealloc_phi_slots(&mut self) -> CompileResult<()> {
        for id in 0..self.graph.nodes.len() {
            if matches!(self.graph.nodes[id].op, Op::Phi) {
                self.alloc_slot_checked(id as NodeId)?;
            }
        }
        Ok(())
    }

    /// Resolve the block that produces control token `ctrl` by walking up
    /// control inputs until we reach a node that heads some block.
    ///
    /// Merge predecessor `k` records `self.ctrl` (the predecessor's live
    /// control node) as `merge.inputs[k]`; that token is either a block
    /// head directly (goto fall-through) or a `Proj` off an `If` (block
    /// head). Walking control inputs makes the mapping robust to either.
    ///
    /// Delegates to the free function [`ctrl_block_of`] so the slot planner,
    /// which must reproduce this exact edge attribution to see phi inputs as
    /// uses at the *predecessor's* terminator, cannot drift from the emitter.
    fn block_of_ctrl(&self, ctrl: NodeId) -> Option<usize> {
        ctrl_block_of(self.graph, self.schedule, ctrl)
    }

    /// Emit the parallel-copy stores for every phi at `succ_block` whose
    /// merge has `pred_block` as the source for that phi argument.
    ///
    /// Each copy loads the incoming SSA value (already spilled by the
    /// predecessor block, which is lowered before its terminator) into RAX
    /// and stores it into the phi's reserved slot.
    ///
    /// The copies are a PARALLEL assignment: every source is read as it was
    /// *before* any destination is written. They are therefore sequentialised
    /// by [`resolve_parallel_copy`] rather than emitted in gather order, and a
    /// cycle among them is broken through [`Lowerer::phi_copy_scratch_slot_off`].
    /// See the doc comment on the emission loop below for what was wrong before.
    ///
    /// Round 9 wave 6: every call site of this function is straight-line code
    /// of ONE edge, after the edge's back-edge poll, so it is also where the
    /// split plan's edge-resolution copies run -- after the phi copies, see
    /// [`Lowerer::ls_emit_edge_copies`].
    fn emit_phi_copies(&mut self, pred_block: usize, succ_block: usize) {
        self.emit_value_phi_copies(pred_block, succ_block);
        self.ls_emit_edge_copies(pred_block, succ_block);
    }

    /// The split plan's CFG-edge resolution for `pred_block -> succ_block`
    /// (round 9 wave 6; [`LsEdgeCopies`] states the design). Nothing unless
    /// `CRATONVM_JIT_IR_LS_EDGE_RESOLUTION` admitted a value with a copy here.
    ///
    /// # Why AFTER the phi copies, and why every copy is a home load
    ///
    /// The phi copies read their sources from registers and publish their phis
    /// into registers. Running the resolution first could overwrite a register
    /// a phi source is still to be read from; running it after can only be
    /// wrong if it READS something the phi copies wrote (it reads home words
    /// only, and a phi copy writes phi home words, the phi-copy scratch and
    /// registers) or WRITES a register a phi was just published into. Both are
    /// checked here per copy, against this edge's own phi copies, and either
    /// refuses the compile -- the planner's `held_by_other` test and the
    /// slot colouring both say neither can happen, so a hit is a model that has
    /// come apart, not a shape to emit.
    ///
    /// # Why the residency tables are NOT updated
    ///
    /// The code of `succ_block` was, or will be, emitted against the state the
    /// emitter carries out of `succ_block`'s LAYOUT predecessor, and these
    /// copies exist to make the machine match that state on this edge. The
    /// emitter's own tables after this point describe the next block in layout
    /// order, which this edge does not reach (the edge is never a fall-through:
    /// `split_edge_resolution` skips those), so publishing here would be
    /// telling the next block something that is not true on ITS paths.
    fn ls_emit_edge_copies(&mut self, pred_block: usize, succ_block: usize) {
        if self.ls_edge_copies.is_empty() {
            return;
        }
        let Some(idx) = self
            .ls_edge_copies
            .iter()
            .position(|e| e.pred == pred_block && e.succ == succ_block)
        else {
            return;
        };
        let copies = self.ls_edge_copies[idx].copies.clone();
        let phis = self.gather_phi_copies(pred_block, succ_block);
        for &(node, reg, gp) in &copies {
            let off = self.slot_of(node);
            let phi_reg_clash = phis.iter().any(|c| {
                if gp {
                    self.assigned_gpr(c.phi) == Some(reg)
                } else {
                    self.assigned_xmm(c.phi) == Some(reg)
                }
            });
            let home_clash =
                off == self.phi_copy_scratch_slot_off || phis.iter().any(|c| c.dst == off);
            if off <= 0 || phi_reg_clash || home_clash {
                self.latch_bailout(Bailout::with_context(
                    BailoutReason::Internal(
                        "ir_lower: an edge-resolution copy collides with the edge's phi copies",
                    ),
                    format!(
                        "n{node} -> {} {reg} on block {pred_block} -> {succ_block} \
                         (home [rbp-{off}], phi register clash {phi_reg_clash}, \
                         home clash {home_clash})",
                        if gp { "gp" } else { "xmm" }
                    ),
                ));
                return;
            }
            if gp {
                self.load_reg_from_frame(reg, off);
            } else {
                let is_double = self
                    .graph
                    .nodes
                    .get(node as usize)
                    .is_some_and(|n| matches!(n.ty, IrType::Double));
                self.fp_load(reg, off, is_double);
            }
            self.ls_edge_loads += 1;
        }
        if let Some(cell) = self.ls_edge_copies_done.get_mut(idx) {
            *cell = true;
        }
    }

    /// The value phis' half of [`Self::emit_phi_copies`].
    fn emit_value_phi_copies(&mut self, pred_block: usize, succ_block: usize) {
        let merge_ctrl = self.schedule.blocks[succ_block].ctrl;
        // Only Merge/Region blocks carry phis tied to incoming edges.
        if !matches!(
            self.graph.nodes[merge_ctrl as usize].op,
            Op::Merge | Op::Region
        ) {
            return;
        }

        // Gather (phi_slot, value_id) pairs first to avoid borrowing `self`
        // immutably while emitting (which borrows `self` mutably).
        let gathered = self.gather_phi_copies(pred_block, succ_block);
        let copies: Vec<(i32, i32)> = gathered.iter().map(|c| (c.dst, c.src_slot)).collect();

        // Phi copies are a PARALLEL assignment, not a sequence.
        //
        // `prealloc_phi_slots` gives every phi its own frame word, so a loop
        // that swaps two locals makes each phi the other's back-edge value and
        // this list becomes a cycle (`a <- b, b <- a`). Emitted in gather order
        // through RAX, the second copy reads the word the first just overwrote
        // and both locals end up holding `b` — a wrong-code bug, not a missed
        // optimisation.
        //
        // `resolve_parallel_copy` orders the copies so that every read still
        // sees the pre-copy value: destinations nothing else reads go first,
        // and when only cycles remain one element is parked in the scratch,
        // which frees its predecessor and unwinds the rest of the cycle. The
        // acyclic majority — every merge that is not a permutation — pays
        // exactly the same one load + one store per copy it always did, and
        // touches the scratch word not at all.
        //
        // An intermediate state of this fix REFUSED a residual cycle
        // (`UnsupportedShape("cyclic phi parallel copy")`) because no scratch
        // location was reserved. That was correct but dropped every swap-shaped
        // loop to a lower tier; `phi_copy_scratch_slot_off` is the reserved word
        // that makes the refusal unnecessary.
        let ops = match phi_copy_sequence(&copies) {
            Ok(ops) => ops,
            Err(bailout) => {
                let Bailout { reason, context } = bailout;
                let edge = format!("phi parallel copy on block {pred_block} -> {succ_block}");
                self.latch_bailout(Bailout::with_context(
                    reason,
                    match context {
                        Some(c) => format!("{edge}: {c}"),
                        None => edge,
                    },
                ));
                return;
            }
        };
        // Which node does each frame word in this edge belong to? Two maps,
        // because one word can be a source here and a destination there, and
        // the reserved scratch is in neither — a `Save`'s destination and a
        // `Restore`'s source therefore find nothing and stay memory, which is
        // what they must be.
        let (src_node_of, phi_of_dst) = if self.phi_copy_regs_on {
            let mut s: HashMap<i32, NodeId> = HashMap::new();
            let mut d: HashMap<i32, NodeId> = HashMap::new();
            for c in &gathered {
                s.insert(c.src_slot, c.src);
                d.insert(c.dst, c.phi);
            }
            (s, d)
        } else {
            (HashMap::new(), HashMap::new())
        };
        // ── The register layer's OWN interference, which the resolver cannot see
        //
        // `resolve_parallel_copy` sequentialises over FRAME WORDS. The register
        // fast path below then reads a source from its assigned GPR and
        // publishes a destination into the phi's assigned GPR — and two
        // DISTINCT frame words can be homed in the SAME register, because the
        // allocator sees a phi's live range as beginning after the merge and a
        // dying source's as ending at it, so they do not interfere by its
        // reckoning. They do interfere across the copy sequence: an earlier
        // copy's publish then overwrites a register a later copy still has to
        // read, and the resolver's word-level order says nothing about it.
        //
        // Measured on
        // `vm/tests/jit_ir_phi_copy_register_alias_fixtures/PhiCopyRegisterAliasProbe.java`
        // (and, in the wild, `java.time.Duration.toNanos()` — 198,356 wrong
        // answers in 200,000 calls): the else-arm of `if (seconds < 0)` emitted
        //   `mov rbx,rax`   ; publish phi_seconds, whose GPR is RBX
        //   `mov rax,rbx`   ; read phi_nanos's SOURCE, whose GPR is also RBX
        // so `nanos` came back as `seconds` and `toNanos()` returned
        // `seconds * 1e9 + seconds`. `CRATONVM_JIT_IR_PHI_COPY_REGS=0` and
        // `CRATONVM_JIT_IR_PHI_RESIDENCY=0` each made it disappear, which is
        // what named this layer as the owner.
        //
        // The fix is per-edge and conservative: a phi whose publish register is
        // ALSO some source's register on this edge does not publish inline.
        // Its home store is kept (so there is a word to read) and the trailing
        // residency loop below publishes it from that word — after every source
        // on the edge has been read. Everything else keeps the reg-to-reg
        // publish it had. The cost is one load per deferred phi per edge; the
        // alternative, ordering the two layers together, would have to model a
        // copy that writes two locations at once.
        let mut defer_publish: Vec<NodeId> = Vec::new();
        if self.phi_copy_regs_on {
            let src_regs: Vec<(NodeId, u8)> = gathered
                .iter()
                .filter_map(|c| self.assigned_gpr(c.src).map(|r| (c.src, r)))
                .collect();
            // Round 16 wave 3 (lane codegen, CG16-6): a phi's OWN source in
            // the phi's register (a coalesced back-edge source) is read by its
            // own copy before that copy writes the register, so it is no
            // reason to defer, unless another copy on this edge reads it too.
            let own_ok = ir_phi_coalesce_back_edge_enabled();
            for c in &gathered {
                if let Some(dst_reg) = self.assigned_gpr(c.phi) {
                    let own_only = |src: NodeId| {
                        own_ok
                            && src == c.src
                            && gathered.iter().filter(|o| o.src == src).count() == 1
                    };
                    if src_regs
                        .iter()
                        .any(|(src, r)| *r == dst_reg && *src != c.phi && !own_only(*src))
                    {
                        defer_publish.push(c.phi);
                        self.phi_copy_publish_deferred += 1;
                    }
                }
            }
        }
        let mut published: Vec<NodeId> = Vec::new();
        for op in ops {
            if let Err(bailout) = self.emit_copy_op(
                op,
                &src_node_of,
                &phi_of_dst,
                &defer_publish,
                &mut published,
            ) {
                self.latch_bailout(bailout);
                return;
            }
        }
        // 2026-09-02: a register-resident phi is PUBLISHED here, at every
        // incoming edge, from the home word the copies just wrote. This is the
        // definition site a phi never had, and it is what lets a loop counter
        // or accumulator -- a phi at every loop header -- be read from a
        // register inside the loop (`ir_phi_residency_enabled`). Reads before
        // the first published edge (in emission order) still take the home
        // word; every edge publishes, so the register is valid on entry to the
        // block whichever predecessor ran.
        //
        // 2026-09-04: a GP phi whose copy went through RAX is published *there*,
        // from RAX, and appears in `published`. The reload below is what is
        // left for everything else — the FP half, and any phi whose copy the
        // resolver dropped as a self-copy (nothing was emitted, so nothing
        // could publish, and on the first edge in emission order the register
        // may not be live yet).
        if ir_phi_residency_enabled() {
            for c in &gathered {
                if published.contains(&c.phi) {
                    continue;
                }
                // A PHI WHOSE HOME WAS DROPPED HAS NO WORD TO PUBLISH FROM.
                //
                // `emit_copy_op` drops the home store for a non-deferred phi
                // that `phi_home_droppable` cleared, on the grounds that its
                // register is the only location anyone reads. This loop is the
                // one reader that did not get that memo: it reaches a phi that
                // `published` does not contain -- which includes every phi
                // whose copy `resolve_parallel_copy` dropped as a SELF-COPY,
                // where `emit_copy_op` never ran at all and so neither stored
                // the word nor published the register -- and loads the home
                // word regardless.
                //
                // That is a read of uninitialised stack, and it is not
                // theoretical: `org.h2.command.query.Select.processGroupResult`
                // reloaded its `long offset` phi from `[rbp-0B0h]`, a slot the
                // 11,591-byte body reads three times and writes zero times, on
                // the loop back edge. The garbage came back large and positive
                // and the loop's `quickOffset && offset > 0` arm dropped result
                // rows as if the query had an OFFSET clause -- H2 window and
                // GROUP BY queries returning 3 rows of 5. See
                // `internal/fixed-bugs/jit-warm-groupdata-window-row-collapse-20260906-FIXED.md`.
                //
                // A DEFERRED phi is exempt and must stay exempt: `emit_copy_op`
                // keeps its home store precisely so this loop can read it.
                if ir_phi_home_publish_guard_enabled()
                    && !defer_publish.contains(&c.phi)
                    && self
                        .home_dropped
                        .get(c.phi as usize)
                        .copied()
                        .unwrap_or(false)
                {
                    if self.resident_gpr(c.phi).is_some() {
                        // The register already holds it -- which is the whole
                        // premise of dropping the home. Nothing to publish.
                        self.phi_home_publish_skipped += 1;
                    } else if let Some(dst) = self.assigned_gpr(c.phi) {
                        // A copy the resolver dropped as a SELF-COPY (the phi's
                        // home slot IS the source's): nothing was emitted on
                        // this edge, and the phi's home is never written, so
                        // publish the phi's register from wherever the SOURCE's
                        // value is. `gp_load_value` is the one reader that knows
                        // every place (its register, a carry -- which only this
                        // read takes out of its slot -- a constant, or a
                        // written home word) and refuses the compile itself
                        // when it is none of them. Refusing here instead threw
                        // away every compile whose slot colouring shared a
                        // phi's home with one of its sources -- bounded
                        // self-recursive inlining's `itemCheck` (a spliced
                        // copy's result phi, fed by a carried `Add`) among them.
                        self.gp_load_value(dst, c.src);
                        self.mark_gp_reg_live(c.phi);
                        self.phi_home_publish_skipped += 1;
                    } else {
                        // Neither location is readable. REFUSE, exactly as
                        // `emit_copy_op` refuses the mirror case, rather than
                        // emit a read of a word nothing wrote.
                        self.phi_home_publish_refused += 1;
                        self.latch_bailout(Bailout::with_context(
                            BailoutReason::UnallocatedValue { node: c.phi },
                            format!(
                                "n{}'s home was dropped and its register is not live at a publish edge",
                                c.phi
                            ),
                        ));
                        return;
                    }
                    continue;
                }
                if self.assigned_gpr(c.phi).is_some() {
                    self.publish_gp_from_slot(c.phi, c.dst);
                } else if self.assigned_xmm(c.phi).is_some() {
                    let is_double = self.graph.nodes[c.phi as usize].ty == IrType::Double;
                    self.publish_fp_from_slot(c.phi, c.dst, is_double);
                }
            }
        } else {
            // The publish `emit_copy_op` skipped for an aliasing phi still has
            // to happen, whatever the residency switch says: it was skipped
            // because doing it inline would have been WRONG, not because it was
            // unwanted. The loop above covers this when residency is on; this
            // arm is the same duty when it is off (the inline publish is gated
            // on `ir_phi_copy_regs_enabled` alone, so it runs in that
            // configuration too, and so must its deferral).
            for c in &gathered {
                if defer_publish.contains(&c.phi) {
                    self.publish_gp_from_slot(c.phi, c.dst);
                }
            }
        }
    }

    /// Emit one sequentialised [`CopyOp`], routed through RAX (the move
    /// temporary) and, for `Save`/`Restore`, the reserved scratch frame word.
    ///
    /// `Save` and `Restore` are *not* a push/pop pair: `resolve_parallel_copy`
    /// emits at most one live save at a time and always consumes it before
    /// starting another cycle, so a single word suffices no matter how many
    /// disjoint cycles the edge contains.
    fn emit_copy_op(
        &mut self,
        op: CopyOp,
        src_node_of: &HashMap<i32, NodeId>,
        phi_of_dst: &HashMap<i32, NodeId>,
        defer_publish: &[NodeId],
        published: &mut Vec<NodeId>,
    ) -> CompileResult<()> {
        let scratch = self.phi_copy_scratch_slot_off;
        let (src, dst) = match op {
            CopyOp::Move { from, to } => (frame_word_off(from)?, frame_word_off(to)?),
            CopyOp::Save { from } => (frame_word_off(from)?, scratch),
            CopyOp::Restore { to } => (scratch, frame_word_off(to)?),
        };
        // The scratch is a reserved bookkeeping word placed by `Lowerer::new`;
        // a zero here would encode `[rbp - 0]`, the saved caller RBP.
        if src <= 0 || dst <= 0 {
            return Err(Bailout::with_context(
                BailoutReason::Internal("ir_lower: a phi copy names frame offset 0"),
                format!("[rbp - {dst}] <- [rbp - {src}]"),
            ));
        }
        // ── Read: from the source's register when it has one ──────────
        //
        // Safe for the same reason the memory schedule is safe, and by the same
        // argument. `resolve_parallel_copy` orders the ops so that every source
        // is READ before anything writes it; a register is updated at exactly
        // the instruction that writes the word (below), so a register and its
        // home word go stale at the same point, and an order that protects one
        // protects the other. A cycle's `Save` copies the pre-value out at the
        // same instant either way.
        // ── Which register STAGES the value ──────────────────────────
        //
        // RAX was the staging register for every phi copy, and the publish
        // below then copied RAX into the phi's own register. When the phi has
        // one, that register is a strictly better temporary: the read lands
        // there directly and the publish disappears, because the value is
        // already where the publish was going to put it.
        //
        // Worth one instruction per phi per edge, i.e. per loop-carried value
        // per iteration. On `probes/FieldLoop.java` `sum` the back edge was
        //
        //     mov rax,r15 / mov r12,rax          ; the `sum` phi
        //     mov rax,[rbp-98h] / mov rbx,rax    ; the `i` phi
        //
        // which is four instructions in a 26-instruction loop body to move two
        // values that are already in a register or a word.
        //
        // # Why it is the same program
        //
        // The write to the phi's register moves EARLIER inside this one
        // `CopyOp` — from after the home store to before it — and nothing in
        // between reads anything: the only instruction it crosses is this
        // copy's own store, whose source it now is. Relative to every OTHER
        // copy on this edge the ordering is unchanged, because the old publish
        // was already inside this op and therefore already ahead of the next
        // op's read. `resolve_parallel_copy`'s invariant (every source is read
        // before anything writes it) is a statement about that cross-op order
        // and is untouched.
        //
        // # What still goes through RAX, and why
        //
        // * a phi with no GP register — an FP phi publishes from its home word
        //   in `emit_phi_copies`'s later loop, and a non-resident phi has
        //   nowhere else to stage;
        // * a DEFERRED publish — the home store is the only thing carrying the
        //   value to the end of the edge, so writing the register here would
        //   publish it at the wrong point;
        // * `CopyOp::Save`, whose destination is the scratch word and has no
        //   phi at all;
        // * **a phi whose home store SURVIVES.** That one is a deliberate
        //   restriction rather than an obstacle, and the reason is in
        //   `a_phi_copy_that_keeps_its_home_is_byte_identical`: staging there
        //   would also have to write the home from the staged register, and no
        //   test in this crate can separate a right store from a wrong one on
        //   that path — nothing reads a resident phi's home word back, so
        //   `store_abi_reg(RAX, dst)` in place of the value produces identical
        //   answers. Requiring the drop keeps every remaining path one this
        //   suite can fail. It costs the home-keeping case one instruction, on
        //   a path a `panic!` proved the whole crate never reaches.
        let stage = phi_of_dst
            .get(&dst)
            .copied()
            .filter(|_| self.phi_copy_regs_on && ir_phi_copy_direct_enabled())
            .filter(|phi| !defer_publish.contains(phi))
            .filter(|phi| {
                self.home_dropped
                    .get(*phi as usize)
                    .copied()
                    .unwrap_or(false)
            })
            .and_then(|phi| self.assigned_gpr(phi).map(|reg| (phi, reg)));
        let stage_reg = stage.map_or(RAX, |(_, reg)| reg);
        let mut from_reg = false;
        if self.phi_copy_regs_on {
            if let Some(&sid) = src_node_of.get(&src) {
                // A source whose home is never written has ONE readable
                // location, and `resident_gpr`'s "has it been published yet"
                // gate is the wrong question for it: there is nothing to fall
                // back to. `assigned_gpr` is the right one, and it is safe for
                // the same reason the publish is — the value is defined before
                // any edge that reads it, and the register is exclusively its
                // own (that is a clause of `phi_home_droppable`).
                let homeless = self
                    .home_dropped
                    .get(sid as usize)
                    .copied()
                    .unwrap_or(false);
                let src_reg = if homeless {
                    self.assigned_gpr(sid)
                } else {
                    self.resident_gpr(sid)
                };
                match src_reg {
                    Some(r) => {
                        // A no-op when the source already sits in the phi's
                        // register, which `emit_mov_reg_reg64` drops rather
                        // than encoding `mov r,r`.
                        self.emit_mov_reg_reg64(stage_reg, r);
                        from_reg = true;
                        self.phi_copy_reg_reads += 1;
                    }
                    // Unreachable by construction: a home is dropped only for a
                    // value the residency file gave an exclusive register. If
                    // it ever happens, refuse the compile rather than emit a
                    // read of a word nothing wrote.
                    // CG16P-4: a dropped constant is read as an immediate
                    // below.
                    None if homeless && self.is_dropped_const(sid) => {}
                    None if homeless => {
                        return Err(Bailout::with_context(
                            BailoutReason::UnallocatedValue { node: sid },
                            format!("n{sid}'s home was dropped but it has no register"),
                        ));
                    }
                    None => {}
                }
            }
        }
        // Round 16 wave 3 (lane codegen, CG16-7): a constant source is an
        // immediate, exactly as `gp_load_value` materialises it, not a home
        // word (`Op::Const` writes its home with the same 64-bit value).
        let dropped_const_src = src_node_of
            .get(&src)
            .is_some_and(|&sid| self.is_dropped_const(sid));
        if !from_reg
            && self.const_imm_on
            && (ir_phi_const_source_imm_enabled() || dropped_const_src)
        {
            let imm = src_node_of
                .get(&src)
                .and_then(|&sid| self.graph.nodes.get(sid as usize))
                .and_then(|node| match node.op {
                    Op::Const(val) if matches!(node.ty, IrType::Int | IrType::Long) => Some(val),
                    _ => None,
                });
            if let Some(val) = imm {
                self.emit_mov_reg_imm_smart(stage_reg, val);
                from_reg = true;
                self.phi_copy_const_imms += 1;
            }
        }
        if !from_reg && dropped_const_src {
            return Err(Bailout::with_context(
                BailoutReason::Internal(
                    "ir_lower: a dropped constant home is an edge copy's source",
                ),
                format!("[rbp - {src}]"),
            ));
        }
        if !from_reg {
            self.load_reg_from_frame(stage_reg, src);
        }
        // ── The store, when anything could read it ───────────────────
        //
        // This is what the register image was reserved for. A loop-carried
        // value whose register a deopt frame can name, whose every reader takes
        // that register, needs no frame word at all — and this store was the
        // last frame traffic left in the loop after the two reloads went.
        // A deferred publish (see `emit_phi_copies`) reads this word back at the
        // end of the edge, so the store it would otherwise have dropped is the
        // only thing that carries the value — keep it.
        let drop_home = phi_of_dst.get(&dst).is_some_and(|phi| {
            !defer_publish.contains(phi)
                && self
                    .home_dropped
                    .get(*phi as usize)
                    .copied()
                    .unwrap_or(false)
        });
        if drop_home {
            self.home_stores_dropped += 1;
        } else {
            // Reached only with `stage_reg == RAX`: `stage` requires the phi's
            // home to be dropped and `drop_home` is that same fact, so the two
            // are the same condition read from the two directions. The
            // `debug_assert` is what stops a future widening of `stage` from
            // silently storing the wrong register here.
            debug_assert_eq!(
                stage_reg, RAX,
                "a staged phi copy reached the home store; `stage` and \
                 `drop_home` have come apart",
            );
            self.store_rax(dst);
        }
        // ── Publish: from RAX, which provably holds the value ─────────
        //
        // The reload this replaces was the second half of the store-then-load
        // pair: `store [dst], rax` and then, a couple of instructions later,
        // `mov reg, [dst]` — the same word, written and read back across a
        // store-forwarding stall, once per phi per edge, i.e. once per loop
        // iteration for every loop-carried value.
        if let Some((phi, _)) = stage {
            // Staged straight into the phi's register above: the value is
            // already published, and the bookkeeping is the same either way so
            // that `emit_phi_copies`'s `published` check cannot tell the two
            // routes apart.
            self.mark_gp_reg_live(phi);
            published.push(phi);
            self.phi_copy_reg_publishes += 1;
        } else if self.phi_copy_regs_on {
            if let Some(&phi) = phi_of_dst.get(&dst) {
                if let Some(dst_reg) = self.assigned_gpr(phi) {
                    if !defer_publish.contains(&phi) {
                        self.emit_mov_reg_reg64(dst_reg, RAX);
                        self.mark_gp_reg_live(phi);
                        published.push(phi);
                        self.phi_copy_reg_publishes += 1;
                    }
                }
            }
        }
        // Round 11 (irlower): a cycle's parked value is consumed; clear the
        // scratch. It sits in the reserved bookkeeping tail the prologue zeroes
        // for the band verifier's sake (see `emit_prologue`), and after a swap
        // of two REFERENCES it held a live young pointer that no oop map names
        // and no shadow push publishes -- which refuses every moving cycle
        // that stops this frame, until the next cycle overwrites it. One store,
        // on the rare edge whose copies form a cycle.
        if matches!(op, CopyOp::Restore { .. }) && !prologue_zero_reserved_tail_disabled() {
            self.emit_zero_frame_slot(scratch);
        }
        Ok(())
    }

    // ── Code emission helpers ────────────────────────────────────────

    /// The callee-saved XMM registers this method actually parked a value in,
    /// paired with the frame offset each is saved at.
    ///
    /// Empty on System V (nothing is callee-saved), empty when the linear-scan
    /// path is off, and empty for any method whose allocation promoted nothing
    /// into XMM6/XMM7 — which is the common case even with the flag on. A
    /// method that uses none of them emits no save, no restore and pays only
    /// the reserved frame bytes.
    ///
    /// Reads the residency plan, which `lower_inner_with_array_list` installs
    /// BEFORE `lower()` runs (`set_residency`, "installed before the prologue
    /// and never touched again"). That ordering is what makes a *dynamic* save
    /// set legal against a *static* frame reservation: the set can only shrink
    /// relative to `IR_LOWER_SAVED_XMMS`, never grow past it.
    ///
    /// **A SNAPSHOT (`ls_saved_fp`), not a scan of `reg_of`.** It was the scan
    /// until split residency, and the scan was correct only for as long as
    /// `reg_of` never changed after installation. Split residency changes it,
    /// per position, so a prologue that saved XMM6 could be followed by an exit
    /// that no longer found XMM6 in `reg_of` and returned to its caller with
    /// XMM6 destroyed. The snapshot is taken once, over every register the plan
    /// can ever hand out, so the prologue and every epilogue read one answer.
    fn saved_xmm_regs(&self) -> impl Iterator<Item = (u8, i32)> + '_ {
        let base = self.spill_cap_off;
        let reserved = self.saved_xmm_bytes;
        // Round 16 wave 17 (lane frames2): a sized band holds the `k`-th saved
        // register in its `k`-th slot (`size_save_bands`).
        let packed = self.save_bands_packed;
        IR_LOWER_SAVED_XMMS
            .iter()
            .enumerate()
            .filter(move |_| reserved > 0)
            .filter(move |(_, reg)| self.ls_saved_fp[**reg as usize])
            .enumerate()
            // Cast: `IR_LOWER_SAVED_XMMS` has two elements.
            .map(move |(k, (i, reg))| {
                let slot = if packed { k } else { i };
                (*reg, base + (slot as i32 + 1) * 16)
            })
    }

    /// `MOVUPS [rbp - off], xmm` (save) or `MOVUPS xmm, [rbp - off]` (restore).
    ///
    /// Unaligned on purpose: `frame_size` is 16-byte aligned but `rbp` itself is
    /// only guaranteed 8-byte aligned at entry (the `push rbp` follows the
    /// caller's `call`), so `MOVAPS` would fault on half the call sites. The
    /// three-byte cost of the unaligned form is paid once per method.
    ///
    /// # REX (R14)
    ///
    /// This is the **fourth** no-REX XMM encoder in this file, and the one
    /// `NOTES-regalloc7.md` §1 did not name. It is fed by
    /// [`Self::saved_xmm_regs`], i.e. by `xmm_roles::IR_PROLOGUE_SAVED` — which
    /// is precisely the constant that same note says must grow in lockstep with
    /// `IR_LINEAR_SCAN` on Windows. Fixing `fp_load`/`fp_store`/`fp_binop` and
    /// then widening the two constants would therefore have moved the silent
    /// truncation from the body into the PROLOGUE, where it corrupts a
    /// caller's register instead of a callee's value. Hence the REX here.
    ///
    /// `MOVUPS` has no mandatory SSE prefix, so REX is the FIRST byte — unlike
    /// `fp_load`/`fp_store`, where it follows the `F2`/`F3`. Only REX.R can be
    /// wanted: the base is RBP (encoding 5).
    fn emit_xmm_frame_move(&mut self, reg: u8, off: i32, store: bool) {
        if reg >= 8 {
            self.buf.emit_byte(0x44); // REX.R — MOVUPS has no prefix to follow
        }
        self.buf.emit(&[0x0F, if store { 0x11 } else { 0x10 }]);
        // ModRM + displacement for `[rbp - off]`, smallest legal form.
        self.emit_rbp_modrm_disp(reg, off);
    }

    /// The callee-saved GPRs this method actually parked a value in, paired
    /// with the frame offset each is saved at.
    ///
    /// The GPR band sits immediately below the XMM one, so register `i` of
    /// [`IR_LOWER_SAVED_GPRS`] lives at
    /// `spill_cap_off + saved_xmm_bytes + 8*(i+1)` — the same "+1 so the
    /// store's bytes land inside the reservation" shape `saved_xmm_regs` uses.
    ///
    /// Dynamic against a static reservation, for the reason stated there: the
    /// residency plan is installed before `lower()` runs, so this set can only
    /// shrink relative to [`IR_LOWER_SAVED_GPRS`], never grow past it. A method
    /// that promotes nothing emits no save and no restore.
    ///
    /// A SNAPSHOT (`ls_saved_gp`) for the reason `saved_xmm_regs` gives at
    /// length: split residency makes `gp_reg_of` change during the emission,
    /// and a prologue and an epilogue that disagree about which registers this
    /// frame owes its caller corrupt the caller's register state with nothing
    /// to notice.
    fn saved_gpr_regs(&self) -> impl Iterator<Item = (u8, i32)> + '_ {
        let base = self.spill_cap_off + self.saved_xmm_bytes;
        let reserved = self.saved_gpr_bytes;
        // `ir_gp_file()`, not `IR_LOWER_SAVED_GPRS`: the save area covers the
        // registers this compile could HAND OUT, so with the kill switch off
        // the frame is byte-identical to the pre-widening tree rather than
        // paying 16 bytes for two registers nothing can name.
        // Round 16 wave 17 (lane frames2): a sized band holds the `k`-th saved
        // register in its `k`-th slot (`size_save_bands`).
        let packed = self.save_bands_packed;
        ir_gp_file()
            .iter()
            .enumerate()
            .filter(move |_| reserved > 0)
            .filter(move |(_, reg)| self.ls_saved_gp[**reg as usize])
            .enumerate()
            // Cast: `IR_LOWER_SAVED_GPRS` is a small compile-time constant
            // (five registers, or seven on Win64).
            .map(move |(k, (i, reg))| {
                let slot = if packed { k } else { i };
                (*reg, base + (slot as i32 + 1) * 8)
            })
    }

    /// `MOV [rbp - off], reg` (save) or `MOV reg, [rbp - off]` (restore), for a
    /// callee-saved GPR. Both directions already exist as frame accessors that
    /// pick the smallest displacement form; this names the pair.
    fn emit_gpr_frame_move(&mut self, reg: u8, off: i32, store: bool) {
        if store {
            self.store_abi_reg(reg, off);
        } else {
            self.load_reg_from_frame(reg, off);
        }
    }

    /// Restore the callee-saved registers. Emitted at every exit, and it must
    /// not disturb RAX — a method's return value and the `i64::MIN`
    /// exception/deopt sentinel both travel there. `MOVUPS` into an XMM
    /// satisfies that for free, and the GPR restores target RBX/R12–R15 (plus
    /// RSI/RDI on Win64), a set RAX could never have been in because every
    /// member of it is callee-saved and RAX is not: see `IR_GP_LINEAR_SCAN`.
    fn emit_callee_saved_restore(&mut self) {
        let restores: Vec<(u8, i32)> = self.saved_xmm_regs().collect();
        for (reg, off) in restores {
            self.emit_xmm_frame_move(reg, off, false);
        }
        let gpr_restores: Vec<(u8, i32)> = self.saved_gpr_regs().collect();
        for (reg, off) in gpr_restores {
            self.emit_gpr_frame_move(reg, off, false);
        }
    }

    fn emit_prologue(&mut self) {
        // push rbp
        self.buf.emit_byte(0x55);
        // mov rbp, rsp
        self.buf.emit(&[0x48, 0x89, 0xE5]);
        // sub rsp, frame_size
        self.buf.emit(&[0x48, 0x81, 0xEC]);
        self.buf.emit(&self.frame_size.to_le_bytes());

        // gen r5w4/jit8, under default-on `CRATONVM_JIT_IR_ZERO_FRESH_FRAMES`
        // (item 1 of `docs/internal/gc/gengc-r5w2-oomjit6-compiled-frame-residue-residuals-RETIRED-20260928.md`):
        // a FRESH frame starts all-zero. Everything below is written after
        // this, so nothing of this activation is lost.
        self.frame_prezeroed = false;
        self.fresh_clear_skip = Vec::new();
        if ir_zero_fresh_frames_enabled() && self.frame_size > 0 && self.frame_size % 8 == 0 {
            // Round 16 wave 6 (lane codegen, CG16-10): the same words, zeroed
            // with 16-byte stores (`emit_zero_frame_sse`), and the prologue's
            // later per-word zero stores, which would store zero over zero,
            // skipped (`frame_prezeroed`).
            // Under a MIR mode too: the prologue is no tile, and the level-2
            // byte oracle compares the whole body against the per-opcode one.
            //
            // Round 16 wave 7 (lane frames): through
            // `emit_fresh_frame_clear_sse`, which with its three switches off
            // emits exactly `emit_zero_frame_sse`; a word it leaves out keeps
            // its later per-word zero store (`fresh_clear_skipped`).
            if ir_zero_fresh_frames_sse_enabled() {
                self.fresh_clear_skip = self.emit_fresh_frame_clear_sse(true);
                self.frame_prezeroed = true;
            } else {
                self.emit_zero_whole_frame();
            }
        }

        // Callee-saved XMM save area. FIRST, before the ABI parameter stores:
        // an incoming floating-point argument arrives in XMM0..XMM3 (Win64) and
        // nothing here touches those, but ordering the save ahead of every
        // other prologue step keeps "the caller's registers are preserved" true
        // across the whole body rather than across most of it.
        let saves: Vec<(u8, i32)> = self.saved_xmm_regs().collect();
        for (reg, off) in saves {
            self.emit_xmm_frame_move(reg, off, true);
        }
        // …and the callee-saved GPR file, on the same footing and for the same
        // reason: every register in it belongs to the caller on both ABIs.
        let gpr_saves: Vec<(u8, i32)> = self.saved_gpr_regs().collect();
        for (reg, off) in gpr_saves {
            self.emit_gpr_frame_move(reg, off, true);
        }

        // Store params from ABI registers to local frame slots.
        // Windows: RCX, RDX, R8, R9.  SysV: RDI, RSI, RDX, RCX, R8, R9.
        // One list, shared with `incoming_abi_reg_capacity()` — the local copy
        // this used to keep could (and did) disagree with the bail that is
        // supposed to keep the `break` below unreachable.
        let abi_regs: &[u8] = ENTRY_ABI_REGS;

        // Gap B: a `needs_context` method receives the VM context pointer in
        // ABI[0] (the `try_call_with_context` convention), with the Java params
        // shifted to ABI[1..]. Store the context to its slot, then the params to
        // their local slots.
        //
        // An argument past the register file arrives on the CALLER'S STACK, and
        // this prologue used to drop it: the loop `break`s and the local keeps
        // whatever the frame slot happened to contain. `lower()` therefore
        // refused any method with more incoming slots than registers outright —
        // four on Win64, six on SysV — which made it "the commonest whole-method
        // refusal an ordinary accessor hits": an instance method with three
        // parameters is four slots, and touching one field turns
        // `needs_context` on, which is the fifth.
        //
        // It is loaded now, the way the single-pass prologue has loaded it since
        // the ROUND-12 fix (`x64/frames.rs`), from the same place, because the
        // two backends share the outgoing convention: `stack_arg_block_size`
        // here mirrors `x64::frames::stack_arg_block_size`, and a caller
        // materializes stack arguments at `[rsp + shadow]` immediately before
        // the CALL. After the CALL pushes the return address and this prologue
        // pushes RBP, argument `k` past the register file sits at
        // `[rbp + STACK_ARG_BASE + (k - reg_count) * 8]`.
        let base = if self.needs_context {
            self.store_abi_reg(abi_regs[0], self.context_slot_off);
            1
        } else {
            0
        };
        // Java arguments that fit the register file, then the rest off the
        // caller's frame. `reg_count` is how many of THIS method's arguments a
        // register carries, which is the file size minus the context slot.
        let reg_count = self.num_params.min(abi_regs.len().saturating_sub(base));
        for i in 0..reg_count {
            self.store_abi_reg(abi_regs[base + i], ((i as i32) + 1) * 8); // local_offset(i)
        }
        // Round 14 wave 7 (lane callcost3, CC6-2): the parameters' registers,
        // straight from the ABI registers they arrived in.
        let fills = self.plan_param_register_fills(base, reg_count);
        for (id, dst, src) in fills {
            self.emit_mov_reg_reg64_raw(dst, src);
            self.mark_gp_reg_live(id);
            self.param_register_fills.push((id, dst));
        }
        if !self.param_register_fills.is_empty()
            && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_PARAM_FILL")
        {
            eprintln!(
                "[ir-param-fill] filled (node, reg): {:?}",
                self.param_register_fills
            );
        }
        for i in reg_count..self.num_params {
            // `[RBP + disp]`, which `load_reg_from_frame` spells as a NEGATIVE
            // offset (it encodes `[RBP - offset]`). Via RAX because there is no
            // memory-to-memory MOV.
            let disp = STACK_ARG_BASE + ((i - reg_count) as i32) * 8;
            self.load_reg_from_frame(RAX, -disp);
            self.store_abi_reg(RAX, ((i as i32) + 1) * 8); // local_offset(i)
        }
        // Zero every local slot this method did NOT receive as a parameter.
        //
        // The JVM's definite-assignment rule means such a slot is never read
        // before it is written, so its entry value is unobservable to Java --
        // but it is very observable to the GC. `alloc`'s `long[] a` is slot 1,
        // and at the `new long[n]` safepoint one instruction later it still
        // holds whatever the previous frame at this address left there. In an
        // allocation-heavy workload that is a stale object pointer, so G1's
        // band verifier finds a movable-resident word that no oop map names
        // (correctly -- the dataflow knows the local is not live yet) and no
        // shadow push published, and refuses to relocate.
        //
        // That was the ENTIRE residual after the reserved-tail zeroing below:
        // 8.5-15.2% of pauses incomplete on `CoverageBench`, every report at
        // this one offset in this one leaf.
        //
        // Safe because this prologue runs only on a normal entry. This tier's
        // OSR entries do not jump past it into an interpreter-filled frame:
        // each enters through its own stub (`emit_osr_entry_stubs`), which
        // builds the frame, saves the callee-saved set into these same slots,
        // zeroes the locals the same way, and only THEN seeds the live ones
        // from the interpreter's snapshot. The single-pass trampoline
        // (`osr_pc_to_native`) is never used for this tier's artifacts.
        // (gcg g3/v: this used to say "the prologue is the sole entry", which
        // stopped being true when the tier gained OSR stubs.)
        //
        // Round 11 wave 16 (lane irback; step 4 of
        // `r11w14-rt-ir-lower-oop-free-frame-patch`): a reference-free body
        // (`lean_prologue`, below) skips this loop and the three GC-only
        // reserved-tail stores. Every one of those stores exists for the
        // collector's band verifier and conservative band scan; such a body is
        // published `frame_holds_no_references` (the artifact fill refuses the
        // compile otherwise), and the collector neither verifies nor rewrites
        // its band. No Java-visible reader exists: a JVM local past the
        // parameters is never read before it is written (definite assignment)
        // and is homed in a coloured slot, not here.
        let lean_prologue = self.lean_ref_free_prologue();
        // Round 16 wave 4 (lane codegen, CG16-8): the zero stores from here to
        // the end of the prologue use the RAX form (`emit_zero_frame_slot`).
        // Under a MIR mode too, for the reason the fresh-frame clear gives.
        self.prologue_zero_rax = ir_prologue_zero_rax_enabled();
        self.zero_rax_end = None;
        self.prologue_zero_stretch = true;
        if !prologue_zero_unset_locals_disabled() && !lean_prologue {
            for i in self.num_params..self.num_locals {
                // Cast: a JVM local index times 8 -- `max_locals` is u16.
                self.emit_zero_frame_slot(((i as i32) + 1) * 8);
            }
        }
        // Before anything is zeroed: the frame block changes which reference
        // homes the prologue must clear, and makes the saved-base word its
        // "published" flag.
        self.plan_frame_block();
        // Zero the cached-thread and watermark slots BEFORE the fetch. The
        // fetch is erased (NOP'd) by `finish_lazy_thread_fetch` when the method
        // publishes nothing, and every consumer below is null-guarded on the
        // thread slot — so it must read 0, not uninitialised stack. The
        // single-pass backend zero-initialises for exactly this reason (see the
        // incident writeup on `x64.rs::Compiler::emit_epilogue`).
        if self.get_current_thread != 0 && self.shadow_thread_slot_off > 0 {
            // KEPT for a lean body: the thread slot has null-guarded readers
            // (the deopt stub's retraction, the call-exception stubs) that
            // would dereference a non-zero stale word.
            self.emit_zero_frame_slot(self.shadow_thread_slot_off);
            // Round 11 wave 16 (lane irback): the watermark's only readers are
            // `emit_shadow_savetop_restore` (erased for a body with no roots)
            // and a rethrow pad's copy-back (only with a pending publication,
            // which a reference-free body never has); the fetch's capture, if
            // it survives, writes it first. A lean body skips the store.
            if !lean_prologue {
                self.emit_zero_frame_slot(self.shadow_savetop_slot_off);
            }
            // ... and the OTHER two reserved bookkeeping words, for the same
            // reason and a second one.
            //
            // `shadow_savebase` is written only by a shadow PUSH and
            // `phi_copy_scratch` only by a parallel copy that needs to break a
            // cycle. A method that does neither -- every no-oop leaf, and
            // `finish_lazy_thread_fetch` erases the fetch in exactly those --
            // leaves both holding whatever the previous frame at this address
            // left behind. In allocation-heavy code that is a stale object
            // pointer, and G1's band verifier then finds a movable-resident
            // word in the reserved-locals tail that no oop map names and no
            // shadow push published, and correctly refuses to relocate the
            // whole collection.
            //
            // Measured on `CoverageBench` after the §26 window repair: the
            // ENTIRE residual incomplete rate (~19%, 386 reports over six runs)
            // was `CoverageBench.alloc`, at three offsets -- and two of them are
            // these. Neither word is ever read while it holds that garbage, so
            // zeroing costs two prologue stores and removes the refusal.
            //
            // Kept inside this gate deliberately: it is the same "the reserved
            // tail must read 0, not uninitialised stack" contract the two
            // stores above already establish, and the same block the
            // single-pass backend zero-initialises for.
            // With a frame block the saved-base word is the block's
            // "published" flag, which every safepoint reads — so it is zeroed
            // whatever the reserved-tail switch says.
            //
            // A lean body has no frame block, no shadow push and no pending
            // publication, which are the saved base's only readers, and its
            // phi scratch is written before every read (`emit_phi_copies`,
            // the `newarray` length staging); both stores exist for the band
            // verifier alone, which does not verify such a frame.
            if (!prologue_zero_reserved_tail_disabled() && !lean_prologue)
                || !self.frame_block.is_empty()
            {
                if self.shadow_savebase_slot_off > 0 {
                    self.emit_zero_frame_slot(self.shadow_savebase_slot_off);
                }
            }
            if !prologue_zero_reserved_tail_disabled() && !lean_prologue {
                if self.phi_copy_scratch_slot_off > 0 {
                    self.emit_zero_frame_slot(self.phi_copy_scratch_slot_off);
                }
            }
        }
        // And the safepoint-id slot, for the SAME reason and on its own gate:
        // `active_safepoint_id` reads `[rbp - sp_id_slot_off]` on any live
        // frame, including one stopped BEFORE its first safepoint, and until
        // that first `emit_safepoint_map` store the word is whatever the
        // previous frame at this stack depth left behind.
        //
        // Ids start at 1 precisely so 0 can mean "no safepoint reached" (see
        // the slot's allocation above), but nothing was writing the 0. The
        // sentinel was a convention the prologue never established.
        //
        // MEASURED, `TestCachedQueryResults` (H2), 13 frames the band verifier
        // reported as `no-map-for-id`: 10 read `0` and 3 read a HEAP POINTER at
        // `sp_id_off`. That was diagnosed as two defects -- "has not reached a
        // safepoint" and "something stored an oop into the reserved slot". It
        // is one: uninitialised stack, reading as zero where the region happened
        // to be clean and as a stale oop where it did not.
        //
        // Refusing the cycle is the benign outcome. The hazard this closes is
        // that safepoint ids are small consecutive integers, so a stale word
        // can equal a VALID id for this method -- and then
        // `find_oop_map_for_safepoint_id` matches the map for a DIFFERENT
        // program point and relocation rewrites against it. That is a silent
        // wrong answer, not a refusal.
        //
        // `CRATONVM_JIT_ZERO_SPID=0` restores the uninitialised read: the
        // one-binary A/B, and the kill switch.
        if self.sp_id_slot_off > 0 && Self::zero_sp_id_slot_enabled() {
            self.emit_zero_frame_slot(self.sp_id_slot_off);
        }
        self.emit_frame_record();
        self.fetch_current_thread();
        self.zero_ref_phi_slots();
        // The entry-block refinement holds only for per-call publication; a
        // frame block publishes every home at the first safepoint, including
        // one the entry block has not written yet (`plan_frame_block`).
        self.zero_ref_value_slots(/* entry_runs */ self.frame_block.is_empty());
        self.prologue_zero_rax = false;
        self.zero_rax_end = None;
        self.prologue_zero_stretch = false;
    }

    /// Round 14 wave 7 (lane callcost3, proposal CC6-2 of
    /// `jit-r14-callcost2-proposals-RETIRED-20260930.md`; F8-4 / LC-5 of
    /// `r12w8-callcost-fib-call-anatomy-FIXED-20261001.md`): the `int`/`long`
    /// parameters whose register [`Self::emit_prologue`] fills with `MOV dst,
    /// abi` right after storing the ABI register to the prologue word, as
    /// `(Op::Param node, dst, abi)`. The prologue marks each one live in `dst`
    /// (`mark_gp_reg_live`), and its `Op::Param` arm then skips the reload
    /// `publish_gp_from_slot` would make from that word (the store-forwarded
    /// `MOV dst, [rbp - 8]` of every activation that reaches the prologue) --
    /// but only while [`Self::param_register_filled`] still says `dst` holds
    /// it.
    ///
    /// Why that answer is exact: the value is the whole incoming register, the
    /// same 64 bits the prologue word holds and the reload would read. Every
    /// write of a GP-file register by the lowering is a publish, which goes
    /// through `mark_gp_reg_live` / `ls_publish` / `ls_drop_residency` and
    /// takes the previous owner's bit away, so a value the linear scan hands
    /// `dst` before the parameter's interval starts clears the fill and the
    /// arm reloads as before. The admission keeps that bookkeeping trivially
    /// complete on the only code between the fill and the arm: the parameter
    /// is in block 0 and only `Op::Param` / `Op::Const` nodes precede it there
    /// (straight-line, no merge, no call), and what else runs in between --
    /// the rest of the prologue, the entry poll and its outlined slow path --
    /// writes RAX/R10/R11, memory, or calls helpers that preserve the
    /// callee-saved file the GP file is made of (C ABI). `dst` is saved by the
    /// prologue before the fill (`ls_saved_gp` covers every register the scan
    /// handed out) and is never an incoming ABI register.
    ///
    /// Off under a MIR mode (its tiles publish on their own), the `int`
    /// poisoning stress mode (the arm writes the poisoned high half into the
    /// word and the register must read it back), and with
    /// `CRATONVM_JIT_IR_PARAM_HOME_ALIAS=0` (the arm then copies the word
    /// through RAX). Kill switch: `CRATONVM_JIT_IR_PARAM_REGISTER_FILL=0`,
    /// read per compile.
    fn plan_param_register_fills(&self, base: usize, reg_count: usize) -> Vec<(NodeId, u8, u8)> {
        let mut fills: Vec<(NodeId, u8, u8)> = Vec::new();
        if !ir_param_register_fill_enabled()
            || self.mir_mode != MirMode::Off
            || self.poison_int_high_on
            || !ir_param_home_alias_enabled()
        {
            return fills;
        }
        let Some(entry) = self.schedule.blocks.first() else {
            return fills;
        };
        for &n in &entry.nodes {
            let Some(node) = self.graph.nodes.get(n as usize) else {
                break;
            };
            let idx = match node.op {
                Op::Const(_) => continue,
                Op::Param(idx) => usize::from(idx),
                _ => break,
            };
            if !matches!(node.ty, IrType::Int | IrType::Long) || idx >= reg_count {
                continue;
            }
            let (Some(dst), Some(&src)) = (self.assigned_gpr(n), ENTRY_ABI_REGS.get(base + idx))
            else {
                continue;
            };
            if dst == src
                || ENTRY_ABI_REGS.contains(&dst)
                || !ir_gp_file().contains(&dst)
                || self.saved_gpr_bytes <= 0
                || !self.ls_saved_gp.get(dst as usize).copied().unwrap_or(false)
                || fills.iter().any(|&(m, d, _)| m == n || d == dst)
            {
                continue;
            }
            fills.push((n, dst, src));
        }
        fills
    }

    /// Did [`Self::emit_prologue`] fill `id`'s register, and does it still
    /// hold `id` (no publish into it since)? Round 14 wave 7 (lane callcost3,
    /// CC6-2; [`Self::plan_param_register_fills`]).
    fn param_register_filled(&self, id: NodeId) -> bool {
        self.param_register_fills.iter().any(|&(n, reg)| {
            n == id
                && self.resident_gpr(id) == Some(reg)
                && self.gp_reg_owner.get(reg as usize).copied().flatten() == Some(id)
        })
    }

    /// Does [`Self::emit_prologue`] skip its GC-only zeroing for this body?
    /// Round 11 wave 16 (lane irback; step 4 of
    /// `r11w14-rt-ir-lower-oop-free-frame-patch`).
    ///
    /// True exactly for a body [`Self::body_publishes_no_roots`] predicts
    /// reference-free, spelled without `frame_block` so it can be asked before
    /// `plan_frame_block` (the block is planned from these same two lists, so
    /// it is empty whenever they are, and the answer is identical). The
    /// artifact fill refuses a compile whose body this predicts reference-free
    /// but which is not then published `frame_holds_no_references`, so a
    /// skipped store is never left for a collector that would verify it.
    ///
    /// Kept: the thread-slot zeroing (null-guarded readers) and the
    /// safepoint-id zeroing (the innermost frame reads its raw slot for a line
    /// number before its first call). Kill switch:
    /// `CRATONVM_JIT_IR_REF_FREE_LEAN_PROLOGUE=0`, read per compile.
    fn lean_ref_free_prologue(&self) -> bool {
        self.ref_node_ids.is_empty()
            && self.ref_param_homes.is_empty()
            && cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_JIT_IR_REF_FREE_LEAN_PROLOGUE",
            )
    }

    /// Publish this frame's exact RBP into the precise-maps innermost-RBP
    /// mirror, exactly as the single-pass prologue does.
    ///
    /// Without it the collector cannot locate the frame at all:
    /// `moving_young_frame_coverage_complete` needs an address to resolve
    /// `sp_id_slot_off` and the map's slot offsets against, and
    /// `PreciseFrameInfo::exact_rbp` is only ever a snapshot of this mirror. An
    /// IR frame that never wrote it left the mirror holding `0`, and the
    /// verifier refused the whole cycle with `missing-exact-rbp` — before it
    /// ever looked at an oop map.
    ///
    /// That is why the relocation contract, though implemented and sound,
    /// changed nothing observable: with `CRATONVM_JIT_FORCE_C2=1` on the
    /// `IrEscapeProbe` the collector reported `cycles=0 coverage_fallbacks=14,
    /// missing-exact-rbp=14` — every young collection diverted for want of a
    /// nine-byte store, with the maps and the shadow publication both present
    /// and correct. Emitted after the ABI parameter stores for the same reason
    /// the single-pass backend does it there.
    fn emit_frame_record(&mut self) {
        if !crate::x64::precise_jit_maps_enabled() || self.frame_record == 0 {
            return;
        }
        let disp = crate::x64::inline_rbp_tls_disp();
        if disp != 0 {
            self.emit_mov_tls_disp32_rbp(disp as u32);
            // …and the identity of the frame that RBP names. Without it the GC
            // must decode the call that created this frame, which is impossible
            // when the caller reached us indirectly (`CALL R11` — every inline
            // cache hit).
            self.emit_frame_record_identity();
        } else {
            // No usable TLS displacement on this target: fall back to the
            // helper. Params are already in frame slots, so its caller-saved
            // clobbers cost nothing here.
            self.emit_mov_arg0_rbp();
            self.emit_mov_reg_imm64(RAX, self.frame_record as u64);
            self.buf.emit(&[0xFF, 0xD0]); // CALL RAX
        }
    }

    /// Restore this frame's RBP into the mirror after a call returned.
    ///
    /// A compiled callee publishes its OWN rbp on entry, so after it returns
    /// the mirror names the wrong (now-dead) frame. The single-pass backend
    /// republishes at every call site (`emit_post_call_rbp_republish`); the
    /// shared allocation stub does the same
    /// (`runtime_lowering::emit_post_call_frame_republish`). This is the IR
    /// tier's equivalent, and it must not disturb RAX — the callee's return
    /// value is still in it — which the inline TLS store satisfies for free.
    fn emit_post_call_frame_record(&mut self) {
        if !crate::x64::precise_jit_maps_enabled() || self.frame_record == 0 {
            return;
        }
        let disp = crate::x64::inline_rbp_tls_disp();
        if disp != 0 {
            self.emit_mov_tls_disp32_rbp(disp as u32);
            // The callee published its own identity on entry; restoring only
            // the RBP would leave the pair naming two different frames.
            self.emit_frame_record_identity();
            return;
        }
        self.buf.emit_byte(0x50); // PUSH RAX (preserve the Java return value)
        #[cfg(target_os = "windows")]
        const RESERVE: u8 = 40; // shadow space + alignment after the PUSH
        #[cfg(not(target_os = "windows"))]
        const RESERVE: u8 = 8; // restore 16-byte call-site alignment
        self.buf.emit(&[0x48, 0x83, 0xEC, RESERVE]); // SUB RSP, reserve
        self.emit_mov_arg0_rbp();
        self.emit_mov_reg_imm64(RAX, self.frame_record as u64);
        self.buf.emit(&[0xFF, 0xD0]); // CALL RAX
        self.buf.emit(&[0x48, 0x83, 0xC4, RESERVE]); // ADD RSP, reserve
        self.buf.emit_byte(0x58); // POP RAX
    }

    /// JIT r21 wave 1 (lane typecheck, TYPECHECK21-3): the array-target plan
    /// of a site whose resolved target `cid` is the array class `site_name`
    /// ([`typecheck_array_plan`]), or `None`. `CRATONVM_DBG_JITC` names each
    /// `[L...;` site.
    fn typecheck_array_plan_for(
        &self,
        site_name: Option<&str>,
        cid: u32,
        op: &str,
    ) -> Option<TypecheckArrayPlan> {
        let plan = typecheck_array_plan(&self.direct_helpers, site_name, cid);
        if crate::x64::dbg_jitc_enabled() && site_name.is_some_and(|n| n.starts_with("[L")) {
            match plan {
                Some(p) => eprintln!(
                    "[cratonvm-jitc] ir {op} array arm: target={cid} component={} object={} display={}",
                    p.component,
                    p.object_component,
                    p.display.is_some()
                ),
                None => eprintln!("[cratonvm-jitc] ir {op} array arm DECLINED: target={cid}"),
            }
        }
        plan
    }

    /// The array-target arm itself (TYPECHECK21-3), with RAX = a non-null
    /// receiver: a PLAIN object skips it (`JE` past it, to the caller's
    /// plain-object arms); an array is answered by
    /// [`typecheck_array_hit_bytes`], its hits appended to `hits` and its
    /// declines to `slow`. Writes RCX, R11 and the flags; RAX is preserved.
    fn emit_typecheck_array_arm(
        &mut self,
        plan: TypecheckArrayPlan,
        hits: &mut Vec<usize>,
        slow: &mut Vec<usize>,
    ) {
        // TEST BYTE [RAX+KIND_TAGS_BYTE_OFFSET], KIND_TAG_BYTE_MASK ; JE plain.
        self.buf.emit(&[
            0xF6,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ]);
        let plain = self.emit_jcc_rel32(0x84);
        self.note_rcx_written();
        let (bytes, edges, arm_hits) = typecheck_array_hit_bytes(plan);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        slow.extend(edges.into_iter().map(|e| at + e));
        hits.extend(arm_hits.into_iter().map(|h| at + h));
        self.patch_rel32_to_here(plain);
    }

    /// JIT r20 wave 11 (lane pAlloc; book `jit-r21-nio-proposals-w14-L4.md`
    /// W14L4-3; `CRATONVM_JIT_TYPECHECK_DISPLAY_ARM`, default ON, `=0` keeps
    /// the exact-class / seen-way arms alone): the supers display of the
    /// typecheck target `cid` (`vh_const_display`: a class with a published
    /// display, or any interface), or `None` -- then the site emits no
    /// display arm and is byte-identical to before. `CRATONVM_DBG_JITC` names
    /// each site.
    fn typecheck_display_for(&self, cid: u32, op: &str) -> Option<VhSubtypeDisplay> {
        if !typecheck_display_arm_enabled() {
            return None;
        }
        let display = vh_const_display(&self.direct_helpers, cid);
        if crate::x64::dbg_jitc_enabled() {
            match display {
                Some(d) => eprintln!(
                    "[cratonvm-jitc] ir {op} display arm: target={cid} interface={} depth={}",
                    d.interface, d.depth
                ),
                None => eprintln!(
                    "[cratonvm-jitc] ir {op} display arm DECLINED: target={cid} has no display"
                ),
            }
        }
        display
    }

    /// The display arm itself, with RAX = a non-null PLAIN object (the caller
    /// has screened null and arrays): falls through when the object's class
    /// is `cid` or a subtype of it per its published display, else jumps to
    /// one of the rel32 edges appended to `decline`. Writes RCX, R11 and the
    /// flags; RAX is preserved.
    ///
    /// Only a HIT is answered here. A miss always declines to the helper,
    /// because the helper's `true` is wider than the hierarchy (an instance-
    /// admitted proxy or `Unmodifiable*` stamp, a non-hierarchy id at or past
    /// `0x8000_0000`, the duplicate-class-name fallback), while its `true` for
    /// a class that the display proves a subtype is exactly JVMS 6.5. An id
    /// past the table's capacity (any of those synthetic ids) declines.
    ///
    /// Why the display can be trusted from compiled code without a lock, for
    /// every thread and across redefinition (the reasoning on
    /// `VhSubtypeDisplay` and `jit_realm::SupersDisplays`): a display is
    /// published once, Release-stored after its words, and never changed or
    /// freed for the VM's life; a table is never freed, and a reader racing a
    /// growth sees an older table that merely lacks the newest classes -- a
    /// decline; x86-64 loads are acquire, so a non-zero entry is a complete
    /// display. Class ids are never reused within a VM, and a redefinition
    /// cannot change a class's superclass or interfaces, so a display, once
    /// published, stays the class's hierarchy. An object whose class has no
    /// display yet (used before its `<clinit>` completed) declines.
    fn emit_typecheck_display_hit(
        &mut self,
        display: VhSubtypeDisplay,
        cid: u32,
        decline: &mut Vec<usize>,
    ) {
        self.note_rcx_written();
        // MOV ECX, DWORD [RAX] -- `ObjectHeader.class_id`, the `u32` at
        // offset 0 (zero-extends RCX).
        self.buf.emit(&[0x8B, 0x08]);
        let (bytes, edges) = typecheck_display_hit_bytes(display, cid);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
    }

    /// JIT r20 wave 17 (lane pAlloc2; `CRATONVM_JIT_TYPECHECK_DISPLAY_MISS`):
    /// [`Self::emit_typecheck_display_hit`] with the miss answered too
    /// ([`typecheck_display_answer_bytes`]), for an `instanceof` whose target
    /// the caller screened ([`Self::typecheck_display_miss_for`]). RAX = a
    /// non-null PLAIN object; appends the rel32 edges to the `1` (`one`), the
    /// `0` (`zero`) and the helper (`decline`). Writes RCX, R11 and the flags;
    /// RAX is preserved.
    fn emit_typecheck_display_answer(
        &mut self,
        display: VhSubtypeDisplay,
        cid: u32,
        decline: &mut Vec<usize>,
        one: &mut Vec<usize>,
        zero: &mut Vec<usize>,
    ) {
        self.note_rcx_written();
        // MOV ECX, DWORD [RAX] -- `ObjectHeader.class_id` (zero-extends RCX).
        self.buf.emit(&[0x8B, 0x08]);
        let latch = cratonvm_types::duplicate_class_name_seen_addr();
        let (bytes, edges, hit, miss) = typecheck_display_answer_bytes(display, cid, latch);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        one.push(at + hit);
        zero.push(at + miss);
    }

    /// JIT r20 wave 17 (lane pAlloc2): may this `instanceof` site answer a
    /// display miss inline? The target-side half of the proof
    /// ([`typecheck_display_answer_bytes`] checks the receiver side at run
    /// time): the switch is on, and the target is not one the
    /// `synthetic_implements` name rules can admit
    /// (`cratonvm_types::synthetic_targets`, proved exhaustive over those
    /// rules by the VM's own test). Every other non-hierarchy `true` of
    /// `jit_typecheck_resolve` is receiver-side (a lambda proxy id has no
    /// display; the instance-admitted shapes carry verdict `0`) or the
    /// duplicate-name rule the latch screens. `CRATONVM_DBG_JITC` names the
    /// site.
    fn typecheck_display_miss_for(&self, cid: u32, site_name: Option<&str>) -> bool {
        let ok = typecheck_display_miss_enabled()
            && site_name.is_some_and(|n| {
                !cratonvm_types::synthetic_targets::synthetic_implements_may_admit(n)
            });
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir instanceof display miss arm: target={cid} {}",
                if ok { "answered" } else { "DECLINED" }
            );
        }
        ok
    }

    /// The inline thin-lock fast path of an `Op::MonitorEnter` (`enter`) /
    /// `Op::MonitorExit` whose receiver's home is `obj_slot`: the single-pass
    /// tier's sequence, through the shared emitter
    /// `crate::runtime_lowering::emit_inline_thin_lock`. Returns the `JMP done`
    /// site the caller patches after its helper sequence, or `None` having
    /// emitted nothing.
    ///
    /// The thread comes from the `JIT_THREAD` mirror (one segment load), NOT
    /// from `shadow_thread_slot_off`, whose prologue fetch is erased in a
    /// method that publishes nothing; the frame slot is the fallback only on a
    /// target with no mirror, where a zero (erased) slot takes the helper.
    ///
    /// Census: `CRATONVM_DBG_JITC` prints one `[cratonvm-jitc] ir thin-lock`
    /// line per site, emitted or declined with the reason, so a run can tell
    /// "the inline path is in the code" from "it never compiled". Under the
    /// same flag an emitted site also bumps the thread's inline-hit / helper-fall
    /// counters (`[monitor-inline census]`), as the single-pass copy does.
    fn emit_monitor_fast_path(&mut self, enter: bool, obj_slot: i32) -> Option<usize> {
        use crate::runtime_lowering::ThinLockThread;
        let op = if enter { "monitorenter" } else { "monitorexit" };
        let outcome = if !crate::runtime_lowering::inline_thin_lock_enabled() {
            Err("CRATONVM_MONITOR_FASTPATH=0")
        } else {
            let tls = crate::x64::jit_thread_tls_disp();
            let thread = if tls != 0 {
                ThinLockThread::Tls(u32::try_from(tls).unwrap_or(0))
            } else if self.get_current_thread != 0 && self.shadow_thread_slot_off > 0 {
                ThinLockThread::Frame(self.shadow_thread_slot_off)
            } else {
                ThinLockThread::Tls(0)
            };
            crate::runtime_lowering::emit_inline_thin_lock(
                &mut self.buf,
                enter,
                obj_slot,
                self.monitor_block_off,
                thread,
                crate::x64::dbg_jitc_enabled(),
            )
        };
        if crate::x64::dbg_jitc_enabled() {
            match outcome {
                Ok(_) => eprintln!(
                    "[cratonvm-jitc] ir thin-lock {op} bci={} emitted",
                    self.cur_bci
                ),
                Err(why) => eprintln!(
                    "[cratonvm-jitc] ir thin-lock {op} bci={} declined: {why}",
                    self.cur_bci
                ),
            }
        }
        outcome.ok()
    }

    /// Put THIS frame's identity back after a shared `runtime_lowering` stub.
    ///
    /// Round 11 (irlower). `runtime_lowering::emit_post_call_frame_republish`
    /// -- the tail of the monitor, allocation and constant-pool stubs -- is
    /// shared code that does not know which method it was emitted into, so on
    /// the inline-TLS shape it restores RBP and writes `0` as the compile id.
    /// This tier then left that `0` standing until its next own republish, and
    /// every GC point in between (the next allocation's helper, a back-edge
    /// poll, another monitor) found no published identity: the collector fell
    /// back to decoding the call that entered this frame, which fails for every
    /// frame entered through `CALL R11` (each inline-cache hit), and the moving
    /// young collection was refused. The identity store writes no register and
    /// no flag. Same condition as the stub's own zeroing: a frame record and an
    /// inline RBP displacement (`emit_frame_record_identity` adds the id half).
    fn emit_identity_after_shared_stub(&mut self) {
        if self.frame_record != 0 && crate::x64::inline_rbp_tls_disp() != 0 {
            self.emit_frame_record_identity();
        }
    }

    /// [`Self::emit_post_call_frame_record`] for a SELF-RECURSIVE direct call
    /// (`emit_self_recursive_call`): on the inline-TLS shape, the RBP store
    /// alone. Answers whether it elided the identity half.
    ///
    /// Round 9 wave 3 (invoke2 X1), the IR twin of the single-pass N1 edit in
    /// `x64/op_invoke.rs`. The callee is this buffer's own entry
    /// (`patch_self_calls`), whose prologue publishes THIS compile's id, and
    /// every writer inside it restores that same id before a normal return
    /// (its own post-call republishes, the Rust dispatch brackets). One
    /// segment-relative `MOV dword gs:[disp32], imm32` per recursive call.
    /// The helper-call shape (no inline displacement) is unchanged: the helper
    /// writes both halves in one call.
    fn emit_post_self_call_frame_record(&mut self) -> bool {
        if !crate::x64::precise_jit_maps_enabled() || self.frame_record == 0 {
            return false;
        }
        let disp = crate::x64::inline_rbp_tls_disp();
        if disp == 0 || self.inline_cm_tls_disp == 0 {
            self.emit_post_call_frame_record();
            return false;
        }
        self.emit_mov_tls_disp32_rbp(disp as u32);
        true
    }

    /// `MOV <arg0>, RBP` — for the helper form of the frame record, which is
    /// reached only when no inline TLS displacement could be probed.
    fn emit_mov_arg0_rbp(&mut self) {
        const RBP_REG: u8 = 5;
        let dest = CALL_ARG_REGS[0];
        // REX.W (+ REX.B when the destination is R8..R15), MOV r/m64, r64.
        self.buf
            .emit_byte(0x48 | if dest >= 8 { 0x01 } else { 0x00 });
        self.buf.emit_byte(0x89);
        self.buf.emit_byte(0xC0 | (RBP_REG << 3) | (dest & 7));
    }

    /// `MOV <seg>:[disp32], RBP` — the 9-byte inline frame-record store.
    ///
    /// Byte-identical to the single-pass backend's `emit_mov_tls_disp32_rbp`;
    /// both must write the SAME slot, since `inline_rbp_tls_disp()` is the one
    /// source of truth the VM-side mirror accessor reads back.
    /// `MOV RAX, gs:[disp32]` (`fs:` on Linux): the one-instruction thread
    /// fetch through the `JIT_THREAD` mirror (`x64::jit_thread_tls_disp`).
    fn emit_mov_rax_tls_disp32(&mut self, disp32: u32) {
        self.buf
            .emit_byte(crate::x64::inline_rbp_tls_segment_prefix());
        self.buf.emit_byte(0x48); // REX.W
        self.buf.emit_byte(0x8B); // MOV r64, r/m64
        self.buf.emit_byte(0x04); // ModRM: reg=RAX, r/m=SIB
        self.buf.emit_byte(0x25); // SIB: [disp32] absolute
        self.buf.emit(&disp32.to_le_bytes());
    }
    fn emit_mov_tls_disp32_rbp(&mut self, disp32: u32) {
        self.buf
            .emit_byte(crate::x64::inline_rbp_tls_segment_prefix());
        self.buf.emit_byte(0x48); // REX.W
        self.buf.emit_byte(0x89); // MOV r/m64, r64
        self.buf.emit_byte(0x2C); // ModRM: reg=RBP, r/m=SIB
        self.buf.emit_byte(0x25); // SIB: [disp32] absolute
        self.buf.emit(&disp32.to_le_bytes());
    }

    /// `MOV dword <seg>:[disp32], imm32` — the identity half of the frame
    /// record, emitted immediately after every RBP store so the two always
    /// describe the same frame.
    ///
    /// 32-bit and immediate, so it needs no scratch register: the post-call
    /// republish path runs with the callee's return value live in RAX. Byte
    /// layout matches the single-pass `emit_mov_tls_disp32_imm32`.
    fn emit_frame_record_identity(&mut self) {
        if self.inline_cm_tls_disp == 0 {
            return;
        }
        self.buf
            .emit_byte(crate::x64::inline_rbp_tls_segment_prefix());
        self.buf.emit_byte(0xC7); // MOV r/m32, imm32
        self.buf.emit_byte(0x04); // ModRM: /0, r/m=SIB
        self.buf.emit_byte(0x25); // SIB: [disp32] absolute
        self.buf
            .emit(&(self.inline_cm_tls_disp as u32).to_le_bytes());
        self.buf.emit(&self.compile_id.id().to_le_bytes());
    }

    /// JIT r20 wave 11 (lane pAlloc; book `jit-r19-concat5-proposals.md`,
    /// "Review notes"; `CRATONVM_JIT_IR_INLINE_TLAB_TLS_THREAD`, default ON,
    /// `=0` restores the frame slot): the `thread_tls_disp` of an inline TLAB
    /// plan. A body that publishes no root has its prologue thread fetch erased
    /// ([`Self::finish_lazy_thread_fetch`], or never emitted,
    /// [`Self::fetch_current_thread`]), so `shadow_thread_slot_off` keeps the
    /// prologue's zero and every bump that reads it takes its stub -- the
    /// inline path never ran in exactly the lean allocating bodies it was built
    /// for. The `JIT_THREAD` mirror is what the fetch itself reads and what the
    /// IR thin lock already reads ([`Self::emit_monitor_fast_path`]), so the
    /// thread is the same pointer; only its availability changes. Gated on
    /// the same condition the frame path needs (a thread helper and a slot),
    /// so a configuration with neither still declines the same way.
    fn ir_tlab_thread_tls_disp(&mut self) -> u32 {
        let tls = if self.get_current_thread != 0
            && self.shadow_thread_slot_off > 0
            && ir_inline_tlab_tls_thread_enabled()
        {
            u32::try_from(crate::x64::jit_thread_tls_disp()).unwrap_or(0)
        } else {
            0
        };
        if tls != 0 {
            self.tlab_tls_thread_plans = self.tlab_tls_thread_plans.saturating_add(1);
        } else {
            self.tlab_frame_thread_plans = self.tlab_frame_thread_plans.saturating_add(1);
        }
        tls
    }

    /// The engagement control of [`Self::ir_tlab_thread_tls_disp`], called
    /// for a body whose thread fetch is erased (or was never emitted): under
    /// `CRATONVM_DBG_JITC` one `[cratonvm-jitc] ir lean body` line naming how
    /// many of its inline TLAB plans read the mirror (`thread=tls`, the bump
    /// can engage) and how many read the zeroed frame slot (`thread=frame`,
    /// the stub on every execution). `=0` of the switch prints `tls 0`.
    fn note_lean_body_tlab_thread_census(&self) {
        if (self.tlab_tls_thread_plans != 0 || self.tlab_frame_thread_plans != 0)
            && crate::x64::dbg_jitc_enabled()
        {
            eprintln!(
                "[cratonvm-jitc] ir lean body: thread fetch erased; inline-TLAB plans thread=tls {} thread=frame {} (frame = stub on every execution)",
                self.tlab_tls_thread_plans, self.tlab_frame_thread_plans
            );
        }
    }

    /// Cache `*mut JvmThread` in its reserved slot.
    ///
    /// Emitted AFTER the ABI parameter stores: the helper clobbers the
    /// caller-saved registers the parameters arrive in, and by this point they
    /// are already in frame slots. A zero helper address (the JIT unit tests'
    /// stub table) leaves the slot untouched, and every shadow site is gated on
    /// the same condition, so such a method is consistently untracked rather
    /// than dereferencing a pointer that was never fetched.
    fn fetch_current_thread(&mut self) {
        if self.get_current_thread == 0 || self.shadow_thread_slot_off <= 0 || !self.reloc_emit_on {
            return;
        }
        // Round 11 wave 13 (lane fib): a body that can never publish a root
        // does not emit the span `finish_lazy_thread_fetch` would jump over.
        if self.body_publishes_no_roots() {
            return;
        }
        let start = self.buf.pos();
        // 2026-09-02: one `mov rax, gs:[disp]` through the `JIT_THREAD`
        // mirror where the VM publishes it; the helper call otherwise. Both
        // stay inside the erasable span.
        let tls_disp = crate::x64::jit_thread_tls_disp();
        if tls_disp != 0 {
            self.emit_mov_rax_tls_disp32(tls_disp as u32);
        } else {
            self.emit_mov_reg_imm64(RAX, self.get_current_thread as u64);
            self.buf.emit(&[0xFF, 0xD0]); // CALL RAX
        }
        self.store_rax(self.shadow_thread_slot_off);
        // Capture the entry watermark, inside the erasable span: a method that
        // publishes nothing has no push to unwind, so the capture goes away
        // with the fetch and the (zeroed) thread slot makes every exit's
        // restore skip through its null guard.
        if self.shadow_savetop_slot_off > 0 {
            let ss_top = self.shadow_off_in_thread;
            // Round 16 wave 17 (lane frames2, FR16P-3,
            // `CRATONVM_JIT_IR_PROLOGUE_THREAD_IN_RAX`, default OFF): RAX
            // still holds the word `store_rax` just wrote -- the TLS load or
            // the helper's return value -- since no current definition is
            // published from the prologue (`publish_def_at_store` and the
            // carry only act on `cur_def`), so copy it rather than reload it.
            if ir_prologue_thread_in_rax_enabled() && self.cur_def.is_none() {
                self.buf.emit(&[0x49, 0x89, 0xC2]); // MOV R10, RAX
            } else {
                // MOV R10, [rbp - thread_slot]
                self.buf.emit(&[0x4C, 0x8B, 0x95]);
                self.buf.emit(&(-self.shadow_thread_slot_off).to_le_bytes());
            }
            // TEST R10, R10 ; JE skip
            self.buf.emit(&[0x4D, 0x85, 0xD2]);
            self.buf.emit(&[0x0F, 0x84]);
            let skip = self.buf.pos();
            self.buf.emit(&[0, 0, 0, 0]);
            // MOV R11, [R10 + ss_top] ; MOV [rbp - savetop], R11
            self.buf.emit(&[0x4D, 0x8B, 0x9A]);
            self.buf.emit(&ss_top.to_le_bytes());
            self.buf.emit(&[0x4C, 0x89, 0x9D]);
            self.buf
                .emit(&(-self.shadow_savetop_slot_off).to_le_bytes());
            self.patch_rel32_to_here(skip);
        }
        self.thread_fetch_span = Some((start, self.buf.pos()));
    }

    /// Lazy prologue: erase the thread fetch when nothing published.
    ///
    /// The fetch is a `CALL` on the ENTRY path of every IR method, and most
    /// methods publish nothing — they hold no live reference across a call, or
    /// make no call at all. Paying a helper call per invocation for a slot that
    /// is then never read is what made the first publication attempt regress
    /// `ZonedDateTimeTest` 302 s -> >1200 s while leaving shallow-stack
    /// `ASTParserLoadingTest` untouched: the cost scales with how often methods
    /// are ENTERED, not with stack depth.
    ///
    /// The single-pass backend solves this the same way (`shadow_pushed_any`).
    /// Erasing in place rather than shifting the body keeps every
    /// already-recorded offset — branch patches, deopt points, oop-map native
    /// pcs — valid, which is why this is an erase and not a removal.
    ///
    /// It erases with a JUMP over the span, not with a run of `0x90`. This
    /// half was missing here while the single-pass backend had it, and the
    /// asymmetry cost real time: the span is ~46 bytes, so every IR method
    /// that published nothing retired 46 NOPs on entry, on every invocation.
    /// `CratonBench fib` — a two-line static method entered 2.27e9 times —
    /// paid it 2.27e9 times and ran ~2x slower on the IR tier than on the
    /// single-pass body it displaced. Both backends now share
    /// [`ExecutableBuffer::erase_range_with_jump_over`] so they cannot drift
    /// apart again.
    fn finish_lazy_thread_fetch(&mut self) {
        debug_assert!(
            !(self.shadow_pushed_any && self.body_publishes_no_roots()),
            "a body predicted to publish no root pushed one; its prologue has no thread fetch"
        );
        if self.shadow_pushed_any {
            return;
        }
        self.note_lean_body_tlab_thread_census();
        if let Some((start, end)) = self.thread_fetch_span.take() {
            // Jumping over the span is only safe while nothing branches INTO
            // its interior: a site patched at `start + 1` would overwrite the
            // rel8 displacement, and one that TARGETS `start + 1` would decode
            // the displacement as an opcode. Under the old NOP fill neither
            // was fatal, so the invariant was never stated — it holds because
            // the span is emitted at the top of the prologue, before any block
            // is lowered, so every recorded patch site is past `end`.
            //
            // This runs before `patch_branches` / `patch_self_calls`, so both
            // lists are still intact here and the invariant is checkable
            // rather than merely true.
            debug_assert!(
                self.branch_patches
                    .iter()
                    .all(|&(pos, _)| pos < start || pos >= end)
                    && self
                        .self_call_patches
                        .iter()
                        .all(|&pos| pos < start || pos >= end),
                "a patch site landed inside the erased thread-fetch span {start}..{end}; \
                 jumping over it would corrupt that patch (or its target)"
            );
            self.buf.erase_range_with_jump_over(start, end);
        }
        // Round 11 wave 11 (lane `calls`, `CratonBench fib`): every exit's
        // shadow-`top` restore, on the same condition. With the fetch erased
        // the thread slot keeps the prologue's zero for the whole activation --
        // the fetch was its only writer -- so each restore's `TEST R10, R10;
        // JE` always skipped, after a load: three instructions on every return
        // of every method that publishes nothing (a leaf, or `fib`, which has
        // no reference at all). One taken `JMP` now, the path those
        // instructions always took. Same interior-branch invariant as the fetch
        // span: the restore's only branch is its own `JE`, already patched to
        // the span's end, and no recorded patch site lies inside it.
        let restores = std::mem::take(&mut self.savetop_restore_spans);
        for (start, end) in restores {
            debug_assert!(
                self.branch_patches
                    .iter()
                    .all(|&(pos, _)| pos < start || pos >= end)
                    && self
                        .self_call_patches
                        .iter()
                        .all(|&pos| pos < start || pos >= end),
                "a patch site landed inside an erased shadow-top restore {start}..{end}"
            );
            self.buf.erase_range_with_jump_over(start, end);
        }
    }

    /// Publish every live oop of this safepoint onto the thread's shadow stack,
    /// so a relocating collector can rewrite each one in place.
    ///
    /// This is the half that `moving_young_coverage_complete` actually asserts.
    /// The oop map names the slots; only this makes them *rewritable*, because
    /// `scan_oop_slots` yields `ObjectRef` values (marking roots) while
    /// `published_shadow_values` yields the homes the collector writes back to.
    ///
    /// Registers: R10 (thread), R11 (running top), RCX (value temp). All
    /// caller-saved and free here — this runs at the top of the `Op::Call` arm,
    /// before any argument staging or ABI register loading.
    ///
    /// Returns whether the push was actually emitted.
    ///
    /// gci i9/ng (i8/nt review item 6): gated on
    /// [`crate::x64::shadow_stack_maps_enabled`], like the frame block
    /// (`plan_frame_block`) and the single-pass backend (whose shadow slots are
    /// not even reserved without it). With shadow emission off
    /// (`CRATONVM_JIT_MY_SHADOW_EMISSION=0`) the VM never allocates the
    /// thread's shadow stack (`top == end == 0`), so every push this tier
    /// emitted took the overflow bail: it stored nothing, but it bumped
    /// `SHADOW_OVERFLOW_COUNT` and so read as `shadow-stack-push-bailed` (47 of
    /// 358 pauses on the vi5g-g1r SH0 rows) and fed the shadow-bail refusal. Not
    /// emitting it makes the map's claim honest instead
    /// (`moving_young_coverage_complete` needs `published`, so the frame now
    /// refuses as `MAP_NOT_COMPLETE`, where the bail refused before). The
    /// default (shadow emission on) is byte-identical.
    fn emit_shadow_push(&mut self, offsets: &[i16]) -> bool {
        if !Self::shadow_push_emits(
            self.get_current_thread,
            self.shadow_thread_slot_off,
            self.shadow_savebase_slot_off,
            offsets.len(),
            crate::x64::shadow_stack_maps_enabled,
        ) {
            return false;
        }
        let ss_top = self.shadow_off_in_thread;
        // MOV R10, [rbp - thread_slot]
        self.buf.emit(&[0x4C, 0x8B, 0x95]);
        self.buf.emit(&(-self.shadow_thread_slot_off).to_le_bytes());
        // TEST R10, R10 ; JE skip  — a null thread means "untracked", exactly
        // as in the single-pass backend; the reload's guard is symmetric.
        self.buf.emit(&[0x4D, 0x85, 0xD2]);
        self.buf.emit(&[0x0F, 0x84]);
        let skip = self.buf.pos();
        self.buf.emit(&[0, 0, 0, 0]);
        // MOV R11, [R10 + ss_top]      (current top)
        self.buf.emit(&[0x4D, 0x8B, 0x9A]);
        self.buf.emit(&ss_top.to_le_bytes());
        // OVERFLOW GUARD (`ShadowStack::END_OFFSET`) — see the matching comment
        // in the single-pass backend. Without it a push that runs past the end
        // of the 2 MiB buffer keeps storing into the allocator arena behind it.
        // LEA leaves flags alone, so the bump is undone between the CMP and the
        // branch and R11 stays the only scratch. `top == end` is the legal
        // exactly-full state, so the test is strictly-above.
        let need = (offsets.len() as i32) * 8; // Cast: x86-64 disp32
        let overflow = if crate::shadow_end_guard_enabled() {
            // LEA R11,[R11+need] ; CMP R11,[R10+end] ; LEA R11,[R11-need]
            self.buf.emit(&[0x4D, 0x8D, 0x9B]);
            self.buf.emit(&need.to_le_bytes());
            self.buf.emit(&[0x4D, 0x3B, 0x9A]);
            self.buf.emit(&(ss_top + 8).to_le_bytes());
            self.buf.emit(&[0x4D, 0x8D, 0x9B]);
            self.buf.emit(&(-need).to_le_bytes());
            // JA overflow
            self.buf.emit(&[0x0F, 0x87]);
            let p = self.buf.pos();
            self.buf.emit(&[0, 0, 0, 0]);
            Some(p)
        } else {
            None
        };
        // MOV [rbp - savebase], R11    (base of THIS push)
        self.buf.emit(&[0x4C, 0x89, 0x9D]);
        self.buf
            .emit(&(-self.shadow_savebase_slot_off).to_le_bytes());
        for &off in offsets {
            // MOV RCX, [rbp - off] ; MOV [R11], RCX ; LEA R11, [R11 + 8]
            self.buf.emit(&[0x48, 0x8B, 0x8D]);
            self.buf.emit(&(-(off as i32)).to_le_bytes());
            self.buf.emit(&[0x49, 0x89, 0x0B]);
            self.buf.emit(&[0x4D, 0x8D, 0x5B, 0x08]);
        }
        // MOV [R10 + ss_top], R11      (publish the new top)
        self.buf.emit(&[0x4D, 0x89, 0x9A]);
        self.buf.emit(&ss_top.to_le_bytes());
        if let Some(overflow) = overflow {
            // JMP done
            self.buf.emit_byte(0xE9);
            let done = self.buf.pos();
            self.buf.emit(&[0, 0, 0, 0]);
            self.patch_rel32_to_here(overflow);
            // Overflow bail: nothing was stored and `top` is untouched. R11
            // still holds the pre-push `top`; tag bit 0 (slot addresses are
            // 8-aligned) so the paired reload skips its value-restore and only
            // puts `top` back.
            self.buf.emit(&[0x49, 0x83, 0xCB, 0x01]); // OR R11, 1
            self.buf.emit(&[0x4C, 0x89, 0x9D]); // MOV [rbp - savebase], R11
            self.buf
                .emit(&(-self.shadow_savebase_slot_off).to_le_bytes());
            self.emit_shadow_overflow_note();
            self.patch_rel32_to_here(done);
        }
        self.patch_rel32_to_here(skip);
        self.shadow_pushes += 1;
        true
    }

    /// gci i9/ng: does [`Self::emit_shadow_push`] emit anything? The wiring
    /// (thread helper, the two reserved slots), something to publish, and the
    /// shadow-stack codegen on (`shadow_maps_on`, read last and only when the
    /// rest holds). Pure, so the gate is testable without the process-wide
    /// cache.
    fn shadow_push_emits(
        get_current_thread: usize,
        thread_slot_off: i32,
        savebase_slot_off: i32,
        n_offsets: usize,
        shadow_maps_on: impl FnOnce() -> bool,
    ) -> bool {
        get_current_thread != 0
            && thread_slot_off > 0
            && savebase_slot_off > 0
            && n_offsets > 0
            && shadow_maps_on()
    }

    /// `CRATONVM_JIT_IR_SHADOW_FRAME_BLOCK=0` — publish per call (push every
    /// home's value before the call, copy it back after) instead of once per
    /// activation through the frame block. Default on; the switch is the
    /// one-binary A/B and the kill switch.
    fn frame_block_enabled() -> bool {
        #[cfg(test)]
        if let Some(on) = FRAME_BLOCK_FORCE.with(|c| c.get()) {
            return on;
        }
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SHADOW_FRAME_BLOCK")
    }

    /// Largest frame block worth publishing. The block costs one store per
    /// home the first time an activation reaches a safepoint, where the
    /// per-call form costs a push and a copy-back per LIVE home per call; past
    /// this many homes a method that reaches one safepoint per activation
    /// would pay more for the block than it saves.
    const FRAME_BLOCK_MAX_HOMES: usize = 32;

    /// Ceiling for [`Self::frame_block_max_homes`]. A block of this many homes
    /// is 8 KiB of shadow stack, far inside the per-push bound the VM's bail
    /// verdict assumes (`SHADOW_BAIL_MAX_PUSH_BYTES`), and the frame itself is
    /// capped at `DEFAULT_MAX_FRAME_BYTES` (4096 words) anyway.
    const FRAME_BLOCK_MAX_HOMES_CEILING: usize = 1024;

    /// `CRATONVM_JIT_IR_FRAME_BLOCK_MAX_HOMES` (round 14 wave 1, lane chain;
    /// `r14w1-chain-frame-block-home-cap-patch-FIXED-20260929.md`): the cap
    /// [`Self::plan_frame_block`] applies, default [`Self::FRAME_BLOCK_MAX_HOMES`]
    /// (byte-identical), clamped to [`Self::FRAME_BLOCK_MAX_HOMES_CEILING`]; zero
    /// or junk keeps the default. Past the cap a body publishes its roots at
    /// EVERY GC point (push and copy back every defined home), which costs a
    /// one-activation kernel with a call in its loop 2N memory operations per
    /// call; a larger block costs ~14 bytes of code per home per GC point.
    /// Read per compile.
    fn frame_block_max_homes() -> usize {
        cratonvm_types::flags::resolve_capped_usize(
            "CRATONVM_JIT_IR_FRAME_BLOCK_MAX_HOMES",
            "IR frame block home cap",
            Self::FRAME_BLOCK_MAX_HOMES,
            Self::FRAME_BLOCK_MAX_HOMES_CEILING,
        )
    }

    /// Decide whether this body publishes through a frame block, and if so
    /// which words the block names (`frame_block`). Must run before the
    /// prologue zeroes the reference homes, because the block changes which
    /// ones it has to zero.
    ///
    /// The block names every word a safepoint map of this body can name: the
    /// reference-parameter homes and the planned slot of every `Ref` node
    /// (phis included). Publishing a word from the first safepoint to the
    /// return is sound only because each of those words holds a reference or
    /// null for that whole span:
    ///
    ///   * the colouring never lets a primitive into a reference colour
    ///     (`SlotPlan::prim_colors`), so a word the block names cannot hold
    ///     an `int` the collector would rewrite;
    ///   * the prologue zeroes every one of them that it does not write itself
    ///     — `zero_ref_value_slots` WITHOUT its entry-block refinement, whose
    ///     argument ("a safepoint before the definition does not publish it")
    ///     does not hold for a block published whole;
    ///   * every exit restores the entry watermark, retracting the block.
    ///
    /// And it is used only where the collector will rewrite through it: the
    /// VM remaps the shadow stack exactly when `shadow_stack_maps_enabled`
    /// agrees, which is also when its frame walk leaves a published block's
    /// homes to it (`conservative_roots::remap_one_jit_frame`).
    fn plan_frame_block(&mut self) {
        self.frame_block.clear();
        // gen r5w3/live7: a block publishes EVERY reference home for the whole
        // activation, so a home the precise-liveness claim proves dead at a
        // call would still be a precise root through it. Under
        // `CRATONVM_JIT_PRECISE_FRAME_LIVENESS` the body publishes per call
        // instead -- the `CRATONVM_JIT_IR_SHADOW_FRAME_BLOCK=0` form, which
        // pushes only the homes the map names (`emit_safepoint_map`).
        if self.frame_liveness_on {
            return;
        }
        if !Self::frame_block_enabled()
            || !crate::x64::shadow_stack_maps_enabled()
            || !self.reloc_emit_on
            || !cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_ZERO_REF_SLOTS")
            || self.sp_id_slot_off <= 0
            || self.get_current_thread == 0
            || self.shadow_thread_slot_off <= 0
            || self.shadow_savebase_slot_off <= 0
            || self.shadow_savetop_slot_off <= 0
        {
            return;
        }
        let mut offs: Vec<i16> = self.ref_param_homes.clone();
        for (id, n) in self.graph.nodes.iter().enumerate() {
            if n.ty != IrType::Ref || matches!(n.op, Op::Dead) {
                continue;
            }
            let Some(color) = self.slot_plan.node_color.get(id).copied().flatten() else {
                continue;
            };
            // `planned_slot_off`'s arithmetic, as `zero_ref_value_slots` does it.
            let Some(off) = i32::try_from(u64::from(color).saturating_mul(8))
                .ok()
                .and_then(|d| self.first_spill.checked_add(d))
            else {
                return;
            };
            if off <= 0 || off > self.spill_cap_off {
                continue;
            }
            let Ok(off) = i16::try_from(off) else {
                return;
            };
            offs.push(off);
        }
        offs.sort_unstable();
        offs.dedup();
        if offs.is_empty() {
            return;
        }
        // Round 15 wave 1 (lane chain): a GC point inside a loop runs the
        // per-GC-point fallback once per ITERATION (a push and a copy-back per
        // defined home), where the block costs one store per home per
        // ACTIVATION. The chain arm's kernels (`CratonBench hashmap`, the
        // reference homes of the spliced `putVal`/`getNode`) are exactly this
        // shape: -10 % with the cap raised to 128 (round 14 w1b bench).
        let base_cap = Self::frame_block_max_homes();
        let cap = Self::frame_block_cap_for(self.graph, self.schedule, offs.len(), base_cap);
        if offs.len() > cap {
            // Round 14 wave 1 (lane chain): say so, or the per-GC-point
            // fallback shows only as code size.
            if self.dbg_ir_reloc_on {
                eprintln!(
                    "[ir-reloc] frame block refused: {} reference homes (cap {cap}); \
                     publishing per GC point",
                    offs.len()
                );
            }
            return;
        }
        if offs.len() > base_cap && self.dbg_ir_reloc_on {
            eprintln!(
                "[ir-reloc] frame block admitted by the loop cap: {} reference homes \
                 (cap {base_cap}, loop cap {cap})",
                offs.len()
            );
        }
        self.frame_block_shared = Self::frame_block_shared_publish_enabled();
        self.frame_block = offs;
    }

    /// Round 15 wave 1 (lane chain): the cap a body with a GC point inside a
    /// loop gets under [`Self::frame_block_loop_cap_enabled`] (or the
    /// `CRATONVM_JIT_IR_FRAME_BLOCK_MAX_HOMES` knob, when that is larger).
    const FRAME_BLOCK_LOOP_MAX_HOMES: usize = 128;

    /// `CRATONVM_JIT_IR_FRAME_BLOCK_LOOP_CAP` — default ON; `0` restores the
    /// flat cap. Read per compile.
    fn frame_block_loop_cap_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_FRAME_BLOCK_LOOP_CAP")
    }

    /// `CRATONVM_JIT_IR_FRAME_BLOCK_SHARED_PUBLISH` — default ON; `0` emits
    /// the whole publication inline at every safepoint again. See
    /// [`Self::emit_frame_block_ensure`]. Read per compile.
    fn frame_block_shared_publish_enabled() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_FRAME_BLOCK_SHARED_PUBLISH")
    }

    /// The home cap [`Self::plan_frame_block`] applies to a body with `homes`
    /// reference homes, and whether a block of that many is taken at all.
    /// The one rule both the plan and the buffer reservation read.
    /// `cap` is [`Self::frame_block_max_homes`], read once by the caller.
    fn frame_block_cap_for(graph: &Graph, schedule: &Schedule, homes: usize, cap: usize) -> usize {
        if homes > cap
            && Self::frame_block_loop_cap_enabled()
            && ir_gc_point_in_loop(graph, schedule)
        {
            cap.max(Self::FRAME_BLOCK_LOOP_MAX_HOMES)
        } else {
            cap
        }
    }

    /// Publish the frame block if this activation has not yet done so. The
    /// frame-block counterpart of [`Self::emit_shadow_push`], emitted at every
    /// safepoint and executed once per activation.
    ///
    /// The saved-base word is the "already published" flag: the prologue zeroes
    /// it, this sets it to the block's base, and an overflow sets it to the
    /// pre-push `top` with bit 0 set — non-zero, so no later safepoint retries,
    /// and tagged, so the collector's frame walk knows the homes are NOT on the
    /// shadow stack and keeps rewriting them itself.
    ///
    /// Registers: R10 (thread), R11 (block base), RCX (entry temp) — the same
    /// three, free at the same point, as the per-call push.
    ///
    /// Round 15 wave 1 (lane chain): under
    /// `CRATONVM_JIT_IR_FRAME_BLOCK_SHARED_PUBLISH` (default ON) only the
    /// once-per-activation test stays at the safepoint —
    /// `CMP [rbp - savebase], 0 ; JNE +5 ; CALL publish` (15 bytes) — and the
    /// publication itself (~50 bytes plus 14 per home) is one subroutine per
    /// body, [`Self::emit_frame_block_publish_stub`]. The inline form repeated
    /// it at every GC point, which is GC points x homes of code (the chain
    /// arm's `HashMap.putVal`: tens of KB). The subroutine touches only R10,
    /// R11, RCX, the frame through `rbp`, and the shadow stack; it calls
    /// nothing (the overflow note's `PUSH RAX`/`POP RAX` is balanced, as it
    /// already was inline) and cannot fault, so the return address it has on
    /// the machine stack is never seen by a stack walk.
    fn emit_frame_block_ensure(&mut self) -> bool {
        if self.frame_block.is_empty() {
            return false;
        }
        let savebase = -self.shadow_savebase_slot_off;
        // CMP qword [rbp - savebase], 0
        self.buf.emit(&[0x48, 0x83, 0xBD]);
        self.buf.emit(&savebase.to_le_bytes());
        self.buf.emit_byte(0);
        if self.frame_block_shared {
            // JNE +5 (over the CALL) ; CALL publish
            self.buf.emit(&[0x75, 0x05]);
            self.buf.emit_byte(0xE8);
            let rel_at = self.buf.pos();
            match self.frame_block_stub_at {
                Some(stub) => {
                    // A site lowered after the subroutine: a backward call.
                    let rel = i32::try_from(stub as i64 - (rel_at as i64 + 4));
                    if rel.is_err() {
                        self.latch_bailout(Bailout::new(BailoutReason::Internal(
                            "ir_lower: a frame-block publication call is out of rel32 range",
                        )));
                    }
                    self.buf.emit(&rel.unwrap_or(0).to_le_bytes());
                }
                None => {
                    self.frame_block_call_patches.push(rel_at);
                    self.buf.emit(&[0, 0, 0, 0]);
                }
            }
            return true;
        }
        // JNE done
        self.buf.emit(&[0x0F, 0x85]);
        let done_published = self.buf.pos();
        self.buf.emit(&[0, 0, 0, 0]);
        let dones = self.emit_frame_block_publication();
        for p in dones {
            self.patch_rel32_to_here(p);
        }
        self.patch_rel32_to_here(done_published);
        true
    }

    /// Round 15 wave 1 (lane chain): the shared publication subroutine of a
    /// `frame_block_shared` body, after the body, and every `CALL` lowered
    /// before it patched to it. Emits nothing for any other body. The
    /// sequence is the inline ensure's, verbatim, ending in `RET` where the
    /// inline form fell through.
    fn emit_frame_block_publish_stub(&mut self) {
        if self.frame_block_stub_at.is_some() || self.frame_block_call_patches.is_empty() {
            // Already emitted, or no safepoint published: nothing calls it.
            return;
        }
        if !self.frame_block_shared || self.frame_block.is_empty() {
            // A `CALL` with nothing to call: fail closed rather than leave a
            // zero `rel32` (a call to the next instruction).
            self.latch_bailout(Bailout::new(BailoutReason::Internal(
                "ir_lower: a frame-block publication call has no subroutine",
            )));
            return;
        }
        let stub = self.buf.pos();
        self.frame_block_stub_at = Some(stub);
        let dones = self.emit_frame_block_publication();
        for p in dones {
            self.patch_rel32_to_here(p);
        }
        self.buf.emit_byte(0xC3); // RET
        for site in std::mem::take(&mut self.frame_block_call_patches) {
            // A buffer that overflowed fails the patch; the overflow itself
            // refuses (and retries) the lowering, as for every other patch.
            match i32::try_from(stub as i64 - (site as i64 + 4)) {
                Ok(rel) => {
                    let _ = self.buf.try_patch_i32(site, rel);
                }
                Err(_) => self.latch_bailout(Bailout::new(BailoutReason::Internal(
                    "ir_lower: a frame-block publication call is out of rel32 range",
                ))),
            }
        }
    }

    /// The publication half of the frame-block ensure: from the thread load to
    /// the published `top`. Returns the `rel32` positions the caller patches to
    /// "done", its end (the untracked-thread skip; the overflow tail's own jump
    /// already lands there).
    fn emit_frame_block_publication(&mut self) -> Vec<usize> {
        let ss_top = self.shadow_off_in_thread;
        let savebase = -self.shadow_savebase_slot_off;
        // MOV R10, [rbp - thread_slot] ; TEST R10, R10 ; JE done — a null
        // thread is "untracked", exactly as the per-call push treats it.
        self.buf.emit(&[0x4C, 0x8B, 0x95]);
        self.buf.emit(&(-self.shadow_thread_slot_off).to_le_bytes());
        self.buf.emit(&[0x4D, 0x85, 0xD2]);
        self.buf.emit(&[0x0F, 0x84]);
        let done_untracked = self.buf.pos();
        self.buf.emit(&[0, 0, 0, 0]);
        // MOV R11, [R10 + ss_top]
        self.buf.emit(&[0x4D, 0x8B, 0x9A]);
        self.buf.emit(&ss_top.to_le_bytes());
        // Cast: at most FRAME_BLOCK_MAX_HOMES_CEILING entries (`frame_block_max_homes`).
        let need = (self.frame_block.len() as i32) * 8;
        // The per-call push's overflow guard, verbatim.
        let overflow = if crate::shadow_end_guard_enabled() {
            self.buf.emit(&[0x4D, 0x8D, 0x9B]);
            self.buf.emit(&need.to_le_bytes());
            self.buf.emit(&[0x4D, 0x3B, 0x9A]);
            self.buf.emit(&(ss_top + 8).to_le_bytes());
            self.buf.emit(&[0x4D, 0x8D, 0x9B]);
            self.buf.emit(&(-need).to_le_bytes());
            self.buf.emit(&[0x0F, 0x87]);
            let p = self.buf.pos();
            self.buf.emit(&[0, 0, 0, 0]);
            Some(p)
        } else {
            None
        };
        // MOV [rbp - savebase], R11 — the block is published from here on.
        self.buf.emit(&[0x4C, 0x89, 0x9D]);
        self.buf.emit(&savebase.to_le_bytes());
        let block = self.frame_block.clone();
        for (i, &off) in block.iter().enumerate() {
            // LEA RCX, [rbp - off + 1] ; MOV [R11 + 8i], RCX — the slot's
            // address with `ShadowStack::INDIRECT_TAG` set.
            let tagged = 1 - i32::from(off);
            self.buf.emit(&[0x48, 0x8D, 0x8D]);
            self.buf.emit(&tagged.to_le_bytes());
            // Cast: i < FRAME_BLOCK_MAX_HOMES_CEILING.
            self.buf.emit(&[0x49, 0x89, 0x8B]);
            self.buf.emit(&((i as i32) * 8).to_le_bytes());
        }
        // LEA R11, [R11 + need] ; MOV [R10 + ss_top], R11
        self.buf.emit(&[0x4D, 0x8D, 0x9B]);
        self.buf.emit(&need.to_le_bytes());
        self.buf.emit(&[0x4D, 0x89, 0x9A]);
        self.buf.emit(&ss_top.to_le_bytes());
        if let Some(overflow) = overflow {
            // JMP done
            self.buf.emit_byte(0xE9);
            let done = self.buf.pos();
            self.buf.emit(&[0, 0, 0, 0]);
            self.patch_rel32_to_here(overflow);
            // Nothing stored, `top` untouched: tag the saved base so this
            // activation neither retries nor claims the block (see above).
            self.buf.emit(&[0x49, 0x83, 0xCB, 0x01]); // OR R11, 1
            self.buf.emit(&[0x4C, 0x89, 0x9D]); // MOV [rbp - savebase], R11
            self.buf.emit(&savebase.to_le_bytes());
            self.emit_shadow_overflow_note();
            self.patch_rel32_to_here(done);
        }
        vec![done_untracked]
    }

    /// Bump the process-wide shadow-overflow bail counter
    /// (`cratonvm_jit::SHADOW_OVERFLOW_COUNT`). RAX is pushed/popped around it
    /// so the site stays transparent to whatever the call is staging.
    fn emit_shadow_overflow_note(&mut self) {
        // Cast through a raw pointer before converting the static's address.
        let counter =
            (&crate::SHADOW_OVERFLOW_COUNT as *const std::sync::atomic::AtomicUsize) as usize;
        self.buf.emit_byte(0x50); // push rax
        self.emit_mov_reg_imm64(RAX, counter as u64);
        self.buf.emit(&[0xF0, 0x48, 0xFF, 0x00]); // lock inc qword [rax]
        self.buf.emit_byte(0x58); // pop rax
    }

    /// cov-01 — direct (helper-free) read of a static field, the IR tier's
    /// mirror of `x64::Compiler::try_emit_inline_getstatic`. Returns `false`
    /// when the site is not eligible, leaving the caller's helper lowering in
    /// place.
    ///
    /// What is baked is the address of the class's base-POINTER cell, not of
    /// the statics block: one extra dependent load buys immunity to every
    /// republication path, because a `StaticsBlock` is a leaked, never-freed
    /// allocation per class whose *cell* address is stable while the block
    /// pointer inside it is not.
    ///
    /// `resolve_static_base` returning `None` is the whole eligibility test,
    /// and it is the VM's judgement rather than this file's: it declines a
    /// class that is not yet initialized (an inline load runs no `<clinit>`),
    /// `java/lang/System` (the `out`/`err`/`in` bootstrap intercept), anything
    /// not yet published, and a second VM in this process. Reusing that one
    /// predicate is what keeps the two tiers from developing different opinions
    /// about which statics may be read directly.
    ///
    /// Only the two type tags the builder admits are emitted — reference
    /// (64-bit payload) and int-category (`MOVSXD` of the 32-bit payload) —
    /// because `IrBuilder`'s `0xb2` arm refuses `J`/`D`/`F` outright. A tag
    /// that reached here anyway would be a builder bug, so it takes the helper
    /// rather than a plausible-looking wrong width.
    fn emit_inline_getstatic(
        &mut self,
        id: NodeId,
        class_id: u32,
        field_index: u32,
        type_tag: u8,
        is_volatile: bool,
    ) -> bool {
        if !crate::x64::inline_getstatic_enabled() {
            return false;
        }
        // Three widths, and they are the single-pass arm's three, in the same
        // order and with the same constants:
        //
        //   `J`/`D`/`L`/`[`  64-bit MOV of the 64-bit payload
        //   `F`              32-bit MOV of the 32-bit payload — a float's bit
        //                    pattern, so ZERO-extended. `MOVSXD` here would
        //                    sign-extend any float whose bit 31 is set (i.e.
        //                    every negative one) into garbage in the high half,
        //                    and the home word is what `publish_fp_from_slot`
        //                    and every deopt frame read.
        //   int-category     `MOVSXD` of the 32-bit payload
        //
        // A tag outside those is a builder bug — its 0xb2 arm admits exactly
        // these — so take the helper rather than emit a plausible-looking width.
        let wide = matches!(type_tag, b'L' | b'[' | b'J' | b'D');
        let is_float = type_tag == b'F';
        if !wide && !is_float && !matches!(type_tag, b'I' | b'Z' | b'B' | b'C' | b'S') {
            return false;
        }
        let Some(base_cell) = self
            .direct_helpers
            .resolve_static_base(class_id, field_index as usize)
        else {
            return false;
        };
        // Cell byte offset within the class's statics block, plus the payload
        // half of the 16-byte cell — the same arithmetic the single-pass arm
        // uses, and the same `FIELD_CELL_PAYLOAD*_OFFSET` constants
        // (`static_cell_offsets`, shared with the inline `putstatic`).
        let Some((_, payload32, payload64)) = static_cell_offsets(field_index) else {
            return false;
        };
        let disp = if wide { payload64 } else { payload32 };
        let slot = self.alloc_slot(id);
        // MOV RAX, imm64(&base_cell) ; MOV RAX, [RAX]
        self.emit_mov_reg_imm64(RAX, base_cell as u64);
        self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]
        self.buf.emit(&0i32.to_le_bytes());
        if wide {
            self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]
        } else if is_float {
            self.buf.emit(&[0x8B, 0x80]); // MOV EAX, [RAX + disp32] (zero-extends)
        } else {
            self.buf.emit(&[0x48, 0x63, 0x80]); // MOVSXD RAX, [RAX + disp32]
        }
        self.buf.emit(&disp.to_le_bytes());
        // No fence after a volatile LOAD on x86-TSO: the load is already an
        // acquire, and the StoreLoad the JMM needs is the volatile store's
        // trailing fence (`LOCK ADD DWORD [RSP], 0` in this tier since round 11
        // wave 2). `CRATONVM_JIT_VOLATILE_LOAD_FENCE=1` restores the
        // old one — see `runtime_lowering::volatile_load_fence_enabled`.
        if is_volatile && self.volatile_load_fence_on {
            self.buf.emit(&[0x0F, 0xAE, 0xF0]); // MFENCE
        }
        self.store_rax(slot);
        // An FP result was computed in RAX and is now in its home word — the
        // `Op::ConstF` shape exactly, so it publishes the same way. A no-op when
        // the allocator gave this value no register.
        if matches!(type_tag, b'F' | b'D') {
            self.publish_fp_from_slot(id, slot, type_tag == b'D');
        }
        true
    }

    /// JIT round 21 wave 1 (lane indy, INDY21-2, [`ir_clinit_barrier_enabled`]):
    /// HotSpot's class-initialization barrier for a `getstatic` whose class was
    /// NOT initialized at compile time (so [`Self::emit_inline_getstatic`]
    /// declined), emitted AHEAD of the helper route, which stays as its decline
    /// edge:
    ///
    /// ```text
    ///   rax = TLS JvmThread*           ; 0 -> helper
    ///   rax = [rax + thread_id] + 1
    ///   cmp rax, [owner cell]          ; != -> helper (not this thread's claim)
    ///   rax = [base cell]              ; the statics block, 0 -> helper
    ///   rax = [rax + payload]          ; the width of emit_inline_getstatic
    ///   store ; jmp done
    /// helper: <map, CALL jit_getstatic, ...>
    /// done:
    /// ```
    ///
    /// The owner cell (VM: `jit_bridge::clinit_owner_cell_for`) holds `1 +` the
    /// thread id of the class's init claimant, set under the claim and cleared
    /// when `finalize_class_init` ends the claim (success or failure). So the
    /// inline read happens exactly when the helper would answer the JVMS 5.5
    /// step 3 recursive request (the claimant reading its own class's statics,
    /// no `<clinit>` to run), and every other thread -- and the claimant after
    /// a failed `<clinit>` -- takes the helper, which waits, runs `<clinit>`,
    /// or throws `NoClassDefFoundError`. No call, no safepoint and no deopt
    /// point on the fast path. RAX and R11 only (R11 is this tier's scratch,
    /// as the poll uses it).
    ///
    /// Returns the `JMP done` operand to patch after the helper route, or
    /// `None` (nothing emitted): switch off, no TLS thread word, a width the
    /// inline read does not take, a field index past 16 bits, or a VM that
    /// answered no cell / no base / no offset.
    fn emit_clinit_barrier_getstatic(
        &mut self,
        id: NodeId,
        class_id: u32,
        field_index: u32,
        type_tag: u8,
        is_volatile: bool,
    ) -> Option<usize> {
        if !ir_clinit_barrier_enabled() || class_id == 0 {
            return None;
        }
        let wide = matches!(type_tag, b'L' | b'[' | b'J' | b'D');
        let is_float = type_tag == b'F';
        if !wide && !is_float && !matches!(type_tag, b'I' | b'Z' | b'B' | b'C' | b'S') {
            return None;
        }
        let tls = u32::try_from(crate::x64::jit_thread_tls_disp())
            .ok()
            .filter(|&d| d != 0)?;
        let field16 = u16::try_from(field_index).ok()?;
        let cell = vh_const_ask(
            &self.direct_helpers,
            vh_const_query(WELL_KNOWN_CLINIT_OWNER_CELL_TAG, class_id, 0),
        );
        let base_cell = vh_const_ask(
            &self.direct_helpers,
            vh_const_query(WELL_KNOWN_CLINIT_BASE_CELL_TAG, class_id, field16),
        );
        let tid_off_plus_one = vh_const_ask(&self.direct_helpers, WELL_KNOWN_JVM_THREAD_ID_OFFSET);
        if cell <= 0 || base_cell <= 0 || tid_off_plus_one <= 0 {
            return None;
        }
        let tid_off = i32::try_from(tid_off_plus_one - 1).ok()?;
        let (_, payload32, payload64) = static_cell_offsets(field_index)?;
        let disp = if wide { payload64 } else { payload32 };
        if crate::ir_stage_reporting() || crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir clinit barrier getstatic n{id} class_id={class_id} \
                 field={field_index} cell={cell:#x}"
            );
        }
        let slot = self.alloc_slot(id);
        let mut helper: Vec<usize> = Vec::with_capacity(3);
        // RAX = the `JvmThread*` (0 outside a JIT thread context).
        self.emit_mov_rax_tls_disp32(tls);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        helper.push(self.emit_jcc_rel32(0x84)); // JZ helper
        self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]: thread_id
        self.buf.emit(&tid_off.to_le_bytes());
        self.buf.emit(&[0x48, 0xFF, 0xC0]); // INC RAX
        // Cast: a VM-lived cell address as the imm64 operand.
        self.emit_mov_reg_imm64(R11, cell as u64);
        self.buf.emit(&[0x49, 0x3B, 0x03]); // CMP RAX, [R11]
        helper.push(self.emit_jcc_rel32(0x85)); // JNE helper
        // Cast: as above.
        self.emit_mov_reg_imm64(RAX, base_cell as u64);
        self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + 0]: the statics block
        self.buf.emit(&0i32.to_le_bytes());
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        helper.push(self.emit_jcc_rel32(0x84)); // JZ helper
        if wide {
            self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]
        } else if is_float {
            self.buf.emit(&[0x8B, 0x80]); // MOV EAX, [RAX + disp32] (zero-extends)
        } else {
            self.buf.emit(&[0x48, 0x63, 0x80]); // MOVSXD RAX, [RAX + disp32]
        }
        self.buf.emit(&disp.to_le_bytes());
        if is_volatile && self.volatile_load_fence_on {
            self.buf.emit(&[0x0F, 0xAE, 0xF0]); // MFENCE
        }
        self.store_rax(slot);
        if matches!(type_tag, b'F' | b'D') {
            self.publish_fp_from_slot(id, slot, type_tag == b'D');
        }
        let done = self.emit_jmp_rel32();
        for p in helper {
            self.patch_rel32_to_here(p);
        }
        Some(done)
    }

    /// Round 16 (lane fieldguard): a PRIMITIVE `putstatic` as a direct store
    /// into the class's statics cell, with no helper `CALL`
    /// (`CRATONVM_JIT_INLINE_PUTSTATIC`, default ON since round 16;
    /// [`inline_putstatic_enabled`]).
    ///
    /// The store twin of [`Self::emit_inline_getstatic`], on the same
    /// eligibility test: `resolve_static_base` answers only for a class whose
    /// `<clinit>` has completed (monotone), whose statics block is published
    /// and covers `field_index`, and which is not `java/lang/System`. So the
    /// helper has nothing left to decide for a primitive write:
    ///
    /// * **class initialization** -- `jit_putstatic_class_init_guard` returns
    ///   at its first line for an initialized class;
    /// * **the SATB pre-barrier** -- `set_static_shared` logs only an old
    ///   `Value::Object`, and a primitive static's cell never holds one;
    /// * **block creation / growth** -- only on its locked fallback, which a
    ///   published block covering the index never reaches;
    /// * **the write itself** -- the helper writes the whole 16-byte `Value`
    ///   cell (`cell.write_volatile`). This writes the same two words,
    ///   word 0 = `tag | payload32 << 32` and word 1 = 0 for an int-category or
    ///   `float` value, word 0 = `tag` and word 1 = the payload for `long` /
    ///   `double`: the words `write_value_atomic` leaves and the inline
    ///   primitive `putfield`'s legacy arm writes, so each store changes one
    ///   aligned 8-byte word and a racing reader sees the old or the new value.
    ///
    /// The base pointer is re-read from the baked cell on every execution, so
    /// a republished block is followed exactly as the inline `getstatic`
    /// follows it. A store racing a GROW of the same block can land in the
    /// abandoned copy -- the helper's documented behaviour too
    /// (`set_static_shared`, "Exclusion from republication: not provided").
    /// The value is already narrowed (the builder's `narrow_to_field_type`).
    /// A volatile write keeps its trailing StoreLoad fence in the caller.
    ///
    /// Reference statics never come here: their write owes the SATB
    /// pre-barrier, which is the helper's.
    ///
    /// Clobbers RAX, RCX and RDX only (this lowerer's per-opcode scratch).
    /// Returns `false`, having emitted nothing, when the site is not admitted.
    fn emit_inline_putstatic(
        &mut self,
        class_id: u32,
        field_index: u32,
        type_tag: u8,
        value: NodeId,
    ) -> bool {
        if !inline_putstatic_enabled() {
            return false;
        }
        let wide = matches!(type_tag, b'J' | b'D');
        if !wide && !matches!(type_tag, b'I' | b'Z' | b'B' | b'C' | b'S' | b'F') {
            return false;
        }
        let Some(base_cell) = self
            .direct_helpers
            .resolve_static_base(class_id, field_index as usize)
        else {
            return false;
        };
        // The cell and its 64-bit payload word (`static_cell_offsets`, shared
        // with the inline `getstatic`).
        let Some((cell_off, _, hi_off)) = static_cell_offsets(field_index) else {
            return false;
        };
        // `Value`'s discriminants: Int 0, Long 1, Float 2, Double 3 (the
        // single-pass `legacy_cell_tag_for`; sub-int statics are `Value::Int`).
        let tag: u32 = match type_tag {
            b'J' => 1,
            b'F' => 2,
            b'D' => 3,
            _ => 0,
        };
        // The value first, so nothing `gp_load_value` emits can disturb the
        // address RAX is about to hold.
        self.gp_load_value(RDX, value);
        // MOV RAX, imm64(&base_cell) ; MOV RAX, [RAX]
        self.emit_mov_reg_imm64(RAX, base_cell as u64);
        self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]
        self.buf.emit(&0i32.to_le_bytes());
        if wide {
            // word 0 = tag (bytes 4..8 zero); word 1 = the 64-bit payload.
            self.buf.emit(&[0x48, 0xC7, 0x80]); // MOV qword [RAX + disp32], imm32
            self.buf.emit(&cell_off.to_le_bytes());
            self.buf.emit(&tag.to_le_bytes());
            self.buf.emit(&[0x48, 0x89, 0x90]); // MOV qword [RAX + disp32], RDX
            self.buf.emit(&hi_off.to_le_bytes());
        } else {
            // word 0 = tag | payload32 << 32; word 1 = 0.
            self.note_rcx_written();
            self.buf.emit(&[0x89, 0xD1]); // MOV ECX, EDX (zero-extends)
            self.buf.emit(&[0x48, 0xC1, 0xE1, 0x20]); // SHL RCX, 32
            if tag != 0 {
                // Cast: `tag` is 0..=3, a positive imm8.
                self.buf.emit(&[0x48, 0x83, 0xC9, tag as u8]); // OR RCX, imm8
            }
            self.buf.emit(&[0x48, 0x89, 0x88]); // MOV qword [RAX + disp32], RCX
            self.buf.emit(&cell_off.to_le_bytes());
            self.buf.emit(&[0x31, 0xC9]); // XOR ECX, ECX
            self.buf.emit(&[0x48, 0x89, 0x88]); // MOV qword [RAX + disp32], RCX
            self.buf.emit(&hi_off.to_le_bytes());
        }
        true
    }

    /// JIT r20 wave 17 (lane pAlloc2; `CRATONVM_JIT_IR_INLINE_PUTSTATIC_REF`,
    /// default ON, `=0` = the helper call alone): a REFERENCE `putstatic` of
    /// an initialized class as a direct store into its statics cell while the
    /// SATB pre-gate byte is clear. `R20PAllocTlabTls`'s kernels pay one
    /// `sink = obj` per allocation, and every one was a `jit_putstatic_object`
    /// call with its safepoint map, post-call record and shadow reload.
    ///
    /// What the helper does for a site `resolve_static_base` admits (the
    /// eligibility test [`Self::emit_inline_putstatic`] already relies on: a
    /// completed `<clinit>`, a published block covering the index, not
    /// `java/lang/System`), and why the fast path may skip each step:
    ///
    /// * **class initialization** -- the guard returns at once for an
    ///   initialized class (monotone), so the value pin around it is moot;
    /// * **the SATB pre-barrier** -- `set_static_shared` logs the OLD
    ///   reference through `heap.satb_barrier`, a no-op exactly while the
    ///   collector's pre-gate byte (`helpers.ref_store_pre_gate`, the
    ///   `Lowerer::satb_pre_gate` the G1 gated `putfield` reads) is clear. The
    ///   byte is armed only inside a stop-the-world step, and nothing between
    ///   the test and the store can reach a safepoint, so a clear byte proves
    ///   the barrier owes nothing; an armed byte takes the helper. A
    ///   cross-thread take-over can freeze a peer between the two (no poll is
    ///   needed for that); for a static it is still sound, because the old
    ///   value is in a static, which the arming pause scans as a root
    ///   (`docs/internal/fixed-bugs/zgc-zr1br-takeover-straddles-the-satb-gate-FIXED-20261017.md`
    ///   covers the field and array stores). An unwired
    ///   gate (`0`) declines the fast path at compile time;
    /// * **no post barrier** -- statics live outside the heap and are scanned
    ///   as roots; `set_static_shared` calls none, on either path;
    /// * **the write** -- the helper writes the whole 16-byte `Value` cell.
    ///   This writes word 1 = the pointer (`Object(None)` is the zero pointer,
    ///   the niche) and then word 0 = discriminant `4`, each one aligned 8-byte
    ///   store, so a racing reader sees the old or the new reference.
    ///
    /// Returns the fast path's `JMP` patch (the caller lands it past its
    /// helper route), having routed an armed gate to the code that follows;
    /// `None`, having emitted nothing, when the site is not admitted. Clobbers
    /// RAX, RDX and R11 (this lowerer's per-opcode scratch).
    fn emit_inline_putstatic_ref(
        &mut self,
        class_id: u32,
        field_index: u32,
        type_tag: u8,
        value: NodeId,
    ) -> Option<usize> {
        if !matches!(type_tag, b'L' | b'[')
            || !inline_putstatic_enabled()
            || !ir_inline_putstatic_ref_enabled()
            || self.satb_pre_gate == 0
        {
            return None;
        }
        let base_cell = self
            .direct_helpers
            .resolve_static_base(class_id, field_index as usize)?;
        let (cell_off, _, hi_off) = static_cell_offsets(field_index)?;
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir inline putstatic ref: class={class_id} field={field_index}"
            );
        }
        // MOV R11, imm64(&gate) ; CMP BYTE [R11], 0 ; JNE -> the helper route.
        // zs s5/bt2: on ZGC's age-floor plan (the fused gate's condition, so
        // G1 and the generational mask plan keep these bytes) the same byte
        // compare is one RIP-relative instruction when the gate is in reach:
        // `CMP BYTE [rip+disp32], 0` (7 bytes, `80 3D d32 00`). Only the pre
        // byte: a static is a root, so no post gate is owed.
        let here = self.buf.as_ptr() as usize + self.buf.pos(); // Cast: buffer address
        let rip = (self.zgc_fused_gate.is_some() && crate::x64::zgc_fused_gate_all_sites_enabled())
            .then(|| zgc_pre_byte_cmp_rip_bytes(here, self.satb_pre_gate))
            .flatten();
        if let Some(bytes) = rip {
            self.buf.emit(&bytes);
        } else {
            self.emit_mov_reg_imm64(R11, self.satb_pre_gate as u64);
            self.buf.emit(&[0x41, 0x80, 0x3B, 0x00]);
        }
        let armed = self.emit_jcc_rel32(0x85);
        // The value first, so nothing `gp_load_value` emits can disturb RAX.
        self.gp_load_value(RDX, value);
        // MOV RAX, imm64(&base_cell) ; MOV RAX, [RAX]
        self.emit_mov_reg_imm64(RAX, base_cell as u64);
        self.buf.emit(&[0x48, 0x8B, 0x80]); // MOV RAX, [RAX + disp32]
        self.buf.emit(&0i32.to_le_bytes());
        self.buf.emit(&[0x48, 0x89, 0x90]); // MOV qword [RAX + disp32], RDX
        self.buf.emit(&hi_off.to_le_bytes());
        self.buf.emit(&[0x48, 0xC7, 0x80]); // MOV qword [RAX + disp32], imm32
        self.buf.emit(&cell_off.to_le_bytes());
        self.buf.emit(&4u32.to_le_bytes()); // `Value::Object`'s discriminant
        let join = self.emit_jmp_rel32();
        self.patch_rel32_to_here(armed);
        Some(join)
    }

    /// Guard a baked COMPACT CELL OFFSET against a layout replacement, and
    /// return the patch site the caller routes to its helper.
    ///
    /// The optimizing tier's twin of `x64::objects::emit_layout_epoch_guard`,
    /// and it exists for the same reason: an emitter that bakes
    /// `HEADER_SIZE + packed_body_offset` as an immediate is making a
    /// compile-time claim about a layout the class manager can replace at run
    /// time. The two ALLOCATION emitters have guarded that since
    /// perf/halfgap-20260717 and call an unguarded baked layout "confirmed heap
    /// corruption"; the field-access emitters had no guard at all.
    ///
    /// Four instructions against the process-wide replacement epoch, which only
    /// a REPLACEMENT bumps — never a new class registration — so a workload
    /// that never swaps a layout keeps every inline arm.
    fn emit_layout_epoch_guard(&mut self) -> Option<usize> {
        if !self.emit_layout_epoch_cmp() {
            return None;
        }
        Some(self.emit_jcc_rel32(0x85)) // JNE -> the caller's slow path
    }

    /// The compare half of [`Self::emit_layout_epoch_guard`]: ZF=1 exactly
    /// when the replacement epoch still matches the one this compile baked.
    /// Emits nothing and answers `false` when there is no epoch cell.
    ///
    /// Split out (round 11 wave 2, lane lower) for a site with no helper slow
    /// path to branch to: `Op::Unbox` deopts on a mismatch instead. Clobbers
    /// R11 and ECX on the non-RIP fallback form, like the guard.
    fn emit_layout_epoch_cmp(&mut self) -> bool {
        let (addr, expected) = cratonvm_types::layout_replace_epoch_guard();
        if addr.is_null() {
            return false;
        }
        // Round 16 (lane fieldguard, FG-b3): the epoch as of the compile's
        // start, before its compact rows were resolved, not as of now.
        let expected = crate::compile_baked_layout_epoch(expected);
        if !self.emit_cmp_layout_epoch_rip(addr as usize, expected) {
            // Out of ±2GB RIP reach, or the encoding switched off: materialize
            // the address and read through it. This is the shape the guard had
            // before 2026-09-10, kept verbatim as the fallback.
            self.emit_mov_reg_imm64(R11, addr as u64);
            // MOV ECX, dword [R11]
            self.buf.emit(&[0x41, 0x8B, 0x0B]);
            // CMP ECX, imm32
            self.buf.emit(&[0x81, 0xF9]);
            self.buf.emit(&(expected as i32).to_le_bytes());
        }
        true
    }

    /// Round 16 (lane fieldguard, FG16-1): the layout-epoch guard of an inline
    /// field site on receiver `base` at bytecode `pc`, in one of three forms.
    /// Returns the patch the caller routes to its helper, as
    /// [`Self::emit_layout_epoch_guard`] does, or `None` when nothing that
    /// rejoins was emitted.
    ///
    /// With `CRATONVM_JIT_IR_LAYOUT_GUARD_DEOPT` off (the default) it IS
    /// `emit_layout_epoch_guard`: a compare whose failure takes this site's
    /// helper and then REJOINS. That rejoin is why no later site could trust
    /// it: the code after the site runs whether the guard passed or not.
    ///
    /// With the switch on:
    ///
    /// * **Elided** -- no compare at all -- when an earlier DEOPTING guard
    ///   proved `base` and that guard's execution is on every path here with
    ///   no later redefinition of `base` in between: either it was emitted
    ///   earlier in THIS block (a block runs straight through, and `base`, an
    ///   input of the earlier site, was defined before it), or the body is
    ///   LOOP-FREE (`schedule_block_cfg_has_cycle` is false) and the guard's
    ///   block dominates this one. Loop-free matters twice: a value defined
    ///   inside a loop is a different object each iteration under one node
    ///   id, and an OSR entry stub enters a loop header past the blocks that
    ///   dominate it (the precedent is the dominated-sample elision, which is
    ///   planned for loop-free bodies only, for the same reason).
    /// * **Deopting** -- `CMP epoch; JE continue; <deopt at pc>` -- otherwise,
    ///   when the site may deopt here: `may_deopt` (the caller's statement
    ///   that [`node_cannot_deopt`] already predicts a deopt at this node, so
    ///   its snapshot is consultable and every value it names keeps a home),
    ///   the site is in the compiling method's own code (a guard inside a
    ///   spliced body would resume at the `invoke` and could replay a
    ///   committed store), no OTHER effectful node carries the same bytecode
    ///   pc (an intrinsic expansion that stores and then reads at one
    ///   `invoke` pc would replay its store on re-execution;
    ///   [`layout_guard_lone_pcs`]), and the body is not self-locking (whose deopt
    ///   exits the hand-over audits; lane monitor's). The deopt re-executes
    ///   the `getfield`/`putfield` in the interpreter, which nothing before
    ///   the guard has started: the guard precedes every load, store and
    ///   receiver dereference of the site. Records `(base, block)`.
    /// * **Rejoining**, as with the switch off, in every other case; records
    ///   nothing.
    ///
    /// # Why an elided guard is sound
    ///
    /// The guard protects a BAKED compact displacement against a layout
    /// REPLACEMENT. An object's layout is fixed when it is allocated: its
    /// header's compact bit and its class's layout version at that moment
    /// decide its body, and no collector re-lays an object (they copy it).
    /// `register_class_layout` bumps `LAYOUT_REPLACE_EPOCH` (Release) under
    /// the registry's write lock BEFORE it publishes the replacement, and an
    /// allocation reads the layout through that lock, so any object laid out
    /// by a replacement was allocated by a thread that had already seen the
    /// bump, and any thread that obtains a reference to it (x86-TSO is
    /// causally consistent) sees the bump too. A deopting guard that PASSED
    /// after `base` was defined therefore proves that the object `base`
    /// names has the baked layout or a legacy one (which the per-object
    /// compact test still routes), for good: across later calls, safepoints
    /// and relocations. The epoch only grows, so a failed guard never needs
    /// re-asking; it left for the interpreter.
    ///
    /// The per-object compact TEST is not elided: it is a property of the
    /// object, not of the epoch, and choosing an arm without it needs a
    /// speculation or a versioned copy of the code (FG16-2).
    fn emit_field_layout_guard(
        &mut self,
        base: NodeId,
        pc: usize,
        may_deopt: bool,
    ) -> Option<usize> {
        if !self.layout_guard_deopt_on {
            return self.emit_layout_epoch_guard();
        }
        let block = self
            .cur_def
            .and_then(|d| self.schedule.node_to_block.get(d as usize).copied());
        let Some(block) = block else {
            return self.emit_layout_epoch_guard();
        };
        let cross_block = self.layout_guard_cross_block;
        let proven = self.layout_proven.iter().any(|&(r, b)| {
            r == base
                && (b == block
                    || (cross_block
                        && self.schedule.dom.is_reachable(b)
                        && self.schedule.dom.dominates(b, block)))
        });
        if proven {
            if crate::ir_stage_reporting() {
                eprintln!("[ir] layout-guard elided n{base} at pc {pc} (block {block})");
            }
            return None;
        }
        // JIT round 17 wave 3 (lane irlower): under the opt-in per-frame rule,
        // the owner count is per `(pc, own frame)`, so a copy that names its
        // own frame is lone in its copy. See `layout_guard_lone_sites`.
        let lone = match self.layout_guard_lone_sites.as_ref() {
            Some(sites) => {
                let graph = self.graph;
                let own = self.cur_node_frame.filter(|&si| {
                    graph
                        .safepoints
                        .get(si as usize)
                        .is_some_and(|sp| sp.bci == pc)
                });
                sites.contains(&(pc, own))
            }
            None => self.layout_guard_lone_pcs.contains(&pc),
        };
        if may_deopt
            && lone
            && !self.pc_is_in_a_spliced_body(pc)
            && self.graph.method_self_lock.is_none()
        {
            if !self.emit_layout_epoch_cmp() {
                // No epoch cell: the rejoining form emits nothing either.
                return None;
            }
            // ZF=1 exactly when the epoch still matches: continue on JE.
            self.emit_deopt_unless(0x84, pc, DeoptReason::ClassLoading);
            self.layout_proven.push((base, block));
            if crate::ir_stage_reporting() {
                eprintln!("[ir] layout-guard deopting n{base} at pc {pc} (block {block})");
            }
            return None;
        }
        self.emit_layout_epoch_guard()
    }

    /// `MOV dst32/dst64, [base + disp32]` for any GPR pair (a SIB byte for an
    /// RSP/R12 base). Used by the inline `ArrayList` prefix.
    fn emit_load_base_disp32(&mut self, dst: u8, base: u8, disp: i32, wide: bool) {
        if dst == RCX {
            self.note_rcx_written();
        }
        let rex = 0x40u8 | ((wide as u8) << 3) | (((dst >= 8) as u8) << 2) | ((base >= 8) as u8);
        if rex != 0x40 {
            self.buf.emit_byte(rex);
        }
        self.buf.emit_byte(0x8B);
        self.buf.emit_byte(0x80 | ((dst & 7) << 3) | (base & 7));
        if base & 7 == 4 {
            self.buf.emit_byte(0x24); // SIB: base only
        }
        self.buf.emit(&disp.to_le_bytes());
    }

    /// NIO19-2 (nio20 wave 1, lane L2): an `Unsafe` primitive accessor over a
    /// heap PRIMITIVE array, answered inline as a guarded PREFIX of the
    /// `Op::Call`'s unchanged lowering -- one load or store where the site used
    /// to CALL `jit_unsafe_get_int_direct` & co (or the funnel, for `getChar`
    /// and the `*Unaligned` bodies). Sites: `direct_helpers::unsafe_inline_access_site`.
    ///
    /// Same contract with the `Op::Call` arm as
    /// [`Self::try_emit_ir_arraylist_access_prefix`]: scratch RAX, RCX, RDX,
    /// R10 and R11 only; the hit edge writes a get's result exactly as the call
    /// route's `store_rax` would and jumps to [`Self::call_prefix_join`]; no
    /// GC point, no call, no deopt on the hit path.
    ///
    /// # What it answers (exactly the thin helpers' heap arm)
    ///
    /// `vm::jit::helpers::raw_accessor_read_bytes` / `_write_bytes` for a
    /// non-null base: the base's header says ARRAY with a PRIMITIVE element type
    /// (any of the eight -- a mismatched width is a raw little-endian copy, as
    /// on HotSpot), `offset >= ARRAY_DATA_OFFSET` (signed), and
    /// `offset - ARRAY_DATA_OFFSET + width <= length << log2(element size)`. No
    /// alignment is required (x86-64 has none, and the helper asked none). A
    /// big-endian `*Unaligned` form swaps the bytes. Everything else DECLINES to
    /// the call: a null receiver (the call raises the NPE), a null base (an
    /// off-heap address or an `Unsafe` arena handle), a plain object (a field or
    /// static offset), a reference array, an out-of-range offset.
    ///
    /// No GC barrier: the access reads or writes primitive bytes only, through
    /// the same object pointer the optimizing tier's own `ArrayLoad`/`ArrayStore`
    /// address primitive elements with.
    ///
    /// # Declines at compile time
    ///
    /// No VM admission bit for the accessor (`DirectHelperTable::unsafe_inline_admitted`,
    /// filled from the per-call policy the inline code skips),
    /// `CRATONVM_JIT_UNSAFE_ACCESSOR_INLINE=0` or `CRATONVM_JIT_UNSAFE_ACCESSOR_DIRECT=0`,
    /// a shape whose arity or result type does not match, an operand some carry
    /// is holding, and a get result that is carried or has its home dropped.
    fn try_emit_ir_unsafe_access_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 || self.direct_helpers.unsafe_inline_admitted == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        let Some(access) = crate::direct_helpers::unsafe_inline_access_site(
            info.class_name,
            info.method_name,
            info.descriptor,
        ) else {
            // nio21 wave 5 L3: the CAS / getAndAdd / getAndSet rows.
            if let Some(rmw) = crate::direct_helpers::unsafe_inline_rmw_site(
                info.class_name,
                info.method_name,
                info.descriptor,
            ) {
                self.try_emit_ir_unsafe_rmw_prefix(id, info, rmw);
            } else if crate::direct_helpers::unsafe_inline_ref_cas_site(
                info.class_name,
                info.method_name,
                info.descriptor,
            ) {
                // JIT round 20 wave 12, lane qUnsafe (AT-4).
                self.try_emit_ir_unsafe_ref_cas_prefix(id, info);
            } else if let Some(rv) = crate::direct_helpers::unsafe_inline_ref_volatile_site(
                info.class_name,
                info.method_name,
                info.descriptor,
            ) {
                // JIT round 21 wave 1, lane updaters (UPDATERS21-1).
                self.try_emit_ir_unsafe_ref_volatile_prefix(id, info, rv);
            }
            return;
        };
        // Instance methods of the final `Unsafe`: virtual (0) or the
        // devirtualised special (1); the receiver is input 2 either way.
        if !matches!(info.invoke_kind, 0 | 1)
            || !access.admitted(self.direct_helpers.unsafe_inline_admitted)
            || !crate::direct_helpers::unsafe_accessor_inline_enabled()
            // nio20 w3 L3 (W2L2-4): this tier's half only.
            || !crate::ir_thin_prefix_enabled()
        {
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, base, offset, (value), (bigEndian)]
        if node.inputs.len() != 3 + access.num_params() {
            return;
        }
        let want_ty = if access.is_put {
            IrType::Void
        } else if access.value_kind == b'F' {
            // JIT round 20 wave 12, lane qUnsafe (L2-2): an FP result is its
            // raw bits in RAX stored to the home word, exactly what the call
            // route's `store_rax(slot)` leaves (it publishes no FP register).
            IrType::Float
        } else if access.value_kind == b'D' {
            IrType::Double
        } else if access.width == 8 {
            IrType::Long
        } else {
            IrType::Int
        };
        if node.ty != want_ty {
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            return;
        }
        let recv = node.inputs[2];
        let base = node.inputs[3];
        let offset = node.inputs[4];
        let value = if access.is_put {
            Some(node.inputs[5])
        } else {
            None
        };
        let big_endian = if access.big_endian_operand {
            Some(node.inputs[node.inputs.len() - 1])
        } else {
            None
        };
        // A get's result home, computed without allocating it (see the
        // ArrayList prefix): the call route allocates it after its map.
        let slot = if access.is_put {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                return;
            }
            match self.planned_slot_off(id) {
                Ok(slot) => Some(slot),
                Err(_) => return,
            }
        };
        // A constant `bigEndian` (the common `ByteOrder` shapes after
        // inlining) decides the swap here; otherwise it is tested at run time.
        let big_endian_const: Option<bool> =
            big_endian.and_then(|b| match graph.nodes.get(b as usize).map(|n| &n.op) {
                Some(Op::Const(v)) => Some(*v as i32 != 0),
                _ => None,
            });
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-unsafe-inline n{id} {}.{}{} width={} put={} be={:?}",
                info.class_name,
                info.method_name,
                info.descriptor,
                access.width,
                access.is_put,
                big_endian.map(|_| big_endian_const),
            );
        }
        let w = access.width;

        let mut decline: Vec<usize> = Vec::new();
        // RCX: the tag byte, then the scale, then a runtime `bigEndian`.
        self.note_rcx_written();
        // R10 = the `Unsafe` receiver; null declines (the call's NPE).
        self.gp_load_value(R10, recv);
        self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // RAX = base; null (an off-heap address or arena handle) declines --
                                                 // or, since nio21 wave 4 L3 (`ir_unsafe_offheap_prefix_enabled`), takes
                                                 // the off-heap arm emitted after the heap one.
        self.gp_load_value(RAX, base);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        let to_offheap = self.emit_jcc_rel32(0x84); // JZ
                                                    // Not for a volatile access (nio21 wave 4 L4's arm): the off-heap
                                                    // arm has neither its alignment test nor its locked store.
                                                    // JIT round 20 wave 12, lane qUnsafe (L2-2): nor for a boolean / float /
                                                    // double row (`UnsafeInlineAccess::heap_only`).
        let offheap = ir_unsafe_offheap_prefix_enabled() && !access.volatile && !access.heap_only();
        if !offheap {
            decline.push(to_offheap);
        }
        // JIT round 20 wave 11, lane pAtom (W7-L3-1 / AT-3): a volatile
        // int/long access to a non-array base takes the instance-field arm
        // (emitted after the hit path) when this VM baked its cell table;
        // without one it declines in the array screen's own kind test.
        let field_arm =
            crate::direct_helpers::unsafe_volatile_field_arm_words(&self.direct_helpers, access);
        let to_field = field_arm.map(|_| {
            let (bytes, edge) = crate::direct_helpers::unsafe_inline_not_array_bytes();
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            at + edge
        });
        self.emit_ir_unsafe_prim_array_screen(offset, w, &mut decline);
        if access.volatile {
            // nio21 wave 4 L4: a volatile access is served only naturally
            // aligned (a misaligned one is the natives' raw, non-atomic arm).
            // The payload starts 8-aligned at +16, so an aligned offset is an
            // aligned address. TEST R11B, w-1 ; JNZ decline.
            self.buf.emit(&[0x41, 0xF6, 0xC3, w - 1]);
            decline.push(self.emit_jcc_rel32(0x85));
        }
        // RAX = the base, R11 = the array offset or (from the field arm) the
        // published compact displacement, which is naturally aligned. The
        // field arm joins here.
        let field_join = self.buf.pos();

        if let Some(value) = value {
            // RDX = the value; its low `w` bytes are stored.
            self.gp_load_value(RDX, value);
            self.emit_unsafe_inline_swap(w, big_endian, big_endian_const, RDX);
            if access.value_kind == b'Z' {
                // JIT r20 lane rev12: `putBoolean` stores `x & 1`, as HotSpot
                // (and `native_unsafe_put_boolean_mb`) do. AND EDX, 1.
                self.buf
                    .emit(&crate::direct_helpers::UNSAFE_BOOLEAN_NORMALIZE_EDX);
            }
            // MOV [RAX + R11], DL / DX / EDX / RDX (SIB: base RAX, index R11);
            // a volatile put is XCHG [RAX + R11], EDX / RDX (an implicitly
            // locked store: the StoreLoad a volatile store owes). JIT round 20
            // wave 12, lane qUnsafe (L2-2): a release / opaque row
            // (`ordered_store`) is the plain `MOV`.
            match (w, access.volatile && !access.ordered_store) {
                (4, true) => self.buf.emit(&[0x42, 0x87, 0x14, 0x18]),
                (8, true) => self.buf.emit(&[0x4A, 0x87, 0x14, 0x18]),
                (1, _) => self.buf.emit(&[0x42, 0x88, 0x14, 0x18]),
                (2, _) => self.buf.emit(&[0x66, 0x42, 0x89, 0x14, 0x18]),
                (4, _) => self.buf.emit(&[0x42, 0x89, 0x14, 0x18]),
                _ => self.buf.emit(&[0x4A, 0x89, 0x14, 0x18]),
            }
        } else {
            // The raw bytes into RAX (SIB: base RAX, index R11).
            match w {
                1 => self.buf.emit(&[0x4A, 0x0F, 0xBE, 0x04, 0x18]), // MOVSX RAX, BYTE
                2 => self.buf.emit(&[0x42, 0x0F, 0xB7, 0x04, 0x18]), // MOVZX EAX, WORD
                4 => self.buf.emit(&[0x42, 0x8B, 0x04, 0x18]),       // MOV EAX, DWORD
                _ => self.buf.emit(&[0x4A, 0x8B, 0x04, 0x18]),       // MOV RAX, QWORD
            }
            self.emit_unsafe_inline_swap(w, big_endian, big_endian_const, RAX);
            // Widen the way the helper's `i64::from(..)` did: `short`/`int`
            // sign-extend, `char` zero-extends. L2-2: a `float` keeps the
            // zero-extended bits of its `MOV EAX`; a `boolean` is normalised
            // to `0`/`1` (`native_unsafe_get_boolean_mb`, HotSpot).
            match w {
                2 if access.signed => self.buf.emit(&[0x48, 0x0F, 0xBF, 0xC0]), // MOVSX RAX, AX
                2 => self.buf.emit(&[0x0F, 0xB7, 0xC0]),                        // MOVZX EAX, AX
                4 if access.is_fp() => {}
                4 => self.buf.emit(&[0x48, 0x63, 0xC0]), // MOVSXD RAX, EAX
                _ => {}
            }
            if access.value_kind == b'Z' {
                self.buf
                    .emit(&crate::direct_helpers::UNSAFE_BOOLEAN_NORMALIZE_RAX);
            }
            // The call route's `store_rax(slot)` at run time, written as the
            // ArrayList prefix writes it: the register when the value has
            // one, then the home word.
            if let Some(reg) = self.assigned_gpr(id) {
                self.emit_mov_reg_reg64(reg, RAX);
            }
            if let Some(slot) = slot {
                let mut bytes = FrameAccess::new();
                enc_frame_store(RAX, slot, &mut bytes);
                self.buf.emit(bytes.as_slice());
            }
        }
        let hit = self.emit_jmp_rel32();
        if let (Some(to_field), Some((cells, epoch_addr))) = (to_field, field_arm) {
            // W7-L3-1: R11 = the offset, then the cell screen leaves R11 = the
            // compact displacement the VM's hardware field atomic published
            // for this `(class id, slot, width)`, or declines. RAX (the base)
            // is untouched by the screen.
            self.patch_rel32_to_here(to_field);
            self.gp_load_value(R11, offset);
            let (bytes, edges) =
                crate::direct_helpers::unsafe_inline_field_cell_bytes(cells, epoch_addr, w);
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            decline.extend(edges.into_iter().map(|e| at + e));
            self.emit_jmp_back_to(field_join);
            if crate::x64::dbg_jitc_enabled() {
                eprintln!("[cratonvm-jitc] ir-unsafe-inline n{id} volatile field arm");
            }
        }
        if offheap {
            // nio21 wave 4 L3 (proposal W3L3-2): a null base, the single-pass
            // prefix's off-heap arm (`x64::op_invoke` `emit_sp_offheap_address`)
            // in this tier. The helper's `raw_accessor_{read,write}_bytes` with
            // `obj == 0`: a positive untagged address is a real pointer; a
            // tagged one is an arena handle, served inline only when it
            // resolves to a live slotted block holding the whole access.
            // Everything else declines to the unchanged call.
            self.patch_rel32_to_here(to_offheap);
            self.gp_load_value(R11, offset);
            let table = scoped_arena_jit_table(&self.direct_helpers);
            let (bytes, edges) = unsafe_offheap_address_decline_bytes(table, w);
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            decline.extend(edges.into_iter().map(|e| at + e));
            // RDX = the real address. RAX carries the value or the result
            // (RDX is not free for the value, as it is in the heap arm).
            if let Some(value) = value {
                self.gp_load_value(RAX, value);
                self.emit_unsafe_inline_swap(w, big_endian, big_endian_const, RAX);
                match w {
                    1 => self.buf.emit(&[0x88, 0x02]),       // MOV [RDX], AL
                    2 => self.buf.emit(&[0x66, 0x89, 0x02]), // MOV [RDX], AX
                    4 => self.buf.emit(&[0x89, 0x02]),       // MOV [RDX], EAX
                    _ => self.buf.emit(&[0x48, 0x89, 0x02]), // MOV [RDX], RAX
                }
            } else {
                match w {
                    1 => self.buf.emit(&[0x48, 0x0F, 0xBE, 0x02]), // MOVSX RAX, BYTE [RDX]
                    2 => self.buf.emit(&[0x0F, 0xB7, 0x02]),       // MOVZX EAX, WORD [RDX]
                    4 => self.buf.emit(&[0x8B, 0x02]),             // MOV EAX, [RDX]
                    _ => self.buf.emit(&[0x48, 0x8B, 0x02]),       // MOV RAX, [RDX]
                }
                self.emit_unsafe_inline_swap(w, big_endian, big_endian_const, RAX);
                match w {
                    2 if access.signed => self.buf.emit(&[0x48, 0x0F, 0xBF, 0xC0]), // MOVSX RAX, AX
                    2 => self.buf.emit(&[0x0F, 0xB7, 0xC0]),                        // MOVZX EAX, AX
                    4 => self.buf.emit(&[0x48, 0x63, 0xC0]), // MOVSXD RAX, EAX
                    _ => {}
                }
                if let Some(reg) = self.assigned_gpr(id) {
                    self.emit_mov_reg_reg64(reg, RAX);
                }
                if let Some(slot) = slot {
                    let mut bytes = FrameAccess::new();
                    enc_frame_store(RAX, slot, &mut bytes);
                    self.buf.emit(bytes.as_slice());
                }
            }
            // Join the heap arm's hit `JMP` (one hit edge for the caller).
            self.emit_jmp_back_to(hit - 1);
            if crate::x64::dbg_jitc_enabled() {
                eprintln!(
                    "[cratonvm-jitc] ir-unsafe-inline n{id} off-heap arm (arena table: {})",
                    table.is_some()
                );
            }
        }
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// The heap-array screen of [`Self::try_emit_ir_unsafe_access_prefix`] and
    /// [`Self::try_emit_ir_unsafe_rmw_prefix`] (moved out unchanged by nio21
    /// wave 5 L3; the single-pass twin is `x64::op_invoke`'s
    /// `emit_sp_prim_array_screen`): RAX = a non-null base. Loads R11 =
    /// `offset` (a `long`) and leaves RAX = the base, R11 = the offset, or
    /// jumps to a `decline` edge unless the base is a one-dimensional
    /// PRIMITIVE array whose payload holds `[offset - 16, offset - 16 + w)`.
    /// Writes RCX, RDX, R10, R11.
    fn emit_ir_unsafe_prim_array_screen(
        &mut self,
        offset: NodeId,
        w: u8,
        decline: &mut Vec<usize>,
    ) {
        // `offset` is a JAVA offset: `Unsafe.arrayBaseOffset` (16, the
        // helpers' `ABASE`) plus the byte index, so `base + offset` is the
        // byte's address only while the payload starts there.
        const _: () = assert!(
            cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the Unsafe inline prefix assumes Unsafe.arrayBaseOffset (16) == ARRAY_DATA_OFFSET"
        );
        const KIND_TAGS: u8 = cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8; // Cast: x86-64 disp8
                                                                           // The checked narrowing: a length offset past 127 fails the build
                                                                           // instead of encoding a negative disp8.
        const LEN: u8 =
            crate::x64::disp::disp8_const(cratonvm_types::ARRAY_LENGTH_OFFSET as i64) as u8;
        const ARRAY_KIND: u8 = cratonvm_types::ObjectKind::Array as u8;
        // The primitive element tags are 4 (`Boolean`) ..= 11 (`Long`), so the
        // whole tag byte of a primitive array is 0x11 ..= 0x2D, and
        // `element_type & 3` is log2 of its element size (pinned by
        // `direct_helpers`' `element_tag_low_bits_are_log2_of_the_element_size`).
        const PRIM_LO: u8 = ARRAY_KIND | ((cratonvm_types::ArrayElementType::Boolean as u8) << 2);
        const PRIM_HI: u8 = ARRAY_KIND | ((cratonvm_types::ArrayElementType::Long as u8) << 2);
        const _: () = assert!(PRIM_LO == 0x11 && PRIM_HI == 0x2D);
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
        // RCX: the tag byte, then the scale.
        self.note_rcx_written();
        // ECX = the kind/element tag byte; EDX = its kind bits.
        self.buf.emit(&[0x0F, 0xB6, 0x48, KIND_TAGS]); // MOVZX ECX, BYTE [RAX+KIND_TAGS]
        self.buf.emit(&[0x89, 0xCA]); // MOV EDX, ECX
        self.buf
            .emit(&[0x83, 0xE2, cratonvm_types::KIND_TAG_BYTE_MASK]); // AND EDX, kind mask
        self.buf.emit(&[0x83, 0xFA, ARRAY_KIND]); // CMP EDX, Array
        decline.push(self.emit_jcc_rel32(0x85)); // JNE: not an array
        self.buf.emit(&[0x83, 0xF9, PRIM_LO]); // CMP ECX, PRIM_LO
        decline.push(self.emit_jcc_rel32(0x82)); // JB: reference array
        self.buf.emit(&[0x83, 0xF9, PRIM_HI]); // CMP ECX, PRIM_HI
        decline.push(self.emit_jcc_rel32(0x87)); // JA: no such element type
        self.buf.emit(&[0xC1, 0xE9, 0x02]); // SHR ECX, 2
        self.buf.emit(&[0x83, 0xE1, 0x03]); // AND ECX, 3 (log2 element size)
                                            // RDX = payload bytes = length << log2 (a u32 shifted by <= 3: no wrap).
        self.buf.emit(&[0x8B, 0x50, LEN]); // MOV EDX, [RAX+LEN] (zero-extends)
        self.buf.emit(&[0x48, 0xD3, 0xE2]); // SHL RDX, CL
                                            // R11 = offset (a `long`).
        self.gp_load_value(R11, offset);
        // CMP R11, ARRAY_DATA_OFFSET ; JL decline (signed: below the payload).
        self.buf
            .emit(&[0x49, 0x83, 0xFB, cratonvm_types::ARRAY_DATA_OFFSET as u8]); // Cast: 16
        decline.push(self.emit_jcc_rel32(0x8C));
        // R10 = offset - ARRAY_DATA_OFFSET + width, the access's END in the
        // payload: positive here, and no wrap (offset < 2^63).
        let end_disp = (i32::from(w) - cratonvm_types::ARRAY_DATA_OFFSET as i32) as i8; // Cast: -15..=-8
        self.buf.emit(&[0x4D, 0x8D, 0x53, end_disp as u8]); // LEA R10, [R11 + disp8]
        self.buf.emit(&[0x49, 0x39, 0xD2]); // CMP R10, RDX
        decline.push(self.emit_jcc_rel32(0x87)); // JA (unsigned): past the payload
    }

    /// nio21 wave 5 L3 (`r21-unsafe-volatile-accessors-are-thin-calls-not-inline-and-getandadd-is-not-one-xadd-FIXED-20261012.md`):
    /// an `Unsafe` CAS / getAndAdd / getAndSet on an aligned primitive-array
    /// element as ONE locked instruction (`LOCK CMPXCHG` / `LOCK XADD` /
    /// `XCHG`), a guarded prefix of the `Op::Call`'s unchanged lowering with
    /// the contract of [`Self::try_emit_ir_unsafe_access_prefix`] (scratch
    /// RAX, RCX, RDX, R10, R11; no GC point, no call, no deopt on the hit
    /// path). Sites and the served set: `direct_helpers::unsafe_inline_rmw_site`
    /// and the section comment above it. A null receiver or base, a reference
    /// array, an out-of-range or misaligned offset all decline to the call, so
    /// every element this writes is one the natives also update with a
    /// hardware atomic (`vm_exec::hw_cas_primitive_array_element`,
    /// `primitive_array_atomic_update`).
    ///
    /// nio21 wave 7 L3: a plain-object base takes the instance-field arm
    /// (`direct_helpers::unsafe_inline_field_cell_bytes`, out of line after the
    /// hit path) when this VM baked its cell table: a compact instance whose
    /// `(class id, offset, width)` the VM's hardware field CAS has published
    /// is updated at the published displacement by the same locked
    /// instruction; anything else declines. The `compareAndExchange*` rows
    /// (`UnsafeRmwOp::Cae`) keep CMPXCHG's witness as the result.
    ///
    /// For `getAndAdd` / `getAndSet` the call is the JDK's Java body (a
    /// `getXVolatile` + `weakCompareAndSetX` loop) or, in `--compatible`, the
    /// registered native; one `LOCK XADD` / `XCHG` is what HotSpot's
    /// intrinsic emits for either. No barrier: the bytes are primitive.
    fn try_emit_ir_unsafe_rmw_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        rmw: crate::direct_helpers::UnsafeInlineRmw,
    ) {
        if !matches!(info.invoke_kind, 0 | 1)
            || !rmw.admitted(self.direct_helpers.unsafe_inline_admitted)
            || !crate::direct_helpers::unsafe_accessor_inline_enabled()
            || !crate::ir_thin_prefix_enabled()
        {
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, base, offset, a, (b)]
        if node.inputs.len() != 3 + rmw.num_params() {
            return;
        }
        let want_ty = if rmw.ret_type() == b'J' {
            IrType::Long
        } else {
            IrType::Int
        };
        if node.ty != want_ty || node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            return;
        }
        // The result's home, as the accessor prefix computes it.
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        let recv = node.inputs[2];
        let base = node.inputs[3];
        let offset = node.inputs[4];
        // CAS / compareAndExchange: (expected, new); getAndAdd: delta;
        // getAndSet: new; getAndBitwise: the mask.
        let (expected, operand) = if rmw.has_expected() {
            (Some(node.inputs[5]), node.inputs[6])
        } else {
            (None, node.inputs[5])
        };
        // nio21 wave 7 L3 (W6-L3-1): the instance-field arm, when this VM
        // published its cell table and no armed ZGC read barrier forbids an
        // inline field access (as for every other inline field arm).
        let field_arm = crate::direct_helpers::unsafe_field_arm_words(&self.direct_helpers);
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-unsafe-rmw-inline n{id} {}.{}{} width={} op={:?} field_arm={}",
                info.class_name,
                info.method_name,
                info.descriptor,
                rmw.width,
                rmw.op,
                field_arm.is_some(),
            );
        }
        let w = rmw.width;
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        // R10 = the `Unsafe` receiver; null declines (the call's NPE).
        self.gp_load_value(R10, recv);
        self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // RAX = base; null (an off-heap address, an arena handle, a static
                                                 // base) declines: no off-heap arm for an atomic.
        self.gp_load_value(RAX, base);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // A non-array base takes the field arm (emitted after the hit path);
                                                 // without one it declines in the array screen's own kind test.
        let to_field = field_arm.map(|_| {
            let (bytes, edge) = crate::direct_helpers::unsafe_inline_not_array_bytes();
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            at + edge
        });
        self.emit_ir_unsafe_prim_array_screen(offset, w, &mut decline);
        // Natural alignment (and, under the natives' old arm order, their
        // synthetic band).
        let (screen, edges) = crate::direct_helpers::unsafe_inline_rmw_screen_bytes(w);
        let at = self.buf.pos();
        self.buf.emit(&screen);
        decline.extend(edges.into_iter().map(|e| at + e));
        // RAX = the base, R11 = the payload displacement: the array arm's
        // offset or the field arm's compact displacement. The field arm joins
        // here.
        let join = self.buf.pos();
        // R10 = expected (a CAS); RDX = the operand. The screen is done with
        // both registers.
        if let Some(expected) = expected {
            self.gp_load_value(R10, expected);
        }
        self.gp_load_value(RDX, operand);
        self.buf
            .emit(&crate::direct_helpers::unsafe_inline_rmw_bytes(rmw));
        // The call route's `store_rax(slot)`: the register, then the home.
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        if let (Some(to_field), Some((cells, epoch_addr))) = (to_field, field_arm) {
            // The field arm: R11 = the offset, then the cell screen leaves
            // R11 = the published compact displacement or declines.
            self.patch_rel32_to_here(to_field);
            self.gp_load_value(R11, offset);
            let (bytes, edges) =
                crate::direct_helpers::unsafe_inline_field_cell_bytes(cells, epoch_addr, w);
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            decline.extend(edges.into_iter().map(|e| at + e));
            self.emit_jmp_back_to(join);
        }
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 20 wave 12, lane qUnsafe (AT-4 / W7-L3-2): a
    /// `compareAndSetReference` (or `weakCompareAndSetReference*`) on a
    /// published COMPACT reference field as ONE `LOCK CMPXCHG`, a guarded
    /// prefix of the `Op::Call`'s unchanged lowering with the contract of
    /// [`Self::try_emit_ir_unsafe_access_prefix`] (scratch RAX, RCX, RDX,
    /// R10, R11; no GC point, no call, no deopt on the hit path). The section
    /// comment above `direct_helpers::unsafe_qu_ref_cas_field_enabled` says
    /// what is served and why; the single-pass twin is `x64::op_invoke`'s
    /// `emit_sp_unsafe_ref_cas_core`, byte for byte the same pieces:
    ///
    /// null receiver / null base / an array base -> decline; the reference
    /// store gate screen ([`vh_ref_store_gate_screen_bytes`], RAX = the
    /// holder, RDX = the new value) -> decline unless both barriers are
    /// provably no-ops; the reference cell screen
    /// (`direct_helpers::unsafe_inline_ref_field_cell_bytes`) -> R11 = the
    /// compact displacement or decline; then the `Unsafe` RMW prefixes' own
    /// CAS bytes (`unsafe_inline_rmw_bytes`, width 8).
    fn try_emit_ir_unsafe_ref_cas_prefix(&mut self, id: NodeId, info: &JitInvokeInfo) {
        if !matches!(info.invoke_kind, 0 | 1)
            || !crate::ir_thin_prefix_enabled()
            || crate::x64::zgc_read_barrier_blocks_inline_fields()
        {
            return;
        }
        let Some((cells, epoch_addr)) =
            crate::direct_helpers::unsafe_ref_cas_field_arm_words(&self.direct_helpers)
        else {
            return;
        };
        let Some(gates) = vh_ref_store_gates(self.ref_store_gates, self.ref_store_post_skip_mask)
        else {
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, base, offset, expected, new]
        if node.inputs.len() != 7
            || node.ty != IrType::Int
            || node.inputs[2..].iter().any(|&i| self.carry_names(i))
        {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        let (recv, base, offset) = (node.inputs[2], node.inputs[3], node.inputs[4]);
        let (expected, new) = (node.inputs[5], node.inputs[6]);
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-unsafe-ref-cas-inline n{id} {}.{}{}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        // R10 = the `Unsafe` receiver; null declines (the call's NPE).
        self.gp_load_value(R10, recv);
        self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // RAX = base; null (a static base, an off-heap address) declines.
        self.gp_load_value(RAX, base);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // An array base (a reference-array element) declines: the field arm
                                                 // only. The kind test jumps over the decline for a non-array base.
        let (bytes, edge) = crate::direct_helpers::unsafe_inline_not_array_bytes();
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        let to_field = at + edge;
        decline.push(self.emit_jmp_rel32());
        self.patch_rel32_to_here(to_field);
        // The barrier gates, decided before the store (RAX = holder, RDX =
        // the new value; writes RCX, R11).
        self.gp_load_value(RDX, new);
        let (bytes, edges) = vh_ref_store_gate_screen_bytes(gates);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        // R11 = the offset, then the published displacement (writes RCX,
        // RDX, R10, R11).
        self.gp_load_value(R11, offset);
        let (bytes, edges) =
            crate::direct_helpers::unsafe_inline_ref_field_cell_bytes(cells, epoch_addr);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        // R10 = expected, RDX = new; the CAS leaves `0`/`1` in RAX.
        self.gp_load_value(R10, expected);
        self.gp_load_value(RDX, new);
        self.buf
            .emit(&crate::direct_helpers::unsafe_inline_rmw_bytes(
                crate::direct_helpers::UnsafeInlineRmw {
                    width: 8,
                    op: crate::direct_helpers::UnsafeRmwOp::Cas,
                },
            ));
        // The call route's `store_rax(slot)`: the register, then the home.
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 21 wave 1, lane updaters (UPDATERS21-1,
    /// `CRATONVM_JIT_UNSAFE_REF_VOLATILE_FIELD`, opt-in): a
    /// `getReferenceVolatile` / `putReferenceVolatile` (and their acquire /
    /// opaque / release bodies) on a published COMPACT reference field as one
    /// `MOV` load / one `XCHG` or `MOV` store, a guarded prefix of the
    /// `Op::Call`'s unchanged lowering with the contract of
    /// [`Self::try_emit_ir_unsafe_access_prefix`] (scratch RAX, RCX, RDX, R10,
    /// R11; no GC point, no call, no deopt on the hit path). What is served and
    /// why: the section comment above
    /// `direct_helpers::unsafe_ref_volatile_field_enabled`. The single-pass
    /// twin is `x64::op_invoke`'s `emit_sp_unsafe_ref_volatile_core`.
    ///
    /// null receiver / null base / an array base -> decline; for a put the
    /// reference-store gate screen ([`vh_ref_store_gate_screen_bytes`], RAX =
    /// holder, RDX = value) -> decline unless both barriers are provably
    /// no-ops; the reference cell screen -> R11 = the displacement or decline;
    /// then `direct_helpers::unsafe_ref_volatile_access_bytes`.
    fn try_emit_ir_unsafe_ref_volatile_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        access: crate::direct_helpers::UnsafeRefVolatileAccess,
    ) {
        if !matches!(info.invoke_kind, 0 | 1)
            || !crate::ir_thin_prefix_enabled()
            || crate::x64::zgc_read_barrier_blocks_inline_fields()
        {
            return;
        }
        let Some((cells, epoch_addr)) =
            crate::direct_helpers::unsafe_ref_volatile_field_arm_words(&self.direct_helpers, access)
        else {
            return;
        };
        let gates = if access.is_put {
            match vh_ref_store_gates(self.ref_store_gates, self.ref_store_post_skip_mask) {
                Some(g) => Some(g),
                None => return,
            }
        } else {
            None
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, base, offset, (value)]
        let want_ty = if access.is_put {
            IrType::Void
        } else {
            IrType::Ref
        };
        if node.inputs.len() != 3 + access.num_params()
            || node.ty != want_ty
            || node.inputs[2..].iter().any(|&i| self.carry_names(i))
        {
            return;
        }
        let slot = if access.is_put {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                return;
            }
            match self.planned_slot_off(id) {
                Ok(slot) => Some(slot),
                Err(_) => return,
            }
        };
        let (recv, base, offset) = (node.inputs[2], node.inputs[3], node.inputs[4]);
        let value = if access.is_put {
            Some(node.inputs[5])
        } else {
            None
        };
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir-unsafe-ref-volatile-inline n{id} {}.{}{} put={}",
                info.class_name, info.method_name, info.descriptor, access.is_put,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        // R10 = the `Unsafe` receiver; null declines (the call's NPE).
        self.gp_load_value(R10, recv);
        self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        // RAX = base; null (a static base, an off-heap address) declines.
        self.gp_load_value(RAX, base);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        // An array base declines; a plain object jumps over that decline.
        let (bytes, edge) = crate::direct_helpers::unsafe_inline_not_array_bytes();
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        let to_field = at + edge;
        decline.push(self.emit_jmp_rel32());
        self.patch_rel32_to_here(to_field);
        if let (Some(g), Some(value)) = (gates, value) {
            // The barrier gates, decided before the store (RAX = holder, RDX
            // = the value; writes RCX, R11).
            self.gp_load_value(RDX, value);
            let (bytes, edges) = vh_ref_store_gate_screen_bytes(g);
            let at = self.buf.pos();
            self.buf.emit(&bytes);
            decline.extend(edges.into_iter().map(|e| at + e));
        }
        // R11 = the offset, then the published displacement (writes RCX,
        // RDX, R10, R11).
        self.gp_load_value(R11, offset);
        let (bytes, edges) =
            crate::direct_helpers::unsafe_inline_ref_field_cell_bytes(cells, epoch_addr);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        if let Some(value) = value {
            self.gp_load_value(RDX, value);
        }
        self.buf
            .emit(&crate::direct_helpers::unsafe_ref_volatile_access_bytes(access));
        if let Some(slot) = slot {
            // The call route's `store_rax(slot)`: the register, then the home.
            if let Some(reg) = self.assigned_gpr(id) {
                self.emit_mov_reg_reg64(reg, RAX);
            }
            let mut bytes = FrameAccess::new();
            enc_frame_store(RAX, slot, &mut bytes);
            self.buf.emit(bytes.as_slice());
        }
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio21 wave 11 L5 (W9L2-2, page
    /// `r21-varhandle-constant-handle-field-access-inline-FIXED-20261012.md`): a
    /// `VarHandle` access-mode call whose handle operand IS a `getstatic` of a
    /// `static final` field the VM filed a constant plan for, as the field
    /// access itself -- a guarded PREFIX of the `Op::Call`'s unchanged lowering
    /// with the contract of [`Self::try_emit_ir_unsafe_access_prefix`]
    /// (scratch RAX, RCX, RDX, R10, R11 only; the hit edge writes the result
    /// home and register and jumps to [`Self::call_prefix_join`]; no call, no
    /// GC point, no deopt on the hit path). The shared section above
    /// `vh_const_core_bytes` says what is served; every receiver, value or
    /// barrier shape it does not serve declines to the call, which answers it
    /// exactly as before.
    ///
    /// The `getstatic` is the proof that the handle is the filed one: a
    /// `static final` is written once, by `<clinit>`, before the VM filed it.
    /// The node stays in the graph (it is this call's input), so its class
    /// initialisation obligation is unchanged.
    ///
    /// Declines at compile time under `CRATONVM_JIT_VH_CONST_INLINE=0` (and
    /// `CRATONVM_JIT_VH_CONST_REF_INLINE=0` for a reference field), for a site
    /// shape [`vh_const_site_shape`] refuses, a handle operand that is not a
    /// `LoadStatic`, no filed plan, no compact layout for the slot, an armed
    /// ZGC read barrier, an operand some carry is holding, and a result that is
    /// carried or has its home dropped.
    fn try_emit_ir_vh_const_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 || !vh_const_inline_enabled() {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if info.class_name != "java/lang/invoke/VarHandle"
            || !matches!(info.invoke_kind, 0 | 1)
            || crate::x64::zgc_read_barrier_blocks_inline_fields()
        {
            return;
        }
        let Some(shape) = vh_const_site_shape(info.method_name, info.descriptor) else {
            // JIT r20 wave 18 (lane xVhArr, AT-2): an array-element shape.
            self.try_emit_ir_vh_const_array_prefix(id, info);
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, handle, receiver, values...]
        if node.inputs.len() != 4 + shape.values.len() {
            return;
        }
        let want_ty = match shape.ret {
            b'V' => IrType::Void,
            b'J' => IrType::Long,
            b'L' | b'[' => IrType::Ref,
            _ => IrType::Int,
        };
        if node.ty != want_ty || node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            return;
        }
        let handle = node.inputs[2];
        let Some(Op::LoadStatic {
            class_id,
            field_index,
            ..
        }) = graph.nodes.get(handle as usize).map(|n| &n.op)
        else {
            return;
        };
        let (static_class, static_field) = (*class_id, *field_index as usize); // Cast: u32 index
        let Some(plan) = vh_const_plan(&self.direct_helpers, static_class, static_field) else {
            return;
        };
        let ref_facts = if plan.kind == b'L' {
            match vh_const_ref_facts(&self.direct_helpers, static_class, static_field) {
                Some(facts) => Some(facts),
                None => return,
            }
        } else {
            None
        };
        // `class_id_offset_in_obj` is 0 by contract (the ArrayList prefix bakes
        // the same `[RAX + 0]`).
        let Some(core) = vh_const_core_cast_return(
            &self.direct_helpers,
            &shape,
            plan,
            ref_facts.as_ref(),
            info.declaring_class_id,
            self.ref_store_gates,
            self.ref_store_post_skip_mask,
            0,
        ) else {
            return;
        };
        let slot = if want_ty == IrType::Void {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                return;
            }
            match self.planned_slot_off(id) {
                Ok(slot) => Some(slot),
                Err(_) => return,
            }
        };
        let recv = node.inputs[3];
        let (expected, operand) = if shape.has_expected() {
            (Some(node.inputs[4]), Some(node.inputs[5]))
        } else if shape.values.len() == 1 {
            (None, Some(node.inputs[4]))
        } else {
            (None, None)
        };
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] vh-const-inline (ir) n{id} {}{} kind={} class={} slot={} disp={} \
                 static=({static_class},{static_field}) checks={:?}/{:?} gated={}",
                info.method_name,
                info.descriptor,
                char::from(core.kind),
                core.class_id,
                plan.slot,
                core.disp,
                core.expected_check,
                core.value_check,
                core.gates.is_some(),
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        // First: the epoch guard's fallback form clobbers R11 and ECX.
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        self.gp_load_value(RAX, recv);
        if let Some(expected) = expected {
            self.gp_load_value(R10, expected);
        }
        if let Some(operand) = operand {
            self.gp_load_value(RDX, operand);
        }
        let (bytes, edges) = vh_const_core_bytes(&core);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        // The call route's `store_rax(slot)`, as the other prefixes write it.
        if let Some(slot) = slot {
            if let Some(reg) = self.assigned_gpr(id) {
                self.emit_mov_reg_reg64(reg, RAX);
            }
            let mut bytes = FrameAccess::new();
            enc_frame_store(RAX, slot, &mut bytes);
            self.buf.emit(bytes.as_slice());
        }
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 21 wave 16 (lane perf-cf-lean,
    /// `CRATONVM_JIT_IR_CALL_ENTRY_NULL_GUARD`, opt-in; page
    /// `docs/known-issues/jit/r21-completablefuture-stage-cost-is-allocation-and-calls-20261018.md`):
    /// a `void` instance call whose resolved target begins with a pure null
    /// test of one reference field of `this` that returns at once on null,
    /// as a guarded PREFIX of the `Op::Call`'s unchanged lowering: when the
    /// field reads null the call is skipped (the hit edge stores nothing --
    /// the method is `void` -- and jumps to [`Self::call_prefix_join`]); any
    /// other receiver or a non-null field declines to the call. No call, no
    /// GC point and no deopt on the hit path.
    ///
    /// The VM decides admission (`jit_bridge::call_entry_null_guard_answer`):
    /// a receiver-bound target (private, final, or in / reached from a final
    /// class), not static, native, abstract, synchronized or a constructor,
    /// with no registered native shadowing it and no breakpoint in it, whose
    /// entry path -- abstractly executed with that field null -- touches only
    /// locals, `this`, that field and reference compares before `return`.
    /// The VM records the target class as copied bytecode, so a redefinition
    /// of it withdraws this body. Skipping is then exactly the callee's own
    /// execution with no side effect: one read of the field, then `return`.
    /// A racing writer between the read and the skip is the race the callee
    /// has between its read and its return.
    ///
    /// Declines at compile time with the switch off, for a static or
    /// interface site, a constructor, a non-`void` descriptor, narrow oops or
    /// an armed ZGC read barrier, a carried receiver, and no VM answer.
    fn try_emit_ir_call_entry_null_guard_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 || !ir_call_entry_null_guard_enabled() {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if !matches!(info.invoke_kind, 0 | 1)
            || !info.descriptor.ends_with(")V")
            || info.method_name.starts_with('<')
            || info.declaring_class_id == 0
            || crate::x64::narrow_oops_block_inline_fields()
            || crate::x64::zgc_read_barrier_blocks_inline_fields()
        {
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, args...], void.
        if node.ty != IrType::Void || node.inputs.len() < 3 || self.carry_names(node.inputs[2]) {
            return;
        }
        let Some((disp, volatile)) = call_entry_null_guard_ask(&self.direct_helpers, info) else {
            return;
        };
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] call-entry-null-guard (ir) n{id} {}.{}{} disp={disp} volatile={volatile}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        // The epoch guard's fallback form clobbers R11 and ECX.
        self.note_rcx_written();
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        self.gp_load_value(RAX, node.inputs[2]);
        let (bytes, edges) = call_entry_null_guard_bytes(disp);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r20 wave 18 (lane xVhArr, AT-2 of
    /// `docs/internal/proposals/jit/jit-r20-atomics-proposals.md`): the
    /// ARRAY-ELEMENT arm of [`Self::try_emit_ir_vh_const_prefix`] (which has
    /// checked the switch, the `VarHandle` site and the ZGC gate), with the
    /// same prefix contract: a `VarHandle` access whose handle operand IS a
    /// `getstatic` of a `static final` filed as an `int[]` / `long[]` element
    /// handle ([`vh_const_array_plan`]) runs as the element access
    /// ([`vh_const_array_core_bytes`]); a null array, an index out of range,
    /// another array shape decline to the unchanged call. The section above
    /// `vh_const_array_element_enabled` says what is served.
    ///
    /// Declines at compile time under `CRATONVM_JIT_VH_CONST_ARRAY_ELEMENT=0`,
    /// for a shape [`vh_const_array_site_shape`] refuses, a handle operand
    /// that is not a `LoadStatic`, no filed array plan of the site's kind, an
    /// operand some carry is holding, and a result that is carried or has its
    /// home dropped.
    fn try_emit_ir_vh_const_array_prefix(&mut self, id: NodeId, info: &JitInvokeInfo) {
        let Some(shape) = vh_const_array_site_shape(info.method_name, info.descriptor) else {
            return;
        };
        // JIT round 21 wave 1, lane updaters (UPDATERS21-5).
        if shape.kind == b'L' {
            self.try_emit_ir_vh_const_ref_array_prefix(id, info, &shape);
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, handle, array, index, values...]
        if node.inputs.len() != 5 + shape.values.len() {
            return;
        }
        let want_ty = match shape.ret {
            b'V' => IrType::Void,
            b'J' => IrType::Long,
            _ => IrType::Int,
        };
        if node.ty != want_ty || node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            return;
        }
        let handle = node.inputs[2];
        let Some(Op::LoadStatic {
            class_id,
            field_index,
            ..
        }) = graph.nodes.get(handle as usize).map(|n| &n.op)
        else {
            return;
        };
        let (static_class, static_field) = (*class_id, *field_index as usize); // Cast: u32 index
        let Some(plan_kind) = vh_const_array_plan(&self.direct_helpers, static_class, static_field)
        else {
            return;
        };
        let Some(core) = vh_const_array_core(&shape, plan_kind) else {
            return;
        };
        let slot = if want_ty == IrType::Void {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                return;
            }
            match self.planned_slot_off(id) {
                Ok(slot) => Some(slot),
                Err(_) => return,
            }
        };
        let (array, index) = (node.inputs[3], node.inputs[4]);
        let (expected, operand) = if shape.has_expected() {
            (Some(node.inputs[5]), Some(node.inputs[6]))
        } else if shape.values.len() == 1 {
            (None, Some(node.inputs[5]))
        } else {
            (None, None)
        };
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] vh-const-array-inline (ir) n{id} {}{} kind={} \
                 static=({static_class},{static_field})",
                info.method_name,
                info.descriptor,
                char::from(core.kind),
            );
        }
        self.note_rcx_written();
        // RAX = the array, R11 = the index, then R10 / RDX (loads into R10 /
        // RDX leave RAX and R11 alone, as the `Unsafe` RMW prefix relies on).
        self.gp_load_value(RAX, array);
        self.gp_load_value(R11, index);
        if let Some(expected) = expected {
            self.gp_load_value(R10, expected);
        }
        if let Some(operand) = operand {
            self.gp_load_value(RDX, operand);
        }
        let (bytes, edges) = vh_const_array_core_bytes(&core);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        let decline: Vec<usize> = edges.into_iter().map(|e| at + e).collect();
        // The call route's `store_rax(slot)`, as the other prefixes write it.
        if let Some(slot) = slot {
            if let Some(reg) = self.assigned_gpr(id) {
                self.emit_mov_reg_reg64(reg, RAX);
            }
            let mut bytes = FrameAccess::new();
            enc_frame_store(RAX, slot, &mut bytes);
            self.buf.emit(bytes.as_slice());
        }
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 21 wave 1, lane updaters (UPDATERS21-5,
    /// `CRATONVM_JIT_VH_CONST_REF_ARRAY_GET`, opt-in): the reference-array
    /// GET arm of [`Self::try_emit_ir_vh_const_array_prefix`], with the same
    /// prefix contract. The section above `vh_const_ref_array_get_enabled`
    /// says what is served and why.
    fn try_emit_ir_vh_const_ref_array_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        shape: &VhConstShape,
    ) {
        // JIT round 21 wave 22, lane vhconst (UPDATERS21-5,
        // `CRATONVM_JIT_VH_CONST_REF_ARRAY_STORE`): the store modes.
        if shape.op != VhConstOp::Get {
            self.try_emit_ir_vh_const_ref_array_store_prefix(id, info, shape);
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, handle, array, index]
        if node.inputs.len() != 5
            || node.ty != IrType::Ref
            || node.inputs[2..].iter().any(|&i| self.carry_names(i))
        {
            return;
        }
        let handle = node.inputs[2];
        let Some(Op::LoadStatic {
            class_id,
            field_index,
            ..
        }) = graph.nodes.get(handle as usize).map(|n| &n.op)
        else {
            return;
        };
        let (static_class, static_field) = (*class_id, *field_index as usize); // Cast: u32 index
        let Some(plan_kind) = vh_const_array_plan(&self.direct_helpers, static_class, static_field)
        else {
            return;
        };
        let Some(core) = vh_const_ref_array_core(
            &self.direct_helpers,
            shape,
            plan_kind,
            info.declaring_class_id,
            0,
        ) else {
            return;
        };
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        let (array, index) = (node.inputs[3], node.inputs[4]);
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] vh-const-ref-array-inline (ir) n{id} {}{} \
                 static=({static_class},{static_field}) cast={:?}",
                info.method_name, info.descriptor, core.result_check,
            );
        }
        self.note_rcx_written();
        self.gp_load_value(RAX, array);
        self.gp_load_value(R11, index);
        let (bytes, edges) = vh_const_ref_array_get_bytes(&core);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        let decline: Vec<usize> = edges.into_iter().map(|e| at + e).collect();
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 21 wave 22, lane vhconst (UPDATERS21-5,
    /// `CRATONVM_JIT_VH_CONST_REF_ARRAY_STORE`, opt-in): the reference-array
    /// STORE arm (set / CAS / compareAndExchange / getAndSet) of
    /// [`Self::try_emit_ir_vh_const_array_prefix`], with the same prefix
    /// contract. The section above `vh_const_cast_cae_enabled` says what is
    /// served and why. The first half's screens (array, gates, store check)
    /// spend every scratch register, so the index, `expected` and the value
    /// are loaded again for the second half (index screen and the store):
    ///
    /// ```text
    ///   RAX = array ; RDX = value ; R10 = expected
    ///   <vh_const_ref_array_store_screen_bytes>
    ///   R11 = index ; R10 = expected ; RDX = value
    ///   <vh_const_ref_array_store_access_bytes>
    /// ```
    fn try_emit_ir_vh_const_ref_array_store_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        shape: &VhConstShape,
    ) {
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, handle, array, index, values...]
        if node.inputs.len() != 5 + shape.values.len() || shape.values.is_empty() {
            return;
        }
        let want_ty = match shape.ret {
            b'V' => IrType::Void,
            b'Z' => IrType::Int,
            _ => IrType::Ref,
        };
        if node.ty != want_ty || node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            return;
        }
        let handle = node.inputs[2];
        let Some(Op::LoadStatic {
            class_id,
            field_index,
            ..
        }) = graph.nodes.get(handle as usize).map(|n| &n.op)
        else {
            return;
        };
        let (static_class, static_field) = (*class_id, *field_index as usize); // Cast: u32 index
        let Some(plan_kind) = vh_const_array_plan(&self.direct_helpers, static_class, static_field)
        else {
            return;
        };
        let Some(core) = vh_const_ref_array_store_core(
            &self.direct_helpers,
            shape,
            plan_kind,
            self.ref_store_gates,
            self.ref_store_post_skip_mask,
            0,
        ) else {
            return;
        };
        let slot = if want_ty == IrType::Void {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                return;
            }
            match self.planned_slot_off(id) {
                Ok(slot) => Some(slot),
                Err(_) => return,
            }
        };
        let (array, index) = (node.inputs[3], node.inputs[4]);
        let (expected, operand) = if shape.has_expected() {
            (Some(node.inputs[5]), node.inputs[6])
        } else {
            (None, node.inputs[5])
        };
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] vh-const-ref-array-store-inline (ir) n{id} {}{} \
                 static=({static_class},{static_field}) display={}",
                info.method_name,
                info.descriptor,
                core.display_cell.is_some(),
            );
        }
        self.note_rcx_written();
        self.gp_load_value(RAX, array);
        if let Some(expected) = expected {
            self.gp_load_value(R10, expected);
        }
        self.gp_load_value(RDX, operand);
        let mut decline: Vec<usize> = Vec::new();
        let (bytes, edges) = vh_const_ref_array_store_screen_bytes(&core);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        // The screens spent RCX, RDX, R10 and R11; RAX still holds the array.
        self.gp_load_value(R11, index);
        if let Some(expected) = expected {
            self.gp_load_value(R10, expected);
        }
        self.gp_load_value(RDX, operand);
        let (bytes, edges) = vh_const_ref_array_store_access_bytes(&core);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
        // The call route's `store_rax(slot)`, as the other prefixes write it.
        if let Some(slot) = slot {
            if let Some(reg) = self.assigned_gpr(id) {
                self.emit_mov_reg_reg64(reg, RAX);
            }
            let mut bytes = FrameAccess::new();
            enc_frame_store(RAX, slot, &mut bytes);
            self.buf.emit(bytes.as_slice());
        }
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// The `bigEndian` byte swap of [`Self::try_emit_ir_unsafe_access_prefix`],
    /// on the low `width` bytes of `reg` (RAX or RDX). Nothing for a form
    /// without the operand or a constant `false`; unconditional for a constant
    /// `true`; otherwise behind `TEST ECX, ECX` on the operand loaded into RCX.
    /// A 2-byte swap leaves the upper bits as they were; the caller widens.
    fn emit_unsafe_inline_swap(
        &mut self,
        width: u8,
        big_endian: Option<NodeId>,
        big_endian_const: Option<bool>,
        reg: u8,
    ) {
        let Some(be) = big_endian else {
            return;
        };
        if width == 1 || big_endian_const == Some(false) {
            return;
        }
        let skip = if big_endian_const == Some(true) {
            None
        } else {
            self.gp_load_value(RCX, be);
            self.buf.emit(&[0x85, 0xC9]); // TEST ECX, ECX
            Some(self.emit_jcc_rel32(0x84)) // JZ: little-endian
        };
        let r = reg & 7; // RAX = 0, RDX = 2
        match width {
            2 => self.buf.emit(&[0x66, 0xC1, 0xC0 | r, 0x08]), // ROL r16, 8
            4 => self.buf.emit(&[0x0F, 0xC8 | r]),             // BSWAP r32
            _ => self.buf.emit(&[0x48, 0x0F, 0xC8 | r]),       // BSWAP r64
        }
        if let Some(p) = skip {
            self.patch_rel32_to_here(p);
        }
    }

    /// NIO19-9 (nio20 wave 1, lane L2): `Reference.reachabilityFence(Object)`
    /// as NO code, which is what HotSpot emits for it.
    ///
    /// The method's whole contract is that its referent is strongly reachable
    /// up to the call. This tier keeps the `Op::Call` node in the graph (it is
    /// impure, so nothing deletes it, and it stays the memory barrier it always
    /// was), with the referent as its input: liveness is computed from the
    /// GRAPH, so the referent's register or home stays allocated and stays in
    /// every safepoint map up to this node -- exactly the coverage the thin
    /// `jit_reachability_fence_direct` CALL bought, minus the CALL. The one map
    /// it no longer publishes is the one AT the fence, which was only owed
    /// because the CALL was a GC point.
    ///
    /// Under `--jdk-only` the same site may be bound to the compiled empty JDK
    /// body instead; that body is `{}`, so dropping the call is inlining it.
    ///
    /// `CRATONVM_JIT_IR_REACHABILITY_FENCE_KEEPALIVE=0` keeps the call. Declines
    /// (keeps the call) for a shape that is not the static `(Object)V` site and
    /// for a referent a carry is holding (a carry must be consumed by a read).
    fn try_lower_ir_reachability_fence(&mut self, id: NodeId, info_ptr: usize) -> bool {
        if info_ptr == 0
            || !cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_JIT_IR_REACHABILITY_FENCE_KEEPALIVE",
            )
        {
            return false;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if info.invoke_kind != 3
            || !crate::is_reachability_fence_site(
                info.class_name,
                info.method_name,
                info.descriptor,
            )
        {
            return false;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return false;
        };
        if node.inputs.len() != 3 || node.ty != IrType::Void || self.carry_names(node.inputs[2]) {
            return false;
        }
        // The slot every `Op::Call` takes, for layout uniformity; nothing
        // writes it (the node is void).
        let _ = self.alloc_slot(id);
        if crate::x64::dbg_jitc_enabled() {
            eprintln!("[cratonvm-jitc] ir-reachability-fence keep-alive n{id} (no code)");
        }
        true
    }

    /// ARRAYLIST_ACCESS in the optimizing tier (round 9 wave 9, irl9): the
    /// inline `ArrayList.get(int)` / `size()` fast path as a guarded PREFIX of
    /// an `Op::Call`'s ordinary lowering. The twin of
    /// `x64/op_invoke.rs::try_emit_arraylist_access_prefix`, which only the
    /// single-pass tier ran: a `[c2]` body's `List.get` stayed a MIC/native
    /// dispatch (`AlProbe list` on w8b: ~1.8 s per 400k x 16 calls from the C2
    /// body, 30 ms from the C1 body that has the prefix).
    ///
    /// Page: `perf-collection-natives-cost-a-generic-native-dispatch-per-call`
    /// (`NOTES-w8-arraylist8.md` cross-lane request 2).
    ///
    /// # Contract with the `Op::Call` arm
    ///
    /// Called first in the arm, before the safepoint map and before a byte of
    /// the call is emitted. Every decline edge lands on the byte after the
    /// prefix, i.e. on the UNCHANGED call lowering (MIC/PIC, direct call or
    /// dispatch), which then runs the registered native exactly as before. The
    /// hit edge writes the node's result exactly as the call route's final
    /// `store_rax` would at run time (home word, plus the resident register
    /// when the value has one) and jumps to [`Self::call_prefix_join`], which
    /// `lower_data_node_tracked` patches to the end of the node's lowering.
    /// Compile-time state is left as the call route leaves it, and that is
    /// sound for the hit path: it writes only RAX, RCX, RDX, R10, R11 (this
    /// lowerer's per-opcode scratch, never an allocated value's register), the
    /// result's home and its own register -- a strict subset of what the call
    /// route's run-time effect is -- and it makes no call, so there is no
    /// collection, no frame-record republish and no shadow reload owed.
    ///
    /// # What the fast path answers
    ///
    /// Exactly the single-pass prefix's answers (see its doc for the sequence
    /// and for why each screen exists): an exact `java/util/ArrayList` plain
    /// object, compact or legacy (both cells present and tagged), `size >= 0`,
    /// a non-null reference-array `elementData`, for `get` an index below
    /// both `size` and the array length (unsigned, so a negative index
    /// declines), and no stale-view marker in the first spare slot. Anything
    /// else declines to the call. Never a deopt, never an exception.
    ///
    /// # Declines at compile time
    ///
    /// No layout on this compile, `CRATONVM_NO_JIT_ARRAYLIST_INTRINSICS=1`, a
    /// site `try_resolve_arraylist_intrinsic` does not name, `invokespecial`,
    /// an armed ZGC read barrier, an argument count or result type that does
    /// not match the resolved member, an operand some carry is holding, and a
    /// result that is itself carried or has its home dropped (the hit edge
    /// writes the home word; those two shapes have no home to write).
    fn try_emit_ir_arraylist_access_prefix(&mut self, id: NodeId, info_ptr: usize) {
        let Some(layout) = self.array_list_layout else {
            return;
        };
        if info_ptr == 0 || crate::arraylist_intrinsics_disabled() {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- the pointer names a live `JitInvokeInfo` owned by
        // `ir_call_infos` for the lifetime of this compile.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        let Some((entry, num_params, _ret, guard)) = crate::try_resolve_arraylist_intrinsic(
            info.class_name,
            info.method_name,
            info.descriptor,
            Some(layout),
        ) else {
            return;
        };
        // Virtual (0) and interface (2) only, as in the single-pass tier.
        if !matches!(info.invoke_kind, 0 | 2) || guard == 0 {
            return;
        }
        if crate::x64::zgc_read_barrier_blocks_inline_fields() {
            return;
        }
        let is_get = entry == crate::JitIntrinsic::ArrayListGet.as_entry();
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        if node.inputs.len() != num_params + 3 {
            return; // [ctrl, mem, receiver, params...]
        }
        let want_ty = if is_get { IrType::Ref } else { IrType::Int };
        if node.ty != want_ty {
            return;
        }
        let recv = node.inputs[2];
        let index = if is_get { Some(node.inputs[3]) } else { None };
        if self.carry_names(recv) || index.is_some_and(|i| self.carry_names(i)) {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        // The result's home, computed without allocating it: the call route
        // below allocates it after its safepoint map, which must not see this
        // node's slot as defined.
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] arraylist-intrinsic n{id} {}.{}{} guard_class_id={guard}",
                info.class_name, info.method_name, info.descriptor,
            );
        }

        let mut decline: Vec<usize> = Vec::new();
        // RCX: the epoch guard's fallback form and the index load write it.
        self.note_rcx_written();
        // A layout REPLACEMENT invalidates the baked compact offsets.
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        // RAX = receiver; null declines (the native reports the NPE).
        self.gp_load_value(RAX, recv);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // A plain object only: an array header carries its COMPONENT's id.
                                                 // TEST BYTE [RAX+KIND_TAGS], KIND_TAG_BYTE_MASK (F6 /0 ib) -- kind bits only.
        self.buf.emit(&[
            0xF6,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ]);
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // CMP DWORD [RAX+0], ArrayList -- `class_id` is the `u32` at offset 0.
        self.buf.emit(&[0x81, 0x78, 0x00]);
        self.buf.emit(&guard.to_le_bytes());
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // TEST BYTE [RAX+GC_FLAGS], COMPACT (F6 /0 ib) ; JZ legacy.
        self.buf.emit(&[
            0xF6,
            0x40,
            cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::GC_FLAG_COMPACT,
        ]);
        let legacy = self.emit_jcc_rel32(0x84);
        // COMPACT: R10D = size, RDX = elementData.
        self.emit_load_base_disp32(R10, RAX, layout.size_compact_offset, false);
        self.emit_load_base_disp32(RDX, RAX, layout.data_compact_offset, true);
        let have = self.emit_jmp_rel32();
        // LEGACY: both cells present, each carrying the tag it is read as.
        self.patch_rel32_to_here(legacy);
        // CMP DWORD [RAX+NUM_SLOTS], min_num_slots ; JB decline.
        self.buf.emit(&[0x81, 0xB8]);
        self.buf
            .emit(&(cratonvm_types::NUM_SLOTS_OFFSET as i32).to_le_bytes()); // Cast: small header constant
        self.buf.emit(&layout.min_num_slots.to_le_bytes());
        decline.push(self.emit_jcc_rel32(0x82)); // JB
                                                 // CMP DWORD [RAX+size_tag], 0 (`Value::Int`) ; JNE decline.
        self.buf.emit(&[0x81, 0xB8]);
        self.buf.emit(&layout.size_legacy_tag_offset.to_le_bytes());
        self.buf.emit(&0u32.to_le_bytes());
        decline.push(self.emit_jcc_rel32(0x85));
        // CMP DWORD [RAX+data_tag], FIELD_CELL_TAG_OBJECT ; JNE decline.
        self.buf.emit(&[0x81, 0xB8]);
        self.buf.emit(&layout.data_legacy_tag_offset.to_le_bytes());
        self.buf
            .emit(&cratonvm_types::FIELD_CELL_TAG_OBJECT.to_le_bytes());
        decline.push(self.emit_jcc_rel32(0x85));
        self.emit_load_base_disp32(R10, RAX, layout.size_legacy_offset, false);
        self.emit_load_base_disp32(RDX, RAX, layout.data_legacy_offset, true);

        self.patch_rel32_to_here(have);
        self.buf.emit(&[0x45, 0x85, 0xD2]); // TEST R10D, R10D
        decline.push(self.emit_jcc_rel32(0x88)); // JS: size >= 0
        self.buf.emit(&[0x48, 0x85, 0xD2]); // TEST RDX, RDX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ: elementData != null
        let ref_array_tags = (cratonvm_types::ObjectKind::Array as u8)
            | ((cratonvm_types::ArrayElementType::Reference as u8) << 2);
        // CMP BYTE [RDX+KIND_TAGS], Array|Reference (80 /7 ib, rm=RDX).
        self.buf.emit(&[
            0x80,
            0x7A,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            ref_array_tags,
        ]);
        decline.push(self.emit_jcc_rel32(0x85));
        // R11D = elementData.length (zero-extends into R11).
        self.emit_load_base_disp32(
            R11,
            RDX,
            cratonvm_types::ARRAY_LENGTH_OFFSET as i32, // Cast: small header constant
            false,
        );
        if let Some(idx) = index {
            self.gp_load_value(RCX, idx);
            // MOV ECX, ECX: the element load scales the FULL register.
            self.buf.emit(&[0x89, 0xC9]);
            self.buf.emit(&[0x44, 0x39, 0xD1]); // CMP ECX, R10D (index vs size)
            decline.push(self.emit_jcc_rel32(0x83)); // JAE
            self.buf.emit(&[0x44, 0x39, 0xD9]); // CMP ECX, R11D (index vs length)
            decline.push(self.emit_jcc_rel32(0x83)); // JAE
        }
        // `view_source_in`: with spare capacity, a non-null LAST slot names a
        // source map this list is a stale view of; the native resyncs it.
        self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D (size vs length)
        let no_marker = self.emit_jcc_rel32(0x83); // JAE: no spare capacity
                                                   // CMP QWORD [RDX + R11*8 + (DATA - 8)], 0 -- REX.W|REX.X, 83 /7 ib,
                                                   // ModRM mod=01 rm=SIB, SIB scale 8 index=R11 base=RDX.
        self.buf.emit(&[
            0x4A,
            0x83,
            0x7C,
            0xDA,
            (cratonvm_types::ARRAY_DATA_OFFSET - cratonvm_types::REF_ELEMENT_SIZE) as u8, // Cast: x86-64 disp8
            0x00,
        ]);
        decline.push(self.emit_jcc_rel32(0x85));
        self.patch_rel32_to_here(no_marker);
        if is_get {
            // MOV RAX, [RDX + RCX*8 + ARRAY_DATA_OFFSET]
            self.buf.emit(&[
                0x48,
                0x8B,
                0x44,
                0xCA,
                cratonvm_types::ARRAY_DATA_OFFSET as u8, // Cast: x86-64 disp8
            ]);
        } else {
            self.buf.emit(&[0x49, 0x63, 0xC2]); // MOVSXD RAX, R10D
        }
        // The call route's `store_rax(slot)` at run time, with no carry and a
        // home that is not dropped (both refused above): the resident
        // register when the value has one and definitions publish, then the
        // home word. No compile-time state is touched -- the call route's
        // own store sets it, and it describes the join for both paths.
        //
        // Round 11 (irlower): whenever the value HAS a register, not only when
        // definitions publish. With `CRATONVM_JIT_IR_PUBLISH_AT_DEF=0` the call
        // route's register is written by the generic publish at the end of
        // `lower_data_node` -- which this hit path jumps PAST (the join is
        // patched after the whole arm) -- while the compile-time state says the
        // register is live on both paths. Writing it here is what makes that
        // true on this one.
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio20 wave 1, lane L3 (NIO19-5, was NIO17-1 / BUF18-1): may the
    /// `Op::Call` described by `info` take [`Self::try_emit_ir_getclass_prefix`]?
    /// The compile-time half of its screens, shared with
    /// [`Self::call_site_may_take_inline_prefix`] so the dead-home planner and
    /// the emitter cannot disagree about which sites have a prefix.
    fn getclass_prefix_admits(&self, info: &JitInvokeInfo) -> bool {
        info.invoke_kind == 0
            && crate::is_object_get_class_site(info.method_name, info.descriptor)
            // JIT r20 (lane qMisc, correctness): not a site that resolves to a
            // class's own private / static `getClass()`.
            && !self
                .graph
                .getclass_prefix_refused_infos
                .contains(&(info as *const JitInvokeInfo as usize))
            && self.direct_helpers.getclass_mirror_words != 0
            && crate::getclass_inline_enabled()
    }

    /// `Object.getClass()` in the optimizing tier as two loads (nio20 wave 1,
    /// lane L3, NIO19-5): the receiver's class id from its header, then that
    /// class's word in the VM's compiled-`getClass()` table
    /// (`DirectHelperTable::getclass_mirror_words`; the VM crate's
    /// `ClassRealm::getclass_mirror_words` documents who writes it and why a
    /// non-zero word always equals `class_mirrors[class_id]`). HotSpot's
    /// `getClass` is the same two loads (klass from the header, mirror from
    /// the klass).
    ///
    /// A guarded PREFIX of the call's unchanged lowering, with the contract of
    /// [`Self::try_emit_ir_arraylist_access_prefix`]: scratch RAX and R10
    /// only; the hit edge writes the result home (and register) and jumps to
    /// [`Self::call_prefix_join`]; every decline edge lands on the call, which
    /// is `jit_object_get_class_direct` (or the MIC route to the native) and
    /// answers exactly what it answered before:
    ///
    /// * a null receiver -- the call raises the JEP 358 receiver NPE;
    /// * a non-plain object -- an array's header carries its COMPONENT's id
    ///   (since nio21 wave 1 L5 a one-dimensional PRIMITIVE array is answered
    ///   from the table's primitive-array band, keyed by its tag byte,
    ///   [`getclass_prim_array_lookup_bytes`], and since nio21 wave 2 L5 a
    ///   REFERENCE array from the reference-array band keyed by that component
    ///   id, [`getclass_array_arm_bytes`]; an unpublished word still declines);
    /// * a class id past the table, or a class with no published word (no
    ///   mirror yet, a display verdict not yet memoised as the stamp, or a
    ///   class the native remaps -- those are never published).
    ///
    /// ```text
    ///   MOV  RAX, recv ; TEST RAX,RAX ; JZ call
    ///   TEST BYTE [RAX+KIND_TAGS], KIND_TAG_BYTE_MASK ; JNZ call
    ///   MOV  EAX, [RAX]                    ; class id, zero-extended
    ///   MOV  R10, imm64 table
    ///   CMP  RAX, [R10] ; JAE call         ; word 0 = capacity
    ///   MOV  RAX, [R10 + RAX*8 + 8] ; TEST RAX,RAX ; JZ call
    ///   <store RAX to the result home> ; JMP join
    /// ```
    ///
    /// Declines at compile time under `CRATONVM_JIT_GETCLASS_INLINE=0`, with
    /// no table on this compile (a door that did not publish one, a non-x86-64
    /// VM), under an armed ZGC read barrier (the gate every inline reference
    /// load shares; the words are rewritten only while mutators are parked,
    /// never colored), and for the carry / dropped-home shapes the other
    /// prefixes refuse.
    fn try_emit_ir_getclass_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if !self.getclass_prefix_admits(info) {
            return;
        }
        // nio20 w3 L3 (W2L2-4): this tier's half of the prefix only.
        if crate::x64::zgc_read_barrier_blocks_inline_fields() || !crate::ir_thin_prefix_enabled() {
            return;
        }
        let table = self.direct_helpers.getclass_mirror_words;
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver], a reference result.
        if node.inputs.len() != 3 || node.ty != IrType::Ref {
            return;
        }
        let recv = node.inputs[2];
        if self.carry_names(recv) {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        // The result's home, computed without allocating it (see the
        // ArrayList prefix).
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] getclass-prefix n{id} {}.{}{} table={table:#x}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
        // nio20 wave 4, lane L2: the optimizing tier's twin of the single-pass
        // `object-getclass-inline (sp)` line, so one `CRATONVM_DBG_JITC` run
        // shows which tier's body carries the prefix; the VM's
        // `getclass-helper served=.. declined=..` lines count the misses.
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] object-getclass-inline (ir) n{id} pc={:?} table={table:#x}",
                node.bytecode_pc,
            );
        }
        // nio21 wave 1 L5: a one-dimensional primitive array is answered from
        // the table's primitive-array band instead of declining; nio21 wave 2
        // L5: a reference array from the reference-array band.
        let prim_arrays = getclass_prim_array_words_enabled();
        let ref_arrays = getclass_ref_array_words_enabled();
        let mut decline: Vec<usize> = Vec::new();
        // RAX = receiver; null declines (the call raises the NPE at this bci).
        self.gp_load_value(RAX, recv);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // R10 = the table (loaded before the kind test: both arms read it).
        self.emit_mov_reg_imm64(R10, table as u64); // Cast: the table's address
                                                    // A plain object takes the class-id lookup: an array header carries
                                                    // its COMPONENT's id. TEST BYTE [RAX+KIND_TAGS], KIND_TAG_BYTE_MASK
                                                    // (F6 /0 ib) ; JNE array arm (or decline).
        self.buf.emit(&[
            0xF6,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ]);
        let not_plain = self.emit_jcc_rel32(0x85); // JNE
                                                   // MOV EAX, dword [RAX] -- `class_id`, the `u32` at offset 0; the
                                                   // 32-bit load zero-extends into RAX, so the index below is unsigned.
        self.buf.emit(&[0x8B, 0x00]);
        // The class's word (or, nio20 wave 5 L2, a lambda proxy's word in the
        // table's second band); an id with no word or an unpublished word
        // declines (`getclass_table_lookup_bytes`).
        let (lookup, edges) = getclass_table_lookup_bytes();
        let at = self.buf.pos();
        self.buf.emit(&lookup);
        decline.extend(edges.into_iter().map(|e| at + e));
        if prim_arrays || ref_arrays {
            // JMP loaded ; array: <the array arm> ; loaded:
            let to_loaded = self.emit_jmp_rel32();
            self.patch_rel32_to_here(not_plain);
            let (arm, edges) = getclass_array_arm_bytes(ref_arrays, prim_arrays);
            let at = self.buf.pos();
            self.buf.emit(&arm);
            decline.extend(edges.into_iter().map(|e| at + e));
            self.patch_rel32_to_here(to_loaded);
        } else {
            decline.push(not_plain);
        }
        // The call route's `store_rax(slot)` at run time, written as the
        // ArrayList prefix writes it: the resident register when the value
        // has one, then the home word.
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT round 20 wave 17, lane pAtom2: may the `Op::Call` described by
    /// `info` take [`Self::try_emit_ir_class_is_instance_prefix`]? The
    /// compile-time half of its screens, shared with
    /// [`Self::call_site_may_take_inline_prefix`]. `Class` is final, so the
    /// site is virtual (0) or the devirtualised special (1); the receiver is
    /// input 2 either way.
    fn class_is_instance_prefix_admits(&self, info: &JitInvokeInfo) -> bool {
        matches!(info.invoke_kind, 0 | 1)
            && info.class_name == "java/lang/Class"
            && info.method_name == "isInstance"
            && info.descriptor == "(Ljava/lang/Object;)Z"
            && self.direct_helpers.getclass_mirror_words != 0
            && crate::getclass_inline_enabled()
            && crate::class_is_instance_inline_enabled()
    }

    /// `Class.isInstance(obj)` for an `obj` of EXACTLY the receiver's class, in
    /// the optimizing tier (JIT round 20 wave 17, lane pAtom2; the field
    /// updaters' `accessCheck` is `cclass.isInstance(obj)` on every access,
    /// `R20PAtomVolatileField` / `R20PAtomRmwNoSplice`): `obj`'s class id from
    /// its header, then that class's word in the compiled-`getClass()` table
    /// (exactly [`Self::try_emit_ir_getclass_prefix`]'s lookup); a word equal to
    /// the receiver mirror answers `true`. HotSpot's intrinsic for a constant
    /// mirror is the same exact-klass compare first.
    ///
    /// Sound because a non-zero word for class id `c` is `class_mirrors[c]`
    /// (`ClassRealm::getclass_mirror_words`), so the hit says `obj.getClass()`
    /// is the receiver, and `native_class_is_instance` answers `true` for that
    /// pair (its id compare). Every other shape declines to the call, which
    /// answers exactly what it answered before: a null `obj` (`false`), a null
    /// receiver (its NPE), an array (its header carries the component id), a
    /// subclass or interface instance, an id past the table, an unpublished
    /// word. The VM's site arm publishes the word on the call's first exact hit
    /// (`LeafNativeKind::ClassIsInstance`).
    ///
    /// Same contract with the `Op::Call` arm as the getClass prefix: scratch
    /// RAX and R10 only; no call, no GC point; the hit edge writes `1` home
    /// (and to the register) and jumps to [`Self::call_prefix_join`]. Declines
    /// at compile time under `CRATONVM_JIT_CLASS_IS_INSTANCE_INLINE=0`, without
    /// a table, under an armed ZGC read barrier, and for the carry /
    /// dropped-home shapes the other prefixes refuse.
    fn try_emit_ir_class_is_instance_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if !self.class_is_instance_prefix_admits(info) {
            return;
        }
        if crate::x64::zgc_read_barrier_blocks_inline_fields() || !crate::ir_thin_prefix_enabled() {
            return;
        }
        let table = self.direct_helpers.getclass_mirror_words;
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, mirror, obj], an int result.
        if node.inputs.len() != 4 || node.ty != IrType::Int {
            return;
        }
        let mirror = node.inputs[2];
        let obj = node.inputs[3];
        if self.carry_names(mirror) || self.carry_names(obj) {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        // The result's home, computed without allocating it (see the
        // ArrayList prefix).
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() || crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] class-is-instance-inline (ir) n{id} pc={:?} table={table:#x}",
                node.bytecode_pc,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        // RAX = obj; null declines (the call answers `false`, or raises the
        // receiver's NPE).
        self.gp_load_value(RAX, obj);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // A plain object only: an array header carries its COMPONENT's id.
                                                 // TEST BYTE [RAX+KIND_TAGS], KIND_TAG_BYTE_MASK (F6 /0 ib) ; JNE.
        self.buf.emit(&[
            0xF6,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ]);
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // MOV EAX, dword [RAX] -- the class id, zero-extended.
        self.buf.emit(&[0x8B, 0x00]);
        // JIT round 20 wave 19, lane zAssign: the subtype arm's display cell
        // (`CRATONVM_JIT_CLASS_IS_INSTANCE_SUBTYPE_INLINE`, which reads the
        // hints `CRATONVM_JIT_CLASS_IS_ASSIGNABLE_INLINE` fills), and the
        // class id kept in RCX across the lookup (which writes RAX only).
        let subtype = if crate::class_is_instance_subtype_inline_enabled()
            && crate::class_is_assignable_inline_enabled()
        {
            self.class_assignable_display_cell()
        } else {
            None
        };
        if subtype.is_some() {
            self.note_rcx_written();
            self.buf.emit(&[0x89, 0xC1]); // MOV ECX, EAX
        }
        // R10 = the table; RAX = obj's class word (an id with no word or an
        // unpublished word declines).
        self.emit_mov_reg_imm64(R10, table as u64); // Cast: the table's address
        let (lookup, edges) = getclass_table_lookup_bytes();
        let at = self.buf.pos();
        self.buf.emit(&lookup);
        decline.extend(edges.into_iter().map(|e| at + e));
        // R10 = the receiver mirror (resident registers are callee-saved, never
        // RAX / R10); CMP RAX, R10 (REX.W+R 39 /r) ; JNE decline.
        self.gp_load_value(R10, mirror);
        self.buf.emit(&[0x4C, 0x39, 0xD0]);
        // JIT round 20 wave 19, lane zAssign: with the subtype arm, a word
        // that is not the receiver goes to that arm instead of the call.
        let other = self.emit_jcc_rel32(0x85); // JNE
        if subtype.is_none() {
            decline.push(other);
        }
        // MOV EAX, 1 -- `true`, zero-extended as the call route's int result.
        let one_at = self.buf.pos();
        self.buf.emit(&[0xB8, 0x01, 0x00, 0x00, 0x00]);
        let store_at = self.buf.pos();
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        // JIT round 20 wave 19, lane zAssign
        // (`CRATONVM_JIT_CLASS_IS_INSTANCE_SUBTYPE_INLINE`): RCX = obj's class
        // id `s` (saved before the lookup), whose compiled-`getClass()` word
        // is published -- so `obj.getClass()` reports `s` and the native's
        // display-class disjunct is the hierarchy -- but is not the receiver.
        // The receiver's class from its mirror hint, then `s`'s display
        // ([`class_instance_subtype_answer_bytes`]): a hit is the `1` above,
        // a hierarchy-only miss `0`, every other outcome the call.
        if let Some(cell) = subtype {
            self.patch_rel32_to_here(other);
            self.buf.emit(&[0x4C, 0x89, 0xD2]); // MOV RDX, R10 (the receiver)
            let latch = cratonvm_types::duplicate_class_name_seen_addr();
            let (arm, edges, hits, miss) = class_instance_subtype_answer_bytes(table, cell, latch);
            let at = self.buf.pos();
            self.buf.emit(&arm);
            decline.extend(edges.into_iter().map(|e| at + e));
            for h in hits {
                let field = at + h;
                // Cast: offsets inside one compiled method.
                let rel = one_at as i32 - (field as i32 + 4);
                let _ = self.buf.try_patch_i32(field, rel);
            }
            self.patch_rel32_to_here(at + miss);
            self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX -- `false`
            self.emit_jmp_back_to(store_at);
        }
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r21 wave 1 (lane typecheck): the supers-display cell the IR
    /// `aastore` store-check arm reads ([`aastore_display_arm_bytes`]), or
    /// `None` under `CRATONVM_JIT_IR_AASTORE_DISPLAY_ARM` off (the default) or
    /// without displays. `CRATONVM_DBG_JITC` names each site.
    fn aastore_display_cell(&self) -> Option<usize> {
        if !ir_aastore_display_arm_enabled() {
            return None;
        }
        let cell = self.class_assignable_display_cell();
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir aastore display arm: {}",
                if cell.is_some() { "emitted" } else { "DECLINED (no display cell)" }
            );
        }
        cell
    }

    /// JIT round 20 wave 19, lane zAssign: the supers-display cell the
    /// `Class.isAssignableFrom` / `Class.isInstance` subtype arms read
    /// ([`class_assignable_core`]), or `None` when this VM keeps no displays
    /// (`CRATONVM_JIT_VH_CONST_INLINE` / `CRATONVM_JIT_VH_CONST_SUBTYPE` off)
    /// or has not published the cell.
    fn class_assignable_display_cell(&self) -> Option<usize> {
        typecheck_display_cell(&self.direct_helpers)
    }

    /// JIT round 20 wave 19, lane zAssign: may the `Op::Call` described by
    /// `info` take [`Self::try_emit_ir_class_is_assignable_prefix`]? The
    /// compile-time half of its screens, shared with
    /// [`Self::call_site_may_take_inline_prefix`]. `Class` is final: a virtual
    /// (0) or devirtualised special (1) site, the receiver at input 2.
    fn class_is_assignable_prefix_admits(&self, info: &JitInvokeInfo) -> bool {
        matches!(info.invoke_kind, 0 | 1)
            && info.class_name == "java/lang/Class"
            && info.method_name == "isAssignableFrom"
            && info.descriptor == "(Ljava/lang/Class;)Z"
            && self.direct_helpers.getclass_mirror_words != 0
            && crate::getclass_inline_enabled()
            && crate::class_is_assignable_inline_enabled()
    }

    /// `Class.isAssignableFrom(Class)` in the optimizing tier with no call
    /// (JIT round 20 wave 19, lane zAssign; page
    /// `jr20-class-is-assignable-from-takes-the-class-manager-lock-per-call-20261013.md`,
    /// `R20PNatAssignable` 93-215 ns against HotSpot's 2-16, the leaf-native
    /// call itself): both mirrors' class ids from the compiled-`getClass()`
    /// table's mirror-hint band, each proven by its class word
    /// ([`class_mirror_hint_resolve`]), then the source's supers display
    /// ([`class_assignable_core`]) -- HotSpot's inline `Klass` subtype check.
    /// [`class_assignable_answer_bytes`] states why a hit is the native's
    /// `true` and a screened miss its `false`; every other shape (a null
    /// argument: the NPE; an array or primitive mirror, which never gets a
    /// hint; an unfilled hint; an interface or lambda-proxy source; a
    /// verdict-0 source; a synthetic target; a raised duplicate-name latch)
    /// is the unchanged call. The VM's native fills the hints
    /// (`NativeClassAccess::note_class_mirror_id`), so the first calls of a
    /// pair take the call.
    ///
    /// The `Op::Call` prefix contract: no call, no GC point; scratch RAX, RCX,
    /// RDX, R10, R11 (as the constant-`VarHandle` prefix); the answer goes home
    /// (and to the register) and jumps to [`Self::call_prefix_join`]. Declines
    /// at compile time under `CRATONVM_JIT_CLASS_IS_ASSIGNABLE_INLINE=0`,
    /// without a table or display cell, under an armed ZGC read barrier, and
    /// for the carry / dropped-home shapes the other prefixes refuse.
    fn try_emit_ir_class_is_assignable_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if !self.class_is_assignable_prefix_admits(info) {
            return;
        }
        if crate::x64::zgc_read_barrier_blocks_inline_fields() || !crate::ir_thin_prefix_enabled() {
            return;
        }
        let Some(cell) = self.class_assignable_display_cell() else {
            return;
        };
        let table = self.direct_helpers.getclass_mirror_words;
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, target mirror (the receiver), source mirror], an int.
        if node.inputs.len() != 4 || node.ty != IrType::Int {
            return;
        }
        let target = node.inputs[2];
        let source = node.inputs[3];
        if self.carry_names(target) || self.carry_names(source) {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() || crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] class-is-assignable-inline (ir) n{id} pc={:?} table={table:#x} \
                 cell={cell:#x}",
                node.bytecode_pc,
            );
        }
        let latch = cratonvm_types::duplicate_class_name_seen_addr();
        let (bytes, edges, hits, miss) = class_assignable_answer_bytes(table, cell, latch);
        self.note_rcx_written();
        self.gp_load_value(RAX, target);
        self.gp_load_value(RDX, source);
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        let decline: Vec<usize> = edges.into_iter().map(|e| at + e).collect();
        // miss: XOR EAX, EAX ; JMP store.
        self.patch_rel32_to_here(at + miss);
        self.buf.emit(&[0x31, 0xC0]);
        let to_store = self.emit_jmp_rel32();
        // hit: MOV EAX, 1.
        for h in hits {
            self.patch_rel32_to_here(at + h);
        }
        self.buf.emit(&[0xB8, 0x01, 0x00, 0x00, 0x00]);
        self.patch_rel32_to_here(to_store);
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut frame = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut frame);
        self.buf.emit(frame.as_slice());
        let join = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(join);
    }

    /// nio20 wave 5, lane L2: the compile-time half of
    /// [`Self::try_emit_ir_identity_hash_prefix`]'s screens, shared with
    /// [`Self::call_site_may_take_inline_prefix`]. `Some(true)` for
    /// `System.identityHashCode`, `Some(false)` for a `Class.hashCode()` site
    /// (see [`ir_identity_hash_site`]).
    fn identity_hash_prefix_admits(&self, info: &JitInvokeInfo) -> Option<bool> {
        if !ir_identity_hash_inline_enabled() {
            return None;
        }
        ir_identity_hash_site(
            info.class_name,
            info.method_name,
            info.descriptor,
            info.invoke_kind,
        )
    }

    /// Emit [`identity_hash_read_bytes`] with RAX = a non-null object: on the
    /// fall-through RAX is the installed identity hash; every decline edge is
    /// pushed onto `decline`. Writes RCX and RDX.
    fn emit_ir_identity_hash_read(&mut self, decline: &mut Vec<usize>) {
        self.note_rcx_written();
        let (bytes, edges) = identity_hash_read_bytes();
        let at = self.buf.pos();
        self.buf.emit(&bytes);
        decline.extend(edges.into_iter().map(|e| at + e));
    }

    /// The identity hash in the optimizing tier (nio20 wave 5, lane L2; page
    /// `r20-identity-hash-is-a-native-call-in-compiled-code-FIXED-20261012.md`):
    /// `System.identityHashCode(o)` and `Class.hashCode()` answered from the
    /// object's header when a hash is already installed there, as a guarded
    /// PREFIX of the call's unchanged lowering. HotSpot reads the mark word the
    /// same way (its `hashCode` intrinsic, with the slow path for an unhashed or
    /// locked object).
    ///
    /// Same contract with the `Op::Call` arm as
    /// [`Self::try_emit_ir_getclass_prefix`]: scratch RAX, RCX and RDX only; no
    /// call, no GC point and nothing that traps on the hit path; the hit edge
    /// writes the result home (and register) and jumps to
    /// [`Self::call_prefix_join`]. Every decline lands on the call, which runs
    /// the registered native exactly as before (`System.identityHashCode`'s
    /// `Bridge`, or `Object.hashCode`'s), so the prefix only ever answers what
    /// that native would have read back from the same header:
    ///
    /// * a null argument / receiver -- the call answers `0` / raises the NPE;
    /// * a `Class.hashCode()` receiver whose class id is not exactly
    ///   `java/lang/Class` (cannot happen for a verified `Class`-typed site
    ///   unless the id is unknown; `Class` is final and does not override
    ///   `hashCode`, so the exact id is the whole override test);
    /// * no hash installed yet (the call mints and installs it), a compact
    ///   instance that is thin-locked or inflated (its hash, if any, is in the
    ///   monitor), a forwarded header.
    ///
    /// The values are GC-stable (every mover copies the header verbatim) and an
    /// installed hash is never rewritten, so one racy 32-bit header load is a
    /// consistent snapshot. Nothing is baked but the decode constants and, for
    /// `Class.hashCode`, `Class`'s id.
    ///
    /// Declines at compile time under `CRATONVM_JIT_IR_IDENTITY_HASH_INLINE=0`,
    /// under an armed ZGC read barrier (as the getClass prefix), without the
    /// `Class` id for a `Class.hashCode` site, and for the carry / dropped-home
    /// shapes the other prefixes refuse.
    fn try_emit_ir_identity_hash_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        let Some(any_object) = self.identity_hash_prefix_admits(info) else {
            return;
        };
        if crate::x64::zgc_read_barrier_blocks_inline_fields() {
            return;
        }
        let class_guard = if any_object {
            None
        } else {
            match ir_class_class_id(&self.direct_helpers) {
                Some(cid) => Some(cid),
                None => return,
            }
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, object], an int result.
        if node.inputs.len() != 3 || node.ty != IrType::Int {
            return;
        }
        let obj = node.inputs[2];
        if self.carry_names(obj) {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() || crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] identity-hash-inline (ir) n{id} pc={:?} {}.{}{} class_guard={class_guard:?}",
                node.bytecode_pc, info.class_name, info.method_name, info.descriptor,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        // RAX = the object; null declines (the call answers 0 or raises).
        self.gp_load_value(RAX, obj);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        if let Some(cid) = class_guard {
            // A plain object of exactly `java/lang/Class`:
            // TEST BYTE [RAX+KIND_TAGS], KIND_TAG_BYTE_MASK ; JNE decline ;
            // CMP DWORD [RAX+0], Class ; JNE decline.
            self.buf.emit(&[
                0xF6,
                0x40,
                cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                cratonvm_types::KIND_TAG_BYTE_MASK,
            ]);
            decline.push(self.emit_jcc_rel32(0x85));
            self.buf.emit(&[0x81, 0x78, 0x00]);
            self.buf.emit(&cid.to_le_bytes());
            decline.push(self.emit_jcc_rel32(0x85));
        }
        self.emit_ir_identity_hash_read(&mut decline);
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio21 wave 1, lane L5: the compile-time half of
    /// [`Self::try_emit_ir_current_thread_prefix`]'s screens, shared with
    /// [`Self::call_site_may_take_inline_prefix`]: `Thread.currentThread()`
    /// (static), with the VM's published thread-word offset
    /// (`DirectHelperTable::thread_java_obj_offset`, non-zero only when the
    /// policy gate the thin helper asks can never refuse for this VM's life,
    /// i.e. not `--jdk-only`; see `vm/src/jit/helpers.rs`
    /// `thread_java_obj_offset_for`) and the `JIT_THREAD` TLS mirror.
    ///
    /// nio21 wave 3, lane L4: `Thread.currentCarrierThread()` too, whose
    /// registered native is `currentThread`'s (`native_thread_current_thread`)
    /// and whose thin helper's fast arm reads the same word; its own bind is
    /// behind `CRATONVM_JIT_CARRIER_THREAD_DIRECT`, asked here as well.
    fn current_thread_prefix_admits(&self, info: &JitInvokeInfo) -> bool {
        info.invoke_kind == 3
            && info.class_name == "java/lang/Thread"
            && (info.method_name == "currentThread"
                || (info.method_name == "currentCarrierThread"
                    && crate::direct_helpers::carrier_thread_direct_enabled()
                    // An unwired cell: this VM's carrier is not the thread
                    // word (JDK-driven virtual threads, `vm::jdk_continuation`).
                    && self.direct_helpers.thread_current_carrier_thread != 0))
            && info.descriptor == "()Ljava/lang/Thread;"
            && self.direct_helpers.thread_java_obj_offset != 0
            && crate::x64::jit_thread_tls_disp() != 0
            && crate::ir_thin_prefix_enabled()
            && ir_current_thread_prefix_enabled()
    }

    /// `Thread.currentThread()` in the optimizing tier (nio21 wave 1, lane L5;
    /// the twin of the single-pass `Compiler::try_emit_sp_current_thread_prefix`,
    /// page `r20-sp-thread-current-thread-prefix-needs-a-per-vm-thread-word-FIXED-20261012.md`):
    /// the `JvmThread*` from the `JIT_THREAD` TLS mirror, then its
    /// `java_thread_obj` word at the per-VM offset the VM published -- exactly
    /// what the thin helper `jit_thread_current_thread_direct` returns on its
    /// fast arm. A guarded PREFIX of the call's unchanged lowering (the
    /// getClass prefix's contract: scratch RAX only, the hit edge writes the
    /// result home and register and jumps to [`Self::call_prefix_join`]); no
    /// JIT thread context or no mirror yet (`None` = 0) declines to the call.
    ///
    /// The word is per VM (`DirectHelperTable`), never a process global, and
    /// is `0` under `--jdk-only`, so the strict mode keeps every call. Declines
    /// at compile time under `CRATONVM_JIT_IR_CURRENT_THREAD_PREFIX=0`,
    /// `CRATONVM_JIT_IR_THIN_PREFIX=0`, an armed ZGC read barrier (the gate
    /// every inline reference load shares), and the carry / dropped-home
    /// shapes the other prefixes refuse.
    fn try_emit_ir_current_thread_prefix(&mut self, id: NodeId, info_ptr: usize) {
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        if !self.current_thread_prefix_admits(info)
            || crate::x64::zgc_read_barrier_blocks_inline_fields()
        {
            return;
        }
        let Ok(off) = i32::try_from(self.direct_helpers.thread_java_obj_offset) else {
            return;
        };
        let Ok(tls) = u32::try_from(crate::x64::jit_thread_tls_disp()) else {
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem], a reference result.
        if node.inputs.len() != 2 || node.ty != IrType::Ref {
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            return;
        };
        if crate::ir_stage_reporting() || crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] current-thread-inline (ir) n{id} pc={:?} off={off}",
                node.bytecode_pc,
            );
        }
        let mut decline: Vec<usize> = Vec::with_capacity(2);
        // RAX = the `JvmThread*` (0 outside a JIT thread context).
        self.emit_mov_rax_tls_disp32(tls);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // MOV RAX, [RAX + disp32] -- `java_thread_obj` (`None` = 0).
        self.buf.emit(&[0x48, 0x8B, 0x80]);
        self.buf.emit(&off.to_le_bytes());
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio20 wave 3, lane L2 (the residual of NIO19-8, page
    /// `r20-string-pin-and-planning-gate-residual-20261007`): the five
    /// `java/lang/String` members the single-pass backend intrinsifies --
    /// `hashCode()`, `equals(Object)`, `compareTo(String)`, `indexOf(int)`,
    /// `indexOf(String)` -- answered inline as a guarded PREFIX of the
    /// `Op::Call`'s unchanged lowering, so a method containing one no longer
    /// has to stay on the single-pass backend to keep an inline body
    /// (`lib.rs::ir_string_search_prefix_handles` lifts the planning gate and
    /// the pin for exactly the sites this emits).
    ///
    /// Same contract with the `Op::Call` arm as
    /// [`Self::try_emit_ir_arraylist_access_prefix`]: scratch RAX, RCX, RDX,
    /// R10 and R11 only (R11 and ECX through the epoch guard's fallback); the
    /// hit edge writes the result home (and register) and jumps to
    /// [`Self::call_prefix_join`]; no call, no GC point and no deopt on the hit
    /// path. Every uncertain case DECLINES to the call, which runs the real
    /// `String` method and answers -- or throws -- exactly as before.
    ///
    /// # What it answers
    ///
    /// * `hashCode()` -- a NON-ZERO cached `hash` (what the JDK body returns
    ///   without reading `value`). nio20 wave 4 (L5, W3-L2-2): a zero `hash`
    ///   on a COMPACT receiver is computed inline and a non-zero result
    ///   cached ([`Self::emit_str_hash_compute`]); a zero result or a legacy
    ///   receiver declines and the call computes and caches it.
    ///
    /// nio20 wave 4 (L5, W3-L2-1): `compareTo` and both `indexOf` forms
    /// answer UTF16 operands too (see each bullet below for the coder pairs
    /// still declined); W3-L2-3: `equals` / `compareTo` compare 16 bytes and
    /// `indexOf(int)` scans 16 bytes per SSE2 step
    /// (`CRATONVM_JIT_IR_STRING_SSE2`). The `StringBuilder` members are
    /// [`Self::try_emit_ir_string_builder_prefix`].
    /// * `equals(Object)` -- `this == arg` is `true`; a null argument is
    ///   `false`; an argument that is not a plain `java/lang/String` declines
    ///   (`false` would be right -- String is final -- but this tier stays as
    ///   conservative as the single-pass body, which deopts there); otherwise
    ///   equal coders, equal `value.length` and equal bytes (8 at a time, then
    ///   a byte tail). Correct for LATIN1 and UTF16 alike: with equal coders the
    ///   strings are equal exactly when the byte arrays are. Unequal coders
    ///   DECLINE (see the arm for why not `false`).
    /// * `compareTo(String)` -- two LATIN1 strings: the unsigned difference of
    ///   the first differing bytes, else the length difference
    ///   (`StringLatin1.compareTo`); two UTF16 strings: the same over code
    ///   units (`StringUTF16.compareTo`). Mixed coders, or a null argument,
    ///   decline.
    /// * `indexOf(int)` -- a LATIN1 receiver: `-1` for any needle outside
    ///   `0..=0xFF` (`StringLatin1.canEncode`; this covers negative, invalid
    ///   and supplementary code points, which can never occur in a LATIN1
    ///   string), else the first matching byte. A UTF16 receiver: a needle
    ///   in `0..=0xFFFF` is one code unit (`StringUTF16.indexOfChar`);
    ///   a negative or supplementary needle declines (the JDK's validity gate
    ///   and surrogate-pair search stay the call's).
    /// * `indexOf(String)` -- LATIN1/LATIN1, UTF16/UTF16 and a UTF16
    ///   haystack with a LATIN1 needle: `0` for an empty needle, `-1` when
    ///   the needle is longer, else the naive first-occurrence search the
    ///   single-pass body also makes. A LATIN1 haystack with a UTF16 needle,
    ///   or a null argument, declines.
    /// * `CharSequence.length()` / `isEmpty()` / `charAt(int)` at an
    ///   `invokeinterface` (proposal NIO20-L3-4): behind a plain-object test
    ///   and the exact String class-id compare the IR expander has no node
    ///   for; any other receiver (`StringBuilder`, `CharBuffer`, `AsciiString`,
    ///   ...) DECLINES to the interface call -- never a deopt, so unlike the
    ///   single-pass guarded body it needs no receiver profile. `charAt`
    ///   declines an index outside `[0, length)` (the call throws).
    ///
    /// The receiver is `[recv+0] == string_class_id`-checked although a
    /// `java/lang/String`-declared receiver can be nothing else: four bytes
    /// against reading a non-String's fields as `value`/`coder`. Field reads
    /// dispatch per object on `GC_FLAG_COMPACT` exactly as the single-pass
    /// `emit_load_string_value_ptr` / `emit_load_string_i32_field` do.
    ///
    /// # Declines at compile time
    ///
    /// No String layout on this compile (every door but the IR door, see
    /// [`CompileStringLayoutScope`]), no `coder`, no class id, a site
    /// `crate::ir_string_search_prefix_kind` does not name (that includes
    /// `CRATONVM_JIT_IR_STRING_SEARCH_PREFIX=0`), an invoke kind other than
    /// virtual or devirtualised special, narrow oops or an armed ZGC read
    /// barrier (`value` is a reference field; the planning gate asks the same
    /// screen), and the carry / dropped-home shapes the other prefixes refuse.
    ///
    /// # No safepoint in the loops
    ///
    /// The byte loops poll nothing, like the single-pass bodies they replace;
    /// a multi-megabyte `equals` delays a safepoint by its own length.
    fn try_emit_ir_string_search_prefix(&mut self, id: NodeId, info_ptr: usize) {
        use crate::IrStringSearchKind as K;
        if info_ptr == 0 {
            return;
        }
        // SAFETY: as every other read of an `Op::Call`'s `info_ptr` in this
        // file -- a live `JitInvokeInfo` owned by `ir_call_infos`.
        let info: &JitInvokeInfo = unsafe { &*(info_ptr as *const JitInvokeInfo) };
        let Some(kind) =
            crate::ir_string_search_prefix_kind(info.class_name, info.method_name, info.descriptor)
        else {
            return;
        };
        // nio21 wave 5 (lane L5): a `CharSequence.charAt` inside a
        // class-predicated loop DEOPTS on a miss instead of calling
        // (`ir_optimize::seq_charat_traps_on_miss`, the predicate the field
        // forward also read). Every compile-time decline below then refuses
        // the compile instead of falling back to the call, which the forward
        // has assumed away.
        let trap =
            kind == K::SeqCharAt && crate::ir_optimize::seq_charat_traps_on_miss(self.graph, id);
        let Some(layout) = self.string_layout else {
            self.note_string_prefix_declined(id, info, "no String layout in this compile");
            self.refuse_seq_charat_trap(trap, "no String layout in this compile");
            return;
        };
        // JIT r20 wave 18, lane xSb (STR20-2): `StringBuilder.toString()`
        // allocates, with its own emitter (the builder half AND the String
        // allocation plan).
        if kind == K::SbToString {
            self.try_emit_ir_sb_to_string_prefix(id, info, layout);
            return;
        }
        // nio20 wave 4, lane L5 (W3-L2-4): the `StringBuilder` members read
        // the layout's builder half, not the String one.
        if kind.is_builder() {
            self.try_emit_ir_string_builder_prefix(id, info, kind, layout);
            return;
        }
        // nio20 wave 6, lane L2: `getChars` is a void four-argument store
        // loop with its own emitter.
        if kind == K::GetChars {
            self.try_emit_ir_string_getchars_prefix(id, info, layout);
            return;
        }
        // ... and the static `StringLatin1.inflate` it ends in (no layout
        // read; asked behind the layout test above anyway, so the
        // `call_site_may_take_inline_prefix` screen, which requires a
        // layout, stays a superset).
        if kind == K::Inflate {
            self.try_emit_ir_string_inflate_prefix(id, info);
            return;
        }
        // JIT r20 wave 18, lane xUtf8 (STR20-6): the two static
        // `StringCoding` leaves, likewise with no layout read.
        if kind.is_string_coding() {
            self.try_emit_ir_string_coding_prefix(id, info, kind);
            return;
        }
        // JIT r20 wave 12, lane qStr (W6-L2-2): the three `char[]` copies
        // allocate, with their own emitter.
        if kind.is_chars_copy() {
            self.try_emit_ir_string_chars_prefix(id, info, kind, layout);
            return;
        }
        // JIT r20 wave 19, lane zCp: the static `Character.toChars(int)`
        // allocates a `char[]` through the same plan, with its own emitter.
        if kind == K::CharacterToChars {
            self.try_emit_ir_character_to_chars_prefix(id, info, layout);
            return;
        }
        // JIT r21 wave 1/3, lane strings: the Latin-1 case kinds (the two
        // `toLowerCase` user sites, which may allocate, and the two
        // `StringLatin1` workers, static sites with no String receiver).
        if kind.is_latin1_case() {
            self.try_emit_ir_string_latin1_case_prefix(id, info, kind, layout);
            return;
        }
        if !kind.admits_invoke_kind(info.invoke_kind)
            || !layout.has_coder
            || layout.string_class_id == 0
        {
            self.refuse_seq_charat_trap(trap, "the String layout has no coder or class id");
            return;
        }
        if crate::x64::narrow_oops_block_inline_fields() {
            self.refuse_seq_charat_trap(trap, "narrow oops");
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            self.refuse_seq_charat_trap(trap, "no node");
            return;
        };
        // [ctrl, mem, receiver] or [ctrl, mem, receiver, argument]; `int`,
        // `byte` and `boolean` results are all `IrType::Int` here. JIT r21
        // (lane strings): the two `toLowerCase` kinds answer the receiver.
        let want_ty = if matches!(kind, K::LowerLocaleUnchanged | K::LowerUnchanged) {
            IrType::Ref
        } else {
            IrType::Int
        };
        if node.inputs.len() != 3 + kind.num_params() || node.ty != want_ty {
            self.refuse_seq_charat_trap(trap, "call shape");
            return;
        }
        // JIT r21 wave 1, lane strings (STRINGS21-1): `coder()` /
        // `isLatin1()` read this VM's `COMPACT_STRINGS` flag byte; without its
        // address the site stays the plain call (decided before any byte).
        let compact_flag_addr = if matches!(kind, K::StrCoder | K::StrIsLatin1) {
            match self.direct_helpers.compact_strings_flag_addr() {
                Some(a) => a,
                None => {
                    self.note_string_prefix_declined(id, info, "no compact-strings flag address");
                    return;
                }
            }
        } else {
            0
        };
        let recv = node.inputs[2];
        let arg = if kind.num_params() == 1 {
            Some(node.inputs[3])
        } else {
            None
        };
        if self.carry_names(recv) || arg.is_some_and(|a| self.carry_names(a)) {
            self.refuse_seq_charat_trap(trap, "a carried operand");
            return;
        }
        // The argument of the one-parameter kinds (the input-count screen
        // above guarantees it exists for them); never read for `hashCode`.
        let arg_id: NodeId = arg.unwrap_or(recv);
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            self.refuse_seq_charat_trap(trap, "a carried or dropped result home");
            return;
        }
        // The result's home, computed without allocating it (see the
        // ArrayList prefix).
        let Ok(slot) = self.planned_slot_off(id) else {
            self.refuse_seq_charat_trap(trap, "no result home");
            return;
        };
        // nio21 wave 5 (lane L5): the trap resumes AT the invoke, so it needs
        // the frame recorded at the top of the call's pc -- the callee chain
        // inside a splice (the flat frame of the outermost invoke would re-run
        // the spliced body's committed stores), the method's own snapshot
        // otherwise. Checked before a byte is emitted.
        let trap_pc = if trap {
            match node.bytecode_pc {
                Some(pc) if self.seq_charat_trap_frame_ok(pc) => Some(pc),
                _ => {
                    self.refuse_seq_charat_trap(trap, "no frame at the call's pc");
                    return;
                }
            }
        } else {
            None
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-search-prefix n{id} {}.{}{} kind={kind:?} string_class_id={}{}",
                info.class_name,
                info.method_name,
                info.descriptor,
                layout.string_class_id,
                if trap_pc.is_some() { " miss=deopt" } else { "" },
            );
        }
        // `[value + 8]` is the array length and `[value + 16 + i]` byte `i`,
        // the two displacements the encodings below bake as disp8.
        const _: () = assert!(
            cratonvm_types::ARRAY_LENGTH_OFFSET == 8 && cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the String search prefix bakes ARRAY_LENGTH_OFFSET 8 / ARRAY_DATA_OFFSET 16"
        );
        let sid = layout.string_class_id;
        let mut decline: Vec<usize> = Vec::new();
        let mut to_store: Vec<usize> = Vec::new();
        // RCX: the epoch guard's fallback form and the field loads write it.
        self.note_rcx_written();
        // A layout REPLACEMENT invalidates the baked compact offsets.
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        // RAX = receiver; null declines (the call raises the NPE at this bci).
        self.gp_load_value(RAX, recv);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                 // A `CharSequence` receiver may be anything: a plain object only (an
                                                 // array header carries its COMPONENT's class id), then the exact
                                                 // String class id -- the guard the IR expander has no node for.
        if matches!(kind, K::SeqLength | K::SeqIsEmpty | K::SeqCharAt) {
            self.emit_str_test_mem8(
                RAX,
                cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                cratonvm_types::KIND_TAG_BYTE_MASK,
            );
            decline.push(self.emit_jcc_rel32(0x85)); // JNE
        }
        self.emit_str_cmp_class_id(RAX, sid);
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
        match kind {
            K::SeqLength | K::SeqIsEmpty => {
                // RCX = value, EDX = coder.
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                if kind == K::SeqLength {
                    // length() == value.length >> coder.
                    self.emit_load_base_disp32(RAX, RCX, 8, false);
                    self.buf.emit(&[0x89, 0xD1]); // MOV ECX, EDX
                    self.buf.emit(&[0xD3, 0xE8]); // SHR EAX, CL
                } else {
                    // isEmpty() == (value.length == 0).
                    self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX
                    self.buf.emit(&[0x83, 0x79, 0x08, 0x00]); // CMP DWORD [RCX+8], 0
                    self.buf.emit(&[0x0F, 0x94, 0xC0]); // SETE AL
                }
            }
            K::SeqCharAt => {
                let index = arg_id;
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                         // R10 = index, zero-extended: the element load scales the
                                                         // FULL register, and the unsigned compares below decline a
                                                         // negative index (the call raises the exception).
                self.gp_load_value(R10, index);
                self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
                self.emit_load_base_disp32(RAX, RCX, 8, false); // EAX = value.length
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let utf16 = self.emit_jcc_rel32(0x85); // JNZ
                                                       // LATIN1: one byte per char.
                self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
                decline.push(self.emit_jcc_rel32(0x83)); // JAE
                self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x11, 0x10]); // MOVZX EAX, BYTE [RCX+R10+16]
                let done = self.emit_jmp_rel32();
                // UTF16: two little-endian bytes per char (the single-pass
                // decode's order).
                self.patch_rel32_to_here(utf16);
                self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1
                self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
                decline.push(self.emit_jcc_rel32(0x83)); // JAE
                self.buf.emit(&[0x42, 0x0F, 0xB7, 0x44, 0x51, 0x10]); // MOVZX EAX, WORD [RCX+R10*2+16]
                self.patch_rel32_to_here(done);
            }
            K::HashCode => {
                // ECX = hash (4-byte payload in both layouts).
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                self.emit_load_base_disp32(RCX, RAX, layout.hash_compact_offset, false);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RCX, RAX, layout.hash_legacy_offset, false);
                self.patch_rel32_to_here(have);
                self.buf.emit(&[0x85, 0xC9]); // TEST ECX, ECX
                if crate::ir_string_hash_compute_enabled() {
                    // nio20 wave 4, lane L5 (W3-L2-2): not cached yet -- compute
                    // it here and cache a non-zero result, as `String.hashCode`
                    // does, for a COMPACT receiver.
                    let cached = self.emit_jcc_rel32(0x85); // JNZ: cached
                                                            // JIT round 19 proposal wave 6, lane str6 (STRGAP19-6,
                                                            // `CRATONVM_JIT_STRING_HASH_IS_ZERO`, opt-in): the JDK
                                                            // body's `!hashIsZero` test. A COMPACT receiver (RAX)
                                                            // whose `hashIsZero` is set answers 0 -- ECX already holds
                                                            // the zero `hash` the `cached` arm sign-extends.
                    let hash_is_zero = layout
                        .hash_is_zero_compact_offset
                        .filter(|_| crate::string_hash_is_zero_enabled());
                    let mut hash_is_zero_hit: Option<usize> = None;
                    if let Some(off) = hash_is_zero {
                        self.emit_str_test_mem8(
                            RAX,
                            cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                            cratonvm_types::GC_FLAG_COMPACT,
                        );
                        let legacy = self.emit_jcc_rel32(0x84); // JZ: the compute declines it
                                                                // CMP BYTE [RAX + disp32], 0 (80 /7 ib, ModRM 0xB8)
                        self.buf.emit(&[0x80, 0xB8]);
                        self.buf.emit(&off.to_le_bytes());
                        self.buf.emit(&[0x00]);
                        hash_is_zero_hit = Some(self.emit_jcc_rel32(0x85)); // JNE
                        self.patch_rel32_to_here(legacy);
                    }
                    self.emit_str_hash_compute(&layout, recv, &mut decline, hash_is_zero);
                    to_store.push(self.emit_jmp_rel32());
                    self.patch_rel32_to_here(cached);
                    if let Some(p) = hash_is_zero_hit {
                        self.patch_rel32_to_here(p);
                    }
                } else {
                    decline.push(self.emit_jcc_rel32(0x84)); // JZ: not cached yet
                }
                self.buf.emit(&[0x48, 0x63, 0xC1]); // MOVSXD RAX, ECX
            }
            K::Equals => {
                let mut trues: Vec<usize> = Vec::new();
                let mut falses: Vec<usize> = Vec::new();
                let arg = arg_id;
                // R10 = argument.
                self.gp_load_value(R10, arg);
                self.buf.emit(&[0x4C, 0x39, 0xD0]); // CMP RAX, R10
                trues.push(self.emit_jcc_rel32(0x84)); // JE: this == anObject
                self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                falses.push(self.emit_jcc_rel32(0x84)); // JZ: equals(null)
                                                        // A plain object of exactly `java/lang/String`, else decline.
                self.emit_str_test_mem8(
                    R10,
                    cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::KIND_TAG_BYTE_MASK,
                );
                decline.push(self.emit_jcc_rel32(0x85)); // JNE: an array
                self.emit_str_cmp_class_id(R10, sid);
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // RCX = this.value, EDX = this.coder; R11 = arg.value, EAX =
                                                         // arg.coder (the receiver is not needed past its fields).
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_value_and_coder(&layout, R10, R11, Some(RAX));
                self.emit_str_test_r64(R11);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                         // Unequal coders DECLINE rather than answer `false`. The JDK
                                                         // body answers `false` (its compact-strings invariant), but a
                                                         // registered `String.equals` native under `--compatible`
                                                         // compares decoded chars, and a VM-built String that broke the
                                                         // invariant would read `true` there; the call keeps whichever
                                                         // body this VM runs the judge, as the single-pass body's deopt
                                                         // does.
                self.buf.emit(&[0x39, 0xD0]); // CMP EAX, EDX (coders)
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // EAX = value.length; CMP EAX, [R11+8].
                self.emit_load_base_disp32(RAX, RCX, 8, false);
                self.buf.emit(&[0x41, 0x3B, 0x43, 0x08]);
                falses.push(self.emit_jcc_rel32(0x85)); // JNE
                let (blk_mismatch, tail_done, byte_mismatch) =
                    self.emit_str_byte_compare_loop(false);
                falses.extend(blk_mismatch);
                falses.push(byte_mismatch);
                trues.push(tail_done);
                for p in trues {
                    self.patch_rel32_to_here(p);
                }
                self.buf.emit(&[0xB8, 0x01, 0x00, 0x00, 0x00]); // MOV EAX, 1
                to_store.push(self.emit_jmp_rel32());
                for p in falses {
                    self.patch_rel32_to_here(p);
                }
                self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX
            }
            K::CompareTo => {
                let arg = arg_id;
                // R10 = argument; null declines (the call's NPE).
                self.gp_load_value(R10, arg);
                self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_cmp_class_id(R10, sid);
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // Equal coders, else decline (nio20 wave 4, L5: W3-L2-1 added
                                                         // the UTF16 pair; a mixed pair still calls).
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_value_and_coder(&layout, R10, R11, Some(RAX));
                self.emit_str_test_r64(R11);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.buf.emit(&[0x39, 0xD0]); // CMP EAX, EDX (coders)
                decline.push(self.emit_jcc_rel32(0x85)); // JNE: mixed coders
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let utf16 = self.emit_jcc_rel32(0x85); // JNZ: both UTF16
                                                       // EAX = min(len1, len2) (lengths are non-negative: unsigned).
                self.emit_load_base_disp32(RAX, RCX, 8, false);
                self.emit_load_base_disp32(RDX, R11, 8, false);
                self.buf.emit(&[0x39, 0xD0]); // CMP EAX, EDX
                self.buf.emit(&[0x0F, 0x47, 0xC2]); // CMOVA EAX, EDX
                                                    // An 8-byte block mismatch falls into the byte loop, which
                                                    // finds the first differing byte inside that block.
                let (_, tail_done, byte_mismatch) = self.emit_str_byte_compare_loop(true);
                // Equal prefix: len1 - len2.
                self.patch_rel32_to_here(tail_done);
                self.emit_load_base_disp32(RAX, RCX, 8, false);
                self.buf.emit(&[0x41, 0x2B, 0x43, 0x08]); // SUB EAX, [R11+8]
                self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
                to_store.push(self.emit_jmp_rel32());
                // First mismatch at EDX: R10D = this[k]; EAX = that[k].
                self.patch_rel32_to_here(byte_mismatch);
                self.buf.emit(&[0x41, 0x0F, 0xB6, 0x44, 0x13, 0x10]); // MOVZX EAX, BYTE [R11+RDX+16]
                self.buf.emit(&[0x41, 0x29, 0xC2]); // SUB R10D, EAX
                self.buf.emit(&[0x49, 0x63, 0xC2]); // MOVSXD RAX, R10D
                to_store.push(self.emit_jmp_rel32());
                // Both UTF16 (`StringUTF16.compareTo`): the same byte loop over
                // the even min byte count; a mismatch at byte k lies in char
                // k >> 1, every earlier char equal. An odd byte length (not a
                // String the JDK builds) declines.
                self.patch_rel32_to_here(utf16);
                self.emit_str_test_mem8(RCX, 8, 1); // TEST BYTE [RCX+8], 1
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: odd
                self.emit_str_test_mem8(R11, 8, 1); // TEST BYTE [R11+8], 1
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: odd
                self.emit_load_base_disp32(RAX, RCX, 8, false);
                self.emit_load_base_disp32(RDX, R11, 8, false);
                self.buf.emit(&[0x39, 0xD0]); // CMP EAX, EDX
                self.buf.emit(&[0x0F, 0x47, 0xC2]); // CMOVA EAX, EDX
                let (_, tail_done16, byte_mismatch16) = self.emit_str_byte_compare_loop(true);
                // Equal prefix: (len1 >> 1) - (len2 >> 1).
                self.patch_rel32_to_here(tail_done16);
                self.emit_load_base_disp32(RAX, RCX, 8, false);
                self.emit_load_base_disp32(RDX, R11, 8, false);
                self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1
                self.buf.emit(&[0xD1, 0xEA]); // SHR EDX, 1
                self.buf.emit(&[0x29, 0xD0]); // SUB EAX, EDX
                self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
                to_store.push(self.emit_jmp_rel32());
                // First differing char: the one holding byte EDX.
                self.patch_rel32_to_here(byte_mismatch16);
                self.buf.emit(&[0x83, 0xE2, 0xFE]); // AND EDX, -2
                self.buf.emit(&[0x44, 0x0F, 0xB7, 0x54, 0x11, 0x10]); // MOVZX R10D, WORD [RCX+RDX+16]
                self.buf.emit(&[0x41, 0x0F, 0xB7, 0x44, 0x13, 0x10]); // MOVZX EAX, WORD [R11+RDX+16]
                self.buf.emit(&[0x41, 0x29, 0xC2]); // SUB R10D, EAX
                self.buf.emit(&[0x49, 0x63, 0xC2]); // MOVSXD RAX, R10D
            }
            K::IndexOfChar => {
                let arg = arg_id;
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                         // R10D = ch.
                self.gp_load_value(R10, arg);
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let utf16 = self.emit_jcc_rel32(0x85); // JNZ: UTF16
                let sse = crate::ir_string_sse2_enabled();
                let mut minus_one: Vec<usize> = Vec::new();
                let mut done: Vec<usize> = Vec::new();
                // TEST R10D, 0xFFFFFF00: `ch >>> 8 != 0` cannot be in a LATIN1
                // string (`StringLatin1.canEncode`).
                self.buf.emit(&[0x41, 0xF7, 0xC2, 0x00, 0xFF, 0xFF, 0xFF]);
                minus_one.push(self.emit_jcc_rel32(0x85)); // JNZ -> -1
                self.emit_load_base_disp32(R11, RCX, 8, false); // R11D = length
                self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX
                if sse {
                    // nio20 wave 4, L5 (W3-L2-3): 16 bytes per step.
                    self.buf.emit(&[0x66, 0x41, 0x0F, 0x6E, 0xCA]); // MOVD XMM1, R10D
                    self.buf.emit(&[0x66, 0x0F, 0x60, 0xC9]); // PUNPCKLBW XMM1, XMM1
                    self.buf.emit(&[0x66, 0x0F, 0x61, 0xC9]); // PUNPCKLWD XMM1, XMM1
                    self.buf.emit(&[0x66, 0x0F, 0x70, 0xC9, 0x00]); // PSHUFD XMM1, XMM1, 0
                    done.push(self.emit_str_sse_scan_stage(false));
                }
                let top = self.buf.pos();
                self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
                minus_one.push(self.emit_jcc_rel32(0x83)); // JAE -> -1
                self.buf.emit(&[0x44, 0x38, 0x54, 0x11, 0x10]); // CMP BYTE [RCX+RDX+16], R10B
                let found = self.emit_jcc_rel32(0x84); // JE
                self.buf.emit(&[0xFF, 0xC2]); // INC EDX
                self.emit_jmp_back_to(top);
                self.patch_rel32_to_here(found);
                self.buf.emit(&[0x89, 0xD0]); // MOV EAX, EDX
                done.push(self.emit_jmp_rel32());
                // UTF16 (`StringUTF16.indexOfChar`): a needle in 0..=0xFFFF is
                // one code unit, every one of which (a lone surrogate too) the
                // JDK scans for as such; a negative or supplementary needle
                // declines (the JDK's validity gate and pair search).
                self.patch_rel32_to_here(utf16);
                self.buf.emit(&[0x41, 0x81, 0xFA, 0xFF, 0xFF, 0x00, 0x00]); // CMP R10D, 0xFFFF
                decline.push(self.emit_jcc_rel32(0x87)); // JA (unsigned: negatives too)
                self.emit_str_test_mem8(RCX, 8, 1); // TEST BYTE [RCX+8], 1
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: an odd byte length
                self.emit_load_base_disp32(R11, RCX, 8, false); // R11D = byte length
                self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX (a byte offset)
                if sse {
                    self.buf.emit(&[0x66, 0x41, 0x0F, 0x6E, 0xCA]); // MOVD XMM1, R10D
                    self.buf.emit(&[0x66, 0x0F, 0x61, 0xC9]); // PUNPCKLWD XMM1, XMM1
                    self.buf.emit(&[0x66, 0x0F, 0x70, 0xC9, 0x00]); // PSHUFD XMM1, XMM1, 0
                    done.push(self.emit_str_sse_scan_stage(true));
                }
                let top16 = self.buf.pos();
                self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
                minus_one.push(self.emit_jcc_rel32(0x83)); // JAE -> -1
                self.buf.emit(&[0x66, 0x44, 0x39, 0x54, 0x11, 0x10]); // CMP WORD [RCX+RDX+16], R10W
                let found16 = self.emit_jcc_rel32(0x84); // JE
                self.buf.emit(&[0x83, 0xC2, 0x02]); // ADD EDX, 2
                self.emit_jmp_back_to(top16);
                self.patch_rel32_to_here(found16);
                self.buf.emit(&[0x89, 0xD0]); // MOV EAX, EDX
                self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1
                done.push(self.emit_jmp_rel32());
                for p in minus_one {
                    self.patch_rel32_to_here(p);
                }
                self.buf.emit(&[0xB8, 0xFF, 0xFF, 0xFF, 0xFF]); // MOV EAX, -1
                for p in done {
                    self.patch_rel32_to_here(p);
                }
                self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
            }
            K::IndexOfStr => {
                let arg = arg_id;
                // R10 = needle; null declines (the call's NPE).
                self.gp_load_value(R10, arg);
                self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_cmp_class_id(R10, sid);
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // RCX = haystack bytes, EDX = its coder; R11 = needle bytes,
                                                         // EAX = its coder.
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_value_and_coder(&layout, R10, R11, Some(RAX));
                self.emit_str_test_r64(R11);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                         // nio20 wave 4, L5 (W3-L2-1): three of the four coder pairs.
                                                         // A LATIN1 haystack with a UTF16 needle declines (the JDK
                                                         // answers -1 by the compact-strings invariant, which a
                                                         // VM-built String need not keep; the call stays the judge).
                self.buf.emit(&[0x85, 0xC0]); // TEST EAX, EAX
                let needle_latin1 = self.emit_jcc_rel32(0x84); // JZ
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: LATIN1 hay, UTF16 needle
                self.emit_str_index_of_str_body(
                    &layout,
                    recv,
                    true,
                    true,
                    &mut decline,
                    &mut to_store,
                );
                self.patch_rel32_to_here(needle_latin1);
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let hay_utf16 = self.emit_jcc_rel32(0x85); // JNZ
                self.emit_str_index_of_str_body(
                    &layout,
                    recv,
                    false,
                    false,
                    &mut decline,
                    &mut to_store,
                );
                self.patch_rel32_to_here(hay_utf16);
                self.emit_str_index_of_str_body(
                    &layout,
                    recv,
                    true,
                    false,
                    &mut decline,
                    &mut to_store,
                );
            }
            K::CodePointAt => {
                // JIT r21 wave 1, lane strings (CP21-1): JDK 17 / 21 / 25
                // `String.codePointAt` -- LATIN1: `checkIndex(index,
                // value.length)`, `value[index] & 0xff`; UTF16: `length =
                // value.length >> 1`, `checkIndex(index, length)`,
                // `StringUTF16.codePointAt(value, index, length)` (the high
                // unit, unless it is a high surrogate whose successor inside
                // `length` is a low one: then `Character.toCodePoint`). Every
                // index outside the range declines; the call throws the SIOOBE.
                let index = arg_id;
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                                                         // R10 = index, zero-extended: a negative index is a huge
                                                         // unsigned one and declines at the compares below.
                self.gp_load_value(R10, index);
                self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
                self.emit_load_base_disp32(RAX, RCX, 8, false); // EAX = value.length
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let utf16 = self.emit_jcc_rel32(0x85); // JNZ
                                                       // LATIN1: the byte, zero-extended.
                self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
                decline.push(self.emit_jcc_rel32(0x83)); // JAE
                self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x11, 0x10]); // MOVZX EAX, BYTE [RCX+R10+16]
                to_store.push(self.emit_jmp_rel32());
                // UTF16: EAX = length in chars; EDX = c1.
                self.patch_rel32_to_here(utf16);
                self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1
                self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
                decline.push(self.emit_jcc_rel32(0x83)); // JAE
                self.buf.emit(&[0x42, 0x0F, 0xB7, 0x54, 0x51, 0x10]); // MOVZX EDX, WORD [RCX+R10*2+16]
                                                                      // `Character.isHighSurrogate(c1)`: (c1 & 0xFC00) == 0xD800.
                self.buf.emit(&[0x41, 0x89, 0xD3]); // MOV R11D, EDX
                self.buf.emit(&[0x41, 0x81, 0xE3, 0x00, 0xFC, 0x00, 0x00]); // AND R11D, 0xFC00
                self.buf.emit(&[0x41, 0x81, 0xFB, 0x00, 0xD8, 0x00, 0x00]); // CMP R11D, 0xD800
                let mut single: Vec<usize> = vec![self.emit_jcc_rel32(0x85)]; // JNE: not a high surrogate
                                                        // `++index < end` (index < length <= 2^30: no overflow).
                self.buf.emit(&[0x45, 0x8D, 0x5A, 0x01]); // LEA R11D, [R10+1]
                self.buf.emit(&[0x41, 0x39, 0xC3]); // CMP R11D, EAX
                single.push(self.emit_jcc_rel32(0x83)); // JAE: the last unit
                                                        // R11D = c2; `Character.isLowSurrogate(c2)`.
                self.buf.emit(&[0x46, 0x0F, 0xB7, 0x5C, 0x51, 0x12]); // MOVZX R11D, WORD [RCX+R10*2+18]
                self.buf.emit(&[0x44, 0x89, 0xD8]); // MOV EAX, R11D
                self.buf.emit(&[0x25, 0x00, 0xFC, 0x00, 0x00]); // AND EAX, 0xFC00
                self.buf.emit(&[0x3D, 0x00, 0xDC, 0x00, 0x00]); // CMP EAX, 0xDC00
                single.push(self.emit_jcc_rel32(0x85)); // JNE: an unpaired high surrogate
                                                        // `Character.toCodePoint(c1, c2)`:
                                                        // ((c1 << 10) + c2) + (0x10000 - (0xD800 << 10) - 0xDC00).
                self.buf.emit(&[0xC1, 0xE2, 0x0A]); // SHL EDX, 10
                self.buf.emit(&[0x44, 0x01, 0xDA]); // ADD EDX, R11D
                // `Character.MIN_SUPPLEMENTARY_CODE_POINT - (MIN_HIGH_SURROGATE
                // << 10) - MIN_LOW_SURROGATE`, as the JDK folds it.
                const PAIR_OFFSET: i32 = 0x1_0000 - (0xD800 << 10) - 0xDC00;
                self.buf.emit(&[0x81, 0xC2]); // ADD EDX, imm32
                self.buf.emit(&PAIR_OFFSET.to_le_bytes());
                for p in single {
                    self.patch_rel32_to_here(p);
                }
                // A non-negative int (<= 0x10FFFF): the 32-bit move's zero
                // extension is its sign extension.
                self.buf.emit(&[0x89, 0xD0]); // MOV EAX, EDX
            }
            K::StrCoder | K::StrIsLatin1 => {
                // JIT r21 wave 1, lane strings (STRINGS21-1): JDK 17 / 21 / 25
                // `byte coder() { return COMPACT_STRINGS ? coder : UTF16; }`
                // and `boolean isLatin1() { return COMPACT_STRINGS && coder
                // == LATIN1; }`. EDX = the `coder` field (RCX = `value`, unused).
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                // Cast: the flag byte's address as the imm64's bits.
                self.emit_mov_reg_imm64(R11, compact_flag_addr as u64);
                self.buf.emit(&[0x41, 0x80, 0x3B, 0x00]); // CMP BYTE [R11], 0
                let compact_off = self.emit_jcc_rel32(0x84); // JE: COMPACT_STRINGS false
                if kind == K::StrCoder {
                    self.buf.emit(&[0x89, 0xD0]); // MOV EAX, EDX
                } else {
                    self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX
                    self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                    self.buf.emit(&[0x0F, 0x94, 0xC0]); // SETE AL
                }
                to_store.push(self.emit_jmp_rel32());
                self.patch_rel32_to_here(compact_off);
                if kind == K::StrCoder {
                    self.buf.emit(&[0xB8, 0x01, 0x00, 0x00, 0x00]); // MOV EAX, 1 (UTF16)
                } else {
                    self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX (false)
                }
            }
            K::CompareToIgnoreCase => {
                // JIT r21 wave 1, lane strings (STRINGS21-2 / ZCP-4): JDK 17 /
                // 21 / 25 `CaseInsensitiveComparator.compare` with two LATIN1
                // operands is `StringLatin1.compareToCI(v1, v2)`: for the
                // first `k < min(len1, len2)` with `v1[k] != v2[k]`, `c =
                // (char) CharacterDataLatin1.toUpperCase(b)` then
                // `Character.toLowerCase(c)` of each; unequal folds answer
                // `fold1 - fold2`. Over Latin-1 that two-step fold is the one
                // map `emit_latin1_ci_fold` encodes, so "equal after either
                // step" is `fold1 == fold2`. Otherwise `len1 - len2`.
                let arg = arg_id;
                // R10 = the argument; null declines (the call's NPE).
                self.gp_load_value(R10, arg);
                self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_cmp_class_id(R10, sid);
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // RCX = v1, EDX = coder1; R11 = v2, EAX = coder2.
                self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_value_and_coder(&layout, R10, R11, Some(RAX));
                self.emit_str_test_r64(R11);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.buf.emit(&[0x09, 0xD0]); // OR EAX, EDX
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: not two LATIN1 operands
                self.emit_latin1_ci_loop(); // RAX = the answer
            }
            // Never reached: the `StringBuilder` kinds return through
            // `try_emit_ir_string_builder_prefix` at the top, `getChars`
            // through `try_emit_ir_string_getchars_prefix` (nio20 wave 6).
            K::SbLength
            | K::SbCharAt
            | K::SbAppendChar
            | K::SbAppendString
            | K::SbAppendInt
            | K::SbToString
            | K::GetChars
            | K::Inflate
            | K::ToCharArray
            | K::CharsValueOf
            | K::CharsInit
            | K::CountPositives
            | K::EncodeAsciiArray
            | K::SbAppendCodePoint
            | K::CharacterToChars
            // JIT r21: `try_emit_ir_string_latin1_case_prefix`.
            | K::LowerLocaleUnchanged
            | K::LowerUnchanged
            | K::Latin1CompareToCI
            | K::Latin1ToLowerCase => return,
        }
        // The call route's `store_rax(slot)` at run time, written as the
        // ArrayList prefix writes it: the resident register when the value
        // has one, then the home word.
        for p in to_store {
            self.patch_rel32_to_here(p);
        }
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        // nio21 wave 5 (lane L5): every decline edge deopts at the invoke; the
        // call lowering emitted after this is never reached.
        if let Some(pc) = trap_pc {
            self.emit_seq_charat_trap(pc);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio21 wave 5 (lane L5): a `SeqCharAt` call
    /// `ir_optimize::seq_charat_traps_on_miss` names could not take the String
    /// prefix: refuse the compile. The field forward has treated the call as a
    /// non-writer, so the plain interface call is not a fall-back.
    fn refuse_seq_charat_trap(&self, trap: bool, why: &'static str) {
        if trap {
            self.latch_bailout(Bailout::with_context(
                BailoutReason::Internal(
                    "ir_lower: a trapping CharSequence.charAt cannot take the String prefix",
                ),
                why.to_string(),
            ));
        }
    }

    /// nio21 wave 5 (lane L5): can a deopt at the call pc `pc` publish the
    /// frame recorded at the top of that pc? Inside a spliced body only a
    /// resolvable caller chain will do (and none inside a synchronized
    /// splice's window, which publishes the flat frame); outside one, the
    /// method's own snapshot at `pc`.
    fn seq_charat_trap_frame_ok(&self, pc: usize) -> bool {
        if self.pc_is_in_a_spliced_body(pc) || self.splice_state_first_by_pc.contains_key(&pc) {
            !self.sync_window_site_publishes_no_chain()
                && self
                    .splice_chain_snapshot_for_site(pc)
                    .is_some_and(|(si, _)| self.splice_chain_frame_state(si).is_ok())
        } else {
            self.safepoint_first_by_bci.contains_key(&pc)
        }
    }

    /// nio21 wave 5 (lane L5): the miss arm of a trapping `SeqCharAt` prefix:
    /// an unconditional deopt at the invoke's pc, which re-executes the
    /// interface call in the interpreter (any receiver, the JDK's own
    /// exception for an index out of range). The `emit_unconditional_deopt`
    /// shape, with the receiver-class reason so the deopt history charges it
    /// as a failed speculation.
    fn emit_seq_charat_trap(&mut self, pc: usize) {
        self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX  (ZF=1: always taken)
                                      // A guard that never passes has no passing arrival to force.
        let forced_chain_deopts = std::mem::replace(&mut self.forced_chain_deopts, false);
        self.emit_deopt_if_zero(pc, DeoptReason::ReceiverTypeChanged);
        self.forced_chain_deopts = forced_chain_deopts;
    }

    /// The shared byte-compare loop of [`Self::try_emit_ir_string_search_prefix`]'s
    /// `equals` / `compareTo` arms: RCX and R11 are the two byte arrays, EAX
    /// the count to compare; EDX is the index on every exit and R10 holds
    /// `RCX`'s byte at it on the byte mismatch. Eight bytes per step while
    /// eight remain, then one at a time.
    ///
    /// Returns `(block_mismatch, all_equal, byte_mismatch)`, the forward edges
    /// the caller routes. With `block_mismatch_to_bytes` (`compareTo`, which
    /// needs the first differing BYTE) an 8-byte mismatch falls into the byte
    /// loop, which finds it inside that block, and `block_mismatch` is empty;
    /// otherwise (`equals`) it is returned for the caller's `false`.
    ///
    /// nio20 wave 4, lane L5 (W3-L2-3, `CRATONVM_JIT_IR_STRING_SSE2`): a
    /// 16-byte SSE2 stage (`MOVDQU` x2, `PCMPEQB`, `PMOVMSKB`) runs first
    /// while 16 bytes remain, in XMM0/XMM1 (this lowerer's per-op FP scratch,
    /// dead at a call prefix). Its mismatch is a block mismatch for `equals`
    /// and, for `compareTo`, re-enters the 8-byte stage at the same index,
    /// which narrows it to the byte within at most two more steps.
    fn emit_str_byte_compare_loop(
        &mut self,
        block_mismatch_to_bytes: bool,
    ) -> (Vec<usize>, usize, usize) {
        let mut mismatches: Vec<usize> = Vec::new();
        self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX
        let mut to_blk: Vec<usize> = Vec::new();
        if crate::ir_string_sse2_enabled() {
            let v16 = self.buf.pos();
            self.buf.emit(&[0x41, 0x89, 0xC2]); // MOV R10D, EAX
            self.buf.emit(&[0x41, 0x29, 0xD2]); // SUB R10D, EDX
            self.buf.emit(&[0x41, 0x83, 0xFA, 0x10]); // CMP R10D, 16
            to_blk.push(self.emit_jcc_rel32(0x82)); // JB: fewer than 16 left
            self.buf.emit(&[0xF3, 0x0F, 0x6F, 0x44, 0x11, 0x10]); // MOVDQU XMM0, [RCX+RDX+16]
            self.buf.emit(&[0xF3, 0x41, 0x0F, 0x6F, 0x4C, 0x13, 0x10]); // MOVDQU XMM1, [R11+RDX+16]
            self.buf.emit(&[0x66, 0x0F, 0x74, 0xC1]); // PCMPEQB XMM0, XMM1
            self.buf.emit(&[0x66, 0x44, 0x0F, 0xD7, 0xD0]); // PMOVMSKB R10D, XMM0
            self.buf.emit(&[0x41, 0x81, 0xFA, 0xFF, 0xFF, 0x00, 0x00]); // CMP R10D, 0xFFFF
            let v_mismatch = self.emit_jcc_rel32(0x85); // JNE
            if block_mismatch_to_bytes {
                to_blk.push(v_mismatch);
            } else {
                mismatches.push(v_mismatch);
            }
            self.buf.emit(&[0x83, 0xC2, 0x10]); // ADD EDX, 16
            self.emit_jmp_back_to(v16);
        }
        for p in to_blk {
            self.patch_rel32_to_here(p);
        }
        let blk = self.buf.pos();
        self.buf.emit(&[0x41, 0x89, 0xC2]); // MOV R10D, EAX
        self.buf.emit(&[0x41, 0x29, 0xD2]); // SUB R10D, EDX
        self.buf.emit(&[0x41, 0x83, 0xFA, 0x08]); // CMP R10D, 8
        let tail_from_blk = self.emit_jcc_rel32(0x82); // JB: fewer than 8 left
        self.buf.emit(&[0x4C, 0x8B, 0x54, 0x11, 0x10]); // MOV R10, [RCX+RDX+16]
        self.buf.emit(&[0x4D, 0x3B, 0x54, 0x13, 0x10]); // CMP R10, [R11+RDX+16]
        let blk_mismatch = self.emit_jcc_rel32(0x85); // JNE
        self.buf.emit(&[0x83, 0xC2, 0x08]); // ADD EDX, 8
        self.emit_jmp_back_to(blk);
        let tail = self.buf.pos();
        self.patch_rel32_to_here(tail_from_blk);
        if block_mismatch_to_bytes {
            self.patch_rel32_to_here(blk_mismatch);
        } else {
            mismatches.push(blk_mismatch);
        }
        self.buf.emit(&[0x39, 0xC2]); // CMP EDX, EAX
        let tail_done = self.emit_jcc_rel32(0x83); // JAE: all equal
        self.buf.emit(&[0x44, 0x0F, 0xB6, 0x54, 0x11, 0x10]); // MOVZX R10D, BYTE [RCX+RDX+16]
        self.buf.emit(&[0x45, 0x3A, 0x54, 0x13, 0x10]); // CMP R10B, BYTE [R11+RDX+16]
        let byte_mismatch = self.emit_jcc_rel32(0x85); // JNE
        self.buf.emit(&[0xFF, 0xC2]); // INC EDX
        self.emit_jmp_back_to(tail);
        (mismatches, tail_done, byte_mismatch)
    }

    /// The 16-byte SSE2 stage of the String prefix's `indexOf(int)` scans
    /// (nio20 wave 4, lane L5, W3-L2-3): RCX the `byte[]`, EDX the byte
    /// offset to start at, R11D the byte length, XMM1 the needle broadcast
    /// to every byte (`words == false`) or every 16-bit lane. While 16 bytes
    /// remain, one `MOVDQU` + `PCMPEQB`/`PCMPEQW` + `PMOVMSKB`; a hit leaves
    /// the char index in EAX and takes the returned forward jump, otherwise
    /// the stage falls through with EDX at the first unscanned byte (and
    /// EAX clobbered) into the caller's scalar tail. Writes EAX, EDX, XMM0.
    fn emit_str_sse_scan_stage(&mut self, words: bool) -> usize {
        let v = self.buf.pos();
        self.buf.emit(&[0x44, 0x89, 0xD8]); // MOV EAX, R11D
        self.buf.emit(&[0x29, 0xD0]); // SUB EAX, EDX
        self.buf.emit(&[0x83, 0xF8, 0x10]); // CMP EAX, 16
        let exit = self.emit_jcc_rel32(0x82); // JB: the scalar tail
        self.buf.emit(&[0xF3, 0x0F, 0x6F, 0x44, 0x11, 0x10]); // MOVDQU XMM0, [RCX+RDX+16]
        if words {
            self.buf.emit(&[0x66, 0x0F, 0x75, 0xC1]); // PCMPEQW XMM0, XMM1
        } else {
            self.buf.emit(&[0x66, 0x0F, 0x74, 0xC1]); // PCMPEQB XMM0, XMM1
        }
        self.buf.emit(&[0x66, 0x0F, 0xD7, 0xC0]); // PMOVMSKB EAX, XMM0
        self.buf.emit(&[0x85, 0xC0]); // TEST EAX, EAX
        let hit = self.emit_jcc_rel32(0x85); // JNZ
        self.buf.emit(&[0x83, 0xC2, 0x10]); // ADD EDX, 16
        self.emit_jmp_back_to(v);
        self.patch_rel32_to_here(hit);
        self.buf.emit(&[0x0F, 0xBC, 0xC0]); // BSF EAX, EAX (the first matching byte)
        self.buf.emit(&[0x01, 0xD0]); // ADD EAX, EDX
        if words {
            self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1 (byte offset -> char index)
        }
        let found = self.emit_jmp_rel32();
        self.patch_rel32_to_here(exit);
        found
    }

    /// One coder pair of the String prefix's `indexOf(String)` (nio20 wave 4,
    /// lane L5, W3-L2-1): the naive first-occurrence search over a haystack
    /// of `hay_utf16` code units and a needle of `needle_utf16` ones (LATIN1 /
    /// LATIN1, UTF16 / UTF16, UTF16 haystack / LATIN1 needle -- the JDK's
    /// `StringLatin1.indexOf`, `StringUTF16.indexOf`, `StringUTF16.indexOfLatin1`
    /// answers). On entry RCX is the haystack's `byte[]`, R11 the needle's;
    /// every exit pushes a jump onto `to_store` with the answer in RAX, or
    /// onto `decline` (a UTF16 array of odd byte length). `recv` is re-read
    /// on the found edge (no GC point since: the same object).
    ///
    /// Register plan: EAX = candidate starts left minus one, RCX = the
    /// candidate's address, R10D = `j` as a NEEDLE byte offset, EDX = the
    /// needle unit.
    fn emit_str_index_of_str_body(
        &mut self,
        layout: &crate::StringFieldLayout,
        recv: NodeId,
        hay_utf16: bool,
        needle_utf16: bool,
        decline: &mut Vec<usize>,
        to_store: &mut Vec<usize>,
    ) {
        if hay_utf16 {
            self.emit_str_test_mem8(RCX, 8, 1); // TEST BYTE [RCX+8], 1
            decline.push(self.emit_jcc_rel32(0x85)); // JNZ: odd
        }
        if needle_utf16 {
            self.emit_str_test_mem8(R11, 8, 1); // TEST BYTE [R11+8], 1
            decline.push(self.emit_jcc_rel32(0x85)); // JNZ: odd
        }
        // EDX = the needle's byte length; an empty needle is found at 0.
        self.emit_load_base_disp32(RDX, R11, 8, false);
        self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
        let empty = self.emit_jcc_rel32(0x84); // JZ -> 0
                                               // EAX = n - m in chars, the positions left to try minus one; < 0 -> -1.
        self.emit_load_base_disp32(RAX, RCX, 8, false);
        if hay_utf16 {
            self.buf.emit(&[0xD1, 0xE8]); // SHR EAX, 1
        }
        if needle_utf16 {
            self.buf.emit(&[0xD1, 0xEA]); // SHR EDX, 1
        }
        self.buf.emit(&[0x29, 0xD0]); // SUB EAX, EDX
        let too_short = self.emit_jcc_rel32(0x88); // JS -> -1
                                                   // JIT r20 wave 12, lane qStr (W4-L5-1, `CRATONVM_JIT_IR_STRING_INDEXOF_SCAN`,
                                                   // inside `CRATONVM_JIT_IR_STRING_SSE2`): LATIN1 / LATIN1 skips
                                                   // candidate starts 16 at a time -- `PCMPEQB` of the 16 bytes at the
                                                   // cursor against the needle's first byte, `PMOVMSKB`, `BSF` to the
                                                   // first equal one -- before the byte compare, as HotSpot's
                                                   // `StringIndexOf` stub does. Taken only while at least 16 starts
                                                   // remain (EAX >= 15), so the 16-byte read stays inside the haystack:
                                                   // from the cursor to its end are EAX + m >= 16 bytes. A miss skips
                                                   // all 16 starts (none begins with the first byte); a hit moves the
                                                   // cursor to the first that does and lets the compare below decide.
        let scan = !hay_utf16
            && !needle_utf16
            && crate::ir_string_sse2_enabled()
            && crate::ir_string_indexof_scan_enabled();
        let mut scan_exhausted: Option<usize> = None;
        if scan {
            // XMM1 = needle[0] in every byte (EDX is free until the compare).
            self.buf.emit(&[0x41, 0x0F, 0xB6, 0x53, 0x10]); // MOVZX EDX, BYTE [R11+16]
            self.buf.emit(&[0x66, 0x0F, 0x6E, 0xCA]); // MOVD XMM1, EDX
            self.buf.emit(&[0x66, 0x0F, 0x60, 0xC9]); // PUNPCKLBW XMM1, XMM1
            self.buf.emit(&[0x66, 0x0F, 0x61, 0xC9]); // PUNPCKLWD XMM1, XMM1
            self.buf.emit(&[0x66, 0x0F, 0x70, 0xC9, 0x00]); // PSHUFD XMM1, XMM1, 0
        }
        let outer = self.buf.pos();
        if scan {
            self.buf.emit(&[0x83, 0xF8, 0x0F]); // CMP EAX, 15
            let scalar = self.emit_jcc_rel32(0x8C); // JL: fewer than 16 starts left
            self.buf.emit(&[0xF3, 0x0F, 0x6F, 0x41, 0x10]); // MOVDQU XMM0, [RCX+16]
            self.buf.emit(&[0x66, 0x0F, 0x74, 0xC1]); // PCMPEQB XMM0, XMM1
            self.buf.emit(&[0x66, 0x44, 0x0F, 0xD7, 0xD0]); // PMOVMSKB R10D, XMM0
            self.buf.emit(&[0x45, 0x85, 0xD2]); // TEST R10D, R10D
            let hit = self.emit_jcc_rel32(0x85); // JNZ
            self.buf.emit(&[0x48, 0x83, 0xC1, 0x10]); // ADD RCX, 16
            self.buf.emit(&[0x83, 0xE8, 0x10]); // SUB EAX, 16
            scan_exhausted = Some(self.emit_jcc_rel32(0x88)); // JS: no start left -> -1
            self.emit_jmp_back_to(outer);
            self.patch_rel32_to_here(hit);
            self.buf.emit(&[0x45, 0x0F, 0xBC, 0xD2]); // BSF R10D, R10D
            self.buf.emit(&[0x4C, 0x01, 0xD1]); // ADD RCX, R10
            self.buf.emit(&[0x44, 0x29, 0xD0]); // SUB EAX, R10D
            self.patch_rel32_to_here(scalar);
        }
        self.buf.emit(&[0x45, 0x31, 0xD2]); // XOR R10D, R10D
        let inner = self.buf.pos();
        self.buf.emit(&[0x45, 0x3B, 0x53, 0x08]); // CMP R10D, [R11+8]
        let found = self.emit_jcc_rel32(0x83); // JAE: the whole needle matched
        match (hay_utf16, needle_utf16) {
            (false, _) => {
                self.buf.emit(&[0x43, 0x0F, 0xB6, 0x54, 0x13, 0x10]); // MOVZX EDX, BYTE [R11+R10+16]
                self.buf.emit(&[0x42, 0x3A, 0x54, 0x11, 0x10]); // CMP DL, BYTE [RCX+R10+16]
            }
            (true, true) => {
                self.buf.emit(&[0x43, 0x0F, 0xB7, 0x54, 0x13, 0x10]); // MOVZX EDX, WORD [R11+R10+16]
                self.buf.emit(&[0x66, 0x42, 0x3B, 0x54, 0x11, 0x10]); // CMP DX, WORD [RCX+R10+16]
            }
            (true, false) => {
                self.buf.emit(&[0x43, 0x0F, 0xB6, 0x54, 0x13, 0x10]); // MOVZX EDX, BYTE [R11+R10+16]
                self.buf.emit(&[0x66, 0x42, 0x3B, 0x54, 0x51, 0x10]); // CMP DX, WORD [RCX+R10*2+16]
            }
        }
        let next = self.emit_jcc_rel32(0x85); // JNE
        if needle_utf16 {
            self.buf.emit(&[0x41, 0x83, 0xC2, 0x02]); // ADD R10D, 2
        } else {
            self.buf.emit(&[0x41, 0xFF, 0xC2]); // INC R10D
        }
        self.emit_jmp_back_to(inner);
        self.patch_rel32_to_here(next);
        if hay_utf16 {
            self.buf.emit(&[0x48, 0x83, 0xC1, 0x02]); // ADD RCX, 2
        } else {
            self.buf.emit(&[0x48, 0xFF, 0xC1]); // INC RCX
        }
        self.buf.emit(&[0xFF, 0xC8]); // DEC EAX
        self.emit_str_jcc_back(0x89, outer); // JNS
                                             // Not found.
        self.patch_rel32_to_here(too_short);
        if let Some(p) = scan_exhausted {
            self.patch_rel32_to_here(p);
        }
        self.buf.emit(&[0x48, 0xC7, 0xC0, 0xFF, 0xFF, 0xFF, 0xFF]); // MOV RAX, -1
        to_store.push(self.emit_jmp_rel32());
        self.patch_rel32_to_here(empty);
        self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX
        to_store.push(self.emit_jmp_rel32());
        // Found: the index is the cursor minus the haystack's start, in
        // chars, the start re-read from the receiver.
        self.patch_rel32_to_here(found);
        self.gp_load_value(RDX, recv);
        self.emit_str_value_and_coder(layout, RDX, RDX, None);
        self.buf.emit(&[0x48, 0x89, 0xC8]); // MOV RAX, RCX
        self.buf.emit(&[0x48, 0x29, 0xD0]); // SUB RAX, RDX
        if hay_utf16 {
            self.buf.emit(&[0x48, 0xD1, 0xE8]); // SHR RAX, 1
        }
        to_store.push(self.emit_jmp_rel32());
    }

    /// `String.hashCode()`'s uncached arm in the String prefix (nio20 wave 4,
    /// lane L5, W3-L2-2, `CRATONVM_JIT_IR_STRING_HASH_COMPUTE`). On entry RAX
    /// is the receiver (a non-null String whose `hash` read 0). A COMPACT
    /// receiver's hash is computed inline -- `h = 31 * h + unit` over the
    /// LATIN1 bytes or the UTF16 code units, `StringLatin1.hashCode` /
    /// `StringUTF16.hashCode` -- and a NON-ZERO result is stored into `hash`
    /// (a plain `int` store, no barrier) and left in RAX for the caller's
    /// store path. A zero result declines (the call sets `hashIsZero`, which
    /// this layout does not address), as do a legacy receiver (its cell is
    /// the call's to write, as in the single-pass body), a null `value` and
    /// a UTF16 array of odd byte length. Writes RAX, RCX, RDX, R10, R11.
    ///
    /// `hash_is_zero` (STRGAP19-6, `CRATONVM_JIT_STRING_HASH_IS_ZERO`): the
    /// COMPACT `hashIsZero` byte's offset. With it a zero result is answered
    /// here too, after `hashIsZero = true` (a plain byte store, as the JDK
    /// body's), instead of declining; the receiver is COMPACT on that path.
    fn emit_str_hash_compute(
        &mut self,
        layout: &crate::StringFieldLayout,
        recv: NodeId,
        decline: &mut Vec<usize>,
        hash_is_zero: Option<i32>,
    ) {
        self.emit_str_test_mem8(
            RAX,
            cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
            cratonvm_types::GC_FLAG_COMPACT,
        );
        decline.push(self.emit_jcc_rel32(0x84)); // JZ: legacy
        self.emit_str_value_and_coder(layout, RAX, RCX, Some(RDX));
        self.emit_str_test_r64(RCX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.emit_load_base_disp32(R11, RCX, 8, false); // R11D = byte length
        self.buf.emit(&[0x31, 0xC0]); // XOR EAX, EAX (h)
        self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
        let utf16 = self.emit_jcc_rel32(0x85); // JNZ
        self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX
        let top = self.buf.pos();
        self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
        let done8 = self.emit_jcc_rel32(0x83); // JAE
        self.buf.emit(&[0x44, 0x0F, 0xB6, 0x54, 0x11, 0x10]); // MOVZX R10D, BYTE [RCX+RDX+16]
        self.buf.emit(&[0x6B, 0xC0, 0x1F]); // IMUL EAX, EAX, 31
        self.buf.emit(&[0x44, 0x01, 0xD0]); // ADD EAX, R10D
        self.buf.emit(&[0xFF, 0xC2]); // INC EDX
        self.emit_jmp_back_to(top);
        self.patch_rel32_to_here(utf16);
        self.emit_str_test_mem8(RCX, 8, 1); // TEST BYTE [RCX+8], 1
        decline.push(self.emit_jcc_rel32(0x85)); // JNZ: odd
        self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX (a byte offset)
        let top16 = self.buf.pos();
        self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
        let done16 = self.emit_jcc_rel32(0x83); // JAE
        self.buf.emit(&[0x44, 0x0F, 0xB7, 0x54, 0x11, 0x10]); // MOVZX R10D, WORD [RCX+RDX+16]
        self.buf.emit(&[0x6B, 0xC0, 0x1F]); // IMUL EAX, EAX, 31
        self.buf.emit(&[0x44, 0x01, 0xD0]); // ADD EAX, R10D
        self.buf.emit(&[0x83, 0xC2, 0x02]); // ADD EDX, 2
        self.emit_jmp_back_to(top16);
        self.patch_rel32_to_here(done8);
        self.patch_rel32_to_here(done16);
        self.buf.emit(&[0x85, 0xC0]); // TEST EAX, EAX
        if let Some(off) = hash_is_zero {
            let nonzero = self.emit_jcc_rel32(0x85); // JNZ
                                                     // `hashIsZero = true` on the (COMPACT) receiver; EAX stays 0.
            self.gp_load_value(RDX, recv);
            // MOV BYTE [RDX + disp32], 1 (C6 /0 ib, ModRM 0x82)
            self.buf.emit(&[0xC6, 0x82]);
            self.buf.emit(&off.to_le_bytes());
            self.buf.emit(&[0x01]);
            let joined = self.emit_jmp_rel32();
            self.patch_rel32_to_here(nonzero);
            self.gp_load_value(RDX, recv);
            self.emit_str_store32_base_disp32(RAX, RDX, layout.hash_compact_offset);
            self.patch_rel32_to_here(joined);
            self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
            return;
        }
        decline.push(self.emit_jcc_rel32(0x84)); // JZ: the call sets `hashIsZero`
                                                 // The receiver again (no GC point since), then `hash = h` (compact).
        self.gp_load_value(RDX, recv);
        self.emit_str_store32_base_disp32(RAX, RDX, layout.hash_compact_offset);
        self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
    }

    /// `MOV DWORD [base + disp32], src` (`89 /r`; a SIB byte for an RSP/R12
    /// base).
    fn emit_str_store32_base_disp32(&mut self, src: u8, base: u8, disp: i32) {
        let rex = 0x40u8 | (((src >= 8) as u8) << 2) | ((base >= 8) as u8);
        if rex != 0x40 {
            self.buf.emit_byte(rex);
        }
        self.buf.emit(&[0x89, 0x80 | ((src & 7) << 3) | (base & 7)]);
        if base & 7 == 4 {
            self.buf.emit_byte(0x24);
        }
        self.buf.emit(&disp.to_le_bytes());
    }

    /// nio20 wave 4, lane L5 (proposal W3-L2-4): `StringBuilder.length()`,
    /// `charAt(int)` and `append(char)` answered inline as a guarded PREFIX of
    /// the `Op::Call`, over the layout's builder half
    /// ([`crate::StringBuilderFieldLayout`]) -- the single-pass
    /// STRINGBUILDER_ACCESS bodies (`x64/objects.rs`'s
    /// `emit_sb_append_char_body` / `emit_sb_char_at_body`, the `length` arm
    /// of `op_invoke.rs`), with every slow edge a decline to the call, which
    /// they already were there (a call, never a deopt). Same contract with
    /// the `Op::Call` arm as [`Self::try_emit_ir_string_search_prefix`].
    ///
    /// * `length()` -- `count`.
    /// * `charAt(int)` -- an index below `count` AND below the array's
    ///   capacity in chars (unsigned, so negatives decline), either coder; the
    ///   call raises the `StringIndexOutOfBoundsException`.
    /// * `append(char)` -- a LATIN1 builder, a char in `0..=0xFF`, and
    ///   `count < value.length` (unsigned): `value[count] = (byte) c;
    ///   count++`, returning the receiver. A full payload, a UTF16 builder
    ///   and a wider char decline (growth and inflation are the JDK body's /
    ///   native's). Two plain stores, a byte into a `byte[]` and an `int`
    ///   field: no reference, so no barrier; no allocation, so no GC point.
    ///   `maybeLatin1` is not touched: the JDK's LATIN1 arm does not touch it
    ///   either.
    ///
    /// The receiver guard is the exact class id (`StringBuilder` is final),
    /// which keeps `StringBuffer` (synchronized, a `toStringCache`) off the
    /// path. Per-object COMPACT / LEGACY dispatch on `GC_FLAG_COMPACT`, as
    /// the single-pass bodies.
    /// Stage reporting (`CRATONVM_DBG_IR_COMPILES` / `CRATONVM_DBG_JITC`):
    /// why a String / StringBuilder prefix site was left a plain call.
    fn note_string_prefix_declined(&self, id: NodeId, info: &JitInvokeInfo, reason: &str) {
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-prefix-declined n{id} {}.{}{}: {reason}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
    }

    fn try_emit_ir_string_builder_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        kind: crate::IrStringSearchKind,
        layout: crate::StringFieldLayout,
    ) {
        use crate::IrStringSearchKind as K;
        // nio20 w5 fix-back (L5): every decline names itself under stage
        // reporting (`note_string_prefix_declined`), so a site that never
        // shows the `[ir] string-builder-prefix` line says why.
        let Some(b) = layout.builder else {
            self.note_string_prefix_declined(id, info, "layout has no StringBuilder half");
            return;
        };
        if !kind.is_builder()
            || !kind.admits_invoke_kind(info.invoke_kind)
            || b.class_id == 0
            || b.value_compact_is_narrow
        {
            self.note_string_prefix_declined(
                id,
                info,
                &format!(
                    "invoke_kind={} builder_class_id={} value_compact_is_narrow={}",
                    info.invoke_kind, b.class_id, b.value_compact_is_narrow
                ),
            );
            return;
        }
        // `append(String)` reads the argument's `value` / `coder` through the
        // OUTER (String) layout; without a coder there is nothing to test.
        if kind == K::SbAppendString && !layout.has_coder {
            self.note_string_prefix_declined(id, info, "String layout has no coder");
            return;
        }
        if crate::x64::narrow_oops_block_inline_fields() {
            self.note_string_prefix_declined(id, info, "narrow oops / armed ZGC barrier");
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        let want_ty = if matches!(
            kind,
            K::SbAppendChar | K::SbAppendString | K::SbAppendInt | K::SbAppendCodePoint
        ) {
            IrType::Ref
        } else {
            IrType::Int
        };
        if node.inputs.len() != 3 + kind.num_params() || node.ty != want_ty {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        let recv = node.inputs[2];
        let arg = if kind.num_params() == 1 {
            Some(node.inputs[3])
        } else {
            None
        };
        if self.carry_names(recv) || arg.is_some_and(|a| self.carry_names(a)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        // The argument of the one-parameter kinds (the input-count screen
        // above guarantees it exists for them); never read for `length()`.
        let arg_id: NodeId = arg.unwrap_or(recv);
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            self.note_string_prefix_declined(id, info, "result carried or home dropped");
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            self.note_string_prefix_declined(id, info, "no planned result slot");
            return;
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-builder-prefix n{id} {}.{}{} kind={kind:?} builder_class_id={}",
                info.class_name, info.method_name, info.descriptor, b.class_id,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        // RAX = receiver; null declines (the call raises the NPE).
        self.gp_load_value(RAX, recv);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.emit_str_cmp_class_id(RAX, b.class_id);
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
        match kind {
            K::SbLength => {
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                self.emit_load_base_disp32(RAX, RAX, b.count_compact_offset, false);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RAX, RAX, b.count_legacy_offset, false);
                self.patch_rel32_to_here(have);
                self.buf.emit(&[0x48, 0x63, 0xC0]); // MOVSXD RAX, EAX
            }
            K::SbCharAt | K::SbAppendChar => {
                // R10 = the index (zero-extended: it scales the full
                // register) or the char.
                self.gp_load_value(R10, arg_id);
                self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
                if kind == K::SbAppendChar {
                    // LATIN1-encodable chars only (`StringLatin1.canEncode`).
                    self.buf.emit(&[0x41, 0x81, 0xFA, 0xFF, 0x00, 0x00, 0x00]); // CMP R10D, 0xFF
                    decline.push(self.emit_jcc_rel32(0x87)); // JA
                }
                // EDX = coder, R11D = count, RCX = value, per layout.
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                if b.coder_compact_is_byte {
                    self.emit_str_movzx8_base_disp32(RDX, RAX, b.coder_compact_offset);
                } else {
                    self.emit_load_base_disp32(RDX, RAX, b.coder_compact_offset, false);
                }
                self.emit_load_base_disp32(R11, RAX, b.count_compact_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_compact_offset, true);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RDX, RAX, b.coder_legacy_offset, false);
                self.emit_load_base_disp32(R11, RAX, b.count_legacy_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_legacy_offset, true);
                self.patch_rel32_to_here(have);
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: no payload yet
                if kind == K::SbCharAt {
                    self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D (index vs count)
                    decline.push(self.emit_jcc_rel32(0x83)); // JAE
                    self.emit_load_base_disp32(R11, RCX, 8, false); // R11D = value.length
                    self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                    let utf16 = self.emit_jcc_rel32(0x85); // JNZ
                    self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D (capacity)
                    decline.push(self.emit_jcc_rel32(0x83)); // JAE
                    self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x11, 0x10]); // MOVZX EAX, BYTE [RCX+R10+16]
                    let done = self.emit_jmp_rel32();
                    self.patch_rel32_to_here(utf16);
                    self.buf.emit(&[0x41, 0xD1, 0xEB]); // SHR R11D, 1
                    self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D (capacity)
                    decline.push(self.emit_jcc_rel32(0x83)); // JAE
                    self.buf.emit(&[0x42, 0x0F, 0xB7, 0x44, 0x51, 0x10]); // MOVZX EAX, WORD [RCX+R10*2+16]
                    self.patch_rel32_to_here(done);
                } else {
                    // append(char): LATIN1 builder with room.
                    self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                    decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16
                    self.buf.emit(&[0x44, 0x3B, 0x59, 0x08]); // CMP R11D, [RCX+8]
                    decline.push(self.emit_jcc_rel32(0x83)); // JAE: full (or a corrupt count)
                    self.buf.emit(&[0x46, 0x88, 0x54, 0x19, 0x10]); // MOV BYTE [RCX+R11+16], R10B
                    self.buf.emit(&[0x41, 0xFF, 0xC3]); // INC R11D
                                                        // `count = count + 1`, at the receiver's own layout.
                    self.emit_str_test_mem8(
                        RAX,
                        cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                        cratonvm_types::GC_FLAG_COMPACT,
                    );
                    let legacy_store = self.emit_jcc_rel32(0x84); // JZ legacy
                    self.emit_str_store32_base_disp32(R11, RAX, b.count_compact_offset);
                    let stored = self.emit_jmp_rel32();
                    self.patch_rel32_to_here(legacy_store);
                    self.emit_str_store32_base_disp32(R11, RAX, b.count_legacy_offset);
                    self.patch_rel32_to_here(stored);
                    // `append` returns its receiver, still in RAX.
                }
            }
            K::SbAppendString => {
                // nio20 wave 5, lane L5 (W4-L5-2): `AbstractStringBuilder
                // .append(String)` for a non-null LATIN1 String into a LATIN1
                // builder whose array already holds `count + len` bytes
                // (`ensureCapacityInternal` a no-op, `putStringAt` the
                // same-coder byte copy, `count += len`); every other shape
                // (null -> "null", either side UTF16, a growth) declines to the
                // call BEFORE anything is stored.
                //
                // R10 = the String, read before RCX / RDX / R11 are written (the
                // allocator never homes a value in them: they are scratch).
                self.gp_load_value(R10, arg_id);
                self.emit_str_test_r64(R10);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: append(null)
                                                         // EDX = builder coder, R11D = count, RCX = builder value.
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                if b.coder_compact_is_byte {
                    self.emit_str_movzx8_base_disp32(RDX, RAX, b.coder_compact_offset);
                } else {
                    self.emit_load_base_disp32(RDX, RAX, b.coder_compact_offset, false);
                }
                self.emit_load_base_disp32(R11, RAX, b.count_compact_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_compact_offset, true);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RDX, RAX, b.coder_legacy_offset, false);
                self.emit_load_base_disp32(R11, RAX, b.count_legacy_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_legacy_offset, true);
                self.patch_rel32_to_here(have);
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: no payload yet
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16 builder
                                                         // RDX = the String's value, EAX = its coder (the receiver is
                                                         // re-read below).
                self.emit_str_value_and_coder(&layout, R10, RDX, Some(RAX));
                self.buf.emit(&[0x85, 0xC0]); // TEST EAX, EAX
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16 String
                self.emit_str_test_r64(RDX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: no value
                                                         // R10D = len (LATIN1: value.length); EAX = count + len, which
                                                         // must fit the builder's array (unsigned: both are < 2^31).
                self.emit_load_base_disp32(R10, RDX, 8, false);
                self.buf.emit(&[0x44, 0x89, 0xD8]); // MOV EAX, R11D
                self.buf.emit(&[0x44, 0x01, 0xD0]); // ADD EAX, R10D
                self.buf.emit(&[0x3B, 0x41, 0x08]); // CMP EAX, [RCX+8]
                decline.push(self.emit_jcc_rel32(0x87)); // JA: needs growth
                                                         // No decline past this point. RCX = &value[count] - 16 (an
                                                         // interior pointer, held only inside this no-safepoint
                                                         // sequence), R11D = the new count.
                self.buf.emit(&[0x4A, 0x8D, 0x0C, 0x19]); // LEA RCX, [RCX+R11]
                self.buf.emit(&[0x41, 0x89, 0xC3]); // MOV R11D, EAX
                self.buf.emit(&[0x45, 0x85, 0xD2]); // TEST R10D, R10D
                let empty = self.emit_jcc_rel32(0x84); // JZ: append("")
                let top = self.buf.pos();
                self.buf.emit(&[0x41, 0xFF, 0xCA]); // DEC R10D
                self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x12, 0x10]); // MOVZX EAX, BYTE [RDX+R10+16]
                self.buf.emit(&[0x42, 0x88, 0x44, 0x11, 0x10]); // MOV BYTE [RCX+R10+16], AL
                self.buf.emit(&[0x45, 0x85, 0xD2]); // TEST R10D, R10D
                self.emit_str_jcc_back(0x85, top); // JNZ top
                self.patch_rel32_to_here(empty);
                // `count = count + len`, at the receiver's own layout; the
                // receiver is the result.
                self.gp_load_value(RAX, recv);
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy_store = self.emit_jcc_rel32(0x84); // JZ legacy
                self.emit_str_store32_base_disp32(R11, RAX, b.count_compact_offset);
                let stored = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy_store);
                self.emit_str_store32_base_disp32(R11, RAX, b.count_legacy_offset);
                self.patch_rel32_to_here(stored);
            }
            K::SbAppendInt => {
                // JIT r20 wave 18, lane xSb (STR20-2,
                // `CRATONVM_JIT_IR_SB_APPEND_INT_PREFIX`):
                // `AbstractStringBuilder.append(int)` for a LATIN1 builder whose
                // array already holds `count + stringSize(i)` bytes -- the
                // digits in place, `count = spaceNeeded`, the receiver as the
                // result. A UTF16 builder (the JDK's `uncheckedGetCharsUTF16`
                // arm), a growth (`ensureCapacitySameCoder`'s `newCapacity`
                // policy) and a missing payload decline to the call BEFORE
                // anything is stored.
                //
                // R10 = i, read before RCX / RDX / R11 are written (scratch: the
                // allocator never homes a value in them).
                const R9: u8 = 9;
                self.gp_load_value(R10, arg_id);
                // EDX = builder coder, R11D = count, RCX = builder value.
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                if b.coder_compact_is_byte {
                    self.emit_str_movzx8_base_disp32(RDX, RAX, b.coder_compact_offset);
                } else {
                    self.emit_load_base_disp32(RDX, RAX, b.coder_compact_offset, false);
                }
                self.emit_load_base_disp32(R11, RAX, b.count_compact_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_compact_offset, true);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RDX, RAX, b.coder_legacy_offset, false);
                self.emit_load_base_disp32(R11, RAX, b.count_legacy_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_legacy_offset, true);
                self.patch_rel32_to_here(have);
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: no payload yet
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16 builder

                // The room test (its decline precedes every store), then the
                // digits; R9D = the new count.
                crate::x64::concat_emit::emit_sb_append_int_latin1(&mut self.buf, &mut decline);
                // `count = spaceNeeded`, at the receiver's own layout; the
                // receiver (re-read: no GC point since) is the result.
                self.gp_load_value(RAX, recv);
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy_store = self.emit_jcc_rel32(0x84); // JZ legacy
                self.emit_str_store32_base_disp32(R9, RAX, b.count_compact_offset);
                let stored = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy_store);
                self.emit_str_store32_base_disp32(R9, RAX, b.count_legacy_offset);
                self.patch_rel32_to_here(stored);
            }
            K::SbAppendCodePoint => {
                // JIT r20 wave 19, lane zCp
                // (`CRATONVM_JIT_IR_SB_APPEND_CODE_POINT_PREFIX`): JDK 25's
                // `AbstractStringBuilder.appendCodePoint` where nothing grows
                // and nothing inflates --
                //
                // * LATIN1 builder, `cp` in `0..=0xFF`, `count < value.length`:
                //   `append((char) cp)`'s LATIN1 arm, `value[count++] = (byte) cp`;
                // * UTF16 builder, BMP `cp` (`cp >>> 16 == 0`, surrogate code
                //   units included, as `append(char)` stores them), `count <
                //   value.length >> 1`: `StringUTF16.putChar(value, count++, cp)`;
                // * UTF16 builder, supplementary `cp` (`cp - 0x10000` unsigned
                //   below `0x100000`), `count + 2 <= value.length >> 1`:
                //   `append(Character.toChars(cp))` -- `ensureCapacitySameCoder`
                //   a no-op, `putCharsSB` of the high then the low surrogate;
                //
                // then `count` advanced and the receiver returned. Everything
                // else -- a LATIN1 builder given a wider code point (the
                // inflation), a full payload (the growth), an invalid code
                // point (`toChars` throws `IllegalArgumentException`), a coder
                // other than 0 / 1, no payload -- declines to the call BEFORE
                // any store. Neither arm touches `maybeLatin1` (the JDK's
                // append paths do not). Plain stores into a `byte[]` and an
                // `int` field: no reference, no barrier, no allocation, no GC
                // point.
                const R9: u8 = 9;
                // R10D = the code point, read before RCX / RDX / R11 are
                // written (scratch: the allocator never homes a value in them).
                self.gp_load_value(R10, arg_id);
                // EDX = builder coder, R11D = count, RCX = builder value.
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy = self.emit_jcc_rel32(0x84); // JZ legacy
                if b.coder_compact_is_byte {
                    self.emit_str_movzx8_base_disp32(RDX, RAX, b.coder_compact_offset);
                } else {
                    self.emit_load_base_disp32(RDX, RAX, b.coder_compact_offset, false);
                }
                self.emit_load_base_disp32(R11, RAX, b.count_compact_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_compact_offset, true);
                let have = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy);
                self.emit_load_base_disp32(RDX, RAX, b.coder_legacy_offset, false);
                self.emit_load_base_disp32(R11, RAX, b.count_legacy_offset, false);
                self.emit_load_base_disp32(RCX, RAX, b.value_legacy_offset, true);
                self.patch_rel32_to_here(have);
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ: no payload yet
                self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                let utf16 = self.emit_jcc_rel32(0x85); // JNZ
                                                       // ---- LATIN1 ----
                self.buf.emit(&[0x41, 0x81, 0xFA, 0xFF, 0x00, 0x00, 0x00]); // CMP R10D, 0xFF
                decline.push(self.emit_jcc_rel32(0x87)); // JA: inflation (or invalid)
                self.buf.emit(&[0x44, 0x3B, 0x59, 0x08]); // CMP R11D, [RCX+8]
                decline.push(self.emit_jcc_rel32(0x83)); // JAE: full (or a corrupt count)
                self.buf.emit(&[0x46, 0x88, 0x54, 0x19, 0x10]); // MOV BYTE [RCX+R11+16], R10B
                self.buf.emit(&[0x41, 0xFF, 0xC3]); // INC R11D
                let latin1_done = self.emit_jmp_rel32();
                // ---- UTF16 ----
                self.patch_rel32_to_here(utf16);
                self.buf.emit(&[0x83, 0xFA, 0x01]); // CMP EDX, 1
                decline.push(self.emit_jcc_rel32(0x85)); // JNE: no such coder
                                                         // EDX = the capacity in chars, `value.length >> 1`.
                self.emit_load_base_disp32(RDX, RCX, 8, false);
                self.buf.emit(&[0xD1, 0xEA]); // SHR EDX, 1
                self.buf.emit(&[0x45, 0x89, 0xD1]); // MOV R9D, R10D
                self.buf.emit(&[0x41, 0xC1, 0xE9, 0x10]); // SHR R9D, 16
                let supplementary = self.emit_jcc_rel32(0x85); // JNZ
                                                               // BMP: one char at `count`.
                self.buf.emit(&[0x41, 0x39, 0xD3]); // CMP R11D, EDX
                decline.push(self.emit_jcc_rel32(0x83)); // JAE: full
                self.buf.emit(&[0x66, 0x46, 0x89, 0x54, 0x59, 0x10]); // MOV WORD [RCX+R11*2+16], R10W
                self.buf.emit(&[0x41, 0xFF, 0xC3]); // INC R11D
                let bmp_done = self.emit_jmp_rel32();
                // Supplementary: valid only below 0x110000.
                self.patch_rel32_to_here(supplementary);
                self.buf.emit(&[0x45, 0x8D, 0x8A]); // LEA R9D, [R10 + disp32]
                self.buf.emit(&(-0x1_0000i32).to_le_bytes());
                self.buf.emit(&[0x41, 0x81, 0xF9]); // CMP R9D, imm32
                self.buf.emit(&0x10_0000i32.to_le_bytes());
                decline.push(self.emit_jcc_rel32(0x83)); // JAE: invalid, the call throws
                self.buf.emit(&[0x45, 0x8D, 0x4B, 0x02]); // LEA R9D, [R11 + 2]
                self.buf.emit(&[0x41, 0x39, 0xD1]); // CMP R9D, EDX
                decline.push(self.emit_jcc_rel32(0x87)); // JA: needs growth
                                                         // No decline past this point. High surrogate at `count`:
                                                         // `(cp >>> 10) + (0xD800 - (0x10000 >>> 10))`.
                self.buf.emit(&[0x45, 0x89, 0xD1]); // MOV R9D, R10D
                self.buf.emit(&[0x41, 0xC1, 0xE9, 0x0A]); // SHR R9D, 10
                self.buf.emit(&[0x41, 0x81, 0xC1]); // ADD R9D, imm32
                self.buf
                    .emit(&crate::x64::concat_emit::HIGH_SURROGATE_BIAS.to_le_bytes());
                self.buf.emit(&[0x66, 0x46, 0x89, 0x4C, 0x59, 0x10]); // MOV WORD [RCX+R11*2+16], R9W
                                                                      // Low surrogate at `count + 1`: `(cp & 0x3FF) + 0xDC00`.
                self.buf.emit(&[0x45, 0x89, 0xD1]); // MOV R9D, R10D
                self.buf.emit(&[0x41, 0x81, 0xE1, 0xFF, 0x03, 0x00, 0x00]); // AND R9D, 0x3FF
                self.buf.emit(&[0x41, 0x81, 0xC1]); // ADD R9D, imm32
                self.buf
                    .emit(&crate::x64::concat_emit::LOW_SURROGATE_BASE.to_le_bytes());
                self.buf.emit(&[0x66, 0x46, 0x89, 0x4C, 0x59, 0x12]); // MOV WORD [RCX+R11*2+18], R9W
                self.buf.emit(&[0x41, 0x83, 0xC3, 0x02]); // ADD R11D, 2
                self.patch_rel32_to_here(latin1_done);
                self.patch_rel32_to_here(bmp_done);
                // `count = R11D`, at the receiver's own layout (RAX is still
                // the receiver, and the result).
                self.emit_str_test_mem8(
                    RAX,
                    cratonvm_types::GC_FLAGS_BYTE_OFFSET as u8, // Cast: x86-64 disp8
                    cratonvm_types::GC_FLAG_COMPACT,
                );
                let legacy_store = self.emit_jcc_rel32(0x84); // JZ legacy
                self.emit_str_store32_base_disp32(R11, RAX, b.count_compact_offset);
                let stored = self.emit_jmp_rel32();
                self.patch_rel32_to_here(legacy_store);
                self.emit_str_store32_base_disp32(R11, RAX, b.count_legacy_offset);
                self.patch_rel32_to_here(stored);
            }
            // Screened above (`is_builder`); a String kind never reaches here,
            // and `SbToString` is routed to its own emitter before this one.
            _ => {}
        }
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio20 wave 6, lane L2 (`heapcb`, NIO19-8's last residual):
    /// `String.getChars(int srcBegin, int srcEnd, char[] dst, int dstBegin)`
    /// answered inline as a guarded PREFIX of the `Op::Call`, for a LATIN1
    /// receiver -- the whole JDK body (`checkBoundsBeginEnd`,
    /// `checkBoundsOffCount`, `StringLatin1.getChars` -> `StringLatin1.inflate`,
    /// a registered native reached through the lean native door) as one
    /// bounds screen and a byte -> char copy. No tier had an intrinsic for it,
    /// so `HeapCharBuffer.put(String,int,int)` paid two door crossings per op
    /// on either tier.
    ///
    /// Same contract with the `Op::Call` arm as
    /// [`Self::try_emit_ir_string_search_prefix`]: scratch RAX, RCX, RDX, R10,
    /// R11 (and XMM0/XMM1, the lowerer's per-op FP scratch, for the 8-char
    /// SSE2 step under `CRATONVM_JIT_IR_STRING_SSE2`); the method is `void`,
    /// so the hit edge stores nothing and jumps to [`Self::call_prefix_join`];
    /// no call, no GC point, no deopt on the hit path.
    ///
    /// # Declines (to the call, which answers or throws exactly as before)
    ///
    /// A replaced layout, a null receiver or one whose header is not
    /// `java/lang/String`, a null `value`, a UTF16 coder, `srcEnd` outside
    /// `[0, length]` or `srcBegin` outside `[0, srcEnd]` (unsigned compares,
    /// so negatives decline), a null `dst` or one whose header is not a
    /// `char[]`, `dstBegin` outside `[0, dst.length]`, and `srcEnd - srcBegin
    /// > dst.length - dstBegin`. Those are exactly the JDK body's throwing
    /// conditions (SIOOBE for the source bounds, NPE for `dst`, SIOOBE for the
    /// destination bounds), plus the UTF16 arm, so every throwing input
    /// reaches the call with nothing stored. Past the last decline the copy
    /// cannot fail.
    ///
    /// The stores are `char`s into a primitive array: no reference, no
    /// barrier. `value` and `dst` are distinct arrays (a `byte[]` and a
    /// `char[]`), so the copy cannot overlap. Like the other String prefixes
    /// the loop polls no safepoint; a multi-megabyte `getChars` delays one by
    /// its own length, as the native it replaces did.
    fn try_emit_ir_string_getchars_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        layout: crate::StringFieldLayout,
    ) {
        use crate::IrStringSearchKind as K;
        if !K::GetChars.admits_invoke_kind(info.invoke_kind)
            || !layout.has_coder
            || layout.string_class_id == 0
        {
            self.note_string_prefix_declined(
                id,
                info,
                &format!(
                    "invoke_kind={} has_coder={} string_class_id={}",
                    info.invoke_kind, layout.has_coder, layout.string_class_id
                ),
            );
            return;
        }
        if crate::x64::narrow_oops_block_inline_fields() {
            self.note_string_prefix_declined(id, info, "narrow oops / armed ZGC barrier");
            return;
        }
        let Some(char_array_tag) = cratonvm_types::primitive_array_kind_tags_byte("[C") else {
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver, srcBegin, srcEnd, dst, dstBegin], void.
        if node.inputs.len() != 3 + K::GetChars.num_params() || node.ty != IrType::Void {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        let recv = node.inputs[2];
        let src_begin = node.inputs[3];
        let src_end = node.inputs[4];
        let dst = node.inputs[5];
        let dst_begin = node.inputs[6];
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-getchars-prefix n{id} {}.{}{} string_class_id={}",
                info.class_name, info.method_name, info.descriptor, layout.string_class_id,
            );
        }
        // `[arr + 8]` is the array length and `[arr + 16 + i]` element byte
        // `i`: the two displacements below. The search prefix above asserts
        // the length offset at compile time; the payload offset is asserted
        // here.
        const _: () = assert!(
            cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the getChars prefix bakes ARRAY_DATA_OFFSET 16"
        );
        const KIND_TAGS: u8 = cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8; // Cast: x86-64 disp8
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
        let mut decline: Vec<usize> = Vec::new();
        // RCX: the epoch guard's fallback form and the `value` load write it.
        self.note_rcx_written();
        if let Some(p) = self.emit_layout_epoch_guard() {
            decline.push(p);
        }
        // RAX = receiver; null declines (the call raises the NPE).
        self.gp_load_value(RAX, recv);
        self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.emit_str_cmp_class_id(RAX, layout.string_class_id);
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // RCX = value, EDX = coder; a null value or UTF16 declines.
        self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
        self.emit_str_test_r64(RCX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
        decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16
                                                 // EAX = length() (LATIN1: value.length).
        self.emit_load_base_disp32(RAX, RCX, 8, false);
        // R10D = srcEnd, zero-extended: unsigned compares decline negatives.
        self.gp_load_value(R10, src_end);
        self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
        self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
        decline.push(self.emit_jcc_rel32(0x87)); // JA: srcEnd > length (or < 0)
                                                 // R11D = srcBegin.
        self.gp_load_value(R11, src_begin);
        self.buf.emit(&[0x45, 0x89, 0xDB]); // MOV R11D, R11D
        self.buf.emit(&[0x45, 0x39, 0xD3]); // CMP R11D, R10D
        decline.push(self.emit_jcc_rel32(0x87)); // JA: srcBegin > srcEnd (or < 0)
                                                 // R10D = count = srcEnd - srcBegin; RCX = &value[srcBegin] - 16 (an
                                                 // interior pointer, held only inside this no-safepoint sequence).
        self.buf.emit(&[0x45, 0x29, 0xDA]); // SUB R10D, R11D
        self.buf.emit(&[0x4A, 0x8D, 0x0C, 0x19]); // LEA RCX, [RCX+R11]
                                                  // RDX = dst: non-null and a `char[]` (the descriptor promises one;
                                                  // the header test is four bytes against trusting it).
        self.gp_load_value(RDX, dst);
        self.emit_str_test_r64(RDX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ: the call's NPE
        self.buf.emit(&[0x80, 0x7A, KIND_TAGS, char_array_tag]); // CMP BYTE [RDX+KIND_TAGS], [C tag
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // EAX = dstBegin, in [0, dst.length].
        self.gp_load_value(RAX, dst_begin);
        self.buf.emit(&[0x89, 0xC0]); // MOV EAX, EAX
        self.buf.emit(&[0x3B, 0x42, 0x08]); // CMP EAX, [RDX+8]
        decline.push(self.emit_jcc_rel32(0x87)); // JA
                                                 // count <= dst.length - dstBegin (both sides in [0, 2^31)).
        self.emit_load_base_disp32(R11, RDX, 8, false); // R11D = dst.length
        self.buf.emit(&[0x41, 0x29, 0xC3]); // SUB R11D, EAX
        self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D
        decline.push(self.emit_jcc_rel32(0x87)); // JA
                                                 // No decline past this point. RDX = &dst[dstBegin] - 16.
        self.buf.emit(&[0x48, 0x8D, 0x14, 0x42]); // LEA RDX, [RDX+RAX*2]
        self.emit_str_inflate_copy();
        // A call chain the single-pass backend has no inline form for, lowered
        // as straight-line code: acceptance evidence, like a scalar intrinsic
        // (a call-site prefix is otherwise invisible to the gate, and a body
        // whose only gain is this one would be refused and memoised).
        crate::ir_evidence::note(crate::ir_evidence::Transform::ScalarIntrinsic);
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// nio20 wave 6, lane L2: `StringLatin1.inflate(byte[] src, int srcOff,
    /// char[] dst, int dstOff, int len)` -- the `@IntrinsicCandidate` the JDK's
    /// LATIN1 `getChars` / `toChars` / `StringUTF16` paths end in, a native
    /// door crossing in this VM -- answered inline at an `invokestatic` as a
    /// guarded PREFIX of the `Op::Call` (kind
    /// [`crate::IrStringSearchKind::Inflate`]), with the same copy as
    /// [`Self::try_emit_ir_string_getchars_prefix`]. Reached when a caller of
    /// `inflate` (`StringLatin1.getChars`, typically spliced into a compiled
    /// `String.getChars`) is on the optimizing tier.
    ///
    /// The JDK body is an unchecked loop: a non-positive `len` copies nothing
    /// (even with null arrays) and an out-of-range index throws
    /// `ArrayIndexOutOfBoundsException` AFTER the elements before it were
    /// copied. So this answers only the fully in-range case -- non-null
    /// `byte[]` and `char[]` headers, `srcOff + len <= src.length` and
    /// `dstOff + len <= dst.length`, every value non-negative (unsigned
    /// compares) -- and DECLINES every other input to the call, before
    /// anything is stored, which reproduces the partial copy and the throw.
    /// No field offsets are baked, so no layout-epoch guard.
    fn try_emit_ir_string_inflate_prefix(&mut self, id: NodeId, info: &JitInvokeInfo) {
        use crate::IrStringSearchKind as K;
        if !K::Inflate.admits_invoke_kind(info.invoke_kind) {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("invoke_kind={}", info.invoke_kind),
            );
            return;
        }
        let (Some(byte_array_tag), Some(char_array_tag)) = (
            cratonvm_types::primitive_array_kind_tags_byte("[B"),
            cratonvm_types::primitive_array_kind_tags_byte("[C"),
        ) else {
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, src, srcOff, dst, dstOff, len], void (static: `src`
        // stands where an instance method's receiver would).
        if node.inputs.len() != 3 + K::Inflate.num_params() || node.ty != IrType::Void {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        let src = node.inputs[2];
        let src_off = node.inputs[3];
        let dst = node.inputs[4];
        let dst_off = node.inputs[5];
        let len = node.inputs[6];
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-inflate-prefix n{id} {}.{}{}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
        const _: () = assert!(
            cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the inflate prefix bakes ARRAY_DATA_OFFSET 16"
        );
        const KIND_TAGS: u8 = cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8; // Cast: x86-64 disp8
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
        let mut decline: Vec<usize> = Vec::new();
        // R10D = len, zero-extended: a negative `len` fails the bounds below
        // and declines (the call copies nothing).
        self.gp_load_value(R10, len);
        self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
                                            // RCX = src: non-null `byte[]`.
        self.gp_load_value(RCX, src);
        self.emit_str_test_r64(RCX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.buf.emit(&[0x80, 0x79, KIND_TAGS, byte_array_tag]); // CMP BYTE [RCX+KIND_TAGS], [B tag
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // R11D = srcOff in [0, src.length]; len <= src.length - srcOff.
        self.gp_load_value(R11, src_off);
        self.buf.emit(&[0x45, 0x89, 0xDB]); // MOV R11D, R11D
        self.buf.emit(&[0x44, 0x3B, 0x59, 0x08]); // CMP R11D, [RCX+8]
        decline.push(self.emit_jcc_rel32(0x87)); // JA
        self.emit_load_base_disp32(RAX, RCX, 8, false); // EAX = src.length
        self.buf.emit(&[0x44, 0x29, 0xD8]); // SUB EAX, R11D
        self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
        decline.push(self.emit_jcc_rel32(0x87)); // JA
        self.buf.emit(&[0x4A, 0x8D, 0x0C, 0x19]); // LEA RCX, [RCX+R11]
                                                  // RDX = dst: non-null `char[]`.
        self.gp_load_value(RDX, dst);
        self.emit_str_test_r64(RDX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.buf.emit(&[0x80, 0x7A, KIND_TAGS, char_array_tag]); // CMP BYTE [RDX+KIND_TAGS], [C tag
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // EAX = dstOff in [0, dst.length]; len <= dst.length - dstOff.
        self.gp_load_value(RAX, dst_off);
        self.buf.emit(&[0x89, 0xC0]); // MOV EAX, EAX
        self.buf.emit(&[0x3B, 0x42, 0x08]); // CMP EAX, [RDX+8]
        decline.push(self.emit_jcc_rel32(0x87)); // JA
        self.emit_load_base_disp32(R11, RDX, 8, false); // R11D = dst.length
        self.buf.emit(&[0x41, 0x29, 0xC3]); // SUB R11D, EAX
        self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D
        decline.push(self.emit_jcc_rel32(0x87)); // JA
                                                 // No decline past this point.
        self.buf.emit(&[0x48, 0x8D, 0x14, 0x42]); // LEA RDX, [RDX+RAX*2]
        self.emit_str_inflate_copy();
        crate::ir_evidence::note(crate::ir_evidence::Transform::ScalarIntrinsic);
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r20 wave 18, lane xUtf8 (book `jit-r20-strings-proposals.md`,
    /// STR20-6; `CRATONVM_JIT_IR_STRING_CODING_PREFIX`): the two
    /// `java/lang/StringCoding` `@IntrinsicCandidate` leaves the coders' ASCII
    /// runs go through, answered inline at their `invokestatic` as a guarded
    /// PREFIX of the `Op::Call` (HotSpot has a stub for each):
    ///
    /// * `countPositives(byte[] ba, int off, int len)` -- `String.decodeASCII`
    ///   (`UTF_8$Decoder.decodeArrayLoop`'s `JLA.uncheckedDecodeASCII`),
    ///   `hasNegatives`, the `new String(bytes, cs)` / `getBytes` ASCII fast
    ///   paths: 16 bytes per SSE2 step (`PMOVMSKB`, then `BSF` on a hit);
    /// * `implEncodeAsciiArray(char[] sa, int sp, byte[] da, int dp, int len)`
    ///   -- `UTF_8$Encoder.encodeArrayLoop`'s `JLA.uncheckedEncodeASCII`: 8
    ///   chars per SSE2 step (a saturating add of `0x7F80` sets bit 15 of a
    ///   lane exactly when its char is `>= 0x80`; `PACKUSWB` then narrows the
    ///   eight tested chars, all `< 0x80`, from the SAME register, so a racing
    ///   writer can never get an untested char stored).
    ///
    /// Both JDK bodies are unchecked loops: a non-positive `len` touches
    /// nothing (even a null array), and an out-of-range index throws
    /// `ArrayIndexOutOfBoundsException` after the elements before it were
    /// scanned / stored. So this answers only the fully in-range case --
    /// non-null arrays of the declared element types (kind tag), every offset
    /// in `[0, length]` and `len <= length - off` (unsigned compares, so a
    /// negative value declines) -- and DECLINES every other input to the call
    /// before anything is stored, which reproduces the bytecode's answer,
    /// partial store and throw. The answer is the bytecode's exactly: the
    /// index of the first negative byte, else `len` (the JDK's implSpec would
    /// allow less; the interpreter answers exactly this), and the number of
    /// chars copied before the first one `>= 0x80`, at or past which nothing
    /// is stored. No field offsets are baked, so no layout-epoch guard; the
    /// loops poll nothing (leaves of at most `len` steps, like the bodies they
    /// replace). Scratch: RAX, RCX, RDX, R10, R11, XMM0/XMM1, the `Inflate`
    /// prefix's set.
    fn try_emit_ir_string_coding_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        kind: crate::IrStringSearchKind,
    ) {
        use crate::IrStringSearchKind as K;
        if !kind.is_string_coding() || !kind.admits_invoke_kind(info.invoke_kind) {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("invoke_kind={}", info.invoke_kind),
            );
            return;
        }
        let (Some(byte_array_tag), Some(char_array_tag)) = (
            cratonvm_types::primitive_array_kind_tags_byte("[B"),
            cratonvm_types::primitive_array_kind_tags_byte("[C"),
        ) else {
            return;
        };
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, ba, off, len] / [ctrl, mem, sa, sp, da, dp, len], `int`
        // (static: the first array stands where a receiver would).
        if node.inputs.len() != 3 + kind.num_params() || node.ty != IrType::Int {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            self.note_string_prefix_declined(id, info, "a carried or dropped result home");
            return;
        }
        // The result's home, computed without allocating it (see the
        // ArrayList prefix).
        let Ok(slot) = self.planned_slot_off(id) else {
            self.note_string_prefix_declined(id, info, "no result home");
            return;
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-coding-prefix n{id} {}.{}{} kind={kind:?}",
                info.class_name, info.method_name, info.descriptor,
            );
        }
        // The array length at `+8` is baked as the `Inflate` prefix bakes it
        // (the String search prefix's `const` assert covers that layout).
        const _: () = assert!(
            cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the StringCoding prefix bakes ARRAY_DATA_OFFSET 16"
        );
        const KIND_TAGS: u8 = cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8; // Cast: x86-64 disp8
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
        let mut decline: Vec<usize> = Vec::new();
        // The raw `LEA RCX` below writes RCX too.
        self.note_rcx_written();
        // R10D = len, zero-extended: a negative `len` fails the bounds below
        // and declines (the call answers it).
        let len = node.inputs[if kind == K::CountPositives { 4 } else { 6 }];
        self.gp_load_value(R10, len);
        self.buf.emit(&[0x45, 0x89, 0xD2]); // MOV R10D, R10D
                                            // RCX = the source array: non-null, of the declared element type.
        let (src, src_off) = (node.inputs[2], node.inputs[3]);
        let src_tag = if kind == K::CountPositives {
            byte_array_tag
        } else {
            char_array_tag
        };
        self.gp_load_value(RCX, src);
        self.emit_str_test_r64(RCX);
        decline.push(self.emit_jcc_rel32(0x84)); // JZ
        self.buf.emit(&[0x80, 0x79, KIND_TAGS, src_tag]); // CMP BYTE [RCX+KIND_TAGS], tag
        decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                 // R11D = off in [0, src.length]; len <= src.length - off.
        self.gp_load_value(R11, src_off);
        self.buf.emit(&[0x45, 0x89, 0xDB]); // MOV R11D, R11D
        self.buf.emit(&[0x44, 0x3B, 0x59, 0x08]); // CMP R11D, [RCX+8]
        decline.push(self.emit_jcc_rel32(0x87)); // JA
        self.emit_load_base_disp32(RAX, RCX, 8, false); // EAX = src.length
        self.buf.emit(&[0x44, 0x29, 0xD8]); // SUB EAX, R11D
        self.buf.emit(&[0x41, 0x39, 0xC2]); // CMP R10D, EAX
        decline.push(self.emit_jcc_rel32(0x87)); // JA
        if kind == K::CountPositives {
            // No decline past this point.
            self.buf.emit(&[0x4A, 0x8D, 0x0C, 0x19]); // LEA RCX, [RCX+R11]
            self.emit_str_count_positives_scan();
        } else {
            self.buf.emit(&[0x4A, 0x8D, 0x0C, 0x59]); // LEA RCX, [RCX+R11*2]
            let (dst, dst_off) = (node.inputs[4], node.inputs[5]);
            // RDX = da: non-null `byte[]`.
            self.gp_load_value(RDX, dst);
            self.emit_str_test_r64(RDX);
            decline.push(self.emit_jcc_rel32(0x84)); // JZ
            self.buf.emit(&[0x80, 0x7A, KIND_TAGS, byte_array_tag]); // CMP BYTE [RDX+KIND_TAGS], [B tag
            decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                     // EAX = dp in [0, da.length]; len <= da.length - dp.
            self.gp_load_value(RAX, dst_off);
            self.buf.emit(&[0x89, 0xC0]); // MOV EAX, EAX
            self.buf.emit(&[0x3B, 0x42, 0x08]); // CMP EAX, [RDX+8]
            decline.push(self.emit_jcc_rel32(0x87)); // JA
            self.emit_load_base_disp32(R11, RDX, 8, false); // R11D = da.length
            self.buf.emit(&[0x41, 0x29, 0xC3]); // SUB R11D, EAX
            self.buf.emit(&[0x45, 0x39, 0xDA]); // CMP R10D, R11D
            decline.push(self.emit_jcc_rel32(0x87)); // JA
                                                     // No decline past this point.
            self.buf.emit(&[0x48, 0x8D, 0x14, 0x02]); // LEA RDX, [RDX+RAX]
            self.emit_str_encode_ascii_copy();
        }
        // EAX = the answer, in [0, len]. The call route's `store_rax(slot)`
        // at run time, written as the ArrayList prefix writes it: the
        // resident register when the value has one, then the home word.
        if let Some(reg) = self.assigned_gpr(id) {
            self.emit_mov_reg_reg64(reg, RAX);
        }
        let mut bytes = FrameAccess::new();
        enc_frame_store(RAX, slot, &mut bytes);
        self.buf.emit(bytes.as_slice());
        // A call the single-pass backend has no inline form for, lowered as
        // straight-line code: acceptance evidence, as `Inflate`.
        crate::ir_evidence::note(crate::ir_evidence::Transform::ScalarIntrinsic);
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r21 wave 1/3, lane strings: the Latin-1 case kinds
    /// ([`crate::IrStringSearchKind::is_latin1_case`]) as a guarded PREFIX of
    /// the `Op::Call`, with the `char[]` copies' contract
    /// ([`Self::try_emit_ir_string_chars_prefix`]: scratch RAX, RCX, RDX,
    /// R8-R11; the hit edge stores the result and joins; no call, no poll, no
    /// throw; every decline precedes the first store and lands on the
    /// unchanged call).
    ///
    /// * `String.toLowerCase(Locale)` / `toLowerCase()` (ZCP-3,
    ///   `CRATONVM_JIT_IR_STRING_LOWER_UNCHANGED_PREFIX`) and the static
    ///   `StringLatin1.toLowerCase(String, byte[], Locale)` (the worker,
    ///   `CRATONVM_JIT_IR_STRING_INTERNAL_ADMIT`): JDK 17 / 21 / 25
    ///   `StringLatin1.toLowerCase` -- a null locale throws (decline); the
    ///   scan for the first `CharacterDataLatin1.isUpperCase` byte (`A-Z`,
    ///   `0xC0..=0xD6`, `0xD8..=0xDE`: the JDK's `B[]` bit `0x0002`); none
    ///   answers `str` itself. From the first upper-case byte on, a byte
    ///   ConditionalSpecialCasing's lower-case table names for `tr` / `az` /
    ///   `lt` (`I`, `J`, `0xCC`, `0xCD` -- every other row of it is outside
    ///   Latin-1) declines, because the language is not read here; otherwise
    ///   the result is the non-locale arm's, `new String(mapped, LATIN1)` of
    ///   `CharacterDataLatin1.toLowerCase` of every byte, and that is what
    ///   [`crate::x64::concat_emit::emit_ir_latin1_to_lower_string`] builds
    ///   (a FRESH String, as the JDK's). Without an allocation plan for this
    ///   compile, a changed string declines. A UTF16 receiver declines.
    /// * the static `StringLatin1.compareToCI([B[B)I` (the worker,
    ///   `CRATONVM_JIT_IR_STRING_INTERNAL_ADMIT`): two non-null `byte[]`s ->
    ///   [`Self::emit_latin1_ci_loop`]; anything else is the call.
    fn try_emit_ir_string_latin1_case_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        kind: crate::IrStringSearchKind,
        layout: crate::StringFieldLayout,
    ) {
        use crate::x64::concat_emit as ce;
        use crate::IrStringSearchKind as K;
        if !kind.is_latin1_case()
            || !kind.admits_invoke_kind(info.invoke_kind)
            || !layout.has_coder
            || layout.string_class_id == 0
        {
            self.note_string_prefix_declined(
                id,
                info,
                &format!(
                    "invoke_kind={} has_coder={} string_class_id={}",
                    info.invoke_kind, layout.has_coder, layout.string_class_id
                ),
            );
            return;
        }
        if crate::x64::narrow_oops_block_inline_fields() {
            self.note_string_prefix_declined(id, info, "narrow oops / armed ZGC barrier");
            return;
        }
        let Some(byte_array_tag) = cratonvm_types::primitive_array_kind_tags_byte("[B") else {
            return;
        };
        const KIND_TAGS: u8 = cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8; // Cast: x86-64 disp8
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
        const _: () = assert!(
            cratonvm_types::ARRAY_LENGTH_OFFSET == 8 && cratonvm_types::ARRAY_DATA_OFFSET == 16,
            "the Latin-1 case prefix bakes ARRAY_LENGTH_OFFSET 8 / ARRAY_DATA_OFFSET 16"
        );
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        let want_ty = if kind == K::Latin1CompareToCI {
            IrType::Int
        } else {
            IrType::Ref
        };
        if node.inputs.len() != 3 + kind.num_params() || node.ty != want_ty {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        if self.carry_of.get(id as usize).copied().flatten().is_some()
            || self.home_dropped.get(id as usize).copied().unwrap_or(false)
        {
            self.note_string_prefix_declined(id, info, "a carried or dropped result home");
            return;
        }
        let Ok(slot) = self.planned_slot_off(id) else {
            self.note_string_prefix_declined(id, info, "no result home");
            return;
        };
        // The allocation plan of the changed-string arm (the `char[]` copies'
        // screens); `None` keeps the unchanged arm only.
        let site = if kind == K::Latin1CompareToCI {
            None
        } else {
            let frame = ce::ConcatIrFrame {
                tls_disp: crate::x64::jit_thread_tls_disp(),
                thread_slot_off: self.shadow_thread_slot_off,
                cursor_off: self.tlab_cursor_off,
                end_off: self.tlab_end_off,
                class_id_off: self.concat_class_id_off,
                g1_table: self.g1_barrier_addr,
                region_bounds_addr: self.concat_region_bounds_addr,
            };
            match ce::chars_ir_site(
                Some(layout),
                self.direct_helpers.compact_strings_flag_addr(),
                frame,
            ) {
                Ok(site) => Some(site),
                Err(why) => {
                    self.note_string_prefix_declined(id, info, why);
                    None
                }
            }
        };
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-latin1-case-prefix n{id} {}.{}{} kind={kind:?} allocates={}",
                info.class_name,
                info.method_name,
                info.descriptor,
                site.is_some(),
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        self.note_rcx_written();
        // The `str` the unchanged arm answers (the receiver, or the worker's
        // first argument).
        let str_node = node.inputs[2];
        match kind {
            K::Latin1CompareToCI => {
                // RCX = value, R11 = other: non-null `byte[]`s.
                self.gp_load_value(RCX, node.inputs[2]);
                self.emit_str_test_r64(RCX);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.buf.emit(&[0x80, 0x79, KIND_TAGS, byte_array_tag]); // CMP BYTE [RCX+KIND_TAGS], [B
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                self.gp_load_value(R11, node.inputs[3]);
                self.emit_str_test_r64(R11);
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.buf.emit(&[0x41, 0x80, 0x7B, KIND_TAGS, byte_array_tag]); // CMP BYTE [R11+KIND_TAGS], [B
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                self.emit_latin1_ci_loop(); // RAX = the answer
            }
            _ => {
                // The locale: the worker's third operand, the user site's
                // argument; `toLowerCase()` passes `Locale.getDefault()`.
                let locale = match kind {
                    K::Latin1ToLowerCase => Some(node.inputs[4]),
                    K::LowerLocaleUnchanged => Some(node.inputs[3]),
                    _ => None,
                };
                if let Some(l) = locale {
                    self.gp_load_value(R10, l);
                    self.buf.emit(&[0x4D, 0x85, 0xD2]); // TEST R10, R10
                    decline.push(self.emit_jcc_rel32(0x84)); // JZ: the call's NPE
                }
                if kind == K::Latin1ToLowerCase {
                    // RCX = the `byte[]` the caller proved LATIN1.
                    self.gp_load_value(RCX, node.inputs[3]);
                    self.emit_str_test_r64(RCX);
                    decline.push(self.emit_jcc_rel32(0x84)); // JZ
                    self.buf.emit(&[0x80, 0x79, KIND_TAGS, byte_array_tag]); // CMP BYTE [RCX+KIND_TAGS], [B
                    decline.push(self.emit_jcc_rel32(0x85)); // JNE
                } else {
                    // A layout REPLACEMENT invalidates the baked field offsets.
                    if let Some(p) = self.emit_layout_epoch_guard() {
                        decline.push(p);
                    }
                    // RAX = the receiver: non-null, a String; RCX = value,
                    // EDX = coder (LATIN1 only).
                    self.gp_load_value(RAX, str_node);
                    self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
                    decline.push(self.emit_jcc_rel32(0x84)); // JZ
                    self.emit_str_cmp_class_id(RAX, layout.string_class_id);
                    decline.push(self.emit_jcc_rel32(0x85)); // JNE
                    self.emit_str_value_and_coder(&layout, RAX, RCX, Some(RDX));
                    self.emit_str_test_r64(RCX);
                    decline.push(self.emit_jcc_rel32(0x84)); // JZ
                    self.buf.emit(&[0x85, 0xD2]); // TEST EDX, EDX
                    decline.push(self.emit_jcc_rel32(0x85)); // JNZ: UTF16
                }
                // R11D = len; EDX = the index of the first upper-case byte.
                self.buf.emit(&[0x44, 0x8B, 0x59, 0x08]); // MOV R11D, [RCX+8]
                self.buf.emit(&[0x31, 0xD2]); // XOR EDX, EDX
                let top = self.buf.pos();
                self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
                let unchanged = self.emit_jcc_rel32(0x83); // JAE: no upper-case byte
                self.buf.emit(&[0x44, 0x0F, 0xB6, 0x54, 0x11, 0x10]); // MOVZX R10D, BYTE [RCX+RDX+16]
                self.buf.emit(&[0x41, 0x8D, 0x42, 0xBF]); // LEA EAX, [R10-0x41]
                self.buf.emit(&[0x83, 0xF8, 0x19]); // CMP EAX, 25
                let mut changed = vec![self.emit_jcc_rel32(0x86)]; // JBE: `A-Z`
                self.buf.emit(&[0x41, 0x8D, 0x82, 0x40, 0xFF, 0xFF, 0xFF]); // LEA EAX, [R10-0xC0]
                self.buf.emit(&[0x83, 0xF8, 0x1E]); // CMP EAX, 0x1E
                let not_upper = self.emit_jcc_rel32(0x87); // JA: below 0xC0 or above 0xDE
                self.buf.emit(&[0x41, 0x81, 0xFA, 0xD7, 0x00, 0x00, 0x00]); // CMP R10D, 0xD7
                changed.push(self.emit_jcc_rel32(0x85)); // JNE: `0xC0..=0xDE` minus the sign
                self.patch_rel32_to_here(not_upper);
                self.buf.emit(&[0xFF, 0xC2]); // INC EDX
                self.emit_jmp_back_to(top);
                // The first upper-case byte is at EDX.
                for p in changed {
                    self.patch_rel32_to_here(p);
                }
                if let Some(site) = site.as_ref() {
                    // Every byte from EDX on: none of `I`, `J`, `0xCC`, `0xCD`
                    // (the bytes before it are not upper case, so not these).
                    let sens_top = self.buf.pos();
                    self.buf.emit(&[0x44, 0x39, 0xDA]); // CMP EDX, R11D
                    let clean = self.emit_jcc_rel32(0x83); // JAE: no sensitive byte
                    self.buf.emit(&[0x44, 0x0F, 0xB6, 0x54, 0x11, 0x10]); // MOVZX R10D, BYTE [RCX+RDX+16]
                    self.buf.emit(&[0x41, 0x8D, 0x42, 0xB7]); // LEA EAX, [R10-0x49]
                    self.buf.emit(&[0x83, 0xF8, 0x01]); // CMP EAX, 1
                    decline.push(self.emit_jcc_rel32(0x86)); // JBE: `I` / `J`
                    self.buf.emit(&[0x41, 0x8D, 0x82, 0x34, 0xFF, 0xFF, 0xFF]); // LEA EAX, [R10-0xCC]
                    self.buf.emit(&[0x83, 0xF8, 0x01]); // CMP EAX, 1
                    decline.push(self.emit_jcc_rel32(0x86)); // JBE: `0xCC` / `0xCD`
                    self.buf.emit(&[0xFF, 0xC2]); // INC EDX
                    self.emit_jmp_back_to(sens_top);
                    self.patch_rel32_to_here(clean);
                    // RDX = the array, ECX = its length: the emitter's entry.
                    self.buf.emit(&[0x48, 0x89, 0xCA]); // MOV RDX, RCX
                    self.buf.emit(&[0x44, 0x89, 0xD9]); // MOV ECX, R11D
                    ce::emit_ir_latin1_to_lower_string(&mut self.buf, site, &mut decline);
                    // RAX = the fresh String: on to the shared store.
                    let to_store = self.emit_jmp_rel32();
                    // `return str`.
                    self.patch_rel32_to_here(unchanged);
                    self.gp_load_value(RAX, str_node);
                    self.patch_rel32_to_here(to_store);
                } else {
                    // No allocation plan: a changed string is the call.
                    decline.push(self.emit_jmp_rel32());
                    self.patch_rel32_to_here(unchanged);
                    self.gp_load_value(RAX, str_node);
                }
            }
        }
        self.emit_integer_value_of_result_store(id, slot);
        crate::ir_evidence::note(crate::ir_evidence::Transform::ScalarIntrinsic);
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r20 wave 12, lane qStr (book `jit-r20-nio-proposals-w6-L2.md`,
    /// W6-L2-2; `CRATONVM_JIT_IR_STRING_CHARS_PREFIX`): the three `char[]`
    /// copies the optimizing tier answers inline as a guarded PREFIX of the
    /// `Op::Call`, each with an inline TLAB allocation
    /// (`x64::concat_emit::emit_ir_to_char_array` /
    /// `emit_ir_string_from_chars`, the inline concat's bump, collector arm and
    /// header stores):
    ///
    /// * `String.toCharArray()` -- a fresh `char[length()]`, the LATIN1
    ///   payload inflated or the UTF16 one copied;
    /// * the static `String.valueOf(char[])` / `copyValueOf(char[])` -- a
    ///   fresh String (and its `byte[]`) whose coder is the JDK's
    ///   `COMPACT_STRINGS` + `StringUTF16.compress` answer;
    /// * `new String(char[])` at its `invokespecial` -- the receiver's
    ///   `value` and `coder`, by the same rule.
    ///
    /// Same contract with the `Op::Call` arm as
    /// [`Self::try_emit_ir_string_search_prefix`], with the inline concat's
    /// scratch set (RAX, RCX, RDX, R8-R11, XMM0/XMM1: caller-saved, none an
    /// `IR_LOWER_LS_GPRS` home, all clobbered by the call it fronts). The hit
    /// edge stores the result (none for `<init>`) and jumps to
    /// [`Self::call_prefix_join`]; it makes no call, polls nothing and cannot
    /// throw, so it owes no map and no deopt point. Every decline -- each
    /// listed on the two emitters -- precedes the first store and lands on the
    /// unchanged call, which answers or throws exactly as before.
    fn try_emit_ir_string_chars_prefix(
        &mut self,
        id: NodeId,
        info: &JitInvokeInfo,
        kind: crate::IrStringSearchKind,
        layout: crate::StringFieldLayout,
    ) {
        use crate::x64::concat_emit as ce;
        use crate::IrStringSearchKind as K;
        // `emit_ir_string_from_chars`' receiver register (no module constant).
        const R9: u8 = 9;
        if !kind.admits_invoke_kind(info.invoke_kind)
            || !layout.has_coder
            || layout.string_class_id == 0
        {
            self.note_string_prefix_declined(
                id,
                info,
                &format!(
                    "invoke_kind={} has_coder={} string_class_id={}",
                    info.invoke_kind, layout.has_coder, layout.string_class_id
                ),
            );
            return;
        }
        if crate::x64::narrow_oops_block_inline_fields() {
            self.note_string_prefix_declined(id, info, "narrow oops / armed ZGC barrier");
            return;
        }
        let graph = self.graph;
        let Some(node) = graph.nodes.get(id as usize) else {
            return;
        };
        // [ctrl, mem, receiver-or-array(, array)]: a `char[]` / String result,
        // or void for the constructor.
        let want_ty = if kind == K::CharsInit {
            IrType::Void
        } else {
            IrType::Ref
        };
        if node.inputs.len() != 3 + kind.num_params() || node.ty != want_ty {
            self.note_string_prefix_declined(
                id,
                info,
                &format!("node shape: {} inputs, ty {:?}", node.inputs.len(), node.ty),
            );
            return;
        }
        if node.inputs[2..].iter().any(|&i| self.carry_names(i)) {
            self.note_string_prefix_declined(id, info, "an operand is a live carry");
            return;
        }
        // The result's home, computed without allocating it (see the
        // ArrayList prefix); the constructor has none.
        let slot = if kind == K::CharsInit {
            None
        } else {
            if self.carry_of.get(id as usize).copied().flatten().is_some()
                || self.home_dropped.get(id as usize).copied().unwrap_or(false)
            {
                self.note_string_prefix_declined(id, info, "a carried or dropped result home");
                return;
            }
            match self.planned_slot_off(id) {
                Ok(s) => Some(s),
                Err(_) => {
                    self.note_string_prefix_declined(id, info, "no result home");
                    return;
                }
            }
        };
        let frame = ce::ConcatIrFrame {
            tls_disp: crate::x64::jit_thread_tls_disp(),
            thread_slot_off: self.shadow_thread_slot_off,
            cursor_off: self.tlab_cursor_off,
            end_off: self.tlab_end_off,
            class_id_off: self.concat_class_id_off,
            g1_table: self.g1_barrier_addr,
            region_bounds_addr: self.concat_region_bounds_addr,
        };
        let site = match ce::chars_ir_site(
            Some(layout),
            self.direct_helpers.compact_strings_flag_addr(),
            frame,
        ) {
            Ok(site) => site,
            Err(why) => {
                self.note_string_prefix_declined(id, info, why);
                return;
            }
        };
        // The engagement control (`CRATONVM_DBG_IR_COMPILES` / `CRATONVM_DBG_JITC`).
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] string-chars-prefix n{id} {}.{}{} kind={kind:?} string_class_id={}",
                info.class_name, info.method_name, info.descriptor, layout.string_class_id,
            );
        }
        let mut decline: Vec<usize> = Vec::new();
        // RCX: the epoch guard's fallback form and the field loads write it.
        self.note_rcx_written();
        match kind {
            K::ToCharArray => {
                // A layout REPLACEMENT invalidates the baked field offsets.
                if let Some(p) = self.emit_layout_epoch_guard() {
                    decline.push(p);
                }
                // RAX = receiver; null declines (the call raises the NPE).
                self.gp_load_value(RAX, node.inputs[2]);
                self.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
                decline.push(self.emit_jcc_rel32(0x84)); // JZ
                self.emit_str_cmp_class_id(RAX, layout.string_class_id);
                decline.push(self.emit_jcc_rel32(0x85)); // JNE
                                                         // RDX = value, ECX = coder.
                self.emit_str_value_and_coder(&layout, RAX, RDX, Some(RCX));
                ce::emit_ir_to_char_array(&mut self.buf, &site, &mut decline);
            }
            K::CharsValueOf => {
                self.gp_load_value(RDX, node.inputs[2]);
                ce::emit_ir_string_from_chars(&mut self.buf, &site, &mut decline, false);
            }
            K::CharsInit => {
                self.gp_load_value(R9, node.inputs[2]);
                self.gp_load_value(RDX, node.inputs[3]);
                ce::emit_ir_string_from_chars(&mut self.buf, &site, &mut decline, true);
            }
            // `is_chars_copy` admitted only the three above; nothing emitted.
            _ => return,
        }
        if let Some(slot) = slot {
            self.emit_integer_value_of_result_store(id, slot);
        }
        // A call chain the single-pass backend has no inline form for, lowered
        // as straight-line code: acceptance evidence, as the `getChars` prefix.
        crate::ir_evidence::note(crate::ir_evidence::Transform::ScalarIntrinsic);
        let hit = self.emit_jmp_rel32();
        for p in decline {
            self.patch_rel32_to_here(p);
        }
        self.call_prefix_join = Some(hit);
    }

    /// JIT r20 wave 19, lane zCp (page
    /// `jr20-pstr3-code-point-latin1-static-init-mcs-flip-rows-CLOSED-20261012.md`,
    /// row `R20PIRCodePoint` cp-tochars;
    /// `CRATONVM_JIT_IR_CHARACTER_TO_CHARS_PREFIX`): the static
    /// `Character.toChars(int)` answered inline as a guarded PREFIX of its
