pub(crate) fn ir_osr_remat_static_read_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_OSR_REMAT_STATIC_READ")
}

/// `CRATONVM_JIT_IR_LZCNT_TZCNT`, **default OFF** (opt-in) -- JIT round 19
