/// Process totals for the level-2 machine list, so a corpus run has a number
/// rather than a stream of per-compile lines.
///
/// Read them with [`mir_totals::read`]; the `--dump-jit-stats` style consumers
/// and the corpus probe both go through it. Plain atomics rather than a mutex:
/// this runs inside the compile path, on the compiler thread, and a torn read
/// of a diagnostic counter is not worth a lock.
pub mod mir_totals {
    use std::sync::atomic::{AtomicU64, Ordering::Relaxed};

    static METHODS: AtomicU64 = AtomicU64::new(0);
    static TILES: AtomicU64 = AtomicU64::new(0);
    static MISMATCHES: AtomicU64 = AtomicU64::new(0);
    static SHADOW_TILES: AtomicU64 = AtomicU64::new(0);
    static ARM_BYTES: AtomicU64 = AtomicU64::new(0);
    static ENC_BYTES: AtomicU64 = AtomicU64::new(0);
    static ALLOC_VERIFIED: AtomicU64 = AtomicU64::new(0);
    static ALLOC_VALUES: AtomicU64 = AtomicU64::new(0);
    static ALLOC_UNLOCATED_ROOTS: AtomicU64 = AtomicU64::new(0);
    static ALLOC_VACUOUS: AtomicU64 = AtomicU64::new(0);
    static ALLOC_INDESCRIBABLE: AtomicU64 = AtomicU64::new(0);
    static ALLOC_REJECTED: AtomicU64 = AtomicU64::new(0);

    /// Record one method's [`super::MirAllocVerdict`], keeping the three states
    /// apart.
    ///
    /// Collapsing them is the specific failure this counter set exists to
    /// prevent: a corpus where every method came back `NothingToCover` and one
    /// where every method verified thousands of values are indistinguishable in
    /// a single "ok" tally, and the first proves nothing at all.
    pub(super) fn record_alloc(verdict: super::MirAllocVerdict) {
        match verdict {
            super::MirAllocVerdict::Verified {
                located,
                unlocated_tile_roots,
            } => {
                ALLOC_VERIFIED.fetch_add(1, Relaxed);
                ALLOC_VALUES.fetch_add(located as u64, Relaxed);
                ALLOC_UNLOCATED_ROOTS.fetch_add(unlocated_tile_roots as u64, Relaxed);
            }
            super::MirAllocVerdict::NothingToCover => {
                ALLOC_VACUOUS.fetch_add(1, Relaxed);
            }
            super::MirAllocVerdict::Indescribable(_) => {
                ALLOC_INDESCRIBABLE.fetch_add(1, Relaxed);
            }
        }
    }

    /// One method whose allocation `verify_allocation` REJECTED. A compiler
    /// bug, and non-zero is a stop-and-look number, not a ratio to watch.
    pub(super) fn record_alloc_rejected() {
        ALLOC_REJECTED.fetch_add(1, Relaxed);
    }

    /// `(verified, values, nothing_to_cover, indescribable, rejected)` — the
    /// increment-2 allocation verdicts since process start.
    pub fn read_alloc() -> (u64, u64, u64, u64, u64) {
        (
            ALLOC_VERIFIED.load(Relaxed),
            ALLOC_VALUES.load(Relaxed),
            ALLOC_VACUOUS.load(Relaxed),
            ALLOC_INDESCRIBABLE.load(Relaxed),
            ALLOC_REJECTED.load(Relaxed),
        )
    }

    /// Tile roots the allocation could give no home word, summed over every
    /// verified method.
    ///
    /// Increment 3's sizing, taken from real compiles instead of from a
    /// synthetic shape count: every one of these is a value that must live in a
    /// register because there is no memory for it to live in.
    pub fn read_unlocated_tile_roots() -> u64 {
        ALLOC_UNLOCATED_ROOTS.load(Relaxed)
    }

    pub(super) fn record(
        tiles: usize,
        mismatches: usize,
        shadow_tiles: usize,
        arm_bytes: usize,
        enc_bytes: usize,
    ) {
        METHODS.fetch_add(1, Relaxed);
        TILES.fetch_add(tiles as u64, Relaxed);
        MISMATCHES.fetch_add(mismatches as u64, Relaxed);
        SHADOW_TILES.fetch_add(shadow_tiles as u64, Relaxed);
        ARM_BYTES.fetch_add(arm_bytes as u64, Relaxed);
        ENC_BYTES.fetch_add(enc_bytes as u64, Relaxed);
    }

    /// `(methods, tiles, mismatches)` since process start.
    pub fn read() -> (u64, u64, u64) {
        (
            METHODS.load(Relaxed),
            TILES.load(Relaxed),
            MISMATCHES.load(Relaxed),
        )
    }

    /// `(shadow_tiles, arm_bytes, encoder_bytes)` — verify mode's sizing of the
    /// increment that would emit the rules byte equality cannot cover.
    ///
    /// `arm_bytes - encoder_bytes` is what those tiles would save, over exactly
    /// the nodes they cover, on this workload. A zero `shadow_tiles` means the
    /// question does not arise; it does not mean the saving is zero.
    pub fn read_shadow() -> (u64, u64, u64) {
        (
            SHADOW_TILES.load(Relaxed),
            ARM_BYTES.load(Relaxed),
            ENC_BYTES.load(Relaxed),
        )
    }

    /// Zero the accumulator. Tests only — hold [`TEST_LOCK`] across the reset
    /// AND the read, or two tests reading one global see each other's counts.
    #[cfg(test)]
    pub fn reset() {
        for c in [
            &METHODS,
            &TILES,
            &MISMATCHES,
            &SHADOW_TILES,
            &ARM_BYTES,
            &ENC_BYTES,
            &ALLOC_VERIFIED,
            &ALLOC_VALUES,
            &ALLOC_UNLOCATED_ROOTS,
            &ALLOC_VACUOUS,
            &ALLOC_INDESCRIBABLE,
            &ALLOC_REJECTED,
        ] {
            c.store(0, Relaxed);
        }
    }

    /// Serialises the tests that read the counters above. Its own lock, not
    /// `isel::SHADOW_TEST_LOCK`: these are different globals, and sharing one
    /// mutex between two unrelated accumulators is how a later test ends up
    /// holding the wrong one.
    #[cfg(test)]
    pub static TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
}

/// May the level-2 encoder answer for node `id`'s lowering with this tile?
///
/// Three conditions, and the third is the one that is not obvious. The caller
/// skips **every** node a tile covers, so a tile that absorbed a node the
/// encoder does not actually fold leaves that node computed nowhere — the same
/// failure `BlockSelection::covers` exists to make unrepresentable, one level
/// further down. `Rule::AluReg` never absorbs, so today this clause is
/// insurance rather than a live filter; a rule added to the set below without a
/// fold is exactly what it is insurance against.
fn mir_tile_is_emittable(tile: &crate::x64::isel::Tile, id: NodeId) -> bool {
    use crate::x64::isel::Rule;

    tile.root == id && tile.rule == Rule::AluReg && tile.covered.as_slice() == [id]
}

/// Build the level-2 machine list for one method, or refuse.
///
/// `None` means "do not compile this method through the machine level" and is
/// returned for exactly one reason: a block the selector did not cover. That is
/// the invariant `BlockSelection::covers` exists for — a node covered zero times
/// is a dropped instruction — and increment 0 measured it holding on all 1 911
/// blocks of a real Spring Boot workload, so a violation here is a compiler bug
/// and not a shape to work around.
///
/// `SelectOptions::default()` for the same reason `shadow_select_method` uses
/// it: `require_encodable: true`, and `fold_loads: false` because the fold's
/// address half is still `AddrSource::Opaque`.
fn build_mir_plan(graph: &Graph, schedule: &Schedule) -> Option<MirPlan> {
    use crate::x64::isel::{select_block, SelectOptions};

    // `frame_homed: true` is the one departure from `shadow_select_method`'s
    // options, and it is a statement about the consumer rather than a tuning
    // knob: `encode_tile_frame_homed` puts every value in its frame word, so
    // the two-address copy the cost model would otherwise charge the ALU form
    // does not exist. Left `false` it makes `Rule::Lea` outbid `Rule::AluReg`
    // on `a + b` whenever `a` is live afterwards, and the `LEA` that wins is a
    // byte longer than the `ADD` it replaced.
    let opts = SelectOptions {
        frame_homed: true,
        ..SelectOptions::default()
    };
    let mut blocks = Vec::with_capacity(schedule.blocks.len());
    let mut tile_of: Vec<Option<(u32, u32)>> = vec![None; graph.nodes.len()];
    for (bi, block) in schedule.blocks.iter().enumerate() {
        let sel = select_block(graph, &block.nodes, block.terminator, &opts);
        if !sel.covers(&block.nodes) {
            return None;
        }
        let bi = u32::try_from(bi).ok()?;
        for (ti, tile) in sel.tiles.iter().enumerate() {
            let ti = u32::try_from(ti).ok()?;
            if let Some(cell) = tile_of.get_mut(tile.root as usize) {
                // Two tiles rooted at one node would mean the node is computed
                // twice; `covers` already refused that, so this is belt and
                // braces on the index rather than a second policy.
                if cell.is_some() {
                    return None;
                }
                *cell = Some((bi, ti));
            }
        }
        blocks.push(sel);
    }
    Some(MirPlan { blocks, tile_of })
}

/// What [`verify_mir_allocation`] concluded — the three-valued shape the
/// design doc requires, not an `Option`.
///
/// `emit_safepoint_map` already refuses to conflate "nothing to cover" with
/// "could not describe it" (an oop-free safepoint publishes
/// `moving_young_coverage_complete: true`; an indescribable slot publishes
/// `false` and diverts the cycle). A level-2 form owes the same distinction,
/// because the two have opposite consequences: one is a healthy compile, the
/// other is a compile whose allocation nothing proved.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MirAllocVerdict {
    /// An allocation was built over the tile list and `verify_allocation`
    /// accepted it.
    Verified {
        /// Values the allocation gives a location to.
        located: usize,
        /// Tiles whose root the allocation gives NO location.
        ///
        /// Legal, and worth counting rather than refusing: `plan_slots` gives
        /// no home word to a value nothing reads from memory — the last value
        /// in `(a + b) * a` is returned straight out of RAX — while
        /// `select_block` still roots a tile at it, because a tile is about
        /// *computing* the value, not about storing it. The encoder already
        /// declines such a tile (`frame_destination(dst)?`) and the per-opcode
        /// arm emits it instead.
        ///
        /// It is a number rather than a silence because it is exactly the
        /// gap increment 3 closes: a value with no home is a value that MUST
        /// stay in a register, so this count is the size of the register file's
        /// first real customer.
        unlocated_tile_roots: usize,
    },
    /// The tile list defines no value that needs a location. Vacuous, and
    /// counted separately so a run of these cannot be read as coverage.
    NothingToCover,
    /// The allocation could not be *described*, before any verifier ran: the
    /// liveness model did not converge, or it disagrees with `plan_slots` about
    /// which values want a location.
    ///
    /// Not a failure. `plan_register_residency` treats exactly the same
    /// disagreement as "decline to promote and keep the colourer's answer",
    /// and the reasoning carries: the colourer's layout is correct on its own
    /// terms and is the one the frame was built from. What this must not do is
    /// report itself as `Verified`.
    Indescribable(&'static str),
}

/// Build an allocation over the machine list and put it through the **existing**
/// [`crate::regalloc::verify_allocation`].
///
/// This is increment 2 of
/// `docs/feature-designs/jit-machine-level-and-instruction-selection.md`: "an
/// allocation over it, verified by `verify_allocation`". Deliberately not a new
/// verifier — the value of the increment is that the level-2 artifact is
/// checkable by the allocator's *own* checker, and a second checker written for
/// it would be a second model to keep in step.
///
/// # What the allocation says
///
/// Every value lives in its frame home for its entire live range, with an empty
/// register file. That is not a placeholder: it is exactly what
/// [`Lowerer::encode_tile_frame_homed`] emits, so the allocation being verified
/// is the one the encoder actually implements. The register file is empty
/// rather than XMM-shaped because the MIR encoder holds nothing in a long-lived
/// register — RAX is reloaded per tile.
///
/// # What that buys, given nothing is in a register
///
/// The register rules go quiet; four others do not, and they are the ones that
/// bite a memory-only backend:
///
///   * **the timeline covers the live range** — a value the tile list reads
///     after its recorded death, or defines without a location, is refused
///     here instead of `?`-ing out silently inside the encoder;
///   * **no two simultaneously live values share a home word** — checked
///     against `build_live_model`'s ranges, which are computed *independently*
///     of `plan_slots`'. Two implementations of one liveness model drifting
///     apart is precisely how a backend comes to alias two live values, and
///     the tile list is a third consumer of that model;
///   * **home pools stay separated** — a word holding a `Ref` for one value and
///     a pinned primitive for another is the shape a moving collector
///     misreads;
///   * **no reference is register-resident at a safepoint** — vacuous today
///     and the whole point tomorrow: increment 3 swaps the empty `RegFile` for
///     a real one at this exact call site, and this check is what makes that
///     swap reviewable rather than an act of faith.
///
/// # Failure policy
///
/// `Err` only from `verify_allocation`, and only that. A model disagreement is
/// [`MirAllocVerdict::Indescribable`], not an error, for the reason
/// `plan_register_residency` gives. The caller decides what an `Err` costs:
/// `MirMode::Verify` changes no emitted byte and records it, `MirMode::Emit`
/// refuses the compile, because emitting against an allocation nothing proved
/// is the trade that has produced silent heap corruption in this VM before.
fn verify_mir_allocation(
    graph: &Graph,
    schedule: &Schedule,
    plan: &SlotPlan,
    mir: &MirPlan,
) -> CompileResult<MirAllocVerdict> {
    use crate::regalloc::{
        build_live_model, verify_allocation, Allocation, RegFile, RegSpec, Segment,
    };

    let live = build_live_model(graph, schedule);
    if !live.converged {
        return Ok(MirAllocVerdict::Indescribable("liveness did not converge"));
    }
    // The same agreement check `plan_register_residency` runs, and for the same
    // reason: `build_live_model` re-implements `plan_slots`' position model
    // rather than calling it, so the two are only interchangeable while they
    // agree. Checked before either is used.
    let expected_positions: usize = schedule
        .blocks
        .iter()
        .map(|b| b.nodes.len() + usize::from(b.terminator.is_some()) + 1)
        .sum();
    if live.total_positions != expected_positions {
        return Ok(MirAllocVerdict::Indescribable("position models disagree"));
    }
    if live.wants_loc.len() != plan.node_color.len()
        || live
            .wants_loc
            .iter()
            .zip(plan.node_color.iter())
            .any(|(wants, color)| *wants != color.is_some())
    {
        return Ok(MirAllocVerdict::Indescribable(
            "liveness and the colourer disagree about which values want a location",
        ));
    }

    let n = graph.nodes.len();
    let mut segments: Vec<Vec<Segment>> = vec![Vec::new(); n];
    let mut located = 0usize;
    for id in 0..n {
        if !live.wants_loc.get(id).copied().unwrap_or(false) {
            continue;
        }
        let Some(range) = live.range.get(id).copied().flatten() else {
            // `wants_loc` without a range is the model contradicting itself.
            // Describing it would mean inventing a range, so say so instead.
            return Ok(MirAllocVerdict::Indescribable(
                "a value wants a location but has no live range",
            ));
        };
        segments[id].push(Segment { range, reg: None });
        located += 1;
    }
    if located == 0 {
        return Ok(MirAllocVerdict::NothingToCover);
    }

    // How many tiles the allocation cannot back. Counted, not refused — see
    // `MirAllocVerdict::Verified::unlocated_tile_roots` for why a tile rooted
    // at a homeless value is the normal case rather than a defect.
    let unlocated_tile_roots = mir
        .tile_of
        .iter()
        .enumerate()
        .filter(|(id, cell)| cell.is_some() && segments.get(*id).is_none_or(|s| s.is_empty()))
        .count();

    let alloc = Allocation {
        segments,
        // `Allocation::stack_slot`'s own contract: "a drop-in replacement for
        // `ir_lower`'s `SlotPlan::node_color` — same numbering, same
        // Ref/Prim/pinned pool separation". Passing the colourer's answer
        // rather than a re-derived one is what makes the home-aliasing check
        // above a check of the *frame the encoder addresses*, not of a
        // parallel invention.
        stack_slot: plan.node_color.clone(),
        stack_slots: plan.slots,
        spills: 0,
        reloads: 0,
        remats: 0,
        reg_moves: 0,
        splits: 0,
        promoted: 0,
        events: Vec::new(),
        peak_live: live.peak_live,
    };
    let empty_file = RegFile::from_specs(std::iter::empty::<RegSpec>());
    let model = ir_lower_machine_model(graph, schedule, &live, empty_file);
    verify_allocation(graph, &live, &model, &alloc)?;
    Ok(MirAllocVerdict::Verified {
        located,
        unlocated_tile_roots,
    })
}

/// Does a register for `id` pay for itself, counting loop frequency?
///
/// The publish is one memory→register load at the definition; each read it
/// replaces is one memory→register load at its own site. So the trade is
/// `uses_frequency >= 2 × definition_frequency`, and the static `use_count >= 2`
/// is that same test with every frequency pinned to 1.
///
/// `live.weight[id]` is already the loop-frequency-weighted use count. The
/// definition's frequency is derived from `live.loop_depth` and `live.span`,
/// both public, using the same `LOOP_WEIGHT_PER_DEPTH` model — so the two sides
/// of the comparison come from one model rather than two.
///
/// Falls back to the static rule whenever the loop model cannot place the
/// definition, which keeps a graph the scheduler left unusual on the old
/// behaviour rather than on a guess.
fn ir_residency_pays_here(
    live: &crate::regalloc::LiveModel,
    schedule: &Schedule,
    id: usize,
    static_uses: u32,
) -> bool {
    if !ir_residency_loop_weight_enabled() {
        return static_uses >= 2;
    }
    let Some(def_pos) = live.pos_of.get(id).copied().flatten() else {
        return static_uses >= 2;
    };
    // Which block holds the definition? `span[b]` is that block's
    // (first position, outgoing-edge position).
    let mut def_depth: Option<u32> = None;
    for b in 0..schedule.blocks.len() {
        if let Some(&(lo, hi)) = live.span.get(b) {
            if lo <= def_pos && def_pos <= hi {
                def_depth = live.loop_depth.get(b).copied();
                break;
            }
        }
    }
    let Some(depth) = def_depth else {
        return static_uses >= 2;
    };
    let def_freq = u64::from(
        crate::regalloc::LOOP_WEIGHT_PER_DEPTH
            .checked_pow(depth)
            .unwrap_or(crate::regalloc::MAX_LOOP_DEPTH_WEIGHT)
            .min(crate::regalloc::MAX_LOOP_DEPTH_WEIGHT),
    );
    let uses_freq = live.weight.get(id).copied().unwrap_or(0);
    uses_freq >= def_freq.saturating_mul(2)
}

/// Weigh the residency trade by loop frequency instead of a static use count —
/// **default OFF**, opt in with `CRATONVM_JIT_IR_LS_LOOP_WEIGHT=1`.
///
/// Off is the static `use_count >= 2` this file has always used.
fn ir_residency_loop_weight_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LS_LOOP_WEIGHT"))
}

/// Give every LOOP-CARRIED value a register of its own before the transients
/// compete for one -- **default ON** since 2026-09-05;
/// `CRATONVM_JIT_IR_RESERVE_CARRIED=0` is the kill switch.
///
/// The census said the residency file accepts ONE of the nineteen values the
/// scan promotes on a loop kernel, and that two of the four loop-carried values
/// are refused as SPLIT. With four carried values and five registers nothing
/// needs splitting; the scan splits them only because it allocates them in
/// competition with eleven transients. A better spill heuristic moves one value
/// (`ls_carry_relief`); this moves the set, which is what
/// `JIT_OPTIMIZATION.md`'s "the live set has to move as a group, or not at all"
/// has meant since the four zeros.
fn ir_reserve_carried_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        // 2026-09-05: DEFAULT ON. `=0` is the kill switch — which is why
        // this reads the VALUE now rather than only asking whether the
        // variable is present.
        // `runtime_flag_default_on` (round 9): `off`/`no` are kill words
        // too, matching every other default-ON switch in this file.
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RESERVE_CARRIED")
    })
}

/// Copy a loop-live int/long PARAMETER into a callee-saved register at entry —
/// **default OFF**, opt in with `CRATONVM_JIT_IR_PARAM_COPY=1`.
///
/// The optimizing tier cannot promote an entry parameter at all: they are
/// pinned to their incoming ABI registers, which are caller-saved and outside
/// this file, and the allocator skips a pinned value. The baseline tier copies
/// them into callee-saved registers in its prologue and reads them from there;
/// this is that copy.
///
/// Off is exactly the previous emission: the parameter reaches every use
/// through its frame slot.
fn ir_param_prologue_copy_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_PARAM_COPY"))
}

/// An `int`/`long` parameter's home is its prologue word, not a copy of it
/// (`Lowerer::alias_param_home`) -- **default ON** since round 11 wave 14;
/// `CRATONVM_JIT_IR_PARAM_HOME_ALIAS=0` is the kill switch and restores the
/// copy. Read live (a handful of reads per compile, one per parameter node),
/// so an in-process A/B can exercise both arms.
fn ir_param_home_alias_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_PARAM_HOME_ALIAS")
}

/// Seed each block's null proofs with the receiver — **default ON since round
/// 16**; `CRATONVM_JIT_IR_THIS_NONNULL=0` (or `false`/`off`/`no`) is the kill
/// switch. Round 16 measured it as a bundle with
/// `CRATONVM_JIT_IR_FIELD_STORE_FORWARD` and
/// `CRATONVM_JIT_IR_STORE_NULL_CHECK_CSE` (whose store null checks use the
/// seed): SyncM p 14→12 ns, alloc kernel -13 %, in two interleaved campaigns.
/// The history below is why it was off until then.
///
/// # It was off because it measured SLOWER, which nobody expected (2026-09-03)
///
/// It is correct and it engages (`seeded=9 elided=2 emitted=0` against
/// `0/0/2` with it off, same answer). On the loop it was built for — the one
/// the 2026-09-03 tier comparison found inverted — it is **~20% slower with
/// the check removed than with it emitted**: medians 1.78/1.93 on against
/// 1.49/1.61 off, two replicate pairs, within-config spread 8%, same direction
/// both times.
///
/// **The cost is not compile time.** At `reps=1`, where the loop barely runs,
/// the two arms are 0.19 against 0.18 — so the per-block seed scan is ~0.01s
/// and the 0.3s is in the emitted code.
///
/// Removing two instructions cannot make a loop 20% slower on its own, so what
/// this really says is that the body is dominated by something layout- or
/// branch-structure-sensitive, and deleting a never-taken forward `JZ` moved
/// it. That is a lead worth pulling for the residual tier inversion itself,
/// and it is the reason this switch stays available rather than being deleted:
/// it is the smallest known perturbation that moves that loop by 20%.
///
/// If nobody finds the cause, withdraw it.
///
/// The optimizing-tier half of `CRATONVM_JIT_THIS_NONNULL`, which seeds the
/// single-pass backend's null-check dataflow. Separate switch because the two
/// tiers reach the fact by different routes — a bytecode dataflow there, the
/// graph's `receiver_param` here — and a single flag would make a bisect
/// unable to say which one moved.
///
/// Off restores the previous emission exactly: a `TEST`/`JZ` at every
/// `getfield` whose receiver the per-block CSE has not already proven.
///
/// `pub(crate)` since round 17 wave 2 (lane monitor2): `ir_optimize`'s loop
/// block coarsening admits a `synchronized (this.lock)` re-read only when this
/// seed drops its null check in every block.
pub(crate) fn ir_this_nonnull_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_THIS_NONNULL")
    })
}

/// Run the linear-scan allocator and use its result as a register read cache.
/// **Default ON** since 2026-09-02; `CRATONVM_JIT_IR_LINEAR_SCAN=0` opts out.
///
/// # What this file gained, and how the default moved
///
/// It shipped OFF while the file was XMM-only, and while it was XMM-only that
/// was the right default: the wiring's own comment said *"this wiring is still
/// FP-only. An `int` loop counter gets nothing out of it"*, so turning it on
/// bought two callee-saved XMM registers on Windows and nothing anywhere else.
///
/// [`IR_LOWER_LS_GPRS`] closes that half. It is the answer to a measured
/// inversion: this backend read every `int` value out of a frame word while the
/// single-pass backend it supersedes colours Java locals into callee-saved
/// GPRs, and on five one-line kernels — same binary, `CRATONVM_JIT_IR_LONG=0`
/// to route them to single-pass — the optimizing tier came out **1.25x to 1.9x
/// slower** on Windows and **~3.2x** slower on a quieter Linux host, on every
/// kernel whose cost was not already dominated by an out-of-line helper call.
///
/// **The default stayed off at first because the fix did not reach those
/// kernels, and the census said so rather than a guess.** With
/// `CRATONVM_DBG_IR_LINEAR_SCAN=1`, at that time:
///
/// * on `BinTrees.itemCheck` the file works —
///   `resident=7 (fp=0 gp=7) demoted=0`, `phi=0`, with 13 candidates lost to
///   splits and 2 to type;
/// * on all five probe kernels it never runs at all: `refused: liveness and
///   colourer disagree about which values want a home`, 5 of 5.
///
/// That refusal is a PRE-EXISTING gate, not something the GP file introduced —
/// `regalloc::ir_op_defines_value` and `ir_lower`'s `op_defines_result_slot`
/// are two enumerations of one question (the second and third of the three
/// `the_three_ir_op_enumerations` names), and any disagreement declines the
/// whole method. It was declining the XMM cache the same way and nobody could
/// see it, because the flag printed only on success. The refusal now names the
/// op, so reconciling the two is a one-line fix with a test rather than a
/// search through fifty variants.
///
/// **Both prerequisites landed on 2026-09-02 and the default moved with them.**
/// The enumeration disagreement was the one `ir_op_defines_value` had over
/// `Op::ArrayLength` and `Op::NewArray` — it declined the file on every method
/// containing an `arraylength`, which is every counted `for` loop over an
/// array. Phis are admitted separately (`ir_phi_residency_enabled`). The
/// regression suite is green with the file on (88/88).
///
/// **What the flip did NOT settle** is the tiering inversion this paragraph
/// was written about. Re-measured 2026-09-03 on a RELEASE binary, arms
/// interleaved, with a second arm of each configuration to establish the noise
/// floor: four of five loop shapes are indistinguishable between tiers, and the
/// field-read loop is still **~1.65x slower at the optimizing tier**
/// (C1 0.86/0.83 against C2 1.39/1.41, fifteen reps, controls agreeing to 3.5%
/// and 1.4%). So this file closed the part of the gap it was built for and the
/// remaining case is elsewhere — see `docs/JIT_OPTIMIZATION.md`.
///
/// **Retaken 2026-09-10** on `probes/FieldLoop.java` `sum`, after seven more
/// register flags went default-ON: **1.594x** (503 ms against 812 ms over a
/// 2.6% floor). Still there, and widening the GP file does not close it
/// either — see [`ir_gp_wide_enabled`].
///
/// Off is exactly the pre-change emission: no register is handed out, no save
/// area is reserved, every read goes to its home word.
///
/// Declared in `types/src/flag_groups.rs` as `jit/ir-linear-scan`, so `-XX:`
/// options and `flags::with_thread_overrides` reach it.
fn linear_scan_enabled() -> bool {
    #[cfg(test)]
    {
        if let Some(forced) = ls_forced() {
            return forced;
        }
    }
    // 2026-09-02: DEFAULT ON. The enumeration disagreement that declined the
    // file on every array-touching method was reconciled the same day, phis
    // are admitted (`ir_phi_residency_enabled`), and the census below says
    // where the file engages. `=0` is the kill switch.
    !matches!(
        cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_LINEAR_SCAN").as_deref(),
        Ok("0") | Ok("false") | Ok("off") | Ok("no")
    )
}

/// `CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD=1` (opt-in; interpreter round i2
/// wave 64, lane L2; `i63-L2-proposal-the-lowering-refuses-a-token-slot-operand-read`):
/// refuse a compile in which a lowering arm reads a machine value through an
/// input it names ONLY in a memory-token slot (`ir::is_memory_token_slot`).
///
/// `CRATONVM_JIT_IR_LS_TOKEN_EDGES_NOT_USES` (JIT round 17), the slot-plan
/// switch `CRATONVM_JIT_IR_SLOTS_TOKEN_EDGES_NOT_USES` (wave 64) and the
/// wave-58 OSR excuse all assume no arm does: a token is an ordering edge, the
/// arm never `slot_of`s it, never asks for its register. This turns the
/// assumption into a checked one -- see [`Lowerer::token_read_check`] for the
/// funnels and what is exempt. Compile-time only; costs nothing at run time,
/// and nothing at compile time while off (the per-node set stays empty).
///
/// Implied by the slot-plan switch: a shortened home some arm still reads is
/// the wrong-code case this exists to refuse.
fn ir_lower_token_read_guard_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD")
        || crate::regalloc::slots_token_edges_not_uses_enabled()
        || (cfg!(debug_assertions) && ir_lower_token_read_guard_debug_default_enabled())
}

/// `CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD_DEBUG_DEFAULT=1` (opt-in; JIT round
/// 19 proposal wave 11, lane lv11, TOK10-2): in a build with
/// `debug_assertions`, the token-read guard is on unless
/// `CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD` says `0` (or another off word).
/// No effect in a release build. Flipping this switch default ON is the
/// TOK10-2 decision, taken on TOK10-1's count (the strict lib-test run) being
/// zero; a debug-only refusal changes which methods a debug build compiles,
/// which is the cost the flip weighs.
fn ir_lower_token_read_guard_debug_default_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD_DEBUG_DEFAULT")
        && !matches!(
            cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD")
                .ok()
                .map(|v| cratonvm_types::flags::value_is_off(&v)),
            Some(true)
        )
}

/// TOK10-1 (JIT round 19 proposal wave 11, lane lv11): the strict test mode
/// of the token-read guard, `CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD=strict`
/// (any `strict` spelling; still an "on" value for the guard itself). Test
/// builds only; see [`Lowerer::token_read_check`].
#[cfg(test)]
fn token_read_guard_strict() -> bool {
    cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_LOWER_TOKEN_READ_GUARD")
        .is_ok_and(|v| v.trim().eq_ignore_ascii_case("strict"))
}

#[cfg(test)]
thread_local! {
    /// Test-only override for [`linear_scan_enabled`], so a unit test never
    /// depends on the process environment or on whether the flag has been
    /// declared yet. Thread-local, so parallel tests cannot see each other's
    /// setting.
    static LS_FORCE: std::cell::Cell<Option<bool>> = const { std::cell::Cell::new(None) };
}

#[cfg(test)]
fn ls_forced() -> Option<bool> {
    LS_FORCE.with(|c| c.get())
}

/// Test-only RAII override of [`linear_scan_enabled`] on this thread.
#[cfg(test)]
struct LsForce;

#[cfg(test)]
impl LsForce {
    fn on() -> LsForce {
        LS_FORCE.with(|c| c.set(Some(true)));
        LsForce
    }

    /// Force the cache OFF for the duration.
    ///
    /// Needed by the level-2 tests: residency and the selector are mutually
    /// exclusive in production (see `lower_inner_with_array_list`), so a test that
    /// compares a MIR-mode body against a no-mode body is otherwise comparing
    /// two different backends and not the selector at all.
    fn off() -> LsForce {
        LS_FORCE.with(|c| c.set(Some(false)));
        LsForce
    }
}

#[cfg(test)]
impl Drop for LsForce {
    fn drop(&mut self) {
        LS_FORCE.with(|c| c.set(None));
    }
}

/// One location transition the emission must materialise for a value the
/// linear scan SPLIT.
///
/// The machine-level form of a `regalloc::SpillEvent`, narrowed to the four
/// shapes this backend can emit between two nodes without a scratch register.
/// `gp` picks the bank; a node's type picks its bank once and for all, so the
/// flag is carried rather than re-derived at every emission site.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LsTransition {
    /// `reg ← [home(node)]`. A `SpillKind::Load`, and also what a `Move` and a
    /// non-integer `Remat` degrade to.
    Load { node: NodeId, reg: u8, gp: bool },
    /// `reg ← imm`. A `SpillKind::Remat` of an `Op::Const`: no memory access,
    /// which is the entire point of the kind.
    RematConst { node: NodeId, reg: u8, value: i64 },
    /// `to ← from`. A `SpillKind::Move`, already sequentialised against every
    /// other move at this position by `regalloc::resolve_parallel_copy`.
    Move {
        node: NodeId,
        from: u8,
        to: u8,
        gp: bool,
    },
    /// `node`'s value is in its home word from here on. Emits nothing; see
    /// [`Lowerer::ls_drop_residency`].
    Drop { node: NodeId, gp: bool },
}

impl LsTransition {
    /// The value this transition is about.
    fn node(self) -> NodeId {
        match self {
            LsTransition::Load { node, .. }
            | LsTransition::RematConst { node, .. }
            | LsTransition::Move { node, .. }
            | LsTransition::Drop { node, .. } => node,
        }
    }

    /// `(register, is_gp)` this transition publishes into, if it publishes.
    ///
    /// `None` for a [`LsTransition::Drop`], which takes a register away rather
    /// than filling one. Read by `set_residency` to build the save-set
    /// snapshot, so a transition kind added without an arm here would leave a
    /// register written by the body and not saved by the prologue — the
    /// exhaustive match is what makes that a compile error.
    fn destination(self) -> Option<(u8, bool)> {
        match self {
            LsTransition::Load { reg, gp, .. } => Some((reg, gp)),
            // A remat is integer-only; see `ls_split_transitions`.
            LsTransition::RematConst { reg, .. } => Some((reg, true)),
            LsTransition::Move { to, gp, .. } => Some((to, gp)),
            LsTransition::Drop { .. } => None,
        }
    }
}

/// Where every SPLIT value is, position by position, and what to emit at each
/// transition.
///
/// # Why this exists
///
/// `plan_register_residency` used to answer one question per value — "does it
/// hold one register over its entire live range?" — and decline everything
/// else. That threw away the allocator's whole answer: a value given a register
/// everywhere except across one call came back with no register at all and paid
/// a home store plus a reload at *every* use, exactly as it did before the
/// allocator existed. `Allocation::events`, `SpillKind::Remat`, `reg_moves`,
/// `splits` and the eviction cost model that produces them had no reader
/// outside `verify_allocation` and the tests. See `NOTES-regalloc.md` §1.
///
/// This is the reader. Empty unless [`ir_ls_splits_enabled`].
///
/// # What a managed value gives up
///
/// Three things, and each is a refusal rather than a hope:
///
/// * **Its home word stays.** `set_residency` withholds `home_dropped` from
///   every managed value, because the transitions LOAD from that word.
/// * **No deopt frame names its register.** `set_residency` poisons the
///   exclusive-ownership count for every register a managed value visits, so
///   `register_frame_value` answers `None` — a frame state says "this value is
///   in RBX" with no position attached, and a split value is in RBX only
///   sometimes.
/// * **Every transition sits at a NODE position.** Not at a terminator, not at
///   an outgoing edge. That is what keeps every publish inside `lower_block`'s
///   per-node invalidation audit, which is the whole of the argument that a
///   `Ref` in a register cannot outlive a point where a collector ran.
#[derive(Clone, Debug, Default)]
struct LsSplitPlan {
    /// `at[pos]` = what to materialise immediately before the node at linear
    /// position `pos`. Sized to the whole position space; empty nearly
    /// everywhere.
    at: Vec<Vec<LsTransition>>,
    /// `block_start[b]` = block `b`'s first linear position.
    block_start: Vec<usize>,
    /// `managed[id]` = this value's residency is position-driven.
    managed: Vec<bool>,
    /// How many values that is, and how many transitions they cost.
    values: usize,
    transitions: usize,
    /// The CFG-edge resolution copies for managed values the split timeline
    /// leaves in the wrong place on some non-fall-through edge. Empty unless
    /// [`ir_ls_edge_resolution_enabled`]; see [`LsEdgeCopies`].
    edges: Vec<LsEdgeCopies>,
}

/// The edge-resolution copies one CFG edge owes (round 9 wave 6, lane
/// irlower6; `linear-scan-split-timeline-has-no-edge-resolution-20260918.md`).
///
/// `copies[i] = (node, reg, gp)`: before control reaches `succ` along
/// `pred -> succ`, `reg` (in the GP bank when `gp`) must hold `node`, because
/// the code of `succ` was emitted against the LAYOUT predecessor's state, in
/// which it does. The source is always the value's home word, never a
/// register, and that is a choice rather than a shortcut:
///
/// * a managed value's home is never dropped and is written at the definition,
///   which dominates every block the value is live into, so the word is
///   always right on this edge;
/// * the copies then read no register at all, so no order among them and no
///   order against the edge's phi copies can make one read a register another
///   has already overwritten -- the whole of the parallel-copy hazard is gone,
///   and no scratch is needed for a cycle;
/// * the one remaining interaction, a destination register one of the edge's
///   phis is published into, is refused by the planner (the allocator's
///   `held_by_other` test at the target's first position) and checked again at
///   emission (`Lowerer::ls_emit_edge_copies`).
///
/// The price is one load per repaired value per edge execution, on a path that
/// used to have no register for that value at all.
#[derive(Clone, Debug, Default)]
struct LsEdgeCopies {
    pred: usize,
    succ: usize,
    copies: Vec<(NodeId, u8, bool)>,
}

/// `CRATONVM_JIT_IR_LS_EDGE_RESOLUTION=1` -- **default OFF**, and inert unless
/// `CRATONVM_JIT_IR_LS_SPLITS` is on as well (round 9 wave 6).
///
/// Off, a split value the allocator leaves in the wrong place on some CFG edge
/// is refused split residency (`regalloc::split_edge_conflicts`, the wave-1
/// gate). On, such a value is admitted when `regalloc::split_edge_resolution`
/// can repair every one of its edges and every such edge leaves a block whose
/// lowering has an edge-specific copy site (`ls_edge_copy_site_exists`); the
/// repair is emitted by `Lowerer::ls_emit_edge_copies`.
///
/// Read uncached, like `ir_ls_splits_enabled`, because it is asked once per
/// compile and the tests flip it per case.
fn ir_ls_edge_resolution_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LS_EDGE_RESOLUTION")
}

/// Does lowering block `pred` emit a copy site that runs on exactly one
/// outgoing edge, for EVERY outgoing edge -- the place `emit_phi_copies` (and
/// with it `Lowerer::ls_emit_edge_copies`) runs?
///
/// Two terminator shapes do: no terminator at all (`lower_block`'s goto path,
/// one successor, copies after the back-edge poll), and `Op::If`, all of whose
/// arms put an edge's copies on straight-line code of that edge alone once
/// `edge_has_phi_copies` answers `true` for it (which it does for an edge
/// carrying resolution copies). Everything else -- a switch above all, which
/// latches a bailout on any edge with copies -- is refused, and the value that
/// would need a copy there keeps the wave-1 refusal.
///
/// A prediction, and checked: `lower_inner_attempt` refuses the compile if
/// an edge's copies were never emitted.
fn ls_edge_copy_site_exists(graph: &Graph, schedule: &Schedule, pred: usize) -> bool {
    let Some(block) = schedule.blocks.get(pred) else {
        return false;
    };
    match block.terminator {
        None => block.successors.len() == 1,
        Some(term) => matches!(
            graph.nodes.get(term as usize).map(|node| &node.op),
            Some(Op::If)
        ),
    }
}

/// Which bank a `(type, register)` pair belongs to, or `None` when the pair is
/// one neither file may hold.
///
/// The same decision the single-segment path makes inline, as a function
/// because the split path has to make it once per SEGMENT and the two must not
/// drift. The `Ref` arm is deliberately identical, obligation included: a
/// reference in a GP register is admitted only under
/// `CRATONVM_JIT_IR_REF_RESIDENCY`, whose price is `invalidate_ref_residency`
/// dropping the cached copy wherever a collector could have run. `Ref` is never
/// in the FP file at all, so the FP arm needs no such clause.
fn ls_bank_for(ty: Option<IrType>, reg: crate::regalloc::PhysReg) -> Option<bool> {
    use crate::regalloc::RegClass;
    match (reg.class, ty) {
        (RegClass::Xmm, Some(IrType::Float) | Some(IrType::Double))
            if IR_LOWER_LS_XMMS.contains(&reg.num) =>
        {
            Some(false)
        }
        (RegClass::Gp, Some(IrType::Int) | Some(IrType::Long))
            if IR_LOWER_LS_GPRS.contains(&reg.num) =>
        {
            Some(true)
        }
        (RegClass::Gp, Some(IrType::Ref))
            if ir_ref_residency_enabled() && IR_LOWER_LS_GPRS.contains(&reg.num) =>
        {
            Some(true)
        }
        _ => None,
    }
}

/// Every transition node `id` needs, or `None` when this file cannot place it
/// and it must fall back to no register at all.
///
/// # Where the transitions come from
///
/// The `Load` / `Remat` / `Move` set is `alloc.events`, filtered to this node —
/// those are the allocator's own statement of what has to happen and where.
/// The **drops** are not in `events` and have to come from the timeline: a
/// `SpillKind::Store`'s `pos` is the last position at which the register is
/// still GOOD, not the position at which it stops being good, and a
/// rematerializable value produces no `Store` at all while still leaving its
/// register. `segments` is the thing `location_at` reads, so taking the drop
/// from the segment boundary is taking it from the authority.
///
/// # Why `SpillKind::Store` emits nothing
///
/// Because this backend is write-through. `store_rax` / `gp_store_value` /
/// `fp_store_value` write the home word at EVERY definition, promoted or not,
/// and `set_residency` refuses a dropped home to every managed value — so by
/// the time any transition runs, the home already holds the value and a store
/// would write bytes that are already there. This also disposes of the one
/// ordering hazard `Store` carries: its `pos` may be the definition's own
/// position, which is a position this emitter reaches BEFORE the definition has
/// run.
///
/// # The refusals, and why each is a refusal
///
/// * **A transition outside the node positions.** A terminator or an outgoing
///   edge is outside `lower_block`'s per-node loop, so a `Ref` published there
///   would survive the back-edge poll's own call with nothing to drop it, and
///   an operand published there would have to be re-proved against
///   `emit_phi_copies`' own register discipline. Neither argument is written,
///   so the value is refused.
/// * **A transition at or before the definition.** Liveness is widened to whole
///   block spans, so a loop-carried value's range can START before the node
///   that defines it. A load from the home word there reads bytes nothing has
///   written — an `int` with a garbage value, or for an `IrType::Ref` a
///   fabricated pointer handed to the collector.
/// * **A segment register outside this value's bank or file.** The same
///   defensive test the single-segment path makes, applied per segment.
/// * **An event with no destination.** Nothing but `Store` has one legitimately,
///   and an unfamiliar shape is refused rather than guessed at.
fn ls_split_transitions(
    graph: &Graph,
    alloc: &crate::regalloc::Allocation,
    id: usize,
    gp: bool,
    def: usize,
    first: Option<u8>,
    node_pos: &[bool],
) -> Option<Vec<(usize, LsTransition)>> {
    use crate::regalloc::{remat_of, Remat, SpillKind};
    let node = id as NodeId;
    let segs = alloc.segments.get(id)?;
    let mut out: Vec<(usize, LsTransition)> = Vec::new();

    // Register → home, read off the timeline. See the doc comment.
    for pair in segs.windows(2) {
        if pair[0].reg.is_some() && pair[1].reg.is_none() {
            out.push((pair[1].range.lo, LsTransition::Drop { node, gp }));
        }
    }

    for event in alloc.events.iter().filter(|e| e.node == node) {
        if event.kind == SpillKind::Store {
            continue;
        }
        let to = event.to?;
        let transition = match event.kind {
            SpillKind::Load => LsTransition::Load {
                node,
                reg: to.num,
                gp,
            },
            SpillKind::Remat => match remat_of(graph, node) {
                // The only true re-materialisation this backend can perform
                // between two nodes. Everything else would need a scratch
                // register, and there is none here that is free by
                // construction: RAX may be carrying a value to the next node
                // and RCX a deferred one.
                //
                // `Remat::ConstF` is the case that names the constraint — the
                // bit pattern reaches an XMM register through a GP immediate
                // and a `movq`, so it costs the very register the carry is in.
                // `Remat::Param` would be a load from the incoming argument
                // slot, which is a second home word for the same value and
                // buys nothing over the one below.
                //
                // Both therefore lower as a home load, which is correct for
                // exactly the reason the `Store` paragraph above gives: the
                // home word is written at the definition, the definition
                // precedes every transition, and no managed value has a
                // dropped home.
                Some(Remat::Const(value)) if gp => LsTransition::RematConst {
                    node,
                    reg: to.num,
                    value,
                },
                _ => LsTransition::Load {
                    node,
                    reg: to.num,
                    gp,
                },
            },
            SpillKind::Move => LsTransition::Move {
                node,
                from: event.from?.num,
                to: to.num,
                gp,
            },
            // Filtered above. Spelled as a `continue` and not an
            // `unreachable!`, because a compiler that panics on a shape it did
            // not expect is a VM that dies on a method it could have declined.
            SpillKind::Store => continue,
        };
        out.push((event.pos, transition));
    }

    out.sort_by_key(|&(pos, _)| pos);
    let mut kept: Vec<(usize, LsTransition)> = Vec::with_capacity(out.len());
    for (pos, transition) in out {
        if pos < def || !node_pos.get(pos).copied().unwrap_or(false) {
            return None;
        }
        if pos == def {
            // A transition AT the definition is realised by the definition's
            // own write-through publish, which puts the value in `first` — so
            // emitting one here would either duplicate that publish or, if it
            // named a different register, contradict it. The first is elided;
            // the second is refused, because a contradiction between the
            // allocator's timeline and this file's publish site is not
            // something to resolve by picking one.
            match (transition.destination(), first) {
                (Some((reg, _)), Some(f)) if reg == f => continue,
                (None, None) => continue,
                _ => return None,
            }
        }
        kept.push((pos, transition));
    }
    Some(kept)
}

/// Can this file place split value `id` position by position, and if so where
/// does it start and what does it owe?
///
/// `Some((gp, first, transitions))`: which bank, the register the value's own
/// definition should publish into (`None` when the allocator has it in memory
/// at that point), and every transition after that.
///
/// Refuses, and the caller then falls back to today's behaviour — no register
/// at all — rather than to a guess:
///
/// * no home word from `plan_slots`, which write-through has nothing to write
///   to and no transition has anything to load from;
/// * no definition position, so "after the definition" is not a question this
///   pass can answer;
/// * a segment register the type's bank may not hold, or that is outside the
///   file this backend saves — the same defensive test the single-segment path
///   makes, per segment;
/// * two segments in DIFFERENT banks, which would mean a node changed type;
/// * no register anywhere in the timeline, which is a spilled value and not a
///   split one;
/// * anything [`ls_split_transitions`] cannot place.
fn ls_split_place(
    graph: &Graph,
    plan: &SlotPlan,
    live: &crate::regalloc::LiveModel,
    alloc: &crate::regalloc::Allocation,
    id: usize,
    segs: &[crate::regalloc::Segment],
    node_pos: &[bool],
) -> Option<(bool, Option<u8>, Vec<(usize, LsTransition)>)> {
    use crate::regalloc::ValueLoc;
    // Write-through needs a home to write, and every transition below reads
    // one. This is the same requirement `skip_home` states for whole-range
    // values, asked earlier because the split path never reaches that check.
    plan.node_color.get(id).copied().flatten()?;
    let ty = graph.nodes.get(id).map(|node| node.ty);
    let def = live.pos_of.get(id).copied().flatten()?;

    let mut bank: Option<bool> = None;
    for seg in segs {
        let Some(reg) = seg.reg else { continue };
        let seg_bank = ls_bank_for(ty, reg)?;
        match bank {
            None => bank = Some(seg_bank),
            // A node has one type and a type picks one bank, so this is
            // unreachable unless `RegClass::of` or the bank match moved under
            // this code — which is exactly when a refusal is wanted.
            Some(b) if b == seg_bank => {}
            Some(_) => return None,
        }
    }
    let gp = bank?;

    // Where the value is at its OWN definition, which is what the definition's
    // write-through publish will put it in. Taken from `location_at` rather
    // than from `segs[0]`: liveness is widened to whole block spans, so a
    // loop-carried value's first segment can begin before the node that defines
    // it and `segs[0]` is then the wrong answer.
    let first = match alloc.location_at(id as NodeId, def) {
        Some(ValueLoc::Reg(reg)) => Some(reg.num),
        _ => None,
    };
    let transitions = ls_split_transitions(graph, alloc, id, gp, def, first, node_pos)?;
    // Counted only once the value is actually placed. The whole-range site
    // bumps this before its own second-opinion passes can take the register
    // back, which is already one source of over-count; adding a second, for
    // values this function is about to refuse outright, would make the number
    // mean nothing at all.
    if matches!(ty, Some(IrType::Ref)) {
        REF_RESIDENCY_ADMITTED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
    Some((gp, first, transitions))
}

/// Which linear positions are NODE positions — the ones `lower_block`'s
/// per-node loop reaches, and therefore the only ones a transition may sit at.
///
/// A terminator's position and a block's outgoing-edge position are the two
/// that are not here, and leaving them out is the safepoint argument rather
/// than a simplification: both are outside the per-node loop that invalidates
/// reference residency, so a `Ref` published at either would survive the
/// back-edge poll's own call with nothing to drop it. See
/// [`ls_split_transitions`].
fn ls_node_positions(schedule: &Schedule, live: &crate::regalloc::LiveModel) -> Vec<bool> {
    let mut node_pos = vec![false; live.total_positions];
    for (b, block) in schedule.blocks.iter().enumerate() {
        let Some(&(start, _)) = live.span.get(b) else {
            continue;
        };
        for offset in 0..block.nodes.len() {
            if let Some(cell) = node_pos.get_mut(start + offset) {
                *cell = true;
            }
        }
    }
    node_pos
}

/// The location a transition's register denotes, in the allocator's vocabulary.
fn ls_reg_loc(reg: u8, gp: bool) -> crate::regalloc::ValueLoc {
    use crate::regalloc::{PhysReg, ValueLoc};
    ValueLoc::Reg(if gp {
        PhysReg::gp(reg)
    } else {
        PhysReg::xmm(reg)
    })
}

/// Bucket every managed value's transitions by position and put each bucket in
/// an order that is safe to emit sequentially, or refuse the whole plan.
///
/// # Why an order is needed at all
///
/// The transitions at one position are SIMULTANEOUS. The allocator's statement
/// is "at position `p`, these values are in these registers"; it says nothing
/// about an order, and every order is not equally good. `a ← b` beside `b ← a`
/// is a swap, and emitting the two in sequence makes both `b`. A load into a
/// register that another value is still being moved out of destroys that
/// value's source the same way.
///
/// That is exactly a parallel copy, and `regalloc::resolve_parallel_copy` is
/// the sequencer for one — the same one `emit_phi_copies` feeds its edge webs
/// to. Loads and remats go into it as well as moves: their DESTINATION races
/// with everybody else's source even though their own source is memory (or an
/// immediate), and `ValueLoc::Slot` is how a source that is not a register is
/// spelled.
///
/// # Why a cycle refuses the whole method
///
/// Breaking a cycle costs a scratch register, and `CopyOp::Save` deliberately
/// does not name one — the backend is supposed to supply whatever it keeps free
/// at that point. Between two nodes this backend keeps nothing free: RAX may be
/// carrying a value to the next node and RCX a deferred one (`plan_carries`),
/// and the whole register file is either in use or callee-saved and owned by
/// somebody. So there is no scratch to supply, and the honest answer is to
/// decline every split value in the method rather than to pick a register and
/// hope. The caller sends them all back to memory, which is what they had
/// before this pass existed.
///
/// Also refuses when two transitions publish into ONE register at one position
/// (`resolve_parallel_copy` rejects a destination written twice), and when the
/// sequence comes back with a different number of moves than it was given —
/// both are states in which this file's model of the allocation has come apart
/// from the allocation, and neither is one to emit code from.
fn ls_sequence_split_plan(
    taken: &[(usize, bool, Vec<(usize, LsTransition)>)],
    total_positions: usize,
) -> Option<Vec<Vec<LsTransition>>> {
    use crate::regalloc::{resolve_parallel_copy, CopyOp, ValueLoc};
    let mut buckets: Vec<Vec<LsTransition>> = vec![Vec::new(); total_positions];
    for (_, _, transitions) in taken {
        for &(pos, transition) in transitions {
            buckets.get_mut(pos)?.push(transition);
        }
    }
    for at in buckets.iter_mut() {
        // A drop emits nothing and `ls_apply_transitions` runs every drop
        // before any publish, so only the publishes need sequencing — and one
        // publish cannot race itself.
        let publishes: Vec<LsTransition> = at
            .iter()
            .copied()
            .filter(|t| t.destination().is_some())
            .collect();
        if publishes.len() < 2 {
            continue;
        }
        let mut copies: Vec<(ValueLoc, ValueLoc)> = Vec::with_capacity(publishes.len());
        for transition in &publishes {
            let (reg, gp) = transition.destination()?;
            let source = match *transition {
                LsTransition::Move { from, gp, .. } => ls_reg_loc(from, gp),
                // A load or a remat reads no register, so it depends on nothing
                // here and only has to be ordered after whoever still reads its
                // destination. `Slot` is how `resolve_parallel_copy` spells
                // "not a register"; a `Slot` can never equal a destination,
                // which are all `Reg`, so the index is free to be the node.
                _ => ValueLoc::Slot(transition.node()),
            };
            copies.push((ls_reg_loc(reg, gp), source));
        }
        let sequence = resolve_parallel_copy(&copies).ok()?;
        let mut ordered: Vec<LsTransition> = at
            .iter()
            .copied()
            .filter(|t| t.destination().is_none())
            .collect();
        for op in sequence {
            match op {
                CopyOp::Move { to, .. } => {
                    let found = publishes.iter().find(|t| match t.destination() {
                        Some((reg, gp)) => ls_reg_loc(reg, gp) == to,
                        None => false,
                    })?;
                    ordered.push(*found);
                }
                // A cycle. See the doc comment: there is no scratch here.
                CopyOp::Save { .. } | CopyOp::Restore { .. } => return None,
            }
        }
        if ordered.len() != at.len() {
            return None;
        }
        *at = ordered;
    }
    Some(buckets)
}

/// Which XMM register holds each value for its whole life, plus what the
/// decision cost.
#[derive(Clone, Debug, Default)]
struct RegResidency {
    /// `reg_of[id]` = the XMM number holding node `id`'s value from its
    /// definition to its last use, with no split, no spill and no reload.
    /// `None` for everything else, which is the majority.
    ///
    /// For a value named by [`Self::splits`] this is instead the register the
    /// value's DEFINITION publishes into, and `ls_apply_transitions` re-points
    /// it at each transition. See [`LsSplitPlan`].
    reg_of: Vec<Option<u8>>,
    /// `gp_reg_of[id]` = the same, in the GENERAL-PURPOSE file. Disjoint from
    /// `reg_of` by construction: a node has one type, and the two files serve
    /// disjoint type sets (FP here, int/long there, `Ref` in neither).
    gp_reg_of: Vec<Option<u8>>,
    /// How many values that is.
    promoted: usize,
    /// Values the allocator promoted that this file then refused, because the
    /// allocator's liveness model and `plan_slots`' disagreed about them. A
    /// non-zero count is a compiler bug worth chasing; it is not wrong code,
    /// because a refusal only sends the value back to memory.
    demoted: usize,
    /// Copied out of the liveness model so the caller can report it.
    #[allow(dead_code)]
    peak_live: usize,
    /// The position-driven half of the plan, for the values the scan SPLIT.
    /// Default (empty) unless [`ir_ls_splits_enabled`]; see [`LsSplitPlan`].
    splits: LsSplitPlan,
    /// What happened to every value-typed `Op::Phi` in the graph. See
    /// [`PhiCensus`].
    phi_census: PhiCensus,
    /// Per back-edge BLOCK: the FP values resident in a caller-saved XMM at
    /// that block's poll, which its slow path must reload from their home
    /// words (round 11 wave 6, see [`ir_poll_preserves_fp`]). Empty whenever
    /// the model still clobbers the XMM bank at the poll, because no value can
    /// then hold such a register there.
    poll_fp_reloads: HashMap<usize, Vec<NodeId>>,
}

/// Why each phi ended up where it did.
///
/// # Why a phi-scoped census beside the general one
///
/// The general skip census has a single `phi=` field, and until 2026-09-02 it
/// meant one thing: *"refused because it is a phi"*, unconditionally, because
/// [`plan_register_residency`] refused the op outright. Once phis are admitted
/// that field stops distinguishing the two answers a reader needs to tell
/// apart — **"the mechanism did not apply"** against **"the mechanism applied
/// and this phi lost anyway"** — and a single number that conflates them is
/// exactly the shape of diagnostic this file has been burned by twice: the
/// residency flag that printed only on success and hid a pre-existing refusal
/// for months, and the `droppable=0` line that was quoted as evidence a lever
/// was dead while the same compile was pulling it three times.
///
/// So each refusal gets its own field, and they are *disjoint*: a phi is
/// counted once and only once, under the first cause that stopped it.
///
/// # Attributed AFTER every pass, not at the refusal
///
/// The obvious implementation counts at each `continue` inside the scan loop.
/// That over-reports, because `ir_reserve_carried_enabled`'s pass runs
/// afterwards and can hand a register to a phi the scan refused — a loop
/// counter the scan split is exactly its target population. A census taken at
/// the `continue` would report that phi as `no_register` while the emitted code
/// reads it from RBX, which is the same class of error as the two above: a
/// diagnostic computing its own answer instead of reading the one the emission
/// used.
///
/// The causes are therefore *recorded* per node during the scan and *tallied*
/// at the end, against the final `reg_of`/`gp_reg_of`. A phi that any later
/// pass rescued is counted under [`Self::resident`] and its recorded cause is
/// discarded. What this census reports is what the emission does.
///
/// The accounting identity — every VALUE-typed phi in the graph lands in
/// exactly one field — is asserted in `debug_assert` form at the tally site,
/// for the same reason `census_home_blocks` asserts its own: a cause added to
/// the scan and not here makes the census read low, and a census that reads low
/// retires levers that are engaged.
///
/// # What is NOT counted
///
/// `Memory` phis. `IrBuilder` builds one at every merge where it builds a value
/// phi, so a counted loop has one at its header; it carries no runtime value,
/// `RegClass::of` answers `None` for it, and `allocate_linear_scan` never gives
/// it an interval. Counting it would put one guaranteed refusal per loop in
/// this census and make `refused == 0` unassertable on the very shape the
/// mechanism exists for.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PhiCensus {
    /// Phis holding a register in the emitted body, in either bank.
    resident: usize,
    /// Refused because `CRATONVM_JIT_IR_PHI_RESIDENCY` is off. This is the
    /// "did not apply" bucket and the only one the pre-2026-09-02 `phi=` field
    /// ever counted.
    disabled: usize,
    /// Refused because the phi's `IrType` is `Ref`. **A hard refusal, not a
    /// heuristic** — see the refusal site in [`plan_register_residency`].
    ref_type: usize,
    /// Refused because the scan gave it no single whole-range register: no
    /// interval at all, a spilled interval, or a split one.
    ///
    /// A split one stays here even under `CRATONVM_JIT_IR_LS_SPLITS`, which
    /// admits split values everywhere else. A phi's publish site is
    /// `emit_phi_copies`, on the EDGE -- outside the per-node loop that owns
    /// the reference-invalidation audit, and with its own discipline for
    /// reading sources and staging destinations. Admitting one needs that
    /// argument written; it is not, so this is a refusal and not a `TODO`.
    no_register: usize,
    /// Refused because `plan_slots` gave it no home word. Write-through has
    /// nothing to write to.
    no_home: usize,
    /// Refused because its type is in neither bank for a reason other than
    /// `Ref` — which means this file or `RegClass::of` changed under the bank
    /// match, since a phi's type otherwise picks its bank.
    wrong_bank: usize,
    /// Assigned a register and then taken back by one of the two second-opinion
    /// passes (an aliasing disagreement between the two liveness models, or a
    /// clobber `plan_slots`' range sees and the allocator's did not).
    demoted: usize,
}

impl PhiCensus {
    /// Every phi accounted for, which by the identity asserted at the tally
    /// site is every value-typed `Op::Phi` in the graph.
    fn total(&self) -> usize {
        self.resident
            + self.disabled
            + self.ref_type
            + self.no_register
            + self.no_home
            + self.wrong_bank
            + self.demoted
    }

    /// Phis that reached no register, whatever the cause.
    ///
    /// The number a test asserts zero on when it means "this loop's carried
    /// values all moved". Written as `total - resident` rather than as a sum of
    /// the refusals so that a cause added to [`PhiCensus`] and not to this
    /// method cannot make it read low.
    #[cfg_attr(not(test), allow(dead_code))]
    fn refused(&self) -> usize {
        self.total() - self.resident
    }
}

/// One phi's recorded refusal, pending the tally described on [`PhiCensus`].
///
/// Deliberately not `Default`: "no cause recorded" is `Option::None` and means
/// the scan never refused this phi, which is a different statement from any of
/// these and must not be spelled by one of them.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PhiRefusal {
    Disabled,
    RefType,
    NoRegister,
    NoHome,
    WrongBank,
}

/// The machine model for `ir_lower`'s emission, over `regs`.
///
/// [`crate::regalloc::MachineModel::for_graph`] derives clobbers from ops. It
/// is correct as far as it goes, and it cannot know about the calls a
/// particular backend emits *between* ops. This adds the one `ir_lower` has:
/// the cooperative safepoint poll, which on a loop back edge tests a byte and
/// on a set flag calls its slow path (`emit_safepoint_poll`) — at the block's
/// outgoing-edge position, which belongs to no node. `for_graph` already marks
/// those positions safepoints; they must also be clobbers, because a value in
/// a caller-saved register across a back edge would be destroyed by that call.
///
/// The entry poll (before block 0) needs nothing: no value is live yet.
fn ir_lower_machine_model(
    graph: &Graph,
    schedule: &Schedule,
    live: &crate::regalloc::LiveModel,
    regs: crate::regalloc::RegFile,
) -> crate::regalloc::MachineModel {
    use std::collections::BTreeMap;
    // The back-edge safepoint poll is a CALL site, so what it destroys is the
    // caller-saved subset — the same rule `MachineModel::for_graph` applies at
    // an `Op::Call`, applied here because the poll is not a graph node and
    // `for_graph` therefore never sees it.
    //
    // This used to be every register in the file. That was safe but wrong in
    // the expensive direction: it made a loop-carried value unpromotable into
    // XMM6/XMM7 even on the target where this frame saves them, which is
    // exactly the case the save area was built for. The narrowing is sound
    // because the poll's slow path is `jit_safepoint_slow_path`, an ordinary
    // `extern "C"` function — Win64 obliges it to preserve XMM6–XMM15, and on
    // System V no XMM is callee-saved so `IR_LOWER_SAVED_XMMS` is empty and
    // this set is still the whole file, byte for byte as before.
    //
    // Round 11 wave 6: minus the XMM bank when `ir_poll_preserves_fp`, because
    // the slow path then reloads every FP value resident across the edge from
    // its home word. On System V this was the whole IR XMM file, so no FP
    // value stayed in a register across a loop iteration.
    let preserve_fp = ir_poll_preserves_fp();
    let poll_destroys: Vec<crate::regalloc::PhysReg> = regs
        .specs()
        .iter()
        .filter(|s| s.caller_saved)
        .filter(|s| !(preserve_fp && s.reg.class == crate::regalloc::RegClass::Xmm))
        .map(|s| s.reg)
        .collect();
    let mut model = crate::regalloc::MachineModel::for_graph(graph, schedule, live, regs);
    // Reference residency. The allocator's own rule — no reference may hold a
    // register across a safepoint — is the right default for a backend whose
    // register file is authoritative. This one's is a write-through read cache
    // over a frame slot the oop map DOES name, so the collector's view is
    // complete without it and the obligation this lifts is discharged instead
    // by `invalidate_ref_residency`, which drops the cached copy at every point
    // a collector could have run. See `ir_ref_residency_enabled`.
    model.refs_may_cross_safepoints =
        ir_ref_residency_enabled() && ir_ref_residency_cross_safepoint_enabled();

    // `MachineModel::clobbered_at` binary-searches by position, so the list
    // must stay sorted AND hold one entry per position. Merge through a map
    // rather than push-and-sort.
    let mut merged: BTreeMap<usize, Vec<crate::regalloc::PhysReg>> = BTreeMap::new();
    for (pos, regs) in model.clobbers.drain(..) {
        merged.entry(pos).or_default().extend(regs);
    }
    for (b, block) in schedule.blocks.iter().enumerate() {
        if !block.successors.iter().any(|&s| s <= b) {
            continue;
        }
        let Some(&(_, edge)) = live.span.get(b) else {
            continue;
        };
        // `lower_terminator` and `lower_block`'s fall-through arm both emit the
        // poll immediately before the edge's phi copies, i.e. between the
        // terminator position and the edge position. Clobber both, for the same
        // reason `MachineModel::for_graph` makes both safepoints.
        for pos in [edge.saturating_sub(1), edge] {
            merged
                .entry(pos)
                .or_default()
                .extend_from_slice(&poll_destroys);
        }
    }
    model.clobbers = merged
        .into_iter()
        .map(|(pos, mut regs)| {
            regs.sort_unstable();
            regs.dedup();
            (pos, regs)
        })
        .collect();
    // Last use at a call (round 9 wave 4, irlower4 -- page
    // `linear-scan-last-use-at-a-call-still-splits`). AFTER every clobber above
    // is merged, as `mark_call_operand_reads_first` requires: the exemption
    // covers every register clobbered at a listed position, the back-edge poll
    // included, and that is sound here because the poll runs after the node at
    // that position was lowered (it is emitted before the edge's phi copies),
    // i.e. after the operand read. Only the audited ops are listed -- see
    // `ir_call_reads_operands_first`.
    if ir_ls_call_last_use_enabled() {
        model.mark_operand_reads_first_where(graph, live, ir_call_reads_operands_first);
    }
    model
}

/// Let a value whose LAST use is an operand of an audited call-lowered op keep
/// its (caller-saved) register through that op -- **default ON** since round 9
/// wave 6, `CRATONVM_JIT_IR_LS_CALL_LAST_USE=0` opts out (landed opt-in in
/// wave 4). Off, the allocator splits such a value at the call as before and
/// the consumer then promotes it nowhere, which is what the page measured.
///
/// # The measurement that flipped it (wave-5 binary, Windows x64)
///
/// * The `[ir-ls]` census of `CratonBenchC2 dispatch` / `pipeline`,
///   `CratonBench arithmetic` and `IrEscapeProbe` is byte-identical off and on
///   (no audited op takes a caller-saved value there), and their timings are
///   within noise both ways.
/// * An FP kernel whose `double` is read twice, the second time as an FP `%`
///   operand (`CALL jit_drem`): the value becomes resident (`resident fp=1` ->
///   `fp=2`, `split_or_spilled=3` -> `2`), with identical answers, and the
///   loop ran 2 146/2 136/2 000/1 979/1 945/1 983 ms off against 2 092/1 891/
///   1 888/1 802/1 981/1 880 ms on (median ~5% faster; 5 of 6 interleaved
///   pairs, and 4 of 5 in an earlier round).
///
/// See `linear-scan-last-use-at-a-call-still-splits-20260918.md`,
/// "Resolution". System V (every XMM caller-saved) should gain more.
fn ir_ls_call_last_use_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_LS_CALL_LAST_USE")
}

/// Does this file's lowering of `node` read EVERY register operand before the
/// first instruction that can destroy a caller-saved register? The audit
/// `MachineModel::reads_precede_clobber` asks the emitter for, per op.
///
/// Admitted (round 9 wave 4):
///
/// * `Op::Store(_)`, every route. The receiver goes to RAX and the null check
///   is a `TEST` plus a deopt JUMP (the deopt path reads its frame from home
///   words, which the write-through invariant keeps complete, and never
///   returns into the body). The helper routes then load their arguments and
///   `CALL` once, with nothing after the call; the gated reference store's
///   bails reload from HOME words (`slot_of`), not registers; the inline int
///   store makes no call at all. No frame record, no safepoint map. And the
///   stored value is read through `gp_load_value`, which reads an FP value
///   from its home word (no GP residency), so an XMM register is never read.
/// * An FP `Op::Rem`: `fp_load_value(XMM0, a)`, `fp_load_value(XMM1, b)`, then
///   `MOV RAX, helper ; CALL RAX`, and the result from XMM0. Both operands are
///   read before the call.
///
/// NOT admitted, with the reason, so the list is extended by audit and not by
/// guess:
///
/// * `Op::Call`, `Op::LambdaIntToDouble`, `Op::MonitorEnter/Exit`,
///   `Op::ArrayStore(Ref)`: `emit_safepoint_map` runs FIRST, and its shadow
///   push CALLS `get_current_thread`, destroying every volatile register
///   before the arguments are marshalled. (A monitor op's inline thin-lock
///   fast path runs before even that, and writes RAX/RCX/RDX/R10/R11.)
/// * `Op::New`, `Op::NewArray`, `Op::ConstString`, `Op::ConstClass`,
///   `Op::LoadStatic`, `Op::Load`, `Op::InstanceOf`, `Op::CheckCast`: not
///   audited. Their operands are references or ints, which live in the
///   callee-saved GP file here and are never clobbered at a call, so there is
///   nothing to gain from admitting them.
fn ir_call_reads_operands_first(node: &Node) -> bool {
    match node.op {
        Op::Store(_) => true,
        Op::Rem => matches!(node.ty, IrType::Float | IrType::Double),
        _ => false,
    }
}

/// [`clobbered_within`] for ONE value, honouring the allocator's last-use
/// exemption: a clobber at `hi` does not count when
/// `MachineModel::read_before_clobber` holds for `id` there (the position is
/// listed in `reads_precede_clobber`, and it is both the end of `id`'s live
/// range and its last use). The same predicate the scan and
/// `verify_allocation` apply, so the second opinion cannot demote exactly the
/// values the opt-in exists to keep -- and, with the list empty (the default),
/// this is `clobbered_within` exactly.
fn clobbered_within_for_value(
    model: &crate::regalloc::MachineModel,
    live: &crate::regalloc::LiveModel,
    id: usize,
    lo: usize,
    hi: usize,
    reg: crate::regalloc::PhysReg,
) -> bool {
    let start = model.clobbers.partition_point(|(pos, _)| *pos < lo);
    model.clobbers[start..]
        .iter()
        .take_while(|(pos, _)| *pos <= hi)
        .any(|(pos, regs)| {
            regs.contains(&reg)
                && !(*pos == hi && model.read_before_clobber(live, id as NodeId, *pos))
        })
}

/// Plan register residency for one scheduled graph, or `None` when nothing is
/// promotable and the colourer's memory layout stands unchanged.
///
/// Every refusal here is a *demotion*, never a bailout: a value that does not
/// take a register keeps the home slot the lowerer has always given it, which
/// is correct by construction. The one hard failure is
/// [`crate::regalloc::verify_allocation`] rejecting the allocation, which is a
/// compiler bug — that returns `Err` and the caller refuses the compile rather
/// than emitting against an allocation nothing proved.
/// Report why residency was declined, under `CRATONVM_DBG_IR_LINEAR_SCAN`.
///
/// Every refusal in `plan_register_residency` used to be a bare `Ok(None)`,
/// and the flag printed only on SUCCESS -- so "no output" meant "declined,
/// somewhere, for one of four reasons" and could not be acted on. Naming the
/// conjunct is the difference between a count and a diagnosis.
fn ls_refuse(reason: &str) -> Option<RegResidency> {
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
        eprintln!("[ir-ls] refused: {reason}");
    }
    None
}

/// Is `reg` in any clobber set at a position in `lo..=hi`?
///
/// `clobbers` is a `MachineModel::clobbers` list, which is sorted by position
/// with one entry per position (`ir_lower_machine_model` rebuilds it through a
/// `BTreeMap`, and `verify_allocation` rejects a model that is not), so the
/// window is found by binary search instead of scanning the whole list once
/// per promoted value — `plan_register_residency`'s re-checks were `O(values * clobbers)`, and a
/// call-heavy method has a clobber entry per call.
fn clobbered_within(
    clobbers: &[(usize, Vec<crate::regalloc::PhysReg>)],
    lo: usize,
    hi: usize,
    reg: crate::regalloc::PhysReg,
) -> bool {
    let start = clobbers.partition_point(|(pos, _)| *pos < lo);
    clobbers[start..]
        .iter()
        .take_while(|(pos, _)| *pos <= hi)
        .any(|(_, regs)| regs.contains(&reg))
}

/// Keep the scan's certain refusals out of the scan -- **default ON**
/// (round 13 wave 11, lane callcost5, proposal CC4-3 in
/// `jit-r13-callcost4-proposals-RETIRED-20260929.md`); `CRATONVM_JIT_IR_LS_PREPIN_REFUSED=0` hands
/// every candidate to the scan as before.
///
/// Every register the kept values hold is saved in the prologue and restored
/// at every exit (`ls_saved_gp`). The scan's free-register choice is already
/// "lowest free in file order" -- first fit, which on intervals taken in start
/// order uses as few registers as the candidates' overlap allows -- so CC4-3's
/// "reuse a register already handed out before opening a new one" was true of
/// the scan all along. What made `fib` save more registers than it keeps
/// values across a call is WHO the scan hands them to: constants (read as
/// immediates), values read once, and (by default) references, all of which
/// the refusal loop in [`plan_register_residency`] then throws away. A refused
/// value that held RBX while a kept one was defined pushed the kept one to R12;
/// the refusal left RBX idle and R12 saved. Pinning them first is exactly the
/// refusal, made before the scan instead of after it: a pinned value keeps its
/// home word, which is what the refusal gives it.
///
/// Read per compile (no `OnceLock`): nothing in the frame layout depends on it
/// beyond the residency plan it shapes.
fn ir_ls_prepin_refused_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_LS_PREPIN_REFUSED")
}

/// A single-use `int`/`long` whose home is one `store_rax` and whose range
/// crosses a Java call may take a register -- **default ON** (round 14 wave 1,
/// lane calls, proposal CC5-1 in `jit-r13-callcost5-proposals-RETIRED-20260929.md`);
/// `CRATONVM_JIT_IR_RESIDENCY_CALL_CROSSING=0` restores the plain pays rule.
///
/// In `return fib(n-1) + fib(n-2)` the first result is read once, by the add,
/// after the second call. The pays rule refuses it (`skip_single_use`), so it
/// is stored to its home after its call and reloaded at the add. A register
/// makes that home droppable (`value_home_droppable`: the direct self-call's
/// result is one `store_rax`), which turns the pair into one register move.
/// This is the narrow case of `CRATONVM_JIT_IR_RESIDENCY_CROSSBLOCK` (still
/// off: it regresses `mixNarrow`): only a value a real `Op::Call` separates
/// from its use, and it is charged against the same carried-reservation
/// price, so a loop kernel's carried values are not displaced by it.
///
/// Residency is a pure placement decision here (every register of the GP
/// file is callee-saved and survives the call; the publish and home-drop
/// rules are the ordinary ones), so the switch changes cost, never answers.
/// Read per compile.
fn ir_residency_call_crossing_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RESIDENCY_CALL_CROSSING")
}

/// The sorted positions of every `Op::Call` the schedule places, for
/// [`single_use_crosses_a_call`]; empty (so nothing is a candidate) when
/// [`ir_residency_call_crossing_enabled`] is off. The switch is read here, once
/// per plan, not once per candidate.
fn ls_call_positions(graph: &Graph, live: &crate::regalloc::LiveModel) -> Vec<usize> {
    if !ir_residency_call_crossing_enabled() {
        return Vec::new();
    }
    let mut out: Vec<usize> = graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(_, node)| matches!(node.op, Op::Call { .. }))
        .filter_map(|(id, _)| live.pos_of.get(id).copied().flatten())
        .collect();
    out.sort_unstable();
    out
}

/// Is `id` a CC5-1 candidate ([`ir_residency_call_crossing_enabled`])? A value
/// read once (`uses == 1`), of type `int`/`long`, whose home is written by one
/// `store_rax` (so a register lets it drop), with an `Op::Call` strictly inside
/// its live range (its one read is after a call it is live across).
/// `call_pos` is [`ls_call_positions`]. Shared by the pre-pin
/// ([`ls_certain_refusals`]) and the refusal loop so the two cannot disagree.
fn single_use_crosses_a_call(
    graph: &Graph,
    live: &crate::regalloc::LiveModel,
    call_pos: &[usize],
    id: usize,
    uses: u32,
) -> bool {
    if uses != 1 || call_pos.is_empty() {
        return false;
    }
    let Some(node) = graph.nodes.get(id) else {
        return false;
    };
    if !matches!(node.ty, IrType::Int | IrType::Long) {
        return false;
    }
    let one_store = op_home_is_one_store_rax(&node.op)
        || (matches!(node.op, Op::Call { .. })
            && Lowerer::is_direct_self_call(node)
            && ir_self_call_states_unread_enabled());
    if !one_store {
        return false;
    }
    let Some(range) = live.range.get(id).copied().flatten() else {
        return false;
    };
    let first_after_def = call_pos.partition_point(|&p| p <= range.lo);
    call_pos.get(first_after_def).is_some_and(|&p| p < range.hi)
}

/// The values [`plan_register_residency`]'s refusal loop refuses WHATEVER the
/// scan does with them, for [`ir_ls_prepin_refused_enabled`]. Each clause is
/// one of that loop's refusals, restated with its own predicates so the two
/// cannot disagree, and restricted to the case where no later branch of the
/// loop (nor the carried or parameter passes, which hand out registers the
/// scan did not use and never consult the pin) could keep the value:
///
/// * a constant, under `ir_residency_pays_enabled` (`skip_const`, asked before
///   any other non-phi check);
/// * a value read once, under the same rule, that is not a crossblock
///   candidate (`skip_single_use`: `!pays_here && !crossblock_admit`, and
///   `crossblock_admit` implies `crossblock_candidate`) nor a call-crossing
///   one ([`single_use_crosses_a_call`], same implication for
///   `call_crossing_admit`);
/// * a reference, while `ir_ref_residency_enabled` is off (the bank match) and
///   `ir_ls_splits_enabled` is off (the split arm, which could otherwise place
///   one).
///
/// A phi is never listed: its refusals have their own census and its pin its
/// own release.
fn ls_certain_refusals(
    graph: &Graph,
    schedule: &Schedule,
    live: &crate::regalloc::LiveModel,
) -> Vec<NodeId> {
    let pays = ir_residency_pays_enabled();
    // JIT round 19 proposal wave 12, lane lv12 (LV11-1,
    // `CRATONVM_JIT_IR_LS_PREPIN_REFS_UNDER_SPLITS`): the split arm refuses a
    // `Ref` too unless reference residency is on (`ls_bank_for`), so under
    // `LS_SPLITS` alone a `Ref` is still a certain refusal.
    let refs_refused = !ir_ref_residency_enabled()
        && (!ir_ls_splits_enabled() || ir_ls_prepin_refs_under_splits_enabled());
    let crossblock = ir_residency_crossblock_enabled();
    let n = graph.nodes.len();
    // The refusal loop's own `use_count`, computed the same way.
    let mut use_count = vec![0u32; n];
    for node in &graph.nodes {
        for &input in &node.inputs {
            if input != NO_NODE {
                if let Some(c) = use_count.get_mut(input as usize) {
                    *c = c.saturating_add(1);
                }
            }
        }
    }
    let call_pos = ls_call_positions(graph, live);
    let mut out: Vec<NodeId> = Vec::new();
    for (id, node) in graph.nodes.iter().enumerate() {
        if !live.wants_loc.get(id).copied().unwrap_or(false) || matches!(node.op, Op::Phi) {
            continue;
        }
        let uses = use_count.get(id).copied().unwrap_or(0);
        let crossblock_candidate =
            crossblock && uses == 1 && !single_use_is_in_the_carry_window(graph, schedule, id);
        // CC5-1: the refusal loop may keep this one, so it is not certain.
        let call_crossing_candidate = single_use_crosses_a_call(graph, live, &call_pos, id, uses);
        let refused = (pays && matches!(node.op, Op::Const(_)))
            || (pays
                && !ir_residency_pays_here(live, schedule, id, uses)
                && !crossblock_candidate
                && !call_crossing_candidate)
            || (refs_refused && node.ty == IrType::Ref);
        if refused {
            // Cast: an index into the node arena is a `NodeId`.
            out.push(id as NodeId);
        }
    }
    out
}

/// `plan_register_residency`'s `ranges_agree`: the slot plan and the
/// allocator's liveness model give every value the same range (or both give
/// it none). Split out in interpreter round i2 wave 65 (lane L2) so the φ-edge
/// fix can be tested against the exact predicate the gate uses.
fn slot_and_live_ranges_agree(plan: &SlotPlan, live: &crate::regalloc::LiveModel) -> bool {
    plan.range.len() == live.range.len()
        && plan
            .range
            .iter()
            .zip(live.range.iter())
            .all(|(colourer, scan)| match (colourer, scan) {
                (Some(c), Some(s)) => c.lo == s.lo && c.hi == s.hi,
                (None, None) => true,
                _ => false,
            })
}

/// The `[ir-ls] ranges-disagree:` census line (JIT round 19 proposal wave 10,
/// lane lv10; the measurement half of
/// `i65-L2-proposal-measure-the-split-path-once-the-gate-opens`): why
/// [`slot_and_live_ranges_agree`] is false. `count=` values whose two ranges
/// differ (`phi=` of them φs, `slot_only=` / `live_only=` ranged by one model
/// alone), `len_differs=` when the two range tables are not even the same
/// length, and the first four as `n<id>:<op>:slot=<lo>..<hi>/live=<lo>..<hi>`
/// (`-` for no range). Printed under `CRATONVM_DBG_IR_LINEAR_SCAN` only.
fn ranges_disagreement_census(
    graph: &Graph,
    plan: &SlotPlan,
    live: &crate::regalloc::LiveModel,
) -> String {
    let fmt = |r: Option<LiveRange>| match r {
        Some(r) => format!("{}..{}", r.lo, r.hi),
        None => "-".to_string(),
    };
    let (mut count, mut phi, mut slot_only, mut live_only) = (0usize, 0usize, 0usize, 0usize);
    let mut first: Vec<String> = Vec::new();
    for (id, (c, s)) in plan.range.iter().zip(live.range.iter()).enumerate() {
        let same = match (c, s) {
            (Some(c), Some(s)) => c.lo == s.lo && c.hi == s.hi,
            (None, None) => true,
            _ => false,
        };
        if same {
            continue;
        }
        count += 1;
        let op = graph.nodes.get(id).map(|n| &n.op);
        if matches!(op, Some(Op::Phi)) {
            phi += 1;
        }
        match (c, s) {
            (Some(_), None) => slot_only += 1,
            (None, Some(_)) => live_only += 1,
            _ => {}
        }
        if first.len() < 4 {
            let name = op.map_or_else(
                || "?".to_string(),
                |op| {
                    let full = format!("{op:?}");
                    full.split([' ', '{', '('])
                        .next()
                        .unwrap_or("?")
                        .to_string()
                },
            );
            first.push(format!(
                "n{id}:{name}:slot={}/live={}",
                fmt(*c),
                fmt((*s).map(|r| LiveRange { lo: r.lo, hi: r.hi }))
            ));
        }
    }
    format!(
        "[ir-ls] ranges-disagree: count={count} phi={phi} slot_only={slot_only} \
         live_only={live_only} len_differs={} first=[{}]",
        plan.range.len() != live.range.len(),
        first.join(" ")
    )
}

/// The loop-carried reservation of [`plan_register_residency_with`]: which
/// carried-and-read values get which free GP register, in the pass's own
/// order (loop weight, then id), given the registers already `taken`.
/// Factored out unchanged in JIT round 19 proposal wave 11 (lane lv11) so the
/// `CRATONVM_JIT_IR_LS_SPLITS_CARRIED_FIRST` dry run asks the very question
/// the pass asks.
fn carried_reservation(
    graph: &Graph,
    plan: &SlotPlan,
    live: &crate::regalloc::LiveModel,
    clobbers: &[(usize, Vec<crate::regalloc::PhysReg>)],
    gp_reg_of: &[Option<u8>],
    taken: &[u8],
) -> Vec<(usize, u8)> {
    let n = graph.nodes.len();
    let mut out: Vec<(usize, u8)> = Vec::new();
    let mut free: Vec<u8> = ir_gp_file()
        .iter()
        .copied()
        .filter(|r| !taken.contains(r))
        .collect();
    // `carried_and_read`, not `carried` (round 11 wave 6): a value live
    // THROUGH the loop and read only after it covers the back edge too,
    // but it is not read on any iteration, so a register reserved for it
    // idles for the whole loop. The crossblock budget above counts with
    // this same predicate.
    let mut cands: Vec<(u64, usize)> = (0..n)
        .filter(|&id| live.carried_and_read.get(id).copied().unwrap_or(false))
        .filter(|&id| gp_reg_of.get(id).copied().flatten().is_none())
        // Write-through needs a home to write, exactly as the main loop
        // above requires.
        .filter(|&id| plan.node_color.get(id).copied().flatten().is_some())
        .filter(|&id| {
            match graph.nodes.get(id) {
                // `Ref` is excluded for the safepoint reason the bank match
                // gives, not as tuning: `OopMapEntry` names frame slots
                // only. FP belongs to the other file.
                Some(node) => {
                    matches!(node.ty, IrType::Int | IrType::Long)
                    // A constant is materialised as an immediate by every
                    // reader, so its register could never be read.
                    && !matches!(node.op, Op::Const(_))
                    // A phi is only publishable when its edges publish it.
                    && (ir_phi_residency_enabled() || !matches!(node.op, Op::Phi))
                }
                None => false,
            }
        })
        .map(|id| (live.weight.get(id).copied().unwrap_or(0), id))
        .collect();
    cands.sort_unstable_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    for (_, id) in cands {
        let Some(range) = plan.range.get(id).copied().flatten() else {
            continue;
        };
        // The same clobber question the demotion pass asks. Inert for this
        // file today — every register in it is callee-saved and no fixed
        // x86 operand names one — but asking it here keeps the two places
        // that hand out a register from disagreeing about the rule.
        let Some(pos) = free.iter().position(|r| {
            !clobbered_within(
                clobbers,
                range.lo,
                range.hi,
                crate::regalloc::PhysReg::gp(*r),
            )
        }) else {
            continue;
        };
        let reg = free.remove(pos);
        out.push((id, reg));
        if free.is_empty() {
            break;
        }
    }
    out
}

fn plan_register_residency(
    graph: &Graph,
    schedule: &Schedule,
    plan: &SlotPlan,
) -> CompileResult<Option<RegResidency>> {
    let mut live = crate::regalloc::build_live_model(graph, schedule);
    plan_register_residency_with(graph, schedule, plan, &mut live)
}

/// [`plan_register_residency`] over a liveness model the caller built and
/// keeps. The only mutation is to `live.pinned` (`pin_values` and the two pin
/// releases), so on return every other field is still exactly
/// `build_live_model(graph, schedule)`'s answer, and `lower_inner_attempt`
/// hands the same model to `emit_osr_entry_stubs` (which reads `converged`,
/// `span` and `range` only) instead of building it a second time
/// (`r11w4-ircore-live-model-built-twice-per-osr-compile`).
fn plan_register_residency_with(
    graph: &Graph,
    schedule: &Schedule,
    plan: &SlotPlan,
    live: &mut crate::regalloc::LiveModel,
) -> CompileResult<Option<RegResidency>> {
    use crate::regalloc::{
        allocate_linear_scan, verify_allocation, PhysReg, RegClass, RegFile, RegSpec,
    };

    if !live.converged {
        // Every range is the whole method; nothing is promotable and the scan
        // would only burn compile time proving it.
        return Ok(ls_refuse("liveness model did not converge"));
    }

    // ── Release the deopt pins, and why that is legal HERE ───────────
    //
    // Without this the wiring is inert on every real method. `IrBuilder`
    // records a `SafepointSnapshot` of the locals and the operand stack at
    // EVERY bytecode boundary, so every temporary is named by some frame state
    // and `build_live_model` pins the entire value set — `allocate_linear_scan`
    // then promotes nothing at all, on any graph that came from bytecode.
    //
    // The pin's premise is "the home word must hold the value at any recorded
    // bci, and an allocator cannot establish that". This consumer establishes
    // it by construction rather than by analysis: `fp_store_value` emits the
    // home store at EVERY definition, promoted or not, so a deopt frame read
    // out of home words is bit-identical to the one the colourer-only path
    // produces. `build_deopt_points` is not modified and does not need to be.
    //
    // The price, per `release_deopt_pins`' contract, is `Allocation::stack_slot`
    // — which this file must not read, and does not: every home offset comes
    // from `plan_slots`, which keeps every pin, through `alloc_slot_checked`.
    // Since R7 the prohibition is also enforced structurally: the
    // `adopt_home_colouring` call below overwrites `stack_slot` with
    // `plan_slots`' layout, so there is no longer a released-pin colouring in
    // the allocation for a future reader to find.
    // The third pin population `plan_slots` has and `build_live_model` cannot
    // see: scalar-replacement field values (a rematerialising deopt reads them
    // from their home words). Pinned FIRST so the model's pin set is exactly
    // `plan_slots`' before anything is released -- for this consumer the
    // release below takes them straight back off, by the same write-through
    // argument as every deopt pin, so this changes no allocation; it keeps the
    // two pin sets identical by construction for any reader of `live.pinned`
    // in between (`regalloc-live-model-misses-scalar-replacement-pins`).
    live.pin_values(plan.sr_field_values.iter().copied());
    let released = live.release_deopt_pins(graph);
    // Phis too, when their edges publish them (see `emit_phi_copies`).
    if ir_phi_residency_enabled() {
        live.release_phi_pins(graph);
    }
    // Round 13 wave 11 (lane callcost5, proposal CC4-3): the values the
    // refusal loop below is CERTAIN to refuse never enter the scan, so they
    // cannot push a value that IS kept into a register nobody else needed.
    // See `ir_ls_prepin_refused_enabled`.
    if ir_ls_prepin_refused_enabled() {
        let refused = ls_certain_refusals(graph, schedule, live);
        live.pin_values(refused);
    }
    // Read-only from here on.
    let live: &crate::regalloc::LiveModel = live;

    // ── Agreement check: two liveness models, one program ────────────
    //
    // `build_live_model` re-implements `plan_slots`' position model rather than
    // calling it (`SlotPlan` and `LiveRange` are private to this file). Two
    // implementations of one model drifting apart is precisely how a register
    // allocator comes to alias two live values, so the agreement is CHECKED
    // before either is used, not documented and hoped for.
    //
    // A disagreement disables promotion entirely. It is not a bailout: the
    // colourer's answer is still correct on its own terms, and it is the one
    // the frame is built from.
    let expected_positions: usize = schedule
        .blocks
        .iter()
        .map(|b| b.nodes.len() + usize::from(b.terminator.is_some()) + 1)
        .sum();
    if live.total_positions != expected_positions {
        return Ok(ls_refuse("position models disagree (live vs schedule)"));
    }
    // Two enumerations of "does this op define a value" have to agree here:
    // `regalloc::ir_op_defines_value` (via `wants_loc`) and `ir_lower`'s own
    // `op_defines_result_slot` (via `node_color`). They are the second and
    // third of the three enumerations the module comment at
    // `the_three_ir_op_enumerations` names, and a disagreement declines the
    // whole method.
    //
    // Name the OP that disagrees, not just the fact. "Declined" sends the
    // reader looking through fifty variants; "declined because `Op::X` is in
    // one enumeration and not the other" is a one-line fix with a test.
    let disagreement = if live.wants_loc.len() != plan.node_color.len() {
        Some("node-count mismatch".to_string())
    } else {
        live.wants_loc
            .iter()
            .zip(plan.node_color.iter())
            .enumerate()
            .find(|(_, (wants, color))| **wants != color.is_some())
            .map(|(id, (wants, _))| {
                let op = graph
                    .nodes
                    .get(id)
                    .map(|node| format!("{:?}", node.op))
                    .unwrap_or_else(|| "<out of range>".to_string());
                let (yes, no) = if *wants {
                    ("liveness", "colourer")
                } else {
                    ("colourer", "liveness")
                };
                format!("n{id} ({op}): {yes} says it wants a home, {no} says it does not")
            })
    };
    if let Some(what) = disagreement {
        return Ok(ls_refuse(&format!(
            "liveness and colourer disagree about which values want a home -- {what}"
        )));
    }

    // ── The register file ────────────────────────────────────────────
    //
    // Two banks, not one. The GP half is what makes an `int` loop counter
    // register-resident; the FP half is unchanged.
    let gp_specs = ir_gp_file().iter().map(|&n| RegSpec {
        reg: PhysReg::gp(n),
        // RBX and R12–R15 are callee-saved on BOTH ABIs, and this prologue
        // saves every one it hands out (`IR_LOWER_SAVED_GPRS` is the whole
        // file), so `caller_saved` is uniformly false and a value may live
        // across a call. That is exactly the property the GP file was selected
        // for: this backend emits calls constantly and has no reload
        // machinery, so a value whose register did not survive a call could
        // not be promoted at all.
        caller_saved: !IR_LOWER_SAVED_GPRS.contains(&n),
    });
    let xmm_specs = IR_LOWER_LS_XMMS.iter().map(|&n| RegSpec {
        reg: PhysReg::xmm(n),
        // Not "the ABI says so" but "does THIS frame save it", which is the
        // property that matters: a value may stay in a register across a call
        // exactly when the callee is obliged to give it back.
        //
        // XMM2–XMM5 are volatile on both ABIs, so a value in one dies at every
        // call and `caller_saved: true` is what makes the allocator split it.
        // XMM6/XMM7 are volatile on System V too — `IR_LOWER_SAVED_XMMS` is
        // empty there, so they come out `true` as well and nothing changes. On
        // Windows they are non-volatile AND this prologue saves them, so they
        // come out `false` and a value CAN live across a call. That is the
        // whole return on the save area, and it is expressed here rather than
        // in a platform `cfg` because the two facts that make it true — the
        // ABI's and this frame's — are both already in `IR_LOWER_SAVED_XMMS`.
        caller_saved: !IR_LOWER_SAVED_XMMS.contains(&n),
    });
    let regs = RegFile::from_specs(gp_specs.chain(xmm_specs));
    let model = ir_lower_machine_model(graph, schedule, live, regs);

    let mut alloc = match allocate_linear_scan(graph, live, &model) {
        Ok(alloc) => alloc,
        // Register pressure, an unsatisfiable fixed constraint or an exhausted
        // split budget is a property of the input program, not a compiler bug.
        // Decline to promote and keep the frame layout the colourer already
        // produced; there is no reason to lose the whole optimized body over
        // an optimization that did not fit.
        Err(_) => {
            return Ok(ls_refuse(
                "linear scan declined (pressure, fixed constraint or split budget)",
            ))
        }
    };
    // `allocate_linear_scan` verifies its own result. Re-verify anyway: this
    // call site's guarantee must not rest on an internal detail of another
    // module, and the check is the only thing standing between a bug in the
    // scan and machine code that reads a register two values are in.
    //
    // THIS one propagates. A verifier failure is a compiler bug, and emitting
    // against an allocation nothing proved is exactly the trade that has
    // produced silent heap corruption in this VM before.
    verify_allocation(graph, live, &model, &alloc)?;

    // ── R7: adopt this frame's colouring, do not compare against it ──
    //
    // `ls_color_homes` and `plan_slots` both colour home words and only the
    // second one lays out a frame anybody addresses. They cannot be compared —
    // `NOTES-regalloc.md` §4's proposed `stack_slot[id] == node_color[id]`
    // fires on every SUCCESSFUL allocation, because a value promoted for its
    // whole range consumes no `ls_color_homes` colour and shifts every colour
    // after it, and that shift is the frame-size win rather than a drift. The
    // full argument is at `Allocation::stack_slot`.
    //
    // So hand the emitter's layout over instead. From here every
    // `ValueLoc::Slot` payload `alloc.location_at` produces names a word
    // `emit_safepoint_map` and this file's encoder can address, rather than a
    // word in a parallel numbering that happens to be unread today (the one
    // consumer, `ls_split_candidate`, keeps only the `Reg` arm).
    //
    // That "unread today" is the whole reason to do it now rather than when
    // something breaks. `release_deopt_pins` above is paid for with exactly
    // this: `ls_color_homes` ran against a model whose deopt pins were
    // released, so `alloc.stack_slot` may alias two values a deopt frame names
    // and is NOT a layout anything may emit from. The note at that call says
    // this file "must not read" it. A prohibition is the weakest possible form
    // of that guarantee — it holds until someone adds a reader. Replacing the
    // contents removes the thing that must not be read.
    //
    // The `?` is correct: `adopt_home_colouring` refuses only a layout with no
    // word for a value that spends time in memory, which is a compiler bug in
    // exactly the sense the `verify_allocation` above propagates. It should not
    // be reachable — the agreement check above has already established that
    // `plan.node_color` is `Some` for precisely the nodes `live.wants_loc`
    // marks, and every node with a memory segment is one of those.
    //
    // **`verify_allocation` is deliberately NOT re-run afterwards**, although
    // `adopt_home_colouring`'s own doc comment offers that as the payoff. Proof
    // 6 asks whether two values sharing a home word have disjoint ranges, and
    // it asks it of `live.range` — the ALLOCATOR's liveness, after the pin
    // releases above. `plan_slots` colours against its own ranges and its own
    // (unreleased, therefore larger) pinned set. The agreement check compares
    // the two models' POSITION COUNT and their wants-a-home sets; it does not
    // compare their ranges, so "disjoint under `plan.range`" does not imply
    // "disjoint under `live.range`" by anything checked here. Re-verifying
    // would therefore risk turning a method that compiles correctly today into
    // a `BailoutReason::Internal`, which is a worse trade than leaving proof 6
    // where it is. `verify_slot_colouring` already proves the no-aliasing
    // property of this colouring against the ranges it was computed from.
    alloc.adopt_home_colouring(&plan.node_color, plan.slots)?;

    let n = graph.nodes.len();
    let mut reg_of: Vec<Option<u8>> = vec![None; n];
    let mut gp_reg_of: Vec<Option<u8>> = vec![None; n];
    let mut demoted = 0usize;
    // Per-CAUSE refusal census. A bare "promoted 0 of N" is a count and cannot
    // be acted on: the causes below call for different next steps. `skip_phi`
    // used to be the one that decided whether this file could ever reach a LOOP
    // COUNTER -- which is a phi, at every loop header -- because it meant
    // "refused for BEING a phi". Since phis are admitted it means only "the
    // sub-flag is off", and the question it used to stand for is answered in
    // full by `PhiCensus` below.
    let (mut skip_split, mut skip_bank, mut skip_home, mut skip_phi) = (0usize, 0, 0, 0);
    // The phi-scoped half of the census, RECORDED here and TALLIED at the
    // bottom of this function. See `PhiCensus` for why the tally cannot happen
    // at the `continue`s below.
    let mut phi_refusal: Vec<Option<PhiRefusal>> = vec![None; n];
    // Split apart from `skip_split` on 2026-09-03: see the refusal below.
    let (mut skip_no_alloc, mut skip_spilled) = (0usize, 0usize);
    // Parameters copied into a callee-saved register by the prologue.
    let mut param_copies = 0usize;

    // ── R4: the split values, and the two gates in front of them ─────
    //
    // `skip_split` goes on counting exactly what it counted before — values the
    // scan split and this file then refused — so the census measures the
    // before/after population with no new instrumentation: turning
    // `CRATONVM_JIT_IR_LS_SPLITS` on moves nodes out of `split_or_spilled=` and
    // into `split_taken=`, and `split_unplaceable=` says how many of them this
    // file looked at and could not prove.
    let ls_splits = ir_ls_splits_enabled();
    // **The second-opinion gate, and it is load-bearing.** Two passes below
    // re-prove the allocation's aliasing property against `plan_slots`'
    // independently computed ranges, by asking "do two values sharing a
    // register have overlapping WHOLE ranges". For a split value that question
    // has the wrong answer by construction — a value is split precisely so that
    // another value can use its register while it is elsewhere — so the pass
    // would demote every one of them, and a `drop_ids` hit that cleared the
    // register while the transition table still named it would be worse than
    // useless.
    //
    // The pass is therefore skipped for managed values and replaced by a
    // stronger, simpler fact: the two liveness models agree about EVERY value
    // in the method. If they do, `verify_allocation`'s proof — which is over
    // `live` — is a proof over `plan` as well, and there is no second opinion
    // left to take. If they do not agree anywhere, no value is split-promoted
    // at all, which is exactly today's behaviour and costs nothing that was not
    // already being lost.
    //
    // Interpreter round i2 wave 65 (lane L2): the φ ranges agree only under
    // `CRATONVM_JIT_IR_SLOTS_PHI_EDGE_RANGES`
    // (`i64-L2-ranges-agree-is-false-for-every-graph-with-a-phi`).
    let ranges_agree = slot_and_live_ranges_agree(plan, live);
    let node_pos = ls_node_positions(schedule, live);
    // A split timeline is in LAYOUT order and the allocator does no edge
    // resolution; a value whose register claim at a block top is not honoured
    // on some other incoming edge cannot be followed position by position.
    // Such a value is refused below exactly like every other `ls_split_place`
    // refusal (round 9 wave 2, regalloc request A;
    // `linear-scan-split-timeline-has-no-edge-resolution-20260918.md`).
    // `alloc` is the post-adopt allocation; adoption does not touch
    // `segments`, which is all the detector reads.
    let edge_conflicts = crate::regalloc::split_edge_conflicts(schedule, live, &alloc);
    // Round 9 wave 6 (irlower6): the resolution half. With
    // `CRATONVM_JIT_IR_LS_EDGE_RESOLUTION` on, a flagged value is admitted
    // after all when the allocator can name a repair for every edge it is wrong
    // on (`!unresolvable`), every such edge leaves a block with an
    // edge-specific copy site, and the value is not a reference (a `Ref`
    // loaded on an edge would be a register copy of a root published outside
    // `lower_block`'s invalidation audit; the argument is not written, so it
    // stays refused). The copies themselves are collected after the demotion
    // passes, for the values that survive them (`ls_edges` below).
    let edge_resolution = if ls_splits && ir_ls_edge_resolution_enabled() {
        Some(crate::regalloc::split_edge_resolution(
            schedule, live, &alloc,
        ))
    } else {
        None
    };
    let edge_repairable: Vec<bool> = match &edge_resolution {
        None => vec![false; n],
        Some(res) => {
            let mut ok: Vec<bool> = (0..n)
                .map(|id| {
                    edge_conflicts.get(id).copied().unwrap_or(false)
                        && !res.unresolvable.get(id).copied().unwrap_or(true)
                        && matches!(
                            graph.nodes.get(id).map(|node| node.ty),
                            Some(IrType::Int | IrType::Long | IrType::Float | IrType::Double)
                        )
                })
                .collect();
            for edge in &res.edges {
                if !ls_edge_copy_site_exists(graph, schedule, edge.pred) {
                    for &v in &edge.nodes {
                        if let Some(cell) = ok.get_mut(v as usize) {
                            *cell = false;
                        }
                    }
                }
            }
            ok
        }
    };
    let ls_admitted = ls_splits && ranges_agree;
    // `(node, gp, transitions)` for every value this pass placed. Collected
    // here and turned into a position table at the bottom, after the demotion
    // passes have had their say.
    let mut split_taken: Vec<(usize, bool, Vec<(usize, LsTransition)>)> = Vec::new();
    let mut split_managed = vec![false; n];
    let mut skip_split_unplaceable = 0usize;
    // LV11-3 refusals (counted inside `unplaceable=` as well).
    let mut split_no_gain = 0usize;
    // 2026-09-02, measured: promotion is not free, and two populations pay for
    // it without ever collecting.
    //
    // A register costs a PROLOGUE SAVE and a restore at every exit (the file is
    // callee-saved by construction), plus one publish load at the definition.
    // It repays that at each READ it turns into a register move. So a value
    // read once breaks even at best, and on a small call-heavy method the
    // saves dominate: `FibProbe.fib` promoted five registers, was measured
    // 145-149 ms against 110-133 ms for the same binary with the file off, and
    // the disassembly showed why -- four of the five registers were published
    // and never read.
    //
    // A CONSTANT is worse than break-even: since `ir_const_imm_enabled` every
    // reader materialises it as an immediate, so its register can never be
    // read at all.
    let mut use_count = vec![0u32; n];
    for node in &graph.nodes {
        for &input in &node.inputs {
            if input != NO_NODE {
                if let Some(c) = use_count.get_mut(input as usize) {
                    *c = c.saturating_add(1);
                }
            }
        }
    }
    let (mut skip_const, mut skip_single_use) = (0usize, 0usize);
    // What `ir_reserve_carried_enabled`'s pass will want, computed with ITS
    // predicate so the two cannot disagree about who is a candidate. Its own
    // `gp_reg_of[id].is_none()` filter is the one thing left out -- nothing is
    // assigned yet, and the point here is to reserve room BEFORE that happens.
    // See `ir_residency_crossblock_budget_enabled`.
    let mut carried_w: Vec<u64> = (0..n)
        .filter(|&id| live.carried_and_read.get(id).copied().unwrap_or(false))
        .filter(|&id| plan.node_color.get(id).copied().flatten().is_some())
        .filter(|&id| match graph.nodes.get(id) {
            Some(node) => {
                matches!(node.ty, IrType::Int | IrType::Long)
                    && !matches!(node.op, Op::Const(_))
                    && (ir_phi_residency_enabled() || !matches!(node.op, Op::Phi))
            }
            None => false,
        })
        .map(|id| live.weight.get(id).copied().unwrap_or(0))
        .collect();
    // Descending, because the carried pass serves its own candidates in that
    // order (`cands.sort_unstable_by(|a, b| b.0.cmp(&a.0)...)`) and the register
    // a crossblock value takes comes off the BOTTOM of that list.
    carried_w.sort_unstable_by(|a, b| b.cmp(a));
    let carried_demand = carried_w.len();
    let (mut crossblock_taken, mut crossblock_over) = (0usize, 0usize);
    // CC5-1 (`ir_residency_call_crossing_enabled`): its admissions are charged
    // to `crossblock_taken` too (they spend the same registers), and counted
    // on their own for the census.
    let call_pos = ls_call_positions(graph, live);
    let mut call_crossing_taken = 0usize;
    for id in 0..n {
        let Some(segs) = alloc.segments.get(id) else {
            continue;
        };
        // ── Is this a phi, and does the phi mechanism apply at all? ──────
        //
        // Hoisted to the TOP of the loop body, ahead of every other refusal.
        // It used to sit at the bottom, after the bank and home checks, which
        // made the general census double-count: with the mechanism off a phi
        // was tallied under `no_alloc`/`split`/`wrong_bank_or_type` on its way
        // past those checks and then again under `phi`, so `phi=` read as a
        // number of phis while the other fields read as "candidates lost to
        // register pressure" and counted the same nodes. Asking first makes
        // every cause below disjoint, which is the property the phi census's
        // accounting identity rests on.
        //
        // Emission is unchanged by the move: both arms `continue`.
        //
        // **`is_value_ty`, and it is not a formality.** `IrBuilder` builds a
        // MEMORY phi at every merge it builds a value phi at — a counted loop
        // has one at its header — and `build_live_model` sets `wants_loc` for
        // every `Op::Phi` regardless of type, so a memory phi arrives here
        // looking exactly like a candidate. It is not one: `RegClass::of`
        // answers `None` for `Memory`, `allocate_linear_scan` skips it, and it
        // reaches the `[]` arm below with an empty segment list. Counting it as
        // a phi that lost would put one guaranteed refusal per loop into the
        // census, which is precisely how a census stops being read.
        //
        // So a memory phi is not a phi *for this file's purposes*: it takes the
        // unchanged no-candidate path and appears in no phi field.
        let phi_candidate = graph
            .nodes
            .get(id)
            .is_some_and(|node| matches!(node.op, Op::Phi) && is_value_ty(node.ty));
        // 2026-09-02: with `ir_phi_residency_enabled`, `emit_phi_copies` IS
        // the publishing site — every incoming edge writes the home word and
        // then moves the value into the phi's register — so a phi is admitted
        // like any other value, and the allocator's structural pin was
        // released by `release_phi_pins` above on the same condition. With the
        // sub-flag off there is no site that could publish one, and the
        // refusal below is the whole of the pre-2026-09-02 behaviour.
        if phi_candidate && !ir_phi_residency_enabled() {
            skip_phi += 1;
            phi_refusal[id] = Some(PhiRefusal::Disabled);
            continue;
        }
        // ── The safepoint obligation, refused BY TYPE ────────────────────
        //
        // A GC root walk reads a frame it did not stop, through RBP, and
        // `OopMapEntry` names frame slots only — so no reference may be
        // register-resident at a safepoint unless something drops the copy at
        // every point a collector could have run. For ordinary values that
        // something exists (`invalidate_ref_residency`, behind
        // `CRATONVM_JIT_IR_REF_RESIDENCY`, itself default OFF) and its audit is
        // `lower_block`'s per-node loop: every node that is not
        // `op_cannot_deopt` invalidates immediately after it is lowered, so a
        // register copy published by a definition arm cannot survive a GC point
        // it precedes.
        //
        // **A phi is published somewhere that audit does not reach.** Its
        // publish site is `emit_phi_copies`, which runs on the EDGE — after the
        // predecessor's terminator, after the back-edge poll's own
        // invalidation, and before the successor block's node loop starts. That
        // is a publish outside the loop that owns the invariant. It may well be
        // sound; what does not exist is the argument, and a `Ref` phi is the
        // one shape where being wrong is a collector reading a stale pointer
        // rather than a wrong `int`.
        //
        // A `Ref` phi is also the shape with the most to lose: `zero_ref_phi_slots`
        // zeroes every `Ref` phi's home word in the prologue precisely so that
        // word is a publishable GC root from the first safepoint on, before any
        // edge copy has run. The home is therefore a root the collector both
        // READS and WRITES, and a register copy of it is a copy of something
        // evacuation moves.
        //
        // So: refused, unconditionally, **by `IrType`** and not by which bank
        // the type happens to land in. Stating it as a type test is the point —
        // the bank match below would refuse a `Ref` today only because
        // `ir_ref_residency_enabled()` is off, and a future default flip there
        // would silently admit `Ref` phis through an arm written for values
        // with a different publish site. Admitting them needs the edge-publish
        // audit written and tested first, and an owner: nobody has one, so this
        // is a refusal rather than a `TODO`.
        if phi_candidate && matches!(graph.nodes.get(id).map(|node| node.ty), Some(IrType::Ref)) {
            // Counted in the general aggregate too, where it has always
            // landed, so `wrong_bank_or_type` does not change meaning.
            skip_bank += 1;
            phi_refusal[id] = Some(PhiRefusal::RefType);
            continue;
        }
        // A value the carry window cannot reach, and whether the budget still
        // has room for it. `crossblock_candidate` is what it IS;
        // `crossblock_admit` is what this method can still afford.
        let crossblock_candidate = ir_residency_crossblock_enabled()
            && use_count.get(id).copied().unwrap_or(0) == 1
            && !single_use_is_in_the_carry_window(graph, schedule, id);
        let crossblock_admit = crossblock_candidate
            && (!ir_residency_crossblock_budget_enabled()
                || live.weight.get(id).copied().unwrap_or(0)
                    >= carried_displacement_price(&carried_w, crossblock_taken));
        if crossblock_candidate && !crossblock_admit {
            crossblock_over += 1;
        }
        let call_crossing_candidate = !crossblock_candidate
            && single_use_crosses_a_call(
                graph,
                live,
                &call_pos,
                id,
                use_count.get(id).copied().unwrap_or(0),
            );
        let call_crossing_admit = call_crossing_candidate
            && (!ir_residency_crossblock_budget_enabled()
                || live.weight.get(id).copied().unwrap_or(0)
                    >= carried_displacement_price(&carried_w, crossblock_taken));
        if ir_residency_pays_enabled() {
            match graph.nodes.get(id).map(|node| &node.op) {
                Some(Op::Const(_)) => {
                    skip_const += 1;
                    continue;
                }
                // A phi is exempt: its reads are inside the loop it carries a
                // value around, which is the whole population this file exists
                // for, and its "definition" is an edge copy that is already
                // paying the store.
                Some(Op::Phi) => {}
                // The `< 2` rule below counts STATIC graph edges. That is the
                // right comparison only when the definition and the uses run
                // equally often, and in a loop they do not: a value defined at
                // method entry and read once per iteration is one publish
                // against N reads, and the static count sees 1 and refuses.
                //
                // Measured on the loop the 2026-09-03 tier comparison found
                // inverted: `Param(0)` (the receiver) and `Param(1)` (the loop
                // bound) both read `static_uses=1 loop_weight=10` — refused by
                // a rule that could not see the ten. The disassembly showed
                // exactly that, `mov rax,[rbp-58h]` and `mov rcx,[rbp-60h]`
                // reloaded every iteration, while the baseline tier held both
                // in callee-saved registers.
                //
                // The loop-aware form compares the uses' frequency against the
                // DEFINITION's: residency pays when the reads happen at least
                // twice as often as the single publish. It reduces exactly to
                // `use_count >= 2` when everything sits at depth 0, so a
                // method with no loop is byte-identical.
                // The single-use refusal, and the one population it must not
                // refuse: a value the carry window cannot reach. See
                // `ir_residency_crossblock_enabled` -- for those the
                // alternative to a register is a home store AND a reload, not
                // the free RAX hand-off the refusal assumes.
                _ if !ir_residency_pays_here(
                    live,
                    schedule,
                    id,
                    use_count.get(id).copied().unwrap_or(0),
                ) && !crossblock_admit
                    && !call_crossing_admit =>
                {
                    skip_single_use += 1;
                    continue;
                }
                _ => {}
            }
        }
        // ONE segment, and it holds a register -- the whole-range case, which
        // needs no transition machinery at all. A spill is refused. A SPLIT
        // goes to the `_` arm below, which since R4 places it position by
        // position when `CRATONVM_JIT_IR_LS_SPLITS` is on and declines it
        // exactly as before when it is off.
        //
        // **The NO-SEGMENT case is counted separately, and that distinction is
        // not cosmetic.** A node the scan produced no interval for was never a
        // candidate — every control and memory node in the graph lands here,
        // `Start` and `Proj` included — and folding it into the split count
        // makes the file look like it is losing values to register pressure
        // when it is only being handed nodes that hold no value at all.
        //
        // It read that way for real. On the loop the 2026-09-03 tier
        // comparison found inverted, this line reported
        // `split_or_spilled=5` beside the allocator's `splits=4`, and the two
        // together said: four candidates lost to live-range splits. They were
        // not. Four of the five had EMPTY segment lists and one was genuinely
        // spilled; the method had no split value for the file to reclaim at
        // all. A day of work aimed at split residency followed from that
        // reading, and its engagement counter read zero — which is how the
        // miscount was found.
        let reg = match segs.as_slice() {
            [] => {
                skip_no_alloc += 1;
                if phi_candidate {
                    phi_refusal[id] = Some(PhiRefusal::NoRegister);
                }
                continue;
            }
            [seg] => match seg.reg {
                Some(reg) => reg,
                None => {
                    skip_spilled += 1;
                    if phi_candidate {
                        phi_refusal[id] = Some(PhiRefusal::NoRegister);
                    }
                    continue;
                }
            },
            _ => {
                // ── R4: the split arm, which used to decline outright ────
                //
                // Everything this arm needs is decided here rather than falling
                // through to the checks below, because those are written around
                // ONE register for a whole range and a split value has several.
                // The bank test is the same one, made once per segment through
                // `ls_bank_for`, so the two cannot drift.
                //
                // A PHI is not admitted. Its publish site is `emit_phi_copies`,
                // which runs on the edge — outside the per-node loop that owns
                // the invalidation audit, and with its own register discipline
                // for reading sources and staging destinations. Admitting one
                // needs that argument written; it is not, so this is a refusal
                // and not a `TODO`.
                let edges_ok = !edge_conflicts.get(id).copied().unwrap_or(true)
                    || edge_repairable.get(id).copied().unwrap_or(false);
                let placed = if ls_admitted && !phi_candidate && edges_ok {
                    ls_split_place(graph, plan, live, &alloc, id, segs.as_slice(), &node_pos)
                } else {
                    None
                };
                // JIT round 19 proposal wave 12, lane lv12 (LV11-3,
                // `CRATONVM_JIT_IR_LS_SPLITS_REFUSE_NO_GAIN`): a placement whose
                // register segments serve no more (loop-weighted) reads than
                // the loads that fill them buys nothing over the memory
                // operand, and still withholds its registers from the carried
                // pass. Refused like every other `ls_split_place` refusal.
                let placed = match placed {
                    Some((_, _, ref transitions))
                        if ir_ls_splits_refuse_no_gain_enabled()
                            && split_register_benefit(live, id, segs.as_slice(), transitions)
                                <= 0 =>
                    {
                        split_no_gain += 1;
                        None
                    }
                    other => other,
                };
                match placed {
                    Some((gp, first, transitions)) => {
                        split_managed[id] = true;
                        if gp {
                            gp_reg_of[id] = first;
                        } else {
                            reg_of[id] = first;
                        }
                        split_taken.push((id, gp, transitions));
                    }
                    None => {
                        if ls_admitted && !phi_candidate {
                            skip_split_unplaceable += 1;
                        }
                        skip_split += 1;
                        if phi_candidate {
                            phi_refusal[id] = Some(PhiRefusal::NoRegister);
                        }
                    }
                }
                continue;
            }
        };
        let ty = graph.nodes.get(id).map(|node| node.ty);
        // Which bank, and is the type one that bank may hold?
        //
        // **`IrType::Ref` is admitted by neither, and that is the safepoint
        // obligation, not a tuning choice.** A GC root walk reads a frame it
        // did not stop, through RBP, and `OopMapEntry` names frame slots only —
        // there is no register a collector could be told about, walk, or update
        // on an evacuation. The XMM file discharged this structurally (no
        // register a `Ref` could occupy); the GP file has to discharge it by
        // refusing the type here, which is what this match does and what
        // `a_reference_is_never_promoted_into_the_gp_file` pins.
        //
        // Everything else in the match is defensive: a register outside its own
        // file, or a type outside its bank, means the file or `RegClass::of`
        // changed under this code.
        let is_gp = match (reg.class, ty) {
            (RegClass::Xmm, Some(IrType::Float) | Some(IrType::Double))
                if IR_LOWER_LS_XMMS.contains(&reg.num) =>
            {
                false
            }
            (RegClass::Gp, Some(IrType::Int) | Some(IrType::Long))
                if IR_LOWER_LS_GPRS.contains(&reg.num) =>
            {
                true
            }
            // A REFERENCE, under `CRATONVM_JIT_IR_REF_RESIDENCY`. **A `Ref`
            // PHI never reaches this arm** -- it was refused by type above,
            // because its publish site is the edge copy and this arm's
            // invalidation argument is about definition arms. Read the
            // paragraph above and then this one: what that paragraph states is
            // the obligation, and the obligation is discharged rather than
            // waived. The home word is still written at the definition (a
            // `Ref` is refused by `value_home_droppable` and
            // `phi_home_droppable` exactly as before), so `emit_safepoint_map`
            // publishes a slot the collector can read AND update; the register
            // is a copy, and `invalidate_ref_residency` drops it at every point
            // a collector could have run, so the next read reloads the word the
            // collector just rewrote. No reference is ever a root the map does
            // not name, and `OopMapEntry` needs no register bank.
            (RegClass::Gp, Some(IrType::Ref))
                if ir_ref_residency_enabled() && IR_LOWER_LS_GPRS.contains(&reg.num) =>
            {
                REF_RESIDENCY_ADMITTED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                true
            }
            _ => {
                skip_bank += 1;
                if phi_candidate {
                    // NOT `RefType`: the `Ref` refusal above already took every
                    // `Ref` phi, so anything reaching here is a phi whose type
                    // and bank disagree for some other reason — which means the
                    // file or `RegClass::of` moved under this match.
                    phi_refusal[id] = Some(PhiRefusal::WrongBank);
                }
                continue;
            }
        };
        // Write-through needs a home to write to.
        if plan.node_color.get(id).copied().flatten().is_none() {
            skip_home += 1;
            if phi_candidate {
                phi_refusal[id] = Some(PhiRefusal::NoHome);
            }
            continue;
        }
        // The home check above is deliberately NOT `SlotClass::Pinned`. That
        // class means "never shares a frame word", and after
        // `release_deopt_pins` it covers exactly the deopt-named values — i.e.,
        // on a bytecode graph, nearly all of them. Testing it here would undo
        // the release and make this wiring inert again. A dedicated home word
        // is if anything the safer case for write-through, and for a phi it is
        // what `prealloc_phi_slots` guarantees outright.
        if is_gp {
            gp_reg_of[id] = Some(reg.num);
            // Charged HERE rather than at the guard: everything between the two
            // can still `continue`, and a budget spent on a value that never
            // got a register would starve the carried pass for nothing.
            if crossblock_candidate {
                crossblock_taken += 1;
            }
            // Only when the pays rule would have refused it: a value that
            // pays on its own spends nothing of the reservation it did not
            // spend before.
            if call_crossing_admit
                && ir_residency_pays_enabled()
                && !ir_residency_pays_here(
                    live,
                    schedule,
                    id,
                    use_count.get(id).copied().unwrap_or(0),
                )
            {
                crossblock_taken += 1;
                call_crossing_taken += 1;
            }
        } else {
            reg_of[id] = Some(reg.num);
        }
    }

    // ── Second opinion on the aliasing property ──────────────────────
    //
    // `verify_allocation` proves "no two values hold one register at one
    // position" against the ALLOCATOR's liveness model. Re-prove it against
    // `plan_slots`' independently computed ranges. If the two models disagree
    // about an overlap, both values lose the register — the disagreement
    // itself is the reason not to trust either answer for that pair.
    //
    // Keyed by `(bank, number)` now that there are two files: `Gp(3)` and
    // `Xmm(3)` are different registers, and a map keyed by the number alone
    // would report them as one holder and demote a healthy pair. That is the
    // same aliasing hazard `PhysReg` carries its class for.
    //
    // **A managed split value is not in this pass**, and the reason is in the
    // `ranges_agree` comment above: the overlap question is asked of WHOLE
    // ranges, and a split value shares its register with another value by
    // construction, so the pass would demote every one of them. What replaces
    // it is the stronger fact `ls_admitted` already requires — that the two
    // liveness models agree about every value in the method, which makes
    // `verify_allocation`'s proof a proof over `plan_slots`' ranges too and
    // leaves no second opinion to take. Nothing is skipped without that.
    let mut holders: HashMap<(bool, u8), Vec<usize>> = HashMap::new();
    for (id, reg) in gp_reg_of.iter().enumerate() {
        if let Some(reg) = reg {
            if !split_managed[id] {
                holders.entry((true, *reg)).or_default().push(id);
            }
        }
    }
    for (id, reg) in reg_of.iter().enumerate() {
        if let Some(reg) = reg {
            if !split_managed[id] {
                holders.entry((false, *reg)).or_default().push(id);
            }
        }
    }
    let mut drop_ids: Vec<usize> = Vec::new();
    for ids in holders.values() {
        for (i, &a) in ids.iter().enumerate() {
            let Some(ra) = plan.range.get(a).copied().flatten() else {
                drop_ids.push(a);
                continue;
            };
            for &b in &ids[i + 1..] {
                match plan.range.get(b).copied().flatten() {
                    Some(rb) if !ra.overlaps(rb) => {}
                    _ => {
                        drop_ids.push(a);
                        drop_ids.push(b);
                    }
                }
            }
        }
    }
    // ── Second opinion on the ABI property ───────────────────────────
    //
    // The same idea for `verify_allocation`'s clobber check: re-run it against
    // `plan_slots`' range for the value rather than the allocator's.
    for (bank, file) in [(false, &reg_of), (true, &gp_reg_of)] {
        for (id, reg) in file.iter().enumerate() {
            let Some(reg) = reg else { continue };
            // Asked per SEGMENT for a managed value, below: the whole-range
            // form would demote a value whose register is given up at exactly
            // the clobber, which is the shape splitting exists to produce.
            if split_managed[id] {
                continue;
            }
            let Some(range) = plan.range.get(id).copied().flatten() else {
                continue;
            };
            let me = if bank {
                PhysReg::gp(*reg)
            } else {
                PhysReg::xmm(*reg)
            };
            if clobbered_within_for_value(&model, live, id, range.lo, range.hi, me) {
                drop_ids.push(id);
            }
        }
    }
    // The same ABI question for a managed value, asked of each segment over the
    // positions that segment actually covers. This one is a re-assertion rather
    // than a second opinion — `verify_allocation` proves it already — and it is
    // here because a clobber the emission does not respect is a value destroyed
    // by a call it was supposed to survive, and one cheap loop is a better
    // guard than the assumption that another module's proof covers this file's
    // use of it.
    for &(id, gp, _) in &split_taken {
        let Some(segs) = alloc.segments.get(id) else {
            continue;
        };
        let bad = segs.iter().any(|seg| {
            let Some(reg) = seg.reg else { return false };
            let me = if gp {
                PhysReg::gp(reg.num)
            } else {
                PhysReg::xmm(reg.num)
            };
            clobbered_within_for_value(&model, live, id, seg.range.lo, seg.range.hi, me)
        });
        if bad {
            drop_ids.push(id);
        }
    }
    for id in drop_ids {
        // A node lives in at most one bank (its type picks the bank), so
        // clearing both is clearing the one it is in.
        let had_register = reg_of[id].take().is_some() || gp_reg_of[id].take().is_some();
        // A demoted split value must lose its TRANSITIONS as well as its
        // register. Leaving the table naming it would publish into a register
        // the rest of this function believes is free, which is the one way this
        // pass could produce wrong code rather than slow code. It is also the
        // only demotion that has to be counted separately: a split value whose
        // allocator has it in MEMORY at its definition holds no register to
        // take away, so `had_register` alone would report it as untouched.
        let was_managed = split_managed[id];
        split_managed[id] = false;
        // `drop_ids` carries duplicates (the aliasing pass pushes both sides of
        // every overlapping pair), and both tests above are idempotent, so a
        // second visit adds nothing to the count.
        if had_register || was_managed {
            demoted += 1;
        }
    }
    split_taken.retain(|&(id, _, _)| split_managed[id]);

    // ── JIT round 19 proposal wave 11 (lane lv11): carried values first ──
    //
    // Every register a split value visits is withheld from the loop-carried
    // reservation below (`split_gp_regs`), so on a loop whose carried set is
    // larger than what the scan left, admitting a split value can cost a
    // carried accumulator its register for the WHOLE loop -- a store and a
    // reload of a loop-carried chain on every iteration -- in exchange for a
    // value whose reads were memory reads before and are register loads now
    // (`R19Lv10SplitGate.pressure`: two split values took r3 / r14 and the
    // reservation fell from 5 to 3; `lv11_tests`). Under
    // `CRATONVM_JIT_IR_LS_SPLITS_CARRIED_FIRST` a dry run of that reservation
    // with every split value demoted names the registers it would hand out,
    // and a GP split value that visits one of them yields: it is demoted to
    // its home (as every refusal here is), before its edge copies are
    // collected, so nothing is half-kept. Only ever removes split values.
    let mut split_yielded = 0usize;
    // JIT round 19 proposal wave 12, lane lv12 (LV11-2): the priced form,
    // `CRATONVM_JIT_IR_LS_SPLITS_CARRIED_PRICED`, keeps a colliding split value
    // when its register reads outweigh the carried values it displaces.
    let carried_priced = ir_ls_splits_carried_priced_enabled();
    if (ir_ls_splits_carried_first_enabled() || carried_priced)
        && ir_reserve_carried_enabled()
        && split_taken.iter().any(|&(_, gp, _)| gp)
    {
        let mut dry = gp_reg_of.clone();
        for &(id, gp, _) in &split_taken {
            if gp {
                dry[id] = None;
            }
        }
        let mut taken: Vec<u8> = dry.iter().flatten().copied().collect();
        taken.sort_unstable();
        taken.dedup();
        let assigned = carried_reservation(graph, plan, live, &model.clobbers, &dry, &taken);
        let wanted: Vec<u8> = assigned.iter().map(|&(_, reg)| reg).collect();
        for &(id, gp, ref transitions) in &split_taken {
            if !gp {
                continue;
            }
            let mut visited: Vec<u8> = gp_reg_of[id].into_iter().collect();
            for (_, t) in transitions {
                if let Some((reg, true)) = t.destination() {
                    visited.push(reg);
                }
            }
            let visits_wanted = visited.iter().any(|r| wanted.contains(r));
            let displaced: u64 = assigned
                .iter()
                .filter(|(_, reg)| visited.contains(reg))
                .map(|&(cid, _)| live.weight.get(cid).copied().unwrap_or(0))
                .fold(0u64, u64::saturating_add);
            let segs = alloc.segments.get(id).map(Vec::as_slice).unwrap_or(&[]);
            let benefit = split_register_benefit(live, id, segs, transitions);
            let yields = visits_wanted && (!carried_priced || benefit <= i128::from(displaced));
            // Wave 12 (lane lv12): one line per GP split value under
            // `CRATONVM_DBG_IR_LINEAR_SCAN`, so a host run of the probe names
            // the split values that SURVIVE the yield and what they cost
            // (the i22 A/B: E stayed near C on the real, optimised graph).
            if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
                let op = graph
                    .nodes
                    .get(id)
                    .map(|n| format!("{:?}", n.op))
                    .unwrap_or_default();
                let op = op.split([' ', '{', '(']).next().unwrap_or("?").to_string();
                let loads = transitions
                    .iter()
                    .filter(|(_, t)| matches!(t, LsTransition::Load { .. }))
                    .count();
                eprintln!(
                    "[ir-ls] split-value: n{id} {op} regs={visited:?} loads={loads} \
                     transitions={} benefit={benefit} displaced={displaced} \
                     collides={visits_wanted} yields={yields}",
                    transitions.len(),
                );
            }
            if yields {
                split_managed[id] = false;
                gp_reg_of[id] = None;
                split_yielded += 1;
            }
        }
        split_taken.retain(|&(id, _, _)| split_managed[id]);
    }

    // ── Round 9 wave 6: the edge copies the SURVIVING managed values owe ──
    //
    // Filtered to `split_managed` AFTER the demotion passes: a copy for a value
    // that lost its register would write a register the rest of this function
    // believes it no longer owns. Every copy of a surviving value is kept --
    // it was admitted precisely because all of its mismatches have one, and
    // dropping any of them would reintroduce the wrong-code shape the gate
    // exists for. A destination that is not a register is not something
    // `split_edge_resolution` produces; if it ever did, that value is demoted
    // here like any other refusal rather than left half-repaired.
    let mut ls_edges: Vec<LsEdgeCopies> = Vec::new();
    if let Some(res) = &edge_resolution {
        let mut unexpressible: Vec<usize> = Vec::new();
        for edge in &res.edges {
            for (&(dst, _), &v) in edge.copies.iter().zip(edge.nodes.iter()) {
                let v = v as usize;
                if split_managed.get(v).copied().unwrap_or(false)
                    && !matches!(dst, crate::regalloc::ValueLoc::Reg(_))
                {
                    unexpressible.push(v);
                }
            }
        }
        for v in unexpressible {
            if split_managed[v] {
                split_managed[v] = false;
                reg_of[v] = None;
                gp_reg_of[v] = None;
                demoted += 1;
            }
        }
        split_taken.retain(|&(id, _, _)| split_managed[id]);
        for edge in &res.edges {
            let mut copies: Vec<(NodeId, u8, bool)> = Vec::new();
            for (&(dst, _), &v) in edge.copies.iter().zip(edge.nodes.iter()) {
                if !split_managed.get(v as usize).copied().unwrap_or(false) {
                    continue;
                }
                if let crate::regalloc::ValueLoc::Reg(reg) = dst {
                    copies.push((v, reg.num, matches!(reg.class, RegClass::Gp)));
                }
            }
            if !copies.is_empty() {
                ls_edges.push(LsEdgeCopies {
                    pred: edge.pred,
                    succ: edge.succ,
                    copies,
                });
            }
        }
    }

    // Every GP register a surviving managed value passes through.
    //
    // The two passes below hand out registers the ALLOCATOR did not use, and
    // they identify those by scanning `gp_reg_of` — which for a managed value
    // names only the register it starts in. Without this, a register a managed
    // value moves into halfway through the method reads as free, and the
    // carried pass would give it to a loop-carried value that is live across
    // exactly the positions the managed one occupies it. That is an aliasing
    // bug, not a heuristic one: both values would be published into one
    // register while both are live, and the later publish wins.
    let mut split_gp_regs: Vec<u8> = Vec::new();
    for (_, gp, transitions) in &split_taken {
        if !*gp {
            continue;
        }
        for (_, transition) in transitions {
            if let Some((reg, true)) = transition.destination() {
                split_gp_regs.push(reg);
            }
        }
    }
    // An edge copy's destination is a register the value visits too (round 9
    // wave 6). It is also a timeline register of that value at a node position,
    // so this should add nothing new; it is listed anyway, because a register
    // left out of this set is one the passes below may hand to somebody else.
    for edge in &ls_edges {
        for &(_, reg, gp) in &edge.copies {
            if gp {
                split_gp_regs.push(reg);
            }
        }
    }
    split_gp_regs.sort_unstable();
    split_gp_regs.dedup();

    // ── The loop-carried set, reserved out of what the scan left ─────
    //
    // Same door the parameter copy below uses, and the same safety argument:
    // **a register in this file that the accepted set does not name is written
    // by nothing.** Emission is driven by `gp_reg_of` alone, so a register the
    // scan used only for values this file then REFUSED is not written by the
    // emitted code either, and taking it here cannot alias anything.
    //
    // What it fixes is not a bad decision by the scan but a bad QUESTION put to
    // it. The scan allocates the carried values in competition with every
    // transient in the loop body, under `peak_live` far above the file size, so
    // it splits them — and `plan_register_residency` refuses a split value
    // outright, because this backend has no reload machinery. Reserving first
    // asks instead: these few values are needed on every iteration, give each
    // one a register and let everything else have the rest.
    //
    // Ordered by loop-weighted use count so that, when the carried set is
    // larger than the file, the registers go to the values read most often
    // inside the loop.
    //
    // Publishing is already handled and needs nothing new: a phi is published
    // by `emit_phi_copies` at every incoming edge, and any other value by the
    // generic publish at the end of its own `lower_data_node`. Both are keyed
    // on `assigned_gpr`, which is what this writes.
    let mut carried_reserved = 0usize;
    if ir_reserve_carried_enabled() {
        let mut taken: Vec<u8> = gp_reg_of.iter().flatten().copied().collect();
        // Plus every register a SPLIT value moves into later in the method; see
        // `split_gp_regs` for what handing one of those out again would cost.
        taken.extend_from_slice(&split_gp_regs);
        taken.sort_unstable();
        taken.dedup();
        for (id, reg) in carried_reservation(graph, plan, live, &model.clobbers, &gp_reg_of, &taken)
        {
            gp_reg_of[id] = Some(reg);
            carried_reserved += 1;
        }
    }

    // ── Entry parameters, which the scan usually declines ────────────
    //
    // **Corrected 2026-09-16.** This paragraph used to open: "`MachineModel::
    // pin_entry_params` pins every `Param` to its INCOMING ABI register, and
    // `allocate_linear_scan` skips a pinned value outright […] so a parameter
    // can never be promoted into the callee-saved file however the heuristics
    // are tuned." **Nothing in this file calls `pin_entry_params`** — its only
    // mentions in the crate are its own definition and two doc references — so
    // a `Param` is an ordinary candidate here, and one read twice inside a loop
    // is promoted by the scan like any other value.
    //
    // What is true, and is what the disassembly below actually shows, is
    // narrower: a parameter read ONCE is refused by `ir_residency_pays_here`
    // (`skip_single_use`), and a loop bound is exactly that shape — one static
    // read at the loop test, executed every iteration. The static rule cannot
    // see the frequency; `ir_residency_loop_weight_enabled` is the rule that
    // can, and it is default OFF. So the copy below is not a workaround for a
    // structural impossibility but for a heuristic that, at its default,
    // declines the one population it most wants.
    //
    // That is what the 2026-09-03 disassembly of the inverted `fieldloop`
    // showed: `mov rcx,[rbp-60h]` reloading the loop bound on every iteration,
    // while the baseline tier had copied it into a callee-saved register in its
    // prologue (`mov r14,rdx`) and read it from there.
    //
    // So the copy is made here instead, out of a register the ALLOCATOR DID NOT
    // USE. That is the whole safety argument: an unassigned register in this
    // file is written by nothing else — only the residency machinery publishes
    // into it — and every register in the file is callee-saved, so a call
    // cannot destroy it either. The parameter is SSA and never redefined, so
    // one publish at entry is good for the whole method.
    //
    // `IrType::Ref` is excluded for the reason the bank match above gives, and
    // it is not a tuning choice: `OopMapEntry` names frame slots only, so a
    // reference in a register is invisible to a root walk and cannot be
    // updated on evacuation. The receiver therefore stays in its frame slot,
    // and closing that needs oop maps that can name a register.
    if ir_param_prologue_copy_enabled() {
        let mut taken: Vec<u8> = gp_reg_of.iter().flatten().copied().collect();
        // Plus every register a SPLIT value moves into later in the method; see
        // `split_gp_regs` for what handing one of those out again would cost.
        taken.extend_from_slice(&split_gp_regs);
        taken.sort_unstable();
        taken.dedup();
        let mut free: Vec<u8> = ir_gp_file()
            .iter()
            .copied()
            .filter(|r| !taken.contains(r))
            .collect();
        for id in 0..n {
            if free.is_empty() {
                break;
            }
            if gp_reg_of.get(id).copied().flatten().is_some() {
                continue;
            }
            let Some(node) = graph.nodes.get(id) else {
                continue;
            };
            if !matches!(node.op, Op::Param(_)) {
                continue;
            }
            if !matches!(node.ty, IrType::Int | IrType::Long) {
                continue;
            }
            // Worth a register only if the reads outnumber the one publish.
            // Loop-weighted, because a parameter's uses are typically inside a
            // loop its definition is not.
            if live.weight.get(id).copied().unwrap_or(0) < 2 {
                continue;
            }
            if let Some(reg) = free.pop() {
                gp_reg_of[id] = Some(reg);
                param_copies += 1;
            }
        }
    }

    // ── The split plan, sequentialised ───────────────────────────────
    //
    // Everything above decided WHICH values are managed and WHAT each one owes.
    // This turns that into the position table the emission reads, and it is the
    // last place the whole feature can still be refused.
    //
    // **Several moves at one position are a PARALLEL copy.** `a ← b` beside
    // `b ← a` is a swap, and emitting the two in sequence makes both `b`. The
    // sequencer for that is `regalloc::resolve_parallel_copy`, already written,
    // already proved and already used for the phi edges, so it is what runs
    // here — loads included, because a load into a register another value is
    // still being moved out of has exactly the same hazard as a move.
    //
    // **A cycle refuses the feature for the whole method.** Breaking one costs
    // a scratch register, and between two nodes there is none that is free by
    // construction: RAX may be carrying a value to the next node and RCX a
    // deferred one (see `plan_carries`). Refusing is a handful of lines and
    // costs only an optimization; guessing at a scratch is a wrong value in a
    // register.
    let mut split_plan = LsSplitPlan::default();
    if !split_taken.is_empty() {
        match ls_sequence_split_plan(&split_taken, live.total_positions) {
            Some(at) => {
                split_plan.transitions = at.iter().map(|v| v.len()).sum();
                split_plan.at = at;
                split_plan.block_start = live.span.iter().map(|&(start, _)| start).collect();
                split_plan.managed = split_managed.clone();
                split_plan.values = split_taken.len();
                split_plan.edges = std::mem::take(&mut ls_edges);
            }
            None => {
                // Every managed value goes back to no register at all. The
                // registers they were given are then written by nothing, which
                // is the same position this file is in for every value the scan
                // promoted and it refused.
                for &(id, _, _) in &split_taken {
                    reg_of[id] = None;
                    gp_reg_of[id] = None;
                    split_managed[id] = false;
                }
                skip_split += split_taken.len();
                split_taken.clear();
            }
        }
    }

    // Round 11 wave 6: what each back-edge poll reloads, and the values that
    // may not be reloaded (see `poll_fp_reload_sets`) sent back to memory
    // BEFORE anything below counts or tallies `reg_of`.
    let (poll_fp_reloads, poll_demoted) =
        poll_fp_reload_sets(schedule, live, plan, &alloc, &mut reg_of, &split_managed);
    demoted += poll_demoted;
    let fp_promoted = reg_of.iter().filter(|r| r.is_some()).count();
    let gp_promoted = gp_reg_of.iter().filter(|r| r.is_some()).count();
    // A managed value whose allocator has it in MEMORY at its own definition
    // appears in neither vector yet — its first register arrives at a
    // transition — so it has to be counted here, or the `promoted == 0` refusal
    // below would throw away a plan that does real work.
    let split_only = split_taken
        .iter()
        .filter(|&&(id, gp, _)| {
            if gp {
                gp_reg_of[id].is_none()
            } else {
                reg_of[id].is_none()
            }
        })
        .count();
    let promoted = fp_promoted + gp_promoted + split_only;

    // ── The phi census, tallied against the FINAL assignment ─────────
    //
    // Every phi in the graph lands in exactly one field. `resident` is read off
    // `reg_of`/`gp_reg_of` after the reserve and parameter passes have run, so
    // a phi the scan refused and `ir_reserve_carried_enabled` then rescued is
    // counted as resident and its recorded refusal is discarded — which is the
    // point: this reports what the emission does, not what the scan intended.
    // See `PhiCensus`.
    let mut phi_census = PhiCensus::default();
    let mut phi_total = 0usize;
    for id in 0..n {
        // The same `is_value_ty` filter the scan loop applies; see the comment
        // on `phi_candidate` there for why a memory phi is not counted.
        if !graph
            .nodes
            .get(id)
            .is_some_and(|node| matches!(node.op, Op::Phi) && is_value_ty(node.ty))
        {
            continue;
        }
        phi_total += 1;
        if reg_of[id].is_some() || gp_reg_of[id].is_some() {
            phi_census.resident += 1;
            continue;
        }
        match phi_refusal[id] {
            Some(PhiRefusal::Disabled) => phi_census.disabled += 1,
            Some(PhiRefusal::RefType) => phi_census.ref_type += 1,
            Some(PhiRefusal::NoRegister) => phi_census.no_register += 1,
            Some(PhiRefusal::NoHome) => phi_census.no_home += 1,
            Some(PhiRefusal::WrongBank) => phi_census.wrong_bank += 1,
            // The scan refused it for no recorded reason, so the only thing
            // that can have taken its register is one of the two
            // second-opinion passes above.
            None => phi_census.demoted += 1,
        }
    }
    debug_assert_eq!(
        phi_census.total(),
        phi_total,
        "the phi census lost a phi: {phi_census:?} against {phi_total} phis in the graph. \
         Every refusal in the scan loop needs a `PhiRefusal` here, or this census reads \
         low for a reason nobody can chase -- which is the exact failure mode the \
         single `phi=` field it replaces had."
    );

    // ── Could the home slot be dropped? The census that ASKED, retired ──
    //
    // `docs/feature-designs/ir-optional-home-slot.md` argues that a value which
    // lives in a register for its whole range needs no frame word, and rested
    // that on `LiveModel::pinned` covering every deopt-named value. On this
    // path it does not: `release_deopt_pins` above deliberately releases
    // exactly those pins. So a promoted value here may very well be named by a
    // deopt frame, and — as the design stood — its home was what that frame
    // read.
    //
    // A census printed here counted that, under the only rule available at the
    // time: "promoted, and named by NO safepoint, and not a phi". It answered
    // `droppable=0` on real bytecode, and the answer was acted on — the next
    // move it named, deopt metadata that can describe a REGISTER, is
    // `ir-deopt-regs`, and `ir-reg-authoritative` / `ir-drop-phi-home` /
    // `ir-phi-copy-regs` followed it.
    //
    // **Which is why the line is gone.** Those flags widened the rule and the
    // census did not follow: on 2026-09-10 it read `droppable=0` on
    // `probes/FieldLoop.java` `sum` while the emission on that same compile
    // dropped THREE homes, and
    // `internal/performance/c2-the-gp-register-file-is-not-the-binding-constraint-20260910.md`
    // quoted the zero as evidence that home elimination "does not yet reach"
    // this loop. It does. A stale diagnostic reading zero is not a neutral
    // gap — it retires levers that are engaged.
    //
    // The replacement is computed from the predicates that actually decide,
    // where they decide, so it cannot drift from them again: `home_dropped`
    // (`[ir-ls] homes: dropped_values=`) is the outcome, and
    // `Lowerer::census_home_blocks` (`[ir-ls] homes kept:`) is the per-cause
    // breakdown of what is left.
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
        eprintln!(
            "[ir-ls] nodes={n} positions={} peak_live={} deopt_pins_released={released} \
             scan_promoted={} resident={promoted} (fp={fp_promoted} gp={gp_promoted}) \
             demoted={demoted} splits={} scan_spills={} scan_reloads={}",
            live.total_positions,
            live.peak_live,
            alloc.promoted,
            alloc.splits,
            alloc.spills,
            alloc.reloads,
        );
    }
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
        eprintln!(
            "[ir-ls] skipped: split_or_spilled={skip_split} \
             wrong_bank_or_type={skip_bank} no_home={skip_home} phi={skip_phi} \
             const={skip_const} single_use={skip_single_use} param_copies={param_copies} \
             spilled={skip_spilled} no_alloc={skip_no_alloc} carried_reserved={carried_reserved} \
             | crossblock: price={} taken={crossblock_taken} \
             over={crossblock_over} carried_demand={carried_demand} carried_w={carried_w:?} \
             call_crossing={call_crossing_taken}",
            carried_displacement_price(&carried_w, crossblock_taken)
        );
        // R4's own line. `split_or_spilled=` above goes on meaning what it
        // always meant — values the scan split and this file refused — so the
        // two lines together are the before/after the staging note asked for:
        // with the flag off `taken=0` and `split_or_spilled=` is the whole
        // population; with it on the population moves across, and
        // `unplaceable=` says how many this file looked at and could not prove.
        eprintln!(
            "[ir-ls] splits: flag={ls_splits} ranges_agree={ranges_agree} \
             taken={} transitions={} unplaceable={skip_split_unplaceable} \
             scan_splits={} scan_remats={} scan_moves={}{}{}",
            split_plan.values,
            split_plan.transitions,
            alloc.splits,
            alloc.remats,
            alloc.reg_moves,
            // JIT round 19 proposal wave 11 (lane lv11): only under its switch,
            // so the default line is unchanged.
            if ir_ls_splits_carried_first_enabled() || ir_ls_splits_carried_priced_enabled() {
                format!(" yielded_to_carried={split_yielded}")
            } else {
                String::new()
            },
            // Wave 12 (lane lv12, LV11-3): only under its switch.
            if ir_ls_splits_refuse_no_gain_enabled() {
                format!(" no_gain={split_no_gain}")
            } else {
                String::new()
            },
        );
        // JIT round 19 wave 10 (lane lv10, i65-L2 measurement): when the gate
        // is shut, name what shut it -- how many values the two models give
        // different ranges, split φ / non-φ, and the first few -- so a host
        // run of `CRATONVM_JIT_IR_LS_SPLITS=1 ..._SLOTS_PHI_EDGE_RANGES=1`
        // that still reads `ranges_agree=false` names its next blocker.
        // Diagnostic only; nothing below reads it.
        if !ranges_agree {
            eprintln!("{}", ranges_disagreement_census(graph, plan, live));
        }
        // The phi half, printed on its own line because it answers a different
        // question from the one above: not "how many candidates did the file
        // lose" but "did the loop-carried population -- a loop counter and a
        // loop accumulator are `Op::Phi` at every loop header -- reach a
        // register, and if not, which refusal took it".
        eprintln!(
            "[ir-ls] phis={phi_total}: resident={} disabled={} ref_type={} \
             no_register={} no_home={} wrong_bank={} demoted={}",
            phi_census.resident,
            phi_census.disabled,
            phi_census.ref_type,
            phi_census.no_register,
            phi_census.no_home,
            phi_census.wrong_bank,
            phi_census.demoted,
        );
        eprintln!("[ir-ls] safepoints={}", graph.safepoints.len());
    }
    if promoted == 0 {
        return Ok(ls_refuse(
            "the scan promoted nothing this file could take -- every candidate \
             was split, spilled, homeless, single-use, a constant, or of a type \
             neither bank holds; see the `skipped:` and `phis:` census lines \
             above for which",
        ));
    }
    Ok(Some(RegResidency {
        reg_of,
        gp_reg_of,
        promoted,
        demoted,
        peak_live: live.peak_live,
        splits: split_plan,
        phi_census,
        poll_fp_reloads,
    }))
}

/// The FP values each back-edge block's poll must reload after its slow-path
/// call: an accepted, unsplit value (`reg_of`, one segment) in a caller-saved
/// XMM whose segment covers the poll.
///
/// The poll is emitted before the terminator (at `edge - 1`) or, in a block
/// without one, after its last node, so "covers the poll" is "its segment
/// contains `edge - 1`" -- or `edge` in a block with no position before it. A
/// value live across the poll contains that position by interval continuity;
/// a value that starts at `edge` is written after the poll. Segments of one
/// register are disjoint (`verify_allocation`), so each register gets at most
/// one value per block and the reloads cannot overwrite one another.
///
/// The reload reads the HOME word, so the home must still be this value's at
/// the poll: `plan_slots`' own range (`plan.range`, which the home colouring
/// was built from) has to cover the poll too. The two liveness models agree
/// on ordinary compiles; a value on which they disagree here is DEMOTED --
/// its `reg_of` entry cleared, which only sends it back to memory -- and
/// counted in the second return value.
fn poll_fp_reload_sets(
    schedule: &Schedule,
    live: &crate::regalloc::LiveModel,
    plan: &SlotPlan,
    alloc: &crate::regalloc::Allocation,
    reg_of: &mut [Option<u8>],
    split_managed: &[bool],
) -> (HashMap<usize, Vec<NodeId>>, usize) {
    let mut out: HashMap<usize, Vec<NodeId>> = HashMap::new();
    // With the XMM clobber still modelled nothing needs a reload, and the
    // outlined arm (one of the two configurations that keep it) refuses a
    // non-empty set -- so do not compute one.
    if !ir_poll_preserves_fp() {
        return (out, 0);
    }
    // Candidates first: usually none, and never more than the values the
    // plan put in the XMM file.
    let cands: Vec<(usize, crate::regalloc::PosRange)> = reg_of
        .iter()
        .enumerate()
        .filter(|&(id, reg)| {
            reg.is_some_and(|r| !IR_LOWER_SAVED_XMMS.contains(&r))
                && !split_managed.get(id).copied().unwrap_or(false)
        })
        .filter_map(|(id, _)| match alloc.segments.get(id).map(Vec::as_slice) {
            Some([seg]) if seg.reg.is_some() => Some((id, seg.range)),
            _ => None,
        })
        .collect();
    if cands.is_empty() {
        return (out, 0);
    }
    let mut unsafe_ids: Vec<usize> = Vec::new();
    for (b, block) in schedule.blocks.iter().enumerate() {
        if !block.successors.iter().any(|&s| s <= b) {
            continue;
        }
        let Some(&(lo, edge)) = live.span.get(b) else {
            continue;
        };
        let at = if edge > lo { edge - 1 } else { edge };
        let mut ids: Vec<NodeId> = Vec::new();
        for &(id, r) in &cands {
            if !(r.lo <= at && at <= r.hi) {
                continue;
            }
            let home_covers = plan
                .range
                .get(id)
                .copied()
                .flatten()
                .is_some_and(|h| h.lo <= at && at <= h.hi);
            if home_covers {
                // Cast: a node index back to its id.
                ids.push(id as NodeId);
            } else {
                unsafe_ids.push(id);
            }
        }
        if !ids.is_empty() {
            out.insert(b, ids);
        }
    }
    unsafe_ids.sort_unstable();
    unsafe_ids.dedup();
    let mut demoted = 0usize;
    for &id in &unsafe_ids {
        if let Some(cell) = reg_of.get_mut(id) {
            if cell.take().is_some() {
                demoted += 1;
            }
        }
    }
    if demoted > 0 {
        // A demoted value is no longer resident anywhere, so no block reloads it.
        for ids in out.values_mut() {
            ids.retain(|&id| !unsafe_ids.contains(&(id as usize)));
        }
        out.retain(|_, ids| !ids.is_empty());
    }
    (out, demoted)
}

/// JIT round 20 (lane loopopt; `r21-loopreload-voidwriter-gets-no-ir-body`,
/// `r21-row-driver-loop-is-never-compiled`): under `CRATONVM_DBG_IR_BAILOUT`,
/// name the node an `UnallocatedValue` latch refused on -- its op, type, pc,
/// whether it is a multi-input merge's phi, and its users' ops -- so a host
/// trace says WHICH value had no location instead of only its id (the w16 and
/// w18b traces stopped at `value n26 read before a location was assigned`).
/// Diagnostic only; prints nothing for any other bailout.
fn describe_unallocated_value(graph: &Graph, bailout: &Bailout) {
    let BailoutReason::UnallocatedValue { node } = &bailout.reason else {
        return;
    };
    let node = *node;
    if !cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_BAILOUT") {
        return;
    }
    let Some(n) = graph.nodes.get(node as usize) else {
        return;
    };
    let anchor = n
        .inputs
        .first()
        .and_then(|&a| graph.nodes.get(a as usize))
        .map(|a| format!("{:?}/{} input(s)", a.op, a.inputs.len()));
    let users: Vec<String> = graph
        .users_of(node)
        .into_iter()
        .filter_map(|u| {
            graph
                .nodes
                .get(u as usize)
                .map(|un| format!("n{u} {:?}", un.op))
        })
        .take(8)
        .collect();
    eprintln!(
        "[ir-bailout] unallocated n{node}: {:?} ty {:?} pc {:?} anchor {:?} users [{}]",
        n.op,
        n.ty,
        n.bytecode_pc,
        anchor,
        users.join(", ")
    );
}

/// Funnel every refusal in this file through one place: count it, then return
/// the `None` the public entry points have always returned, which is the
/// caller's signal to run the method in a lower tier. A compiler refusal must
/// never terminate the VM.
fn refuse(bailout: Bailout) -> Option<CompiledMethod> {
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_BAILOUT") {
        eprintln!("[ir-bailout] {bailout}");
    }
    record_bailout(&bailout);
    // Attribution, not duplication — the same split `verify_or_bail` makes:
    // `record_bailout` owns the process-wide category counters, and this
    // attaches the bailout to *this* method in the per-compilation report.
    //
    // Without it the report's `bailouts` field is STRUCTURALLY empty for every
    // lowering refusal: a census over CratonBench read `bailouts:[]` on all 105
    // compilations, including the 17 that fell through to single-pass, so the
    // one record that names both the method and the reason named neither. The
    // counters were moving the whole time, which is what made the hole hard to
    // see — the totals looked alive while every per-method row was blank.
    crate::metrics::note_current_bailout(&bailout, "lower");
    // Name the refusal for `last_lower_bail` too, unless the site already did
    // (a site's own label is more specific than the reason's). Before round 9
    // the two channels were disjoint: `refuse` sites counted but read back as
    // "unlabelled" in the `[ir] lower_inner refused (..)` line, and the
    // `note_lower_bail` sites were labelled but never counted.
    if last_lower_bail().is_none() {
        note_lower_bail(match &bailout.reason {
            BailoutReason::UnsupportedShape(what) | BailoutReason::Internal(what) => *what,
            other => other.category(),
        });
    }
    None
}

/// A labelled refusal: [`note_lower_bail`] plus [`refuse`], so the site is both
/// named (for `last_lower_bail`) and counted (`record_bailout` and the
/// per-method report). The label doubles as the `UnsupportedShape` text.
fn refuse_labelled(label: &'static str) -> Option<CompiledMethod> {
    note_lower_bail(label);
    refuse(Bailout::new(BailoutReason::UnsupportedShape(label)))
}

/// Smallest executable buffer this backend will ask for.
///
/// Two pages. Raised from 4096 with the rest of the sizing below: under the old
/// model the floor WAS the capacity for most compiles (the formula fell under
/// it for any modest graph), so 4096 is where the overflows piled up.
///
/// Raising the floor ALONE does not work, and the census says so: `nodes*32 +
/// calls*448 + 1024` with a 16 KiB floor still overflows 5 of 1664 while
/// reserving 26 MiB — worse on both axes than fixing the formula and keeping
/// the floor at 8 KiB.
const IR_CODE_BUFFER_FLOOR: usize = 8 * 1024;

/// How many bytes to reserve for a lowered graph of `nodes` nodes, `call_nodes`
/// of which are calls.
///
/// **This is a capacity, not a prediction.** Getting it too high wastes address
/// space in a region already capped by `COMMITTED_JIT_CODE_BYTES`; getting it
/// too low does NOT produce a bug — `ExecutableBuffer::emit` is non-panicking
/// and the caller discards an overflowed body — it silently drops the method to
/// the single-pass backend. That failure is invisible except as throughput, so
/// the bias here is deliberately toward over-reserving.
///
/// ## Where these numbers come from
///
/// Measured, not reasoned. `CRATONVM_DBG_IR_BUFSIZE=1` (below) censused
/// **1664 IR compiles** across three workloads on 2026-08-01 — Spring Boot's
/// `BasicErrorControllerDirectMockMvcTests` (595) and
/// `BasicErrorControllerIntegrationTests` (1067), plus the whole
/// `bench/CratonBench` CPU suite (2) — recording `wanted` against `capacity`
/// for every one.
///
/// The old `nodes*32 + call_nodes*448 + 1024` **overflowed 155 of those 1664**
/// (9.3%), under-shooting by up to **2.65x**. It was never measured; it was
/// reasoned from "an arithmetic node emits well under 32 bytes", and that
/// premise is fine — the error is entirely in the other two terms:
///
/// * **the per-call term.** 448 budgeted, 1141 actually required at worst. The
///   278 call-free compiles in the census never wanted more than 1545 bytes
///   total, so nodes were never the problem; calls always were.
/// * **the constant.** 1024 does not pay for a prologue, an epilogue and the
///   frame setup, so every small graph fell through to the floor and inherited
///   whatever the floor happened to be.
///
/// This model overflows **0 of 1664**, and its tightest fit still has **1.24x**
/// headroom, so it is not sitting on a knife edge. It reserves 13.8 MiB across
/// that census against the old 6.6 MiB.
///
/// **That 2.1x mattered when it was written.** [`ExecutableBuffer::new`] adds
/// the full CAPACITY to [`COMMITTED_JIT_CODE_BYTES`], the quantity the
/// code-cache cap bounds, so over-reserving bought headroom with code cache.
/// Since `ExecutableBuffer::trim_unused_tail` (run by `CompiledMethod::new`)
/// the whole pages past the emitted code go back before the body is
/// published, so an over-estimate now costs at most the last page per
/// published body, plus address space during codegen.
///
/// [`ExecutableBuffer::wanted`] measures this exactly for this backend: it
/// counts every byte codegen ASKED to emit, including writes dropped after an
/// overflow, and this lowerer calls neither `rewind_to` nor `emit_checked`, so
/// nothing inflates it or hides from it.
fn ir_code_buffer_estimate(nodes: usize, call_nodes: usize) -> usize {
    if legacy_ir_code_buffer_estimate() {
        // The floor is part of the arm: 4096 was doing most of the work in the
        // old sizing, so an A/B that kept the new floor would not be measuring
        // the old behaviour.
        return nodes
            .saturating_mul(32)
            .saturating_add(call_nodes.saturating_mul(448))
            .saturating_add(1024)
            .max(4096);
    }
    nodes
        .saturating_mul(IR_BYTES_PER_NODE)
        .saturating_add(call_nodes.saturating_mul(IR_BYTES_PER_CALL_NODE))
        .saturating_add(IR_CODE_BUFFER_BASE)
        .max(IR_CODE_BUFFER_FLOOR)
}

/// Bytes one GC point's root publication spends per reference home, for
/// [`ir_ref_home_publication_reserve`]: the per-call push (`MOV RCX,[rbp-d]` /
/// `MOV [R11],RCX` / `LEA R11,[R11+8]`, 14 bytes) plus its copy-back after the
/// call, or the frame block's inline ensure (14 bytes per home), rounded up.
const IR_BYTES_PER_PUBLISHED_HOME: usize = 32;

/// Extra first-attempt buffer for a body with more reference homes than the
/// frame block takes by default (round 14 wave 1, lane chain) -- **default
/// ON**, `CRATONVM_JIT_IR_BUFFER_REF_HOME_RESERVE=0` restores the fitted
/// estimate alone.
///
/// [`ir_code_buffer_estimate`] was fitted on a census where every body stayed
/// under `FRAME_BLOCK_MAX_HOMES`. Past it, each GC point publishes every
/// reference home inline, so the code grows as GC points x homes and the
/// estimate (linear in nodes and calls) is overrun: the chain arm's
/// `HashMap.putVal` (76 847 bytes) was lowered twice, the second time at the
/// exact size (`lower_inner_with_array_list`'s overflow retry). Reserving that
/// term up front lowers such a body once. Capacity only: the emitted bytes
/// are unchanged, and a body at or under the default cap reserves nothing
/// extra (byte-identical sizing).
///
/// Round 15 wave 1 (lane chain): a body over the default cap that still gets
/// a frame block (a raised `CRATONVM_JIT_IR_FRAME_BLOCK_MAX_HOMES`, or
/// `CRATONVM_JIT_IR_FRAME_BLOCK_LOOP_CAP`) reserves for the form it will
/// emit: the shared subroutine once, or the inline ensure (14 bytes per home)
/// at every GC point. Before, a raised knob reserved NOTHING for the inline
/// ensure, so such a body overran the estimate and was lowered twice.
fn ir_ref_home_publication_reserve(graph: &Graph, schedule: &Schedule, plan: &SlotPlan) -> usize {
    if !cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_BUFFER_REF_HOME_RESERVE") {
        return 0;
    }
    let mut seen = vec![false; plan.slots];
    let mut homes = 0usize;
    for (id, node) in graph.nodes.iter().enumerate() {
        if node.ty != IrType::Ref {
            continue;
        }
        if let Some(Some(colour)) = plan.node_color.get(id).copied() {
            if let Some(cell) = seen.get_mut(colour as usize) {
                if !*cell {
                    *cell = true;
                    homes += 1;
                }
            }
        }
    }
    // At or under the DEFAULT cap (and the knob) the fitted estimate covers
    // the publication. Round 15 wave 1: not the knob alone -- a body under a
    // raised `CRATONVM_JIT_IR_FRAME_BLOCK_MAX_HOMES` gets a frame block, whose
    // inline ensure is 14 bytes per home at EVERY GC point (below).
    let knob = Lowerer::<'static>::frame_block_max_homes();
    if homes <= knob.min(Lowerer::<'static>::FRAME_BLOCK_MAX_HOMES) {
        return 0;
    }
    let gc_points = graph
        .nodes
        .iter()
        .filter(|n| ir_op_is_gc_point(&n.op))
        .count();
    // The block also names the reference-parameter homes.
    let block_homes = homes.saturating_add(
        graph
            .nodes
            .iter()
            .filter(|n| matches!(n.op, Op::Param(_)) && n.ty == IrType::Ref)
            .count(),
    );
    if block_homes <= Lowerer::<'static>::frame_block_cap_for(graph, schedule, block_homes, knob)
        && Lowerer::<'static>::frame_block_shared_publish_enabled()
    {
        // One subroutine (14 bytes per home plus its frame), and 15 bytes per
        // GC point, which the fitted estimate already covers.
        return block_homes.saturating_mul(IR_BYTES_PER_PUBLISHED_HOME);
    }
    gc_points
        .saturating_mul(block_homes)
        .saturating_mul(IR_BYTES_PER_PUBLISHED_HOME)
}

/// Is some GC point ([`ir_op_is_gc_point`]) scheduled in a block the
/// frequency model places inside a loop (`BlockFrequencies::depth > 0`)?
fn ir_gc_point_in_loop(graph: &Graph, schedule: &Schedule) -> bool {
    let depth = &schedule.freq.depth;
    schedule.blocks.iter().enumerate().any(|(b, block)| {
        depth.get(b).copied().unwrap_or(0) > 0
            && block
                .nodes
                .iter()
                .any(|&id| graph.node_opt(id).is_some_and(|n| ir_op_is_gc_point(&n.op)))
    })
}

/// `CRATONVM_JIT_IR_SYNC_WINDOW_NO_CHAIN_POINTS` (round 15 wave 1, lane chain,
/// hand-back) -- **default ON**; `0` lets a deopt site inside a synchronized
/// splice's monitor window publish a caller chain again (the chain arm's
/// behaviour before, wrong under `CRATONVM_DEOPT_EAGER_CHAINS`). See
/// `Lowerer::sync_window_site_publishes_no_chain`. Read per deopt site of a
/// graph that has a window.
fn ir_sync_window_no_chain_points_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SYNC_WINDOW_NO_CHAIN_POINTS")
}

/// The ops whose arms call `emit_safepoint_map` (a superset is harmless: both
/// readers, [`ir_ref_home_publication_reserve`] and [`ir_gc_point_in_loop`],
/// only size or choose a publication form).
fn ir_op_is_gc_point(op: &Op) -> bool {
    matches!(
        op,
        Op::Call { .. }
            | Op::New { .. }
            | Op::NewArray { .. }
            | Op::ConstString { .. }
            | Op::ConstClass { .. }
            | Op::LoadStatic { .. }
            | Op::StoreStatic { .. }
            | Op::CheckCast { .. }
            | Op::InstanceOf { .. }
            | Op::MonitorEnter
            | Op::MonitorExit
            | Op::LambdaIntToDouble
            | Op::IndyBridge { .. }
            | Op::MultiNewArray { .. }
            | Op::NewCp { .. }
    )
}

/// Per-node reservation. See [`ir_code_buffer_estimate`].
const IR_BYTES_PER_NODE: usize = 64;
/// Per-call-node reservation, on top of [`IR_BYTES_PER_NODE`]. This is the term
/// the old estimate got badly wrong: it budgeted 448, and the census puts the
/// true worst-case marginal cost of a call node at **1141 bytes**. A MIC plus a
/// 4-way PIC dual-ABI inline-cache site, its deopt/guard stub and its safepoint
/// spill run all hang off one call node.
const IR_BYTES_PER_CALL_NODE: usize = 1536;
/// Fixed per-method reservation: prologue, epilogue, frame setup and the
/// per-method stubs, none of which are nodes.
const IR_CODE_BUFFER_BASE: usize = 4096;

/// A/B opt-out (`CRATONVM_JIT_IR_LEGACY_BUFFER_ESTIMATE=1`): restore the
/// pre-2026-08-01 `nodes*32 + calls*448 + 1024` sizing and the 4096 floor.
///
/// It exists so the estimate change can be measured on ONE binary, both arms.
/// Buffer sizing decides which methods the optimizing tier produces bodies for
/// at all, and that tier is not uniformly faster than single-pass — a
/// same-binary A/B is the only honest way to tell a throughput change caused by
/// this from one caused by whatever else moved between two builds.
fn legacy_ir_code_buffer_estimate() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LEGACY_BUFFER_ESTIMATE")
    })
}

/// `CRATONVM_DBG_IR_BUFSIZE=1` — one line per IR compile that reaches
/// emission, reporting what the sizing model predicted against what codegen
/// actually asked for.
///
/// This is the instrument the estimate above was fitted with, and the one to
/// re-run before changing it again. It reports EVERY compile, not just the
/// overflowing ones: an estimate is only as good as its headroom on the
/// compiles that succeeded, and a census of failures alone cannot show that.
///
/// `[ir-bufsize] nodes=N calls=C wanted=W capacity=C' ratio=… overflow=bool`
fn report_ir_buffer_size(nodes: usize, call_nodes: usize, wanted: usize, capacity: usize) {
    if !cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_BUFSIZE") {
        return;
    }
    // Integer permille, so the line stays greppable and needs no float
    // formatting in a path that may run thousands of times.
    let permille = if capacity == 0 {
        0
    } else {
        wanted.saturating_mul(1000) / capacity
    };
    eprintln!(
        "[ir-bufsize] nodes={nodes} calls={call_nodes} wanted={wanted} capacity={capacity} \
         permille={permille} overflow={}",
        wanted > capacity
    );
}

// ── Public entry point ───────────────────────────────────────────────

/// Lower the scheduled IR graph to x86-64 machine code.
///
/// # The load-hoisting TODO that used to live here is DONE (2026-09-16)
///
/// This doc comment carried a `TODO(round-8, HIGH from round-7 jit #9)`
/// saying there was "no Loop-Invariant Code Motion (LICM) for
/// `Op::Load`/`Op::LoadStatic` on a loop-invariant base", and prescribed a
/// four-step plan "implemented in `ir_optimize.rs` so this lowerer sees a
/// pre-hoisted graph".
///
/// That is exactly what `ir_optimize::licm` is, it is **default-ON**
/// (`licm_enabled`, opt out with `CRATONVM_JIT_LICM=0`), and it runs the
/// prescribed steps: loop headers from a back-edge scan (`loop_headers`),
/// invariance marking (`is_loop_invariant_d`), a memory-clobber /
/// alias test for the read (`loop_store_clobber`, `load_safe_past_clobber`,
/// `Graph::may_alias`), and a pre-header re-anchor. The complementary
/// within-block form is `ir_optimize::eliminate_redundant_loads`.
///
/// The TODO stayed for two releases after the pass landed, and the cost of
/// that is not cosmetic: `x64/single_pass_only.rs` decides whether the
/// optimizing tier may take a method by asking which transforms this tier
/// HAS, and it cites `ir_optimize::licm` by name as the reason the
/// single-pass `aaload`/FP hoists are not on its veto list. A stale "the IR
/// tier has no LICM" here argues for adding them to it, which would decline
/// the optimizing tier on every loop with an invariant load.
///
/// If this needs re-opening, the live gap is named at
/// `ir_optimize::optimize`: LICM runs AFTER the unroller by default, so the
/// unroller never sees the re-anchored form (`CRATONVM_JIT_IR_LICM_BEFORE_UNROLL=1`
/// flips the order). That is an ordering question, not a missing pass.
pub fn lower(
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
) -> Option<CompiledMethod> {
    // No profile → empty branch hints; no scalar-deopt → None. Both default to
    // the historical byte-for-byte layout. An empty `HashMap` performs no
    // allocation until first insert.
    let empty: HashMap<usize, bool> = HashMap::new();
    let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
    let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
    let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
    lower_inner(
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        &empty,
        &[],
        None,
        &no_direct,
        &no_ic,
        &no_compact,
        &crate::ir::IrInlineFrameSites::default(),
    )
}

/// `lower` with profile-guided conditional-branch layout (wire-tiered-manager
/// Step 4 — PGO handoff C1 → C2). `branch_hints` maps a conditional-branch
/// instruction's bytecode PC to its bias (`true` = usually taken, `false` =
/// usually not taken); see `Lowerer::branch_hints`. An empty map reproduces
/// [`lower`] exactly.
pub fn lower_with_branch_hints(
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
) -> Option<CompiledMethod> {
    let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
    let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
    let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
    lower_inner(
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        &[],
        None,
        &no_direct,
        &no_ic,
        &no_compact,
        &crate::ir::IrInlineFrameSites::default(),
    )
}

/// As [`lower`], but with an optional [`ScalarReplacementMap`] enabling the
/// guard-surviving scalar-replacement deopt producer (a deopt slot holding a
/// scalar-replaced `Op::New` lowers to a `FrameValue::VirtualObject`). The
/// production caller passes `Some(map)` only when `CRATONVM_SCALAR_DEOPT` and
/// `CRATONVM_DEOPT_REAL` are both set; `None` is byte-identical to the prior
/// `lower`.
pub fn lower_with_scalar_deopt(
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    sr_map: Option<&ScalarReplacementMap>,
) -> Option<CompiledMethod> {
    let empty: HashMap<usize, bool> = HashMap::new();
    let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
    let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
    let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
    lower_inner(
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        &empty,
        &[],
        sr_map,
        &no_direct,
        &no_ic,
        &no_compact,
        &crate::ir::IrInlineFrameSites::default(),
    )
}

thread_local! {
/// The reason the most recent `lower_inner` on this thread refused.
///
/// A bail that names itself is the difference between "the optimizing tier
/// declined" and a fact you can act on: the C2 task pays for an IR build,
/// optimize and schedule before any of these fire, and whether that cost can be
/// avoided up front depends entirely on WHICH of them fired.
///
/// Thread-local and overwritten per compile; read it immediately after the
/// lowering call, on the same thread.
///
/// The second half (round 14 wave 3, lane fixup, RV3-1) is the `bytecode_pc`
/// of the first synchronized-splice monitor op whose window the lowerer
/// refused ([`Lowerer::sync_splice_window_refusal`]): the IR door retries the
/// build without that splice, as it does for a builder refusal (W5-2). Shared
/// with the reason rather than its own `thread_local!` for the JIT statics
/// ratchet.
static LOWER_BAIL_REASON: std::cell::Cell<(Option<&'static str>, Option<usize>)> =
    const { std::cell::Cell::new((None, None)) };
}

pub(crate) fn note_lower_bail(reason: &'static str) {
    LOWER_BAIL_REASON.with(|c| c.set((Some(reason), c.get().1)));
}

/// Clear the reason before a lowering attempt, so a stale one cannot be read
/// as this attempt's.
pub(crate) fn clear_lower_bail() {
    LOWER_BAIL_REASON.with(|c| c.set((None, None)));
}

/// The reason the last lowering attempt on this thread refused, if it did.
pub fn last_lower_bail() -> Option<&'static str> {
    LOWER_BAIL_REASON.with(|c| c.get().0)
}

/// Record the first refused synchronized-splice window's pc (RV3-1); a later
/// refusal in the same attempt keeps the first, like `latch_bailout`.
fn note_sync_window_refused_pc(pc: usize) {
    LOWER_BAIL_REASON.with(|c| {
        let (reason, first) = c.get();
        if first.is_none() {
            c.set((reason, Some(pc)));
        }
    });
}

/// The combined-buffer pc of the synchronized splice whose monitor window the
/// last lowering attempt on this thread refused, if it refused one
/// (round 14 wave 3, lane fixup, RV3-1). Read by the IR door right after the
/// lowering call, to rebuild without that splice.
pub(crate) fn last_sync_window_refused_pc() -> Option<usize> {
    LOWER_BAIL_REASON.with(|c| c.get().1)
}

#[cfg(test)]
mod r14w3_fixup_sync_window_blame_tests {
    use super::*;

    /// RV3-1: the first refused window's pc is kept through later refusals
    /// and a labelled bail, and a new attempt starts with none.
    #[test]
    fn the_first_refused_window_is_blamed_until_the_next_attempt() {
        clear_lower_bail();
        assert_eq!(last_sync_window_refused_pc(), None);
        note_sync_window_refused_pc(7);
        note_sync_window_refused_pc(40);
        note_lower_bail("synchronized splice window");
        assert_eq!(last_sync_window_refused_pc(), Some(7));
        assert_eq!(last_lower_bail(), Some("synchronized splice window"));
        clear_lower_bail();
        assert_eq!(last_sync_window_refused_pc(), None);
        assert_eq!(last_lower_bail(), None);
    }
}

/// Shared lowering body: profile-guided branch hints, the optional
/// guard-surviving scalar-replacement map, and the two per-call-site lowering
/// tables all flow in here. `pub(crate)` so the production compile path
/// (`lib.rs`) can supply all of them at once.
///
/// **The code buffer is sized by estimate, and an overflow is retried ONCE at
/// the exact size** (round 9 wave 2, in [`lower_inner_with_array_list`]; round 9
/// wave 1 had corrected this paragraph from "Sizes the code buffer by
/// retrying", which was then untrue — the `lib.rs` retry keyed on
/// `CODE_BUFFER_TOO_SMALL_SITE` serves the single-pass backend, not this one).
/// The measured `ir_code_buffer_estimate` still decides the first attempt; the
/// history below is why that estimate exists. The original estimate
/// (`nodes * 32 + calls * 448 + 1024`) budgeted one number for a call site
/// whose real cost swings by several hundred bytes depending on which lowering
/// it selects — a MIC + 4-way-PIC dual-ABI inline cache is the expensive end,
/// and widening the PIC's inter-slot branch from `rel8` to `rel32` pushed it
/// past the budget. The result was a silent de-optimization: `emit` drops the
/// write, sets the sticky `overflowed` flag, and the method quietly stays
/// interpreted forever. A single Spring Boot suite class produced **8072** such
/// warnings in one run, every one of them from this estimate (the report that
/// first noticed the flood,
/// `basicerrorcontroller-jit-only-failure-20260731-FIXED.md`,
/// attributed them to the single-pass backend's estimate — that one accounted
/// for 10).
///
/// `ExecutableBuffer::wanted()` counts every byte codegen asked for, including
/// the writes dropped after the overflow, so a retry at that size is exact
/// rather than another guess — and since round 9 wave 2 that retry happens,
/// once, in [`lower_inner_with_array_list`]. Raising the constant instead would
/// have to over-reserve every ordinary method to cover the worst one, and
/// every reserved byte counts against the code-cache cap.
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner(
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
) -> Option<CompiledMethod> {
    lower_inner_with_direct_helpers(
        &crate::DirectHelperTable::EMPTY,
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
    )
}

/// [`lower_inner`] for a compile that carries the VM's direct-helper table,
/// which the IR `getstatic` lowering asks for a static slot's base.
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner_with_direct_helpers(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
) -> Option<CompiledMethod> {
    // The inline FRAME sites are forwarded, not emptied: they are a different
    // table with a different consumer (stack traces, not deopt).
    lower_inner_with_array_list(
        direct_helpers,
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
        &HashMap::new(),
        &std::collections::HashSet::new(),
        None,
    )
}

/// [`lower_inner_with_direct_helpers`] plus the compile-time recursion-cycle
/// closing edges this compile planned as [`crate::JitCycleEdgeCell`] sites,
/// `pc -> cell address` (round 9 wave 8, irl8; the IR half of
/// `perf-mutual-recursion-forces-every-call-through-invoke-dispatch`).
///
/// Contract for the producer (`lib.rs`'s IR door): a row is planned exactly as
/// `build_single_pass_tables` plans the single-pass one -- an `invokestatic`
/// closing edge (`note_jit_recursive_compile_cycle` answered `true`), not
/// self-recursive, `jit_cycle_edge_cell_enabled()`,
/// `jit_cycle_direct_bind_enabled()`, `direct_jit_callee_calls_enabled()`,
/// the target not sticky, `helpers.self_call_stack_guard != 0`,
/// `helpers.invoke_dispatch != 0`, and the VM's `cycle_edge_admission`
/// admitting the target -- with a context-ABI cell
/// (`JitCycleEdgeCell::new(.., true)`) whose `Arc` the resulting
/// `CompiledMethod` owns in `_jit_cycle_cells` before it is published. The
/// site keeps its `Op::Call` and `JitInvokeInfo` (the dispatch fallback and
/// the deopt service read it) and gets NO `direct_calls` row. A row the
/// lowerer cannot serve (an argument past the entry-ABI register file, a
/// missing helper, a non-static `invoke_kind`) silently keeps dispatch.
// `lib.rs`'s IR door plans the cells (round 9 wave 8b, NOTES-w8-irl8.md
// cross-lane request 2).
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner_with_cycle_cells(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
    cycle_cells: &HashMap<usize, usize>,
    // Round 9 wave 8b (irl8 request 3): classes whose inline-TLAB `new`
    // announces to ZGC instead of calling `tlab_post_init`. Empty keeps the
    // historical call.
    tlab_announce_classes: &std::collections::HashSet<u32>,
) -> Option<CompiledMethod> {
    lower_inner_with_array_list(
        direct_helpers,
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
        cycle_cells,
        tlab_announce_classes,
        None,
    )
}

/// [`lower_inner_with_cycle_cells`] plus THIS compile's `java/util/ArrayList`
/// layout (round 9 wave 9, irl9), which arms the optimizing tier's inline
/// `ArrayList.get(int)` / `size()` prefix on every `Op::Call` site
/// `crate::try_resolve_arraylist_intrinsic` names
/// (`Lowerer::try_emit_ir_arraylist_access_prefix`).
///
/// Contract for the producer (`lib.rs`'s IR door): pass
/// `resolved_string_layout.and_then(|l| l.array_list)` -- the layout the same
/// compile hands the single-pass tier, never a process-wide latch
/// (the class id and compact offsets are per VM). `None` is byte-identical to
/// [`lower_inner_with_cycle_cells`].
///
/// It absorbed `lower_inner_with_scopes` when round 10 retired
/// `ir::InlineScopeTable` (that function's only extra parameter was the scope
/// table, which every caller passed empty — see the retirement note in
/// `ir.rs`). Since round 11 wave 10 the FULL form, and the retry logic below,
/// live one level down in [`lower_inner_with_protected_ranges`]; this passes
/// it no protected ranges.
///
/// # A code-buffer overflow is retried once (round 9 wave 2)
///
/// The buffer is sized by [`ir_code_buffer_estimate`]; a method that outgrows
/// it used to be refused (`CodeBufferExhausted`) and so lost its optimizing
/// body for good. `ExecutableBuffer::wanted()` is the EXACT requirement — this
/// backend never rewinds, so it counts every byte codegen asked for, dropped
/// writes included — so the first attempt's overflow is not refused: the
/// method is lowered again, once, into a buffer of `wanted()` plus a little
/// slack (the one size-varying encoding is the RIP-relative poll, whose reach
/// depends on where the buffer lands). Only a second overflow refuses.
///
/// What a discarded first attempt leaves behind: its compile-id reservation is
/// dropped (released) with its `Lowerer`; the unroller's thread-local flag is
/// taken ONCE, here, and handed to both attempts; the process-wide diagnostic
/// census counters (`IR_POLLS_*`, `FALLTHROUGHS_ELIDED`, the MIR totals, ...)
/// do count the discarded attempt too — diagnostic skew on a rare path,
/// accepted rather than threading a rollback through every counter.
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner_with_array_list(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
    cycle_cells: &HashMap<usize, usize>,
    tlab_announce_classes: &std::collections::HashSet<u32>,
    array_list: Option<crate::ArrayListFieldLayout>,
) -> Option<CompiledMethod> {
    lower_inner_with_protected_ranges(
        direct_helpers,
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
        cycle_cells,
        tlab_announce_classes,
        array_list,
        &[],
        Some(&[][..]),
    )
}

/// [`lower_inner_with_array_list`] plus the method's protected ranges
/// `[start_pc, end_pc)` (round 11 wave 10, lane irexc) — the FULL form every
/// other `lower_inner*` wrapper now funnels into, and the one `lib.rs`'s IR
/// door calls.
///
/// Contract for the producer: pass the exception table's ranges ONLY on the
/// precise-frame route (an RBC.6 method admitted under
/// `CRATONVM_JIT_IR_PRECISE_HANDLER_FRAMES=1`). A non-empty list puts a
/// reason-9 rethrow pad on every call-exception exit inside it
/// (`Lowerer::push_rethrow_pad`); empty is byte-identical to
/// [`lower_inner_with_array_list`].
///
/// `osr_handler_reachable` (round 11 wave 11, lane irexc) is
/// `deopt::pcs_reachable_from_handlers` over the same method: the bcis at
/// which a body with a rethrow pad may NOT offer an OSR entry
/// (`Lowerer::osr_entry_closed_by_a_handler`). `None` withholds every entry
/// of such a body; `Some(&[])` with empty ranges is byte-identical to the
/// form without it.
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner_with_protected_ranges(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
    cycle_cells: &HashMap<usize, usize>,
    tlab_announce_classes: &std::collections::HashSet<u32>,
    array_list: Option<crate::ArrayListFieldLayout>,
    protected_ranges: &[(u32, u32)],
    osr_handler_reachable: Option<&[u32]>,
) -> Option<CompiledMethod> {
    lower_inner_with_mode_exit_polls(
        direct_helpers,
        graph,
        schedule,
        num_params,
        num_locals,
        helpers,
        branch_hints,
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
        cycle_cells,
        tlab_announce_classes,
        array_list,
        protected_ranges,
        osr_handler_reachable,
        IrPollModeExits::Off,
        None,
        None,
    )
}

/// [`lower_inner_with_protected_ranges`] with the back-edge polls' mode exits
/// (interpreter round i1 wave 15, lane L2): `poll_mode_exits` other than
/// [`IrPollModeExits::Off`] lets an unconditional back-edge poll leave at its
/// loop header when its slow path says the frame (`OsrDoor`, from
/// `CompileRequest::osr_mode_exit_polls`) or the body (`MethodEntry`, wave
/// 18) must run interpreted (`Lowerer::back_edge_mode_exit_state`). `Off` is
/// byte-identical to the form without it. The one `lib.rs` IR door calls
/// this.
#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_inner_with_mode_exit_polls(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    direct_calls: &HashMap<usize, (usize, bool)>,
    ic_slots: &HashMap<usize, (usize, usize)>,
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
    cycle_cells: &HashMap<usize, usize>,
    tlab_announce_classes: &std::collections::HashSet<u32>,
    array_list: Option<crate::ArrayListFieldLayout>,
    protected_ranges: &[(u32, u32)],
    osr_handler_reachable: Option<&[u32]>,
    poll_mode_exits: IrPollModeExits,
    poll_exit_bytecode: Option<PollExitBytecode<'_>>,
    // gen r5w2/oomjit6: the method's own bytecode, unpadded, for the opt-in
    // dead-reference-home clearing (`DeadRefSlotClear`). `None` clears
    // nothing, and is what every caller but `lib.rs`'s IR door passes.
    // gen r5w6/oomjit10: with what its local liveness needs.
    dead_ref_clear_code: Option<DeadRefClearBytecode<'_>>,
) -> Option<CompiledMethod> {
    // Consume the unroller's thread-local "I relied on unreachable frame
    // states" flag FIRST, before any refusal below can return: it describes the
    // graph this call was handed, and a refusal that left it set would hand it
    // to whatever compile runs next on this thread. Read at the deopt-point
    // check near the end of each attempt.
    let unroll_used_unreachable_frames = crate::ir_optimize::take_unroll_used_unreachable_frames();
    // Round nio20 wave 5 (lane L3): the flat bcis a pure-body full unroll
    // stranded, taken here for the same reason; checked against the emission's
    // transfer bcis near the end of each attempt.
    let unroll_stranded_bcis = crate::ir_optimize::take_unroll_stranded_bcis();
    // The acceptance gate's per-compile cost record, as it stood before either
    // attempt charged a blind dispatch to it. See the retry below.
    let blind_dispatch_charge = crate::ir_evidence::blind_dispatch_charge();
    // nio21 wave 3 (lane L5, proposal L5W2-4): the retry ladder below lowers
    // the SAME graph up to four times (estimated size, exact size, and both
    // again with the deopt image kept). Each extra lowering is named under
    // `CRATONVM_DBG_IR_COMPILES` / `CRATONVM_DBG_JITC`, with the graph size,
    // so a compile-cost census can tell a retry from a second compile request
    // (the `ir-post-call-exit site` lines print once per LOWERING).
    let dbg_ladder = crate::x64::dbg_jitc_enabled()
        || cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_COMPILES");
    if dbg_ladder {
        eprintln!(
            "[ir] lowering-ladder start: {} graph node(s), {} block(s)",
            graph.nodes.len(),
            schedule.blocks.len()
        );
    }
    // One lowering at the estimated size, and the one exact-size retry an
    // overflow earns. `keep_image` / `dropped`: see `lower_inner_attempt`.
    let run = |keep_image: bool, dropped: &mut bool| -> Option<CompiledMethod> {
        let mut overflow_wanted: Option<usize> = None;
        *dropped = false;
        let first = lower_inner_attempt(
            direct_helpers,
            graph,
            schedule,
            num_params,
            num_locals,
            helpers,
            branch_hints,
            spliced_ranges,
            sr_map,
            direct_calls,
            ic_slots,
            compact_fields,
            inline_frame_sites,
            cycle_cells,
            tlab_announce_classes,
            array_list,
            protected_ranges,
            osr_handler_reachable,
            poll_mode_exits,
            poll_exit_bytecode,
            dead_ref_clear_code,
            unroll_used_unreachable_frames,
            &unroll_stranded_bcis,
            None,
            Some(&mut overflow_wanted),
            keep_image,
            dropped,
        );
        if first.is_some() {
            return first;
        }
        // `None` with no overflow recorded is an ordinary refusal, already counted.
        let wanted = overflow_wanted?;
        IR_BUFFER_OVERFLOW_RETRIES.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        // Round 11 (irlower): the discarded attempt already charged its blind
        // dispatches to THIS compile's evidence record, and the retry lowers the
        // same graph and charges them again. The census counters may double-count
        // (see above); the gate's input may not -- a doubled charge priced a large
        // spliced body as a regression and refused it.
        if let Some(charge) = blind_dispatch_charge {
            crate::ir_evidence::restore_blind_dispatch_charge(charge);
        }
        let retry_capacity = wanted
            .saturating_add(wanted / 16)
            .saturating_add(IR_BUFFER_RETRY_SLACK);
        if dbg_ladder {
            eprintln!(
                "[ir] lowering-ladder retry: buffer overflow (wanted {wanted} bytes), \
                 lowering again at {retry_capacity} (image kept: {keep_image})"
            );
        }
        *dropped = false;
        lower_inner_attempt(
            direct_helpers,
            graph,
            schedule,
            num_params,
            num_locals,
            helpers,
            branch_hints,
            spliced_ranges,
            sr_map,
            direct_calls,
            ic_slots,
            compact_fields,
            inline_frame_sites,
            cycle_cells,
            tlab_announce_classes,
            array_list,
            protected_ranges,
            osr_handler_reachable,
            poll_mode_exits,
            poll_exit_bytecode,
            dead_ref_clear_code,
            unroll_used_unreachable_frames,
            &unroll_stranded_bcis,
            Some(retry_capacity),
            None,
            keep_image,
            dropped,
        )
    };
    let mut dropped = false;
    let lowered = run(false, &mut dropped);
    if lowered.is_some() || !dropped {
        return lowered;
    }
    // Round 16 wave 13 (lane polyclear): the refused attempt had dropped the
    // deopt register image (`CRATONVM_JIT_IR_DEOPT_IMAGE_EXITLESS`), whose
    // prediction (`Lowerer::deopt_image_never_read`) fails closed: an exit that
    // did need the image refuses the compile. Lower once more with the image
    // kept, so a misprediction costs a second lowering instead of the body.
    // The refused attempt charged its blind dispatches like the overflow
    // retry's discarded one; restore the record the same way.
    if let Some(charge) = blind_dispatch_charge {
        crate::ir_evidence::restore_blind_dispatch_charge(charge);
    }
    if dbg_ladder {
        eprintln!(
            "[cratonvm-jitc] ir-deopt-image dropped and the attempt was refused; lowering again with the image kept"
        );
    }
    run(true, &mut dropped)
}

thread_local! {
    /// The String layout of the compile currently lowering on this thread;
    /// see [`CompileStringLayoutScope`].
    static COMPILE_STRING_LAYOUT: std::cell::Cell<Option<crate::StringFieldLayout>> =
        const { std::cell::Cell::new(None) };
}

/// nio20 wave 3, lane L2: hands THIS compile's `java/lang/String` layout to
/// the lowerer ([`Lowerer::try_emit_ir_string_search_prefix`]) without a
/// new parameter on [`lower_inner_with_mode_exit_polls`] and its dozen test
/// callers.
///
/// A per-THREAD, per-compile value, not a process latch: `lib.rs`'s IR door
/// enters the scope immediately around its one lowering call (on the
/// compiling thread), `lower_inner_attempt` reads it on that same thread, and
/// `Drop` restores whatever was there before -- so a nested compile on the
/// same thread (a callee compiled from inside a compile) cannot leak its
/// layout into, or take it from, the outer one. Outside a scope the value is
/// `None`, which emits no prefix: every unit test and every other door lowers
/// byte-for-byte as before.
pub(crate) struct CompileStringLayoutScope {
    previous: Option<crate::StringFieldLayout>,
}

impl CompileStringLayoutScope {
    /// Install `layout` for the rest of this scope on this thread.
    pub(crate) fn enter(layout: Option<crate::StringFieldLayout>) -> Self {
        let previous = COMPILE_STRING_LAYOUT.with(|c| c.replace(layout));
        CompileStringLayoutScope { previous }
    }

    /// The layout of the innermost open scope on this thread, if any.
    fn current() -> Option<crate::StringFieldLayout> {
        COMPILE_STRING_LAYOUT.with(std::cell::Cell::get)
    }
}

impl Drop for CompileStringLayoutScope {
    fn drop(&mut self) {
        let previous = self.previous;
        COMPILE_STRING_LAYOUT.with(|c| c.set(previous));
    }
}

thread_local! {
    /// Whether a debugger or a JVMTI agent may read the locals of the compile
    /// currently lowering on this thread; see [`CompileLocalsObservedScope`].
    static COMPILE_LOCALS_OBSERVED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// JIT round 21 wave 24 (lane flipprep, item 2 of
/// `r21-optin-flip-review-20261019.md`): hands THIS compile's "an agent may
/// read locals" answer (`CompileRequest::debugger_observes_locals` or
/// `CompileRequest::jvmti_locals_accessible`) to
/// [`Lowerer::volatile_store_fence_elided`], which then computes the
/// fresh-allocation unfenced volatile-store set empty
/// (`CRATONVM_JIT_IR_FRESH_VOLATILE_STORE_UNFENCED`): an agent that reads the
/// new object from a local at a safepoint between the allocation and the
/// store is an observer the escape rule does not see. HotSpot's escape
/// analysis opts out under `can_access_local_variables` the same way.
///
/// Per thread and per compile, as [`CompileStringLayoutScope`]: `lib.rs`'s IR
/// door enters it around its one lowering call, `Drop` restores the previous
/// value (a nested compile cannot leak its answer), and outside a scope the
/// answer is `false`, so every unit test and every other door lowers exactly
/// as before. With the switch off the answer is never read.
pub(crate) struct CompileLocalsObservedScope {
    previous: bool,
}

impl CompileLocalsObservedScope {
    /// Install `observed` for the rest of this scope on this thread.
    pub(crate) fn enter(observed: bool) -> Self {
        let previous = COMPILE_LOCALS_OBSERVED.with(|c| c.replace(observed));
        CompileLocalsObservedScope { previous }
    }

    /// The answer of the innermost open scope on this thread (`false` when
    /// none is open).
    fn current() -> bool {
        COMPILE_LOCALS_OBSERVED.with(std::cell::Cell::get)
    }
}

impl Drop for CompileLocalsObservedScope {
    fn drop(&mut self) {
        let previous = self.previous;
        COMPILE_LOCALS_OBSERVED.with(|c| c.set(previous));
    }
}

/// Bytes added to `wanted()` for the one retry [`lower_inner_with_array_list`]
/// makes after an overflow. See the note there on why the second attempt can
/// differ at all.
const IR_BUFFER_RETRY_SLACK: usize = 256;

/// Compiles that overflowed their first buffer and were lowered again at the
/// exact size (round 9 wave 2). Diagnostic; read by
/// [`ir_buffer_overflow_retries`].
static IR_BUFFER_OVERFLOW_RETRIES: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

/// How many IR compiles were retried after a code-buffer overflow. A non-zero
/// count is the signal to refit `IR_BYTES_PER_NODE` / `IR_BYTES_PER_CALL_NODE`
/// with `CRATONVM_DBG_IR_BUFSIZE`.
#[allow(dead_code)]
pub fn ir_buffer_overflow_retries() -> u64 {
    IR_BUFFER_OVERFLOW_RETRIES.load(std::sync::atomic::Ordering::Relaxed)
}

#[cfg(test)]
thread_local! {
    /// Test hook: size the FIRST attempt's buffer at this many bytes instead
    /// of the estimate, so the overflow-retry path can be driven on purpose.
    static IR_FIRST_ATTEMPT_CAPACITY_FOR_TEST: std::cell::Cell<Option<usize>> =
        std::cell::Cell::new(None);
}

/// One lowering of the graph into one buffer — [`lower_inner_with_array_list`]'s
/// body. `capacity_override` replaces the estimate (the retry passes the first
/// attempt's `wanted()`); `overflow_wanted`, when present, turns an overflow
/// into "record `wanted()` there and return `None` WITHOUT refusing", which is
/// what lets the caller retry without counting a bailout it then avoided.
#[allow(clippy::too_many_arguments)]
/// One compile's inline-frame-row census (interpreter round i1 wave 49, lane
/// L3; [`Lowerer::begin_inline_row_census`]).
#[derive(Debug, Default)]
struct InlineRowCensus {
    /// `(native offset, Some(node pc) when the node lies inside a spliced
    /// body)` where each lowered node's code starts, ascending.
    marks: Vec<(u32, Option<usize>)>,
    /// Where the last node's code ended (the out-of-line code starts).
    closed_at: Option<u32>,
}

/// What [`classify_inline_row_census`] found.
#[derive(Debug, Default, PartialEq, Eq)]
struct InlineRowCensusVerdict {
    /// Calls emitted for a node inside a spliced body.
    spliced: usize,
    /// Those of them whose return address has no inline-frame row, as
    /// `(return address, node pc)`.
    rowless: Vec<(u32, usize)>,
    /// Calls emitted after the last node (stubs, pads, tails): not attributed.
    out_of_line: usize,
}

/// Attribute each call of `calls` (return addresses, ascending) to the node
/// whose code it lies in -- the last mark at or before the call's first byte,
/// i.e. strictly before its return address -- and count the ones inside a
/// spliced body whose return address `filed` (the rows' native offsets) does
/// not name.
fn classify_inline_row_census(
    census: &InlineRowCensus,
    calls: &[u32],
    filed: &std::collections::HashSet<u32>,
) -> InlineRowCensusVerdict {
    let mut verdict = InlineRowCensusVerdict::default();
    for &ret in calls {
        if census.closed_at.is_some_and(|end| ret > end) {
            verdict.out_of_line += 1;
            continue;
        }
        let k = census.marks.partition_point(|&(at, _)| at < ret);
        let Some(&(_, Some(pc))) = k.checked_sub(1).and_then(|i| census.marks.get(i)) else {
            continue;
        };
        verdict.spliced += 1;
        if !filed.contains(&ret) {
            verdict.rowless.push((ret, pc));
        }
    }
    verdict
}

#[cfg(test)]
mod i49_l3_inline_row_census_tests {
    use super::{classify_inline_row_census, InlineRowCensus, InlineRowCensusVerdict};

    /// A call is the node's whose code it lies in (the last mark strictly
    /// before its return address); only a spliced node's calls count, a row
    /// at the return address clears one, and a call past the last node is
    /// out of line.
    #[test]
    fn calls_are_attributed_to_their_node_and_checked_against_the_rows() {
        let census = InlineRowCensus {
            // prologue node at 0 (own code), spliced node pc 40 at 10, own
            // node at 30, an empty spliced node pc 41 at 50, spliced pc 42 at 50.
            marks: vec![
                (0, None),
                (10, Some(40)),
                (30, None),
                (50, Some(41)),
                (50, Some(42)),
            ],
            closed_at: Some(70),
        };
        let filed = [20u32].into_iter().collect();
        let calls = [5, 20, 30, 35, 55, 70, 80];
        assert_eq!(
            classify_inline_row_census(&census, &calls, &filed),
            InlineRowCensusVerdict {
                // 20 (filed), 30 (ends exactly at the own node's start: still
                // the spliced node's), 55 and 70 (pc 42's).
                spliced: 4,
                rowless: vec![(30, 40), (55, 42), (70, 42)],
                out_of_line: 1,
            }
        );
    }
}

fn lower_inner_attempt(
    direct_helpers: &crate::DirectHelperTable,
    graph: &Graph,
    schedule: &Schedule,
    num_params: usize,
    num_locals: usize,
    helpers: &JitRuntimeHelpers,
    branch_hints: &HashMap<usize, bool>,
    spliced_ranges: &[(usize, usize, usize)],
    sr_map: Option<&ScalarReplacementMap>,
    // IR direct-call lowering: `pc → (callee_entry, callee_needs_context)` for
    // every statically-bound call site whose callee was eagerly compiled. Empty
    // ⇒ every `Op::Call` keeps the historical `jit_invoke_dispatch` lowering.
    direct_calls: &HashMap<usize, (usize, bool)>,
    // IR inline-cache lowering: `pc → (mic_slot_addr, pic_slot_addr)` for every
    // virtual / interface site served from an inline cache. Empty ⇒ every such
    // site keeps the historical helper dispatch.
    ic_slots: &HashMap<usize, (usize, usize)>,
    // Guarded inline field reads: `(pc, is_reference) → (packed body offset,
    // is_reference, descriptor tag)` for every resolved compact instance field,
    // plus the two rows the IR String-access expansion needs at its invoke pc.
    // Empty ⇒ every `Op::Load` takes the checked helper, as it always did.
    compact_fields: &HashMap<(usize, bool), (u32, bool, u8)>,
    // Combined-buffer pc → enclosing spliced callees. Empty ⇒ this compile
    // spliced nothing and the artifact's inline frame map stays empty, exactly
    // as it was before 2026-09-08.
    inline_frame_sites: &crate::ir::IrInlineFrameSites,
    // Round 9 wave 8 (irl8): `pc -> JitCycleEdgeCell` for the closing edges
    // of a compile-time recursion cycle. Empty => every such site dispatches.
    cycle_cells: &HashMap<usize, usize>,
    // Round 9 wave 8b (irl8 request 3): see `Lowerer::tlab_announce_classes`.
    tlab_announce_classes: &std::collections::HashSet<u32>,
    // Round 9 wave 9 (irl9): see `Lowerer::array_list_layout`.
    array_list: Option<crate::ArrayListFieldLayout>,
    // Round 11 wave 10 (lane irexc): see `Lowerer::protected_ranges`.
    protected_ranges: &[(u32, u32)],
    // Round 11 wave 11 (lane irexc): see `Lowerer::osr_handler_reachable`.
    osr_handler_reachable: Option<&[u32]>,
    // Interpreter round i1 wave 15 (lane L2): see `Lowerer::poll_mode_exits`.
    poll_mode_exits: IrPollModeExits,
    // Wave 18 (lane L2): see `Lowerer::poll_exit_bytecode`.
    poll_exit_bytecode: Option<PollExitBytecode<'_>>,
    // gen r5w2/oomjit6: see `Lowerer::dead_ref_clear`.
    dead_ref_clear_code: Option<DeadRefClearBytecode<'_>>,
    // Taken once by the caller (see there) and read at the deopt-point check
    // near the end.
    unroll_used_unreachable_frames: bool,
    // Round nio20 wave 5 (lane L3): taken once by the caller, like the flag
    // above; see the pure-body unroll's net near the end.
    unroll_stranded_bcis: &[usize],
    capacity_override: Option<usize>,
    overflow_wanted: Option<&mut Option<usize>>,
    // Round 16 wave 13 (lane polyclear): `true` keeps the deopt register image
    // whatever `CRATONVM_JIT_IR_DEOPT_IMAGE_EXITLESS` says (the fallback
    // attempt), and `image_dropped` reports whether this attempt dropped it.
    keep_deopt_image: bool,
    image_dropped: &mut bool,
) -> Option<CompiledMethod> {
    // A monitor whose helper is absent must REFUSE the compile.
    //
    // History, because the shape of it is the reason `lower_data_node`'s final
    // arm now refuses too. `ir::Op::MonitorEnter`/`MonitorExit` were added for
    // escape analysis (lock elision) BEFORE either a lowering arm or a
    // `JitRuntimeHelpers` monitor entry existed. `lower_data_node`'s catch-all
    // was `_ => {}` at the time, so an unguarded monitor compiled to *nothing*
    // — the lock silently gone, an unbalanced `monitorexit` left behind, a data
    // race rather than a missed optimization. This guard was written to keep
    // that unreachable.
    //
    // Both halves have since landed: `lower_data_node` has a real
    // `Op::MonitorEnter | Op::MonitorExit` arm that calls the helper, and
    // `a_synchronized_region_lowers_through_the_monitor_helper` drives it. So
    // what remains here is narrower than the comment this replaces claimed: a
    // graph with monitor ops and a helper table that has no monitor entry (in
    // practice a synthetic unit-test table). Refuse rather than call through a
    // zero pointer.
    //
    // The general form of the original hazard — an `ir::Op` variant with no arm
    // at all — is now handled where it arises, by that final arm, instead of
    // needing a new hand-written guard here per op. See
    // `docs/feature-designs/jit-machine-level-and-instruction-selection.md`,
    // "The cheap alternative".
    if (helpers.monitor_enter == 0 || helpers.monitor_exit == 0)
        && graph
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::MonitorEnter | Op::MonitorExit))
    {
        return refuse(Bailout::with_context(
            BailoutReason::UnsupportedShape("monitor helper absent"),
            "graph contains monitor ops but the helper table has no monitor \
             entry; refusing rather than emitting nothing and dropping the lock",
        ));
    }
    // A live object allocation is now supported by the common allocation
    // stub. A zero helper pointer is only possible in synthetic unit-test
    // tables; reject it instead of emitting a call through address zero.
    if helpers.new_object == 0
        && graph
            .nodes
            .iter()
            .any(|node| matches!(node.op, Op::New { .. }))
    {
        return refuse_labelled("new-without-alloc-helper");
    }
    // cov-06. Same reasoning, split per `Op::NewArray` shape: a PRIMITIVE
    // array (`element_type != 0`) needs `helpers.newarray` wired; a
    // REFERENCE array (`element_type == 0`) needs `helpers.anewarray_object`.
    // Only a synthetic unit-test table leaves either at 0.
    if graph
        .nodes
        .iter()
        .any(|node| matches!(node.op, Op::NewArray { element_type, .. } if element_type != 0))
        && helpers.newarray == 0
    {
        return refuse_labelled("newarray-primitive-without-helper");
    }
    if graph
        .nodes
        .iter()
        .any(|node| matches!(node.op, Op::NewArray { element_type, .. } if element_type == 0))
        && helpers.anewarray_object == 0
    {
        return refuse_labelled("anewarray-without-helper");
    }
    // nio21 wave 15 (lane L3): a deferred `new` calls `new_object_cp`, and a
    // zero there is a CALL to address 0. The arm latches the same refusal; this
    // one names it before any code is emitted.
    if helpers.new_object_cp == 0 && graph.nodes.iter().any(|n| matches!(n.op, Op::NewCp { .. })) {
        return refuse_labelled("new-cp-without-helper");
    }
    // cov-01. The same reasoning as the two guards above, for the three
    // constant-pool nodes: each lowers to a `CALL` through a helper address,
    // and a zero there is a call to address 0. Only a synthetic unit-test table
    // can produce one — `build_helpers` always wires all three — but "only a
    // test can hit it" is what the monitor guard's history says not to rely on.
    //
    // `Op::LoadStatic` is guarded on the helper even though its usual route is
    // the direct load: which route a site takes is decided per site inside
    // `emit_inline_getstatic`, and any site the resolver declines falls back to
    // this helper. Refusing the graph is the only answer that does not depend
    // on a runtime resolver's answer at emission time.
    for (helper, present, what) in [
        (
            helpers.ldc_string_cp,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::ConstString { .. })),
            "ldc_string_cp",
        ),
        (
            helpers.ldc_class_cp,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::ConstClass { .. })),
            "ldc_class_cp",
        ),
        (
            helpers.getstatic,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::LoadStatic { .. })),
            "getstatic",
        ),
        // A WIDE static's helper route peeks `jit_dispatch_threw` to tell a
        // legitimate `Long.MIN_VALUE` from the exception sentinel, so that
        // helper is load-bearing for exactly the `J`/`D`/`F` tags and for
        // nothing else. `Op::Call` reaches the same peek and does not guard it
        // — its wide-return sites are gated elsewhere — but a wide static
        // arrives here through a table, so state the requirement rather than
        // inherit an assumption.
        (
            helpers.dispatch_threw,
            graph.nodes.iter().any(|n| {
                matches!(n.op, Op::LoadStatic { type_tag, .. } if matches!(type_tag, b'J' | b'D' | b'F'))
            }),
            "dispatch_threw (needed by a J/D/F getstatic)",
        ),
        // `Op::StoreStatic` has no route but its helper, one per width.
        (
            helpers.putstatic_int,
            graph.nodes.iter().any(|n| {
                matches!(n.op, Op::StoreStatic { type_tag, .. }
                    if !matches!(type_tag, b'J' | b'F' | b'D' | b'L' | b'['))
            }),
            "putstatic_int",
        ),
        (
            helpers.putstatic_long,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::StoreStatic { type_tag: b'J', .. })),
            "putstatic_long",
        ),
        (
            helpers.putstatic_float,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::StoreStatic { type_tag: b'F', .. })),
            "putstatic_float",
        ),
        (
            helpers.putstatic_double,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::StoreStatic { type_tag: b'D', .. })),
            "putstatic_double",
        ),
        (
            helpers.putstatic_object,
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::StoreStatic { type_tag: b'L' | b'[', .. })),
            "putstatic_object",
        ),
    ] {
        if helper == 0 && present {
            return refuse(Bailout::with_context(
                BailoutReason::UnsupportedShape("constant-pool helper absent"),
                format!(
                    "graph contains a cov-01 constant-pool node but the helper table has no \
                     `{what}` entry; refusing rather than emitting a CALL through address zero"
                ),
            ));
        }
    }
    // Compact field layout (default ON) packs field offsets, so `Op::Load` and
    // `Op::Store`'s inline `HEADER_SIZE + field_index*SLOT_SIZE` displacements
    // are wrong for a compact object. Both have a compact-correct alternative —
    // the `jit_getfield` / `jit_putfield_int` helpers — so the only unlowerable
    // combination is "compact layout on AND the helper address absent", which
    // in practice means a synthetic unit-test helper table.
    //
    // This check used to live in `IrBuilder::build` as an unconditional bail on
    // the getfield/putfield opcodes themselves, which refused every
    // field-accessing method — most of real Java — from the optimizing tier
    // regardless of which lowering would have been chosen. Keeping it here
    // states the actual constraint: it is a property of one lowering, not of
    // the opcode.
    if cratonvm_types::compact_ref_fields_enabled() {
        let needs_getfield_helper =
            helpers.getfield == 0 && graph.nodes.iter().any(|n| matches!(n.op, Op::Load(_)));
        // Only an INT store has an inline lowering to fall back to, so only an
        // int store is what this compact-layout clause is about. Every other
        // `MemKind` is helper-only in both layouts and is refused
        // unconditionally below — checking `putfield_int` for them would refuse
        // a reference store for the absence of a helper it never calls.
        let needs_putfield_helper = helpers.putfield_int == 0
            && graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::Store(MemKind::Int)));
        if needs_getfield_helper || needs_putfield_helper {
            return refuse_labelled("getfield-or-putfield-helper-required");
        }
    }
    // A REFERENCE or WIDE field read has only one correct lowering: the helper.
    // The inline displacement fallback decodes a 16-byte int cell at
    // `HEADER_SIZE + index*SLOT_SIZE`, which for a reference slot yields the
    // discriminant word rather than the pointer — a fabricated address the
    // frame would then publish as a root — and for a `J`/`F`/`D` slot yields a
    // sign-extended half of the payload. Refuse the graph outright rather than
    // emit it, independently of the compact-layout switch above.
    //
    // A wide read additionally needs `jit_dispatch_threw`: `Long.MIN_VALUE`,
    // and the `-0.0` bit pattern, are bit-identical to the helper's deopt/NPE
    // sentinel, and without the out-of-band peek the lowering must either drop
    // a real NPE or bail on a legitimate value. Neither is acceptable, so
    // refuse instead. `Float` is included for the same reason the `J`/`D`/`F`
    // branch of `emit_call_return_check` includes it: the disambiguation is one
    // shape, keyed on the value's WIDTH CLASS rather than on a claim about what
    // `jit_getfield` happens to zero-extend today.
    if graph.nodes.iter().any(|n| {
        matches!(
            n.op,
            Op::Load(MemKind::Ref | MemKind::Long | MemKind::Float | MemKind::Double)
        )
    }) && helpers.getfield == 0
    {
        return refuse_labelled("wide-load-without-getfield-helper");
    }
    if helpers.dispatch_threw == 0
        && graph.nodes.iter().any(|n| {
            matches!(
                n.op,
                Op::Load(MemKind::Long | MemKind::Float | MemKind::Double)
            )
        })
    {
        return refuse_labelled("wide-load-shape-unsupported");
    }
    // COV-03 — every non-int field STORE is helper-only, and each width has its
    // own helper. A reference store's helper is the one that carries the write
    // barrier; emitting the store without it is the failure this lane is most
    // careful about (invisible until a concurrent or generational collection,
    // and it surfaces as a lost object, not as a fault at the store). Refuse
    // rather than substitute.
    for n in &graph.nodes {
        let missing = match n.op {
            Op::Store(MemKind::Ref) => helpers.putfield_object == 0,
            Op::Store(MemKind::Long) => helpers.putfield_long == 0,
            Op::Store(MemKind::Float) => helpers.putfield_float == 0,
            Op::Store(MemKind::Double) => helpers.putfield_double == 0,
            _ => false,
        };
        if missing {
            return refuse_labelled("putfield-helper-missing-for-width");
        }
    }
    // Every field access carries its slot index as a `Const` offset input, and
    // both lowerings read that index out of the node the edge points at. If it
    // is not a `Const`, neither has an index to use — and both used to fall
    // back to a silent `0`, i.e. to accessing SOME OTHER FIELD of the receiver.
    //
    // A silent `0` is the worst available answer for exactly the defect family
    // this lane keeps meeting: a store lands in a slot the class declares a
    // reference, the cell then holds a primitive under a reference's name, and
    // the fault appears much later in whatever dereferences it — a compiled
    // `arraylength` on `Int(1)`, faulting at `addr=0x5`
    // (`punned-sqlchar-rawdata-was-a-direct-call-pinned-by-address-FIXED-20260828.md`).
    // Nothing in the report points back here, because a wrong-slot write leaves
    // no trace of having chosen the wrong slot.
    //
    // The builder only ever emits `iconst(field_index)` into this edge, so this
    // is unreachable today and refusing costs nothing measurable. That is the
    // point: it closes the hazard while it is still unreachable, rather than
    // after some later optimisation makes the offset node non-constant and the
    // fallback starts silently corrupting objects.
    if graph.nodes.iter().any(|n| {
        matches!(n.op, Op::Load(_) | Op::Store(_))
            && n.inputs
                .get(3)
                .and_then(|&o| graph.nodes.get(o as usize))
                .map_or(true, |o| !matches!(o.op, Op::Const(_)))
    }) {
        return refuse_labelled("non-const-store-operand");
    }

    // ── Resource bounds, decided before anything is reserved ─────────
    //
    // Both checks precede `ExecutableBuffer::new` and `Lowerer::new`, so an
    // over-budget method costs neither an executable mapping nor an enormous
    // frame. `estimate_frame_bytes` is the same function `Lowerer::new` sizes
    // the frame from, so passing here guarantees the constructor's `i32`
    // arithmetic stays in range.
    if let Err(bailout) = check_graph_size(graph.nodes.len(), DEFAULT_MAX_NODES) {
        return refuse(bailout);
    }
    let frame_needs = scan_frame_needs(graph, helpers);
    // Liveness-based frame-slot reuse: values whose live ranges do not overlap
    // share one 8-byte word, so the spill reservation is sized by the peak
    // number of simultaneously live values instead of by the node count. The
    // colouring is *checked* before it is used — an aliased pair of live values
    // is silent wrong code, so it is not taken on trust.
    //
    // Interpreter round i2 wave 66 (lane L2): under
    // `CRATONVM_JIT_IR_ONE_LIVENESS_PASS` the liveness answer behind this plan
    // is also the one the allocator's model is built from below (residency,
    // OSR entry stubs), instead of a second run of the same fixed point.
    // JIT round 19 wave 10 (lane lv10, `CRATONVM_JIT_IR_LIVENESS_SHARED_SCRATCH`,
    // opt-in): one liveness scratch for the legacy copies this compile runs
    // (the slot plan here, the dead-home value ranges and the live model below).
    let mut liveness_scratch = crate::regalloc::liveness_shared_scratch_enabled()
        .then(crate::regalloc::LivenessScratch::new);
    let (mut slot_plan, one_liveness_pass) =
        plan_slots_one_pass_scratch(graph, schedule, sr_map, liveness_scratch.as_mut());
    // JIT round 19 wave 8 (lane osr8, OSR7-1,
    // `CRATONVM_JIT_IR_LOOP_FIELD_PROMOTE_PENDING_LIVE`): the pending values a
    // promoted loop's pads name are live at those pads, in this plan and in
    // the allocator's model below alike. Empty (no change) unless the switch
    // and `..._PENDING_RESIDENT` are on and the graph keeps a silent store.
    let pending_live = pending_deopt_live_widening(graph, schedule);
    if !pending_live.rows.is_empty() {
        let grew = widen_slot_plan_for_pending(&mut slot_plan, &pending_live);
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[ir] loop field promote: {} pending value(s) live to their pads, {grew} slot range(s) widened",
                pending_live.rows.len()
            );
        }
    }
    let slot_plan = slot_plan;
    if let Err(bailout) = verify_slot_colouring(graph, schedule, &slot_plan) {
        return refuse(bailout);
    }
    if crate::regalloc::one_liveness_pass_enabled()
        && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
    {
        eprintln!(
            "[ir-ls] one liveness pass: {}",
            match &one_liveness_pass {
                Ok(_) => "shared",
                Err(why) => why.label(),
            }
        );
    }
    let mut one_liveness_pass = one_liveness_pass.ok();
    let frame_estimate = estimate_frame_bytes(num_locals, slot_plan.slots, &frame_needs);
    if let Err(bailout) = check_frame_size(frame_estimate, DEFAULT_MAX_FRAME_BYTES) {
        return refuse(bailout);
    }
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
        eprintln!(
            "[ir-slots] nodes={} blocks={} slots={} peak_live={} frame_bytes={frame_estimate} \
             chain_ranged={}",
            graph.nodes.len(),
            schedule.blocks.len(),
            slot_plan.slots,
            slot_plan.peak_live,
            slot_plan.chain_ranged,
        );
        for (id, colour) in slot_plan.node_color.iter().enumerate() {
            if let Some(c) = colour {
                eprintln!(
                    "[ir-slots]   node {id:3} -> colour {c} class={:?}",
                    slot_plan.class.get(id).copied().flatten(),
                );
            }
        }
    }

    // ── Every emitted value has a location, decided before emission ──
    //
    // The acceptance test for the `[rbp - 0]` defect: drop a node from the
    // schedule and this refuses the compile here, with no code emitted at all,
    // instead of emitting a read of the saved caller frame pointer and
    // detecting it afterwards with a sticky bit.
    if let Err(bailout) = verify_data_locations(graph, schedule) {
        return refuse(bailout);
    }

    // Buffer sizing. The historical estimate (`nodes * 32 + 256`) predates call
    // lowering: an arithmetic node emits well under 32 bytes, but a single
    // MIC + 4-way-PIC dual-ABI inline-cache site emits ~360 and a direct call
    // ~60. With
    // `ir_compatible`'s invoke budget raised to `ir::IR_MAX_INVOKES`,
    // under-estimating here would silently TRUNCATE the body —
    // `ExecutableBuffer::emit` sets a sticky `overflowed` flag and skips the
    // write rather than panicking — so budget every call node explicitly, with
    // the same saturating arithmetic the single-pass sizing uses.
    let call_nodes = graph
        .nodes
        .iter()
        .filter(|n| {
            matches!(
                n.op,
                Op::Call { .. }
                    | Op::IndyBridge { .. }
                    | Op::MultiNewArray { .. }
                    | Op::NewCp { .. }
            )
            // JIT round 20 (MHIFACE19-1): a seen-class `instanceof` adds its
            // two cell compares and post-call write (~110 bytes) to the arm.
            || matches!(n.op, Op::InstanceOf { seen_cell, .. } if seen_cell != 0)
        })
        .count();
    let estimate = ir_code_buffer_estimate(graph.nodes.len(), call_nodes)
        .saturating_add(ir_ref_home_publication_reserve(graph, schedule, &slot_plan));
    #[cfg(test)]
    let estimate = if capacity_override.is_none() {
        IR_FIRST_ATTEMPT_CAPACITY_FOR_TEST
            .with(|c| c.get())
            .unwrap_or(estimate)
    } else {
        estimate
    };
    // The retry never goes BELOW the estimate: `wanted()` is exact for the
    // first attempt's bytes, and the estimate is what every other compile gets.
    let capacity = match capacity_override {
        Some(c) => c.max(estimate),
        None => estimate,
    };
    // `new_in`, not `new`: the process-wide JIT code arena carves this body
    // out of a shared executable reservation instead of taking its own
    // `VirtualAlloc`/`mmap`. Behaviour is byte-identical while
    // `CRATONVM_JIT_CODE_ARENA` is unset, because `new_in` falls straight
    // through to `new` then — so this call site is what makes the flag
    // reachable, not what changes the default.
    // A failed reservation (code cache at its cap, arena exhausted) is a
    // refusal like any other: route it through `refuse` so it is counted and
    // labelled instead of vanishing through a bare `?`.
    let Some(mut buf) =
        ExecutableBuffer::new_in(crate::platform::shared_jit_code_arena(), capacity)
    else {
        return refuse_labelled("executable-buffer-reservation-failed");
    };
    buf.set_tag("ir-lower");

    let mut lowerer = Lowerer::new(
        graph,
        schedule,
        buf,
        num_params,
        num_locals,
        &slot_plan,
        helpers,
        branch_hints,
        // NOT `&[]`. This argument was dropped on the floor from the day
        // splicing landed: the parameter arrived, `Lowerer::new` got an
        // empty slice, and `Lowerer::resume_bci` was therefore the identity
        // in every production lowering. Every deopt inside a spliced body
        // then recorded its RELOCATED bci — a program point that does not
        // exist in the method's own bytecode — so the interpreter's sink
        // found no matching deopt point, defaulted the reason to
        // `UnreachedCode`, and refused the replay against a bci nothing
        // could resume at. See
        // `ir-inline-turns-an-index-out-of-bounds-into-an-internalerror-FIXED-20260828.md`.
        spliced_ranges,
        sr_map,
        direct_calls,
        ic_slots,
        compact_fields,
        inline_frame_sites,
    );
    lowerer.direct_helpers = *direct_helpers;
    lowerer.cycle_cells = cycle_cells.clone();
    lowerer.tlab_announce_classes = tlab_announce_classes.clone();
    lowerer.array_list_layout = array_list;
    lowerer.string_layout = CompileStringLayoutScope::current();
    lowerer.protected_ranges = protected_ranges.to_vec();
    lowerer.osr_handler_reachable = osr_handler_reachable.map(<[u32]>::to_vec);
    // Not when the unroller relied on a trap-free body (wave 18, lane L2):
    // its net below refuses a compile that built any deopt point, but the
    // poll exits are appended after that check, and a header state naming a
    // value the unroller killed would resume with an `Undefined` local.
    //
    // Shape 2 (b) of the i41 page, its last member: under
    // `CRATONVM_JIT_IR_EXITS_BESIDE_DROPPED_SNAPSHOT_VALUES` the exits are
    // kept, and each one whose header state lost a live value refuses on its
    // own (`Lowerer::state_lost_a_value_to_the_optimizer`). The full unroller
    // leaves a killed node in a snapshot, which `current` already refuses; a
    // strength-reduced multiply leaves `NO_NODE`, which the state would
    // otherwise describe as `Undefined`.
    lowerer.optimizer_dropped_snapshot_values = unroll_used_unreachable_frames;
    if unroll_used_unreachable_frames
        && poll_mode_exits != IrPollModeExits::Off
        && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_JITC")
    {
        eprintln!(
            "[ir-mode-exit] optimizer-dropped-snapshot-values {} method={}",
            if poll_mode_exits.is_method_entry() {
                "method-entry"
            } else {
                "osr-door"
            },
            graph.scope_method_key,
        );
    }
    lowerer.poll_mode_exits =
        if unroll_used_unreachable_frames && !ir_exits_beside_dropped_snapshot_values_enabled() {
            IrPollModeExits::Off
        } else {
            poll_mode_exits
        };
    lowerer.poll_exit_bytecode = poll_exit_bytecode;
    // gen r5w2/oomjit6: opt-in, and only with the method's bytecode in hand.
    // gen r5w3/live7: the same facts feed the store-free claim
    // (`CRATONVM_JIT_PRECISE_FRAME_LIVENESS`); with both flags off nothing is
    // built and every byte below is unchanged.
    let clear_stores = ir_clear_dead_ref_slots_enabled();
    let precise_liveness = ir_precise_frame_liveness_enabled();
    // gen r5w5/oomjit9: the default-on dead-home clears need the same facts.
    let dead_home_clears = ir_dead_home_clears_enabled();
    // gci i1/fr (opt-in): allocation nodes are armed sites too. Read here and
    // by the two keep-set builders (`dead_ref_clear_arms`), once per compile.
    lowerer.alloc_site_clears = ir_alloc_site_clears_enabled();
    // gci i4/ir (opt-in): the pinned non-call GC points too, read the same way.
    lowerer.other_site_clears = ir_other_gc_point_clears_enabled();
    lowerer.dead_ref_clear = match dead_ref_clear_code {
        Some(bytecode) if clear_stores || precise_liveness || dead_home_clears => {
            plan_dead_ref_slot_clear(
                graph,
                schedule,
                &slot_plan,
                bytecode,
                spliced_ranges,
                ir_precise_keep_set_enabled(),
                liveness_scratch.as_mut(),
            )
        }
        _ => None,
    };
    lowerer.dead_ref_clear_stores = clear_stores && lowerer.dead_ref_clear.is_some();
    lowerer.frame_liveness_on = precise_liveness && lowerer.dead_ref_clear.is_some();
    // gci i5/ir (opt-in): the loop back-edge polls are armed sites too; the
    // keep-set builders above recorded their after-sets under the same switch.
    if lowerer.dead_ref_clear.is_some() && ir_poll_gc_point_clears_enabled() {
        lowerer.poll_edge_pos =
            block_edge_positions(schedule, &lowerer.slot_plan.pos_of).unwrap_or_default();
    }
    if dead_home_clears {
        lowerer.prefix_slow_path_clears = ir_prefix_slow_path_clears_enabled();
        // JIT round 20 wave 17, lane gcDead (I-9): read before the plan,
        // which arms allocation sites with it (and drops it on no plan).
        lowerer.alloc_dead_home_clear = ir_alloc_dead_home_clear_enabled();
        lowerer.dead_home_clears_complete = lowerer.plan_dead_home_clears();
    }
    // gci i3/ir (opt-in): the reference parameters whose prologue word is
    // zeroed after their copy. Only with the dead-reference facts (they are
    // withheld under a debugger) and the default dead-home clears, which are
    // what then clear the copy where it is dead.
    if dead_home_clears && lowerer.dead_ref_clear.is_some() && ir_ref_param_home_zero_enabled() {
        // gci i4/ir: `node_to_block[graph.entry]` is `usize::MAX` on every
        // real schedule (`Op::Start` is never placed), which made i3's plan
        // admit nothing (vi3-ir A VOID); the entry block is found by its head.
        let entry_block = scheduled_entry_block(graph, schedule).unwrap_or(usize::MAX);
        let entry_has_predecessors = !schedule
            .blocks
            .first()
            .is_some_and(|b| b.predecessors.is_empty());
        // gci i4/ir: parameter 0 is a reference parameter like any other in a
        // STATIC method (`receiver_param` is `None` exactly for those in
        // `lib.rs`'s builder); it stays out for an instance method (the
        // receiver: self-lock exits, `held_monitors.rs`) and whenever a
        // method-monitor fact names it.
        let param0_admitted =
            graph.receiver_param.is_none() && graph.method_monitor_param.is_none();
        lowerer.ref_param_home_zero = ref_param_home_zero_candidates(
            graph,
            &schedule.node_to_block,
            entry_block,
            entry_has_predecessors,
            param0_admitted,
        );
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_SLOTS") {
            eprintln!(
                "[ir-slots] ref param home zero plan: entry_block={entry_block} preds={entry_has_predecessors} param0={param0_admitted} candidates={:?}",
                lowerer.ref_param_home_zero
            );
        }
        // gci i5/ir (opt-in, the cost of the eager store): the zeroing moves to
        // the planned clears of each parameter's own colour.
        if ir_ref_param_home_zero_lazy_enabled() {
            lowerer.plan_lazy_ref_param_home_zero();
        }
    }
    // JIT round 20 wave 21 (lane pollroot): independent of the plan above --
    // a back-edge poll's clears are argued from dominance, not from it.
    lowerer.back_edge_dead_home_clear = ir_back_edge_dead_home_clear_enabled();

    // Null-check and bounds-check elimination. Runs on the SCHEDULED graph
    // because both facts are dominance facts and dominance is over the block
    // CFG the scheduler built -- so it must be after `schedule` and before any
    // array site is emitted, which is exactly here.
    lowerer.check_elision = crate::ir_check_elim::analyze(graph, schedule);

    // Gap B: only `abi_regs.len()` integer registers carry incoming args (4 on
    // Win64, 6 on SysV), and a `needs_context` method spends the first of them
    // on the hidden VM pointer; anything past that arrives on the caller's
    // stack. `emit_prologue` loads those stack-resident arguments now, exactly
    // as the single-pass prologue does, so there is no refusal here any more.
    // History, because it cost a lot to learn: when the prologue could only
    // read registers, a guard here once sat inside `if lowerer.needs_context`
    // and left LEAF methods unguarded — `probes/EntryAbiArgSlotProbe.java`
    // measured `i4`/`s5` (5 slots) wrong and silently emptied Spring Boot's
    // property binding (`webflux-defaultpathcontainer-defaultseparator-classcast-FIXED.md`).
    // (The refusal that used to be here — "incoming arg slots exceed the entry
    // ABI registers" — is gone: `emit_prologue` loads stack-resident arguments
    // now, exactly as the single-pass prologue does. It was the commonest
    // whole-method refusal an ordinary accessor hit; `VolumeShort2.getIndex(III)I`
    // is `this` + three ints = four incoming slots, and touching one field turns
    // `needs_context` on, which is the fifth. Two separate investigations
    // reached that line by bisecting the lowerer rather than by reading a log.)

    // BUG FIX [jit-irlower #2]: reserve phi destination slots before any
    // block is lowered — a forward branch's edge copies (emit_phi_copies)
    // reference slots of phis in not-yet-lowered merge blocks.
    if let Err(bailout) = lowerer.prealloc_phi_slots() {
        return refuse(bailout);
    }

    // ── Linear-scan register residency (default ON since 2026-09-02) ─
    //
    // The production call site for `regalloc::allocate_linear_scan`. Installed
    // BEFORE the prologue and never touched again, so residency is a property
    // of the whole emission rather than something that changes mid-body.
    //
    // A verifier failure is the one hard stop. `plan_register_residency`
    // returns `Err` only when `verify_allocation` rejects the allocation — a
    // compiler bug — and emitting against an allocation nothing proved is
    // exactly the trade that has produced silent heap corruption here before.
    // Refuse the body; the method runs in a lower tier, which is always valid.
    // Everything else it can decline (register pressure, a liveness-model
    // disagreement, a value it cannot prove) comes back as `Ok(None)` and
    // leaves the colourer's memory layout in charge.
    //
    // The level-2 selector and this cache are MUTUALLY EXCLUSIVE, and the
    // exclusion belongs here rather than in either of them. `isel`'s encoder is
    // anchored byte-for-byte against the per-opcode arms under the assumption
    // that "the frame-homed allocation the encoder assumes IS this backend's
    // allocation" — which residency makes false, because an arm then reads its
    // operand out of a register while the tiler still emits a frame load.
    //
    // Neither outcome is unsound (write-through keeps the home word correct, so
    // the tiler's frame read gets the right value, and `Verify` mode is
    // fail-closed), but the two would silently disagree about bytes, which is
    // the one property the level-2 lane exists to be able to check. So while a
    // MIR mode is on, residency is off and the selector is compared against the
    // emission it was anchored to.
    // Interpreter round i2 wave 63 (lane L2, the i58-L2 proposal's first
    // measurement): `CRATONVM_DBG_IR_LS_TOKEN_TRIM_CENSUS=1` prints how many
    // intervals `CRATONVM_JIT_IR_LS_TOKEN_EDGES_NOT_USES` would shorten in
    // this graph (`regalloc::TokenTrimCensus`). Diagnostic only: it builds
    // two throwaway models and changes nothing below. One line per attempt
    // (a buffer-overflow retry prints again).
    if crate::regalloc::ls_token_trim_census_enabled() {
        match crate::regalloc::token_trim_census(graph, schedule) {
            Some(mut census) => {
                // Wave 64 (lane L2): the frame-home column
                // (`CRATONVM_JIT_IR_SLOTS_TOKEN_EDGES_NOT_USES`).
                census.slot_plan = Some(token_trim_slot_column(graph, schedule, sr_map));
                eprintln!("{}", census.render());
            }
            None => eprintln!("[ir-ls] token-trim census: not converged"),
        }
    }
    let mut ls_active = false;
    // The residency planner's liveness model, kept for `emit_osr_entry_stubs`
    // below when this body may carry OSR entries (see the note there).
    let mut residency_live: Option<crate::regalloc::LiveModel> = None;
    if linear_scan_enabled() && !isel_emit_enabled() && !isel_verify_enabled() {
        let mut live = match one_liveness_pass.take() {
            Some(pass) => pass.into_live_model(graph, schedule),
            None => match liveness_scratch.as_mut() {
                Some(scratch) => {
                    crate::regalloc::build_live_model_scratch(graph, schedule, scratch)
                }
                None => crate::regalloc::build_live_model(graph, schedule),
            },
        };
        // OSR7-1 (lane osr8): the same widening as the slot plan's above.
        widen_live_model_for_pending(&mut live, &pending_live);
        let planned = plan_register_residency_with(graph, schedule, &slot_plan, &mut live);
        // JIT round 19 wave 7 (lane osr7, OSR6-1): the allocator's ranges, for
        // the pads' residency descriptions (`Lowerer::pending_resident_reg`).
        // Copied before `live` moves; only when they can be read.
        let pending_ls = (ir_loop_field_promote_pending_resident_enabled()
            && !graph.promoted_sunk_stores.is_empty()
            && live.converged)
            .then(|| {
                (
                    live.range
                        .iter()
                        .map(|r| r.as_ref().map(|r| (r.lo, r.hi)))
                        .collect::<Vec<_>>(),
                    live.pos_of.clone(),
                )
            });
        if ir_osr_entry_enabled() {
            residency_live = Some(live);
        }
        match planned {
            Ok(Some(residency)) => {
                if crate::ir_stage_reporting() {
                    // The phi count is reported beside the total because it is
                    // the one that answers "did the loop-carried values move",
                    // and a total alone cannot: nineteen resident transients
                    // beside a frame-homed loop counter reads the same as the
                    // shape this file was built to produce.
                    eprintln!(
                        "[ir] linear scan: {} values resident, {} demoted, {} of {} phis resident",
                        residency.promoted,
                        residency.demoted,
                        residency.phi_census.resident,
                        residency.phi_census.total(),
                    );
                }
                lowerer.set_residency(residency);
                if let Some((range, pos)) = pending_ls {
                    lowerer.pending_ls_range = range;
                    lowerer.pending_ls_pos = pos;
                }
                ls_active = true;
            }
            Ok(None) => {}
            Err(bailout) => return refuse(bailout),
        }
    }

    // ── Shadow instruction selection (default OFF, emits nothing) ────
    //
    // Placed here, after every refusal above, so the population it measures is
    // exactly the population that gets a compiled body — measuring methods the
    // lowerer then refuses would inflate the figure with code nobody runs.
    //
    // Deliberately NOT fail-closed, which is the one place in this file that is
    // true. See `isel::shadow_select_method`: a flag whose documented effect is
    // a count must not decide what compiles, or the count describes a different
    // program. A `covers()` violation is counted and printed, not raised.
    if isel_shadow_enabled() {
        let stats = crate::x64::isel::shadow_select_method(graph, schedule);
        if isel_shadow_reporting() {
            eprintln!("[ir-isel] {}", stats.summary_line());
        }
    }

    // ── The level-2 machine list (default OFF) ───────────────────────
    //
    // Increment 2. Unlike the shadow pass above this one IS fail-closed, in
    // both its modes: a method whose blocks the selector cannot cover, or whose
    // tiles disagree with the per-opcode arms, loses its optimized body rather
    // than getting one nobody checked.
    let mir_mode = if isel_emit_enabled() {
        Some(MirMode::Emit)
    } else if isel_verify_enabled() {
        Some(MirMode::Verify)
    } else {
        None
    };
    if let Some(mode) = mir_mode {
        match build_mir_plan(graph, schedule) {
            Some(plan) => {
                // Increment 2: the machine list gets an allocation, and the
                // allocation gets `verify_allocation`. Runs BEFORE `set_mir`,
                // so a plan the verifier rejects is never installed and the
                // encoder never sees it.
                match verify_mir_allocation(graph, schedule, &slot_plan, &plan) {
                    Ok(verdict) => mir_totals::record_alloc(verdict),
                    Err(bailout) => {
                        mir_totals::record_alloc_rejected();
                        // `Verify` mode's contract is that it changes no
                        // emitted byte, so it must not change which methods
                        // compile either: record the rejection, report it with
                        // `CRATONVM_DBG=ir-isel`, and leave the per-opcode arms
                        // to emit exactly what they always did. `Emit` mode has
                        // no such licence — its bytes ARE the allocation's, so
                        // an allocation nothing proved is refused outright.
                        if mode == MirMode::Emit {
                            return refuse(bailout);
                        }
                    }
                }
                lowerer.set_mir(plan, mode)
            }
            None => {
                return refuse(Bailout::new(BailoutReason::Internal(
                    "ir_lower: instruction selection did not cover a block",
                )))
            }
        }
    }

    // Round 16 wave 11 (lane frames2, `CRATONVM_JIT_IR_DEOPT_IMAGE_SIZED`,
    // default OFF): the deopt register image sized to the registers the plan
    // above hands out. After the residency plan (it decides what a frame
    // state can name) and before the first byte of the prologue (which
    // carves the frame).
    // Round 16 wave 17 (lane frames2, PC-1, `CRATONVM_JIT_IR_SAVE_BANDS_SIZED`,
    // default OFF): the callee-saved save bands sized to what the plan saves.
    // First, because the image is placed below the bands.
    lowerer.size_save_bands(ir_save_bands_sized_enabled());
    lowerer.size_deopt_image(ir_deopt_image_sized_enabled());
    // Round 16 wave 12 (lane polyclear, FR2P-1,
    // `CRATONVM_JIT_IR_DEOPT_IMAGE_EXITLESS`, default OFF): and no image at
    // all when no exit of this body can read one.
    *image_dropped =
        lowerer.drop_unread_deopt_image(!keep_deopt_image && ir_deopt_image_exitless_enabled());
    // Round 17 (CG16P-4): constant homes, on the same fallback.
    *image_dropped |= lowerer.drop_const_homes(!keep_deopt_image && ir_const_home_drop_enabled());

    // The patchable entry pad, as the single-pass driver emits it (interpreter
    // round i1 wave 22, lane L6; `jit/src/not_entrant.rs`): a redefinition
    // makes this body not entrant with one atomic store over it.
    if lowerer.buf.pos() == 0 {
        lowerer.buf.emit(&crate::ENTRY_PATCH_PAD);
    }
    // Round 12 wave 8 (lane callcost): which self-call samples are dominated,
    // and the entry fast return (after the pad, before the prologue). See
    // `r12w8-callcost-fib-call-anatomy-FIXED-20261001.md`.
    lowerer.plan_self_call_sample_elision();
    lowerer.emit_entry_fast_return();
    lowerer.emit_prologue();
    lowerer.emit_safepoint_poll(None, None);

    // Emit blocks in order
    lowerer.prepare_fusion_tables();
    // Round nio21 wave 3 (lane L2): which call-site exception edges the pads
    // can enter (`ir::Op::CallThrew`; nothing unless the graph has one).
    lowerer.plan_call_throw_edges();
    // Interpreter round i1 wave 49, lane L3: the inline-frame-row census
    // (`CRATONVM_DBG_INLINE_ROW_CENSUS=1`; nothing without it).
    lowerer.begin_inline_row_census();
    for block_idx in 0..schedule.blocks.len() {
        lowerer.lower_block(block_idx);
    }
    // JIT round 19 wave 5 (lane osr5, OSR2-3): nothing without silent stores.
    lowerer.check_promoted_pending_coverage();
    lowerer.close_inline_row_census();
    // JIT round 19 wave 5 (lane handler5, SPLICE4-1): the compiled handler
    // probes, first after the body (every arm block's offset is known) and
    // before every reader of `call_exc_patches` and the rethrow pads.
    lowerer.emit_catch_probes();
    // Round 13 wave 8 (lane callcost3, CC2-1): the direct self-calls' cold
    // halves, first after the body and before every reader of
    // `call_exc_patches` below (the OSR facts, `emit_call_exc_stub`).
    lowerer.emit_deferred_self_call_tails();
    // zs s9/ca4: the split inline ZGC allocations' cold halves, for the same
    // reason and in the same place (each pushes its exit row).
    lowerer.emit_deferred_zgc_alloc_tails();
    // Round nio21 wave 3 (lane L2): the call-site exception pads, also before
    // every reader of `call_exc_patches` and before `emit_rethrow_pads`: a
    // pad's fallback adds a row to one of the two.
    lowerer.emit_call_throw_pads();
    if crate::x64::dbg_jitc_enabled() && !lowerer.call_throw_plans.is_empty() {
        eprintln!(
            "[cratonvm-jitc] ir-call-throw sites_armed={} pads={} (of {} site(s) in the graph)",
            lowerer.call_throw_plans.len(),
            lowerer.call_throw_pads_emitted,
            graph.call_throw_sites.len(),
        );
    }
    // Round nio21 wave 5 (lane L2): the implicit sites' census.
    if crate::x64::dbg_jitc_enabled() && !lowerer.implicit_throw_plans.is_empty() {
        eprintln!(
            "[cratonvm-jitc] ir-implicit-throw sites_armed={} pads={}",
            lowerer.implicit_throw_plans.len(),
            lowerer.implicit_throw_pads_emitted,
        );
    }
    // Round 14 wave 3 (lane calls, CC3-1): the cold-tail census.
    if crate::x64::dbg_jitc_enabled()
        && (lowerer.cross_call_cold_tails != (0, 0) || lowerer.ic_hit_exit_census != (0, 0))
    {
        eprintln!(
            "[cratonvm-jitc] ir-call-cold-tails cross_deferred={} cross_inline={} \
             ic_hit_exits={} ic_admissible={}",
            lowerer.cross_call_cold_tails.0,
            lowerer.cross_call_cold_tails.1,
            lowerer.ic_hit_exit_census.0,
            lowerer.ic_hit_exit_census.1,
        );
    }
    // Round 9 wave 6: `ls_edge_copy_site_exists` PREDICTED that every edge
    // carrying split-residency resolution copies reaches `emit_phi_copies`.
    // An edge whose copies never ran would leave its target reading a
    // register that holds something else, so a wrong prediction refuses the
    // method here rather than emitting it.
    if let Some(i) = lowerer.ls_edge_copies_done.iter().position(|done| !*done) {
        let (p, s) = lowerer
            .ls_edge_copies
            .get(i)
            .map_or((usize::MAX, usize::MAX), |e| (e.pred, e.succ));
        lowerer.latch_bailout(Bailout::with_context(
            BailoutReason::Internal("ir_lower: a split-residency edge copy was never emitted"),
            format!("block {p} -> {s}"),
        ));
    }

    // Soundness bail (ES SortingDigestTests -Jit on): some emitted use asked
    // for the frame slot of a node that was never allocated one (scheduler
    // gap — the node sits in no emitted block), or a slot allocation ran past
    // the frame's spill cap. Discard the artifact and let the caller fall back
    // to the single-pass backend.
    //
    // Both are now UNREACHABLE — `verify_data_locations` and the frame-size
    // check above refuse those graphs before emission begins — so this is a
    // net, not a mechanism. It is kept, and upgraded from one sticky bit to a
    // structured reason, so that if a future lowering finds a path the
    // pre-checks miss, the compile still fails closed *and* says why.
    // The byte-equality oracle's verdict, for the whole method.
    //
    // Reported before it is acted on, because a mismatch that only ever shows
    // up as "this method did not compile" is a mismatch nobody can diagnose.
    if lowerer.mir_mode != MirMode::Off {
        // Only the disagreements, and only under the debug switch: a corpus run
        // compiles thousands of methods, and a per-compile line for each would
        // bury the one line that matters. The totals are printed once at exit
        // (`vm-cli::maybe_dump_shutdown_reports`).
        if lowerer.mir_mismatches != 0 && isel_shadow_reporting() {
            eprintln!(
                "[ir-isel] mir mode={:?} tiles={} MISMATCHES={}",
                lowerer.mir_mode, lowerer.mir_tiles, lowerer.mir_mismatches
            );
        }
        mir_totals::record(
            lowerer.mir_tiles,
            lowerer.mir_mismatches,
            lowerer.mir_shadow_tiles,
            lowerer.mir_arm_bytes,
            lowerer.mir_enc_bytes,
        );
        if lowerer.mir_mismatches != 0 {
            return refuse(Bailout::new(BailoutReason::Internal(
                "ir_lower: the level-2 encoder disagreed with the per-opcode lowering",
            )));
        }
    }

    // Interpreter round i2 wave 64 (lane L2): the token-read guard's
    // per-compile census, beside the token-trim census line. `refusals=0`
    // over a run is the measured form of "no arm reads through a token slot".
    if lowerer.token_read_guard && crate::regalloc::ls_token_trim_census_enabled() {
        // JIT round 19 wave 10 (lane tok10, i64-L2): `scope=` splits the
        // three counts per lowering scope as `name:nodes/refusals/pinned-hits`.
        // JIT round 19 proposal wave 11 (lane lv11, TOK10-3): `point_stale=`
        // only under the point-range switch, so the default line is unchanged.
        let point_stale = if lowerer.token_guard_point_range {
            format!(" point_stale={}", lowerer.token_point_stale.get())
        } else {
            String::new()
        };
        eprintln!(
            "[ir-ls] token-read guard: nodes={} refusals={} pinned-hits={} scope={}{point_stale}",
            lowerer.token_read_nodes,
            lowerer.token_read_refusals.get(),
            lowerer.token_read_pinned_hits.get(),
            lowerer.token_scope_census(),
        );
    }
    if let Some(bailout) = lowerer.take_latched_bailout() {
        describe_unallocated_value(graph, &bailout);
        return refuse(bailout);
    }
    if lowerer.unallocated_slot_use.get() {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: unallocated slot latched without a reason",
        )));
    }

    // Soundness bail: every emitted shadow PUSH must have exactly one emitted
    // RELOAD. The push advances the thread's shadow `top`; only the reload
    // retracts it. An unmatched push leaks a few slots per execution of that
    // site, so a recursive method walks `top` off the end of the shadow stack
    // and the next push writes into whatever follows the mapping. That
    // presents as heap corruption in an unrelated allocator, arbitrarily far
    // from the JIT — the self-recursive call route did it, and it took a
    // gdb backtrace showing ASCII bytes in a mimalloc free-list header to
    // attribute. A static count is enough (both are emitted per site, not per
    // path), and refusing the body is strictly better than shipping it.
    if lowerer.shadow_pushes != lowerer.shadow_reloads {
        if crate::ir_stage_reporting() {
            eprintln!(
                "[ir] lower_inner refused: {} shadow pushes vs {} reloads — \
                 an unmatched push leaks the thread's shadow top",
                lowerer.shadow_pushes, lowerer.shadow_reloads
            );
        }
        note_lower_bail("shadow-push-reload-imbalance");
        return refuse(Bailout::new(BailoutReason::Internal(
            "shadow-push-reload-imbalance",
        )));
    }

    // real-frame-deopt (step 3): emit the shared deopt stub after the method
    // body so failed guards can jump to it, then patch in-method branches.
    // Captured BEFORE the stubs are emitted: `emit_deopt_stub` takes its patch
    // list, so afterwards the question cannot be asked.
    // The guards' out-of-line deopt pads, first: each ends in a `JMP` to the
    // deopt stub, recorded in `deopt_stub_patches`, which the line below reads.
    lowerer.emit_deopt_pads();
    // Round 11 wave 10 (lane irexc): no GUARD exit, read before the rethrow
    // pads add their own `deopt_stub_patches` rows. A pad is an exceptional
    // exit, not a guard; tier proposal 27's OSR fact below tells them apart.
    let guard_exit_free = lowerer.deopt_stub_patches.is_empty();
    // The reason-9 rethrow pads, before `osr_sentinel_free` is read: a pad's
    // `JMP` makes the body not sentinel-free, which keeps that bit meaning "no
    // exit at all" for every reader that relies on it.
    lowerer.emit_rethrow_pads();
    // Round 15 wave 1 (lane sync, SS8-2): a self-locking body's own monitor
    // edges are exits too (`self_lock_unheld_exc_patches`).
    let osr_sentinel_free = lowerer.deopt_stub_patches.is_empty()
        && lowerer.call_exc_patches.is_empty()
        && lowerer.self_lock_unheld_exc_patches.is_empty();
    // Tier proposal 27 (round 11 wave 10, lane irexc): the body's exits when
    // none of them is a guard — see `CompiledMethod::ir_osr_exception_exit_bcis`.
    // Taken here, before `emit_call_exc_stub` consumes `call_exc_patches`.
    let osr_exception_exit_bcis: Option<Box<[u32]>> =
        if guard_exit_free && !lowerer.propagating_exit_holds_monitor {
            lowerer
                .call_exc_patches
                .iter()
                .map(|&(_, bci)| u32::try_from(bci).ok())
                .collect::<Option<Vec<u32>>>()
                .map(|mut bcis| {
                    bcis.sort_unstable();
                    bcis.dedup();
                    bcis.into_boxed_slice()
                })
        } else {
            None
        };
    // Tier proposal 27 phase 3 (round 11 wave 12, lane irexc): the same list
    // plus the guard exits, when every guard is exact or value-equivalent and
    // resumable in place — see `CompiledMethod::ir_osr_guard_exit_bcis`. Every
    // guard box was pushed while the body was lowered, so the list is whole.
    //
    // Round 11 wave 14 (lane osrmerge): under `CRATONVM_JIT_OSR_OPAQUE_ENTRY`,
    // when the strict fact is refused, also the fact WITHOUT the
    // classification count (`osr_exit::guard_exit_fact_opaque`) — published
    // below only if every entry `emit_osr_entry_stubs` emits is opaque. `None`
    // with the switch off, so nothing below changes.
    let (mut osr_guard_exit_bcis, mut osr_guard_exit_bcis_opaque): (
        Option<Box<[u32]>>,
        Option<Box<[u32]>>,
    ) = {
        let call_exc_bcis: Vec<usize> = lowerer
            .call_exc_patches
            .iter()
            .map(|&(_, bci)| bci)
            .collect();
        let strict = crate::osr_exit::guard_exit_fact(
            &lowerer.deopt_boxes,
            lowerer.classified_guard_exits,
            &call_exc_bcis,
            lowerer.propagating_exit_holds_monitor,
        );
        let opaque = if strict.is_none()
            && (crate::osr_exit::osr_opaque_entry_enabled()
                || poll_mode_exits == IrPollModeExits::OsrDoor
                || graph.unloaded_static_call_traps)
        {
            crate::osr_exit::guard_exit_fact_opaque(
                &lowerer.deopt_boxes,
                &call_exc_bcis,
                lowerer.propagating_exit_holds_monitor,
            )
        } else {
            None
        };
        (strict, opaque)
    };
    // JIT round 18 wave 11 (lane osrfollow, OSRPOLY18-2): the strict fact was
    // refused (a SPECULATIVE guard: its interpreter continuation may falsify a
    // header fact) and the relaxed one admits every exit. Such a body's guard
    // exits are sound only when EVERY entry the door can take is an opaque
    // merge, which is what commit 44df838b5f gave every OSR-door build. Taken
    // here, before the entry block below may publish (and so `take`) the
    // relaxed fact. `CompiledMethod::ir_osr_guard_fact_needs_opaque_entries`.
    let osr_guard_fact_wants_opaque =
        osr_guard_exit_bcis.is_none() && osr_guard_exit_bcis_opaque.is_some();
    // The two counts `osr_sentinel_free` is computed FROM, kept for the
    // diagnostic below: `emit_deopt_stub` / `emit_call_exc_stub` take both
    // vectors a few lines down, so after them the question cannot be asked.
    let osr_nonfree_dbg = (
        lowerer.deopt_stub_patches.len(),
        lowerer.call_exc_patches.len(),
    );
    // Round 12 wave 8 (lane callcost): the entry fast return's `MOV RAX; RET`,
    // the first thing after the body.
    lowerer.emit_entry_fast_return_stub();
    // Round 16 (lane codegen, CG16-2): the integer divisions' out-of-line
    // fixups. RAX-only code reached by a forward `JE` from the body and
    // returning by `JMP`; no exit, so no fact above or below reads it.
    lowerer.emit_div_cold_fixups();
    // The outlined safepoint slow paths, before the other tail stubs: each is
    // reached by a forward `JNZ` from the body and returns with a `JMP`, so it
    // only needs to be after the body, and putting it first keeps both hops
    // short.
    lowerer.emit_outlined_polls();
    // The back-edge polls' mode-exit pads (interpreter round i1 wave 15, lane
    // L2), after the outlined polls (which request them too) and after every
    // OSR fact above was read: such an exit resumes at a state the graph
    // itself reaches and is admitted by the point it carries, not by those
    // facts, so it must not change them. Before `emit_deopt_stub`, which takes
    // the `deopt_stub_patches` rows these add.
    lowerer.emit_poll_exit_pads();
    // Interpreter round i1 wave 28, lane L6: the post-call exit sites' stubs,
    // for the same reason and in the same place (after every OSR fact, before
    // `emit_deopt_stub`, which takes the `deopt_stub_patches` rows they add).
    lowerer.emit_post_call_exit_stubs();
    // The `Op::Switch` jump tables. Data, not code — see `SwitchTablePlan` for
    // why they cannot sit inline behind their own indirect `JMP`. Before
    // `patch_branches`, which resolves the entries this reserves.
    lowerer.emit_switch_tables();
    lowerer.emit_deopt_stub();
    // Gap B: emit the shared call-exception bail stub after the body so each
    // dispatch site's sentinel `JE` reaches it.
    lowerer.emit_call_exc_stub();
    // The optimizing tier's own OSR entry points. After the body, because each
    // stub ends in a `JMP` to a native offset the body has already produced;
    // before `patch_branches`, because a stub's own `JMP` is patched here and
    // must not be mistaken for an in-body branch.
    //
    // The liveness model is the one `plan_register_residency_with` built when
    // residency ran (it only changed `pinned`, which the stubs never read), and
    // a fresh `build_live_model` otherwise. It is a pure function of the graph
    // and the schedule either way, so the OSR decision does not depend on
    // whether residency ran; only the second build is saved
    // (`r11w4-ircore-live-model-built-twice-per-osr-compile`).
    //
    // ── Not emitted into a body no door can enter (2026-09-16) ────────
    //
    // The ONLY consumer is `vm::runtime::interpreter::jit_bridge::try_osr`,
    // and its admission is `ir_osr_entry_addr(pc).is_some() &&
    // ir_osr_sentinel_free` — BOTH. So a body that is not sentinel-free is one
    // the door will refuse whatever entries it carries, and every stub emitted
    // into it is dead weight: the bytes, the `JMP` patch, the published
    // `(bci, offset, needed)` triple, and this `build_live_model` pass.
    //
    // `ir_osr_sentinel_free` means the body emits no deopt stub AND no
    // call-exception stub, so — as `OSR_OPTIMIZING_REFUSED`'s doc in
    // `jit_bridge.rs` states outright — **any method containing a call fails
    // it**. That is most methods, which makes this the common case rather than
    // a corner. The test is free: `osr_sentinel_free` is computed twenty lines
    // above, deliberately before the stubs that would destroy the evidence.
    //
    // `CRATONVM_JIT_IR_OSR_ENTRY_ALWAYS=1` restores unconditional emission, so
    // one binary can A/B the skip and so a test can exercise a stub in a body
    // that would otherwise carry none.
    //
    // Tier proposal 27 (round 11 wave 10, lane irexc): a body whose only exits
    // are exceptional (`osr_exception_exit_bcis`) is one the door CAN enter
    // under `CRATONVM_JIT_OSR_OPTIMIZING_EXC_EXITS=1`, so it gets its stubs
    // under that switch. Off, the stubs are exactly what they were.
    //
    // Phase 3 (round 11 wave 12, lane irexc): a body whose guard exits the
    // door can resume without a plan (`osr_guard_exit_bcis`) gets them under
    // `CRATONVM_JIT_OSR_OPTIMIZING_GUARD_EXITS=1`.
    //
    // Round 15 wave 1 (lane sync, SS8-2): never into a self-locking body. An
    // OSR entry runs it inside the interpreter frame that already holds the
    // method monitor, and its exits would release a hold it never took.
    let osr_entries_wanted = lowerer.self_lock.is_none()
        && ir_osr_entry_enabled()
        && (osr_sentinel_free
            || ir_osr_entry_always_enabled()
            || (osr_exception_exit_bcis.is_some() && ir_osr_exception_exit_entries_enabled())
            || ((osr_guard_exit_bcis.is_some() || osr_guard_exit_bcis_opaque.is_some())
                && ir_osr_guard_exit_entries_enabled()));
    if ir_osr_entry_enabled() && !osr_entries_wanted {
        note_osr_entry_skipped_not_sentinel_free();
        // WHICH stub cost the body its OSR entries, and where it came from.
        //
        // Round 9 wave 12. The counter above says how OFTEN this happens; it
        // has never said WHY, and "why is this loop not sentinel-free" is the
        // question `perf-long-counted-loops-lose-the-optimizing-osr-body`
        // re-asked in five consecutive waves, each time by rebuilding the
        // binary with a print in it. Two numbers and the guards' own
        // `(bci, reason)` list answer it from a released binary: a non-zero
        // `call_exc_patches` is a CALL, a non-zero `deopt_stub_patches` is a
        // guard and the list names it.
        if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
            let pts: Vec<String> = lowerer
                .deopt_boxes
                .iter()
                .map(|p| format!("{}@{:?}", p.bci, p.reason))
                .collect();
            eprintln!(
                "[ir-ls] osr entries SKIPPED (not sentinel-free): \
                 deopt_stub_patches={} call_exc_patches={} points={:?}",
                osr_nonfree_dbg.0, osr_nonfree_dbg.1, pts,
            );
        }
    }
    if osr_entries_wanted {
        let osr_live = match (residency_live.take(), one_liveness_pass.take()) {
            (Some(live), _) => live,
            // Wave 66 (lane L2): residency did not run, so the compile's one
            // liveness answer is still unused.
            (None, Some(pass)) => {
                let mut live = pass.into_live_model(graph, schedule);
                // OSR7-1 (lane osr8): as the residency model's.
                widen_live_model_for_pending(&mut live, &pending_live);
                live
            }
            (None, None) => {
                let mut live = crate::regalloc::build_live_model(graph, schedule);
                widen_live_model_for_pending(&mut live, &pending_live);
                live
            }
        };
        let non_opaque_entries = lowerer.emit_osr_entry_stubs(&osr_live);
        // Round 11 wave 14 (lane osrmerge): the relaxed fact holds only for a
        // body the door can enter nowhere but through an opaque merge.
        if non_opaque_entries == 0 && osr_guard_exit_bcis.is_none() {
            osr_guard_exit_bcis = osr_guard_exit_bcis_opaque.take();
        }
    }
    // JIT round 18 wave 11 (lane osrfollow, OSRPOLY18-2): see
    // `osr_guard_fact_wants_opaque` above. Read nowhere but the narrowed OSR
    // door (`ir_tier`); asking it changes no byte of this body.
    let osr_guard_fact_needs_opaque_entries = osr_entries_wanted && osr_guard_fact_wants_opaque;
    drop(residency_live);

    let lowerer_osr_entries = std::mem::take(&mut lowerer.osr_entries);
    // Round 12 wave 8 (lane callcost): an elided self-call sample relies on a
    // dominating site's sample having run in the same activation. An OSR entry
    // enters past it, and a planned site that never reached the self-call
    // route emitted no sample of its own. Planned only for loop-free bodies,
    // which get no OSR entry, and every kind-4 node takes that route; refuse
    // rather than trust either if it ever fails.
    if lowerer.self_call_samples_elided > 0
        && (!lowerer_osr_entries.is_empty()
            || lowerer.self_call_sites_lowered != lowerer.self_call_sites_planned)
    {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a dominated self-call sample was elided without its dominator",
        )));
    }
    let lowerer_osr_entry_kinds = std::mem::take(&mut lowerer.osr_entry_kinds);
    let lowerer_osr_opaque_entry_bcis = {
        let mut opaque = std::mem::take(&mut lowerer.osr_opaque_entry_bcis);
        opaque.sort_unstable();
        opaque.dedup();
        opaque.into_boxed_slice()
    };
    if osr_entries_wanted {
        // OD16-4 (round 16, lane osrdoor). Cast: a count of entries fits u64.
        note_osr_entry_census_n(OSR_ENTRY_CENSUS_EMITTED, lowerer_osr_entries.len() as u64);
    }
    if osr_entries_wanted && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
        eprintln!(
            "[ir-ls] osr entries: emitted={} refused={:?}",
            lowerer_osr_entries.len(),
            lowerer.osr_refusals,
        );
    }
    // Fail closed: a guard emitted by a tail stub after `emit_deopt_pads` ran
    // would leave its `Jcc` pointing at the next instruction — a deopt that
    // silently never happens. No tail emitter guards today; this keeps it so.
    if !lowerer.deopt_pads.is_empty() {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a deopt pad was requested after the pads were emitted",
        )));
    }
    // The same net for the reason-9 rethrow pads (round 11 wave 10): a pad
    // requested by a tail stub would leave its exceptional branch unpatched.
    if !lowerer.rethrow_pads.is_empty() {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a rethrow pad was requested after the pads were emitted",
        )));
    }
    // And for the poll mode exits (wave 15): no poll is emitted after them.
    if !lowerer.poll_exit_pads.is_empty() {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a poll exit pad was requested after the pads were emitted",
        )));
    }
    // Round 15 wave 1 (lane chain): the frame block's shared publication
    // subroutine, after every tail emitter that can lower a safepoint (each
    // `CALL` to it so far is patched here; a later one would call backwards).
    lowerer.emit_frame_block_publish_stub();
    lowerer.finish_lazy_thread_fetch();
    lowerer.patch_branches();
    // fib44-fix follow-up: patch direct self-recursive calls to the method entry.
    lowerer.patch_self_calls();
    // Every branch of the body is in place: the reloads no branch reaches.
    lowerer.apply_home_reload_forwards();

    // real-frame-deopt (step 2): resolve recorded safepoint snapshots into
    // native-offset-keyed DeoptimizationPoints before the buffer is consumed.
    // Emit-and-discard: nothing reads these yet, so codegen is unchanged.
    let mut deopt_points = lowerer.build_deopt_points(osr_sentinel_free);
    // The reason-9 points the rethrow pads publish, by value beside the by-bci
    // resume points — the single-pass layout, where the OSR exception transfer
    // finds them (`osr_exit::exceptional_reason_at_bci`) and the by-bci resume
    // lookups skip them (`deopt_reason_at_bci`). Each is anchored at its
    // site's exceptional branch, which no by-bci point shares (that is never
    // an instruction start); re-sorted so the verifier's order check holds.
    // Empty off the precise-frame route (round 11 wave 10, lane irexc).
    if !lowerer.rethrow_points.is_empty() {
        deopt_points.append(&mut lowerer.rethrow_points);
        deopt_points.sort_by_key(|p| p.native_offset);
    }
    // The SECOND read of the latch (round 9 wave 2). Everything after the first
    // read — the deopt pads, outlined polls, tail stubs, OSR entry stubs and,
    // above all, `build_deopt_points` — can latch too, and nothing read it
    // again, so a by-bci point whose dropped home no register describes became
    // a silent `Unsupported` (unresumable at run time) instead of a refused
    // compile. `build_deopt_points` quiets the one latch that is routine and
    // harmless (points at bcis nothing transfers from), so what reaches here
    // is a real disagreement.
    if let Some(bailout) = lowerer.take_latched_bailout() {
        describe_unallocated_value(graph, &bailout);
        return refuse(bailout);
    }
    // The unroller's net. It relaxed its safepoint refusal on the strength of
    // the GRAPH being trap-free; that is only sound while the points it
    // orphaned are never built. If they were built, the killed body nodes now
    // resolve to `FrameValue::Undefined` and a deopt would silently lose
    // interpreter locals -- so refuse the compile and let the single-pass
    // backend take the method, which is what happened before the relaxation.
    //
    // Read ONCE, at the TOP of `lower_inner_with_array_list`
    // (`unroll_used_unreachable_frames`, passed to every attempt): `take_`
    // clears it, and taking it here — after a dozen earlier refusals that
    // `return` first — left a refused compile's flag set on the thread for the
    // NEXT compile to inherit (round 9).
    if unroll_used_unreachable_frames && !deopt_points.is_empty() {
        return refuse(Bailout::with_context(
            BailoutReason::UnsupportedShape(
                "ir_lower: the unroller relied on unreachable frame states and points were built",
            ),
            format!(
                "{} deopt point(s) built for a graph the unroller treated as trap-free",
                deopt_points.len()
            ),
        ));
    }
    // Round nio20 wave 5 (lane L3): the pure-body unroll's net. It left the
    // frames at these bcis naming killed body nodes on the prediction that
    // nothing in the kept graph transfers at them
    // (`ir_optimize::pure_body_frames_unconsultable`); the emission's record of
    // where it CAN transfer is the check of that prediction. A disagreement
    // refuses the compile rather than publish a resume with `Undefined` locals.
    // JIT r20 wave 19 (LOOPOPT20-6, `CRATONVM_JIT_IR_UNROLL_NAMED_FRAME_PCS`):
    // only a transfer that reads the stranded FLAT frame counts; one through
    // its node's own named frame (a loop-entry predicate at the header bci)
    // never reads it. `=0`: every transfer, as before.
    let named_frame_pcs = crate::ir_optimize::unroll_named_frame_pcs_enabled();
    if let Some(&bci) = unroll_stranded_bcis.iter().find(|&b| {
        if named_frame_pcs {
            lowerer.by_bci_transfer_bcis.contains(b)
        } else {
            lowerer.transfer_bcis.contains(b)
        }
    }) {
        return refuse(Bailout::with_context(
            BailoutReason::UnsupportedShape(
                "ir_lower: a pure-body unroll stranded a frame the emission transfers at",
            ),
            format!("bci {bci} is a transfer bci but its frame names an unrolled body node"),
        ));
    }
    let mut deopt_boxes = std::mem::take(&mut lowerer.deopt_boxes);
    // JIT round 19 wave 5 (lane handler5, SPLICE4-1): the probes' sites, owned
    // by the artifact like the single-pass tier's local-handler sites.
    let catch_site_boxes = std::mem::take(&mut lowerer.catch_site_boxes);
    let trap_cause_points = std::mem::take(&mut lowerer.trap_cause_points);
    // Round 13 wave 11 (lane chain5, CH-1): baked like the boxes, owned like them.
    let forced_chain_deopt_counters = std::mem::take(&mut lowerer.forced_chain_deopt_counters);
    // Round 15 wave 4 (lane chain4): and the point each cell belongs to.
    let forced_chain_deopt_points = std::mem::take(&mut lowerer.forced_chain_deopt_points);
    // Read for the monitor-block vouch at the end (wave 19, lane L2).
    let poll_exits_emitted = !lowerer.poll_exit_boxes.is_empty();
    // nio21 wave 4 L3: which exits this body carries, per compile, so a host
    // A/B of `CRATONVM_JIT_IR_BACK_EDGE_VIRTUAL_OBJECT_EXITS` /
    // `CRATONVM_JIT_IR_EXITS_BESIDE_DROPPED_SNAPSHOT_VALUES` can name the
    // methods an arm changes (`r21-buffer-relative-le-be-rows-...` page). The
    // exits' code is in the polls' outlined slow blocks and the 5-byte
    // post-call `NOP`s, so an arm changes a body's fast path only through
    // those `NOP`s; the line says how many there are.
    if poll_exits_emitted && crate::x64::dbg_jitc_enabled() {
        eprintln!(
            "[cratonvm-jitc] ir-exit-cost-census method={} mode={:?} poll_exits={} \
             naming_virtuals={} spliced_header={} post_call_sites={} beside_dropped_values={}",
            graph.scope_method_key,
            lowerer.poll_mode_exits,
            lowerer.mode_exit_census[0],
            lowerer.poll_exits_naming_virtuals,
            lowerer.spliced_header_poll_exits,
            lowerer.post_call_exit_sites.len(),
            lowerer.optimizer_dropped_snapshot_values,
        );
    }
    // Interpreter round i2 wave 53, lane L2: every box a named-only poll exit
    // (no guard or rethrow pad among the boxes so far, and the mode puts no
    // post-call exit), which the VM's caller-held binding reads.
    let named_poll_exits_only = poll_exits_emitted
        && deopt_boxes.is_empty()
        && lowerer.post_call_exit_sites.is_empty()
        && lowerer.poll_mode_exits == IrPollModeExits::MethodEntryNamedOnly;
    // Interpreter round i2 wave 57, lane L2: a poll exit leaves through a
    // caller chain, which the VM's verdict checks before telling it to leave.
    let chain_poll_exits = lowerer.spliced_header_poll_exits > 0;
    // The poll mode exits' points (wave 15), kept out of the guard facts above
    // and owned by the artifact from here like every other box.
    deopt_boxes.append(&mut lowerer.poll_exit_boxes);
    // Round 15 wave 1 (lane sync, SS8-2): a self-locking body is published
    // only with every exit closed (`Lowerer::self_lock_refusal`); anything
    // else falls back to the single-pass tier, which never leaks the hold.
    if let Some((cause, why)) = lowerer.self_lock_refusal(&deopt_boxes, &deopt_points) {
        if crate::x64::dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] ir self-lock REFUSED ({}): {why}",
                cause.name()
            );
        }
        // Round 15 wave 3 (lane sync2, S15-2's first half): on the
        // synchronized-splice census line, beside the builds.
        crate::ir::note_sync_splice_census(crate::ir::SYNC_CENSUS_IR_SELF_LOCK_REFUSED);
        // Round 15 wave 4 (lane sync3, SY2-6): and by cause.
        crate::ir::note_sync_splice_census(cause.census_row());
        note_lower_bail("ir-self-lock-exits-not-closed");
        return refuse(Bailout::with_context(
            BailoutReason::UnsupportedShape("ir self-locking body: an exit is not closed"),
            why,
        ));
    }
    let self_locks_monitor = lowerer.self_lock.is_some();
    if self_locks_monitor {
        crate::ir::note_sync_splice_census(crate::ir::SYNC_CENSUS_IR_SELF_LOCK_CLOSED);
    }
    // JIT round 19 proposal wave 6, lane sync6 (SYNCDOOR618-5): the hold's
    // kind for the VM's locked-monitor depths; this tier publishes no frame
    // word for it.
    let self_lock_hold = self_locks_monitor.then(|| {
        if lowerer.self_lock_mirror_slot().is_some() {
            crate::SelfLockHold::Static {
                mirror_word_rbp_off: None,
            }
        } else {
            // JIT round 19 proposal wave 8, lane gc8 (GC719-1): the receiver's
            // prologue home `[rbp - 8]`, which every safepoint map republishes
            // (`Lowerer::self_lock_obj_home`; metadata only, the VM reads it
            // only where the active map names it).
            crate::SelfLockHold::Instance {
                obj_rbp_off: lowerer.self_lock_obj_home(),
            }
        }
    });
    // Gap B: a method containing an `Op::Call` takes the VM context pointer as a
    // hidden first arg, so it must be invoked via `try_call_with_context`.
    let needs_context = lowerer.needs_context;

    // Relocation-contract values, read off the lowerer before `buf` moves out.
    let sp_id_slot_off = lowerer.sp_id_slot_off;
    let shadow_thread_slot_off = lowerer.shadow_thread_slot_off;
    let shadow_savebase_slot_off = lowerer.shadow_savebase_slot_off;
    // Whether any safepoint of this body can publish the frame block. Read by
    // the collector's frame walk, which leaves a published block's homes to the
    // shadow-stack remap (`CompiledMethod::shadow_frame_block`).
    let shadow_frame_block = !lowerer.frame_block.is_empty() && lowerer.shadow_pushed_any;
    let oop_maps = std::mem::take(&mut lowerer.oop_maps);
    // gen r5w3/live7: empty unless `CRATONVM_JIT_PRECISE_FRAME_LIVENESS`.
    // GC719-1 (round 19 wave 8, lane gc8): the blocks held per safepoint id.
    let ir_monitor_homes = std::mem::take(&mut lowerer.ir_monitor_homes);
    let frame_liveness = lowerer.take_frame_liveness();
    let sp_id_bcis = std::mem::take(&mut lowerer.sp_id_bcis);
    // The reference-free frame contract (round 11 wave 14, lane fib): the same
    // prediction every row was recorded under, read before the lowerer goes.
    let body_keeps_no_references = lowerer.body_publishes_no_roots();
    // Round 11 wave 15 (lane fib): a direct self-call that deferred its id
    // store relied on the frame being published `frame_holds_no_references`
    // below, the one contract under which no collector reads that slot. The
    // prediction it was made under is `body_keeps_no_references` itself; the
    // map clause is re-checked here because a map naming a slot would clear
    // the flag, and a stale id is then trusted. Cannot fire while
    // `emit_safepoint_map` builds its slots from exactly the two lists that
    // prediction reads; refuse rather than publish if it ever does.
    if lowerer.self_call_id_stores_deferred > 0
        && !(body_keeps_no_references && oop_maps.iter().all(|m| m.frame_slot_offsets.is_empty()))
    {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a self-call deferred its safepoint-id store in a frame that keeps references",
        )));
    }
    // Round 11 wave 16 (lane irback): the same rule for the lean prologue
    // (`Lowerer::lean_ref_free_prologue`), which left the unset locals and the
    // reserved tail unzeroed on the promise that the collector will neither
    // verify nor scan this band. Cannot fire for the reason above.
    if lowerer.lean_ref_free_prologue() && !oop_maps.iter().all(|m| m.frame_slot_offsets.is_empty())
    {
        return refuse(Bailout::new(BailoutReason::Internal(
            "ir_lower: a lean prologue skipped GC zeroing in a frame whose maps name a slot",
        )));
    }
    let return_site_rows = std::mem::take(&mut lowerer.return_site_rows);
    // Wave 25 (lane L6): the polls a redefinition that withdraws this body
    // forces, and the flag they test.
    let exit_poll_sites = std::mem::take(&mut lowerer.exit_poll_sites);
    // Wave 28 (lane L6): and the post-call exit sites it forces with them.
    let post_call_exit_sites = std::mem::take(&mut lowerer.post_call_exit_sites);
    let exit_poll_flag = lowerer.safepoint_flag_addr;
    let inline_frame_rows = std::mem::take(&mut lowerer.inline_frame_rows);
    lowerer.report_inline_row_census(&inline_frame_rows);
    let inline_frame_sp_id_rows = std::mem::take(&mut lowerer.inline_frame_sp_id_rows);
    let npe_trap_sites = std::mem::take(&mut lowerer.npe_trap_sites);
    let locals_size = lowerer.locals_size;
    let first_spill = lowerer.first_spill;
    let spill_cap_off = lowerer.spill_cap_off;
    let saved_xmm_bytes = lowerer.saved_xmm_bytes;
    // gen r5w6/oomjit10: read before `buf` moves out of the lowerer; see
    // `CompiledMethod::ir_saved_gpr_slots`.
    let ir_saved_gpr_slots: Vec<(u8, i32)> = lowerer.saved_gpr_regs().collect();
    let frame_size = lowerer.frame_size;
    // Round 13 wave 3 (lane framestate): how many guards inside spliced bodies
    // publish a caller chain, and how many fell back to the flat frame at the
    // outermost `invoke` (`CRATONVM_JIT_IR_SPLICE_FRAME_STATES`).
    if (lowerer.splice_chain_points > 0
        || lowerer.splice_chain_fallbacks > 0
        || lowerer.sync_window_flat_sites > 0)
        && crate::ir_stage_reporting()
    {
        eprintln!(
            "[ir] splice-frame-states: {} guard(s) publish a caller chain, {} fell back to the \
             outermost invoke's frame, {} inside a synchronized splice window kept it",
            lowerer.splice_chain_points,
            lowerer.splice_chain_fallbacks,
            lowerer.sync_window_flat_sites,
        );
    }
    // Interpreter round i1 wave 47, lane L3: post-call exits after a call
    // inside a splice, whose frame is a caller chain
    // (`CRATONVM_JIT_IR_POST_CALL_SPLICE_EXITS`); the positive control of
    // `L3W47PostCallExitInsideASplice`.
    if (lowerer.post_call_chain_sites > 0 || !lowerer.post_call_splice_state_by_call.is_empty())
        && crate::ir_stage_reporting()
    {
        eprintln!(
            "[ir] post-call-chain-sites: {} of {} spliced call(s) with a post-call chain snapshot",
            lowerer.post_call_chain_sites,
            lowerer.post_call_splice_state_by_call.len(),
        );
    }

    // ── Install-time deopt-metadata verification ─────────────────────
    //
    // The metadata is checked BEFORE the artifact becomes a `CompiledMethod`,
    // because a frame that cannot be reconstructed is only discoverable at
    // runtime otherwise — at a guard, on a VM thread, with the frame already
    // half torn down. Bailing here is always semantically valid (the method
    // takes the single-pass backend or the interpreter); installing code whose
    // deopt map disagrees with its oop map is not.
    //
    // Which lanes are active is decided by which data this backend actually
    // has, so every check that fires is one this file can be held to:
    //
    //   * **scope** — `resolve_frame_state` records `method_key: String::new()`
    //     (the lowerer does not know the method's identity; deopt resume keys on
    //     the running `CompiledMethod`), so the limits are registered under that
    //     same empty key. `code_len`/`max_locals`/`max_stack` are saturated: the
    //     bytecode length and `max_stack` never reach this function, and
    //     `num_locals` is not a bound a hand-built graph's snapshots respect.
    //     What the lane does buy is the `UnknownMethod` check — the day inlined
    //     caller scopes start carrying real method keys, they must arrive with
    //     limits rather than silently skipping every per-scope check.
    //   * **removed-node** — every `Op::Dead` id, cross-checked against the
    //     scalar-replacement map's keys as the ones a `VirtualObject` recipe is
    //     allowed to name. This is the lane that catches a recipe built from a
    //     stale graph.
    //   * **oop-map agreement** — one `OopCoverage` per emitted `OopMapEntry`,
    //     keyed by native offset. `emit_safepoint_map` currently pushes entries
    //     with `native_pc_offset: 0` (the relocation path matches them by the
    //     safepoint id in the frame slot, not by pc), and registering every map
    //     under key `0` would compare deopt points against an arbitrary map, so
    //     only anchored entries are registered. The lane therefore arms itself
    //     the moment this backend starts anchoring its maps to native offsets.
    //   * **structural** — always on.
    let mut verifier = DeoptVerifier::new()
        .with_method(MethodFrameLimits::new(
            String::new(),
            u32::MAX,
            u16::MAX,
            u16::MAX,
        ))
        .with_removed_nodes(
            graph
                .nodes
                .iter()
                .enumerate()
                .filter(|(_, n)| matches!(n.op, Op::Dead))
                .map(|(id, _)| id as u32),
        );
    if let Some(sr) = sr_map {
        verifier = verifier.with_materializable_nodes(sr.objects.keys().copied());
    }
    // Round 13 wave 3 (lane framestate): a guard in a spliced body may carry a
    // caller chain whose scopes name REAL method keys -- the spliced callees and,
    // outermost, the compiling method (`Graph::scope_method_key`). Each arrives
    // with its limits, so the scope lane checks every level rather than
    // reporting `UnknownMethod`. A callee's `code_len` / `max_locals` come from
    // its splice site; the compiling method's are saturated like the empty
    // key's above (a self-recursive copy registers the same key again with
    // its real limits, which then hold for both).
    if !graph.scope_method_key.is_empty() && graph.safepoints.iter().any(|s| s.is_splice_state()) {
        verifier = verifier.with_method(MethodFrameLimits::new(
            graph.scope_method_key.clone(),
            u32::MAX,
            u16::MAX,
            u16::MAX,
        ));
        let mut registered: std::collections::HashSet<&str> = std::collections::HashSet::new();
        for chain in graph
            .safepoints
            .iter()
            .filter_map(|s| s.splice_scope.as_deref())
        {
            for scope in &chain.scopes {
                if scope.method_key.is_empty() || !registered.insert(scope.method_key.as_str()) {
                    continue;
                }
                let code_len = if scope.code_len == 0 {
                    u32::MAX
                } else {
                    scope.code_len
                };
                let max_locals = u16::try_from(scope.max_locals)
                    .ok()
                    .filter(|&m| m != 0)
                    .unwrap_or(u16::MAX);
                verifier = verifier.with_method(MethodFrameLimits::new(
                    scope.method_key.clone(),
                    code_len,
                    max_locals,
                    u16::MAX,
                ));
            }
        }
    }
    for entry in &oop_maps {
        if entry.native_pc_offset != 0 {
            verifier = verifier.with_oop_map(
                entry.native_pc_offset,
                OopCoverage {
                    frame_slot_offsets: entry.frame_slot_offsets.clone(),
                    // The IR lowerer keeps every live value in a frame slot; it
                    // never publishes a reference in a GPR.
                    registers: Vec::new(),
                    moving_young_coverage_complete: entry.moving_young_coverage_complete,
                },
            );
        }
    }
    // Both sets are checked. `deopt_points` is the sorted, native-offset-keyed
    // list the verifier's structural lane checks the order of; `deopt_boxes` are the boxes baked
    // into the emitted guards, and those are the frame states a *live* deopt
    // actually reconstructs from. Each box is verified on its own — they are not
    // one sorted sequence, so checking them as a slice would report a bogus
    // ordering violation.
    for point in &deopt_boxes {
        if let Err(bailout) = verifier.verify(std::slice::from_ref(&**point)) {
            return refuse(bailout);
        }
    }
    if let Err(bailout) = verifier.verify(&deopt_points) {
        return refuse(bailout);
    }

    // The liveness colouring's peak — the number of values simultaneously live
    // at the busiest program point — is exactly what
    // `CompilationReport::peak_live_values` asks for, and this is the only place
    // in the compiler that computes it. Recorded through the thread-local hook
    // rather than a parameter because `lower_inner`'s signature is pinned (see
    // `metrics::note_current_peak_live_values`); a no-op when metrics are off.
    crate::metrics::note_current_peak_live_values(slot_plan.peak_live);

    // `CompilationReport::spills` / `::reloads` are reported ONLY when the
    // linear-scan path actually ran, and they count what this backend EMITTED,
    // not what `regalloc::Allocation` planned — the plan is a full
    // spill/reload/split schedule, and this wiring executes only the subset it
    // can prove (see `plan_register_residency`). Reporting the plan's numbers
    // would describe machine code that was never generated.
    //
    // The colourer-only path leaves both `NotMeasured`, which is the truth: it
    // allocates no registers, so it has no register↔memory transitions to
    // count, and a reported `0` would be indistinguishable from "measured, and
    // it spilled nothing".
    if ls_active {
        crate::metrics::note_current_spills(lowerer.ls_spills);
        crate::metrics::note_current_reloads(lowerer.ls_reloads);
    }

    // ENGAGEMENT, not effect. Both numbers answer "did the wiring fire on this
    // method", which is the question a null timing result cannot answer on its
    // own -- and this session spent three A/B arms on `CratonBench` before
    // noticing that the optimizing tier plans no residency there at all, so
    // both arms had been running identical machine code.
    if ls_active
        && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
        && (lowerer.phi_copy_reg_reads > 0
            || lowerer.phi_copy_reg_publishes > 0
            || lowerer.phi_copy_publish_deferred > 0
            || lowerer.phi_home_publish_skipped > 0
            || lowerer.phi_home_publish_refused > 0)
    {
        // `home_publish_skipped` is the engagement census for the dropped-home
        // publish guard, and `home_publish_refused` the compiles it turned into
        // an interpreter fallback rather than a read of an unwritten word.
        eprintln!(
            "[ir-ls] phi copies: reg_reads={} reg_publishes={} publish_deferred={} home_publish_skipped={} home_publish_refused={}",
            lowerer.phi_copy_reg_reads,
            lowerer.phi_copy_reg_publishes,
            lowerer.phi_copy_publish_deferred,
            lowerer.phi_home_publish_skipped,
            lowerer.phi_home_publish_refused,
        );
    }
    // Round 16 wave 3 (lane codegen, CG16-7): its own line, so the one above
    // keeps its format.
    if lowerer.phi_copy_const_imms > 0
        && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
    {
        eprintln!(
            "[ir-ls] phi copies: const_imms={}",
            lowerer.phi_copy_const_imms
        );
    }
    if ls_active
        && ir_deopt_regs_enabled()
        && cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN")
    {
        eprintln!(
            "[ir-ls] deopt regs: nameable={} frame_slots_named_by_register={} regs_base={}",
            lowerer.deopt_nameable.iter().filter(|n| **n).count(),
            lowerer.deopt_reg_named.get(),
            lowerer.deopt_regs_base,
        );
        eprintln!(
            "[ir-ls] homes: dropped_values={} stores_skipped={} read_refusals={} \
             def_publishes={} def_stores_skipped={}",
            lowerer.home_dropped.iter().filter(|d| **d).count(),
            lowerer.home_stores_dropped,
            lowerer.home_read_refusals.get(),
            lowerer.reg_publishes_at_def,
            lowerer.homes_dropped_at_def,
        );
        // The counterpart to `dropped_values`, and the line to read when it is
        // low: of the values this compile PROMOTED, why each one still writes
        // its home. See `Lowerer::census_home_blocks`.
        let c = lowerer.census_home_blocks();
        eprintln!(
            "[ir-ls] homes kept: switch={} deopt={} type={} op={}",
            c[0], c[1], c[2], c[3],
        );
        // What the split plan actually FIRED, as opposed to what it planned.
        // The two are printed from different places on purpose: the plan's line
        // (`[ir-ls] splits:`) is what `plan_register_residency` decided, and
        // this is what the emission did with it. A plan with transitions and an
        // emission with none is the shape every stale diagnostic in this file
        // has taken, and one number cannot show it.
        let e = lowerer.ls_split_emitted;
        eprintln!(
            "[ir-ls] splits emitted: load={} remat={} move={} drop={} edge_resolution: edges={} loads={}",
            e[0],
            e[1],
            e[2],
            e[3],
            lowerer.ls_edge_copies.len(),
            lowerer.ls_edge_loads,
        );
    }
    // The accounting identity inside `census_home_blocks` is the thing that
    // keeps this census tied to `home_dropped`, and a check that only runs
    // under a diagnostic env var is a check no test performs — which is the
    // shape of the failure it exists to prevent. So a debug build pays for one
    // extra pass and gets the assertion on every lowering, diagnostics or not.
    #[cfg(debug_assertions)]
    {
        let _ = lowerer.census_home_blocks();
    }
    // Unconditional, and cheap: four relaxed adds per compiled method. The
    // per-method lines below are behind a diagnostic flag; this total is what a
    // probe-set census reads, and a census you have to switch on is one nobody
    // has for the run they already did.
    note_deferred_census(
        lowerer.deferred_candidates,
        lowerer.carry_deferred_planned,
        lowerer.deferred_skips[7],
        lowerer.deferred_mid_foldable,
    );
    if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_IR_LINEAR_SCAN") {
        eprintln!(
            "[ir-ls] carries: planned={} taken={} read={} refused={} \
             stores_dropped={} still_deopt_named={} deferred={}/{} cmp_in_place={}+{} \
             cmp_imm={}+{}",
            lowerer.carry_of.iter().filter(|c| c.is_some()).count(),
            lowerer.carries_taken,
            lowerer.carries_read,
            lowerer.carries_refused,
            lowerer.carry_stores_dropped,
            lowerer.carry_named,
            lowerer.carry_deferred_planned,
            lowerer.carry_deferred_read,
            lowerer.cmp_in_place,
            lowerer.cmp_in_place_frame,
            lowerer.cmp_imm,
            lowerer.cmp_imm_frame,
        );
        let s = lowerer.carry_skips;
        eprintln!(
            "[ir-ls] carry skips: multi_use={} wrong_type={} producer_arm={} \
             already_resident={} consumer_arm={} operand_position={}",
            s[0], s[1], s[2], s[3], s[4], s[5],
        );
        let d = lowerer.deferred_skips;
        eprintln!(
            "[ir-ls] deferred candidates={} taken={} | declined: \
             prod_carrying={} prod_multi_use={} prod_type_or_arm={} \
             prod_resident={} operand_position={} consumer={} \
             mid_writes_rcx={} (of which foldable={}) | non_candidate_windows={}",
            lowerer.deferred_candidates,
            lowerer.carry_deferred_planned,
            d[1],
            d[2],
            d[3],
            d[4],
            d[5],
            d[6],
            d[7],
            lowerer.deferred_mid_foldable,
            d[0],
        );
        eprintln!(
            "[ir-ls] alu immediates folded: {} add_lea={}+{} rcx_twins={}",
            lowerer.alu_imms_folded, lowerer.add_lea, lowerer.add_lea_acc, lowerer.rcx_twins,
        );
        // Wave 17: which unconditional back-edge polls of an OSR-door compile
        // can pull the loop back into the interpreter, and why the rest
        // cannot (`Lowerer::back_edge_mode_exit_state`). Wave 18: the same for
        // a method-entry compile, on a line of its own.
        let tier = match lowerer.poll_mode_exits {
            IrPollModeExits::Off => None,
            IrPollModeExits::OsrDoor => Some(""),
            IrPollModeExits::MethodEntry => Some("entry "),
            // Wave 53 (lane L2): the positive control of the named-only
            // exits; counted on the method-entry census row.
            IrPollModeExits::MethodEntryNamedOnly => Some("entry named-only "),
        };
        if let Some(tier) = tier {
            let m = lowerer.mode_exit_census;
            let refused: Vec<String> = ModeExitRefusal::CAUSE_NAMES
                .iter()
                .zip(&m[1..])
                .map(|(name, n)| format!("{name}={n}"))
                .collect();
            eprintln!(
                "[ir-ls] {tier}poll mode exits: given={} | refused: {}",
                m[0],
                refused.join(" ")
            );
        }
        // The SCHEDULER's half of the same question. `carry skips:
        // operand_position` above says how often the emitter wanted a triple
        // the scheduler had not formed; this says why it had not.
        let pc = schedule.pairing;
        eprintln!(
            "[ir-ls] operand pairing: candidates={} paired={} | declined: \
             multi_use={} producer_arm={} other_block={} after_consumer={} \
             already_adjacent={} deopt_between={} memory_order={} no_node={} too_far={}",
            pc.candidates,
            pc.paired,
            pc.multi_use,
            pc.producer_arm,
            pc.other_block,
            pc.after_consumer,
            pc.already_adjacent,
            pc.deopt_between,
            // `PairCensus` gained this bucket when the scheduler's step 5b
            // became `check_memory_order`'s business, and this printer
            // enumerates the fields by hand -- so it silently omitted the new
            // one, and the LINE stopped adding up while the identity
            // `PairCensus::closes` asserts went on holding. A census that reads
            // low retires levers that are engaged. See `NOTES-regalloc.md` S1.
            pc.memory_order,
            pc.no_node,
            pc.too_far,
        );
        eprintln!(
            "[ir-ls] carried homes dropped: {}",
            lowerer.carried_homes_dropped,
        );
        eprintln!(
            "[ir-ls] unreachable frame states: graph_trap_free={} homes_freed={} points_skipped={}",
            lowerer.graph_cannot_deopt(),
            lowerer.unreachable_homes,
            lowerer.unreachable_points_skipped.get(),
        );
    }

    // Carry the identity the prologue encoded, so publication can bind it to
    // the artifact this buffer becomes. It stays a reservation until the
    // artifact exists: the overflow refusal below drops it, releasing the id.
    // Read before `lowerer.compile_id` / `lowerer.buf` are moved out below
    // (wave 11, frames2).
    let deopt_gpr_image = lowerer.deopt_gpr_image();
    let deopt_xmm_image = lowerer.deopt_xmm_image();
    // Round nio21 wave 3 (lane L2): the sites the call-site exception pads
    // bake, owned by the artifact from here on (`_jit_local_handler_sites`).
    let call_throw_sites = std::mem::take(&mut lowerer.call_throw_sites);
    let mut compile_id = lowerer.compile_id;
    let mut buf = lowerer.buf;
    // Soundness bail (jit-inlining-and-ir-calls). `ExecutableBuffer::emit` is
    // non-panicking: on capacity exhaustion it sets a sticky `overflowed` flag
    // and DROPS the write, so an under-estimated buffer yields a silently
    // truncated body — execution runs off the end of the emitted code. The
    // single-pass backend has always checked this; the IR lowerer never did,
    // which was harmless only while its per-node emission was tiny and bounded.
    // Inline caches (~250 bytes/site) plus the widened invoke budget make the
    // estimate materially harder, so check it here and let the caller fall back
    // to single-pass, exactly like the unallocated-slot latch above.
    report_ir_buffer_size(graph.nodes.len(), call_nodes, buf.wanted(), capacity);
    if buf.overflowed() {
        // `needed` is `wanted()`, NOT `pos()`. `pos()` is the write cursor,
        // which STOPS at capacity the moment the buffer overflows — so it
        // reported `needed == capacity` on every single exhausted compile and
        // told you nothing about how much more the method actually wanted. The
        // whole 2026-08-01 census read `needed 4096 bytes, capacity 4096`
        // seventeen times over and looked like a tie. `wanted()` keeps counting
        // through the dropped writes, and this backend never calls `rewind_to`
        // or `emit_checked`, so it is the exact requirement rather than a
        // bound.
        //
        // On a first attempt that exactness is used, not just reported: the
        // caller lowers again at this size (round 9 wave 2). Not a refusal,
        // so nothing is counted here.
        // Only a genuine CAPACITY overflow: a `mark_codegen_unencodable`
        // discard also sets `overflowed`, and no bigger buffer fixes that.
        if let Some(out) = overflow_wanted {
            if buf.codegen_failure_reason().is_none() {
                *out = Some(buf.wanted());
                return None;
            }
        }
        return refuse(Bailout::new(BailoutReason::CodeBufferExhausted {
            needed: buf.wanted(),
            capacity,
        }));
    }
    let _code_size = buf.pos();

    // Round 9 wave 3 (runtime2 #2): the fallible constructor. A refused
    // RW -> RX flip (`VirtualProtect`/`mprotect` failing under commit
    // pressure) is a compile this method cannot finish, not a reason to abort
    // the process: `try_new` records it (`note_code_buffer_protect_failure`)
    // and the method stays on the tier below.
    let Some(mut cm) = CompiledMethod::try_new(buf) else {
        return refuse(Bailout::new(BailoutReason::Internal(
            "code-buffer-protect-failed",
        )));
    };
    cm.compile_id = compile_id.hand_off();
    cm.deopt_points = deopt_points;
    cm.named_poll_exits_only = named_poll_exits_only;
    cm.chain_poll_exits = chain_poll_exits;
    cm.exit_poll_sites = exit_poll_sites;
    cm.post_call_exit_sites = post_call_exit_sites;
    cm.exit_poll_flag = exit_poll_flag;
    // Published unconditionally since 2026-09-09.
    //
    // A merge inside a relocated callee body used to withhold this vector
    // wholesale (`ir::SPLICED_MERGE_SEEN`), because entering such an artifact
    // at a loop header produced a wrong, run-to-run varying answer. The cause
    // was never the splice: `emit_osr_entry_stubs` jumped past the block that
    // writes a CONSTANT's home word, and a merge store reads its arms from
    // their home words. `probes/Min0.java` reproduces it with no call at all.
    // The stub seeds those constants now — see the `const_seeds` loop there —
    // and the containment comes off with them.
    cm.ir_osr_entries = lowerer_osr_entries;
    cm.ir_osr_entry_kinds = lowerer_osr_entry_kinds;
    cm.ir_osr_opaque_entry_bcis = lowerer_osr_opaque_entry_bcis;
    cm.ir_osr_sentinel_free = osr_sentinel_free;
    cm.ir_osr_exception_exit_bcis = osr_exception_exit_bcis;
    cm.ir_osr_guard_exit_bcis = osr_guard_exit_bcis;
    cm.ir_osr_guard_fact_needs_opaque_entries = osr_guard_fact_needs_opaque_entries;
    cm._deopt_point_boxes = deopt_boxes;
    // nio21 wave 3 L2: forward-only candidates (`ir::call_site_throw_plan`
    // admits no handler at or before its call), so
    // `deopt::local_handler_replay_edges` reads no row out of them. The
    // SPLICE4-1 compiled handler arms' sites (JIT round 19 wave 5) own the
    // same kind of boxed `JitLocalHandlerSite`; both lists bake their boxes'
    // addresses, which a move of the `Box`es does not change.
    let mut local_handler_sites = call_throw_sites;
    local_handler_sites.extend(catch_site_boxes);
    cm._jit_local_handler_sites = local_handler_sites;
    // JIT round 19 wave 3 (lane eager3, EAGER2-4): the causes beside them.
    cm.trap_cause_points = trap_cause_points.into_boxed_slice();
    cm._forced_chain_deopt_counters = forced_chain_deopt_counters;
    cm._forced_chain_deopt_points = forced_chain_deopt_points;
    // Round 15 wave 1 (lane sync, SS8-2): closed-exits checked above;
    // `JitCache::put` then publishes it unwrapped.
    cm.self_locks_monitor = self_locks_monitor;
    cm.self_lock_hold = self_lock_hold;

    // ── Moving-young relocation contract ────────────────────────────────
    //
    // Publish what `conservative_roots` needs to decide, per frame, whether a
    // relocating young collection may proceed while this frame is live. Before
    // this the IR backend published NOTHING — no maps, no frame layout, no
    // safepoint-id slot — and an empty `oop_maps` reads as "no precise
    // coverage", so every live IR frame forced the non-moving sweep. That is
    // also why the optimizing tier was gated off under moving-young.
    //
    // The frame the lowerer builds, from `rbp` downward:
    //
    //     locals | [context] | bookkeeping ×5 | spills … | arg staging | argrsv | shadow
    //     ^0       ^locals    ^                 ^first_spill           ^spill_cap_off
    //
    // The five bookkeeping words are the safepoint id, the cached thread
    // pointer, the shadow save-base, the shadow save-top and the phi
    // parallel-copy scratch. They are all below `first_spill`, so the spill
    // band the maps and the deopt verifier describe is unchanged by them.
    //
    // `callee_saved_lo` names the start of the region the verifier must NOT
    // inspect: the callee-saved XMM save area (`IR_LOWER_SAVED_XMMS`, empty on
    // System V and on every compile with the linear-scan path off), then the
    // outgoing-argument staging, the stack-arg reserve and the ABI shadow
    // space. Register images, dead argument words and scratch — storage this
    // frame never resumes from, which is exactly the role the field plays on
    // the reader side (`band_slot_is_verifiable` skips everything at or above
    // it).
    //
    // The save area was placed at `spill_cap_off` precisely so this bound did
    // not have to move: it grew the skipped band from below without changing
    // either endpoint's meaning, and `conservative_roots` needed no edit. An
    // XMM save area could never hold a reference in any case — the file is
    // FP-only — but the band is the right home for it regardless, because
    // "this word is a register image" is the property the reader is testing.
    cm.sp_id_slot_off = sp_id_slot_off;
    cm.oop_maps = oop_maps;
    // JIT round 19 proposal wave 8, lane gc8 (GC719-1): the blocks held per
    // safepoint id, for the VM's locked-monitor depths. Only ids a map is
    // recorded at (every row is pushed beside its map); metadata only.
    cm.ir_monitor_homes = {
        let mut rows = ir_monitor_homes;
        rows.sort_unstable_by_key(|&(id, _)| id);
        rows.dedup_by_key(|(id, _)| *id);
        rows.retain(|(id, _)| cm.oop_maps.iter().any(|m| m.bytecode_pc == *id));
        rows.into_boxed_slice()
    };
    cm.frame_liveness = frame_liveness;
    // Ascending by construction (ids come from a counter), which is what
    // `CompiledMethod::safepoint_bci` binary-searches on. Sorted rather than
    // asserted: a future lowerer that emits a safepoint out of order would
    // otherwise turn a diagnostic into a wrong line, and the vector is one
    // entry per GC-capable point.
    // The inlined callees this tier spliced, as a stack trace needs them.
    //
    // `code_len()` is load-bearing exactly as it is on the single-pass side:
    // `from_rows` uses it to bound the offsets it will keep. An artifact that
    // spliced nothing pushes no rows and gets `InlineFrameMap::default()` —
    // two empty `Vec`s, the state every IR artifact was in before 2026-09-08,
    // when `compiled_frame_inline_chain` returned on its `is_empty()` guard and
    // IR-tier inlining contributed no frames at all.
    cm.inline_frame_map = crate::x64::InlineFrameMap::from_rows(inline_frame_rows, cm.code_len());
    // Round 14 wave 2 (lane trace): the innermost frame's exact key -- see
    // `InlineFrameMap::chain_for_safepoint_id`. `CRATONVM_JIT_IR_INLINE_CHAIN_BY_SP_ID=0`
    // attaches nothing, and the walk keeps the bci key (read once per compile).
    if !inline_frame_sp_id_rows.is_empty()
        && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_INLINE_CHAIN_BY_SP_ID")
    {
        cm.inline_frame_map
            .set_safepoint_id_rows(inline_frame_sp_id_rows);
    }
    // No `code_len` screen, for the reason the single-pass twin states at its
    // own publication site: the keys are monotonic ids rather than code
    // offsets, so a row nothing carries a key for is simply unreachable.
    cm.npe_trap_map = crate::x64::NpeTrapMap::from_rows(npe_trap_sites);
    cm.safepoint_bci_table = {
        let mut t = sp_id_bcis;
        t.sort_unstable_by_key(|(id, _)| *id);
        t.dedup_by_key(|(id, _)| *id);
        t
    };
    // Round 11 wave 14 (lane fib, `r11w14-rt-ir-lower-oop-free-frame-patch`):
    // a body that keeps no reference in its frame -- no `Ref` node, no
    // reference parameter, no frame block, so every map it published names no
    // slot -- tells the collector so, and the collector then neither scans nor
    // verifies its band (`CompiledMethod::frame_holds_no_references`). Such a
    // frame suspended in a direct JIT-to-JIT call is placed by its return
    // address (`return_site_bci_table`), recorded at every call
    // `note_inline_frame_return_site_at` saw -- the same set of calls the
    // inline-frame map is keyed on, for the same walk. The safepoint id is
    // still stored before every call, so the innermost frame's slot is
    // current as before.
    cm.frame_holds_no_references =
        body_keeps_no_references && cm.oop_maps.iter().all(|m| m.frame_slot_offsets.is_empty());
    // Interpreter round i5 wave 102, lane L2: kept for every body under
    // `CRATONVM_JIT_RETURN_SITE_LINE_FALLBACK` (the walk reads it only after
    // the slot refused, except for a reference-free frame as before).
    cm.return_site_bci_table = if cm.frame_holds_no_references
        || crate::return_site_line_fallback_enabled()
    {
        let mut t = return_site_rows;
        t.sort_unstable_by_key(|(off, _)| *off);
        t.dedup_by_key(|(off, _)| *off);
        t
    } else {
        Vec::new()
    };
    // Stage A.2 (precise oop maps, B-K fix) parity with the x64 fast-tier
    // driver (`x64/driver.rs`'s `cm.fully_oop_covered = compiler.precise_maps
    // && ... && compiler.safepoint_pcs.is_subset(&compiler.mapped_safepoint_pcs)`).
    // This backend never computed the field at all -- it stayed at the
    // `CompiledMethod` default of `false` for every method this tier compiled,
    // OSR or not, which blanket-failed `moving_young_osr_method_needs_fallback`'s
    // precise-map check on every OSR artifact this backend ever produced.
    // Measured 2026-08-22 on `TestKillProcessWhileWriting`: this is the
    // disjunct that actually fires (`osr_reason=(... map_coverage=N ...)`),
    // not the shadow layout and not a missing exact RBP -- both of which this
    // backend gets right already.
    //
    // Unlike the fast tier, this backend needs no PC-based subset check: each
    // `OopMapEntry` above already carries its own `moving_young_coverage_complete`
    // (the shadow-push `coverable && (published || slots.is_empty())` verdict,
    // computed per safepoint at the point it is emitted), and `cm.oop_maps` is
    // the complete set this compilation ever pushed to -- so the aggregate is a
    // straight AND over data already relied on elsewhere: it is the exact
    // per-entry flag `gc_quiescence`'s per-cycle proof already consults for
    // every non-OSR moving-young collection. An empty `oop_maps` makes this
    // vacuously true, which is safe: `has_precise_oop_maps()` (`!oop_maps.is_empty()`)
    // is what actually gates the fast tier's OR-branch on "no maps at all," so a
    // vacuous true here never overrides that check.
    cm.fully_oop_covered = cm.oop_maps.iter().all(|m| m.moving_young_coverage_complete);
    // The same aggregate under the name that says what it measures — see
    // `CompiledMethod::fully_shadow_covered`. The two coincide on THIS backend
    // and deliberately differ on the fast tier, where `fully_oop_covered` is
    // the frame-slot subset test; the OSR fallback reads `fully_shadow_covered`
    // so it gets the same question from both.
    cm.fully_shadow_covered =
        !cm.oop_maps.is_empty() && cm.oop_maps.iter().all(|m| m.moving_young_coverage_complete);
    cm.osr_frame_size = frame_size;
    // OSR and the save area, stated where the artifact is published.
    //
    // gcg g3/v (`gcg-g1f-ir-lower-osr-save-area-comment-and-assertion-read-the-wrong-osr-table`):
    // this block used to assert `cm.osr_pc_to_native.is_none()` and say "this
    // backend has no OSR". Both were stale: `osr_pc_to_native` is the
    // SINGLE-PASS trampoline's table (`x64/osr.rs`), which this backend never
    // sets, so the assertion could not fire; and this backend HAS OSR entries,
    // published in `cm.ir_osr_entries` and entered through its own stubs
    // (`emit_osr_entry_stubs`). The invariant the assertion was written for
    // holds by construction there: each stub builds the frame and saves the
    // caller's GPRs and XMMs into the SAME slots `emit_prologue` uses
    // (`saved_gpr_regs` / `saved_xmm_regs`), so every exit restores what was
    // saved. The single-pass trampoline (`osr_trampoline`, which enters past
    // `emit_prologue`) is never used for an artifact of this backend
    // (`an_ir_artifact_never_offers_an_osr_entry_the_save_area_would_break`).
    // Where the reader finds what the emission side published. Without these
    // three, `shadow_window_from_frame` cannot even locate the shadow stack —
    // it returns `None`, `published_shadow_values` yields the empty set, and
    // EVERY published word then reads back as unpublished. That is not a
    // partial failure that shows up as a smaller win: it makes a fully correct
    // publication indistinguishable from no publication at all, and it is what
    // `compiled-frame-oop-not-published` meant on `IrEscapeProbe` after the
    // maps, the frame record and the parameter homes were all in place.
    cm.shadow_thread_slot_off = shadow_thread_slot_off;
    cm.shadow_savebase_slot_off = shadow_savebase_slot_off;
    cm.shadow_frame_block = shadow_frame_block;
    cm.shadow_off_in_thread = helpers.shadow_stack_offset_in_thread as i32;
    // gen r5w6/oomjit10: the prologue's GPR save list, for the collector's
    // callee-saved-image rule (`CompiledMethod::ir_saved_gpr_slots`). The
    // same snapshot the prologue and every epilogue emit from.
    // gcg g3/v: published for OSR bodies too -- an OSR entry stub saves the
    // caller's registers into these same slots (see the block above). The old
    // guard tested the single-pass `osr_pc_to_native`, always `None` here, so
    // this is behaviour-identical.
    cm.ir_saved_gpr_slots = Some(ir_saved_gpr_slots);
    cm.frame_layout = super::FrameLayout {
        // Round 16 wave 11 (lane frames2, FR-B1): the EXCLUSIVE end of the
        // Java-local words, `(num_locals + 1) * 8` -- local `i` is at
        // `[rbp - (i + 1) * 8]`, so the last one is AT `num_locals * 8`, which
        // this used to publish. Every `FrameLayout` range is `lo..hi` with `hi`
        // exclusive, the single-pass producer publishes `(n + 1) * 8`, and
        // `FrameLayout::is_non_oop_reserved_tail_slot` reads `off >=
        // java_locals_hi` as the reserved tail: so the band scan (both its
        // root and pin halves) never read the last Java-local word of an
        // optimizing-tier frame, which is the prologue's home of the last
        // parameter when that parameter is the last local -- `this` of a
        // one-slot instance method, the reference argument of
        // `static f(Object)`. `ir_published_java_locals_hi`, kill switch
        // `CRATONVM_JIT_IR_PUBLISH_LAST_LOCAL=0`.
        java_locals_hi: ir_published_java_locals_hi(locals_size, ir_publish_last_local_enabled()),
        // No LICM hoists, no scalar-replacement slots and no per-safepoint
        // blind GPR spill in this backend: empty ranges (`hi == lo`), which
        // `is_register_image` and `region_name` both read as "absent".
        ref_hoist_lo: 0,
        ref_hoist_hi: 0,
        ref_hoist_mapped: false,
        arith_lo: 0,
        arith_hi: 0,
        scalar_lo: 0,
        scalar_hi: 0,
        locals_hi: first_spill,
        spill_lo: first_spill,
        spill_hi: spill_cap_off,
        callee_saved_lo: spill_cap_off,
        callee_saved_hi: frame_size,
        callee_saved_shallow: false,
        // Named separately as well as covered by the band above. Not for
        // `FrameLayout::region_name`: its ladder tests `callee_saved_*` first,
        // and on this backend that band spans the whole tail, so these words
        // still report as `callee-saved-gpr-image`. What the range decides is
        // the remap: `conservative_roots::is_callee_saved_gpr_image` excludes
        // it, so the register-image remap never rewrites an XMM word (a
        // double's bits are not a reference). `hi == lo == 0` when nothing was
        // reserved, which `is_register_image` already reads as "absent".
        xmm_saved_lo: if saved_xmm_bytes > 0 {
            spill_cap_off
        } else {
            0
        },
        // gci i4/ir (i4/so open item 1): `saved_xmm_regs` writes register
        // `k` at `MOVUPS [rbp - (spill_cap_off + 16*(k+1))]`, i.e. the words
        // at offsets `spill_cap_off + 8 ..= spill_cap_off + saved_xmm_bytes`,
        // and the reader's range is `[lo, hi)`: `hi` is one word past the
        // top save, or the low qword of the last saved XMM sat outside the
        // range and was admitted to the GPR-image remap (a double whose bits
        // equal a moved object's old address would have been rewritten). The
        // first GPR save is at `spill_cap_off + saved_xmm_bytes + 8`
        // (`saved_gpr_regs`), exactly `hi`, so it stays out. `lo` stays at
        // `spill_cap_off` on purpose: that word is the last spill colour
        // (`planned_slot_off` admits `off == spill_cap_off`), and keeping it
        // out of the remap keeps its present pin-not-rewrite treatment (a
        // `long` / `double` colour must never be rewritten); i4/so's
        // `ir_last_colour_is_dead_above_cursor` drops it when it is dead.
        xmm_saved_hi: if saved_xmm_bytes > 0 {
            spill_cap_off + saved_xmm_bytes + 8
        } else {
            0
        },
        reg_spill_lo: 0,
        reg_spill_hi: 0,
        // No outgoing reserve this backend can name; see
        // `FrameLayout::outgoing_lo`, where 0 means "no claim".
        outgoing_lo: 0,
        // The GPR half of this backend's `SavedRegisters` region, on the same
        // convention as the single-pass backend: `gpr[0]` is its LOWEST
        // address, at `[rbp - deopt_regs_base]`, so `deopt_regs_base` is the
        // DEEPEST of the sixteen offsets.
        //
        // On this tier the GPR half changes nothing: this backend's
        // `callee_saved_lo..callee_saved_hi` already spans the whole tail, and
        // both `region_name`'s ladder and `register_image_remap_admits` test
        // that band FIRST, so the GPR half already reports as
        // `callee-saved-gpr-image` and is already rewritten by
        // `remap_register_image_words`. The XMM half below is NOT inert here:
        // `is_callee_saved_gpr_image` subtracts `deopt_xmm_*` from the band, so
        // those words are withdrawn from the remap and let go by the pin
        // decision (no reference is ever resumed from them; see
        // `FrameLayout::deopt_xmm_lo`). It still reports as
        // `callee-saved-gpr-image` in `region_name`.
        //
        // Round 16 wave 11 (lane frames2): the words the image actually
        // reserves (`Lowerer::deopt_gpr_image`) -- all sixteen for the full
        // image, `gpr[0..=k]` for a sized one -- with `hi == base + 8` either
        // way, the convention the collector derives `gpr[0]` and the RBP image
        // from. With the switch off these are the literal `base - 120` /
        // `base + 8` this replaced.
        deopt_gpr_lo: deopt_gpr_image.0,
        deopt_gpr_hi: deopt_gpr_image.1,
        // The XMM half of the same region; see `FrameLayout::deopt_xmm_lo`.
        // Round 16 wave 7 (lane frames): through `deopt_xmm_image_range`,
        // which the fresh-frame clear's `_SKIP_UNROOTED` reads too. Same
        // values as the literal arithmetic this replaced. Wave 11 (frames2):
        // `(0, 0)` when a sized image reserves no XMM half.
        deopt_xmm_lo: deopt_xmm_image.map_or(0, |r| r.0),
        deopt_xmm_hi: deopt_xmm_image.map_or(0, |r| r.1),
        frame_size,
    };
    if needs_context {
        cm.needs_context = true;
    }
    // Guard-surviving scalar replacement: if any deopt frame carries a
    // scalar-replaced object as a `FrameValue::VirtualObject`, route this method
    // through the interpreter's precise-resume + materialize path
    // (`resume_real_ir_deopt` → `materialize_virtual_objects`) instead of the
    // no-materialize int-only path / whole-method re-run. Without this the
    // `can_deopt_resume` gate stays off for the IR backend and the emitted
    // VirtualObject is never consumed. Sound to enable: the per-slot mapper and
    // the materializer each bail to a safe whole-method re-run on any slot they
    // cannot reconstruct. Only reachable with `sr_map` set.
    //
    // A method that takes a monitor is no longer excluded. Until 2026-09-12
    // every `FrameState` this lowerer built hard-coded `monitors: Vec::new()`,
    // so a precise resume would have rebuilt a frame that believed it held no
    // lock, and this condition refused any graph with a monitor op. The
    // builder now records its monitor stack in every snapshot, and
    // `resolve_monitors` lowers it with a `relock` marker: a lock the compiled
    // code took is still held and is left alone, a lock escape analysis elided
    // is re-acquired by the resume after the object is materialized
    // (`build_deopt_frame_inner`). See
    // `ir-frame-states-carry-no-monitor-stack-FIXED-20260912.md`.
    if sr_map.is_some()
        && cm
            ._deopt_point_boxes
            .iter()
            .any(|p| crate::deopt::count_virtual_objects(&p.frame_state) > 0)
    {
        cm.can_deopt_resume = true;
    }
    // A body that takes a monitor vouches for its own frames too (round 11
    // wave 2, lane lower; `r11-tier-ir-monitor-body-trap-reruns-from-entry`).
    //
    // The sinks' OTHER precise-resume arm, `sink_precise_resume_allowed`,
    // refuses every body whose bytecode holds a monitor, because it cannot tell
    // this backend from the single-pass one — and the single-pass backend may
    // elide a lock without describing it. So an optimizing body with a
    // `synchronized` block and no scalar-replaced object answered neither arm,
    // and its trap re-ran the method from entry, repeating every side effect
    // committed before the trapping bci.
    //
    // This backend describes every lock: the builder records its monitor stack
    // in every snapshot (and refuses unstructured locking and any monitor in a
    // spliced body), and `resolve_monitors` publishes it with a `relock` marker
    // on each elided lock, which `build_deopt_frame_inner` honours. That is the
    // same promise the single-pass backend makes when it sets this flag for
    // every body with deopt points, `ACC_SYNCHRONIZED` ones included; the VM's
    // resume doors hand the method monitor to the resumed frame
    // (`JitSynchronizedMonitorGuard::transfer_to_resumed_frame`).
    if !cm.can_deopt_resume
        && !cm._deopt_point_boxes.is_empty()
        && graph.safepoints.iter().any(|sp| !sp.monitors.is_empty())
    {
        cm.can_deopt_resume = true;
    }
    // Round 12 wave 3 (lane replay): the same promise when the graph takes a
    // monitor but no surviving snapshot sits inside its region (a
    // `synchronized` block with no deopt point in it). Every point is then
    // outside every lock and its frame, which records the builder's monitor
    // stack, correctly holds none. Without the vouch the sinks' other arm
    // refuses the body for its monitor BYTECODE and the only fallback is a
    // whole-method replay, which for a conditional deopt in a loop that
    // stores after it commits the store again (or, with the loop-closed
    // replay rule, raises `InternalError`). `CRATONVM_JIT_IR_MONITOR_OP_VOUCH=0`
    // restores the snapshot-only rule.
    if !cm.can_deopt_resume
        && !cm._deopt_point_boxes.is_empty()
        && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_MONITOR_OP_VOUCH")
        && graph
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::MonitorEnter | Op::MonitorExit))
    {
        cm.can_deopt_resume = true;
    }
    // The same promise for a METHOD-ENTRY body of a method with monitor
    // bytecode that gave a back-edge poll an exit (interpreter round i1 wave
    // 19, lane L2; `ir_entry_mode_exits_admitted` admits such a method on this
    // arm). No surviving snapshot need carry a monitor (a `synchronized` block
    // with no safepoint inside leaves none), and then the rule above does not
    // fire, so the interpreter and first-call doors, whose other arm refuses
    // any monitor bytecode, would re-run the exit from entry. Every snapshot
    // still records the monitor stack, so the vouch holds for every point.
    if !cm.can_deopt_resume
        && poll_exits_emitted
        && lowerer.poll_mode_exits.is_method_entry()
        && poll_exit_bytecode.is_some_and(|b| {
            b.code_len <= b.code.len() && crate::bytecode_holds_monitor(b.code, b.code_len)
        })
    {
        cm.can_deopt_resume = true;
    }
    Some(cm)
}

// ── Tests ────────────────────────────────────────────────────────────

/// A definition whose value is already live in its register is not published
/// again -- **default ON** since 2026-09-05; `CRATONVM_JIT_IR_SKIP_REPUBLISH=0`
/// is the kill switch.
///
/// Off is the historical unconditional reload of the home word at every
/// definition site, phis included.
fn ir_skip_live_republish_enabled() -> bool {
    // 2026-09-05: DEFAULT ON. `=0` is the kill switch.
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_SKIP_REPUBLISH")
}

/// An edge's phi copies move register to register where both ends are
/// resident -- **default ON** since 2026-09-05;
/// `CRATONVM_JIT_IR_PHI_COPY_REGS=0` is the kill switch.
///
/// Off is the historical memory-to-memory copy through RAX followed by a
/// reload of the word just written.
fn ir_phi_copy_regs_enabled() -> bool {
    // 2026-09-05: DEFAULT ON. `=0` is the kill switch.
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_PHI_COPY_REGS")
}

/// Admit `Op::Phi` to the residency plan — **default ON** *within*
/// [`linear_scan_enabled`]; `CRATONVM_JIT_IR_PHI_RESIDENCY=0` is the kill
/// switch. Declared as `jit/ir-phi-residency`, so `-XX:` options and
/// `flags::with_thread_overrides` reach it.
///
/// # Why a sub-flag rather than riding the outer one
///
/// The outer flag turns on a *register file*. This turns on one *population's*
/// access to it, and the two fail differently: the file's risk is a value read
/// from a register nothing published, and the phi half's risk is the edge-copy
/// layer and the register layer disagreeing about an order (which is not
/// hypothetical — see `emit_phi_copies`' `defer_publish`, written after
/// `java.time.Duration.toNanos()` returned `seconds * 1e9 + seconds` on 198,356
/// calls in 200,000). A single flag makes a bisect unable to say which layer
/// moved; two flags let `CRATONVM_JIT_IR_PHI_RESIDENCY=0` keep the whole
/// pre-phi residency plan intact while taking the phi half out, which is what
/// named that layer as the owner of that bug in the first place.
///
/// It is also the A/B the doc asks for: with it off, the census reports
/// `[ir-ls] phis=N: ... disabled=N`, i.e. exactly how much a given workload has
/// riding on this, before anyone argues about a measurement.
///
/// # What it is off
///
/// Off is the pre-2026-09-02 emission for phis and nothing else: the allocator
/// keeps their structural pin (`release_phi_pins` is not called), the scan loop
/// refuses them under `PhiRefusal::Disabled`, and `emit_phi_copies` writes only
/// the home word at each incoming edge. Every other value's residency is
/// unchanged.
///
/// # What it is NOT
///
/// It is not a waiver of the safepoint obligation. A `Ref`-typed phi is refused
/// by type whichever way this flag is set — see the refusal in
/// [`plan_register_residency`], and
/// `a_reference_typed_phi_is_refused_by_type_whatever_the_flags_say`.
fn ir_phi_residency_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_PHI_RESIDENCY")
}

/// Promote only where a register can repay its prologue save -- **default
/// ON**, opt out with `CRATONVM_JIT_IR_RESIDENCY_PAYS=0` to promote every
/// candidate the allocator hands back, which is what this file did before
/// 2026-09-02 and what made `FibProbe.fib` slower with the file on than off.
fn ir_residency_pays_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RESIDENCY_PAYS")
}

/// What the NEXT register taken from the loop-carried reservation costs, in
/// loop-weighted uses, once `taken` have already been taken.
///
/// `carried_w` is every carried candidate's `live.weight`, descending. The
/// carried pass serves its list in that same order and stops when the file runs
/// out, so the value a crossblock admission actually displaces is the weakest
/// one that would still have been served -- `carried_w[file_len - 1]` -- and
/// each further admission displaces the next one up. The bar therefore RISES as
/// the file empties, which is what stops a run of cheap single-use values from
/// evicting the whole carried set one register at a time.
///
/// Returns `u64::MAX` once the file is spent, refusing everything after that,
/// and `0` when there are fewer carried candidates than registers -- nothing is
/// displaced then, so nothing has to be outbid.
///
/// The caller compares with `>=`, not `>`, and that is MEASURED rather than
/// chosen. On `probes/FieldLoop.java` the carried weights are
/// `[20, 11, 10, 10, 10, 10]`, so the price is 10 -- and the induction variable
/// the whole transform exists to serve weighs exactly 10 too. Under `>` all ten
/// candidates are refused and the body reverts to its slow 1052 bytes. A tie
/// means "these two values are read equally often", and at that point the
/// crossblock value is the better holder: the carried pass's own candidates are
/// phis and loop-carried values whose home word is written by
/// `emit_phi_copies` at every incoming edge regardless, so their register saves
/// reads only, while the crossblock value's register removes a store AND a
/// reload. `probes/RegPressure.java` is unaffected by the tie-break -- its price
/// is 21 against candidates weighing 10, which `>=` refuses just as `>` did.
///
/// This replaces a COUNT-based budget, which was built first and measured wrong:
/// `ir_gp_file().len() - carried_demand` is zero for any loop with five or more
/// carried candidates, which is most loops including `probes/FieldLoop.java` --
/// so it removed the regression on `RegPressure` by removing the transform
/// everywhere, reverting `FieldLoop.sum` to its slow 1052-byte body. A count
/// cannot tell "displacing something worth less than me" from "displacing
/// something worth more".
fn carried_displacement_price(carried_w: &[u64], taken: usize) -> u64 {
    let file_len = ir_gp_file().len();
    if carried_w.len() < file_len {
        return 0;
    }
    match file_len.checked_sub(1 + taken) {
        Some(i) => carried_w.get(i).copied().unwrap_or(0),
        None => u64::MAX,
    }
}

/// Leave the loop-carried reservation its registers before the crossblock arm
/// spends them -- **default ON**, opt out with
/// `CRATONVM_JIT_IR_RESIDENCY_CROSSBLOCK_BUDGET=0`.
///
/// [`ir_residency_crossblock_enabled`] admits single-use values in the MAIN
/// residency loop. `ir_reserve_carried_enabled`'s pass runs after it, over
/// `free = ir_gp_file() - taken`, so on a contended method the crossblock arm
/// can spend the whole file before the values read on every iteration are ever
/// considered. That is measured, on `probes/RegPressure.java`: 5 loop-carried
/// values resident with the flag off, 2 with it on, and 5-12% SLOWER.
///
/// The budget is the cheapest form of the occupancy term that result asks for.
/// Count what the carried pass will want -- the same predicate it uses -- and
/// let the crossblock arm have only what is left over:
///
/// ```text
/// budget = ir_gp_file().len() - |{ id : live.carried_and_read[id] && has home
///                                      && Int|Long && !Const && (phi ok) }|
/// ```
///
/// It is deliberately a COUNT and not a priority queue. The carried pass
/// already orders its own candidates by loop-weighted use count; this only has
/// to stop the main loop from emptying the file first, and a count does that
/// without duplicating the ordering in two places that could disagree.
fn ir_residency_crossblock_budget_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RESIDENCY_CROSSBLOCK_BUDGET")
}

/// Let a SINGLE-USE value be register-resident when the carry window cannot
/// reach it -- **default OFF**, opt in with
/// `CRATONVM_JIT_IR_RESIDENCY_CROSSBLOCK=1`.
///
/// `ir_residency_pays_here` reduces to `static_uses >= 2` in a default build
/// (`ir_residency_loop_weight_enabled` is off), so a value read ONCE never gets
/// a register. The reasoning behind that rule is sound where it applies: a
/// single-use value costs one publish and saves one reload, which is a wash --
/// **and `plan_carries` already serves those, for free, by handing the
/// producer's RAX straight to the consumer.**
///
/// But `plan_carries` scans a window exactly one node wide:
///
/// ```text
/// for w in 1..block.nodes.len() {
///     let prod = block.nodes[w - 1];
///     let cons = block.nodes[w];
/// ```
///
/// so it reaches a single-use value only when its consumer is the very next
/// node in the same block. For every other single-use value the trade is not a
/// wash at all: the alternative to a register is a home STORE and a RELOAD, two
/// memory operations, and the publish that replaces them is a register move.
///
/// `FibCall.fib` is the shape that names it. `n-1` and `n-2` are computed in
/// the entry block and read at call sites blocks later, so neither can be
/// carried and neither is resident:
///
/// ```asm
/// lea eax,[rbx-1] ; mov [rbp-50h],rax    ; … stored in the entry block
/// mov rdx,[rbp-50h]                      ; … and reloaded at the call
/// ```
///
/// Four memory operations per call for two values a callee-saved register would
/// have held across it, which is what the single-pass tier does and what
/// `c2-fib-per-call-budget-20260912.md` counts as the largest term in that
/// method's per-call budget.
///
/// This admits exactly the complement of the carry window, so the two
/// mechanisms partition the single-use population instead of competing for it:
/// `plan_carries` already declines a value residency took
/// (`assigned_gpr(prod).is_some()`, `carry_skips[3]`).
///
/// **MEASURED** (2026-09-12, one binary, arms interleaved with a control arm;
/// `c2-the-per-frame-contract-residency-20260912.md`):
///
/// ```text
/// FieldLoop.sum  reps=3000 n=20000   A 99.0 | C 99.0 | B 91.5 ms
///                floor 0.0%   effect -7.6%   ratio 0.924x   FASTER
/// FibCall.fib    n=30                A 179.0 | C 177.0 | B 178.0 ms
///                floor 1.1%   effect +0.0%   ratio 1.000x   UNMEASURABLE
/// ```
///
/// The loop win is one value: `i + 1` is read exactly once, by the phi at the
/// back edge, so it was stored to its home and reloaded on every iteration.
/// The optimizing body SHRINKS there, 1052 -> 1039 bytes.
///
/// `fib` is the cost side. It admits four more values (`single_use` 13 -> 6,
/// `resident` 2 -> 6) and grows the body 788 -> 883, because every register in
/// [`ir_gp_file`] is callee-saved and `fib` has FOUR epilogues, each restoring
/// the whole set -- twelve restores EMITTED against three removed reloads.
///
/// That static count is not the cost, and `probes/ManyExits.java` was written
/// to prove it was: loop-free with SIX exits, the shape an epilogue-scaled cost
/// would have to lose on. It is neutral twice (1.007x, 1.002x). **Exactly one
/// epilogue executes per call**, so the file is saved once and restored once
/// whatever the static exit count:
///
/// ```text
///   dynamic cost = 2 memory ops per promoted register, PER CALL
///                  (one save, one restore) -- NOT scaled by exit count
///   static cost  = 1 + N_epilogues per register  (code size only)
///   benefit      = reloads/stores removed, TIMES how often they execute
/// ```
///
/// All three probes follow from that: `fib` and `ManyExits` each pay ~6 ops and
/// recover ~6 (a wash, at four exits and at six alike), while `FieldLoop` pays
/// ZERO -- its body already saves all five registers in both arms -- and
/// recovers a load and a store on each of 20 000 iterations.
///
/// `static_uses >= 2` misses both sides: it counts static edges rather than
/// executions, and it prices a register-to-register publish as costing what a
/// memory reload costs.
///
/// **DEFAULT OFF, and the losing shape is now KNOWN.** `probes/RegPressure.java`
/// oversubscribes the five-register file -- six loop-carried accumulators plus
/// three cross-block single-use values -- and this flag is SLOWER there, three
/// runs out of three, each above its own floor:
///
/// ```text
///   mix       (6 accumulators)   floor 0.9%  +12.5%  ratio 1.125x  SLOWER
///   mix       (confirmation)     floor 5.5%   +9.7%  ratio 1.097x  SLOWER
///   mixNarrow (3 accumulators)   floor 2.3%   +5.4%  ratio 1.054x  SLOWER
/// ```
///
/// The census names it: 25 more values admitted buys ONE more resident, while
/// `split_or_spilled` goes 12 -> 28 and `carried_reserved` 5 -> 2. The model
/// above prices the register as free to take; under pressure its real price is
/// whatever the value that would otherwise have held it was worth, and on that
/// probe that value is read every iteration.
///
/// [`ir_residency_crossblock_budget_enabled`] is that occupancy term, and it is
/// **default ON**. With it, `mix` compiles byte-identically to this flag being
/// off (3164) so its 12.5% is structurally gone, and `FieldLoop`'s win is kept
/// (1039). It is still not enough to flip THIS flag on: `mixNarrow` remains
/// 1.067x slower over a 0.0% floor, and it cannot be fixed by any rule of that
/// shape -- it and `FieldLoop.sum` present identical carried weights, identical
/// displacement price and identical candidate weights, and diverge anyway. Loop
/// weight is not the discriminating variable; the allocator's own outcome under
/// the added pressure is. See section 6d.
///
/// Correctness is not the objection -- section 6b: `jit-flag-soak` divergent=0,
/// every `CratonBench` / `CratonBenchC2` checksum bit-identical.
///
/// **Measuring this flag on a new probe: check `CRATONVM_DBG=jit-disasm` prints
/// a `full/ir` body at the A/B's settings, and that the two arms' `len=` DIFFER.**
/// The OSR door is single-pass only (`osr ir-eligibility: ... INERT at this
/// door`) while still running the IR pipeline, so a linear-scan census can differ
/// between arms that execute byte-identical code. The first run of `RegPressure`
/// read 1.000x over a 0.5% floor for exactly that reason.
fn ir_residency_crossblock_enabled() -> bool {
    matches!(
        cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_RESIDENCY_CROSSBLOCK").as_deref(),
        Ok("1") | Ok("true") | Ok("on") | Ok("yes")
    )
}

/// Is `id`'s single use the node immediately after it in its own block -- the
/// window [`Lowerer::plan_carries`] scans?
///
/// Mirrors that scan deliberately, including its "consumer is `nodes[w]`,
/// producer is `nodes[w - 1]`" shape, so the two cannot drift into either
/// double-serving a value or leaving one to neither. It does NOT re-check the
/// carry's type and arm conditions: a value that clears this window but fails
/// those is one the carry declines and residency would then have to serve, and
/// answering `true` here would leave it with nothing. Erring toward `false`
/// hands it to residency, which is the side that always has an answer.
fn single_use_is_in_the_carry_window(graph: &Graph, schedule: &Schedule, id: usize) -> bool {
    for block in &schedule.blocks {
        let Some(w) = block.nodes.iter().position(|&n| n as usize == id) else {
            continue;
        };
        let Some(&cons) = block.nodes.get(w + 1) else {
            return false;
        };
        return graph
            .nodes
            .get(cons as usize)
            .is_some_and(|cn| cn.inputs.iter().any(|&i| i != NO_NODE && i as usize == id));
    }
    false
}

/// A constant is read as an immediate rather than from its home word --
/// **default ON**, opt out with `CRATONVM_JIT_IR_CONST_IMM=0`.
fn ir_const_imm_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_CONST_IMM")
}

/// A compare whose only use is its `If` lowers as one `cmp; jcc`, and a
/// branch edge with no phi copies emits no trampoline -- both edges when
/// neither carries copies, and (round 9) the copy-free edge of a branch whose
/// other edge does -- **default ON**, opt out with
/// `CRATONVM_JIT_IR_FUSED_BRANCH=0`, which restores the general
/// trampoline layout for every two-successor `If`.
fn ir_fused_branch_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_FUSED_BRANCH")
}

/// `CRATONVM_JIT_IR_FUSED_CLASS_TEST_BRANCH=1` (JIT round 18 wave 11, lane
/// osrfollow, OSRPOLY18-1; **default OFF**, a perf switch): an
/// `Op::ExactClassIs` whose only use is an `Op::If` -- each class test of the
/// guarded receiver splices (mono-, bi- and polymorphic) -- is tested on the
/// flags at the branch ([`Lowerer::emit_exact_class_test_flags`]) instead of
/// `MOV EAX, 1/0; store; reload; TEST`. Same answer for every input (null and
/// arrays still answer "no"); per test it saves the 0/1 materialisation, a
/// frame store and a reload. Only asked when `CRATONVM_JIT_IR_FUSED_BRANCH` is
/// on too. Read once per lowering; no `static`.
fn ir_fused_class_test_branch_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_FUSED_CLASS_TEST_BRANCH")
}

/// The bytes of [`Lowerer::emit_exact_class_test_flags`] (see there for the
/// layout): ZF=1 iff RAX is non-null, a plain object and of exactly
/// `class_id`. RAX-only.
fn exact_class_test_flags_bytes(class_id: u32) -> [u8; 23] {
    const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
    let id = class_id.to_le_bytes();
    [
        0x48,
        0x85,
        0xC0, // TEST RAX, RAX
        0x74,
        0x0F, // JZ null (+15 -> 20)
        0xF6,
        0x40,
        cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8,
        cratonvm_types::KIND_TAG_BYTE_MASK, // TEST BYTE [RAX+kind], mask
        0x75,
        0x0C, // JNE done (+12 -> 23), ZF=0
        0x81,
        0x78,
        0x00,
        id[0],
        id[1],
        id[2],
        id[3], // CMP DWORD [RAX+0], class_id
        0xEB,
        0x03, // JMP done (+3 -> 23)
        0x83,
        0xC8,
        0x01, // null: OR EAX, 1 (ZF=0)
    ]
}

/// JIT round 19 proposal wave (lane osr19, OSRPOLY19-2): the bytes of the
/// `Op::ClassWordOf` arm and of its OSR recomputation
/// ([`OsrRematInsn::ClassWordOf`]). In: a reference in RAX. Out: RAX = the
/// sign-extended 32-bit header class word of a plain object, `0` for a null
/// (no load) or an array (whose header names its component). RAX-only; every
/// jump is rel8 because the sequence is fixed-length:
///
/// ```text
///   +0  TEST RAX, RAX                 48 85 C0
///   +3  JZ done (+13): RAX is the 0   74 0D
///   +5  TEST BYTE [RAX+kind], mask    F6 40 kk mm
///   +9  JNE zero (+5)                 75 05
///  +11  MOVSXD RAX, DWORD [RAX+0]     48 63 00
///  +14  JMP done (+2)                 EB 02
///  +16  zero: XOR EAX, EAX            31 C0
///  +18  done:
/// ```
///
/// Sign-extended so the word is a canonical `int` in a 64-bit home: the
/// chain's `Cmp(Eq, word, Const(id))` compares it with `id as i32`.
fn class_word_of_bytes() -> [u8; 18] {
    const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET <= 127);
    [
        0x48,
        0x85,
        0xC0, // TEST RAX, RAX
        0x74,
        0x0D, // JZ done (+13 -> 18)
        0xF6,
        0x40,
        cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8,
        cratonvm_types::KIND_TAG_BYTE_MASK, // TEST BYTE [RAX+kind], mask
        0x75,
        0x05, // JNE zero (+5 -> 16)
        0x48,
        0x63,
        0x00, // MOVSXD RAX, DWORD [RAX]
        0xEB,
        0x02, // JMP done (+2 -> 18)
        0x31,
        0xC0, // zero: XOR EAX, EAX
    ]
}

/// JIT round 19 wave 3 (lane eager3, EAGER2-3): the `Op::ClassInitTest` arm's
/// machine code. RAX = `1` when the byte at `state_addr` (a class's
/// `init_state`, kept alive by the artifact) equals `initialized`, else `0`.
///
/// ```text
///   +0  MOV RAX, imm64(state_addr)    48 B8 <8>
///  +10  MOVZX EAX, BYTE [RAX]         0F B6 00
///  +13  CMP EAX, imm32(initialized)   3D <4>
///  +18  SETE AL                       0F 94 C0
///  +21  MOVZX EAX, AL                 0F B6 C0
///  +24
/// ```
///
/// A plain byte load: x86-64 loads are acquire, so a `1` here orders every
/// later read after the initializing thread's publication of the class, as
/// `vm_util::is_class_initialized_fast`'s `Acquire` load does.
fn class_init_test_bytes(state_addr: u64, initialized: u8) -> [u8; 24] {
    let a = state_addr.to_le_bytes();
    let v = u32::from(initialized).to_le_bytes();
    [
        0x48, 0xB8, a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7], // MOV RAX, imm64
        0x0F, 0xB6, 0x00, // MOVZX EAX, BYTE [RAX]
        0x3D, v[0], v[1], v[2], v[3], // CMP EAX, imm32
        0x0F, 0x94, 0xC0, // SETE AL
        0x0F, 0xB6, 0xC0, // MOVZX EAX, AL
    ]
}

/// Fuse `fcmp<l|g>`/`dcmp<l|g>; if<lt|le|gt|ge>` into one `UCOMIS; Jcc`
/// (`fused_fcmp`) -- **default ON**, opt out with `CRATONVM_JIT_IR_FUSED_FCMP=0`
/// (round 9 wave 8, irl8). Only asked when `CRATONVM_JIT_IR_FUSED_BRANCH` is
/// on too; that switch still turns every fusion off.
fn ir_fused_fcmp_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_FUSED_FCMP")
}

/// How `FCmp(a, b) <cc> 0` branches as ONE `UCOMIS; Jcc`:
/// `Some((swap, taken_jcc))` means `UCOMIS a, b` (or `UCOMIS b, a` when
/// `swap`) followed by the near-Jcc byte `taken_jcc` is taken exactly when the
/// JVMS three-way result satisfies `<cc> 0` -- NaN included. `None` for
/// `Eq`/`Ne`, which need ZF and PF together.
///
/// `UCOMIS p, q` sets CF on `p < q` OR unordered, ZF on `p == q` OR
/// unordered, neither on `p > q`. So `JA` (CF=0, ZF=0) is "`p > q`, NaN
/// false", `JAE` "`p >= q`, NaN false", `JB` "`p < q`, NaN true", `JBE`
/// "`p <= q`, NaN true". `fcmpl`/`dcmpl` answer -1 on NaN, so `< 0`/`<= 0` are
/// NaN-true and `> 0`/`>= 0` NaN-false: that is exactly `UCOMIS a, b` with
/// `JB/JBE/JA/JAE`. `fcmpg`/`dcmpg` answer +1, flipping which side NaN lands
/// on; swapping the operands (`UCOMIS b, a`) and mirroring the condition
/// gives it. Every answer is a single flags predicate, so its negation (the
/// `cc ^ 1` the branch layout takes) is the exact complement, NaN included.
fn fcmp_fused_branch(cc: CmpOp, nan_greater: bool) -> Option<(bool, u8)> {
    const JB: u8 = 0x82;
    const JAE: u8 = 0x83;
    const JBE: u8 = 0x86;
    const JA: u8 = 0x87;
    let jcc = match (cc, nan_greater) {
        (CmpOp::Gt, false) => JA,
        (CmpOp::Ge, false) => JAE,
        (CmpOp::Lt, false) => JB,
        (CmpOp::Le, false) => JBE,
        // `UCOMIS b, a`: `a > b` is `b < a`, and NaN must answer true.
        (CmpOp::Gt, true) => JB,
        (CmpOp::Ge, true) => JBE,
        // ...and here NaN must answer false.
        (CmpOp::Lt, true) => JA,
        (CmpOp::Le, true) => JAE,
        (CmpOp::Eq | CmpOp::Ne, _) => return None,
    };
    Some((nan_greater, jcc))
}

/// `(cell, payload32, payload64)`: the byte offsets, within its class's
/// statics block, of static field `field_index`'s 16-byte `Value` cell and of
/// the cell's 32- and 64-bit payload words; `None` past a disp32. The one place
/// the inline `getstatic` and `putstatic` arms (`Lowerer::emit_inline_getstatic`,
/// `Lowerer::emit_inline_putstatic`) derive them, so the two cannot disagree
/// and the layout-constant inventory (`layout_const_inventory.rs`) counts one
/// site for both, as it did for the `getstatic` arm alone. A statics block
/// has no object header, so no `HEADER_SIZE` term.
fn static_cell_offsets(field_index: u32) -> Option<(i32, i32, i32)> {
    let cell = i32::try_from((field_index as usize).saturating_mul(SLOT_SIZE)).ok()?;
    Some((
        cell,
        cell.checked_add(FIELD_CELL_PAYLOAD32_OFFSET as i32)?,
        cell.checked_add(FIELD_CELL_PAYLOAD64_OFFSET as i32)?,
    ))
}

/// The null + mapped receiver guard is emitted once per receiver per block --
/// **default ON**, opt out with `CRATONVM_JIT_IR_RECEIVER_GUARD_CSE=0`.
fn ir_receiver_guard_cse_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_RECEIVER_GUARD_CSE")
}

/// Round 16 (lane fieldguard, FG16-1): the bytecode pcs that exactly one live
/// node outside [`op_cannot_deopt`] carries. A deopt at such a pc resumes the
/// interpreter at an instruction this body has done nothing of yet, when the
/// guard precedes the node's own effects; a pc two such nodes share (an
/// intrinsic expansion of one `invoke`, an unrolled copy) is left out.
fn layout_guard_lone_pcs(graph: &Graph) -> std::collections::HashSet<usize> {
    let mut owners: HashMap<usize, u32> = HashMap::new();
    for n in &graph.nodes {
        if n.op == Op::Dead || op_cannot_deopt(&n.op) {
            continue;
        }
        if let Some(pc) = n.bytecode_pc {
            *owners.entry(pc).or_insert(0) += 1;
        }
    }
    owners
        .into_iter()
        .filter(|&(_, count)| count == 1)
        .map(|(pc, _)| pc)
        .collect()
}

/// `CRATONVM_JIT_IR_BCI_ANCHOR_DOMINATED` -- **default ON** (`=0` restores
/// the earliest-owner rule; JIT round 17 wave 3, lane irlower; item 1 of
/// `r17-monitor2-by-bci-readers-that-stay-by-bci-FIXED-20261005.md`): the by-bci
/// table anchor of a pc prefers an owner whose block the snapshot's values'
/// defining blocks dominate ([`Lowerer::note_bci_anchor`]). Read once per
/// lowering (no `static`).
fn ir_bci_anchor_dominated_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_BCI_ANCHOR_DOMINATED")
}

/// Per bci, the distinct blocks defining a value that a BY-BCI snapshot there
/// names: a snapshot that is not a splice chain (`build_deopt_points` skips
/// those) and that no live node claims through [`Node::frame_snapshot`] (a
/// claimed one anchors through `snapshot_native`, never `bci_native`). A value
/// with no scheduled block (a parameter, an unscheduled constant) adds none.
/// A bci whose snapshots name no scheduled value maps to an empty list, which
/// every owner satisfies.
fn bci_anchor_value_blocks(graph: &Graph, schedule: &Schedule) -> HashMap<usize, Vec<usize>> {
    let nb = schedule.blocks.len();
    let mut claimed = vec![false; graph.safepoints.len()];
    for n in &graph.nodes {
        if n.op == Op::Dead {
            continue;
        }
        if let Some(c) = n.frame_snapshot.and_then(|si| claimed.get_mut(si as usize)) {
            *c = true;
        }
    }
    let mut out: HashMap<usize, Vec<usize>> = HashMap::new();
    for (i, sp) in graph.safepoints.iter().enumerate() {
        if sp.is_splice_state() || claimed.get(i).copied().unwrap_or(false) {
            continue;
        }
        let blocks = out.entry(sp.bci).or_default();
        for &v in sp
            .locals
            .iter()
            .chain(sp.stack.iter())
            .chain(sp.monitors.iter())
        {
            if v == NO_NODE {
                continue;
            }
            let Some(vn) = graph.nodes.get(v as usize).filter(|n| n.op != Op::Dead) else {
                continue;
            };
            // A φ is defined at its merge's block (the scheduler places no φ
            // in a block's node list); every other value at its own block.
            let at = if matches!(vn.op, Op::Phi) {
                vn.input_opt(0).unwrap_or(NO_NODE)
            } else {
                v
            };
            let Some(b) = schedule.node_to_block.get(at as usize).copied() else {
                continue;
            };
            if b < nb && !blocks.contains(&b) {
                blocks.push(b);
            }
        }
    }
    out
}

/// `CRATONVM_JIT_IR_LAYOUT_GUARD_LONE_PER_FRAME=1` (opt-in; JIT round 17 wave
/// 3, lane irlower; item 3 of
/// `r17-monitor2-by-bci-readers-that-stay-by-bci-FIXED-20261005.md`): count the
/// deopting layout guard's lone sites per `(pc, own frame)`
/// ([`layout_guard_lone_sites`]) instead of per pc. Inert unless
/// `CRATONVM_JIT_IR_LAYOUT_GUARD_DEOPT` is on. Read once per compile.
fn ir_layout_guard_lone_per_frame_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_IR_LAYOUT_GUARD_LONE_PER_FRAME")
}

/// [`layout_guard_lone_pcs`] counted per `(pc, own frame)`: a node outside
/// [`op_cannot_deopt`] that names its OWN frame at its pc
/// ([`node_names_own_frame_at_its_pc`]: a per-copy frame of an unrolled or
/// coarsened body, an LICM pre-header frame) is keyed by that frame, every
/// other node by `(pc, None)`. A key one node owns is lone.
///
/// Why that is the lone-pc rule's own argument, per copy. The rule exists so
/// that the deopt re-executes nothing but the site itself: no other effectful
/// node of the SAME program point ran before the guard. Each copy's frame
/// describes a distinct program point (that copy's iteration), and the guard
/// deopts with that frame (`emit_deopt_unless` resolves through
/// `cur_node_frame` first), so what the interpreter re-executes is the copy's
/// own instruction; earlier copies' effects are complete and their results
/// are in the frame. Two effectful nodes of one copy at one pc (an intrinsic
/// expansion inside a copy) share a key and stay non-lone, as two unnamed
/// nodes at one pc always did. An unnamed node keeps the by-bci frame, which
/// describes the original's program point, and is lone when it is the only
/// unnamed owner.
fn layout_guard_lone_sites(graph: &Graph) -> std::collections::HashSet<(usize, Option<u32>)> {
    let mut owners: HashMap<(usize, Option<u32>), u32> = HashMap::new();
    for n in &graph.nodes {
        if n.op == Op::Dead || op_cannot_deopt(&n.op) {
            continue;
        }
        if let Some(pc) = n.bytecode_pc {
            let own = n
                .frame_snapshot
                .filter(|_| node_names_own_frame_at_its_pc(graph, n));
            *owners.entry((pc, own)).or_insert(0) += 1;
        }
    }
    owners
        .into_iter()
        .filter(|&(_, count)| count == 1)
        .map(|(key, _)| key)
        .collect()
}

/// `CRATONVM_JIT_IR_LEGACY_FIELD_INLINE` (round 16, lane fieldguard, FG16-7) --
/// **default ON** since round 16 batch 3 (`=0` is the kill switch): an inline
/// field site with NO compact row (its class has no compact layout, e.g. a JDK
/// class padded to a synthetic-stub floor) reads and stores through the legacy
/// arm alone instead of calling the checked helper. See
/// [`legacy_only_field_tag`]. Read per site at compile time; no static.
///
/// Such a site is not a `no-compact-slot-for-pc` decline any more, so that
/// census no longer shows whether a class has a compact layout; the
/// `CRATONVM_DBG_JITC` line `[ir] field rows <method>: compact=N rowless=M`
/// (`jit/src/lib.rs` `ir_tier_attempt`) does.
fn ir_legacy_field_inline_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_LEGACY_FIELD_INLINE")
}

/// Round 16 (lane fieldguard, FG16-7): the descriptor tag a legacy-only inline
/// READ uses for a node of type `ty` (`0` refuses the site).
///
/// # Why a site with no compact row may read inline at all
///
/// `ir_compact_fields` carries a row only when the field's declaring class has
/// a registered compact layout (`compact_field_disp`). The JDK's
/// `java/util/ArrayList$Itr` has none: its synthetic-stub table pads it to five
/// slots, and `build_compact_layout` refuses any padded class
/// (`r16-arraylist-jdk-arraylist-field-sites-take-the-checked-helper`), so
/// every `cursor`/`lastRet`/`this$0` access was a `jit_getfield` /
/// `jit_putfield_int` CALL. The compact row is what the inline arms need only
/// for their COMPACT half; the legacy half reads the uniform 16-byte `Value`
/// cell at `HEADER_SIZE + index * SLOT_SIZE`, which depends on no class layout
/// at all. So without a row the site emits that half alone, guarded by:
///
/// * the per-object compact bit -- set means "compact layout registered after
///   this compile resolved its rows", which has no displacement here, so the
///   checked helper;
/// * `num_slots > index` on the legacy header -- natives mint instances with an
///   explicit slot count (`alloc_concurrent_synthetic`), and a short one goes
///   to the helper, which bounds-checks, instead of reading past the object;
/// * for a reference, the cell's tag (`FIELD_CELL_TAG_OBJECT`), exactly as the
///   compact-row arm's legacy half checks it.
///
/// No layout-epoch guard: nothing baked depends on a layout. The width comes
/// from the node's type, which the builder took from the field descriptor:
/// every int-category legacy payload is the narrowed `Value::Int`, read back
/// sign-extended exactly as the helper answers.
fn legacy_only_field_tag(ty: IrType) -> u8 {
    match ty {
        IrType::Ref => b'L',
        IrType::Int => b'I',
        IrType::Long => b'J',
        IrType::Float => b'F',
        IrType::Double => b'D',
        _ => 0,
    }
}

/// [`legacy_only_field_tag`] for a STORE of `kind` (the value is already
/// narrowed to a sub-int field's width by the builder).
fn legacy_only_store_tag(kind: MemKind) -> u8 {
    match kind {
        MemKind::Int => b'I',
        MemKind::Long => b'J',
        MemKind::Float => b'F',
        MemKind::Double => b'D',
        _ => 0,
    }
}

/// The legacy (long) header's field-count word: the one place the legacy-arm
/// bounds checks take `NUM_SLOTS_OFFSET` from (the layout-constant inventory
/// counts it once for both).
fn legacy_num_slots_disp() -> i32 {
    cratonvm_types::NUM_SLOTS_OFFSET as i32
}

/// The legacy (long-header) displacement of field `field_index`'s 16-byte
/// `Value` cell, `HEADER_SIZE + field_index * SLOT_SIZE` -- the inline
/// `getfield`'s legacy arm's, compact row or not (FG16-7).
fn legacy_cell_disp(field_index: usize) -> i32 {
    (HEADER_SIZE + field_index * SLOT_SIZE) as i32
}

