    // ── Regression: BUG FIX [jit-irlower #1 + #3] — Op::Cmp SETcc ────────
    //
    // Hand-build a single-block graph whose Return value is a bare
    // `Op::Cmp(Lt)`, so the SETcc store is the only thing producing the
    // result. Two bugs had to be fixed: #1 the opcode (`+ 0x10` → `0F 9C` =
    // SETL, not the old `- 0x10` MMX byte), and #3 the MISSING ModRM byte —
    // SETcc is a /digit form, so `0F 9C` without `0xC0` desynced the stream
    // (the next `0F B6` MOVZX was partly consumed as the ModRM) and AL/RAX
    // were never written, so the Cmp returned the first operand (`a`) instead
    // of the 0/1 boolean. With `0F 9C C0` the boolean is correct.
    #[test]
    fn test_lower_cmp_lt_setcc() {
        use crate::ir::{CmpOp, Graph, IrType, Op};

        // Mirror IrBuilder::new node layout: Start, Proj(0)=ctrl, Proj(1)=mem,
        // Param(0), Param(1).
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let b = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        // cmp = (a < b) ? 1 : 0
        let cmp = graph.add(Op::Cmp(CmpOp::Lt), IrType::Int, vec![a, b], None);
        // Return [ctrl, cmp]
        let ret = graph.add(Op::Return, IrType::Void, vec![ctrl, cmp], None);
        graph.exit = ret;

        let schedule = ir_schedule::schedule(&graph);
        let method = lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lower cmp graph");

        // a < b  → 1
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_true = unsafe { method.try_call(&[3, 7]).expect("test JIT call") };
        assert_eq!(r_true, 1, "3 < 7 should set the boolean to 1");
        // a >= b → 0
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_false = unsafe { method.try_call(&[7, 3]).expect("test JIT call") };
        assert_eq!(r_false, 0, "7 < 3 is false → 0");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_eq = unsafe { method.try_call(&[5, 5]).expect("test JIT call") };
        assert_eq!(r_eq, 0, "5 < 5 is false → 0");
    }

    // ── Regression: BUG FIX [jit-irlower #1 + #2] — ternary via IR path ──
    //
    // int f(int a, int b) { return a < b ? 1 : 0; }
    //
    // javac lowers the ternary to a compare-and-branch joined by a phi:
    //   iload_0; iload_1; if_icmpge else; iconst_1; goto end;
    //   else: iconst_0; end: ireturn
    // This exercises the fixes end-to-end: the `Op::Cmp(Ge)` feeding the `If`
    // (#1 + #3 SETcc) and the edge-split parallel copy that materialises the
    // phi value 1/0 at each branch edge (#2). The earlier "always resolves to
    // the else value" symptom was a downstream effect of the SETcc desync (#3):
    // the `If` branched on the first operand instead of the comparison, so it
    // always took the same edge. With the SETcc ModRM fix the phi/branch path
    // is correct.
    #[test]
    fn test_lower_ternary_lt_phi() {
        // PCs:
        //  0: iload_0      1a
        //  1: iload_1      1b
        //  2: if_icmpge 9  a2 00 07   (offset 7 from pc 2 → pc 9)
        //  5: iconst_1     04
        //  6: goto 10      a7 00 04   (offset 4 from pc 6 → pc 10)
        //  9: iconst_0     03
        // 10: ireturn      ac
        let code = [
            0x1a, 0x1b, 0xa2, 0x00, 0x07, 0x04, 0xa7, 0x00, 0x04, 0x03, 0xac, 0, 0,
        ];
        let compiled = compile_via_ir(&code, 11, 2, 2);
        assert!(compiled.is_some(), "ternary should compile via IR path");
        let method = compiled.unwrap();

        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_true = unsafe { method.try_call(&[3, 7]).expect("test JIT call") };
        assert_eq!(r_true, 1, "3 < 7 → 1");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_false = unsafe { method.try_call(&[7, 3]).expect("test JIT call") };
        assert_eq!(r_false, 0, "7 < 3 → 0");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_eq = unsafe { method.try_call(&[5, 5]).expect("test JIT call") };
        assert_eq!(r_eq, 0, "5 == 5, not < → 0");
    }

    // ── Regression: the canonical production SIGSEGV shape — a pure,
    // call-free branchy predicate (e.g. `Modifier.isStatic`). Before the
    // SETcc ModRM fix (#3) this exact shape emitted a stray `SETcc [rdi]`
    // (write through a near-null base) → SIGSEGV, which is why
    // `jit/src/lib.rs` declined branchy call-free methods from the IR path.
    #[test]
    fn test_lower_and_predicate_isstatic_shape() {
        // static boolean f(int m) { return (m & 8) != 0; }
        //  0: iload_0     1a
        //  1: bipush 8    10 08
        //  3: iand        7e
        //  4: ifeq 11     99 00 07   (m&8 == 0 → pc 11)
        //  7: iconst_1    04
        //  8: goto 12     a7 00 04
        // 11: iconst_0    03
        // 12: ireturn     ac
        let code = [
            0x1a, 0x10, 0x08, 0x7e, 0x99, 0x00, 0x07, 0x04, 0xa7, 0x00, 0x04, 0x03, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 13, 1, 1).expect("branchy predicate compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |m: i64| unsafe { cm.try_call(&[m]).expect("call") };
        assert_eq!(f(8), 1, "8 & 8 != 0 → true");
        assert_eq!(f(0), 0, "0 & 8 == 0 → false");
        assert_eq!(f(7), 0, "7 & 8 == 0 → false");
        assert_eq!(f(15), 1, "15 & 8 != 0 → true");
    }

    // ── Regression: a phi that merges non-constant operand values (param a
    // vs param b) across the two branch edges, not just 0/1 constants —
    // exercises the edge-split parallel copy with live values.
    #[test]
    fn test_lower_max_phi_merges_params() {
        // int max(int a, int b) { return a >= b ? a : b; }
        //  0: iload_0     1a
        //  1: iload_1     1b
        //  2: if_icmplt 9 a1 00 07   (a < b → pc 9, return b)
        //  5: iload_0     1a
        //  6: goto 10     a7 00 04
        //  9: iload_1     1b
        // 10: ireturn     ac
        let code = [
            0x1a, 0x1b, 0xa1, 0x00, 0x07, 0x1a, 0xa7, 0x00, 0x04, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 11, 2, 2).expect("max compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let max = |a: i64, b: i64| unsafe { cm.try_call(&[a, b]).expect("call") };
        assert_eq!(max(3, 7), 7, "max(3,7)=7");
        assert_eq!(max(7, 3), 7, "max(7,3)=7");
        assert_eq!(max(5, 5), 5, "max(5,5)=5");
        assert_eq!(max(-2, -9), -2, "max(-2,-9)=-2");
    }

    // ── Gate-flip readiness probe: a COUNTED LOOP (loop-carried phi over a
    // back-edge). If this fails, the IR builder/lowerer does not yet handle
    // loop phis, and branchy call-free methods (which include loops) must NOT
    // be routed to the IR path — i.e. the lib.rs gate cannot be flipped on the
    // SETcc fix alone.
    #[test]
    fn test_lower_counted_loop_sum() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 19
        //  9: iload_1  10: iload_2  11: iadd  12: istore_1
        // 13: iinc 2,1 16: goto 4   19: iload_1 20: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sum = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(sum(5), 10, "0+1+2+3+4 = 10");
        assert_eq!(sum(0), 0, "empty loop = 0");
        assert_eq!(sum(10), 45, "sum 0..9 = 45");
    }

    /// A partially unrolled loop offers **one** OSR entry at its header bci,
    /// and entering through it finishes the loop the interpreter started.
    ///
    /// # The defect
    ///
    /// `emit_osr_entry_stubs` plans one entry per BLOCK and
    /// `ir_osr_entry_addr` resolves one per BCI with `.find()`, so a bci two
    /// blocks claim silently resolves to whichever came first in block order.
    /// Nothing could claim a bci twice until a transform cloned a CONTROL node.
    /// The partial unroller gives every copy its own `If`/`Proj` triple at the
    /// loop test's own bci — it has to, because the pc is also the site key —
    /// so a factor-4 unroll offers four blocks at the header bci and three of
    /// them are mid-group.
    ///
    /// Entering mid-group re-runs the copies after it, which the interpreter
    /// has already run. Measured on `C2PartialUnrollProbe` before the fix: the
    /// probe returned `sum(trip + factor - 1)` on roughly 40% of runs — the
    /// wrong answer and a 3x slowdown arriving together, and both vanishing
    /// under `CRATONVM_JIT_IR_OSR_ENTRY=0`.
    ///
    /// # Why this test is an entry and not a count
    ///
    /// The count alone (`one entry at bci 4`) is what a wrong version can also
    /// have: keeping the first plan rather than the header's gives exactly one
    /// entry too, and it is the mid-group one. So this ENTERS, from a state the
    /// method could not have reached on its own — `i` already at 3 with `s`
    /// holding a value no prefix of this loop produces — and asks for the
    /// answer the interpreter would have finished with. A mid-group door
    /// returns a larger sum, because it runs the copies below it before
    /// reaching the test that should have stopped it.
    #[test]
    fn a_partially_unrolled_loop_has_one_osr_door_and_it_is_the_header() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_PER_COPY_FRAMES", Some("1")),
                ("CRATONVM_JIT_IR_PARTIAL_UNROLL", Some("1")),
                ("CRATONVM_JIT_IR_PARTIAL_UNROLL_FACTOR", Some("4")),
            ],
            || compile_via_ir(&code, 21, 1, 3).expect("the partially unrolled loop compiles"),
        );

        // Cast: the low 32 bits of RAX are this method's `int` result.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sum = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32;
        for n in 0..24i64 {
            let want: i32 = (0..n as i32).sum();
            assert_eq!(sum(n), want, "the ordinary door got sum({n}) wrong");
        }

        let at_header = cm
            .ir_osr_entries
            .iter()
            .filter(|(bci, _, _)| *bci == 4)
            .count();
        assert!(
            at_header <= 1,
            "bci 4 is claimed by {at_header} OSR entries; `ir_osr_entry_addr` \
             resolves one by `.find()`, so the others are unreachable and the \
             one that wins is whichever block order put first",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // Refusing the bci outright is the other correct answer, and the
            // one the filter falls back to when the header cannot be singled
            // out. Nothing else may hold a door.
            assert!(
                cm.ir_osr_entries.is_empty(),
                "the header bci was refused but some other bci kept a door",
            );
            return;
        };

        // Enter as the interpreter would, mid-loop, in a state no prefix of
        // this loop produces: `s = 1000` with `i = 3`. Finishing correctly
        // means adding 3..n-1 and nothing else.
        for n in [4i64, 7, 12, 24] {
            let want: i32 = 1000 + (3..n as i32).sum::<i32>();
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            let got = unsafe { cm.ir_osr_enter(4, 0, &[n, 1000, 3]) }
                .expect("the header door accepts three locals");
            assert_eq!(
                got as i32, want,
                "entered at the header with (s=1000, i=3, n={n}) — a mid-group \
                 door re-runs the copies below it and reads larger",
            );
        }
    }

    /// **The one that matters: enter the loop part-way and finish it.**
    ///
    /// `int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }`, whose
    /// loop header is bci 4. The stub is called the way an OSR trigger would
    /// call it — with an interpreter locals array, not with the method's
    /// arguments — carrying a state the method could never have reached from
    /// its own entry: `n=10, s=100, i=7`. A correct entry finishes the loop
    /// from there and returns `100 + 7 + 8 + 9 = 124`.
    ///
    /// Nothing else proves this. The frame build, the callee-saved saves, the
    /// clean-frame zeroing, the ORDER of that zeroing against the seeding
    /// (`zero_ref_phi_slots` would erase a seeded reference), the parked
    /// locals pointer surviving `emit_frame_record`'s call, the seeding
    /// itself and the jump are six independent chances to be wrong, and every
    /// one of them fails by returning a plausible number.
    #[test]
    fn an_osr_entry_finishes_a_loop_it_did_not_start() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 19
        //  9: iload_1  10: iload_2  11: iadd  12: istore_1
        // 13: iinc 2,1 16: goto 4   19: iload_1 20: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        // The ordinary entry still works, unchanged.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // Not every configuration admits the header (the refusal census
            // says which clause declined). Assert the shape that IS guaranteed:
            // a refusal is silent and total, never a half-emitted stub.
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // The interpreter's locals at bci 4: local 0 = n, 1 = s, 2 = i.
        let locals: [i64; 3] = [10, 100, 7];
        // Through the artifact's own entry point, which is what the VM calls:
        // it re-checks the bci and refuses a locals slice shorter than the stub
        // reads, so the test exercises the admission as well as the code.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&locals),
            Some(124),
            "entering at the header with s=100 i=7 n=10 must run i=7,8,9 and \
             return 100+7+8+9",
        );
        // A second entry, to catch a stub that works once because it left the
        // frame or a callee-saved register in a state the next entry inherits.
        let again: [i64; 3] = [5, 0, 2];
        assert_eq!(entered(&again), Some(9), "i=2,3,4 from s=0 is 2+3+4");
        // And the admission: a locals slice shorter than the stub reads is
        // refused rather than read past.
        assert_eq!(
            entered(&again[..1]),
            None,
            "a short locals snapshot must be refused, not read past",
        );
    }

    /// Round 11 wave 14 (lane osrmerge): the same loop and the same states,
    /// entered through an OPAQUE arm (`CRATONVM_JIT_OSR_OPAQUE_ENTRY`,
    /// `IrBuilder::build_opaque_osr_merge`). The stub now seeds nothing: the
    /// arm's `Op::OsrLocal`s read the parked locals pointer out of the
    /// phi-copy scratch word and its edge copies write the merge's φs, and the
    /// loop's `+ 1` constant is live into the arm, so the stub's constant
    /// seeding runs too. The ordinary door must be unchanged by the arm.
    ///
    /// Round 11 wave 17 (lane tier): CORRECTION. `compile_via_ir` never calls
    /// `IrBuilder::set_osr_opaque_liveness` (only `lib.rs` does), and the
    /// builder reads no environment switch, so this graph has NO opaque arm:
    /// the thread override below changes nothing and the entry exercised is
    /// the ordinary one. Kept as the "the switch alone changes nothing" pin;
    /// the arm is built and entered by
    /// `r11w17_tier_an_opaque_arm_is_entered_and_publishes_its_bci`.
    #[test]
    fn r11w14_an_opaque_osr_entry_finishes_a_loop_it_did_not_start() {
        let _osr = OsrEntryForce::on();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OSR_OPAQUE_ENTRY", Some("1"))],
            || compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR"),
        );
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
        // SAFETY: as above.
        assert_eq!(unsafe { cm.try_call(&[0]).expect("call") }, 0);
        assert_eq!(
            cm.ir_osr_entries
                .iter()
                .filter(|(bci, _, _)| *bci == 4)
                .count(),
            1,
            "one header, one opaque arm, one door: {:?}",
            cm.ir_osr_entries
        );
        let (_addr, needed) = cm
            .ir_osr_entry_addr(4)
            .expect("the opaque arm is the door at the header bci");
        assert_eq!(needed, 3, "the arm reads locals 0..3");
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]` through its arm, and returns the method's `int`.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(entered(&[10, 100, 7]), Some(124), "100+7+8+9");
        assert_eq!(entered(&[5, 0, 2]), Some(9), "2+3+4");
        // Already past the bound: the loop test runs first on the arm path.
        assert_eq!(entered(&[3, 41, 9]), Some(41));
        assert_eq!(
            entered(&[5, 0, 2][..1]),
            None,
            "a short snapshot is refused"
        );
        // No arm was built (see the doc), so no bci is published as opaque.
        assert!(cm.ir_osr_opaque_entry_bcis.is_empty());
    }

    /// Round 11 wave 17 (lane tier): the loop of the test above, built the way
    /// `lib.rs` builds it under `CRATONVM_JIT_OSR_OPAQUE_ENTRY` (the builder is
    /// handed `regalloc::live_locals_per_pc_all`), so the header really gets
    /// an opaque arm. Pins the door's per-entry bit
    /// (`CompiledMethod::ir_osr_opaque_entry_bcis`, read by
    /// `jit_bridge::build_osr_optimizing_artifact`'s handler-reach refusal):
    /// an emitted arm is published, and every published bci is an entry. When
    /// the lowerer emits the arm, entering it must finish the loop.
    #[test]
    fn r11w17_tier_an_opaque_arm_is_entered_and_publishes_its_bci() {
        let _osr = OsrEntryForce::on();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let mut builder = IrBuilder::new(1, 3);
        let (rows, covered, words) =
            crate::regalloc::live_locals_per_pc_all(&code, 21, 1, &[], &[], 3);
        builder.set_osr_opaque_liveness(rows, covered, words);
        let mut graph = builder.build(&code, 21).expect("the loop builds");
        assert!(
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::OsrEntryFlag { header_bci: 4 })),
            "the builder put an opaque arm in front of the header"
        );
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OSR_OPAQUE_ENTRY", Some("1"))],
            || lower(&graph, &schedule, 1, 3, &no_helpers()).expect("the loop lowers"),
        );
        // SAFETY: compiled by this test for one `int` argument, run on this thread.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
        // Every published opaque bci is one of the body's entries.
        for &b in cm.ir_osr_opaque_entry_bcis.iter() {
            assert!(
                cm.ir_osr_entries.iter().any(|&(e, _, _)| e == b),
                "opaque bci {b} is not an entry: {:?}",
                cm.ir_osr_entries
            );
        }
        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // The lowerer may refuse the header (its refusal census says why);
            // then nothing may be published as opaque either.
            assert!(cm.ir_osr_opaque_entry_bcis.is_empty());
            return;
        };
        assert_eq!(
            &*cm.ir_osr_opaque_entry_bcis,
            &[4u32][..],
            "the header's only entry is its opaque arm, and the door must see it"
        );
        // SAFETY: the stub builds and tears down its own frame, reads at most
        // `locals[0..3]`, and returns the method's `int`.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(entered(&[10, 100, 7]), Some(124), "100+7+8+9");
        assert_eq!(entered(&[5, 0, 2]), Some(9), "2+3+4");
        assert_eq!(entered(&[3, 41, 9]), Some(41));
    }

    /// **The entered body may not read a constant nobody wrote.**
    ///
    /// `int f(int n){ int s=0; for(int i=0;i<n;i++){ int r; if(i<3) r=100;
    /// else r=900; s+=r; } return s; }` — a counted loop whose body carries an
    /// in-loop MERGE, and whose two arms are literals.
    ///
    /// That last detail is the whole test. A constant reached only by ALU code
    /// is folded into an immediate at every use, so it needs no frame word; a
    /// constant that flows into a PHI does not get that treatment — the merge
    /// store and `emit_phi_copies` read it from its HOME WORD, which its own
    /// `Op::Const` definition writes once, in the entry block. An OSR stub
    /// jumps past that block, so before 2026-09-09 the entered body read
    /// `[rbp - const_slot]` for `100` and got whatever the previous frame at
    /// that address had left there: a wrong, run-to-run VARYING answer from a
    /// deterministic program (`probes/Min0.java`, 8x800 000: three runs, three
    /// different sums, none of them HotSpot's 5 134 452 788).
    ///
    /// `emit_osr_entry_stubs` re-materialises those constants now. The check
    /// that let them through — the `Op::Const` arm of the live-in test — was
    /// correct to let them through, and wrong to do so without emitting them.
    #[test]
    fn an_osr_entry_seeds_the_constants_its_merge_arms_read() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 35        <- header, bci 4
        //  9: iload_2   10: iconst_3  11: if_icmpge 21
        // 14: sipush 100 17: istore_3 18: goto 25
        // 21: sipush 900 24: istore_3
        // 25: iload_1   26: iload_3   27: iadd     28: istore_1
        // 29: iinc 2,1  32: goto 4    35: iload_1  36: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1d, 0x1c, 0x06, 0xa2, 0x00, 0x0a,
            0x11, 0x00, 0x64, 0x3e, 0xa7, 0x00, 0x07, 0x11, 0x03, 0x84, 0x3e, 0x1b, 0x1d, 0x60,
            0x3c, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xe4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 37, 1, 4).expect("clamp loop compiles via IR");
        // The ordinary entry, which never skipped the constants and was always
        // right. `i < 3` on three iterations, `i >= 3` on two.
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { cm.try_call(&[5]).expect("test JIT call") },
            3 * 100 + 2 * 900,
            "the method-entry door: 100,100,100,900,900",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // Enter at the header in a state the method could not have reached from
        // its own entry: n=10, s=1000, i=4. Every remaining iteration takes the
        // `i >= 3` arm, so the answer is 1000 + 6*900 and it names the `900`
        // constant's home word directly.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&[10, 1000, 4]),
            Some(1000 + 6 * 900),
            "the `900` arm must come from the constant this stub seeded, not \
             from whatever the previous frame left in its word",
        );
        // And the other arm, from a state whose remaining iterations are all
        // `i < 3` — so a stub that seeded one constant and not the other is not
        // reported as a pass.
        assert_eq!(
            entered(&[3, 0, 0]),
            Some(3 * 100),
            "the `100` arm, on its own, from i=0",
        );
        // Both arms in one entry, which is also the shape that would catch a
        // seed emitted INSIDE the loop rather than before it.
        assert_eq!(
            entered(&[6, 7, 1]),
            Some(7 + 2 * 100 + 3 * 900),
            "i=1,2 take the 100 arm and i=3,4,5 take the 900 arm",
        );
    }

    /// Round 15 wave 6 (lane irosr): an OSR entry whose only obstacle is a
    /// post-loop expression of a loop-invariant local -- scheduled EARLY, in
    /// front of the loop, so live across the header with no local naming it --
    /// recomputes it in the stub (`osr_entry_remat_program`) instead of being
    /// refused. The `R15OsrtierAllocLoop.ring` shape at unit scale, `int`
    /// flavour, with a truncating negative division:
    ///
    /// ```java
    /// static int f(int n) { int s = 0;
    ///     for (int i = 0; i < n; i++) s += i;
    ///     return s + (n - 3) * (n - 4) / 2 + (n * 3 - 7) / 4; }
    /// ```
    ///
    /// With `CRATONVM_JIT_IR_OSR_REMAT_INVARIANTS=0` the header has no entry,
    /// which is what proves the fixture exercises the recomputation.
    #[test]
    fn r15w6_irosr_an_osr_entry_recomputes_an_unnamed_int_invariant() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 19        <- header, bci 4
        //  9: iload_1   10: iload_2   11: iadd      12: istore_1
        // 13: iinc 2,1  16: goto 4
        // 19: iload_1   20: iload_0   21: iconst_3  22: isub
        // 23: iload_0   24: iconst_4  25: isub      26: imul
        // 27: iconst_2  28: idiv      29: iadd
        // 30: iload_0   31: iconst_3  32: imul      33: bipush 7
        // 35: isub      36: iconst_4  37: idiv      38: iadd     39: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0x1a, 0x06, 0x64, 0x1a, 0x07, 0x64, 0x68, 0x05,
            0x6c, 0x60, 0x1a, 0x06, 0x68, 0x10, 0x07, 0x64, 0x07, 0x6c, 0x60, 0xac, 0, 0,
        ];
        let reference = |n: i32, s: i32, i: i32| -> i64 {
            let mut s = s;
            let mut i = i;
            while i < n {
                s = s.wrapping_add(i);
                i += 1;
            }
            i64::from(s + (n - 3) * (n - 4) / 2 + (n * 3 - 7) / 4)
        };
        let off = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_OSR_REMAT_INVARIANTS", Some("0"))],
            || compile_via_ir(&code, 40, 1, 3).expect("the loop compiles via IR"),
        );
        assert!(
            off.ir_osr_entry_addr(4).is_none(),
            "kill switch: the fixture must put an unnamed value across the \
             header, or this test proves nothing about the recomputation",
        );
        let cm = compile_via_ir(&code, 40, 1, 3).expect("the loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(
            unsafe { cm.try_call(&[10]).expect("call") },
            reference(10, 0, 0)
        );
        assert!(
            cm.ir_osr_entry_addr(4).is_some(),
            "the header's entry recomputes the invariant instead of refusing",
        );
        let kinds = cm
            .ir_osr_entry_kinds
            .iter()
            .find(|(bci, _)| *bci == 4)
            .map(|(_, k)| k.clone())
            .expect("the entry publishes its kinds");
        assert_eq!(
            kinds.first().copied(),
            Some(b'I'),
            "`n` is read by the stub"
        );
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        for (n, s, i) in [
            (10, 1000, 4),
            (2, 0, 0),
            (1, 5, 0),
            (-5, 7, 0),
            (40000, 3, 39990),
        ] {
            assert_eq!(
                // Cast: the method's `int` result is the low half of RAX.
                entered(&[i64::from(n), i64::from(s), i64::from(i)]).map(|r| i64::from(r as i32)),
                Some(reference(n, s, i)),
                "entered at the header with n={n} s={s} i={i}",
            );
        }
    }

    /// The `long` flavour of the test above, and the exact shape of
    /// `R15OsrtierAllocLoop.ring`'s post-loop check: `(long) (n - 3) * (n - 4)
    /// / 2` (two `i2l`, a 64-bit product past 2^32 for a large `n`, a constant
    /// `ldiv`), plus a 64-bit shift whose count is above 31.
    ///
    /// ```java
    /// static long g(int n) { long s = 0;
    ///     for (int i = 0; i < n; i++) s += i;
    ///     return s + (long) (n - 3) * (n - 4) / 2 + ((long) n << 33); }
    /// ```
    #[test]
    fn r15w6_irosr_an_osr_entry_recomputes_an_unnamed_long_invariant() {
        let _osr = OsrEntryForce::on();
        //  0: lconst_0   1: lstore_1   2: iconst_0   3: istore_3
        //  4: iload_3    5: iload_0    6: if_icmpge 20        <- header, bci 4
        //  9: lload_1   10: iload_3   11: i2l       12: ladd     13: lstore_1
        // 14: iinc 3,1  17: goto 4
        // 20: lload_1   21: iload_0   22: iconst_3  23: isub     24: i2l
        // 25: iload_0   26: iconst_4  27: isub      28: i2l      29: lmul
        // 30: iconst_2  31: i2l       32: ldiv      33: ladd
        // 34: iload_0   35: i2l       36: bipush 33 38: lshl     39: ladd
        // 40: lreturn
        let code = [
            0x09, 0x40, 0x03, 0x3e, 0x1d, 0x1a, 0xa2, 0x00, 0x0e, 0x1f, 0x1d, 0x85, 0x61, 0x40,
            0x84, 0x03, 0x01, 0xa7, 0xff, 0xf3, 0x1f, 0x1a, 0x06, 0x64, 0x85, 0x1a, 0x07, 0x64,
            0x85, 0x69, 0x05, 0x85, 0x6d, 0x61, 0x1a, 0x85, 0x10, 0x21, 0x79, 0x61, 0xad, 0, 0,
        ];
        let reference = |n: i64, s: i64, i: i64| -> i64 {
            let mut s = s;
            let mut i = i;
            while i < n {
                s = s.wrapping_add(i);
                i += 1;
            }
            s.wrapping_add((n - 3) * (n - 4) / 2).wrapping_add(n << 33)
        };
        let off = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_OSR_REMAT_INVARIANTS", Some("0"))],
            || compile_via_ir(&code, 41, 1, 4).expect("the loop compiles via IR"),
        );
        assert!(
            off.ir_osr_entry_addr(4).is_none(),
            "kill switch: the fixture must put an unnamed value across the \
             header, or this test proves nothing about the recomputation",
        );
        let cm = compile_via_ir(&code, 41, 1, 4).expect("the loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(
            unsafe { cm.try_call(&[10]).expect("call") },
            reference(10, 0, 0)
        );
        assert!(
            cm.ir_osr_entry_addr(4).is_some(),
            "the header's entry recomputes the invariant instead of refusing",
        );
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..4]` (a `long` in slot 1, slot 2 its unused half), and
        // returns the method's `long` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        for (n, s, i) in [(10, 1000, 4), (-5, 7, 0), (3, 0, 1), (100_000, 0, 99_999)] {
            assert_eq!(
                entered(&[n, s, 0, i]),
                Some(reference(n, s, i)),
                "entered at the header with n={n} s={s} i={i}",
            );
        }
    }

    /// Round 15 wave 6 (lane irosr2, IRO-4): an OSR entry whose only
    /// obstacle is a loop-invariant GUARD CONDITION -- the division's
    /// `Cmp(Ne, d, 0)`, scheduled in front of the loop while its `Op::Guard`
    /// stays inside it -- recomputes the compare in the stub instead of being
    /// refused (the `n109 Some(Cmp(Eq))` refusal of the w5a census).
    ///
    /// ```java
    /// static int f(int n, int d) { int s = 0;
    ///     for (int i = 0; i < n; i++) s += i / d;
    ///     return s; }
    /// ```
    ///
    /// `CRATONVM_JIT_IR_OSR_REMAT_COMPARES=0` must leave the header without an
    /// entry, which is what proves the fixture puts the compare across it.
    #[test]
    fn r15w6_irosr2_an_osr_entry_recomputes_an_unnamed_guard_compare() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_2   2: iconst_0   3: istore_3
        //  4: iload_3    5: iload_0    6: if_icmpge 21        <- header, bci 4
        //  9: iload_2   10: iload_3   11: iload_1   12: idiv   13: iadd
        // 14: istore_2  15: iinc 3,1  18: goto 4
        // 21: iload_2   22: ireturn
        let code = [
            0x03, 0x3d, 0x03, 0x3e, 0x1d, 0x1a, 0xa2, 0x00, 0x0f, 0x1c, 0x1d, 0x1b, 0x6c, 0x60,
            0x3d, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf2, 0x1c, 0xac, 0, 0,
        ];
        let reference = |n: i32, d: i32, s: i32, i: i32| -> i64 {
            let mut s = s;
            let mut i = i;
            while i < n {
                s = s.wrapping_add(i.wrapping_div(d));
                i += 1;
            }
            i64::from(s)
        };
        let off = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_OSR_REMAT_COMPARES", Some("0"))],
            || compile_via_ir(&code, 23, 2, 4).expect("the loop compiles via IR"),
        );
        assert!(
            off.ir_osr_entry_addr(4).is_none(),
            "kill switch: the fixture must put the unnamed guard compare across \
             the header, or this test proves nothing about the recomputation",
        );
        let cm = compile_via_ir(&code, 23, 2, 4).expect("the loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(
            unsafe { cm.try_call(&[10, 3]).expect("call") },
            reference(10, 3, 0, 0)
        );
        assert!(
            cm.ir_osr_entry_addr(4).is_some(),
            "the header's entry recomputes the compare instead of refusing",
        );
        let kinds = cm
            .ir_osr_entry_kinds
            .iter()
            .find(|(bci, _)| *bci == 4)
            .map(|(_, k)| k.clone())
            .expect("the entry publishes its kinds");
        assert_eq!(kinds.get(1).copied(), Some(b'I'), "`d` is read by the stub");
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..4]`, and returns the method's `int` result in RAX. No
        // case divides by zero, so the guard never leaves the body.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        for (n, d, s, i) in [
            (10, 3, 1000, 4),
            (100, -7, 0, 0),
            (1, 5, 9, 0),
            (50_000, 13, 0, 49_990),
        ] {
            assert_eq!(
                // Cast: the method's `int` result is the low half of RAX.
                entered(&[i64::from(n), i64::from(d), i64::from(s), i64::from(i)])
                    .map(|r| i64::from(r as i32)),
                Some(reference(n, d, s, i)),
                "entered at the header with n={n} d={d} s={s} i={i}",
            );
        }
    }

    /// OD16-4 (round 16, lane osrdoor): a shape row names the variant without
    /// its fields, and the census line carries every row it was given.
    #[test]
    fn r16_osrdoor_the_osr_entry_census_keys_and_prints_its_rows() {
        assert_eq!(
            osr_entry_census_shape_key(&Op::ExactClassIs { class_id: 64 }, IrType::Int),
            "unnamed:ExactClassIs:Int",
        );
        assert_eq!(
            osr_entry_census_shape_key(&Op::Phi, IrType::Memory),
            "unnamed:Phi:Memory"
        );
        assert_eq!(
            osr_entry_census_shape_key(&Op::Cmp(CmpOp::Eq), IrType::Int),
            "unnamed:Cmp:Int"
        );
        // Process-wide and shared with every other compile in this binary, so
        // only growth is asserted.
        note_osr_entry_census("r16-osrdoor-test-row");
        note_osr_entry_census_n("r16-osrdoor-test-row", 0);
        let line = osr_entry_census_line().expect("a row was noted");
        assert!(line.starts_with("[cratonvm] OSR entry census: "), "{line}");
        assert!(line.contains("r16-osrdoor-test-row="), "{line}");
    }

    /// Round 16 (lane osrdoor): the decision of
    /// `osr_entry_value_needs_no_seed`, rule by rule, with each switch alone.
    #[test]
    fn r16_osrdoor_which_unnamed_values_an_osr_entry_owes_no_seed() {
        let mut g = Graph::empty(8);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let merge = g.add(Op::Merge, IrType::Control, vec![start], Some(4));
        let mem_phi = g.add(Op::Phi, IrType::Memory, vec![merge, start], Some(4));
        let long_phi = g.add(Op::Phi, IrType::Long, vec![merge, start], Some(4));
        let ref_phi = g.add(Op::Phi, IrType::Ref, vec![merge, start], Some(4));
        let add = g.add(Op::Add, IrType::Int, vec![], Some(9));
        // `f(value, in the entry block, dataflow answer, tokens switch, dataflow switch)`.
        let f = |id: NodeId, own: bool, live_in: fn() -> Option<bool>, tok: bool, flow: bool| {
            Lowerer::osr_entry_value_needs_no_seed_by(
                &g.nodes[id as usize],
                own,
                live_in,
                tok,
                flow,
            )
        };
        let dead: fn() -> Option<bool> = || Some(false);
        let live: fn() -> Option<bool> = || Some(true);
        let unknown: fn() -> Option<bool> = || None;
        // Both switches off: nothing is excused, whatever the dataflow says.
        for id in [mem_phi, long_phi, ref_phi, add] {
            assert!(!f(id, false, dead, false, false));
        }
        // Memory tokens: a memory φ, even the entry block's own and even
        // "live"; never a value.
        assert!(f(mem_phi, true, live, true, false));
        assert!(!f(long_phi, false, dead, true, false));
        assert!(!f(add, false, dead, true, false));
        // Dataflow: a primitive the dataflow calls dead, and only that.
        assert!(f(long_phi, false, dead, false, true));
        assert!(f(add, false, dead, false, true));
        assert!(!f(add, false, live, false, true));
        assert!(
            !f(add, false, unknown, false, true),
            "an unconverged model is not a verdict of death",
        );
        assert!(
            !f(long_phi, true, dead, false, true),
            "a φ of the entry block is written by the edge copies the stub skips",
        );
        assert!(
            !f(ref_phi, false, dead, false, true),
            "a reference is never excused: a safepoint map may publish its word",
        );
        assert!(
            !f(mem_phi, false, dead, false, true),
            "a memory φ is the token rule's, not the dataflow rule's",
        );
    }

    /// Round 16 (lane osrdoor): an INNER loop's header is entered although an
    /// OUTER loop's φ -- `s`'s outer φ, the inner φ's forward input and the
    /// method's return value -- has an interval across it that no local
    /// names. The phi-edge interference rule stretches that interval to the
    /// outer latch; the converged dataflow says no read of it is reachable
    /// from the inner header before the outer back edge rewrites it
    /// (`R16ChainGetNode.run` bci 18 at unit scale):
    ///
    /// ```java
    /// static int f(int n) { int s = 0;
    ///     for (int r = 0; r < n; r++)
    ///         for (int i = 0; i < n; i++) s += i;
    ///     return s; }
    /// ```
    ///
    /// Without `CRATONVM_JIT_IR_OSR_DATAFLOW_LIVE_IN` the inner header has no
    /// entry, which is what proves the fixture puts the outer φ across it.
    #[test]
    fn r16_osrdoor_an_inner_header_entry_owes_no_seed_to_an_outer_phi() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 32        <- outer header, bci 4
        //  9: iconst_0  10: istore_3
        // 11: iload_3   12: iload_0   13: if_icmpge 26        <- inner header, bci 11
        // 16: iload_1   17: iload_3   18: iadd      19: istore_1
        // 20: iinc 3,1  23: goto 11
        // 26: iinc 2,1  29: goto 4
        // 32: iload_1   33: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let reference = |n: i32, s: i32, r: i32, i: i32| -> i64 {
            let (mut s, mut r, mut i) = (s, r, i);
            loop {
                while i < n {
                    s = s.wrapping_add(i);
                    i += 1;
                }
                r += 1;
                if r >= n {
                    break;
                }
                i = 0;
            }
            i64::from(s)
        };
        let off = compile_via_ir(&code, 34, 1, 4).expect("the nest compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let first = reference(7, 0, 0, 0);
        assert_eq!(unsafe { off.try_call(&[7]).expect("call") }, first);
        assert!(
            off.ir_osr_entry_addr(11).is_none(),
            "switch off: the fixture must put the outer φ across the inner \
             header, or this test proves nothing about the dataflow excuse",
        );
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_OSR_DATAFLOW_LIVE_IN", Some("1"))],
            || compile_via_ir(&code, 34, 1, 4).expect("the nest compiles via IR"),
        );
        // SAFETY: as above.
        assert_eq!(unsafe { cm.try_call(&[7]).expect("call") }, first);
        assert!(
            cm.ir_osr_entry_addr(11).is_some(),
            "the inner header's entry owes the outer φ no seed",
        );
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..4]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(11, 0, l) };
        for (n, s, r, i) in [
            (7, 1000, 2, 3),
            (5, 0, 4, 0),
            (3, -9, 0, 3),
            (300, 11, 298, 150),
        ] {
            assert_eq!(
                // Cast: the method's `int` result is the low half of RAX.
                entered(&[i64::from(n), i64::from(s), i64::from(r), i64::from(i)])
                    .map(|v| i64::from(v as i32)),
                Some(reference(n, s, r, i)),
                "entered at the inner header with n={n} s={s} r={r} i={i}",
            );
        }
    }

    /// Round 16 wave 14 (lane osrir): a refusal the dataflow excuse would lift
    /// is counted as such in the exit census, with the switch OFF -- the
    /// fixture of `r16_osrdoor_an_inner_header_entry_owes_no_seed_to_an_outer_phi`,
    /// whose inner header (bci 11) is refused only for the outer φ. The
    /// census is process-wide, so only the row's presence is asserted.
    #[test]
    fn r16w14_osrir_a_refused_entry_names_the_excuse_that_would_admit_it() {
        let _osr = OsrEntryForce::on();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let off = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_OSR_DATAFLOW_LIVE_IN", Some("0")),
                ("CRATONVM_JIT_IR_OSR_EXCUSE_MEMORY_TOKENS", Some("0")),
            ],
            || compile_via_ir(&code, 34, 1, 4).expect("the nest compiles via IR"),
        );
        assert!(
            off.ir_osr_entry_addr(11).is_none(),
            "switches off: the inner header must be refused, or this proves nothing",
        );
        let line = osr_entry_census_line().expect("the refusal was counted");
        assert!(
            line.contains("would-admit:dataflow-live-in="),
            "the census names the excuse that lifts the refusal: {line}",
        );
    }

    /// **The entered body may not read an XMM register nobody wrote.**
    ///
    /// The constants defect above, in the other register file, and reached
    /// without a merge, a literal arm or a splice:
    ///
    /// ```java
    /// int f(int n) { double a = (double) n; int s = 0;
    ///                for (int i = 0; i < n; i++) {
    ///                    s += (int) (a + i);
    ///                    s += (int) (a + s);
    ///                }
    ///                return s; }
    /// ```
    ///
    /// `a` is an ordinary JVM local. It is not a phi -- nothing reassigns it
    /// in the loop -- so at the header the snapshot names the `Op::I2D` that
    /// computed it, the eligibility test is satisfied, and the stub seeds it.
    /// Seeded into its HOME WORD, which was the whole of the seeding: and an
    /// FP definition does not stop at the home word. `fp_store_value` copies
    /// the result into the value's assigned XMM and marks it resident, after
    /// which every reader in the body takes the REGISTER (`fp_load_value` ->
    /// `resident_xmm`) and never looks at the frame again. The stub jumps past
    /// that definition, so the body read whatever floating-point register the
    /// previous frame happened to leave behind.
    ///
    /// **Observable on Windows only, and that is a property of the defect
    /// rather than of the test.** A value is register-resident across a
    /// safepoint only if its register survives one, and `IR_PROLOGUE_SAVED` --
    /// the XMMs this prologue saves -- is `[6, 7]` on Win64 and EMPTY on
    /// System V, where the ABI makes every XMM volatile. So on Linux every
    /// register in `IR_LINEAR_SCAN` is caller-saved, an FP value live across
    /// the safepoint at a loop header is split rather than promoted, and there
    /// is no stale register for the entry to leave behind. The byte scan below
    /// is what establishes which of the two a given run is, instead of letting
    /// System V report a pass it did not earn.
    ///
    /// Three details of the fixture are load-bearing, and every one of them
    /// was found by watching an earlier fixture fail to reproduce:
    ///
    /// * `a` read TWICE, because residency is `static_uses >= 2`
    ///   (`ir_residency_pays_here`, whose loop weighting is default-off). A
    ///   value read once per trip gets no register, stays in its frame word,
    ///   and is seeded correctly by the unfixed emitter.
    /// * the two reads adding `i` and `s`, not `i` twice: GVN merges two
    ///   `(double) i` conversions into ONE node with two uses of its own, and
    ///   that one -- defined in the loop, with the shorter range -- takes the
    ///   register instead of `a`.
    /// * neither read loop-invariant, because LICM hoists an invariant
    ///   `(int) a` out of the loop and the hoisted `Op::D2I` is then an
    ///   unnamed integer live across the header, which the eligibility test
    ///   refuses outright -- a test that never enters, passing for the wrong
    ///   reason.
    ///
    /// The byte scan below is what turned each of those from a false pass into
    /// a failure, and it is why this test is worth more than its assertion.
    #[test]
    fn an_osr_entry_seeds_the_fp_registers_its_body_reads() {
        let _osr = OsrEntryForce::on();
        //  0: iload_0  1: i2d  2: dstore_1        (a = (double) n)
        //  3: iconst_0 4: istore_3                (s = 0)
        //  5: iconst_0 6: istore 4                (i = 0)
        //  8: iload 4 10: iload_0 11: if_icmpge 37   <- header, bci 8
        // 14: iload_3 15: dload_1 16: iload 4 18: i2d 19: dadd 20: d2i
        // 21: iadd    22: istore_3
        // 23: iload_3 24: dload_1 25: iload_3 26: i2d 27: dadd 28: d2i
        // 29: iadd    30: istore_3
        // 31: iinc 4,1 34: goto 8  37: iload_3  38: ireturn
        let code = [
            0x1a, 0x87, 0x48, 0x03, 0x3e, 0x03, 0x36, 0x04, 0x15, 0x04, 0x1a, 0xa2, 0x00, 0x1a,
            0x1d, 0x27, 0x15, 0x04, 0x87, 0x63, 0x8e, 0x60, 0x3e, 0x1d, 0x27, 0x1d, 0x87, 0x63,
            0x8e, 0x60, 0x3e, 0x84, 0x04, 0x01, 0xa7, 0xff, 0xe6, 0x1d, 0xac, 0, 0,
        ];
        // The bytecode's own arithmetic, in Rust, so the expected answers are
        // derived rather than hand-computed: `d2i` truncates toward zero and
        // `iadd` is 32-bit, which `as i32` and `wrapping_add` reproduce.
        let expect = |n: i32, a: f64, s0: i32, i0: i32| -> i32 {
            let (mut s, mut i) = (s0, i0);
            while i < n {
                s = s.wrapping_add((a + f64::from(i)) as i32);
                s = s.wrapping_add((a + f64::from(s)) as i32);
                i += 1;
            }
            s
        };

        let cm = compile_via_ir(&code, 39, 1, 5).expect("the FP-invariant loop compiles via IR");
        // The ordinary entry, which never skipped the definition and was always
        // right. `a` is `(double) n` here, because that is what the method's
        // own prologue computes.
        // Cast: both doors hand back RAX, whose low 32 bits are this method's
        // `int` result; the upper half is not sign-extended, so the comparison
        // is made on the 32 bits the body actually wrote.
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { cm.try_call(&[5]).expect("test JIT call") } as i32,
            expect(5, 5.0, 0, 0),
            "the method-entry door",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(8) else {
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // Cast: as above.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(8, 0, l) }.map(|v| v as i32);
        // Enter at the header in a state the method could not have reached
        // from its own entry -- `a` is 2.5, which `(double) n` never produces,
        // so a stub that leaves the register alone cannot accidentally hold
        // the right bits. The fraction also makes `d2i`'s truncation part of
        // the answer, so a register holding SOME double is not enough either.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..5]`, and returns the method's `int` result in RAX.
        // Cast: an IEEE-754 bit pattern into the locals array's word.
        let locals: [i64; 5] = [6, 2.5f64.to_bits() as i64, 0, 3, 2];
        assert_eq!(
            entered(&locals),
            Some(expect(6, 2.5, 3, 2)),
            "`a` must come from the XMM this stub seeded, not from whatever \
             floating-point register the previous frame left behind",
        );
        // A second entry, with a DIFFERENT `a`, from a frame the first entry
        // has just used: a stub that seeds the register once, or that passes
        // because the right value happened to still be there, fails here.
        // Cast: as above.
        let again: [i64; 5] = [4, (-1.75f64).to_bits() as i64, 0, 0, 0];
        assert_eq!(
            entered(&again),
            Some(expect(4, -1.75, 0, 0)),
            "a second entry must re-seed the register rather than inherit it",
        );

        // The vacuity guard, LAST: the two entries above are the claim, and
        // this is the evidence that they were asked anything at all. If the
        // allocator gave `a` no register there is no stale register to read,
        // the body loads it from its frame word, and both entries pass on the
        // unfixed emitter too. This graph builds no `Op::ConstF` and the
        // stub's other work is integer stores, so a MOVSD inside the stub can
        // only be the FP publish this test exists to check.
        let bytes = cm.code_bytes();
        let (_, stub_off, _) = *cm
            .ir_osr_entries
            .first()
            .expect("the header entry was found above");
        assert_eq!(cm.ir_osr_entries.len(), 1, "one entry, so one stub to scan");
        let movsd = |b: &[u8]| b.windows(3).filter(|w| *w == [0xF2, 0x0F, 0x10]).count();
        let (in_body, in_stub) = (
            movsd(&bytes[..stub_off as usize]),
            movsd(&bytes[stub_off as usize..]),
        );
        if IR_LOWER_SAVED_XMMS.is_empty() && !ir_poll_preserves_fp() {
            // System V with the back-edge poll still clobbering the XMM bank:
            // every register in `IR_LINEAR_SCAN` is caller-saved, so an FP
            // value live across the header's poll is split rather than
            // promoted and there is no stale register for the entry to leave
            // behind.
            assert_eq!(
                in_stub, 0,
                "an FP value is register-resident across a clobbering back-edge \
                 poll ({in_body} MOVSD in the body)",
            );
            return;
        }
        if IR_LOWER_SAVED_XMMS.is_empty() && in_stub == 0 {
            // System V since round 11 wave 6: the poll reloads the caller-saved
            // file (`ir_poll_preserves_fp`), so `a` MAY now hold a register
            // across the header, but any call the loop makes still splits it.
            // Both are legal; the two entries above were asked either way.
            return;
        }
        assert!(
            in_stub > 0,
            "the stub publishes no XMM register ({in_body} MOVSD in the body, \
             {in_stub} in the stub): the allocator gave `a` none, so this \
             fixture no longer reproduces the defect it was written for and \
             must be repaired rather than believed",
        );
    }

    /// Interpreter round i1 wave 10: every optimizing OSR entry publishes the
    /// kind each seeded local is read as, and `ir_osr_entry_kind_mismatch`
    /// refuses an offer whose tags disagree. The fixture is the loop above:
    /// `n` (int, 0), `a` (double, 1-2), `s` (int, 3), `i` (int, 4).
    #[test]
    fn an_osr_entry_publishes_the_kind_of_every_local_it_seeds() {
        use cratonvm_types::{VTAG_DOUBLE, VTAG_INT, VTAG_NULL, VTAG_OBJECT, VTAG_UNINIT};
        let _osr = OsrEntryForce::on();
        let code = [
            0x1a, 0x87, 0x48, 0x03, 0x3e, 0x03, 0x36, 0x04, 0x15, 0x04, 0x1a, 0xa2, 0x00, 0x1a,
            0x1d, 0x27, 0x15, 0x04, 0x87, 0x63, 0x8e, 0x60, 0x3e, 0x1d, 0x27, 0x1d, 0x87, 0x63,
            0x8e, 0x60, 0x3e, 0x84, 0x04, 0x01, 0xa7, 0xff, 0xe6, 0x1d, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 39, 1, 5).expect("the FP-invariant loop compiles via IR");
        assert_eq!(
            cm.ir_osr_entries.len(),
            cm.ir_osr_entry_kinds.len(),
            "one kind row per entry"
        );
        for &(bci, _, needed) in &cm.ir_osr_entries {
            let row = cm
                .ir_osr_entry_kinds
                .iter()
                .find(|(b, _)| *b == bci)
                .map(|(_, k)| k);
            assert_eq!(row.map(|k| k.len()), Some(needed as usize), "bci {bci}");
        }
        let Some((_addr, needed)) = cm.ir_osr_entry_addr(8) else {
            return; // the header was refused; the rows above are the claim
        };
        let (_, kinds) = cm
            .ir_osr_entry_kinds
            .iter()
            .find(|(b, _)| *b == 8)
            .expect("an entry at 8 has a kind row");
        // `a` is a double read from local 1, and local 2 is its reserved half.
        if needed >= 3 && kinds[1] != 0 {
            assert_eq!(kinds[1], b'D');
            assert_eq!(kinds[2], 0, "the high half of a double is not seeded");
        }
        if needed >= 5 && kinds[4] != 0 {
            assert_eq!(kinds[4], b'I');
        }
        let good = [VTAG_INT, VTAG_DOUBLE, VTAG_UNINIT, VTAG_INT, VTAG_INT];
        assert_eq!(
            cm.ir_osr_entry_kind_mismatch(8, |i| good.get(i).copied()),
            None
        );
        // Any seeded local offered as a reference is refused, at that local.
        for (i, &kind) in kinds.iter().enumerate() {
            if kind == 0 || kind == b'L' {
                continue;
            }
            let mut bad = good;
            bad[i] = if i % 2 == 0 { VTAG_OBJECT } else { VTAG_NULL };
            assert_eq!(
                cm.ir_osr_entry_kind_mismatch(8, |j| bad.get(j).copied()),
                Some(i),
                "local {i} ({}) offered as a reference",
                kind as char
            );
        }
        // A frame shorter than the row is refused rather than read past.
        if kinds.iter().any(|&k| k != 0) {
            assert!(cm.ir_osr_entry_kind_mismatch(8, |_| None).is_some());
        }
        // No row, no constraint.
        assert_eq!(cm.ir_osr_entry_kind_mismatch(9999, |_| None), None);
    }

    /// The kind vocabulary against the interpreter's tags.
    #[test]
    fn the_osr_slot_kinds_admit_exactly_their_own_tags() {
        use crate::ir::IrType;
        use cratonvm_types::{
            VTAG_DOUBLE, VTAG_FLOAT, VTAG_INT, VTAG_LONG, VTAG_NULL, VTAG_OBJECT, VTAG_RETADDR,
            VTAG_UNINIT,
        };
        let admits = crate::ir_osr_slot_kind_admits;
        let kind = crate::ir_osr_slot_kind;
        assert!(admits(kind(IrType::Ref), VTAG_OBJECT));
        assert!(admits(kind(IrType::Ref), VTAG_NULL));
        assert!(!admits(kind(IrType::Ref), VTAG_INT));
        assert!(!admits(kind(IrType::Ref), VTAG_LONG));
        assert!(!admits(kind(IrType::Ref), VTAG_UNINIT));
        assert!(admits(kind(IrType::Int), VTAG_INT));
        assert!(!admits(kind(IrType::Int), VTAG_NULL));
        assert!(admits(kind(IrType::Long), VTAG_LONG));
        assert!(!admits(kind(IrType::Long), VTAG_DOUBLE));
        assert!(admits(kind(IrType::Float), VTAG_FLOAT));
        assert!(!admits(kind(IrType::Float), VTAG_INT));
        assert!(admits(kind(IrType::Double), VTAG_DOUBLE));
        assert!(!admits(kind(IrType::Double), VTAG_LONG));
        for tag in [VTAG_INT, VTAG_OBJECT, VTAG_UNINIT, VTAG_RETADDR] {
            assert!(admits(kind(IrType::Void), tag), "no constraint");
        }
        for k in [b'I', b'J', b'F', b'D', b'L'] {
            assert!(!admits(k, VTAG_RETADDR));
        }
    }

    /// **Every shape the eligibility test excuses must have an emission arm.**
    ///
    /// The mechanical half of `osr_entry_can_produce`'s doc comment. The
    /// defect it was extracted from was not a wrong predicate -- excusing a
    /// constant is right -- but two lists in two places that had to agree and
    /// were only checked by hand. This checks them.
    ///
    /// Textual, in the idiom of
    /// `every_droppable_op_writes_its_home_once_through_store_rax` above: the
    /// alternative is a runtime scan, and there is nothing to scan at runtime
    /// -- the failure is a shape that never gets emitted, which is precisely
    /// the case that produces no node to look at.
    #[test]
    fn an_osr_entry_emits_every_shape_its_eligibility_test_excuses() {
        let src = include_str!("ir_lower.rs");
        // The FIRST occurrence of each needle is the code; the second is this
        // test quoting it.
        let excused_src = src
            .split("fn osr_entry_can_produce(op: &Op) -> bool {")
            .nth(1)
            .expect("`osr_entry_can_produce` is in this file")
            .split("\n    }")
            .next()
            .expect("the function ends");
        let mut excused = std::collections::BTreeSet::new();
        collect_op_names(excused_src, &mut excused);
        assert!(
            !excused.is_empty(),
            "the predicate scan found nothing -- `osr_entry_can_produce` \
             changed shape and this test would now pass vacuously",
        );

        let emitted_src = src
            .split("let (bits, is_fp, is_double) = match self.graph.nodes.get(id as usize) {")
            .nth(1)
            .expect("the seed emission is in this file")
            .split("None => continue,")
            .next()
            .expect("the match ends");
        let mut emitted = std::collections::BTreeSet::new();
        collect_op_names(emitted_src, &mut emitted);

        assert_eq!(
            excused, emitted,
            "the OSR entry excuses {excused:?} from being seeded but emits \
             {emitted:?}. A shape excused and not emitted is a value the \
             entered body reads out of a frame word nothing wrote -- see \
             `an_osr_entry_seeds_the_constants_its_merge_arms_read`.",
        );
    }

    /// The page's own reproducer, at unit scale: `Min1.clamp` spliced into a
    /// counted loop, entered through BOTH doors.
    ///
    /// `int clamp(int v){ int r; if (v < 100) r = 100; else r = v; return r; }`
    /// relocated to a combined-buffer offset, which is what
    /// `ir-splice-branch` admits and what `SPLICED_MERGE_SEEN` used to bar from
    /// the optimizing OSR door. The bar is off; this is what has to hold
    /// without it.
    ///
    /// The OSR half is the half that failed. Its two arms are LITERALS, so the
    /// merge store reads them from their home words, and the entry stub jumps
    /// past the block that writes those words — see
    /// `an_osr_entry_seeds_the_constants_its_merge_arms_read` for the same
    /// defect with nothing spliced at all.
    fn splice_branch_fixture() -> (Vec<u8>, usize, HashMap<usize, crate::ir::IrInlineSite>) {
        // Caller: `int f(int n){ int s=0; for(int i=0;i<n;i++) s += clamp(i);
        //          return s; }`   locals: 0=n, 1=s, 2=i
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 22        <- header, bci 4
        //  9: iload_1   10: iload_2   11: invokestatic #1   14: iadd
        // 15: istore_1  16: iinc 2,1  19: goto 4
        // 22: iload_1   23: ireturn
        let caller = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x10, 0x1b, 0x1c, 0xb8, 0x00, 0x01,
            0x60, 0x3c, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xf1, 0x1b, 0xac,
        ];
        const CALLER_LEN: usize = 24;
        // Callee: locals 0=v, 1=r
        //  0: iload_0    1: sipush 100   4: if_icmpge 14
        //  7: sipush 100 10: istore_1   11: goto 16
        // 14: iload_0   15: istore_1
        // 16: iload_1   17: ireturn                       <- single trailing return
        let callee = [
            0x1a, 0x11, 0x00, 0x64, 0xa2, 0x00, 0x0a, 0x11, 0x00, 0x64, 0x3c, 0xa7, 0x00, 0x05,
            0x1a, 0x3c, 0x1b, 0xac,
        ];
        let mut combined = caller.to_vec();
        let base = combined.len();
        combined.extend_from_slice(&callee);
        // The two trailing sentinel bytes every method's code carries.
        combined.extend_from_slice(&[0, 0]);
        let mut sites = HashMap::new();
        sites.insert(
            11,
            crate::ir::IrInlineSite {
                base,
                code_len: callee.len(),
                num_args: 1,
                max_locals: 2,
                arg_local_slots: vec![0],
                returns_value: true,
                receiver_is_arg0: false,
                method_key: "P.clamp:(I)I".to_string(),
                class_id: 0,
            },
        );
        (combined, CALLER_LEN, sites)
    }

    /// A callee whose loop ECJ rotated, spliced into its caller: built, optimized,
    /// lowered and run. `f(n) = sumTo(n) + 1`, `sumTo(n) = 0 + 1 + … + (n-1)`.
    #[test]
    fn a_spliced_callee_with_a_rotated_loop_runs() {
        let caller = [0x1a, 0xb8, 0x00, 0x01, 0x04, 0x60, 0xac];
        // sumTo: 0: s = 0; 2: i = 0; 4: goto 14; 7: s += i; 11: iinc 2, 1;
        // 14: iload_2; 15: iload_0; 16: if_icmplt 7; 19: iload_1; 20: ireturn
        let callee = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x0a, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01,
            0x1c, 0x1a, 0xa1, 0xff, 0xf7, 0x1b, 0xac,
        ];
        let mut combined = caller.to_vec();
        let base = combined.len();
        combined.extend_from_slice(&callee);
        combined.extend_from_slice(&[0, 0]);
        let mut sites = HashMap::new();
        sites.insert(
            1,
            crate::ir::IrInlineSite {
                base,
                code_len: callee.len(),
                num_args: 1,
                max_locals: 3,
                arg_local_slots: vec![0],
                returns_value: true,
                receiver_is_arg0: false,
                method_key: "P.sumTo:(I)I".to_string(),
                class_id: 0,
            },
        );
        let mut builder = IrBuilder::new(1, 1);
        builder.set_inline_sites(sites);
        let mut graph = builder
            .build(&combined, caller.len())
            .expect("a callee body with a rotated loop must splice");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("the graph must lower");
        // SAFETY: the body was compiled by this test for one `int` argument and runs on this thread with no helper calls.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("test JIT call") };
        assert_eq!(f(0), 1, "an empty loop sums to zero");
        assert_eq!(f(1), 1);
        assert_eq!(f(5), 11, "0+1+2+3+4, plus one");
        assert_eq!(f(100), 4951);
    }

    #[test]
    fn a_spliced_body_may_branch_and_its_phi_carries_a_combined_pc() {
        let (combined, caller_len, sites) = splice_branch_fixture();
        let mut builder = IrBuilder::new(1, 3);
        builder.set_inline_sites(sites);
        let graph = builder
            .build(&combined, caller_len)
            .expect("a spliced body with a forward branch must build");
        let spliced_phi = graph
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::Phi) && n.bytecode_pc.is_some_and(|pc| pc >= caller_len));
        assert!(
            spliced_phi,
            "the callee's if/else must produce a phi, and it must carry the \
             COMBINED-buffer pc every node in a relocated region carries",
        );
        // And no `Op::Call` survives at the spliced site: a body that was
        // spliced AND dispatched would run twice.
        assert!(
            !graph.nodes.iter().any(|n| matches!(n.op, Op::Call { .. })),
            "the spliced call must be gone, not emitted alongside the body",
        );
    }

    #[test]
    fn a_spliced_branchy_body_runs_from_both_doors() {
        let _osr = OsrEntryForce::on();
        let (combined, caller_len, sites) = splice_branch_fixture();
        let mut builder = IrBuilder::new(1, 3);
        builder.set_inline_sites(sites);
        let mut graph = builder
            .build(&combined, caller_len)
            .expect("a spliced body with a forward branch must build");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm =
            lower(&graph, &schedule, 1, 3, &no_helpers()).expect("the spliced graph must lower");

        // The method-entry door. `clamp(i)` is 100 for every i below 100.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("test JIT call") };
        assert_eq!(f(5), 500, "clamp(0..4) is 100 each");
        assert_eq!(f(0), 0, "an empty loop sums to zero");
        assert_eq!(
            f(105),
            100 * 100 + (100 + 101 + 102 + 103 + 104),
            "i<100 clamps to 100; i>=100 passes through",
        );

        // The OSR door, into the same body, at the loop header. This is the one
        // the containment used to withhold, so its PRESENCE is asserted rather
        // than tolerated: a silent absence is how the containment would come
        // back without anyone noticing, and this test would then "pass" by
        // never entering.
        assert!(
            cm.ir_osr_entry_addr(4).is_some(),
            "the loop header must carry an optimizing OSR entry even though a \
             spliced body contributed the merge inside it (entries: {:?})",
            cm.ir_osr_entries
                .iter()
                .map(|(b, _, _)| *b)
                .collect::<Vec<_>>(),
        );
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&[5, 1000, 2]),
            Some(1000 + 3 * 100),
            "entering at i=2 with s=1000 must run i=2,3,4 through the spliced \
             clamp and add 100 each",
        );
        assert_eq!(
            entered(&[103, 0, 100]),
            Some(100 + 101 + 102),
            "the OTHER arm of the spliced branch, from i=100",
        );
    }

    /// A body the door cannot enter carries no stubs, and the escape hatch
    /// puts them back.
    ///
    /// # What this is protecting
    ///
    /// `try_osr`'s admission is `ir_osr_entry_addr(pc).is_some() &&
    /// ir_osr_sentinel_free` — BOTH — so every stub in a body that is not
    /// sentinel-free is unreachable: bytes in the code cache, a `JMP` to
    /// patch, a published `(bci, offset, needed)` triple, and a whole
    /// `build_live_model` pass, for a door that will refuse the artifact on
    /// the second conjunct. And it is the COMMON case, not a corner:
    /// sentinel-free means no deopt stub and no call-exception stub, so any
    /// method containing a call fails it.
    ///
    /// The loop below is sentinel-free, so it is the control: it must still
    /// carry entries under the production rule. Making a body that is NOT
    /// sentinel-free is what `assert` on `ir_osr_sentinel_free` checks, so
    /// this test cannot silently degrade into asserting nothing.
    #[test]
    fn a_body_the_door_cannot_enter_carries_no_osr_stubs() {
        // `for (i = 0; i < n; i++) s += i; return s;` — no call, no guard, so
        // no deopt stub and no call-exception stub: sentinel-free.
        let sentinel_free_loop = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        {
            let _on = OsrEntryForce::on_but_not_always();
            let cm = compile_via_ir(&sentinel_free_loop, 21, 1, 3).expect("loop compiles via IR");
            assert!(
                cm.ir_osr_sentinel_free,
                "the control body must be sentinel-free, or this test proves \
                 nothing about the skip"
            );
            assert!(
                !cm.ir_osr_entries.is_empty(),
                "a sentinel-free body still gets its entries — the skip is \
                 about the door's SECOND conjunct, not about turning OSR off"
            );
        }
        // And the escape hatch is what the twenty-odd older stub-shape tests
        // ride on, so it has to actually restore the old behaviour.
        {
            let _always = OsrEntryForce::on();
            let cm = compile_via_ir(&sentinel_free_loop, 21, 1, 3).expect("loop compiles via IR");
            assert!(!cm.ir_osr_entries.is_empty());
        }
    }

    /// The kill switch really removes them: with `CRATONVM_JIT_IR_OSR_ENTRY=0`
    /// an artifact carries no entry stub at all.
    ///
    /// Until 2026-09-05 this asserted the same thing about the DEFAULT, which
    /// is what it was. The switch is on now, so the property worth pinning is
    /// that turning it off still works — a default-on codegen change is only as
    /// good as its way back.
    #[test]
    fn the_osr_entry_kill_switch_emits_no_stub() {
        let _off = OsrEntryForce::off();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        assert!(
            cm.ir_osr_entries.is_empty(),
            "with the kill switch set an artifact must carry no entry stub",
        );
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
    }

    /// Round 12 wave 1 (lane osr, irback proposal W18-2): an ordinary OSR
    /// entry is planned only at a loop header. The door enters only at the
    /// target of a taken backward branch, which here is bci 4 alone; a stub
    /// at the loop exit (19) or any other block start is dead code the door
    /// can never ask for.
    #[test]
    fn r12w1_ordinary_osr_entries_are_planned_only_at_loop_headers() {
        let _always = OsrEntryForce::on();
        // `for (i = 0; i < n; i++) s += i; return s;` -- header at 4.
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        let bcis: Vec<u32> = cm.ir_osr_entries.iter().map(|&(b, _, _)| b).collect();
        assert!(
            !bcis.is_empty(),
            "the header lost its entry too: this fixture no longer asks anything",
        );
        assert!(
            bcis.iter().all(|&b| b == 4),
            "OSR entries at {bcis:?}; bci 4 is the only back-edge target",
        );
    }

    /// `Lowerer::first_safepoint_index_by_bci` gives, for every bci, the answer
    /// of the by-bci scan it replaced: the FIRST snapshot at that bci. That
    /// holds when several snapshots share a bci, as an unrolled body's copies
    /// do, and for a bci with no snapshot at all.
    #[test]
    fn the_safepoint_index_names_the_first_snapshot_at_each_bci() {
        // iconst_0; istore_1; iload_1; ireturn
        let code = [0x03, 0x3c, 0x1b, 0xac, 0, 0];
        let mut graph = IrBuilder::new(1, 2).build(&code, 4).expect("builds");
        for bci in [2usize, 0, 2, 7, 3, 7] {
            graph.safepoints.push(crate::ir::SafepointSnapshot::new(
                bci,
                Vec::new(),
                Vec::new(),
                Vec::new(),
            ));
        }
        let index = Lowerer::first_safepoint_index_by_bci(&graph);
        for bci in 0..10usize {
            assert_eq!(
                index.get(&bci).copied(),
                graph.safepoints.iter().position(|s| s.bci == bci),
                "bci {bci}"
            );
        }
        let distinct: std::collections::HashSet<usize> =
            graph.safepoints.iter().map(|s| s.bci).collect();
        assert_eq!(index.len(), distinct.len(), "one entry per distinct bci");
    }

    // ── Bottom-tested (rotated) loops ────────────────────────────────────
    //
    // ECJ, Kotlin and Scala jump forward to a loop's test and branch back to
    // its body. The IR builder refused every such method until it learned to
    // walk one in reverse post-order. Each test compiles the shape through the
    // whole IR pipeline and checks the answer the obvious Java gives. The byte
    // layouts are annotated beside the same fixtures in `ir.rs`.

    /// `int f(int n) { int s = 0; for (int i = 0; i < n; i++) s += i; return s; }`, ECJ-shaped.
    #[test]
    fn a_rotated_for_loop_compiles_via_ir_and_sums() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x0a, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01,
            0x1c, 0x1a, 0xa1, 0xff, 0xf7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("a rotated for loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        for (n, want) in [(0i64, 0i64), (1, 0), (5, 10), (10, 45), (-3, 0)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { do { n = n - 3; } while (n > 0); return n; }`: the loop
    /// header is pc 0.
    #[test]
    fn a_do_while_at_the_method_entry_compiles_via_ir() {
        let code = [
            0x1a, 0x06, 0x64, 0x3b, 0x1a, 0x9d, 0xff, 0xfb, 0x1a, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 10, 1, 1).expect("a do/while at pc 0 compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32 as i64;
        for (n, want) in [(10i64, -2i64), (0, -3), (3, 0), (1, -2), (-5, -8)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { int c = 0; for (int i = 0; i < n; i++) for (int j = 0; j < i; j++) c += j; return c; }`:
    /// a javac-shaped outer loop around an ECJ-shaped inner one.
    #[test]
    fn a_rotated_loop_nested_in_a_javac_loop_compiles_via_ir() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0xa7, 0x00, 0x0a,
            0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0x1d, 0x1c, 0xa1, 0xff, 0xf7, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 34, 1, 4).expect("a nested rotated loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        // sum over i < n of (0 + 1 + ... + (i - 1))
        for (n, want) in [(0i64, 0i64), (1, 0), (4, 4), (5, 10), (6, 20)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { int s = 0; for (int i = 0; i < n; i++) { if ((i & 1) == 0) s += i; else s -= 1; } return s; }`,
    /// ECJ-shaped: a forward if/else join inside a rotated body.
    #[test]
    fn a_rotated_loop_with_an_if_else_join_compiles_via_ir() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x16, 0x1c, 0x04, 0x7e, 0x9a, 0x00, 0x0a, 0x1b,
            0x1c, 0x60, 0x3c, 0xa7, 0x00, 0x06, 0x84, 0x01, 0xff, 0x84, 0x02, 0x01, 0x1c, 0x1a,
            0xa1, 0xff, 0xeb, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 33, 1, 3)
            .expect("a rotated loop with an if/else compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32 as i64;
        for (n, want) in [(0i64, 0i64), (1, 0), (2, -1), (3, 1), (5, 4), (6, 3)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    // do-while: the back-edge is an `if_icmplt` (not a goto), and the loop
    // header self-loops (the condition is at the bottom). Exercises the
    // if-as-back-edge path + a block whose true edge targets its own head.
    #[test]
    fn test_lower_do_while_sum() {
        // int f(int n){ int s=0,i=0; do { s+=i; i++; } while(i<n); return s; }
        //  0:iconst_0 1:istore_1 2:iconst_0 3:istore_2
        //  4:iload_1 5:iload_2 6:iadd 7:istore_1 8:iinc 2,1
        // 11:iload_2 12:iload_0 13:if_icmplt 4  16:iload_1 17:ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01, 0x1c, 0x1a, 0xa1,
            0xff, 0xf7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 18, 1, 3).expect("do-while compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(f(5), 10, "runs i=0..4 → 0+1+2+3+4 = 10");
        assert_eq!(f(1), 0, "runs once (i=0) → 0");
        assert_eq!(f(0), 0, "do-while runs once even at n=0 → s=0");
    }

    // Nested counted loops: two loop headers, the inner nested in the outer.
    #[test]
    fn test_lower_nested_loops() {
        // int f(int n){ int c=0; for(i=0;i<n;i++) for(j=0;j<n;j++) c++; return c; }
        //  0:iconst_0 1:istore_1            // c=0
        //  2:iconst_0 3:istore_2            // i=0
        //  4:iload_2 5:iload_0 6:if_icmpge 28   // outer header
        //  9:iconst_0 10:istore_3           // j=0
        // 11:iload_3 12:iload_0 13:if_icmpge 22 // inner header
        // 16:iinc 1,1  19:iinc 3,1  22? ...
        // Layout carefully below.
        //  0:03 1:3c 2:03 3:3d
        //  4:1c 5:1a 6:a2 00 16(=22? we need offset) ...
        // Compute: outer if_icmpge at 6 must exit past the outer iinc/goto.
        //  4: iload_2        1c            outer header
        //  5: iload_0        1a
        //  6: if_icmpge 31   a2 00 19       (6+25=31)
        //  9: iconst_0       03            j=0
        // 10: istore_3       3e
        // 11: iload_3        1d            inner header
        // 12: iload_0        1a
        // 13: if_icmpge 25   a2 00 0c       (13+12=25)
        // 16: iinc 1,1       84 01 01       c++
        // 19: iinc 3,1       84 03 01       j++
        // 22: goto 11        a7 ff f5       (22-11=11)
        // 25: iinc 2,1       84 02 01       i++
        // 28: goto 4         a7 ff e8       (28-24=4)
        // 31: iload_1        1b
        // 32: ireturn        ac
        let code = [
            0x03, 0x3c, 0x03, 0x3d, // 0..3
            0x1c, 0x1a, 0xa2, 0x00, 0x19, // 4: outer header, if_icmpge 31
            0x03, 0x3e, // 9: j=0
            0x1d, 0x1a, 0xa2, 0x00, 0x0c, // 11: inner header, if_icmpge 25
            0x84, 0x01, 0x01, // 16: iinc c
            0x84, 0x03, 0x01, // 19: iinc j
            0xa7, 0xff, 0xf5, // 22: goto 11
            0x84, 0x02, 0x01, // 25: iinc i
            0xa7, 0xff, 0xe8, // 28: goto 4
            0x1b, 0xac, // 31: iload_1; ireturn
            0, 0,
        ];
        let cm = compile_via_ir(&code, 33, 1, 4).expect("nested loops compile via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(f(3), 9, "3*3 = 9");
        assert_eq!(f(5), 25, "5*5 = 25");
        assert_eq!(f(0), 0, "no iterations");
        assert_eq!(f(1), 1, "1*1 = 1");
    }

    // ── real-frame-deopt fires end-to-end: div-by-zero guard ─────────────
    // Proves the trigger half: an IR-compiled `a/b` deopts (instead of the raw
    // IDIV faulting) when b==0, with the reconstructed frame carrying the live
    // operands at the idiv bci so the interpreter can re-execute and throw
    // ArithmeticException. (The VM-side resume is wired separately, gated.)
    #[test]
    fn test_lower_div_by_zero_deopts() {
        use crate::deopt::{take_last_deopt, FrameValue};
        // int f(int a, int b){ return a / b; }  — iload_0; iload_1; idiv; ireturn
        let code = [0x1a, 0x1b, 0x6c, 0xac, 0, 0];
        let cm = compile_via_ir(&code, 4, 2, 2).expect("div compiles via IR");

        let _ = take_last_deopt(); // clear any stale state
                                   // divisor != 0 → normal result, no deopt.
                                   // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let ok = unsafe { cm.try_call(&[20, 4]).expect("call (b != 0)") };
        assert_eq!(ok, 5, "20 / 4 = 5");
        assert!(take_last_deopt().is_none(), "no deopt when divisor != 0");

        // divisor == 0 → deopt (sentinel + reconstructed frame), NOT a #DE fault.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sentinel = unsafe { cm.try_call(&[20, 0]).expect("call (b == 0)") };
        assert_eq!(sentinel, i64::MIN, "div by zero → deopt sentinel");
        let frame = take_last_deopt().expect("deopt reconstructed a frame");
        // idiv is at bci 2; resume there with [a, b] live on the operand stack
        // so the interpreter re-executes the division and throws.
        assert_eq!(frame.bci, 2, "resume at the idiv bci");
        assert_eq!(
            frame.stack,
            vec![FrameValue::Int(20), FrameValue::Int(0)],
            "operands restored for re-execution",
        );
    }

    #[test]
    fn test_lower_ldiv_by_zero_reconstructs_long_frame() {
        use crate::deopt::{take_last_deopt, FrameValue};
        use crate::ir::{IrBuilder, IrType};
        // long f(long a, long b){ return a / b; }
        //   lload_0; lload_2; ldiv; lreturn   (+ 2 trailing padding bytes)
        // Proves a `long` live at the div guard reconstructs as a full-64-bit
        // FrameValue::Long (cat-2 width on resume), not a truncated Int.
        let code = [0x1e, 0x20, 0x6d, 0xad, 0, 0];
        let mut builder = IrBuilder::new(2, 4); // 2 long params (a@0-1, b@2-3)
        builder.set_param_types(&[IrType::Long, IrType::Long]);
        let mut graph = builder.build(&code, 4).expect("ldiv IR build");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 2, 4, &no_helpers()).expect("lower ldiv");

        let _ = take_last_deopt(); // clear any stale state
                                   // divisor != 0 → normal full-64-bit result, no deopt. A 32-bit IDIV
                                   // would mishandle this dividend (> i32::MAX).
                                   // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let ok = unsafe { cm.try_call(&[0x1_0000_0000, 2]).expect("call (b != 0)") };
        assert_eq!(ok, 0x8000_0000, "0x1_0000_0000 / 2 (genuinely 64-bit)");
        assert!(take_last_deopt().is_none(), "no deopt when divisor != 0");

        // divisor == 0 → deopt; the reconstructed frame must carry the two LONG
        // operands as FrameValue::Long (full 64 bits) so the interpreter resumes
        // at the ldiv bci and re-executes it (throwing ArithmeticException).
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sentinel = unsafe { cm.try_call(&[0x7_0000_0000, 0]).expect("call (b == 0)") };
        assert_eq!(sentinel, i64::MIN, "ldiv by zero → deopt sentinel");
        let frame = take_last_deopt().expect("deopt reconstructed a frame");
        assert_eq!(frame.bci, 2, "resume at the ldiv bci");
        assert_eq!(
            frame.stack,
            vec![FrameValue::Long(0x7_0000_0000), FrameValue::Long(0)],
            "long operands restored as full-64-bit FrameValue::Long",
        );
        // Locals: a@0 and b@2 are longs (StackSlotLong → Long); the high-half
        // slots 1/3 are dummies (never read by the interpreter).
        assert_eq!(frame.locals[0], FrameValue::Long(0x7_0000_0000));
        assert_eq!(frame.locals[2], FrameValue::Long(0));
    }

    // ── `[rbp - 0]` sentinel removal + resource bounds ───────────────────

    /// `int f(int a) { return a + 1; }` as a hand-built graph, plus its
    /// schedule. The smallest shape that has a real data edge to verify.
    fn add_one_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let sum = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// `void f(int a) { a + 1; }` — the same shape as [`add_one_graph`] with the
    /// value dropped from the `Return`, so the only difference between the two
    /// lowerings is the void exit itself.
    fn void_return_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let _sum = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// Laying out a jump table on an OVERFLOWED buffer must return, not spin.
    ///
    /// `emit_switch_tables` pads to a 4-byte boundary with `emit_byte` until
    /// `pos() % 4 == 0`. Once the buffer has overflowed, every write is a
    /// sticky no-op and `pos()` is frozen. If it froze at an unaligned offset,
    /// the loop never ended. That hung the compiling thread, and with it the
    /// whole VM: Spring tests using Mockito's inline mock maker hung in
    /// ByteBuddy's agent self-attach (`JarInputStream.<init>` compiling
    /// a switch-bearing method at the IR tier) until the watchdog fired.
    ///
    /// Run on a worker with a deadline, so a regression FAILS this test
    /// rather than hanging the test binary.
    #[test]
    fn a_switch_table_on_an_overflowed_buffer_returns_instead_of_spinning() {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let (graph, schedule) = add_one_graph();
            let graph: &'static Graph = Box::leak(Box::new(graph));
            let schedule: &'static Schedule = Box::leak(Box::new(schedule));
            let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
            let mut lo = lowerer_over(graph, schedule, plan, 64);
            // Three bytes in, then a write that does not fit: the buffer is
            // overflowed with `pos()` frozen at 3, which no padding can align.
            lo.buf.emit(&[0x90; 3]);
            lo.buf.emit(&[0x90; 128]);
            assert!(lo.buf.overflowed() && lo.buf.pos() % 4 != 0);
            lo.switch_tables.push(SwitchTablePlan {
                lea_patch: 0,
                targets: vec![0, 0],
            });
            lo.emit_switch_tables();
            let _ = tx.send(lo.buf.pos());
        });
        let pos = rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("emit_switch_tables did not return on an overflowed buffer: it is spinning");
        assert_eq!(pos, 3, "nothing may be written past the overflow");
    }

    /// A VOID return must leave a defined value in the return register.
    ///
    /// `i64::MIN` there is the VM-wide "the callee trapped" sentinel, and every
    /// consumer reads the raw register: the single-pass inline MIC/PIC
    /// cascade's `emit_inline_callee_deopt_check`, the megamorphic hashed
    /// stub's, `jit_invoke_virtual_mic`'s `rc == i64::MIN`, and the
    /// interpreter's post-JIT drain. A void method has no return value, so
    /// unless the exit writes one, RAX carries whatever the last operation left
    /// there and can equal the sentinel by accident — on behalf of a call that
    /// neither threw nor deopted. The single-pass backend has always zeroed it
    /// (`x64/bytecode_walk.rs`, the `0xb1` arm); this backend did not.
    ///
    /// Asserted on the BYTES, and as a DIFFERENCE against the value-returning
    /// twin, so it cannot pass by accident: `try_call` returning 0 would be
    /// satisfied by an undefined register that merely happened to hold 0.
    #[test]
    fn a_void_return_writes_the_return_register() {
        const XOR_EAX_EAX: [u8; 2] = [0x31, 0xC0];

        let (vg, vs) = void_return_graph();
        let void_method = lower(&vg, &vs, 1, 1, &no_helpers()).expect("void method must lower");
        let (ag, as_) = add_one_graph();
        let value_method = lower(&ag, &as_, 1, 1, &no_helpers()).expect("a+1 must lower");

        let void_zeroes = count_seq(void_method._buffer_slice_for_debug(), &XOR_EAX_EAX);
        let value_zeroes = count_seq(value_method._buffer_slice_for_debug(), &XOR_EAX_EAX);
        assert_eq!(
            void_zeroes,
            value_zeroes + 1,
            "the void exit must contribute exactly one `XOR EAX,EAX` the \
             value-returning exit does not (void={void_zeroes}, value={value_zeroes})",
        );
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { void_method.try_call(&[41]) },
            Ok(0),
            "a void method must not hand its caller the deopt sentinel",
        );
    }

    /// The verifier must not refuse a graph the lowerer handles — otherwise the
    /// "bail before emission" fix would silently cost JIT coverage.
    #[test]
    fn verification_accepts_a_well_formed_graph() {
        let (graph, schedule) = add_one_graph();
        assert!(verify_data_locations(&graph, &schedule).is_ok());
        let method = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("a+1 must lower");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { method.try_call(&[41]) }, Ok(42));
    }

    /// Acceptance test for the `[rbp - 0]` defect (report: "replace
    /// zero-initialized `node_slot` with verified optional locations").
    ///
    /// A data input that no emitted node defines — here an `Op::Dead` node,
    /// which the scheduler never places, exactly like the GVN-collapsed
    /// `ArrayLoad(Double)` observed in `DualPivotQuicksort.insertionSort` —
    /// must refuse the compile *before* emission, not be detected afterwards by
    /// a sticky bit. Before this change the use lowered to `[rbp - 0]`, reading
    /// the saved caller frame pointer as a `double`.
    #[test]
    fn an_unallocated_data_input_refuses_the_compile_before_emission() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        // Scheduler omission, modelled: `Op::Dead` is never placed into a
        // block, so nothing ever allocates a location for it.
        let ghost = graph.add(Op::Dead, IrType::Int, vec![], None);
        let sum = graph.add(Op::Add, IrType::Int, vec![a, ghost], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], None);

        let schedule = ir_schedule::schedule(&graph);
        assert_eq!(
            schedule.node_to_block[ghost as usize],
            usize::MAX,
            "precondition: the ghost node is in no emitted block",
        );

        let err = verify_data_locations(&graph, &schedule)
            .expect_err("an unallocated data input must be refused");
        assert_eq!(err.reason, BailoutReason::UnallocatedValue { node: ghost });
        assert_eq!(err.category(), "unallocated_value");

        // …and the public entry point turns that into the historical "run in a
        // lower tier" answer rather than emitting or panicking.
        assert!(lower(&graph, &schedule, 1, 1, &no_helpers()).is_none());
    }

    /// The slot accessor has no encoding for "unallocated", so it can never
    /// hand back `0` — the offset that means `[rbp - 0]`, the saved caller RBP.
    #[test]
    fn slot_accessor_never_yields_the_rbp_zero_sentinel() {
        let (graph, schedule) = add_one_graph();
        let a = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Param(0)))
            .expect("param node") as NodeId;
        let sum = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Add))
            .expect("add node") as NodeId;

        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact_fields: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let plan = plan_slots(&graph, &schedule, None);
        let mut lowerer = Lowerer::new(
            &graph,
            &schedule,
            buf,
            1,
            1,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact_fields,
            &no_frame_sites,
        );

        // Unallocated is an error, not an offset.
        assert!(lowerer.slot_of_checked(a).is_err());
        assert!(lowerer.node_slot.iter().all(|slot| slot.is_none()));

        let off = lowerer.alloc_slot_checked(a).expect("first spill slot");
        assert!(
            off >= lowerer.first_spill,
            "{off} < {}",
            lowerer.first_spill
        );
        assert_ne!(off, 0);
        assert_eq!(lowerer.slot_of_checked(a).expect("allocated"), off);
        // Non-zero by type, not by convention: every occupied entry is a
        // `NonZeroU32`, so `0` is not a representable location at all.
        assert!(lowerer
            .node_slot
            .iter()
            .flatten()
            .all(|located| located.get() > 0));

        // The infallible façade the emission sites use latches a structured
        // reason and still never returns 0.
        let poison = lowerer.slot_of(sum);
        assert_ne!(poison, 0, "the façade must never emit [rbp - 0]");
        assert!(lowerer.unallocated_slot_use.get());
        let latched = lowerer.take_latched_bailout().expect("a latched reason");
        assert_eq!(
            latched.reason,
            BailoutReason::UnallocatedValue { node: sum }
        );
        // An out-of-range id is an error too — it used to index-panic.
        assert!(lowerer.slot_of_checked(NO_NODE).is_err());
    }

    /// Report: "bound graph and frame memory before allocation" — an
    /// over-budget node count is refused with `GraphTooLarge`.
    #[test]
    fn an_over_limit_node_count_bails_with_graph_too_large() {
        assert!(check_graph_size(0, DEFAULT_MAX_NODES).is_ok());
        assert!(check_graph_size(DEFAULT_MAX_NODES, DEFAULT_MAX_NODES).is_ok());
        let err = check_graph_size(DEFAULT_MAX_NODES + 1, DEFAULT_MAX_NODES)
            .expect_err("over the node budget");
        assert_eq!(
            err.reason,
            BailoutReason::GraphTooLarge {
                nodes: DEFAULT_MAX_NODES + 1,
                limit: DEFAULT_MAX_NODES,
            }
        );
        assert_eq!(err.category(), "graph_too_large");
    }

    /// Report: "bound graph and frame memory before allocation" — the frame is
    /// estimated (spill reservation + locals + staged outgoing args) and
    /// refused with `FrameTooLarge` before a byte of it is reserved.
    #[test]
    fn an_over_limit_frame_estimate_bails_with_frame_too_large() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };

        // A normal method is nowhere near the bound.
        let small = estimate_frame_bytes(4, 32, &plain);
        assert!(small < DEFAULT_MAX_FRAME_BYTES, "{small}");
        assert!(check_frame_size(small, DEFAULT_MAX_FRAME_BYTES).is_ok());
        assert_eq!(small % 16, 0, "the estimate is 16-byte aligned");

        // Each of the three terms the report names moves the estimate.
        assert!(estimate_frame_bytes(64, 32, &plain) > small); // locals
        assert!(estimate_frame_bytes(4, 512, &plain) > small); // spills
        assert!(
            estimate_frame_bytes(
                4,
                32,
                &FrameNeeds {
                    needs_context: true,
                    max_call_args: 8,
                },
            ) > small,
            "staged outgoing arguments must count",
        );

        // A method whose PEAK LIVE set is as wide as the node budget still has
        // to be refused: 20_000 simultaneously live values is ~160 KiB, five
        // times the 32 KiB oop-map bound. What changed with liveness reuse is
        // that reaching this now takes 20_000 values live *at once*, not merely
        // 20_000 values in the arena — see
        // `a_previously_declined_large_method_now_compiles`.
        let huge = estimate_frame_bytes(0, DEFAULT_MAX_NODES, &plain);
        assert!(huge > DEFAULT_MAX_FRAME_BYTES, "{huge}");
        let err =
            check_frame_size(huge, DEFAULT_MAX_FRAME_BYTES).expect_err("over the frame budget");
        assert_eq!(
            err.reason,
            BailoutReason::FrameTooLarge {
                bytes: huge,
                limit: DEFAULT_MAX_FRAME_BYTES,
            }
        );
        assert_eq!(err.category(), "frame_too_large");

        // Saturating, not wrapping: a pathological count reports "enormous"
        // instead of overflowing into a small (or negative) frame.
        assert_eq!(
            estimate_frame_bytes(0, usize::MAX, &plain),
            usize::MAX & !15usize,
        );

        // End to end: the public entry point refuses instead of reserving a
        // frame whose slot offsets the oop map could not even encode.
        let (graph, schedule) = add_one_graph();
        assert!(
            lower(&graph, &schedule, 1, 10_000, &no_helpers()).is_none(),
            "10_000 locals is an 80 KiB frame — refuse, do not build it",
        );
        // The same graph with a sane local count still compiles.
        assert!(lower(&graph, &schedule, 1, 1, &no_helpers()).is_some());
    }

    // ── Liveness-based frame-slot reuse ──────────────────────────────────

    /// An empty graph shell, so each test below only writes the shape it cares
    /// about.
    fn empty_graph() -> Graph {
        Graph::empty(0)
    }

    /// `int f(int a) { a += 1; a += 1; … }` with `len` increments: a chain in
    /// which every temporary is dead the instant the next one consumes it. The
    /// shape the old one-slot-per-node reservation was worst on.
    fn straight_line_chain(len: usize) -> (Graph, Schedule) {
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let mut cur = a;
        for _ in 0..len {
            cur = graph.add(Op::Add, IrType::Int, vec![cur, one], None);
        }
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, cur], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// Re-derive the linear emission positions [`plan_slots`] numbers, so a
    /// test can assert *where* a value is live. Deliberately a separate
    /// implementation of the numbering the module comment documents: if the two
    /// ever disagree, the loop test below is the one that notices.
    #[allow(clippy::type_complexity)]
    fn emission_positions(
        graph: &Graph,
        schedule: &Schedule,
    ) -> (Vec<Option<usize>>, Vec<(usize, usize)>) {
        let mut pos = vec![None; graph.nodes.len()];
        let mut span = Vec::with_capacity(schedule.blocks.len());
        let mut seq = 0usize;
        for block in &schedule.blocks {
            let start = seq;
            for &nid in &block.nodes {
                pos[nid as usize] = Some(seq);
                seq += 1;
            }
            if let Some(term) = block.terminator {
                pos[term as usize] = Some(seq);
                seq += 1;
            }
            span.push((start, seq));
            seq += 1;
        }
        (pos, span)
    }

    /// How many values the plan gives a slot to at all — the number the old
    /// reservation would have needed (one word each, forever).
    fn slotted_value_count(plan: &SlotPlan) -> usize {
        plan.node_color.iter().flatten().count()
    }

    /// The colouring's whole point: values that are never live at the same time
    /// land on the same frame word.
    #[test]
    fn non_overlapping_values_share_a_frame_slot() {
        let (graph, schedule) = straight_line_chain(64);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let slotted = slotted_value_count(&plan);
        assert_eq!(slotted, 66, "param + const + 64 adds each want a slot");
        // Successive links of the chain overlap at one position (the consumer's
        // own position), so the chain alternates between two words; the
        // constant and the parameter account for the rest.
        assert!(
            plan.slots <= 8,
            "64 chained temporaries should collapse to a handful of slots, got {}",
            plan.slots,
        );
        assert!(
            plan.slots < slotted,
            "no reuse happened at all: {} slots for {slotted} values",
            plan.slots,
        );
        assert!(
            plan.peak_live <= plan.slots,
            "peak live ({}) is the floor the colouring cannot beat, slots = {}",
            plan.peak_live,
            plan.slots,
        );
    }

    /// …and values that ARE live at the same time never do. The endpoint-
    /// inclusive overlap rule means a value whose last use is at position `p`
    /// also keeps its word against a value defined at `p`.
    #[test]
    fn overlapping_values_never_share_a_frame_slot() {
        // int f(int a, int b) { int s = a + b; return a + s; }  — `a` is live
        // across `s`, so the two cannot share; `b` dies at `s`, so it can be
        // recycled by the value defined last.
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let b = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        let s = graph.add(Op::Add, IrType::Int, vec![a, b], None);
        let t = graph.add(Op::Add, IrType::Int, vec![a, s], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, t], None);
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        let color = |id: NodeId| plan.node_color[id as usize].expect("a coloured value");

        assert_ne!(color(a), color(b), "both live into the first add");
        assert_ne!(color(a), color(s), "a outlives s's definition");
        assert_ne!(color(a), color(t), "a is live where t is defined");
        assert_ne!(color(s), color(t), "s is live where t is defined");
        // Four values, one legitimate sharing pair (b dies before t is defined).
        assert_eq!(slotted_value_count(&plan), 4);
        assert!(
            plan.slots < 4,
            "a dead-before-t value must be recycled, got {} slots",
            plan.slots,
        );

        // End to end, the code still computes a + (a + b).
        let cm = lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lowers");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[3, 4]) }, Ok(10));
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[-1, 5]) }, Ok(3));
    }

    /// A value used anywhere in a loop is live across the WHOLE loop, not just
    /// up to its textually last use — otherwise the second iteration reads a
    /// word some later definition has overwritten.
    ///
    /// The liveness fixed point produces this without knowing what a loop is:
    /// the back edge makes the header's uses reach every block on the path back
    /// to it. This test pins that it actually happens.
    #[test]
    fn a_loop_carried_value_stays_live_across_the_whole_loop() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; } —
        // `n` is compared every iteration, so it must survive the back edge.
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let mut graph = IrBuilder::new(1, 3).build(&code, 21).expect("IR build");
        ir_optimize::optimize(&mut graph);
        // Drop the deopt snapshots: every node they name is deliberately pinned
        // to a dedicated slot, which would make this test pass for the wrong
        // reason. The pinning itself is covered by
        // `a_deopt_visible_value_keeps_a_dedicated_slot`.
        graph.safepoints.clear();
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let (_pos, span) = emission_positions(&graph, &schedule);
        // The loop: the last back edge (a successor at or before its own block
        // index — the same test `lower_block` uses to place a safepoint poll)
        // and the header it returns to.
        let mut back_edge: Option<(usize, usize)> = None;
        for (b, block) in schedule.blocks.iter().enumerate() {
            for &s in &block.successors {
                if s <= b {
                    back_edge = Some((s, b));
                }
            }
        }
        let (header, latch) = back_edge.expect("the counted loop has a back edge");
        assert!(
            header < latch,
            "precondition: the loop spans more than one block ({header}..={latch})",
        );

        let n_node = graph
            .nodes
            .iter()
            .position(|node| matches!(node.op, Op::Param(0)))
            .expect("the loop bound is a parameter") as NodeId;
        let n_range = plan.range[n_node as usize].expect("the loop bound has a live range");
        assert!(
            n_range.lo <= span[header].0 && n_range.hi >= span[latch].1,
            "the loop bound is live [{}, {}] but the loop spans [{}, {}]",
            n_range.lo,
            n_range.hi,
            span[header].0,
            span[latch].1,
        );

        // …and therefore nothing defined inside the loop took its word.
        let n_color = plan.node_color[n_node as usize].expect("a coloured value");
        for (id, color) in plan.node_color.iter().enumerate() {
            if id as NodeId == n_node || *color != Some(n_color) {
                continue;
            }
            let block = schedule.node_to_block[id];
            assert!(
                block == usize::MAX || block < header || block > latch,
                "n{id} is inside the loop (block {block}) and reused the loop \
                 bound's frame slot",
            );
        }

        // The behavioural proof is `test_lower_counted_loop_sum`, which runs
        // this exact method; keep the compile working here too.
        assert!(lower(&graph, &schedule, 1, 3, &no_helpers()).is_some());
    }

    /// A reference and a primitive never share a frame word.
    ///
    /// `emit_safepoint_map` publishes a slot as a GC root because *some* `Ref`
    /// value was defined into it, and `defined_nodes` never un-sets. If a
    /// primitive could inherit that word, the collector would follow an `int`
    /// as an object pointer. The two free lists are disjoint, so this is a
    /// property of the representation, not of the schedule.
    #[test]
    fn a_reference_is_never_aliased_with_a_non_reference() {
        // Object f(Object r, int a) { int t = a + 1; int u = t + 1; return r; }
        // `r` is live to the return; `a`, `t`, `u` die in sequence, so the
        // primitive pool recycles while the reference pool does not.
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let r = graph.add(Op::Param(0), IrType::Ref, vec![start], None);
        let a = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let t = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        let u = graph.add(Op::Add, IrType::Int, vec![t, one], None);
        let v = graph.add(Op::Add, IrType::Int, vec![u, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, r], None);
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        // Reuse did happen among the primitives…
        assert!(
            plan.slots < slotted_value_count(&plan),
            "the primitive chain should have recycled a word",
        );
        // …and no word holds both classes.
        let mut class_of_color: HashMap<u32, SlotClass> = HashMap::new();
        for (id, color) in plan.node_color.iter().enumerate() {
            let (color, class) = match (color, plan.class[id]) {
                (Some(color), Some(class)) => (*color, class),
                _ => continue,
            };
            match class_of_color.get(&color) {
                Some(seen) => assert_eq!(
                    *seen, class,
                    "slot {color} mixes {seen:?} and {class:?} (n{id})",
                ),
                None => {
                    class_of_color.insert(color, class);
                }
            }
        }
        // The reference genuinely got a word of its own, not merely a word no
        // primitive happened to want.
        let r_color = plan.node_color[r as usize].expect("a coloured reference");
        assert_eq!(class_of_color.get(&r_color), Some(&SlotClass::Ref));
        for id in [a, t, u, v] {
            assert_ne!(
                plan.node_color[id as usize],
                Some(r_color),
                "n{id} is a primitive on the reference's word",
            );
        }

        // …and the stale-word oracle's view of the same plan agrees: every
        // primitive's colour is offered as "provably not a reference", and the
        // reference's colour is not. This is what an IR frame publishes as
        // `OopMapEntry::non_oop_stack_slots`, and a colour wrongly listed here
        // would let the residue report call a live root dead storage.
        let prim = plan.prim_colors();
        for id in [a, t, u, v] {
            let c = plan.node_color[id as usize].expect("a coloured primitive");
            assert!(
                prim.contains(&c),
                "n{id}'s word {c} is missing from prim_colors"
            );
        }
        assert!(
            !prim.contains(&r_color),
            "the reference's word {r_color} must never be offered as a non-reference",
        );
    }

    /// COV-02: an `aaload` result is a GC ROOT, and this is the executed proof.
    ///
    /// `emit_safepoint_map` decides what to publish by scanning
    /// `graph.nodes[id].ty != IrType::Ref`, and `plan_slots` decides which pool
    /// a node's frame word comes from. Both answers hang on the ONE thing the
    /// `aaload` builder arm chooses: the node's `IrType`. Typing it `Int`
    /// compiles, passes every value-differential in
    /// `jit/tests/ir_vs_singlepass.rs`, and loses the element at the first
    /// relocating collection — a failure that surfaces nowhere near here.
    ///
    /// The brief's own suggestion for proving this — run it under
    /// `CRATONVM_MOVING_YOUNG` — cannot work: `JIT_PUBLISHES_RELOCATION_CONTRACT`
    /// is `false`, so a young collection that meets an unprovable compiled frame
    /// falls back to the non-moving sweep instead of relocating, and an
    /// unpublished root produces no observable stale pointer. See
    /// `cov-02-array-element-access-RETIRED-20260803.md`. So the
    /// property is asserted where it is actually decided.
    ///
    /// **Anti-vacuity, executed rather than argued.** The mutation was run:
    /// with `0x32`'s arm in `ir.rs` changed to `(MemKind::Ref, IrType::Int)`,
    /// this test fails with `left: Int, right: Ref` and nothing else in the
    /// crate's 1,869 lib tests notices. That is the edit to repeat if this test
    /// is ever suspected of measuring something else.
    ///
    /// It has already been wrong once in the other direction: it first asserted
    /// `class == SlotClass::Ref` and failed on an honest tree, because in a
    /// method this short the element is still deopt-visible and gets pinned.
    /// See the comment at the assertion.
    #[test]
    fn an_aaload_result_is_reference_typed_and_takes_a_reference_slot() {
        use crate::ir::{IrBuilder, MemKind};

        // static Object get(Object[] a, int i) { return a[i]; }
        //   aload_0; iload_1; aaload; areturn      (+2 bytes of padding)
        let code = [0x2a, 0x1b, 0x32, 0xb0, 0x00, 0x00];
        let graph = IrBuilder::new(2, 2)
            .build(&code, 4)
            .expect("the aaload corpus must build");

        let loads: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::ArrayLoad(MemKind::Ref)))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert_eq!(
            loads.len(),
            1,
            "precondition: exactly one `aaload` node, or this test is measuring \
             something else"
        );
        let load = loads[0];
        assert_eq!(
            graph.nodes[load as usize].ty,
            IrType::Ref,
            "an `aaload` result is a reference; `emit_safepoint_map` skips every \
             node whose `ty` is not `Ref`, so an `Int` here is an unpublished \
             root at every later safepoint"
        );

        // …and no primitive may ever inherit the word it lands in, because
        // `emit_safepoint_map` will name that word as a root.
        //
        // Asserted as an ALIASING property rather than as `class ==
        // SlotClass::Ref`, which is what this test tried first and which is
        // wrong: in a method this short the element is still on the operand
        // stack at the `areturn` bci, so a safepoint snapshot names it and
        // `plan_slots` pins it (`SlotClass::Pinned` — shares with nothing at
        // all, strictly stronger than the reference pool). Which of the two it
        // gets depends on where the value dies, i.e. on the fixture. What must
        // hold for every fixture is that no `Prim` sits on its colour.
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        let class = plan.class[load as usize].expect("the element must get a frame word");
        assert_ne!(
            class,
            SlotClass::Prim,
            "an `aaload` result took a word from the PRIMITIVE pool; the \
             collector would then follow whatever int recycled it as an object \
             pointer"
        );
        let color = plan.node_color[load as usize].expect("a coloured element");
        for (id, other) in plan.node_color.iter().enumerate() {
            if id == load as usize || *other != Some(color) {
                continue;
            }
            assert_ne!(
                plan.class[id],
                Some(SlotClass::Prim),
                "n{id} is a primitive sharing the `aaload` element's frame word",
            );
        }
    }

    /// Every value a deopt frame names keeps a dedicated slot: the deopt
    /// producer reads it at a native offset chosen at run time, so "dead by
    /// then" is not a question this file can answer.
    #[test]
    fn a_deopt_visible_value_keeps_a_dedicated_slot() {
        let (mut graph, _) = straight_line_chain(8);
        // Name the first two adds in a snapshot, exactly as `IrBuilder` would
        // for a bytecode boundary whose locals hold them.
        let adds: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id as NodeId)
            .take(2)
            .collect();
        graph.safepoints.push(SafepointSnapshot::new(
            0,
            vec![adds[0]],
            vec![adds[1]],
            Vec::new(),
        ));
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        for &pinned in &adds {
            assert_eq!(
                plan.class[pinned as usize],
                Some(SlotClass::Pinned),
                "n{pinned} is named by a deopt frame and must not share",
            );
            let color = plan.node_color[pinned as usize].expect("a coloured value");
            let sharers = plan
                .node_color
                .iter()
                .filter(|c| **c == Some(color))
                .count();
            assert_eq!(sharers, 1, "n{pinned}'s word is shared by {sharers} values");
        }
    }

    /// Round 14 wave 1 (lane chain): a value only a CHAIN snapshot names is
    /// not pinned (`CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS`, default on);
    /// its colouring range reaches the node that could publish the chain, and
    /// no value whose range meets that one takes its word. With the switch at
    /// `0` it is pinned, as before.
    #[test]
    fn r14w1_chain_named_value_is_ranged_to_its_reader_not_pinned() {
        let (mut graph, _) = straight_line_chain(8);
        let adds: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id as NodeId)
            .collect();
        // A chain snapshot at combined pc 40 naming the first add, and the
        // sixth add sitting at pc 40 (a node a guard could be lowered for).
        let mut sp = SafepointSnapshot::new(40, vec![adds[0]], Vec::new(), Vec::new());
        sp.splice_scope = Some(Box::new(crate::ir::SpliceScopeChain { scopes: Vec::new() }));
        graph.safepoints.push(sp);
        graph.nodes[adds[5] as usize].bytecode_pc = Some(40);
        let schedule = ir_schedule::schedule(&graph);
        let (pos, _) = emission_positions(&graph, &schedule);
        let reader = pos[adds[5] as usize].expect("the reader is scheduled");
        let first = adds[0] as usize;

        let plan = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS", None)],
            || plan_slots(&graph, &schedule, None),
        );
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        assert_ne!(plan.class[first], Some(SlotClass::Pinned));
        assert_eq!(plan.chain_ranged, 1);
        let value = plan.range[first].expect("a value range");
        assert!(
            value.hi < reader,
            "precondition: its last value use is earlier"
        );
        let widened = plan.colouring_ranges()[first].expect("a colouring range");
        assert!(widened.lo <= value.lo && widened.hi >= reader);
        let color = plan.node_color[first].expect("a coloured value");
        for (id, c) in plan.node_color.iter().enumerate() {
            if id == first || *c != Some(color) {
                continue;
            }
            let other = plan.colouring_ranges()[id].expect("a colouring range");
            assert!(
                !other.overlaps(widened),
                "n{id} [{}, {}] took the chain-named word inside [{}, {}]",
                other.lo,
                other.hi,
                widened.lo,
                widened.hi
            );
        }

        let pinned = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS", Some("0"))],
            || plan_slots(&graph, &schedule, None),
        );
        assert_eq!(pinned.class[first], Some(SlotClass::Pinned));
        assert_eq!(pinned.chain_ranged, 0);
        assert!(pinned.colour_range.is_empty());
    }

    /// The colouring verifier is a real check, not a comment: each way a
    /// colouring could go wrong is refused.
    #[test]
    fn the_colouring_verifier_rejects_an_aliased_plan() {
        let (graph, schedule) = straight_line_chain(8);
        let good = plan_slots(&graph, &schedule, None);
        assert!(verify_slot_colouring(&graph, &schedule, &good).is_ok());

        let adds: Vec<usize> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id)
            .collect();

        // (a) Two values that ARE live together forced onto one word — the
        //     silent-wrong-code case.
        let mut aliased = plan_slots(&graph, &schedule, None);
        let (first, second) = (adds[0], adds[1]);
        assert!(
            aliased.range[first]
                .expect("range")
                .overlaps(aliased.range[second].expect("range")),
            "precondition: consecutive chain links overlap",
        );
        let (donor_color, donor_class) = (aliased.node_color[first], aliased.class[first]);
        aliased.node_color[second] = donor_color;
        aliased.class[second] = donor_class;
        let err = verify_slot_colouring(&graph, &schedule, &aliased)
            .expect_err("an aliased pair must be refused");
        assert_eq!(err.category(), "internal");
        assert!(
            err.to_string().contains("simultaneously live"),
            "unexpected reason: {err}",
        );

        // (b) A reference on a primitive's word.
        let mut mixed = plan_slots(&graph, &schedule, None);
        let shared = mixed.node_color[adds[0]];
        mixed.node_color[adds[2]] = shared;
        mixed.class[adds[2]] = Some(SlotClass::Ref);
        mixed.class[adds[0]] = Some(SlotClass::Prim);
        let err = verify_slot_colouring(&graph, &schedule, &mixed)
            .expect_err("a mixed-class word must be refused");
        assert!(
            err.to_string().contains("reference and primitive"),
            "unexpected reason: {err}",
        );

        // (c) A value the lowerer will allocate for, left uncoloured — the
        //     scheduler-omission class `verify_data_locations` guards, restated
        //     for the plan.
        let mut missing = plan_slots(&graph, &schedule, None);
        missing.node_color[adds[0]] = None;
        let err = verify_slot_colouring(&graph, &schedule, &missing)
            .expect_err("an uncoloured scheduled value must be refused");
        assert_eq!(err.category(), "unallocated_value");

        // (d) A colour outside the reservation the frame was sized from.
        let mut oversized = plan_slots(&graph, &schedule, None);
        let beyond = oversized.slots as u32 + 1;
        oversized.node_color[adds[0]] = Some(beyond);
        assert!(verify_slot_colouring(&graph, &schedule, &oversized).is_err());
    }

    /// The measurement the report asks for: frame bytes against node count on a
    /// long straight-line method.
    #[test]
    fn frame_bytes_track_peak_liveness_not_node_count() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };
        let (graph, schedule) = straight_line_chain(512);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let before = estimate_frame_bytes(0, graph.nodes.len(), &plain);
        let after = estimate_frame_bytes(0, plan.slots, &plain);
        assert!(
            after * 8 < before,
            "frame bytes only fell from {before} to {after} on a 512-link chain",
        );
        // The residual is the fixed part of the frame — bookkeeping slots, the
        // stack-arg reserve, the ABI shadow space and, since the register file
        // went default-on (2026-09-02), the estimate's reservation for the
        // callee-saved GP save area — not spill.
        // The 2026-09-05 default-on of the deopt register image adds its 256
        // bytes to the same fixed part. Read from the function the frame is
        // laid out with rather than folded into the literal, so the bound
        // still means "no spill" on a configuration that reserves neither.
        //
        // The GP save area is now read the same way, for the same reason: it
        // is 40 bytes on System V and 56 on Win64, where RSI/RDI joined
        // `IR_GP_LINEAR_SCAN` (2026-09-10). It had been folded into the 192,
        // which made this bound a Windows-vs-Linux coin the moment the file
        // stopped being the same width on both.
        let fixed = 152 + ir_saved_gpr_bytes() as usize + ir_deopt_regs_bytes() as usize;
        assert!(
            after <= fixed,
            "{after} bytes for a 4-slot working set (fixed part is {fixed})",
        );
    }

    /// The node ceiling the frame bound implies, before and after.
    ///
    /// One 8-byte slot per node put the ceiling at ~4 000 nodes: past that the
    /// frame estimate crossed `DEFAULT_MAX_FRAME_BYTES` and the optimizing tier
    /// declined the method outright. Sized by peak liveness instead, a long
    /// method is bounded by `DEFAULT_MAX_NODES` again.
    #[test]
    fn a_previously_declined_large_method_now_compiles() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };

        // Where the old accounting stopped: the largest node count whose
        // one-slot-per-node frame still fit.
        let old_ceiling = (1..=DEFAULT_MAX_NODES)
            .take_while(|&n| estimate_frame_bytes(0, n, &plain) <= DEFAULT_MAX_FRAME_BYTES)
            .last()
            .expect("some node count fits");
        assert!(
            (4000..4200).contains(&old_ceiling),
            "the old ceiling was ~4 000 nodes, computed {old_ceiling}",
        );

        let (graph, schedule) = straight_line_chain(5_000);
        assert!(
            graph.nodes.len() > old_ceiling,
            "precondition: this method was over the old ceiling",
        );
        assert!(
            check_frame_size(
                estimate_frame_bytes(0, graph.nodes.len(), &plain),
                DEFAULT_MAX_FRAME_BYTES,
            )
            .is_err(),
            "precondition: one slot per node would still be refused",
        );

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        assert!(
            check_frame_size(
                estimate_frame_bytes(1, plan.slots, &plain),
                DEFAULT_MAX_FRAME_BYTES,
            )
            .is_ok(),
            "{} slots should fit comfortably",
            plan.slots,
        );

        // And it really compiles and really runs.
        let cm = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("a 5 000-node method lowers");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[0]) }, Ok(5_000));
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[42]) }, Ok(5_042));
    }

    // ── Phi parallel copy (the swap-loop wrong-code fix) ─────────────────
    //
    // `prealloc_phi_slots` gives every phi its OWN frame word, so the copies on
    // one CFG edge are a parallel assignment over distinct words. Emitted in
    // gather order through RAX — which is what this file did — a loop that
    // swaps two locals makes each phi the other's back-edge value, the second
    // copy reads the word the first just overwrote, and both locals end up
    // holding the same value. These tests execute the emitted bytes, because
    // that bug is invisible to any assertion about the copy *list*.

    /// Value seeded into the reserved scratch word before every harness run, so
    /// a test can prove an acyclic copy never touched it.
    const SCRATCH_SENTINEL: i64 = 0x0BAD_5C7A_0000_1234;

    /// Emit `push rbp; mov rbp,rsp; sub rsp,frame`, seed the named frame words
    /// (plus the scratch, with [`SCRATCH_SENTINEL`]), run `copies` through the
    /// REAL sequencer and the REAL emitter, load one word into RAX and return.
    /// Then execute it.
    ///
    /// `read_back == None` reads the reserved scratch word itself.
    ///
    /// The frame is a genuine `Lowerer` frame (so the offsets, the scratch
    /// reservation and `frame_size` are the ones production uses); only the
    /// prologue/epilogue are hand-rolled, because the real ones fetch a thread
    /// and touch the shadow stack that this fixture has no helpers for.
    fn parallel_copy_harness(
        seed: &[(i32, i64)],
        copies: &[(i32, i32)],
        read_back: Option<i32>,
    ) -> (i64, Vec<CopyOp>) {
        // Eight locals so the harness has plenty of frame words BELOW the
        // bookkeeping reservation to use as stand-in phi slots.
        const HARNESS_LOCALS: usize = 8;

        let (graph, schedule) = add_one_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let mut lowerer = Lowerer::new(
            &graph,
            &schedule,
            buf,
            0,
            HARNESS_LOCALS,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &no_frame_sites,
        );
        let scratch = lowerer.phi_copy_scratch_slot_off;
        let frame = lowerer.frame_size;
        for &(off, _) in seed {
            assert!(
                off > 0 && off < frame && off != scratch,
                "the fixture must name a real frame word other than the scratch: {off}",
            );
        }

        // push rbp ; mov rbp, rsp ; sub rsp, frame_size
        lowerer.buf.emit_byte(0x55);
        lowerer.buf.emit(&[0x48, 0x89, 0xE5]);
        lowerer.buf.emit(&[0x48, 0x81, 0xEC]);
        lowerer.buf.emit(&frame.to_le_bytes());

        let scratch_seed = [(scratch, SCRATCH_SENTINEL)];
        for &(off, val) in seed.iter().chain(scratch_seed.iter()) {
            lowerer.emit_mov_reg_imm64(RAX, val as u64);
            lowerer.store_rax(off);
        }

        let ops = phi_copy_sequence(copies).expect("the fixture's copies sequentialise");
        for op in ops.iter().copied() {
            lowerer
                // No `defer_publish`: this fixture drives the memory path only
                // (`src_node_of`/`phi_of_dst` are empty, so nothing publishes a
                // register and nothing can alias one).
                .emit_copy_op(op, &HashMap::new(), &HashMap::new(), &[], &mut Vec::new())
                .expect("every location in this backend is a frame word");
        }

        lowerer.load_to_rax(read_back.unwrap_or(scratch));
        // add rsp, frame_size ; pop rbp ; ret
        lowerer.buf.emit(&[0x48, 0x81, 0xC4]);
        lowerer.buf.emit(&frame.to_le_bytes());
        lowerer.buf.emit_byte(0x5D);
        lowerer.buf.emit_byte(0xC3);
        assert!(!lowerer.buf.overflowed(), "the harness body must fit");

        let cm = CompiledMethod::new(lowerer.buf);
        // SAFETY: the emitted body takes no arguments, reads only its own
        // frame, calls nothing and returns an i64 in RAX.
        let value = unsafe { cm.try_call(&[]) }.expect("the harness body runs");
        (value, ops)
    }

    fn count_kind(ops: &[CopyOp], f: impl Fn(&CopyOp) -> bool) -> usize {
        ops.iter().copied().filter(|o| f(o)).count()
    }

    /// The swap loop's back edge, at the machine level: `a <- b, b <- a`.
    ///
    /// Sequential emission through RAX put `b`'s value in BOTH words. This is
    /// the wrong-code witness, asserted by running the bytes.
    #[test]
    fn a_two_element_phi_cycle_really_swaps_the_two_frame_words() {
        let (a, b) = (8i32, 16i32);
        let seed = [(a, 0x1111_1111i64), (b, 0x2222_2222i64)];
        let copies = [(a, b), (b, a)];

        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        assert_eq!(got_a, 0x2222_2222, "a must receive b's PRE-copy value");
        assert_eq!(
            got_b, 0x1111_1111,
            "b must receive a's PRE-copy value — 0x22222222 here is the old \
             sequential-emission bug, in which both words ended up holding b",
        );

        // One save/restore pair breaks the cycle; the third op is the move.
        assert_eq!(ops.len(), 3, "{ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Restore { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Move { .. })), 1);

        // …and the scratch word really is where the parked value went.
        let (scratch_after, _) = parallel_copy_harness(&seed, &copies, None);
        assert_ne!(
            scratch_after, SCRATCH_SENTINEL,
            "a cycle must go through the reserved scratch word",
        );
    }

    /// A three-element cycle rotates; the last move IS the restore, so it costs
    /// one save, two moves and one restore.
    #[test]
    fn a_three_element_phi_cycle_rotates_the_frame_words() {
        let (a, b, c) = (8i32, 16i32, 24i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64)];
        // a <- b, b <- c, c <- a
        let copies = [(a, b), (b, c), (c, a)];

        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        assert_eq!((got_a, got_b, got_c), (2, 3, 1), "{ops:?}");

        assert_eq!(ops.len(), 4, "one save, two moves, one restore: {ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Restore { .. })), 1);
    }

    /// The acyclic majority — every merge that is not a permutation — must be
    /// unchanged: one load + one store per copy, and the scratch word untouched.
    #[test]
    fn an_acyclic_phi_chain_emits_the_minimal_moves_and_no_scratch() {
        let (a, b, c) = (8i32, 16i32, 24i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64)];
        // b <- a, c <- b. Gather order would overwrite b before c reads it.
        let copies = [(b, a), (c, b)];

        let (got_b, ops) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        assert_eq!(got_b, 1, "b <- a");
        assert_eq!(got_c, 2, "c must read b's PRE-copy value: {ops:?}");

        assert_eq!(
            ops,
            vec![
                CopyOp::Move {
                    from: frame_word_loc(b).expect("a frame word"),
                    to: frame_word_loc(c).expect("a frame word"),
                },
                CopyOp::Move {
                    from: frame_word_loc(a).expect("a frame word"),
                    to: frame_word_loc(b).expect("a frame word"),
                },
            ],
            "an acyclic web must cost exactly one move per copy",
        );

        let (scratch_after, _) = parallel_copy_harness(&seed, &copies, None);
        assert_eq!(
            scratch_after, SCRATCH_SENTINEL,
            "an acyclic web must not touch the reserved scratch word",
        );
    }

    /// A copy to itself is not a move: it must emit nothing at all, so a merge
    /// whose phi already lives in its source's word costs zero instructions.
    #[test]
    fn a_self_copy_emits_nothing() {
        let ops = phi_copy_sequence(&[(8, 8), (16, 16)]).expect("sequentialises");
        assert!(ops.is_empty(), "{ops:?}");
    }

    /// ONE scratch word is enough however many cycles an edge contains: the
    /// sequencer always consumes a save before it starts the next cycle. If
    /// that ever stopped being true the saves would nest and the single
    /// reserved word would be clobbered, so pin it here — this file's frame
    /// reservation is what depends on it.
    #[test]
    fn disjoint_phi_cycles_never_nest_their_saves() {
        let (a, b, c, d) = (8i32, 16i32, 24i32, 32i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64), (d, 4i64)];
        let copies = [(a, b), (b, a), (c, d), (d, c)];

        let mut saved = false;
        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        for op in &ops {
            match op {
                CopyOp::Save { .. } => {
                    assert!(!saved, "a second save before the first restore: {ops:?}");
                    saved = true;
                }
                CopyOp::Restore { .. } => {
                    assert!(saved, "a restore with nothing saved: {ops:?}");
                    saved = false;
                }
                CopyOp::Move { .. } => {}
            }
        }
        assert!(!saved, "an unconsumed save: {ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 2);

        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        let (got_d, _) = parallel_copy_harness(&seed, &copies, Some(d));
        assert_eq!((got_a, got_b, got_c, got_d), (2, 1, 4, 3));
    }

    /// A register is representable in the shared `ValueLoc` but unreachable
    /// here — this backend keeps every value in its home frame word. Refused,
    /// not mis-emitted as an offset.
    #[test]
    fn a_register_location_is_refused_rather_than_emitted_as_an_offset() {
        let err = frame_word_off(ValueLoc::Reg(crate::regalloc::PhysReg::gp(3)))
            .expect_err("a register is not a frame word");
        assert!(matches!(err.reason, BailoutReason::Internal(_)), "{err:?}",);
        // …and offset 0 (`[rbp - 0]` is the saved caller RBP) is not a location.
        assert!(frame_word_loc(0).is_err());
        assert!(frame_word_loc(-8).is_err());
    }

    /// The scratch is a BOOKKEEPING word: it sits below `first_spill`, so no
    /// colour `plan_slots` hands out can ever land on it, and the five reserved
    /// words are contiguous with no gap for a coloured slot to hide in.
    ///
    /// Also the frame arithmetic: `estimate_frame_bytes` (which `lower_inner`
    /// bounds against) must still equal the frame `Lowerer::new` lays out. The
    /// constructor pins that with a `debug_assert_eq!`; this asserts it in a
    /// release build too, and from the published offsets rather than from a
    /// repetition of the same sum.
    #[test]
    fn the_phi_scratch_word_is_reserved_below_the_spill_band() {
        for &num_locals in &[0usize, 1, 8] {
            let (graph, schedule) = add_one_graph();
            let plan = plan_slots(&graph, &schedule, None);
            let empty: HashMap<usize, bool> = HashMap::new();
            let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
            let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
            let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
            let no_frame_sites = crate::ir::IrInlineFrameSites::default();
            let buf = ExecutableBuffer::new(4096).expect("executable buffer");
            let helpers = no_helpers();
            let lowerer = Lowerer::new(
                &graph,
                &schedule,
                buf,
                0,
                num_locals,
                &plan,
                &helpers,
                &empty,
                &[],
                None,
                &no_direct,
                &no_ic,
                &no_compact,
                &no_frame_sites,
            );

            // The five bookkeeping words are contiguous and end at first_spill.
            assert_eq!(lowerer.shadow_thread_slot_off, lowerer.sp_id_slot_off + 8);
            assert_eq!(
                lowerer.shadow_savebase_slot_off,
                lowerer.shadow_thread_slot_off + 8
            );
            assert_eq!(
                lowerer.shadow_savetop_slot_off,
                lowerer.shadow_savebase_slot_off + 8
            );
            assert_eq!(
                lowerer.phi_copy_scratch_slot_off,
                lowerer.shadow_savetop_slot_off + 8,
                "the scratch is the fifth reserved word",
            );
            assert_eq!(
                lowerer.first_spill,
                lowerer.phi_copy_scratch_slot_off + 8,
                "the spill band starts one word above the scratch",
            );

            // No coloured slot can collide with it.
            for color in 0..plan.slots as i32 {
                assert_ne!(
                    lowerer.first_spill + color * 8,
                    lowerer.phi_copy_scratch_slot_off,
                );
            }
            assert!(lowerer.first_spill <= lowerer.spill_cap_off);

            // The estimate `lower_inner` bounds against is the frame that got
            // built — including the fifth reserved word.
            let needs = scan_frame_needs(&graph, &helpers);
            assert_eq!(
                lowerer.frame_size,
                estimate_frame_bytes(num_locals, plan.slots, &needs) as i32,
            );
            // …and that number really does account for locals + 5 bookkeeping
            // words + the spill band + the callee-saved save bands + the
            // 16-byte stack-arg reserve + the 32-byte ABI shadow.
            // `add_one_graph` needs no context slot and stages no call
            // arguments.
            //
            // The two save bands are read from the same functions the frame
            // was laid out with rather than spelled as literals: they are
            // platform- and flag-dependent (`IR_LOWER_SAVED_XMMS` is empty on
            // System V; both are empty with the linear-scan path off), and a
            // literal here would pin this test to one configuration.
            let locals_size = (num_locals as i32) * 8;
            let bookkeeping = 8 * 5;
            // `ir_deopt_regs_bytes` joined the other two on 2026-09-05, when
            // the register image went default-on. Read, not spelled, for the
            // reason the comment above gives.
            let saved = ir_saved_xmm_bytes() + ir_saved_gpr_bytes() + ir_deopt_regs_bytes();
            let tail = 32 + 16;
            assert_eq!(
                lowerer.frame_size,
                ((locals_size + bookkeeping + (plan.slots as i32) * 8 + saved + tail) + 15) & !15,
            );
            assert_eq!(lowerer.spill_cap_off, lowerer.frame_size - tail - saved);
            // Offsets are 1-based — `[rbp - 0]` is the saved caller RBP — so the
            // first spill word sits one word past the locals + bookkeeping bytes.
            assert_eq!(lowerer.first_spill, locals_size + bookkeeping + 8);
        }
    }

    /// End to end, on the shape the fix exists for.
    ///
    /// ```java
    /// static int f(int a, int b, int n) {
    ///     for (int i = 0; i < n; i++) { int t = a; a = b; b = t; }
    ///     return a - b;
    /// }
    /// ```
    ///
    /// The two loop-header phis are each other's back-edge value, so the back
    /// edge's parallel copy is a two-element cycle. Before the scratch word this
    /// method REFUSED to compile (`UnsupportedShape("cyclic phi parallel
    /// copy")`) and dropped to a lower tier; before that it compiled to wrong
    /// code. `a - b` is the sharp readout: `0` is what both duplication bugs
    /// (both words ending up with `a`, or both with `b`) produce.
    #[test]
    fn the_swap_loop_compiles_and_swaps() {
        //  0: iconst_0     03
        //  1: istore_3     3e          i = 0
        //  2: iload_3      1d      ← loop header
        //  3: iload_2      1c
        //  4: if_icmpge 17 a2 00 0d
        //  7: iload_1      1b          swap through the operand stack:
        //  8: iload_0      1a          stack = [b, a]
        //  9: istore_1     3c          b = a
        // 10: istore_0     3b          a = b
        // 11: iinc 3,1     84 03 01
        // 14: goto 2       a7 ff f4
        // 17: iload_0      1a
        // 18: iload_1      1b
        // 19: isub         64
        // 20: ireturn      ac
        let code = [
            0x03, 0x3e, 0x1d, 0x1c, 0xa2, 0x00, 0x0d, 0x1b, 0x1a, 0x3c, 0x3b, 0x84, 0x03, 0x01,
            0xa7, 0xff, 0xf4, 0x1a, 0x1b, 0x64, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 3, 4).expect(
            "the swap loop must COMPILE — a None here is the cyclic-parallel-copy \
             refusal coming back, which drops the method a tier",
        );
        // `ireturn` leaves a 32-bit value in the return register, so the raw
        // i64 readout carries an untouched upper half and a negative result
        // reads as its u32 bit pattern (-4 as 0xFFFF_FFFC). Sign-extend before
        // comparing, or a correct swap reports as a failure.
        let f = |a: i64, b: i64, n: i64| {
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            let raw = unsafe { cm.try_call(&[a, b, n]).expect("call") };
            raw as i32 as i64
        };
        assert_eq!(f(3, 7, 0), -4, "no iterations: 3 - 7");
        assert_eq!(f(3, 7, 1), 4, "one swap: 7 - 3 (0 would mean a == b)");
        assert_eq!(f(3, 7, 2), -4, "two swaps: back to 3 - 7");
        assert_eq!(f(3, 7, 3), 4, "three swaps");
        assert_eq!(f(-9, 5, 1), 14, "5 - (-9)");
    }

    // ── Inlined caller scopes → `FrameState::caller` ─────────────────────

    /// A trivially lowerable graph (`Start → Proj ctrl/mem → Param(0) →
    /// Const(7) → Return`) with no safepoints; the caller pushes whatever
    /// snapshots the test needs. Returns the `Const` node id, which resolves to
    /// `FrameValue::Int(7)` with no machine location — the simplest slot a
    /// snapshot can name.
    fn scope_fixture_graph() -> (Graph, NodeId) {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let p0 = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let k = g.add(Op::Const(7), IrType::Int, vec![], None);
        let ret = g.add(Op::Return, IrType::Void, vec![ctrl, p0], None);
        g.exit = ret;
        (g, k)
    }

    /// Resolve `graph.safepoints[index]` through a real `Lowerer`, i.e. exactly
    /// the path `build_deopt_points` takes.
    fn resolve_snapshot(graph: &Graph, index: usize) -> FrameState {
        let schedule = ir_schedule::schedule(graph);
        let plan = plan_slots(graph, &schedule, None);
        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let lowerer = Lowerer::new(
            graph,
            &schedule,
            buf,
            1,
            1,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &no_frame_sites,
        );
        lowerer.resolve_frame_state(index, &graph.safepoints[index])
    }

    /// A held monitor lowers with `relock` saying whether the compiled code
    /// took the lock itself. A live monitor op on the object ⇒ `false` (the
    /// thread already holds it). Every monitor op on it killed, the way
    /// `apply_ea_to_ir`'s lock elision leaves them ⇒ `true` (the resume must
    /// acquire it).
    #[test]
    fn a_held_monitor_is_marked_relock_only_when_its_ops_were_elided() {
        // aload_0; monitorenter; aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc3, 0xb1, 0, 0];
        let live = IrBuilder::new(1, 1).build(&code, 5).expect("build");
        let index = live
            .safepoints
            .iter()
            .position(|s| s.bci == 3)
            .expect("a snapshot at the monitorexit");

        let fs = resolve_snapshot(&live, index);
        assert_eq!(fs.monitors.len(), 1, "the lock is recorded");
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock, "a live lock is not re-acquired");

        let mut elided = IrBuilder::new(1, 1).build(&code, 5).expect("build");
        let monitor_ops: Vec<NodeId> = elided
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::MonitorEnter | Op::MonitorExit))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert_eq!(monitor_ops.len(), 2);
        for id in monitor_ops {
            elided.kill(id);
        }
        let fs = resolve_snapshot(&elided, index);
        assert_eq!(fs.monitors.len(), 1, "an elided lock is still recorded");
        assert!(
            fs.monitors[0].relock,
            "no live monitor op names the object, so the resume must acquire it"
        );
    }

    /// Re-entrant locking of one object is ONE `MonitorInfo` with
    /// `lock_depth` 2 — the install verifier refuses two entries on one object.
    #[test]
    fn a_reentrant_lock_coalesces_into_one_entry_with_its_depth() {
        // aload_0; monitorenter; aload_0; monitorenter; aload_0; monitorexit;
        // aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc2, 0x2a, 0xc3, 0x2a, 0xc3, 0xb1, 0, 0];
        let g = IrBuilder::new(1, 1).build(&code, 9).expect("build");
        let index = g
            .safepoints
            .iter()
            .position(|s| s.bci == 5)
            .expect("a snapshot at the inner monitorexit");
        assert_eq!(g.safepoints[index].monitors.len(), 2, "two enters recorded");
        let fs = resolve_snapshot(&g, index);
        assert_eq!(fs.monitors.len(), 1);
        assert_eq!(fs.monitors[0].lock_depth, 2);
    }

    /// Round 11 wave 14 (lane fib): once `ir_optimize::elide_nested_monitors`
    /// deleted the inner region, a frame inside it is TWO entries on the one
    /// object -- the level the compiled code holds (`relock == false`), then
    /// the elided one (`relock == true`) -- and a frame outside it is the
    /// ordinary single held entry. The resume enters the second entry once, so
    /// the thread holds the object twice, as the interpreter frame expects.
    #[test]
    fn r11w14_a_nested_elided_lock_splits_into_held_and_relock_entries() {
        let code = [0x2a, 0xc2, 0x2a, 0xc2, 0x2a, 0xc3, 0x2a, 0xc3, 0xb1, 0, 0];
        let mut g = IrBuilder::new(1, 1).build(&code, 9).expect("build");
        assert_eq!(crate::ir_optimize::elide_nested_monitors(&mut g), 1);
        let inner = g
            .safepoints
            .iter()
            .position(|s| s.bci == 5)
            .expect("a snapshot at the inner monitorexit");
        let fs = resolve_snapshot(&g, inner);
        assert_eq!(fs.monitors.len(), 2, "held and elided levels are split");
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock, "the outer level is still held");
        assert_eq!(fs.monitors[1].lock_depth, 1);
        assert!(
            fs.monitors[1].relock,
            "the elided level must be re-acquired"
        );
        assert_eq!(fs.monitors[0].object, fs.monitors[1].object);

        let outer = g
            .safepoints
            .iter()
            .position(|s| s.bci == 7)
            .expect("a snapshot at the outer monitorexit");
        let fs = resolve_snapshot(&g, outer);
        assert_eq!(fs.monitors.len(), 1);
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock);
    }

    /// Every deopt frame this tier lowers is FLAT — one scope, `caller: None`.
    ///
    /// That was already true of every compile before round 10 wave 9; what
    /// changed is that it is now true by construction rather than because the
    /// scope table nobody populated happened to be empty. `ir::InlineScopeTable`
    /// and `Lowerer::caller_chain_for` were retired together (the read side was
    /// wired to production and the write side had no caller outside
    /// `#[cfg(test)]`, which made a `rg` for the table report inlined scope
    /// support this tier has never had). The tests that exercised chain
    /// building went with them; what they were really covering — that an
    /// unresumable CALLER sinks the whole point, and that the walk is bounded —
    /// is `deopt.rs`'s own coverage of `frame_state_is_resumable`, which still
    /// walks `FrameState::caller` because the single-pass producer can build
    /// one.
    #[test]
    fn every_lowered_frame_is_flat() {
        let (mut g, _k) = scope_fixture_graph();
        g.safepoints
            .push(SafepointSnapshot::new(4, vec![NO_NODE], vec![], Vec::new()));
        let fs = resolve_snapshot(&g, 0);
        assert_eq!(fs.bci, 4);
        assert!(
            fs.caller.is_none(),
            "this tier publishes no caller chains, and says so in \
             `resolve_frame_state`"
        );
        assert!(crate::deopt::frame_state_is_resumable(&fs));
    }

    /// Every `DeoptimizationPoint` this file builds carries
    /// `ResumeSemantics::for_reason(reason)` — the convention, written down
    /// instead of re-derived by each consumer. `build_deopt_points` is the
    /// site under test; the two guard sites (`Op::Guard`, `emit_deopt_unless`)
    /// box their points into code and are covered by the source witness below.
    #[test]
    fn every_deopt_point_stamps_for_reason() {
        // iconst_5; iconst_3; iadd; iconst_2; imul; ireturn — two deopt points
        // (bci 2 and bci 4), the same fixture `test_deopt_points_resolve_*` uses.
        let code = [0x08, 0x06, 0x60, 0x05, 0x68, 0xac, 0, 0];
        let cm = compile_via_ir_no_opt(&code, 6, 0, 0);
        assert!(
            !cm.deopt_points.is_empty(),
            "fixture must emit deopt points"
        );
        for p in &cm.deopt_points {
            assert_eq!(
                p.semantics,
                ResumeSemantics::for_reason(p.reason),
                "deopt point at +{:#x} (reason {:?})",
                p.native_offset,
                p.reason
            );
            assert_eq!(
                p.semantics,
                ResumeSemantics::REEXECUTE,
                "a resume point before the bytecode re-executes it"
            );
        }
    }

    /// Source witness: no `DeoptimizationPoint` literal in this file may omit
    /// `semantics`. The two guard sites bake their point's *address* into
    /// emitted code and are never handed back to a test, so the field's
    /// presence there cannot be asserted behaviourally.
    #[test]
    fn every_deopt_point_literal_names_its_semantics() {
        let src = include_str!("ir_lower.rs");
        let literals = src.matches("DeoptimizationPoint {").count();
        let stamped = src.matches("semantics: ResumeSemantics::").count();
        assert!(
            stamped >= literals,
            "{literals} `DeoptimizationPoint` literal(s) but only {stamped} \
             `semantics:` initialiser(s) — a construction site is inferring \
             the re-execute convention again instead of recording it"
        );
    }

    // ── Linear-scan register residency ──────────────────────────────────

    /// `double f(double a) { return a * a * 2.0 + a; }` as a hand-built graph.
    ///
    /// Hand-built rather than compiled from `dload_0; dmul; …`, because the
    /// point of these tests is the ALLOCATION, and a bytecode-built graph
    /// carries a `SafepointSnapshot` per bci whose interaction with pinning is
    /// the subject of its own test below.
    fn fp_chain_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Double, vec![start], Some(0));
        let sq = graph.add(Op::Mul, IrType::Double, vec![a, a], Some(1));
        let two = graph.add(
            Op::ConstF(2.0f64.to_bits()),
            IrType::Double,
            vec![],
            Some(2),
        );
        let scaled = graph.add(Op::Mul, IrType::Double, vec![sq, two], Some(3));
        let sum = graph.add(Op::Add, IrType::Double, vec![scaled, a], Some(4));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], Some(5));
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    #[test]
    fn linear_scan_promotes_fp_values_and_nothing_else() {
        let (graph, schedule) = fp_chain_graph();
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("the colouring verifies");

        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("an FP arithmetic chain has something to promote");

        assert!(residency.promoted > 0);
        assert_eq!(
            residency.demoted, 0,
            "the two liveness models must agree on a straight-line graph"
        );
        for (id, reg) in residency.reg_of.iter().enumerate() {
            let Some(reg) = reg else { continue };
            assert!(
                IR_LOWER_LS_XMMS.contains(reg),
                "n{id} was given xmm{reg}, which is outside the file this \
                 backend may clobber"
            );
            assert!(
                matches!(graph.nodes[id].ty, IrType::Float | IrType::Double),
                "n{id} is {:?} — only FP values may take a register here, which \
                 is what makes a reference at a safepoint unrepresentable",
                graph.nodes[id].ty
            );
        }
    }

    /// A value named by a deopt frame state must still be promotable, and its
    /// home word must still be written.
    ///
    /// This is the regression witness for the check that nearly made the whole
    /// wiring inert: `plan_slots` marks every deopt-named value
    /// `SlotClass::Pinned` (= never shares a frame word), and refusing to
    /// promote that class would have undone `release_deopt_pins` for exactly
    /// the values it exists to release. `IrBuilder` names essentially every
    /// value in some frame state, so this is not a corner case — it is the
    /// common case on real bytecode.
    #[test]
    fn a_deopt_named_value_is_still_promotable() {
        let (mut graph, _) = fp_chain_graph();
        // Name every FP value in a frame state, as `IrBuilder` would.
        let fp: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.ty, IrType::Float | IrType::Double))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert!(!fp.is_empty());
        graph.safepoints.push(SafepointSnapshot::new(
            3,
            fp.clone(),
            fp.clone(),
            Vec::new(),
        ));
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        // Precondition: the colourer really does pin them, so this test is
        // asserting against the state it means to.
        assert!(
            fp.iter()
                .any(|&id| plan.class[id as usize] == Some(SlotClass::Pinned)),
            "the colourer must pin a deopt-named value"
        );

        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect(
                "a deopt-named FP value must still be promotable — write-through \
                 keeps its home word correct at every bci",
            );
        assert!(residency.promoted > 0);
    }

    /// Round 11 wave 6 (`r11w5-ircore-back-edge-poll-evicts-fp-loop-values`):
    /// the `double` accumulator of a counted loop keeps ONE register across
    /// the back edge, and when that register is caller-saved the latch's poll
    /// reloads it. Before the fix the poll clobbered every caller-saved XMM,
    /// so on System V the accumulator was split at the edge and then refused
    /// (split residency is off), and every read in the loop went to memory.
    #[test]
    fn r11w6_a_carried_double_keeps_its_register_across_the_poll() {
        if !ir_poll_preserves_fp() {
            return;
        }
        // static double f(int n) { double s = 0; for (int i = 0; i < n; i++) s += i; return s; }
        //  0: dconst_0  1: dstore_1  2: iconst_0  3: istore_3
        //  4: iload_3   5: iload_0   6: if_icmpge 20
        //  9: dload_1  10: iload_3  11: i2d  12: dadd  13: dstore_1
        // 14: iinc 3,1  17: goto 4  20: dload_1  21: dreturn
        let code = [
            0x0e, 0x48, 0x03, 0x3e, 0x1d, 0x1a, 0xa2, 0x00, 0x0e, 0x27, 0x1d, 0x87, 0x63, 0x48,
            0x84, 0x03, 0x01, 0xa7, 0xff, 0xf3, 0x27, 0xaf, 0, 0,
        ];
        // Unoptimized, like the model test above: the back edge is the subject.
        let graph = IrBuilder::new(1, 4).build(&code, 22).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("the loop has something to promote");
        let phi = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Phi) && n.ty == IrType::Double)
            .expect("the accumulator is a double phi at the loop header");
        let reg = residency.reg_of[phi]
            .expect("the carried double is resident, not split at the back edge");
        if !IR_LOWER_SAVED_XMMS.contains(&reg) {
            assert!(
                residency
                    .poll_fp_reloads
                    .values()
                    .any(|ids| ids.contains(&(phi as NodeId))),
                "xmm{reg} is caller-saved, so the latch's poll must reload n{phi}: \
                 {:?}",
                residency.poll_fp_reloads
            );
        }
    }

    /// A RIP-relative displacement must resolve to the word it names.
    ///
    /// The one property both RIP emitters rest on, and the one whose failure
    /// is silent: x86-64 adds the displacement to the address of the NEXT
    /// instruction, so `here + len + disp` has to BE the target. A `len` that
    /// forgets the trailing immediate — 6 instead of 7 for the poll's `imm8`,
    /// or 6 instead of 10 for the guard's `imm32` — still assembles, still
    /// runs, and reads a neighbouring global forever.
    #[test]
    fn a_rip_displacement_resolves_to_its_target() {
        // Both encoded lengths in use: the poll's `F6 05 <disp32> <imm8>` and
        // the epoch guard's `81 3D <disp32> <imm32>`.
        for len in [7usize, 10] {
            for (here, target) in [
                (0x1_0000usize, 0x2_0000usize), // forward
                (0x2_0000, 0x1_0000),           // backward
                (0x1000, 0x1000),               // degenerate: names itself
                (0usize, i32::MAX as usize),    // the far positive edge
            ] {
                let disp = rip_disp32(here, len, target)
                    .unwrap_or_else(|| panic!("len={len} here={here:#x} should be in reach"));
                let next = here.wrapping_add(len);
                // Cast: two's-complement re-add of a signed displacement.
                let resolved = (next as i64).wrapping_add(disp as i64) as usize;
                assert_eq!(
                    resolved, target,
                    "len={len}: disp {disp} from {here:#x} resolved to {resolved:#x}, \
                     not {target:#x}",
                );
            }
        }
        // Out of ±2GB in both directions is refused, so the caller emits its
        // materialize-the-address fallback rather than a truncated disp32.
        assert!(rip_disp32(0, 10, u32::MAX as usize + 1).is_none());
        assert!(rip_disp32(usize::MAX / 2, 10, 0).is_none());
    }

    /// The GP file may not name a register this emitter uses for a FIXED
    /// purpose, on either ABI.
    ///
    /// The argument that RSI/RDI are promotable on Win64 rests entirely on
    /// them being neither an argument register nor a deopt-trampoline
    /// argument THERE, while being both on System V — a claim about six
    /// `#[cfg]`-selected constants that no compiler checks and that a reader
    /// has to assemble by hand. It is checked here instead, and it is checked
    /// on whichever platform the tests run on, so the arm that is wrong is the
    /// arm that fails.
    ///
    /// This is the invariant whose absence produced the two clobber gaps
    /// `docs/jit/linear-scan-wiring.md` records under "Calls the op model does
    /// not see": a register the allocator believed survived a call, destroyed
    /// by an emitter that never told the model it writes there.
    #[test]
    fn the_gp_file_names_no_register_this_emitter_reserves() {
        let mut reserved: Vec<(u8, &str)> = vec![
            (RAX, "RAX — the GP value tier"),
            (RCX, "RCX — the GP value tier"),
            (RDX, "RDX — IDIV and FCmp's SETcc"),
            (R10, "R10 — thread pointer / shadow-stack scratch"),
            (R11, "R11 — safepoint flag and epoch-guard scratch"),
            (DEOPT_ARG0, "DEOPT_ARG0"),
            (DEOPT_ARG1, "DEOPT_ARG1"),
            (DEOPT_ARG2, "DEOPT_ARG2"),
        ];
        for &r in CALL_ARG_REGS.iter() {
            reserved.push((r, "CALL_ARG_REGS"));
        }
        for &r in ENTRY_ABI_REGS.iter() {
            reserved.push((r, "ENTRY_ABI_REGS"));
        }
        for &f in IR_LOWER_LS_GPRS.iter() {
            if let Some((_, why)) = reserved.iter().find(|(r, _)| *r == f) {
                panic!(
                    "IR_GP_LINEAR_SCAN names r{f}, which this emitter reserves: {why}. \
                     A value promoted there is destroyed by an emission the \
                     MachineModel does not model as a clobber."
                );
            }
        }
        // …and the file is exactly as wide as the platform's callee-saved set
        // allows, so a future edit that adds a register has to come here.
        let expected = if cfg!(windows) { 7 } else { 5 };
        assert_eq!(
            IR_LOWER_LS_GPRS.len(),
            expected,
            "the GP file is {} on this platform, expected {expected}",
            IR_LOWER_LS_GPRS.len(),
        );
        // The narrow prefix the kill switch restores must be a PREFIX, or
        // `ir_gp_file()`'s slice is not the historical file.
        assert_eq!(
            &IR_LOWER_LS_GPRS[..crate::regalloc::xmm_roles::IR_GP_LINEAR_SCAN_NARROW],
            &[3u8, 12, 13, 14, 15][..],
            "the narrow prefix is no longer RBX + R12-R15",
        );
    }

    /// The GC cliff, stated as a property rather than a comment: no reference
    /// can be register-resident, so `emit_safepoint_map`'s frame-slot-only
    /// publication stays complete.
    #[test]
    fn a_reference_is_never_register_resident() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        // A live array reference and an int index, both genuinely read.
        let arr = graph.add(Op::Param(0), IrType::Ref, vec![start], Some(0));
        let idx = graph.add(Op::Param(1), IrType::Int, vec![start], Some(1));
        let elem = graph.add(
            Op::ArrayLoad(MemKind::Double),
            IrType::Double,
            vec![ctrl, mem, arr, idx],
            Some(2),
        );
        let doubled = graph.add(Op::Add, IrType::Double, vec![elem, elem], Some(3));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, doubled], Some(4));
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("the FP values are promotable");
        assert_eq!(
            residency.reg_of[arr as usize], None,
            "a reference took a register; `emit_safepoint_map` publishes frame \
             slots only, so the collector could neither see nor relocate it"
        );
        assert_eq!(
            residency.reg_of[idx as usize], None,
            "an int took a register, but this file's register set is XMM-only"
        );
        // `elem`, not `doubled`: since `ir_residency_pays_enabled` a value read
        // ONCE is not promoted (its register cannot repay the prologue save it
        // costs), and `doubled` is read once, by the return. `elem` is read
        // twice — it is both inputs of the `Add` — so it is the FP value this
        // graph can promote, and asserting on it keeps the two checks above
        // non-vacuous for the reason they were written.
        assert!(
            residency.reg_of[elem as usize].is_some(),
            "the FP value must be promoted, or the two assertions above are \
             vacuous"
        );
        let _ = doubled;
    }

    /// The GP half of the same invariant, at its DEFAULT.
    ///
    /// The bank match in `plan_register_residency` names
    /// `a_reference_is_never_promoted_into_the_gp_file` as what pins it, and
    /// until 2026-09-09 the name pointed at nothing. It does now, and it pins
    /// the DEFAULT rather than an absolute: `CRATONVM_JIT_IR_REF_RESIDENCY=1`
    /// admits a reference deliberately, and `invalidate_ref_residency` is what
    /// it owes for that. With the flag at its default the answer must be the
    /// old one, whatever else has changed around it.
    #[test]
    fn a_reference_is_never_promoted_into_the_gp_file() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let obj = graph.add(Op::Param(0), IrType::Ref, vec![start], Some(0));
        // Two reads of `obj`, so `ir_residency_pays_enabled` cannot decline it
        // for the unrelated reason that a once-read value never repays the
        // prologue save. Both are `Op::Cmp`, which reaches no helper — so
        // nothing but the type is keeping this value out of the file.
        let a = graph.add(
            Op::Cmp(crate::ir::CmpOp::Ne),
            IrType::Int,
            vec![obj, obj],
            Some(1),
        );
        let b = graph.add(
            Op::Cmp(crate::ir::CmpOp::Eq),
            IrType::Int,
            vec![obj, obj],
            Some(2),
        );
        let sum = graph.add(Op::Add, IrType::Int, vec![a, b], Some(3));
        let sum2 = graph.add(Op::Add, IrType::Int, vec![sum, sum], Some(4));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum2], Some(5));
        let _ = mem;
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        let Some(residency) =
            plan_register_residency(&graph, &schedule, &plan).expect("the allocation verifies")
        else {
            return;
        };
        assert_eq!(
            residency.gp_reg_of[obj as usize], None,
            "a reference took a GP register at the DEFAULT setting; the oop map \
             names frame slots only, so a collector could neither see nor \
             relocate it, and nothing invalidates the copy"
        );
        assert!(
            residency.gp_reg_of[sum as usize].is_some(),
            "the int must be promoted, or the assertion above is vacuous"
        );
    }

    // ── Phi residency ────────────────────────────────────────────────
    //
    // A loop counter and a loop accumulator are `Op::Phi` at the loop header.
    // While phis were excluded from the residency plan, the optimizing tier
    // read both out of a frame word on every iteration while the baseline tier
    // it supersedes coloured them into callee-saved GPRs -- the measured
    // inversion `docs/JIT_OPTIMIZATION.md` tabulates at 2.7-3.2x on array
    // kernels. These five tests pin what admitting them means, in the order the
    // obligations fall due: the population moves, the sub-flag still takes it
    // back, the GC obligation does not move, the parallel copy still leaves one
    // home and one register per phi, and the emitted code computes the same
    // answer either way.

    /// `int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }`
    ///
    /// The smallest program with the shape this whole line of work is about:
    /// exactly two loop-carried values, and both of them a phi at the header.
    const COUNTED_LOOP_SUM: [u8; 23] = [
        0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02,
        0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
    ];

    /// `int f(int n){ int a=1,b=2; for(int i=0;i<n;i++){ int t=a; a=b; b=t; } return a; }`
    ///
    /// The swap runs on the operand stack (`iload_1; iload_2; istore_1;
    /// istore_2`), so it needs no temporary local -- which makes the loop
    /// header's two phis each other's back-edge value, i.e. a copy CYCLE.
    /// `f(n)` is 2 for odd `n` and 1 for even `n`.
    const SWAP_LOOP: [u8; 25] = [
        0x04, 0x3c, // 0: iconst_1; istore_1        a = 1
        0x05, 0x3d, // 2: iconst_2; istore_2        b = 2
        0x03, 0x3e, // 4: iconst_0; istore_3        i = 0
        0x1d, 0x1a, // 6: iload_3; iload_0          loop header
        0xa2, 0x00, 0x0d, // 8: if_icmpge 21
        0x1b, 0x1c, // 11: iload_1; iload_2         push a, then b
        0x3c, 0x3d, // 13: istore_1; istore_2       a = b; b = old a
        0x84, 0x03, 0x01, // 15: iinc 3, 1
        0xa7, 0xff, 0xf4, // 18: goto 6
        0x1b, 0xac, // 21: iload_1; ireturn
        0, 0,
    ];

    /// Every VALUE-typed `Op::Phi` in `graph`, in node order.
    ///
    /// `is_value_ty` and not "every phi": `IrBuilder` builds a `Memory` phi at
    /// every merge it builds a value phi at, and a counted loop therefore has
    /// one at its header. It carries no runtime value (`RegClass::of` answers
    /// `None` for `Memory`), it is never a residency candidate, and
    /// `PhiCensus` excludes it for the same reason -- so a test that counted it
    /// would be asserting against a different set from the one the census
    /// reports.
    fn phis_of(graph: &Graph) -> Vec<usize> {
        (0..graph.nodes.len())
            .filter(|&id| matches!(graph.nodes[id].op, Op::Phi) && is_value_ty(graph.nodes[id].ty))
            .collect()
    }

    /// Run `f` with the phi sub-flag pinned, so no test in this group depends
    /// on the ambient environment or on whether the flag has been declared in
    /// this process yet.
    ///
    /// `with_thread_overrides` and not `std::env::set_var`: the flag is
    /// declared (`types/src/flag_groups.rs`, `jit/ir-phi-residency`), the
    /// override mechanism reaches it, and a process-wide env write would race
    /// every other test in this binary. `ir_phi_residency_enabled` deliberately
    /// does NOT cache its answer in a `OnceLock`, which is what makes a
    /// per-thread override work at all -- if someone adds that cache, these
    /// tests start reading whichever value the first test in the binary set.
    fn with_phi_residency<R>(on: bool, f: impl FnOnce() -> R) -> R {
        cratonvm_types::flags::with_thread_overrides(
            &[(
                "CRATONVM_JIT_IR_PHI_RESIDENCY",
                Some(if on { "1" } else { "0" }),
            )],
            f,
        )
    }

    /// The induction phi and the accumulator phi of a counted `int` loop are
    /// BOTH register-resident, and the census reports nothing refused.
    ///
    /// This is the claim the admission exists to make, on the smallest program
    /// that carries it. Asserted through `plan_register_residency`'s own output
    /// rather than through emitted bytes, because the plan names *which node*
    /// moved and a byte scan cannot -- "the body got shorter" is consistent
    /// with a transient being promoted and the loop counter still reloading
    /// from `[rbp-…]` every iteration, which is exactly the state this is meant
    /// to detect the return of. The bytes are the subject of
    /// `a_counted_loop_computes_the_same_sum_with_phi_residency_forced_on`.
    ///
    /// Unoptimized on purpose, like the other residency fixtures over this same
    /// bytecode: the optimizer is free to reshape a loop header, and the
    /// subject here is the allocator's verdict on the phis the builder emits.
    ///
    /// # Why `refused() == 0` is assertable rather than optimistic
    ///
    /// Every other value in this graph declines for a reason that has nothing
    /// to do with pressure: the `Op::Const`s are materialised as immediates by
    /// every reader (`skip_const`), and `Param(0)`, `s+i`, `i+1` and the
    /// compare are each read exactly once, which `ir_residency_pays_here`
    /// refuses (`skip_single_use`). The phis are exempt from that rule and are
    /// the only values left, so they compete with nobody for a file of five
    /// GPRs — and a failure here is a real regression rather than a heuristic
    /// that moved.
    #[test]
    fn a_counted_loops_induction_and_accumulator_phis_are_both_resident() {
        with_phi_residency(true, || {
            let graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = plan_register_residency(&graph, &schedule, &plan)
                .expect("the allocation verifies")
                .expect("a counted loop promotes something");

            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the fixture must carry an induction phi AND an accumulator phi; \
                 found {phis:?}"
            );
            for &id in &phis {
                assert_eq!(
                    graph.nodes[id].ty,
                    IrType::Int,
                    "n{id} is not the `int` phi this fixture is about"
                );
                assert!(
                    residency.gp_reg_of[id].is_some(),
                    "phi n{id} reached no register, so this loop still reads its \
                     carried value out of a frame word every iteration; census {:?}",
                    residency.phi_census
                );
            }
            assert_eq!(
                residency.phi_census.resident,
                phis.len(),
                "the census disagrees with the per-node assertions above: {:?}",
                residency.phi_census
            );
            assert_eq!(
                residency.phi_census.refused(),
                0,
                "nothing in this graph competes with the phis for a register; a \
                 refusal here is a regression, not a tuning decision: {:?}",
                residency.phi_census
            );
        });
    }

    /// With the sub-flag off, the SAME fixture refuses both phis and the census
    /// says why — which is the A/B the switch exists for.
    ///
    /// Without this the test above cannot distinguish "phi admission works"
    /// from "phis were always resident and the flag does nothing".
    #[test]
    fn the_phi_sub_flag_off_refuses_the_same_two_phis_and_names_the_cause() {
        with_phi_residency(false, || {
            let graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let phis = phis_of(&graph);
            // With the phis refused this graph may promote NOTHING at all,
            // which `plan_register_residency` reports as a declined plan
            // (`Ok(None)`). That is the same answer said louder, and it is what
            // the pre-admission emitter did on every counted loop — so the
            // assertions below are conditional on there being a plan to assert
            // against.
            if let Some(residency) =
                plan_register_residency(&graph, &schedule, &plan).expect("the allocation verifies")
            {
                assert_eq!(
                    residency.phi_census.disabled,
                    phis.len(),
                    "every phi must be refused, under `PhiRefusal::Disabled` and \
                     under no other cause: {:?}",
                    residency.phi_census
                );
                assert_eq!(
                    residency.phi_census.resident, 0,
                    "a phi took a register with the sub-flag off: {:?}",
                    residency.phi_census
                );
            }
        });
    }

    /// Round 13 wave 11 (lane callcost5, proposal CC4-3): the certain
    /// refusals are the refusal loop's own -- every constant and the once-read
    /// parameter, never a phi -- and with `CRATONVM_JIT_IR_RESIDENCY_PAYS=0`
    /// (which keeps every candidate) nothing in this reference-free graph is
    /// certain to be refused.
    #[test]
    fn r13w11_certain_refusals_are_the_refusal_loops_own() {
        let graph = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let live = crate::regalloc::build_live_model(&graph, &schedule);
        let refusals = |pays: &'static str| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_RESIDENCY_PAYS", Some(pays))],
                || ls_certain_refusals(&graph, &schedule, &live),
            )
        };
        let on = refusals("1");
        assert!(
            !on.is_empty(),
            "the constants and `Param(0)` are read at most once"
        );
        for &id in &on {
            assert!(
                !matches!(graph.nodes[id as usize].op, Op::Phi),
                "phi n{id} was listed; its refusals are decided by the phi rules"
            );
        }
        for (id, node) in graph.nodes.iter().enumerate() {
            if matches!(node.op, Op::Const(_)) && live.wants_loc[id] {
                assert!(
                    on.contains(&(id as NodeId)),
                    "constant n{id} was not listed"
                );
            }
        }
        assert!(
            refusals("0").is_empty(),
            "with the pays rule off only a reference is a certain refusal"
        );
    }

    /// Round 14 wave 1 (lane calls, proposal CC5-1): the call-crossing
    /// candidate is exactly "read once, `int`/`long`, one-`store_rax` home, an
    /// `Op::Call` strictly inside its range" -- a call AT the range's end is
    /// the value's own read as an argument, not a crossing -- and the kill
    /// switch empties it.
    #[test]
    fn r14w1_a_single_use_value_is_a_call_crossing_candidate_only_across_a_call() {
        let seed = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let seed_schedule = ir_schedule::schedule(&seed);
        // Any converged model, re-pointed at the hand-built graph below: the
        // predicate reads only `pos_of` and `range`.
        let mut live = crate::regalloc::build_live_model(&seed, &seed_schedule);
        let mut g = Graph::empty(6);
        let crossing = g.add(Op::Sub, IrType::Int, vec![], None); // n0
        let call = g.add(Op::Call { info_ptr: 0 }, IrType::Int, vec![], None); // n1
        let short = g.add(Op::Sub, IrType::Long, vec![], None); // n2
        let float = g.add(Op::Sub, IrType::Float, vec![], None); // n3
        let add = g.add(Op::Add, IrType::Int, vec![], None); // n4
        let range = |lo: usize, hi: usize| Some(crate::regalloc::PosRange { lo, hi });
        live.pos_of = vec![Some(1), Some(3), Some(2), Some(1), Some(5)];
        live.range = vec![
            range(1, 5),
            range(3, 5),
            range(2, 3),
            range(1, 5),
            range(5, 6),
        ];
        let positions = |on: &'static str| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_RESIDENCY_CALL_CROSSING", Some(on))],
                || ls_call_positions(&g, &live),
            )
        };
        let call_pos = positions("1");
        assert_eq!(call_pos, vec![3]);
        assert!(positions("0").is_empty(), "the kill switch lists no call");
        let ask = |id: NodeId, uses: u32| {
            single_use_crosses_a_call(&g, &live, &call_pos, id as usize, uses)
        };
        assert!(ask(crossing, 1), "`n-2`-shaped value live across the call");
        assert!(!ask(crossing, 2), "a twice-read value is the pays rule's");
        assert!(
            !ask(short, 1),
            "the call at the range's end is its own read"
        );
        assert!(!ask(float, 1), "FP values keep their own rules");
        assert!(!ask(add, 1), "no call inside the range");
        assert!(!ask(call, 1), "a call's own result starts at the call");
        assert!(
            !single_use_crosses_a_call(&g, &live, &[], crossing as usize, 1),
            "no listed call (the kill switch), no candidate"
        );
    }

    /// Round 13 wave 13 (lane jitfix;
    /// `r13w12-snapliv-loop-header-snapshot-doubles-as-the-osr-seed-list`): an
    /// OSR entry at the header of `COUNTED_LOOP_SUM` is admitted while the
    /// header snapshot names (seeds) every value the in-loop frame at bci 9
    /// names, and refused once one of them is not seeded -- the shape of a
    /// pruned dead header local whose pre-loop value an in-loop frame still
    /// names. A frame in a block the entry cannot reach is never asked.
    #[test]
    fn r13w13_an_osr_entry_is_refused_when_a_reachable_frame_names_a_skipped_value() {
        let graph = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let header = schedule
            .blocks
            .iter()
            .position(|b| {
                let ctrl = &graph.nodes[b.ctrl as usize];
                ctrl.bytecode_pc == Some(4) && matches!(ctrl.op, Op::Merge | Op::Region)
            })
            .expect("the loop header is a block");
        // Block 0 is the dominator tree's root, the method entry.
        let start = 0usize;
        assert_ne!(start, header, "the header is not the method entry");
        let flat_at = |bci: usize| {
            graph
                .safepoints
                .iter()
                .position(|sp| sp.bci == bci && !sp.is_splice_state())
                .expect("a snapshot at that bci")
        };
        let (at_header, in_loop) = (flat_at(4), flat_at(9));
        let named: std::collections::HashSet<NodeId> = graph.safepoints[at_header]
            .locals
            .iter()
            .copied()
            .filter(|&v| v != NO_NODE)
            .collect();
        let n = graph.safepoints[in_loop].locals[0];
        assert!(named.contains(&n), "`n` is named at the header");
        let ask = |sites: &[(usize, usize)], seeded: &std::collections::HashSet<NodeId>| {
            Lowerer::osr_entry_skipped_frame_value(
                &graph, &schedule, None, sites, header, header, false, seeded,
            )
        };
        let sites = [(header, in_loop)];
        assert_eq!(
            ask(&sites, &named),
            None,
            "every value the in-loop frame names is seeded"
        );
        let mut pruned = named.clone();
        pruned.remove(&n);
        assert_eq!(
            ask(&sites, &pruned),
            Some(n),
            "`n` is defined before the header (or is its unseeded φ) and nothing seeds it"
        );
        assert_eq!(
            ask(&[], &pruned),
            None,
            "no frame, no refusal (the kill switch)"
        );
        assert_eq!(
            ask(&[(start, in_loop)], &std::collections::HashSet::new()),
            None,
            "a frame in the method's entry block is not reachable from the header"
        );
    }

    /// Round 13 wave 13 (lane jitfix): the precise half of the same check. An
    /// entry at the INNER header of a nested loop reaches the outer body's
    /// frames only through the outer header, whose φs are then written by its
    /// back edge -- so a frame there naming the outer `s` φ, which the inner
    /// header does not name, must not refuse the entry (dominance alone would).
    ///
    /// `static int f(int n){ int s=0; for(int i=0;i<n;i++) for(int j=0;j<n;j++) s+=j; return s; }`
    #[test]
    fn r13w13_an_inner_loop_entry_keeps_an_outer_phi_its_frames_name() {
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 32
        //  9: iconst_0 10: istore_3
        // 11: iload_3  12: iload_0  13: if_icmpge 26
        // 16: iload_1  17: iload_3  18: iadd  19: istore_1
        // 20: iinc 3,1 23: goto 11
        // 26: iinc 2,1 29: goto 4   32: iload_1 33: ireturn
        let code: [u8; 36] = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let graph = IrBuilder::new(1, 4)
            .build(&code, 34)
            .expect("the nested loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let header_at = |pc: usize| {
            schedule
                .blocks
                .iter()
                .position(|b| {
                    let ctrl = &graph.nodes[b.ctrl as usize];
                    ctrl.bytecode_pc == Some(pc) && matches!(ctrl.op, Op::Merge | Op::Region)
                })
                .expect("a loop header block")
        };
        let inner = header_at(11);
        let flat_at = |bci: usize| {
            graph
                .safepoints
                .iter()
                .position(|sp| sp.bci == bci && !sp.is_splice_state())
                .expect("a snapshot at that bci")
        };
        let named: std::collections::HashSet<NodeId> = graph.safepoints[flat_at(11)]
            .locals
            .iter()
            .copied()
            .filter(|&v| v != NO_NODE)
            .collect();
        // The outer body, between the outer test and the inner header.
        let outer_body = schedule
            .dom
            .idom(inner)
            .expect("the inner header has an idom");
        let at_9 = flat_at(9);
        let s_outer = graph.safepoints[at_9].locals[1];
        assert_eq!(
            graph.nodes[s_outer as usize].op,
            Op::Phi,
            "`s` at bci 9 is the outer φ"
        );
        assert!(
            !named.contains(&s_outer),
            "the inner header names its own `s` φ instead"
        );
        assert!(
            !schedule
                .dom
                .dominates(inner, schedule.node_to_block[s_outer as usize]),
            "the fast (dominance) path cannot accept the outer φ"
        );
        // Ask about `s_outer` alone: every other value the frame names counts
        // as seeded, whatever shape the builder gave it.
        let sp9 = &graph.safepoints[at_9];
        let mut seeded = named.clone();
        seeded.extend(
            sp9.locals
                .iter()
                .chain(sp9.stack.iter())
                .chain(sp9.monitors.iter())
                .copied()
                .filter(|&v| v != NO_NODE && v != s_outer),
        );
        let got = Lowerer::osr_entry_skipped_frame_value(
            &graph,
            &schedule,
            None,
            &[(outer_body, at_9)],
            inner,
            inner,
            false,
            &seeded,
        );
        assert_eq!(
            got, None,
            "the outer body is reached only through the outer header"
        );
        // The same frame at a site the entered path reaches BEFORE it re-enters
        // the outer header (the inner header block itself) does refuse.
        let before_the_outer_header = Lowerer::osr_entry_skipped_frame_value(
            &graph,
            &schedule,
            None,
            &[(inner, at_9)],
            inner,
            inner,
            false,
            &seeded,
        );
        assert_eq!(before_the_outer_header, Some(s_outer));
    }

    /// JIT round 18 wave 11 close (lane testfix18;
    /// `r18-osr-frame-premise-withdraws-protected-loop-entry-FIXED-20261006.md`): a
    /// frame listed at a block its values do not dominate is not a value the
    /// entry skips. Same nested loop as above, entered at the OUTER header:
    /// the inner header's frame (its `j` / `s` φs) paired with the outer body
    /// block BEFORE the inner header -- a pair no honest site publishes, and
    /// one the method-entry path misses just the same -- keeps the entry. The
    /// round-17 premise check refused it (the walk from the outer header
    /// reaches the outer body without entering the inner header).
    #[test]
    fn r18_testfix18_a_frame_its_site_does_not_dominate_keeps_the_entry() {
        let code: [u8; 36] = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let graph = IrBuilder::new(1, 4)
            .build(&code, 34)
            .expect("the nested loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let header_at = |pc: usize| {
            schedule
                .blocks
                .iter()
                .position(|b| {
                    let ctrl = &graph.nodes[b.ctrl as usize];
                    ctrl.bytecode_pc == Some(pc) && matches!(ctrl.op, Op::Merge | Op::Region)
                })
                .expect("a loop header block")
        };
        let (outer, inner) = (header_at(4), header_at(11));
        let outer_body = schedule
            .dom
            .idom(inner)
            .expect("the inner header has an idom");
        let flat_at = |bci: usize| {
            graph
                .safepoints
                .iter()
                .position(|sp| sp.bci == bci && !sp.is_splice_state())
                .expect("a snapshot at that bci")
        };
        let at_inner = flat_at(11);
        let named: std::collections::HashSet<NodeId> = graph.safepoints[flat_at(4)]
            .locals
            .iter()
            .copied()
            .filter(|&v| v != NO_NODE)
            .collect();
        let inner_phis: Vec<NodeId> = graph.safepoints[at_inner]
            .locals
            .iter()
            .copied()
            .filter(|&v| {
                v != NO_NODE
                    && !named.contains(&v)
                    && graph.nodes[v as usize].op == Op::Phi
                    && schedule.node_to_block[v as usize] == inner
            })
            .collect();
        assert!(
            !inner_phis.is_empty(),
            "the inner header names φs of its own"
        );
        assert!(
            !schedule.dom.dominates(inner, outer_body),
            "the pair breaks the round-17 premise"
        );
        // Everything else the frame names counts as seeded.
        let mut seeded = named.clone();
        seeded.extend(
            graph.safepoints[at_inner]
                .locals
                .iter()
                .chain(graph.safepoints[at_inner].stack.iter())
                .chain(graph.safepoints[at_inner].monitors.iter())
                .copied()
                .filter(|&v| v != NO_NODE && !inner_phis.contains(&v)),
        );
        let got = Lowerer::osr_entry_skipped_frame_value(
            &graph,
            &schedule,
            None,
            &[(outer_body, at_inner)],
            outer,
            outer,
            false,
            &seeded,
        );
        assert_eq!(
            got, None,
            "the outer header dominates the inner φs: no skipped value"
        );
    }

    /// Interpreter round i2 wave 58, lane L2
    /// (`CRATONVM_JIT_IR_OSR_EXCUSE_MEMORY_ORDER_USES`): at the INNER header of
    /// the nested loop above, a primitive value defined in the outer body and
    /// read past the entry only through memory-token slots owes the entry no
    /// seed; a value read in a block the entered path reaches first, a value
    /// φ reader, a reference, or a value with no token reader at all does not
    /// qualify.
    #[test]
    fn i58_l2_a_value_read_past_an_inner_entry_only_as_a_memory_token_owes_no_seed() {
        // `static int f(int n){ int s=0; for(int i=0;i<n;i++) for(int j=0;j<n;j++) s+=j; return s; }`
        let code: [u8; 36] = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        // A fresh graph and schedule, the inner header and the outer body, and
        // `place` to put a hand-added node in a block.
        let fresh = || {
            let graph = IrBuilder::new(1, 4)
                .build(&code, 34)
                .expect("the nested loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let inner = schedule
                .blocks
                .iter()
                .position(|b| {
                    let ctrl = &graph.nodes[b.ctrl as usize];
                    ctrl.bytecode_pc == Some(11) && matches!(ctrl.op, Op::Merge | Op::Region)
                })
                .expect("the inner header is a block");
            let outer_body = schedule
                .dom
                .idom(inner)
                .expect("the inner header has an idom");
            (graph, schedule, inner, outer_body)
        };
        fn place(schedule: &mut crate::ir_schedule::Schedule, id: NodeId, b: usize) {
            let i = id as usize;
            if schedule.node_to_block.len() <= i {
                schedule.node_to_block.resize(i + 1, usize::MAX);
            }
            schedule.node_to_block[i] = b;
        }
        let volatile_read = |ty: IrType, tag: u8| Op::LoadStatic {
            class_id: 1,
            field_index: 0,
            type_tag: tag,
            is_volatile: ty == IrType::Int,
        };
        // `stop`, read in the outer body; `burnt`'s read names it as its
        // memory token inside the inner header block (reached first: a token
        // read anywhere is fine).
        let build = |ty: IrType| {
            let (mut graph, mut schedule, inner, outer_body) = fresh();
            let ctrl = schedule.blocks[outer_body].ctrl;
            let stop = graph.add(volatile_read(ty, b'Z'), ty, vec![ctrl, ctrl], None);
            place(&mut schedule, stop, outer_body);
            let inner_ctrl = schedule.blocks[inner].ctrl;
            let burnt = graph.add(
                volatile_read(IrType::Long, b'J'),
                IrType::Long,
                vec![inner_ctrl, stop],
                None,
            );
            place(&mut schedule, burnt, inner);
            (graph, schedule, inner, outer_body, stop)
        };
        let ask =
            |graph: &Graph, schedule: &crate::ir_schedule::Schedule, id: NodeId, entry: usize| {
                Lowerer::osr_entry_value_read_only_as_memory_order(graph, schedule, id, entry)
            };

        let (graph, schedule, inner, _, stop) = build(IrType::Int);
        assert!(
            ask(&graph, &schedule, stop, inner),
            "token readers only: no seed owed"
        );

        // A value reader in the value's own block runs only after the value is
        // computed again on every entered path.
        let (mut graph, mut schedule, inner, outer_body, stop) = build(IrType::Int);
        let test = graph.add(Op::Add, IrType::Int, vec![stop, stop], None);
        place(&mut schedule, test, outer_body);
        assert!(
            ask(&graph, &schedule, stop, inner),
            "the outer test reads a recomputed value"
        );

        // A value reader the entered path reaches first: refused.
        let (mut graph, mut schedule, inner, _, stop) = build(IrType::Int);
        let early = graph.add(Op::Add, IrType::Int, vec![stop, stop], None);
        place(&mut schedule, early, inner);
        assert!(
            !ask(&graph, &schedule, stop, inner),
            "a value read inside the inner loop"
        );

        // A value φ reader: refused.
        let (mut graph, mut schedule, inner, outer_body, stop) = build(IrType::Int);
        let ctrl = schedule.blocks[outer_body].ctrl;
        let phi = graph.add(Op::Phi, IrType::Int, vec![ctrl, stop], None);
        place(&mut schedule, phi, outer_body);
        assert!(
            !ask(&graph, &schedule, stop, inner),
            "a value φ reads it on an edge"
        );

        // A reference: refused, whatever its readers.
        let (graph, schedule, inner, _, stop) = build(IrType::Ref);
        assert!(
            !ask(&graph, &schedule, stop, inner),
            "a reference is never left unseeded"
        );

        // No token reader at all: not this excuse's shape.
        let (mut graph, mut schedule, inner, outer_body) = fresh();
        let ctrl = schedule.blocks[outer_body].ctrl;
        let lone = graph.add(Op::Add, IrType::Int, vec![ctrl, ctrl], None);
        place(&mut schedule, lone, outer_body);
        assert!(
            !ask(&graph, &schedule, lone, inner),
            "no memory-token reader"
        );
    }

    /// Round 13 wave 11 (lane callcost5, proposal CC4-3): with the certain
    /// refusals out of the scan, the two phis of `COUNTED_LOOP_SUM` -- the only
    /// values the refusal loop keeps from it -- hold the FIRST two registers of
    /// the file. Before, the once-read `Param(0)` entered the scan first, took
    /// the first register, was refused, and left the phis one register higher.
    #[test]
    fn r13w11_the_kept_phis_take_the_first_registers_of_the_file() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_PHI_RESIDENCY", Some("1")),
                ("CRATONVM_JIT_IR_LS_PREPIN_REFUSED", Some("1")),
            ],
            || {
                let graph = IrBuilder::new(1, 3)
                    .build(&COUNTED_LOOP_SUM, 21)
                    .expect("the counted loop builds");
                let schedule = ir_schedule::schedule(&graph);
                let plan = plan_slots(&graph, &schedule, None);
                let residency = plan_register_residency(&graph, &schedule, &plan)
                    .expect("the allocation verifies")
                    .expect("a counted loop promotes something");
                let mut regs: Vec<u8> = phis_of(&graph)
                    .iter()
                    .filter_map(|&id| residency.gp_reg_of[id])
                    .collect();
                regs.sort_unstable();
                // The loop header carries a phi per live local (`n`, `sum`,
                // `i`), so count what is resident rather than assume two.
                assert!(regs.len() >= 2, "the loop phis are resident: {regs:?}");
                let mut first: Vec<u8> = ir_gp_file()[..regs.len()].to_vec();
                first.sort_unstable();
                assert_eq!(
                    regs, first,
                    "the phis must hold the first registers of the file"
                );
            },
        );
    }

    /// A `Ref`-typed phi is refused **by type**, and the census names the type
    /// cause — whatever else is switched on.
    ///
    /// # The property, which is a GC one and not a tuning one
    ///
    /// A root walk reads a frame it did not stop, through RBP, and
    /// `OopMapEntry` names frame slots only. There is no register a collector
    /// could be told about, walk, or update on an evacuation. For ordinary
    /// values `CRATONVM_JIT_IR_REF_RESIDENCY` admits a reference anyway and
    /// pays for it with `invalidate_ref_residency`, whose audit is
    /// `lower_block`'s per-node loop. **A phi is published on the EDGE**, by
    /// `emit_phi_copies`, which is not inside that loop — so the refusal here
    /// is unconditional and does not consult that flag.
    ///
    /// Both arms are exercised, and the flag-on arm is the load-bearing one:
    /// with the flag off a `Ref` phi would fall out of the bank match anyway,
    /// so an assertion at the default alone would pass even if the refusal were
    /// deleted.
    ///
    /// # Why the phi is retyped by hand
    ///
    /// `IrBuilder::new` types every parameter `IrType::Int`, so no bytecode
    /// fixture this test could write produces a `Ref` phi at all. Retyping one
    /// node of the fixture above isolates the TYPE as the single difference
    /// from a graph that is known to promote both of its phis — which is
    /// exactly the comparison the assertion wants, and a stronger one than a
    /// separate hand-built graph could make.
    #[test]
    fn a_reference_typed_phi_is_refused_by_type_whatever_the_flags_say() {
        for ref_residency in ["0", "1"] {
            let mut graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the fixture must have a second phi, or the non-vacuity check \
                 below cannot be made"
            );
            let reference = phis[0];
            graph.nodes[reference].ty = IrType::Ref;

            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JIT_IR_PHI_RESIDENCY", Some("1")),
                    ("CRATONVM_JIT_IR_REF_RESIDENCY", Some(ref_residency)),
                ],
                || {
                    plan_register_residency(&graph, &schedule, &plan)
                        .expect("the allocation verifies")
                        .expect("the remaining int phi is still promotable")
                },
            );

            assert_eq!(
                residency.gp_reg_of[reference], None,
                "a `Ref` phi took a GP register with \
                 CRATONVM_JIT_IR_REF_RESIDENCY={ref_residency}; the oop map names \
                 frame slots only, so a collector could neither see nor relocate it"
            );
            assert_eq!(
                residency.reg_of[reference], None,
                "and it must not be in the FP file either"
            );
            assert_eq!(
                residency.phi_census.ref_type, 1,
                "the census must name the TYPE cause, not fold the refusal into \
                 a generic one: {:?}",
                residency.phi_census
            );
            assert!(
                phis[1..]
                    .iter()
                    .any(|&id| residency.gp_reg_of[id].is_some()),
                "the `int` phi must still be resident, or the assertion above is \
                 vacuous: {:?}",
                residency.phi_census
            );
        }
    }

    /// A phi fed by a different value on each incoming edge still ends up with
    /// ONE home word and ONE register for its whole life.
    ///
    /// The parallel-copy question. `SWAP_LOOP`'s two carried phis are each
    /// other's back-edge value, so the edge's copies are a CYCLE (`a <- b,
    /// b <- a`) rather than a chain: emitted in gather order through one
    /// temporary, the second copy reads the word the first just overwrote and
    /// both locals end up holding `b`. `resolve_parallel_copy` orders them and
    /// breaks the cycle through `phi_copy_scratch_slot_off`; the register layer
    /// adds its own hazard on top (`emit_phi_copies`' `defer_publish`, written
    /// after `java.time.Duration.toNanos()` returned `seconds * 1e9 + seconds`
    /// on 198,356 calls in 200,000).
    ///
    /// What residency must not do to any of that is give one phi two homes or
    /// two registers. Both halves are asserted, plus the answer the loop
    /// actually computes, because a consistency property over an allocation
    /// nothing runs is worth very little.
    #[test]
    fn a_phi_whose_edges_disagree_keeps_one_home_and_one_register() {
        with_phi_residency(true, || {
            let graph = IrBuilder::new(1, 4)
                .build(&SWAP_LOOP, 23)
                .expect("the swap loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = plan_register_residency(&graph, &schedule, &plan)
                .expect("the allocation verifies")
                .expect("the swap loop promotes something");

            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the swap loop carries two locals: {phis:?}"
            );
            assert_eq!(
                residency.phi_census.disabled, 0,
                "the sub-flag is forced on for this test"
            );
            assert_eq!(residency.phi_census.ref_type, 0, "no reference here");

            // Every phi that took a register: one register, one home, and
            // neither shared with another phi that is live at the same header.
            let resident: Vec<usize> = phis
                .iter()
                .copied()
                .filter(|&id| residency.gp_reg_of[id].is_some())
                .collect();
            assert!(
                resident.len() >= 2,
                "at least the two swapped locals must be resident, or the \
                 distinctness assertions below are vacuous: {:?}",
                residency.phi_census
            );
            for (i, &a) in resident.iter().enumerate() {
                // `gp_reg_of` holds ONE register per node by construction, and
                // `plan_register_residency` refuses any value the scan gave
                // more than one segment -- so "one register for its whole life"
                // is structural here rather than something to count. What can
                // still go wrong is two phis sharing one, which is what the
                // inner loop checks.
                assert!(
                    residency.reg_of[a].is_none(),
                    "phi n{a} is in both banks at once"
                );
                let home_a = plan.node_color[a].expect("a phi always has a home word");
                for &b in &resident[i + 1..] {
                    assert_ne!(
                        residency.gp_reg_of[a], residency.gp_reg_of[b],
                        "phis n{a} and n{b} are both live at the loop header and \
                         were given the same register"
                    );
                    assert_ne!(
                        home_a,
                        plan.node_color[b].expect("a phi always has a home word"),
                        "phis n{a} and n{b} share a home word; the edge copies \
                         would write each other's value"
                    );
                }
            }

            // And it still swaps. `f(n)` is 2 for odd `n`, 1 for even.
            let _flag = LsForce::on();
            let cm = compile_via_ir(&SWAP_LOOP, 23, 1, 4).expect("the swap loop compiles");
            for (n, want) in [(0i64, 1i64), (1, 2), (2, 1), (3, 2), (10, 1), (11, 2)] {
                // SAFETY: one `int` argument, matching the fixture's signature;
                // the body calls no helper and runs on this thread.
                let got = unsafe { cm.try_call(&[n]).expect("call") };
                assert_eq!(got, want, "swap loop with n={n}");
            }
        });
    }

    /// End to end: the counted loop returns the right sum with phi residency
    /// forced ON, and the same sum with it forced OFF.
    ///
    /// The second arm is not decoration. Write-through means a resident phi is
    /// a CACHE — `emit_phi_copies` writes the home word at every incoming edge
    /// exactly as it always did and then moves the value into the register — so
    /// the two configurations must agree bit for bit on every input. A
    /// disagreement is a wrong-code bug in the publish, not a performance
    /// question, and `n=0` is in the list because a loop that never executes is
    /// the input on which a phi's register is read before any edge published
    /// it.
    #[test]
    fn a_counted_loop_computes_the_same_sum_with_phi_residency_forced_on() {
        let ns = [0i64, 1, 2, 5, 10, 100];
        let run = |on: bool| -> Vec<i64> {
            with_phi_residency(on, || {
                // The outer flag forced on rather than left alone: it is
                // default-ON today, so an unforced arm would be a different
                // configuration the day someone flips it.
                let _flag = LsForce::on();
                let cm = compile_via_ir(&COUNTED_LOOP_SUM, 21, 1, 3)
                    .expect("the counted loop compiles either way");
                ns.iter()
                    // SAFETY: one `int` argument, matching the fixture's
                    // signature; the body calls no helper and runs on this
                    // thread.
                    .map(|&n| unsafe { cm.try_call(&[n]).expect("call") })
                    .collect()
            })
        };
        let want: Vec<i64> = ns.iter().map(|&n| n * (n - 1) / 2).collect();
        let on = run(true);
        assert_eq!(on, want, "sum 0..n-1 with the loop phis in registers");
        let off = run(false);
        assert_eq!(
            on, off,
            "phi residency changed a computed value; write-through means the \
             register is a cache over a home word that is still written at \
             every incoming edge, so these must be identical"
        );
    }

    /// A value live across a helper call must not keep a caller-saved register.
    ///
    /// FP `Op::Rem` is the sharp case: it lowers to `CALL jit_drem`, and
    // ── Shadow instruction selection ─────────────────────────────────
    //
    // `docs/feature-designs/jit-machine-level-and-instruction-selection.md`,
    // increment 0.
    //
    // Increment 0's whole claim is "turning this on changes no emitted byte".
    // These are what hold it up. Note they drive the flag through
    // `flags::with_thread_overrides` and NOT `std::env::set_var`: the flag is
    // declared (`types/src/flag_groups.rs`, `jit/ir-isel-shadow`), so the
    // override mechanism reaches it, and a process-wide env write would race
    // every other test in this binary.

    /// Compile the same method with the shadow pass off and on, and compare
    /// **the emitted bytes**.
    ///
    /// Not "compare the result", not "both compiled" — the bytes. A shadow pass
    /// that perturbed slot numbering, buffer sizing or safepoint ids would still
    /// produce a working method and would still have broken the one property
    /// that makes increment 0 free.
    ///
    /// The exact edit that trips it: make the shadow block do anything to
    /// `lowerer` (allocate a slot, bump `next_sp_id`, touch the buffer).
    #[test]
    fn shadow_selection_changes_no_emitted_byte() {
        // Enabling the flag mutates the process-global shadow counters, so this
        // test owes the same lock as the two that read them.
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        // int f(int a, int b) { return (a + b) * a; } — arithmetic, one block,
        // the shape `isel`'s ALU and LEA rules actually fire on, so the shadow
        // pass has real work to do rather than trivially selecting nothing.
        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];

        let bytes = |on: bool| -> Vec<u8> {
            let value = if on { Some("1") } else { None };
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_ISEL_SHADOW", value)],
                || {
                    let cm = compile_via_ir(&code, 6, 2, 2).expect("compiles either way");
                    // SAFETY: the artifact is alive for the duration of this
                    // borrow, and `code_len` is what the emitter wrote.
                    unsafe {
                        std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len())
                            .to_vec()
                    }
                },
            )
        };

        let off = bytes(false);
        let on = bytes(true);
        assert!(
            !off.is_empty(),
            "precondition: the method compiled to bytes"
        );
        assert_eq!(
            off.len(),
            on.len(),
            "shadow selection changed the emitted length"
        );
        assert_eq!(off, on, "shadow selection changed the emitted bytes");
    }

    /// With the flag on, the pass actually ran — and covered every node.
    ///
    /// Without this the byte-identity test above passes vacuously: a shadow
    /// pass that never executes also changes no byte. So this asserts the
    /// counters moved, that `covers()` held on every block, and that the
    /// coverage figure is a real fraction rather than the "no nodes" zero.
    #[test]
    fn shadow_selection_runs_and_covers_every_scheduled_node() {
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        crate::x64::isel::reset_shadow_totals();

        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_ISEL_SHADOW", Some("1"))],
            || {
                compile_via_ir(&code, 6, 2, 2).expect("compiles");
            },
        );

        let (methods, stats) = crate::x64::isel::shadow_totals();
        assert_eq!(methods, 1, "exactly one method should have been shadowed");
        assert!(stats.blocks > 0, "no blocks were selected");
        assert!(
            stats.nodes > 0,
            "no data nodes were offered to the selector"
        );
        assert!(stats.tiles >= stats.blocks, "every block yields >= 1 tile");
        assert_eq!(
            stats.coverage_failures, 0,
            "`BlockSelection::covers` failed on {} block(s) — that is an `isel` \
             bug, not a measurement",
            stats.coverage_failures
        );
        assert!(
            stats.matched_tiles > 0,
            "no rule fired on `(a + b) * a`; the corpus this test uses was \
             chosen because the ALU rules match it, so zero means the selector \
             regressed, not that the method is unusual"
        );
        let pct = stats.coverage_pct();
        assert!(
            pct > 0.0 && pct <= 100.0,
            "coverage {pct} is not a fraction"
        );
    }

    /// With the flag OFF — the default, and every compile today — the pass does
    /// not run at all.
    ///
    /// The counter, not the bytes: "changed no byte" and "did not execute" are
    /// different claims and increment 0 makes both.
    #[test]
    fn shadow_selection_is_off_by_default() {
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        crate::x64::isel::reset_shadow_totals();

        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];
        compile_via_ir(&code, 6, 2, 2).expect("compiles");

        let (methods, stats) = crate::x64::isel::shadow_totals();
        assert_eq!(methods, 0, "the shadow pass ran without being asked");
        assert_eq!(stats, crate::x64::isel::ShadowStats::default());
    }

    /// The flag is DECLARED, so `-XX:` and the test override mechanism reach it.
    ///
    /// Rule 4 of `docs/known-issues/c2/README.md`: an undeclared flag is
    /// invisible to both, and the declaration sweep has already had to be re-run
    /// once because a flag was added 21 minutes after it closed at zero. The
    /// two tests above would still pass with an undeclared flag — `runtime_var`
    /// falls through to a live `std::env` read — so this checks the property
    /// they cannot.
    #[test]
    fn the_shadow_flag_is_declared() {
        let declared: Vec<&str> = cratonvm_types::flag_groups::INVENTORY
            .iter()
            .filter_map(|e| e.on_key)
            .collect();
        assert!(
            declared.contains(&"CRATONVM_JIT_IR_ISEL_SHADOW"),
            "`CRATONVM_JIT_IR_ISEL_SHADOW` is not in `types/src/flag_groups.rs`"
        );
        assert!(
            declared.contains(&"CRATONVM_DBG_IR_ISEL"),
            "`CRATONVM_DBG_IR_ISEL` is not in `types/src/flag_groups.rs`"
        );
        // Increment 2's two flags, same rule.
        for key in ["CRATONVM_JIT_IR_ISEL_EMIT", "CRATONVM_JIT_IR_ISEL_VERIFY"] {
            assert!(
                declared.contains(&key),
                "`{key}` is not in `types/src/flag_groups.rs`"
            );
        }
    }

    // ── Increment 2: the machine list emits ───────────────────────────
    //
    // The oracle is byte equality on a corpus: compile a method both ways and
    // compare the emitted bytes. Every `PATTERNS` row carries that property per
    // row — it names the hand-written emitter it reproduces — and these are the
    // same check at method scale.

    /// `int f(int a, int b) { return (a + b) * a; }` — `iload_0; iload_1;
    /// iadd; iload_0; imul; ireturn`, and the length is **6**, the whole
    /// method. (The neighbouring shadow tests pass 4, which truncates after the
    /// `iload_0` and leaves the multiply out of the graph entirely; that costs
    /// them nothing because they only count, but it would make every assertion
    /// below about `Rule::AluReg` vacuous.)
    #[cfg(test)]
    const MIR_ALU_CODE: [u8; 8] = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];

    /// [`MIR_ALU_CODE`] as a graph and a schedule, for the tests that work on
    /// the machine list directly instead of on the emitted bytes.
    #[cfg(test)]
    fn mir_alu_graph() -> (Graph, Schedule) {
        let builder = IrBuilder::new(2, 2);
        let graph = builder.build(&MIR_ALU_CODE, 6).expect("build");
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    #[cfg(test)]
    fn mir_emitted_bytes(mode: Option<MirMode>) -> Vec<u8> {
        // Both arms with the register cache OFF. Production makes the two
        // mutually exclusive, so a comparison that left it on for the no-mode
        // arm and off for the MIR arm would measure residency rather than the
        // selector -- and would report the selector as having changed bytes it
        // never touched.
        let _ls = LsForce::off();
        // Same argument for the two emission changes that landed 2026-09-05.
        // Both are ON by default now and neither is known to the tiler, so a
        // comparison that left them on for the no-mode arm would measure THEM
        // rather than the selector -- and would report the selector as having
        // changed bytes it never touched.
        let _carry = CarryForce::off();
        let _imm = AluImmForce::off();
        let _force = mode.map(MirForce::set);
        let cm = compile_via_ir(&MIR_ALU_CODE, 6, 2, 2).expect("compiles");
        // SAFETY: the artifact is alive for the duration of this borrow, and
        // `code_len` is what the emitter wrote.
        unsafe { std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len()).to_vec() }
    }

    /// The level-2 encoder reproduces the per-opcode arms **byte for byte**.
    ///
    /// This is increment 2's whole deliverable. `Rule::AluReg`'s seven rows are
    /// anchored to the exact literals `lower_data_node` emits — `01 C8`,
    /// `29 C8`, `0F AF C1`, `48 21 C8` and so on — and the frame-homed
    /// allocation the encoder assumes IS this backend's allocation, so equality
    /// is reachable rather than approximate.
    ///
    /// The exact edit that trips it: change any of those literals in
    /// `lower_data_node`, or change `enc_frame_load`'s displacement-form choice
    /// on one side only.
    #[test]
    fn the_machine_level_emits_the_same_bytes_as_the_per_opcode_arms() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let off = mir_emitted_bytes(None);
        let emit = mir_emitted_bytes(Some(MirMode::Emit));
        assert!(
            !off.is_empty(),
            "precondition: the method compiled to bytes"
        );
        assert_eq!(off, emit, "the level-2 encoder changed the emitted bytes");

        // Not vacuous: tiles were actually taken. A path that declined every
        // tile would satisfy the equality above trivially.
        let (methods, tiles, mismatches) = mir_totals::read();
        assert_eq!(
            methods, 1,
            "exactly one method went through the machine list"
        );
        assert!(
            tiles >= 2,
            "`(a + b) * a` has two AluReg roots; the encoder took {tiles}"
        );
        assert_eq!(mismatches, 0);
    }

    // ── Increment 2: the allocation over the tile list ───────────────

    /// The machine list gets an allocation, and `verify_allocation` accepts it.
    ///
    /// The point of the increment is *which* verifier: the allocator's own,
    /// unmodified. A second checker written for the level-2 form would be a
    /// second model of the same program, and the whole reason the frame-homed
    /// allocation is describable at all is that `Allocation` already has a
    /// shape for "everything in its home word".
    ///
    /// Not vacuous by construction — `located` is asserted non-zero, which is
    /// the difference between "verified" and "there was nothing to verify".
    #[test]
    fn the_machine_list_carries_an_allocation_that_verify_allocation_accepts() {
        let (graph, schedule) = mir_alu_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let mir = build_mir_plan(&graph, &schedule).expect("selection covers every block");

        let verdict =
            verify_mir_allocation(&graph, &schedule, &plan, &mir).expect("the allocation verifies");
        match verdict {
            MirAllocVerdict::Verified { located, .. } => assert!(
                located >= 3,
                "`(a + b) * a` has two params and two results; the allocation \
                 located only {located} values, so this test is close to vacuous"
            ),
            other => panic!("expected a verified allocation, got {other:?}"),
        }
    }

    /// The verifier is REACHED, and it can say no.
    ///
    /// A verification step nothing can fail is indistinguishable from no
    /// verification step. This one runs over an allocation whose every segment
    /// is `reg: None` — the arm where most of `verify_allocation`'s rules go
    /// quiet — so what gets injected against is the rule that does *not* go
    /// quiet: two values whose live ranges overlap, pointed at one home word.
    ///
    /// The violation is planted in the `SlotPlan`, UPSTREAM of
    /// `verify_mir_allocation`, so the whole path is under test rather than
    /// `verify_allocation` in isolation. Only the colour's *value* changes,
    /// never its `Some`-ness, so the liveness-agreement precheck still passes
    /// and the rejection can only have come from the verifier.
    ///
    /// The exact edit that trips it: drop the `verify_allocation` call from
    /// `verify_mir_allocation`.
    #[test]
    fn an_aliased_home_word_is_rejected_by_the_allocation_verifier() {
        use crate::regalloc::build_live_model;

        let (graph, schedule) = mir_alu_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let mir = build_mir_plan(&graph, &schedule).expect("selection covers every block");
        // Precondition: unaliased, this graph verifies. Without it a broken
        // fixture would make the rejection below meaningless.
        assert!(
            matches!(
                verify_mir_allocation(&graph, &schedule, &plan, &mir),
                Ok(MirAllocVerdict::Verified { .. })
            ),
            "the fixture must verify BEFORE the injection"
        );

        // Two values genuinely live at the same position, so the rejection is
        // the aliasing rule and not some other one.
        let live = build_live_model(&graph, &schedule);
        let located: Vec<usize> = (0..graph.nodes.len())
            .filter(|&id| plan.node_color.get(id).copied().flatten().is_some())
            .filter(|&id| live.range.get(id).copied().flatten().is_some())
            .collect();
        let mut pair = None;
        'outer: for (i, &a) in located.iter().enumerate() {
            let ra = live.range[a].expect("located");
            for &b in &located[i + 1..] {
                let rb = live.range[b].expect("located");
                if ra.lo <= rb.hi && rb.lo <= ra.hi {
                    pair = Some((a, b));
                    break 'outer;
                }
            }
        }
        let (a, b) = pair.expect("this graph has two simultaneously live values");

        let mut aliased = plan_slots(&graph, &schedule, None);
        aliased.node_color[b] = aliased.node_color[a];
        let err = verify_mir_allocation(&graph, &schedule, &aliased, &mir)
            .expect_err("two values live together in one home word");
        let text = format!("{err:?}");
        assert!(
            text.contains("home word") || text.contains("slot pools"),
            "rejected for the wrong reason: {text}"
        );
    }

    /// Emit mode refuses a compile whose allocation the verifier rejected;
    /// verify mode does not.
    ///
    /// Asserted as a property of the two modes rather than by forcing a
    /// rejection, because the only way to force one on a real graph is to
    /// introduce the compiler bug it exists to catch. What is checkable without
    /// that is the ASYMMETRY, and the asymmetry is the whole policy: verify
    /// mode's contract is that it changes no emitted byte, which it would break
    /// by also changing which methods compile.
    #[test]
    fn verify_mode_records_the_allocation_and_emit_mode_stakes_the_compile_on_it() {
        let _guard = mir_totals::TEST_LOCK.lock();

        for mode in [MirMode::Verify, MirMode::Emit] {
            mir_totals::reset();
            let bytes = mir_emitted_bytes(Some(mode));
            assert!(!bytes.is_empty(), "{mode:?} must still produce a body");
            let (verified, values, vacuous, indescribable, rejected) = mir_totals::read_alloc();
            assert_eq!(rejected, 0, "{mode:?}: the allocation was rejected");
            assert_eq!(
                verified, 1,
                "{mode:?}: one method, one verdict — got verified={verified} \
                 nothing_to_cover={vacuous} indescribable={indescribable}"
            );
            assert!(
                values > 0,
                "{mode:?}: the verdict was `Verified` over zero values, which \
                 is `NothingToCover` wearing the wrong label"
            );
        }
    }

    /// Verify mode is the same oracle without the risk: the per-opcode arms
    /// still emit, and the encoder's answer is compared against what they wrote.
    #[test]
    fn verify_mode_agrees_and_changes_no_emitted_byte() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let off = mir_emitted_bytes(None);
        let verify = mir_emitted_bytes(Some(MirMode::Verify));
        assert_eq!(off, verify, "verify mode must not change an emitted byte");

        let (methods, tiles, mismatches) = mir_totals::read();
        assert_eq!(methods, 1);
        assert!(tiles >= 2, "verify mode checked {tiles} tiles");
        assert_eq!(mismatches, 0, "the two paths disagreed");
    }

    /// The oracle can FAIL. Injected, because a guard nobody has seen fail is a
    /// guard of unknown polarity — and this one's whole job is to be believed
    /// when it stays silent over a corpus.
    ///
    /// Both halves matter: verify mode must *count* the disagreement, and the
    /// compile must be *refused* rather than shipped with a body nothing
    /// checked. Increment 2 is where fail-closed returns.
    #[test]
    fn an_injected_wrong_byte_is_caught_by_the_oracle() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let _inject = MirInject::on();
        let _force = MirForce::set(MirMode::Verify);
        let refused = compile_via_ir(&MIR_ALU_CODE, 6, 2, 2);
        assert!(
            refused.is_none(),
            "a disagreeing method must lose its optimized body, not ship it"
        );
        let (_, _, mismatches) = mir_totals::read();
        assert!(
            mismatches >= 1,
            "the byte-equality oracle did not notice a corrupted tile"
        );
    }

    /// With both flags off — the default, and every compile today — the machine
    /// list is not built at all.
    ///
    /// The counter, not the bytes: "changed no byte" and "did not execute" are
    /// different claims, and the equality tests above would pass vacuously on a
    /// path that never ran.
    #[test]
    fn the_machine_level_is_off_by_default() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        compile_via_ir(&MIR_ALU_CODE, 6, 2, 2).expect("compiles");

        assert_eq!(
            mir_totals::read(),
            (0, 0, 0),
            "the machine list was built without being asked"
        );
    }

    /// A tile that absorbed another node must never reach the encoder.
    ///
    /// `Rule::AluReg` covers exactly its own root, so this guard is insurance
    /// against a future rule rather than a live filter — which is precisely why
    /// it is tested directly instead of through a compile. Driven through one it
    /// would be vacuous: the rules that DO absorb (`Lea`, `AluImm`, the fused
    /// branches) are already refused a line earlier, by rule.
    ///
    /// What it prevents: the caller skips every node a tile covers, so a tile
    /// that absorbed a node the encoder does not actually fold leaves that node
    /// computed nowhere. That is the same failure `BlockSelection::covers`
    /// exists to make unrepresentable, one level lower down.
    ///
    /// The exact edit that trips it: delete the `covered.as_slice() == [id]`
    /// clause from `mir_tile_is_emittable`.
    #[test]
    fn the_encoder_refuses_a_tile_that_absorbed_another_node() {
        use crate::x64::isel::{MInst, Op as SelOp, Rule, Tile, Ty};

        let alu = |dst: NodeId, lhs: NodeId, rhs: NodeId| MInst::AluRR {
            op: SelOp::Add,
            ty: Ty::I32,
            dst,
            lhs,
            rhs,
        };
        // The shape the encoder handles: one root, nothing absorbed.
        let plain = Tile::for_test(5, vec![5], vec![alu(5, 3, 4)], Rule::AluReg);
        assert!(mir_tile_is_emittable(&plain, 5));

        // The same tile, having absorbed node 4.
        let absorbing = Tile::for_test(5, vec![5, 4], vec![alu(5, 3, 4)], Rule::AluReg);
        assert!(
            !mir_tile_is_emittable(&absorbing, 5),
            "a tile that absorbed node 4 would leave it computed nowhere"
        );

        // And a rule the encoder has not been proved byte-equal for, however
        // ordinary its cover list.
        let other = Tile::for_test(5, vec![5], vec![alu(5, 3, 4)], Rule::AluImm);
        assert!(!mir_tile_is_emittable(&other, 5));
        // A tile rooted somewhere else is never this node's answer.
        assert!(!mir_tile_is_emittable(&plain, 4));
    }

    /// The two frame-access encoders are the ONE producer of these bytes.
    ///
    /// `load_to_rax` / `load_to_rcx` / `store_rax` delegate to them, so the
    /// level-2 encoder and the per-opcode arms cannot drift apart. This pins the
    /// literals those methods used to hold inline, in both displacement forms.
    #[test]
    fn the_frame_access_encoders_reproduce_the_inline_literals() {
        let bytes = |f: fn(u8, i32, &mut FrameAccess), reg: u8, off: i32| -> Vec<u8> {
            let mut a = FrameAccess::new();
            f(reg, off, &mut a);
            a.as_slice().to_vec()
        };
        // disp8: mod=01, r/m=RBP(101).
        assert_eq!(bytes(enc_frame_load, RAX, 8), vec![0x48, 0x8B, 0x45, 0xF8]);
        assert_eq!(bytes(enc_frame_load, RCX, 8), vec![0x48, 0x8B, 0x4D, 0xF8]);
        assert_eq!(bytes(enc_frame_store, RAX, 8), vec![0x48, 0x89, 0x45, 0xF8]);
        // disp32: mod=10.
        let mut want = vec![0x48u8, 0x8B, 0x85];
        want.extend_from_slice(&(-4096i32).to_le_bytes());
        assert_eq!(bytes(enc_frame_load, RAX, 4096), want);
        let mut want = vec![0x48u8, 0x89, 0x85];
        want.extend_from_slice(&(-4096i32).to_le_bytes());
        assert_eq!(bytes(enc_frame_store, RAX, 4096), want);
        // A register these encodings cannot express is a refusal, not a
        // silently truncated `reg & 7` — which would encode R8 as RAX.
        assert!(bytes(enc_frame_load, 8, 8).is_empty());
        assert!(bytes(enc_frame_store, 8, 8).is_empty());
    }

    // ── The three `ir::Op` enumerations, checked against each other ──
    //
    // `docs/feature-designs/jit-machine-level-and-instruction-selection.md`,
    // "The cheap alternative". One set of operations is enumerated
    // in three places, in two different vocabularies:
    //
    //   1. `lower_data_node`'s match arms          — 48 of 53 `ir::Op` variants
    //   2. `op_defines_result_slot`                — 37
    //   3. `ir::ir_compatible`                     — in the BYTECODE's
    //      vocabulary (`scan.anewarray_ops`, …), not `Op`'s
    //
    // (1) and (2) are checked here. (3) cannot be: it answers a different
    // question about a different type, which is precisely why the catch-all's
    // old claim — "bail in `ir_compatible` prevents reaching here" — was not
    // checkable where it was written, and why `lower_data_node`'s final arm now
    // refuses instead of asserting.
    //
    // WHAT TRIPS THESE (rule 5 of `docs/known-issues/c2/README.md`: write down
    // the exact edit, or the test is decoration):
    //
    //   * Add a variant to `ir::Op`. `declared_lowering` is an exhaustive match
    //     with NO wildcard arm, so the crate stops compiling until the author
    //     classifies it. That is the primary forcing function and it fires at
    //     build time, not test time.
    //   * Classify it `Lowered*` but forget the `lower_data_node` arm.
    //     `every_ir_op_is_lowered_or_declared_unlowerable` fails: the source
    //     scan finds no arm naming it.
    //   * Add the arm but forget `op_defines_result_slot`.
    //     `op_defines_result_slot_matches_the_arms_that_allocate` fails.
    //   * Remove a variant from `ir::Op` and leave it here.
    //     `the_op_representatives_cover_every_declared_variant` fails.
    //
    // All three scans read the source with `include_str!`, the same idiom as
    // `the_register_read_path_is_gated_on_publication` above.

    /// What `lower_data_node` does with one `ir::Op`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum OpLowering {
        /// Has an arm, and that arm allocates a result slot. Must therefore
        /// also be named by `op_defines_result_slot`.
        LoweredValue,
        /// Has an arm, but produces no value anyone can read: a control node, a
        /// memory-only effect, or a terminator handled by `lower_terminator`.
        LoweredEffect,
        /// No arm. Reaching `lower_data_node` with one refuses the compile.
        Unlowerable,
    }

    /// The variants with no lowering arm — the explicit list the catch-all
    /// used to leave implicit.
    ///
    /// Each is unreachable from a real compile today (see the catch-all's own
    /// comment for the evidence per op). This is a statement about the tree,
    /// not a permission: a variant added here is a variant the optimizing tier
    /// silently declines to compile, and the edit should be visible in review.
    ///
    /// `NewArray` left this list in cov-06: it now has a real arm below (the
    /// shared `emit_new_array_stub`, mirroring `Op::New`).
    const UNLOWERABLE: [&str; 3] = ["I2B", "I2C", "I2S"];

    /// **Exhaustive on purpose — do not add a wildcard arm.**
    ///
    /// This match is the forcing function. A new `ir::Op` variant makes the
    /// crate fail to compile here, which is the only mechanism that catches the
    /// author *before* the tests run.
    fn declared_lowering(op: &Op) -> OpLowering {
        use OpLowering::{LoweredEffect, LoweredValue, Unlowerable};
        match op {
            // Control and terminator nodes: an arm exists and does nothing,
            // because `lower_terminator` owns them.
            Op::Start
            | Op::Return
            | Op::Throw
            | Op::If
            | Op::Switch { .. }
            | Op::Merge
            | Op::Region
            | Op::Proj(_)
            | Op::Dead => LoweredEffect,
            // Values.
            Op::Const(_)
            | Op::ConstF(_)
            | Op::Param(_)
            | Op::Phi
            | Op::ScalarIntrinsic(_)
            | Op::Add
            | Op::Sub
            | Op::Mul
            | Op::Div
            | Op::Rem
            | Op::Neg
            | Op::And
            | Op::Or
            | Op::Xor
            | Op::Shl
            | Op::Shr
            | Op::UShr
            | Op::Cmp(_)
            | Op::LCmp
            | Op::FCmp { .. }
            | Op::I2L
            | Op::L2I
            | Op::I2F
            | Op::I2D
            | Op::L2F
            | Op::L2D
            | Op::F2I
            | Op::F2L
            | Op::F2D
            | Op::D2I
            | Op::D2L
            | Op::D2F
            | Op::Load(_)
            | Op::ArrayLoad(_)
            | Op::ArrayStore(_)
            | Op::ArrayLength
            | Op::New { .. }
            | Op::NewArray { .. }
            | Op::Call { .. }
            | Op::ConstString { .. }
            | Op::ConstClass { .. }
            | Op::LoadStatic { .. }
            | Op::LambdaIntToDouble
            | Op::IndyBridge { .. }
            | Op::MultiNewArray { .. }
            | Op::NewCp { .. }
            | Op::InstanceOf { .. }
            | Op::Unbox { .. }
            | Op::ExactClassIs { .. }
            | Op::ClassWordOf
            | Op::OsrEntryFlag { .. }
            | Op::OsrLocal(_)
            | Op::CallThrew { .. }
            | Op::ClassInitTest { .. }
            | Op::CurrentThreadMirror { .. }
            // JIT round 20 wave 11 (lane pIndy): one root word load.
            | Op::IndyRootRef { .. }
            | Op::CatchEntryFlag { .. }
            | Op::CaughtException
            | Op::CheckCast { .. } => LoweredValue,
            // Effects with an arm but no result slot.
            Op::Store(_)
            | Op::StoreStatic { .. }
            | Op::MonitorEnter
            | Op::MonitorExit
            | Op::OsrMemory
            | Op::KeepAlive
            | Op::Guard { .. } => LoweredEffect,
            // No arm. Keep in step with `UNLOWERABLE`; the tests check it.
            Op::I2B | Op::I2C | Op::I2S => Unlowerable,
        }
    }

