#[cfg(test)]
mod gci_i9ng_shadow_push_gate_tests {
    //! gci i9/ng (i8/nt review item 6): the IR tier's per-call shadow push is
    //! gated on the shadow-stack codegen, as the frame block and the
    //! single-pass backend already were.
    use super::*;

    #[test]
    fn gci_i9ng_shadow_push_needs_the_shadow_codegen() {
        let on = || true;
        let off = || false;
        assert!(Lowerer::shadow_push_emits(0x1000, 16, 24, 3, on), "wired, codegen on");
        assert!(
            !Lowerer::shadow_push_emits(0x1000, 16, 24, 3, off),
            "shadow emission off: no push, so no overflow bail"
        );
    }

    #[test]
    fn gci_i9ng_shadow_push_wiring_is_checked_before_the_codegen_switch() {
        let never = || -> bool { panic!("the switch is read only for a wired push") };
        assert!(!Lowerer::shadow_push_emits(0, 16, 24, 3, never), "no thread helper");
        assert!(!Lowerer::shadow_push_emits(0x1000, 0, 24, 3, never), "no thread slot");
        assert!(!Lowerer::shadow_push_emits(0x1000, 16, 0, 3, never), "no savebase slot");
        assert!(!Lowerer::shadow_push_emits(0x1000, 16, 24, 0, never), "nothing to publish");
    }
}

/// JIT round 20 wave 5 (lane loopopt): a guard whose condition has no home
/// word (a dropped constant: a site trap or a folded guard) reads it through
/// `gp_load_value` on both of its routes, instead of `slot_of`, which refused
/// and cost the attempt a second lowering with every home kept.
#[cfg(test)]
mod jr20_guard_homeless_condition_tests {
    #[test]
    fn a_guard_reads_a_homeless_condition_through_gp_load_value() {
        let src = include_str!("ir_lower.rs");
        let arm = src
            .split("let cond_homeless = fused.is_none()")
            .nth(1)
            .expect("the guard arm decides whether its condition is homeless");
        let arm = arm
            .split("// getfield read")
            .next()
            .expect("the arm ends before the getfield arm");
        assert_eq!(
            arm.matches("self.gp_load_value(RAX, cond_id);").count(),
            2,
            "both routes (implicit throw pad and deopt pad) read it by value"
        );
        assert!(arm.contains("fused.is_some() || cond_homeless"));
    }
}

// JIT round 20 wave 20 (lane refspin): the spliced `Reference.get` loop of
// `jr20-spliced-reference-get-loop-never-sees-the-clear-20261013.md`.
#[cfg(test)]
mod jr20_refspin_referent_loop_tests {
    use super::*;
    use crate::ir::{IrBuilder, IrInlineSite, IrInlineTables};
    use crate::ir_schedule;

    /// `static int spin(R r, int limit) { int n = 0; while (get(r) != null &&
    /// n < limit) n++; return n; }`, with `static Object get(R r) { return
    /// r.referent; }` spliced at caller pc 3 and relocated to combined pc 24:
    ///
    /// ```text
    ///  0 iconst_0          1 istore_2
    ///  2 aload_0           3 invokestatic #1  (spliced)
    ///  6 ifnull 20         9 iload_2   10 iload_1   11 if_icmpge 20
    /// 14 iinc 2, 1        17 goto 2
    /// 20 iload_2          21 ireturn
    /// 24 aload_0          25 getfield #2 (referent)   28 areturn
    /// ```
    const CODE: [u8; 31] = [
        0x03, 0x3d, 0x2a, 0xb8, 0x00, 0x01, 0xc6, 0x00, 0x0e, 0x1c, 0x1b, 0xa2, 0x00, 0x09, 0x84,
        0x02, 0x01, 0xa7, 0xff, 0xf1, 0x1c, 0xac, 0x00, 0x00, // caller [0, 22) + pad
        0x2a, 0xb4, 0x00, 0x02, 0xb0, // relocated callee [24, 29)
        0x00, 0x00,
    ];
    const REFERENT_PC: usize = 25;

    /// Build and optimise the loop; `referent` lists pc 25 the way
    /// `append_ir_inline_site` rebases `InlineSite::referent_load_pcs`.
    fn build(referent: bool) -> Graph {
        let site = IrInlineSite {
            base: 24,
            code_len: 5,
            num_args: 1,
            max_locals: 1,
            arg_local_slots: vec![0],
            returns_value: true,
            receiver_is_arg0: false,
            method_key: "R.get:(LR;)Ljava/lang/Object;".to_string(),
            class_id: 7,
        };
        let mut b = IrBuilder::new(2, 3);
        b.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut tables = IrInlineTables::default();
        tables.sites.insert(3, site);
        tables.field_info.insert(REFERENT_PC, (0usize, b'L'));
        if referent {
            tables.referent_load_pcs.insert(REFERENT_PC);
        }
        b.apply_inline_tables(tables);
        let mut g = b.build(&CODE, 22).expect("the spliced loop builds");
        crate::ir_optimize::optimize(&mut g);
        g
    }

    /// The scheduled reads at the referent pc (unrolled copies included).
    fn referent_loads(g: &Graph, s: &Schedule) -> Vec<usize> {
        g.nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Load(_)) && n.bytecode_pc == Some(REFERENT_PC))
            .map(|(id, _)| id)
            .filter(|&id| s.node_to_block.get(id).is_some_and(|&b| b < s.blocks.len()))
            .collect()
    }

    /// `(latch, header)` of every reducible back edge.
    fn back_edges(s: &Schedule) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        for (b, blk) in s.blocks.iter().enumerate() {
            for &h in &blk.successors {
                if h <= b && s.dom.dominates(h, b) {
                    out.push((b, h));
                }
            }
        }
        out
    }

    /// The natural loop of `latch -> header`, as block indices.
    fn natural_loop(s: &Schedule, latch: usize, header: usize) -> Vec<usize> {
        let mut body = vec![header];
        let mut work = vec![latch];
        while let Some(b) = work.pop() {
            if body.contains(&b) {
                continue;
            }
            body.push(b);
            work.extend(s.blocks[b].predecessors.iter().copied());
        }
        body
    }

    /// The referent read is re-read every iteration: it survives the
    /// optimizer (not forwarded, CSE'd or hoisted away), stays volatile-ordered
    /// and sits inside the loop's body; and at the loop's back-edge poll its
    /// home is one `emit_back_edge_dead_home_clears` zeroes, so the poll's map
    /// stops rooting the last iteration's referent (the defect: the collector
    /// never cleared it while the loop spun).
    #[test]
    fn jr20_refspin_a_spliced_referent_read_stays_in_the_loop_and_dies_at_its_back_edge() {
        let g = build(true);
        assert!(g.referent_load_pcs.contains(&REFERENT_PC));
        let schedule = ir_schedule::schedule(&g);
        let loads = referent_loads(&g, &schedule);
        assert!(
            !loads.is_empty(),
            "the referent read survives optimisation (never forwarded or removed)"
        );
        for &l in &loads {
            assert!(
                g.nodes[l].is_volatile_access(),
                "n{l}: a referent read is ordered like a volatile one"
            );
        }
        let edges = back_edges(&schedule);
        assert!(!edges.is_empty(), "the loop survives optimisation");
        for &l in &loads {
            let home = schedule.node_to_block[l];
            assert!(
                edges
                    .iter()
                    .any(|&(latch, header)| natural_loop(&schedule, latch, header).contains(&home)),
                "n{l} (block {home}) is not inside the loop: it was hoisted out"
            );
        }
        let plan = plan_slots(&g, &schedule, None);
        let dead: Vec<usize> = edges
            .iter()
            .flat_map(|&(latch, _)| referent_loads_dead_at_back_edge(&g, &schedule, &plan, latch))
            .map(|(id, _)| id)
            .collect();
        for &l in &loads {
            assert!(
                dead.contains(&l),
                "n{l}: the referent read's home is dead at its loop's back-edge poll \
                 and must be zeroed there (dead: {dead:?})"
            );
        }
    }

    /// Control: the same loop with no referent pc builds an ordinary read,
    /// and nothing is zeroed at its back edge.
    #[test]
    fn jr20_refspin_an_ordinary_field_read_is_not_cleared_at_the_back_edge() {
        let g = build(false);
        assert!(g.referent_load_pcs.is_empty());
        let schedule = ir_schedule::schedule(&g);
        let plan = plan_slots(&g, &schedule, None);
        for (latch, _) in back_edges(&schedule) {
            assert!(referent_loads_dead_at_back_edge(&g, &schedule, &plan, latch).is_empty());
        }
    }
}

// JIT round 20 wave 21 (lane pollroot): the general back-edge dead-home clears
// of `jr20-back-edge-poll-publishes-dead-reference-homes-20261013.md`.
#[cfg(test)]
mod jr20_pollroot_back_edge_tests {
    use super::*;
    use crate::ir::IrBuilder;
    use crate::ir_schedule;

    /// `static int walk(Node head) { int n = 0; Node p = head; while (p !=
    /// null) { if (p.val != null) n++; p = p.next; } return n; }` -- a
    /// call-free loop with a dead `Ref` temporary (`p.val`, read only by the
    /// `ifnull`) and a `Ref` carried round the loop (`p`, a header phi whose
    /// latch edge reads `p.next`):
    ///
    /// ```text
    ///  0 iconst_0          1 istore_1          2 aload_0           3 astore_2
    ///  4 aload_2           5 ifnull 26
    ///  8 aload_2           9 getfield #1 (val) 12 ifnull 18        15 iinc 1, 1
    /// 18 aload_2          19 getfield #2 (next) 22 astore_2        23 goto 4
    /// 26 iload_1          27 ireturn
    /// ```
    const WALK: [u8; 28] = [
        0x03, 0x3c, 0x2a, 0x4d, 0x2c, 0xc6, 0x00, 0x15, 0x2c, 0xb4, 0x00, 0x01, 0xc6, 0x00, 0x06,
        0x84, 0x01, 0x01, 0x2c, 0xb4, 0x00, 0x02, 0x4d, 0xa7, 0xff, 0xed, 0x1b, 0xac,
    ];
    const WALK_VAL_PC: usize = 9;
    const WALK_NEXT_PC: usize = 19;

    /// `static Object last(Node head) { Node p = head; Object v; do { v =
    /// p.val; p = p.next; } while (p != null); return v; }` -- the latch's
    /// branch also LEAVES the loop, and `v` is read after it:
    ///
    /// ```text
    ///  0 aload_0           1 astore_1
    ///  2 aload_1           3 getfield #1 (val)  6 astore_2
    ///  7 aload_1           8 getfield #2 (next) 11 astore_1
    /// 12 aload_1          13 ifnonnull 2
    /// 16 aload_2          17 areturn
    /// ```
    const LAST: [u8; 18] = [
        0x2a, 0x4c, 0x2b, 0xb4, 0x00, 0x01, 0x4d, 0x2b, 0xb4, 0x00, 0x02, 0x4c, 0x2b, 0xc7, 0xff,
        0xf5, 0x2c, 0xb0,
    ];
    const LAST_VAL_PC: usize = 3;

    /// Build and optimise a one-parameter (`Node`) method whose two
    /// `getfield`s at `val_pc` / `next_pc` read reference fields 0 and 1.
    fn build(code: &[u8], val_pc: usize, next_pc: usize) -> Graph {
        let mut b = IrBuilder::new(1, 3);
        b.set_param_types(&[IrType::Ref]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(val_pc, (0usize, b'L'));
        fi.insert(next_pc, (1usize, b'L'));
        b.set_field_info(fi);
        let mut g = b.build(code, code.len()).expect("the list walk builds");
        crate::ir_optimize::optimize(&mut g);
        g
    }

    /// The scheduled `Ref` reads at `pc` (unrolled copies included).
    fn ref_loads_at(g: &Graph, s: &Schedule, pc: usize) -> Vec<usize> {
        g.nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| {
                matches!(n.op, Op::Load(_)) && n.ty == IrType::Ref && n.bytecode_pc == Some(pc)
            })
            .map(|(id, _)| id)
            .filter(|&id| s.node_to_block.get(id).is_some_and(|&b| b < s.blocks.len()))
            .collect()
    }

    /// `(latch, header)` of every reducible back edge.
    fn back_edges(s: &Schedule) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        for (b, blk) in s.blocks.iter().enumerate() {
            for &h in &blk.successors {
                if h <= b && s.dom.dominates(h, b) {
                    out.push((b, h));
                }
            }
        }
        out
    }

    /// Every value reported dead at any back edge, general or referent mode.
    fn dead_anywhere(g: &Graph, s: &Schedule, plan: &SlotPlan, general: bool) -> Vec<usize> {
        back_edges(s)
            .iter()
            .flat_map(|&(latch, _)| back_edge_dead_ref_homes(g, s, plan, latch, general))
            .map(|(id, _)| id)
            .collect()
    }

    /// The defect: `p.val` is dead at the back-edge poll (nothing after the
    /// `ifnull` reads it), yet the poll's map published its home, so the
    /// previous iteration's value stayed a strong root at every collection
    /// stopping there. It is reported now (general mode) -- and NOT under the
    /// `=0` arm, which keeps only the referent reads (there are none).
    #[test]
    fn jr20_pollroot_a_dead_ref_temporary_of_a_call_free_loop_is_cleared_at_its_back_edge() {
        let g = build(&WALK, WALK_VAL_PC, WALK_NEXT_PC);
        assert!(
            !g.nodes.iter().any(|n| matches!(n.op, Op::Call { .. })),
            "the loop body makes no call: the back-edge poll is its only GC point"
        );
        let s = ir_schedule::schedule(&g);
        let vals = ref_loads_at(&g, &s, WALK_VAL_PC);
        assert!(!vals.is_empty(), "the p.val read survives optimisation");
        assert!(!back_edges(&s).is_empty(), "the loop survives optimisation");
        let plan = plan_slots(&g, &s, None);
        let dead = dead_anywhere(&g, &s, &plan, true);
        for &v in &vals {
            assert!(
                dead.contains(&v),
                "n{v} (p.val) is dead at the back-edge poll and must leave its home there \
                 (dead: {dead:?})"
            );
        }
        assert!(
            dead_anywhere(&g, &s, &plan, false).is_empty(),
            "CRATONVM_JIT_IR_BACK_EDGE_DEAD_HOME_CLEAR=0: no referent read, nothing cleared"
        );
        for (latch, _) in back_edges(&s) {
            assert!(referent_loads_dead_at_back_edge(&g, &s, &plan, latch).is_empty());
        }
    }

    /// `p` is carried round the loop in a header phi whose latch edge reads
    /// `p.next`. The edge value is live over the poll and never reported; the
    /// phi itself is (wave 21 follow-up): its last reader, the `p.next` load,
    /// ran before the poll, and the edge copy that rewrites its home runs
    /// after it, so the home holds the node the loop has just left. Not under
    /// the referent-only mode.
    #[test]
    fn jr20_pollroot_a_header_phi_dead_at_the_poll_is_cleared_but_not_its_edge_value() {
        let g = build(&WALK, WALK_VAL_PC, WALK_NEXT_PC);
        let s = ir_schedule::schedule(&g);
        let plan = plan_slots(&g, &s, None);
        let edges = back_edges(&s);
        assert!(!edges.is_empty(), "the loop survives optimisation");
        let mut header_ref_phis = 0usize;
        let mut reported = 0usize;
        for &(latch, header) in &edges {
            let dead: Vec<usize> = back_edge_dead_ref_homes(&g, &s, &plan, latch, true)
                .into_iter()
                .map(|(id, _)| id)
                .collect();
            for (id, n) in g.nodes.iter().enumerate() {
                if !matches!(n.op, Op::Phi) || n.ty != IrType::Ref {
                    continue;
                }
                if n.inputs.as_slice().first().copied() != Some(s.blocks[header].ctrl) {
                    continue;
                }
                header_ref_phis += 1;
                if dead.contains(&id) {
                    reported += 1;
                    let read_by_a_phi = g.nodes.iter().any(|q| {
                        matches!(q.op, Op::Phi)
                            && q.inputs
                                .as_slice()
                                .iter()
                                .skip(1)
                                .any(|&v| v as usize == id)
                    });
                    assert!(!read_by_a_phi, "header phi n{id} is an edge input of a phi");
                }
                for &v in n.inputs.as_slice().iter().skip(1) {
                    assert!(
                        !dead.contains(&(v as usize)),
                        "n{v} feeds header phi n{id}: live over the poll, never cleared"
                    );
                }
            }
        }
        assert!(header_ref_phis > 0, "the list cursor p is a header phi");
        assert!(reported > 0, "the cursor's header phi is dead at the poll");
        assert!(dead_anywhere(&g, &s, &plan, false).is_empty());
    }

    /// `static int swap(Object x, Object y, int n) { while (n > 0) { Object t =
    /// x; x = y; y = t; n--; } return x == null ? 0 : 1; }`: the header phis
    /// read each other on the back edge (a parallel-copy cycle).
    ///
    /// ```text
    ///  0 iload_2           1 ifle 16
    ///  4 aload_0  5 astore_3  6 aload_1  7 astore_0  8 aload_3  9 astore_1
    /// 10 iinc 2, -1       13 goto 0
    /// 16 aload_0          17 ifnonnull 22     20 iconst_0  21 ireturn
    /// 22 iconst_1         23 ireturn
    /// ```
    const SWAP: [u8; 24] = [
        0x1c, 0x9e, 0x00, 0x0f, 0x2a, 0x4e, 0x2b, 0x4b, 0x2d, 0x4c, 0x84, 0x02, 0xff, 0xa7, 0xff,
        0xf3, 0x2a, 0xc7, 0x00, 0x05, 0x03, 0xac, 0x04, 0xac,
    ];

    /// A header phi another phi reads on the back edge is never cleared: that
    /// copy runs after the poll and reads the phi's home.
    #[test]
    fn jr20_pollroot_header_phis_that_swap_are_not_cleared() {
        let mut b = IrBuilder::new(3, 4);
        b.set_param_types(&[IrType::Ref, IrType::Ref, IrType::Int]);
        let mut g = b.build(&SWAP, SWAP.len()).expect("the swap loop builds");
        crate::ir_optimize::optimize(&mut g);
        let s = ir_schedule::schedule(&g);
        let plan = plan_slots(&g, &s, None);
        let dead = dead_anywhere(&g, &s, &plan, true);
        for &id in &dead {
            let read_by_a_header_phi = back_edges(&s).iter().any(|&(_, header)| {
                g.nodes.iter().any(|q| {
                    matches!(q.op, Op::Phi)
                        && q.inputs.as_slice().first().copied() == Some(s.blocks[header].ctrl)
                        && q.inputs
                            .as_slice()
                            .iter()
                            .skip(1)
                            .any(|&v| v as usize == id)
                })
            });
            assert!(
                !read_by_a_header_phi,
                "n{id} is read by a header phi's edge copy after the poll (dead: {dead:?})"
            );
        }
    }

    /// `static int count(Node head) { int n = 0; Node p = head; Object v; do
    /// { v = p.val; if (v == null) n++; p = p.next; } while (p != null);
    /// return n; }` -- the latch's branch leaves the loop, `v` is not read
    /// after it:
    ///
    /// ```text
    ///  0 iconst_0  1 istore_1  2 aload_0  3 astore_2
    ///  4 aload_2   5 getfield #1 (val)  8 astore_3
    ///  9 aload_3  10 ifnonnull 16       13 iinc 1, 1
    /// 16 aload_2  17 getfield #2 (next) 20 astore_2  21 aload_2  22 ifnonnull 4
    /// 25 iload_1  26 ireturn
    /// ```
    const COUNT: [u8; 27] = [
        0x03, 0x3c, 0x2a, 0x4d, 0x2c, 0xb4, 0x00, 0x01, 0x4e, 0x2d, 0xc7, 0x00, 0x06, 0x84, 0x01,
        0x01, 0x2c, 0xb4, 0x00, 0x02, 0x4d, 0x2c, 0xc7, 0xff, 0xee, 0x1b, 0xac,
    ];
    const COUNT_VAL_PC: usize = 5;
    const COUNT_NEXT_PC: usize = 17;

    /// The exit rule's precise snapshot half (wave 21 follow-up) is asked only
    /// at a latch that can leave the loop. The scheduler gives the do-while's
    /// taken back edge a block of its own (the `If`'s projection), so the
    /// latch's one successor is the header: the exit leaves from the branch
    /// block, before the poll, and the first-arrival rule alone clears `v`
    /// (dead on every path from the poll). The keep union is never consulted
    /// there. (Host w21r, 2026-10-13: the earlier form of this test asserted
    /// an exiting latch and failed on that layout.)
    #[test]
    fn jr20_pollroot_a_do_while_back_edge_latch_clears_without_asking_the_exit_rule() {
        let mut b = IrBuilder::new(1, 4);
        b.set_param_types(&[IrType::Ref]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(COUNT_VAL_PC, (0usize, b'L'));
        fi.insert(COUNT_NEXT_PC, (1usize, b'L'));
        b.set_field_info(fi);
        let mut g = b.build(&COUNT, COUNT.len()).expect("the do-while builds");
        crate::ir_optimize::optimize(&mut g);
        let s = ir_schedule::schedule(&g);
        let plan = plan_slots(&g, &s, None);
        let vals = ref_loads_at(&g, &s, COUNT_VAL_PC);
        assert!(!vals.is_empty(), "the p.val read survives optimisation");
        let edges = back_edges(&s);
        assert!(!edges.is_empty(), "the loop survives optimisation");
        for &(latch, header) in &edges {
            assert_eq!(
                s.blocks[latch].successors,
                vec![header],
                "the do-while's back edge is a block of its own"
            );
        }
        let words = plan.slots.div_ceil(64).max(1);
        let mut asked = 0usize;
        let mut dead = Vec::new();
        for &(latch, _) in &edges {
            let mut reach = |_pc: usize| {
                asked += 1;
                Some(vec![u64::MAX; words])
            };
            dead.extend(
                back_edge_dead_ref_homes_with(&g, &s, &plan, latch, true, Some(&mut reach))
                    .into_iter()
                    .map(|(id, _)| id),
            );
        }
        assert_eq!(
            asked, 0,
            "a latch without an exit never asks the keep union"
        );
        for &v in &vals {
            assert!(
                dead.contains(&v),
                "n{v} (v = p.val) is dead on every path from the poll"
            );
        }
        // Referent-only mode never clears it.
        assert!(dead_anywhere(&g, &s, &plan, false).is_empty());
    }

    /// Control: a dead value whose colour another value live over the poll
    /// also lives in is not cleared -- the word holds the live one. The
    /// sharing is forced on the plan (the colouring itself only shares
    /// non-overlapping ranges, so the live tenant is whichever value's range
    /// covers the poll).
    #[test]
    fn jr20_pollroot_a_colour_shared_with_a_value_live_at_the_poll_is_not_cleared() {
        let g = build(&WALK, WALK_VAL_PC, WALK_NEXT_PC);
        let s = ir_schedule::schedule(&g);
        let mut plan = plan_slots(&g, &s, None);
        let (latch, v) = back_edges(&s)
            .into_iter()
            .find_map(|(latch, _)| {
                back_edge_dead_ref_homes(&g, &s, &plan, latch, true)
                    .first()
                    .map(|&(v, _)| (latch, v))
            })
            .expect("the walk has a dead temporary at some back edge");
        let poll = back_edge_poll_pos(&s, &plan, latch).expect("the poll's position is known");
        let ranges: Vec<Option<LiveRange>> = plan.colouring_ranges().to_vec();
        let live = (0..g.nodes.len())
            .find(|&m| {
                m != v
                    && plan.node_color.get(m).copied().flatten().is_some()
                    && ranges
                        .get(m)
                        .copied()
                        .flatten()
                        .is_some_and(|r| r.lo <= poll && poll <= r.hi)
            })
            .expect("some value is live over the poll");
        plan.node_color[live] = plan.node_color[v];
        let dead = back_edge_dead_ref_homes(&g, &s, &plan, latch, true);
        assert!(
            !dead.iter().any(|&(id, _)| id == v),
            "n{v} shares its word with n{live}, live over the poll: not cleared"
        );
    }

    /// Review fix (unconditional, both modes): `v = p.val` is read after a
    /// do-while. A latch that could leave the loop would take the path out
    /// without re-running the body, so it must keep `v`; a latch whose only
    /// successor is its header re-runs `v` before any read and may clear it.
    /// The scheduler gives the taken back edge its own block (host w21r,
    /// 2026-10-13: `v` IS reported dead there, which the earlier form of this
    /// test, asserting "never cleared", got wrong).
    #[test]
    fn jr20_pollroot_a_value_read_after_the_loop_is_cleared_only_where_the_path_re_enters_the_loop()
    {
        let g = build(&LAST, LAST_VAL_PC, 8);
        let s = ir_schedule::schedule(&g);
        let vals = ref_loads_at(&g, &s, LAST_VAL_PC);
        assert!(!vals.is_empty(), "the p.val read survives optimisation");
        let edges = back_edges(&s);
        assert!(!edges.is_empty(), "the loop survives optimisation");
        let plan = plan_slots(&g, &s, None);
        for &(latch, _) in &edges {
            let exits = s.blocks[latch].successors.iter().any(|&x| x > latch);
            let dead = back_edge_dead_ref_homes(&g, &s, &plan, latch, true);
            for &v in &vals {
                if dead.iter().any(|&(id, _)| id == v) {
                    assert!(
                        !exits,
                        "n{v} (v = p.val) is returned after the loop: cleared at an exiting latch"
                    );
                }
            }
        }
    }

    /// `static int run(Holder h, int m) { int n = 0; while (m > 0) { Object
    /// big = h.node; if (big != null) n++; while (n < m) n++; m--; } return
    /// n; }` -- `big` is dead throughout the inner call-free loop:
    ///
    /// ```text
    ///  0 iconst_0   1 istore_2
    ///  2 iload_1    3 ifle 35
    ///  6 aload_0    7 getfield #1 (node)  10 astore_3
    /// 11 aload_3   12 ifnull 18           15 iinc 2, 1
    /// 18 iload_2   19 iload_1             20 if_icmpge 29   23 iinc 2, 1   26 goto 18
    /// 29 iinc 1, -1                       32 goto 2
    /// 35 iload_2   36 ireturn
    /// ```
    const OUTER_DEAD: [u8; 37] = [
        0x03, 0x3d, 0x1b, 0x9e, 0x00, 0x20, 0x2a, 0xb4, 0x00, 0x01, 0x4e, 0x2d, 0xc6, 0x00, 0x06,
        0x84, 0x02, 0x01, 0x1c, 0x1b, 0xa2, 0x00, 0x09, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xf8, 0x84,
        0x01, 0xff, 0xa7, 0xff, 0xe2, 0x1c, 0xac,
    ];

    /// The same with `big` read AFTER the inner loop (live throughout it):
    ///
    /// ```text
    ///  0 iconst_0   1 istore_2
    ///  2 iload_1    3 ifle 35
    ///  6 aload_0    7 getfield #1 (node)  10 astore_3
    /// 11 iload_2   12 iload_1             13 if_icmpge 22   16 iinc 2, 1   19 goto 11
    /// 22 aload_3   23 ifnull 29           26 iinc 2, 1
    /// 29 iinc 1, -1                       32 goto 2
    /// 35 iload_2   36 ireturn
    /// ```
    const OUTER_LIVE: [u8; 37] = [
        0x03, 0x3d, 0x1b, 0x9e, 0x00, 0x20, 0x2a, 0xb4, 0x00, 0x01, 0x4e, 0x1c, 0x1b, 0xa2, 0x00,
        0x09, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xf8, 0x2d, 0xc6, 0x00, 0x06, 0x84, 0x02, 0x01, 0x84,
        0x01, 0xff, 0xa7, 0xff, 0xe2, 0x1c, 0xac,
    ];
    const OUTER_BIG_PC: usize = 7;

    /// Build, optimise and schedule `code`, plan its slots and its
    /// dead-reference facts (precise keep set); then, at the poll of every
    /// back edge whose loop does NOT contain the `big` read, the poll rule's
    /// verdict on `big`'s colour: `(dead, outer, read by a value phi)`.
    fn outer_verdicts(code: &[u8]) -> Vec<(bool, bool, bool)> {
        let mut b = IrBuilder::new(2, 4);
        b.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(OUTER_BIG_PC, (0usize, b'L'));
        b.set_field_info(fi);
        let mut g = b.build(code, code.len()).expect("the nested loop builds");
        crate::ir_optimize::optimize(&mut g);
        let s = ir_schedule::schedule(&g);
        let plan = plan_slots(&g, &s, None);
        let bigs = ref_loads_at(&g, &s, OUTER_BIG_PC);
        assert!(!bigs.is_empty(), "the big read survives optimisation");
        let mut facts = plan_dead_ref_slot_clear(
            &g,
            &s,
            &plan,
            DeadRefClearBytecode {
                code,
                num_params: 2,
                num_locals: 4,
                handlers: &[],
            },
            &[],
            true,
            None,
        )
        .expect("the dead-reference facts build");
        let mut out = Vec::new();
        for (latch, header) in back_edges(&s) {
            for &big in &bigs {
                let big_block = s.node_to_block[big];
                if s.dom.dominates(header, big_block) {
                    continue; // the outer loop: the dominance rule's case
                }
                let pos = back_edge_poll_pos(&s, &plan, latch).expect("poll position");
                let bci = back_edge_poll_bci(&g, &s, latch).expect("poll bci");
                let colour = plan.node_color[big].expect("big has a home");
                let dead = facts
                    .dead_colours_at_back_edge_poll(pos, bci, s.blocks[latch].ctrl)
                    .contains(&colour);
                let outer = outer_ref_colours(&g, &s, &plan, &[header], &|_| false)
                    .get(colour as usize)
                    .copied()
                    .unwrap_or(false);
                let read_by_phi = g.nodes.iter().any(|q| {
                    matches!(q.op, Op::Phi)
                        && q.inputs
                            .as_slice()
                            .iter()
                            .skip(1)
                            .any(|&v| v as usize == big)
                });
                out.push((dead, outer, read_by_phi));
            }
        }
        out
    }

    /// The defect of `jr20-inner-loop-poll-roots-dead-outer-loop-values-FIXED-20261013.md`:
    /// `big`, defined before the inner loop and read by nothing after it, is
    /// dead at the inner loop's poll, and its colour is an outer one -- so the
    /// poll zeroes it. (A header phi carrying it round the outer loop would be
    /// a reader; then it must be kept.)
    #[test]
    fn jr20_pollroot_an_outer_value_dead_across_an_inner_loop_is_cleared_at_its_poll() {
        let verdicts = outer_verdicts(&OUTER_DEAD);
        assert!(
            !verdicts.is_empty(),
            "an inner loop that does not contain big"
        );
        for (dead, outer, read_by_phi) in verdicts {
            assert!(
                outer,
                "big's colour holds only values defined outside the inner loop"
            );
            if read_by_phi {
                assert!(!dead, "a phi carries big on: kept");
            } else {
                assert!(
                    dead,
                    "big is dead throughout the inner loop: cleared at its poll"
                );
            }
        }
    }

    /// Control: `big` is read after the inner loop, so it is live at the
    /// inner poll and never cleared.
    #[test]
    fn jr20_pollroot_an_outer_value_read_after_the_inner_loop_is_kept() {
        let verdicts = outer_verdicts(&OUTER_LIVE);
        assert!(
            !verdicts.is_empty(),
            "an inner loop that does not contain big"
        );
        for (dead, _, _) in verdicts {
            assert!(!dead, "big is read after the inner loop: live at its poll");
        }
    }
}

/// JIT r21 wave 1 (lane typecheck, `CRATONVM_JIT_IR_AASTORE_DISPLAY_ARM`): the
/// `aastore` store-check arm, EXECUTED as `extern "C" fn(value_id,
/// component_id) -> 1 | DECLINED` over fake displays of the VM's layout
/// (`[len, chain.., n, ifaces.., verdict]`). A subclass of a component class,
/// at any depth, and an implementor of a component interface, direct or
/// inherited, are `1`; a shallower or unrelated class, a non-implementor, a
/// value with no display or past the table, and a component past the table
/// that no interface set lists all decline -- never a `0`, so a refusal stays
/// the helper's.
#[cfg(all(test, target_arch = "x86_64"))]
mod r21_typecheck_aastore_display_tests {
    use super::{aastore_display_arm_bytes, CALL_ARG_REGS};

    const OBJ: u32 = 1;
    const BASE: u32 = 0x1001;
    const SUB: u32 = 0x1002;
    const SUBSUB: u32 = 0x1003;
    const OTHER: u32 = 0x1004;
    const UNPUB: u32 = 0x1005;
    const IF_A: u32 = 0x3001;
    const IF_B: u32 = 0x3002;
    const DECLINED: i64 = -1;

    fn mov(dst: u8, src: u8) -> [u8; 3] {
        [
            0x48 | (u8::from(src >= 8) << 2) | u8::from(dst >= 8),
            0x89,
            0xC0 | ((src & 7) << 3) | (dst & 7),
        ]
    }

    #[allow(clippy::type_complexity)]
    fn fixture() -> (Box<u64>, Vec<Box<[u32]>>, Box<[u64]>) {
        let rows: [(&[u32], &[u32]); 5] = [
            (&[OBJ], &[]),
            (&[OBJ, BASE], &[]),
            (&[OBJ, BASE, SUB], &[IF_A]),
            (&[OBJ, BASE, SUB, SUBSUB], &[IF_A, IF_B]),
            (&[OBJ, OTHER], &[IF_B]),
        ];
        let displays: Vec<Box<[u32]>> = rows
            .iter()
            .map(|(c, i)| {
                let mut d = vec![u32::try_from(c.len()).expect("small")];
                d.extend_from_slice(c);
                d.push(u32::try_from(i.len()).expect("small"));
                d.extend_from_slice(i);
                d.push(1);
                d.into_boxed_slice()
            })
            .collect();
        let cap = 0x5000u64;
        let mut table = vec![0u64; usize::try_from(cap).expect("small") + 1];
        table[0] = cap;
        for ((c, _), d) in rows.iter().zip(&displays) {
            let id = *c.last().expect("non-empty");
            table[1 + usize::try_from(id).expect("small")] = d.as_ptr() as u64; // Cast: address
        }
        let table = table.into_boxed_slice();
        let cell = Box::new(table.as_ptr() as u64); // Cast: address
        (cell, displays, table)
    }

    #[test]
    fn r21_aastore_display_arm_proves_subclasses_and_implementors_only() {
        let (cell, displays, table) = fixture();
        let cell_addr = &*cell as *const u64 as usize; // Cast: the cell's address
        let (bytes, decline, hits) = aastore_display_arm_bytes(cell_addr);
        let mut body: Vec<u8> = Vec::new();
        // RAX = arg0 (value id), RCX = arg1 (component id), RDX = RAX: an
        // order that reads both argument registers before writing them on
        // both ABIs.
        body.extend_from_slice(&mov(0, CALL_ARG_REGS[0]));
        body.extend_from_slice(&mov(1, CALL_ARG_REGS[1]));
        body.extend_from_slice(&mov(2, 0));
        let at = body.len();
        body.extend_from_slice(&bytes);
        let hit_at = body.len();
        body.extend_from_slice(&[0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3]); // MOV EAX, 1 ; RET
        let decline_at = body.len();
        body.extend_from_slice(&[0x48, 0xC7, 0xC0, 0xFF, 0xFF, 0xFF, 0xFF, 0xC3]);
        let mut patch = |field: usize, to: usize| {
            let operand = at + field;
            let rel =
                i32::try_from(to).expect("small") - i32::try_from(operand + 4).expect("small");
            body[operand..operand + 4].copy_from_slice(&rel.to_le_bytes());
        };
        assert!(!decline.is_empty() && hits.len() == 2);
        for d in decline {
            patch(d, decline_at);
        }
        for h in hits {
            patch(h, hit_at);
        }
        let mut buf = crate::ExecutableBuffer::new(1024).expect("executable buffer");
        buf.emit(&body);
        assert!(!buf.overflowed());
        buf.finalize();
        // SAFETY: a complete `extern "C" fn(u64, u64) -> i64` that reads only
        // the fake tables this test keeps alive and writes RAX, RCX, RDX, R10
        // (caller-saved on both ABIs).
        let f = unsafe {
            std::mem::transmute::<*const u8, extern "C" fn(u64, u64) -> i64>(buf.as_ptr())
        };
        let ask = |value: u32, component: u32| f(u64::from(value), u64::from(component));
        for (v, c) in [
            (BASE, BASE),
            (SUB, BASE),
            (SUBSUB, BASE),
            (SUBSUB, SUB),
            (SUB, OBJ),
            (OTHER, OBJ),
            (SUB, IF_A),
            (SUBSUB, IF_A),
            (SUBSUB, IF_B),
            (OTHER, IF_B),
        ] {
            assert_eq!(ask(v, c), 1, "{v:#x} stores into {c:#x}[]");
        }
        for (v, c) in [
            (BASE, SUB),
            (SUB, SUBSUB),
            (OTHER, BASE),
            (BASE, OTHER),
            (SUB, IF_B),
            (BASE, IF_A),
            (OTHER, IF_A),
            (UNPUB, BASE),
            (UNPUB, IF_A),
            (SUB, UNPUB),
            (SUB, 0x4FFF_0000),
            (0x8000_0001, BASE),
            (u32::MAX, IF_A),
        ] {
            assert_eq!(ask(v, c), DECLINED, "{v:#x} into {c:#x}[] declines");
        }
        drop((cell, displays, table));
    }

    /// The switch is opt-in: unset means the arm is never emitted.
    #[test]
    fn r21_aastore_display_arm_is_opt_in() {
        if cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_AASTORE_DISPLAY_ARM").is_ok() {
            return; // an explicit setting is the caller's business
        }
        assert!(!super::ir_aastore_display_arm_enabled());
    }
}

/// JIT r21 wave 1 (lane typecheck): the final-miss verdict screen
/// (`CRATONVM_JIT_INSTANCEOF_FINAL_MISS_VERDICT`) and the array-target arm
/// (TYPECHECK21-3, `CRATONVM_JIT_TYPECHECK_ARRAY_TARGETS`), EXECUTED over fake
/// displays of the VM's layout and fake object headers.
#[cfg(all(test, target_arch = "x86_64"))]
mod r21_typecheck_verdict_and_array_tests {
    use super::{
        typecheck_array_hit_bytes, typecheck_receiver_verdict_bytes, TypecheckArrayPlan,
        VhSubtypeDisplay, CALL_ARG_REGS,
    };

    const OBJ: u32 = 1;
    const BASE: u32 = 0x1001;
    const SUB: u32 = 0x1002;
    const OTHER: u32 = 0x1004;
    const UNPUB: u32 = 0x1005;
    const STAMP: u32 = 0x1006;
    const ARRCLS: u32 = 0x1010;
    const IF_A: u32 = 0x3001;
    const DECLINED: i64 = -1;

    fn mov(dst: u8, src: u8) -> [u8; 3] {
        [
            0x48 | (u8::from(src >= 8) << 2) | u8::from(dst >= 8),
            0x89,
            0xC0 | ((src & 7) << 3) | (dst & 7),
        ]
    }

    #[allow(clippy::type_complexity)]
    fn fixture() -> (Box<u64>, Vec<Box<[u32]>>, Box<[u64]>) {
        // (chain, interfaces, verdict)
        let rows: [(&[u32], &[u32], u32); 5] = [
            (&[OBJ], &[], 1),
            (&[OBJ, BASE], &[], 1),
            (&[OBJ, BASE, SUB], &[IF_A], 1),
            (&[OBJ, OTHER], &[], 1),
            (&[OBJ, STAMP], &[IF_A], 0),
        ];
        let displays: Vec<Box<[u32]>> = rows
            .iter()
            .map(|(c, i, v)| {
                let mut d = vec![u32::try_from(c.len()).expect("small")];
                d.extend_from_slice(c);
                d.push(u32::try_from(i.len()).expect("small"));
                d.extend_from_slice(i);
                d.push(*v);
                d.into_boxed_slice()
            })
            .collect();
        let cap = 0x5000u64;
        let mut table = vec![0u64; usize::try_from(cap).expect("small") + 1];
        table[0] = cap;
        for ((c, _, _), d) in rows.iter().zip(&displays) {
            let id = *c.last().expect("non-empty");
            table[1 + usize::try_from(id).expect("small")] = d.as_ptr() as u64; // Cast: address
        }
        let table = table.into_boxed_slice();
        let cell = Box::new(table.as_ptr() as u64); // Cast: address
        (cell, displays, table)
    }

    /// `extern "C" fn(u64) -> 1 | DECLINED`: `prologue`, the arm's bytes
    /// (falling through, or jumping through `hits`, to the `1`), then the
    /// decline target.
    fn build(prologue: &[u8], bytes: &[u8], decline: &[usize], hits: &[usize]) -> crate::ExecutableBuffer {
        let mut body: Vec<u8> = prologue.to_vec();
        let at = body.len();
        body.extend_from_slice(bytes);
        let hit_at = body.len();
        body.extend_from_slice(&[0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3]); // MOV EAX, 1 ; RET
        let decline_at = body.len();
        body.extend_from_slice(&[0x48, 0xC7, 0xC0, 0xFF, 0xFF, 0xFF, 0xFF, 0xC3]);
        let mut patch = |field: usize, to: usize| {
            let operand = at + field;
            let rel =
                i32::try_from(to).expect("small") - i32::try_from(operand + 4).expect("small");
            body[operand..operand + 4].copy_from_slice(&rel.to_le_bytes());
        };
        for &d in decline {
            patch(d, decline_at);
        }
        for &h in hits {
            patch(h, hit_at);
        }
        let mut buf = crate::ExecutableBuffer::new(1024).expect("executable buffer");
        buf.emit(&body);
        assert!(!buf.overflowed());
        buf.finalize();
        buf
    }

    fn call(buf: &crate::ExecutableBuffer, arg: u64) -> i64 {
        // SAFETY: a complete `extern "C" fn(u64) -> i64` reading only the
        // fixtures the caller keeps alive and writing RAX, RCX, R11.
        let f =
            unsafe { std::mem::transmute::<*const u8, extern "C" fn(u64) -> i64>(buf.as_ptr()) };
        f(arg)
    }

    #[test]
    fn r21_final_miss_verdict_admits_only_hierarchy_only_receivers() {
        let (cell, displays, table) = fixture();
        let cell_addr = &*cell as *const u64 as usize; // Cast: the cell's address
        let (bytes, decline) = typecheck_receiver_verdict_bytes(cell_addr);
        let mut prologue = mov(1, CALL_ARG_REGS[0]).to_vec(); // RCX = arg0
        prologue.extend_from_slice(&[0x89, 0xC9]); // MOV ECX, ECX
        let buf = build(&prologue, &bytes, &decline, &[]);
        for id in [OBJ, BASE, SUB, OTHER] {
            assert_eq!(call(&buf, u64::from(id)), 1, "{id:#x} is hierarchy-only");
        }
        for id in [STAMP, UNPUB, 0x4FFF, 0x8000_0001, u32::MAX] {
            assert_eq!(call(&buf, u64::from(id)), DECLINED, "{id:#x} asks the helper");
        }
        drop((cell, displays, table));
    }

    #[test]
    fn r21_final_miss_verdict_is_default_on() {
        if cratonvm_types::flags::runtime_var("CRATONVM_JIT_INSTANCEOF_FINAL_MISS_VERDICT").is_ok() {
            return;
        }
        assert!(super::instanceof_final_miss_verdict_enabled());
    }

    /// A fake header: class id at offset 0, the kind byte at its offset.
    fn header(class_id: u32, kind_tags: u8) -> Box<[u64; 4]> {
        let mut h = Box::new([0u64; 4]);
        let p = h.as_mut_ptr() as *mut u8;
        // SAFETY: both writes land inside the 32-byte box.
        unsafe {
            std::ptr::copy_nonoverlapping(class_id.to_le_bytes().as_ptr(), p, 4);
            *p.add(cratonvm_types::KIND_TAGS_BYTE_OFFSET) = kind_tags;
        }
        h
    }

    #[test]
    fn r21_array_target_arm_proves_covariant_component_arrays_only() {
        let (cell, displays, table) = fixture();
        let cell_addr = &*cell as *const u64 as usize; // Cast: the cell's address
        let ref_array = cratonvm_types::ObjectKind::Array as u8;
        let int_array = cratonvm_types::primitive_array_kind_tags_byte("[I").expect("[I");
        let prologue = mov(0, CALL_ARG_REGS[0]); // RAX = arg0
        let arm = |plan: TypecheckArrayPlan| {
            let (bytes, decline, hits) = typecheck_array_hit_bytes(plan);
            build(&prologue, &bytes, &decline, &hits)
        };
        let ask = |buf: &crate::ExecutableBuffer, h: &[u64; 4]| call(buf, h.as_ptr() as u64);
        let sub_arr = header(SUB, ref_array);
        let base_arr = header(BASE, ref_array);
        let other_arr = header(OTHER, ref_array);
        let nested = header(ARRCLS, ref_array);
        let object_arr = header(0, ref_array);
        let ints = header(0, int_array);
        let plain_sub = header(SUB, 0);

        let class_t = arm(TypecheckArrayPlan {
            component: BASE,
            object_component: false,
            display: Some(VhSubtypeDisplay {
                cell: cell_addr,
                depth: 1,
                interface: false,
            }),
        });
        assert_eq!(ask(&class_t, &sub_arr), 1, "Sub[] is a Base[]");
        assert_eq!(ask(&class_t, &base_arr), 1, "Base[] is a Base[]");
        for (h, what) in [
            (&other_arr, "Other[]"),
            (&nested, "an array of arrays"),
            (&object_arr, "Object[]"),
            (&ints, "int[]"),
            (&plain_sub, "a plain Sub"),
        ] {
            assert_eq!(ask(&class_t, h), DECLINED, "{what} is not proven a Base[]");
        }

        let iface_t = arm(TypecheckArrayPlan {
            component: IF_A,
            object_component: false,
            display: Some(VhSubtypeDisplay {
                cell: cell_addr,
                depth: 0,
                interface: true,
            }),
        });
        assert_eq!(ask(&iface_t, &sub_arr), 1, "Sub[] is an IF_A[]");
        assert_eq!(ask(&iface_t, &base_arr), DECLINED);

        let object_t = arm(TypecheckArrayPlan {
            component: 0,
            object_component: true,
            display: None,
        });
        for h in [&sub_arr, &nested, &object_arr] {
            assert_eq!(ask(&object_t, h), 1, "every reference array is an Object[]");
        }
        assert_eq!(ask(&object_t, &ints), DECLINED, "int[] is not an Object[]");
        assert_eq!(ask(&object_t, &plain_sub), DECLINED);

        let exact_only = arm(TypecheckArrayPlan {
            component: BASE,
            object_component: false,
            display: None,
        });
        assert_eq!(ask(&exact_only, &base_arr), 1);
        assert_eq!(ask(&exact_only, &sub_arr), DECLINED);
        drop((cell, displays, table));
    }

    #[test]
    fn r21_array_targets_are_opt_in() {
        if cratonvm_types::flags::runtime_var("CRATONVM_JIT_TYPECHECK_ARRAY_TARGETS").is_ok() {
            return;
        }
        assert!(!crate::typecheck_array_targets_enabled());
    }
}

/// r21 barriers (BARRIERS21-2, `CRATONVM_JIT_IR_G1_GATED_AASTORE`): the G1
/// `aastore` screen (`g1_aastore_screen_bytes`), EXECUTED as `extern "C"
/// fn(array, value) -> 0 | 1 | -1`.
///
/// * 0: the fall-through, a store with no barrier.
/// * 1: the cross-region edge, the store and then the lean G1 barrier.
/// * -1: the decline edge, the whole `jit_aastore`.
///
/// The fixture is a fake SATB gate byte and a fake `JIT_G1_BARRIER` table
/// whose arena base is NOT region-aligned. The pairs on both sides of an
/// aligned 1 MiB boundary are the ones a base-free test would misjudge.
#[cfg(all(test, target_arch = "x86_64"))]
mod r21_barriers_g1_aastore_tests {
    use super::{g1_aastore_screen_bytes, ir_g1_gated_aastore_enabled, CALL_ARG_REGS};
    use std::sync::atomic::{AtomicU8, AtomicUsize, Ordering};

    const REGION_SIZE: usize = 0x10_0000;
    const ARENA_BASE: usize = 0x4000_0000 + 0x30;
    const DECLINED: i64 = -1;

    fn mov(dst: u8, src: u8) -> [u8; 3] {
        [
            0x48 | (u8::from(src >= 8) << 2) | u8::from(dst >= 8),
            0x89,
            0xC0 | ((src & 7) << 3) | (dst & 7),
        ]
    }

    #[test]
    fn r21_g1_aastore_screen_separates_plain_cross_and_armed() {
        static TABLE: [AtomicUsize; 5] = [
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
        ];
        static GATE: AtomicU8 = AtomicU8::new(0);
        TABLE[0].store(ARENA_BASE, Ordering::Release);
        TABLE[2].store(!(REGION_SIZE - 1), Ordering::Release);
        TABLE[1].store(8 * REGION_SIZE, Ordering::Release);
        GATE.store(0, Ordering::Release);
        let plan = crate::x64::G1AastorePlan {
            pre: &GATE as *const AtomicU8 as usize, // Cast: the gate's address
            table: TABLE.as_ptr() as usize,         // Cast: the table's address
            post: 1,
        };
        let (bytes, decline, cross) = g1_aastore_screen_bytes(plan);
        assert_eq!(decline.len(), 1, "one decline edge: the armed gate");
        assert_eq!(cross.len(), 1, "one cross-region edge");
        let mut body: Vec<u8> = Vec::new();
        // RAX = arg0 (array) first, then RDX = arg1 (value): on Win64 arg1 IS
        // RDX, and arg0 (RCX) is read before anything writes it.
        body.extend_from_slice(&mov(0, CALL_ARG_REGS[0]));
        body.extend_from_slice(&mov(2, CALL_ARG_REGS[1]));
        let at = body.len();
        body.extend_from_slice(&bytes);
        body.extend_from_slice(&[0x31, 0xC0, 0xC3]); // XOR EAX, EAX ; RET (plain)
        let cross_at = body.len();
        body.extend_from_slice(&[0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3]); // MOV EAX, 1 ; RET
        let decline_at = body.len();
        body.extend_from_slice(&[0x48, 0xC7, 0xC0, 0xFF, 0xFF, 0xFF, 0xFF, 0xC3]); // MOV RAX, -1 ; RET
        let mut patch = |field: usize, to: usize| {
            let operand = at + field;
            let rel =
                i32::try_from(to).expect("small") - i32::try_from(operand + 4).expect("small");
            body[operand..operand + 4].copy_from_slice(&rel.to_le_bytes());
        };
        for d in decline {
            patch(d, decline_at);
        }
        for c in cross {
            patch(c, cross_at);
        }
        let mut buf = crate::ExecutableBuffer::new(1024).expect("executable buffer");
        buf.emit(&body);
        assert!(!buf.overflowed());
        buf.finalize();
        // SAFETY: a complete `extern "C" fn(u64, u64) -> i64` that reads only
        // GATE and TABLE (statics) and writes RAX, RCX, RDX, R10, R11
        // (caller-saved on both ABIs).
        let f = unsafe {
            std::mem::transmute::<*const u8, extern "C" fn(u64, u64) -> i64>(buf.as_ptr())
        };
        let ask = |a: usize, v: usize| f(a as u64, v as u64); // Cast: test addresses

        let r0 = ARENA_BASE + 8;
        let r1 = ARENA_BASE + REGION_SIZE + 8;
        let same_lo = ARENA_BASE + REGION_SIZE - 0x38;
        let same_hi = same_lo + 0x10;
        let last_of_r0 = ARENA_BASE + REGION_SIZE - 8;
        let first_of_r1 = ARENA_BASE + REGION_SIZE + 8;
        assert_ne!(same_lo >> 20, same_hi >> 20, "setup: two aligned blocks");
        assert_eq!(last_of_r0 >> 20, first_of_r1 >> 20, "setup: one aligned block");
        let cases: [(usize, usize, i64, &str); 6] = [
            (r0, 0, 0, "a null value records no edge"),
            (r0, r0 + 64, 0, "a same-region value records no edge"),
            (r0, r1, 1, "a cross-region value takes the lean barrier"),
            (r1, r0, 1, "cross-region the other way"),
            (same_lo, same_hi, 0, "one region across an aligned block boundary"),
            (last_of_r0, first_of_r1, 1, "two regions inside one aligned block"),
        ];
        for (a, v, want, why) in cases {
            assert_eq!(ask(a, v), want, "gate clear: {why}");
        }
        GATE.store(1, Ordering::Release);
        for (a, v, _, why) in cases {
            assert_eq!(ask(a, v), DECLINED, "gate armed: jit_aastore logs the old element ({why})");
        }
        GATE.store(0, Ordering::Release);
        for w in TABLE.iter() {
            w.store(0, Ordering::Release);
        }
    }

    #[test]
    fn r21_g1_gated_aastore_is_opt_in() {
        if cratonvm_types::flags::runtime_var("CRATONVM_JIT_IR_G1_GATED_AASTORE").is_ok() {
            return;
        }
        assert!(!ir_g1_gated_aastore_enabled());
    }
}
